{
  "name": "ASA ESTATES LTD 1.1",
  "site": {
    "installCommand": "npm install",
    "buildCommand": "npm run build",
    "serveCommand": "npm run dev",
    "outputDirectory": "./dist"
  }
}

{
  "type": "googledrive",
  "scopes": [
    "https://www.googleapis.com/auth/drive.file",
    "email"
  ]
}

{
  "type": "googlesheets",
  "scopes": [
    "https://www.googleapis.com/auth/spreadsheets",
    "email"
  ]
}

{
  "name": "AuditEvent",
  "type": "object",
  "properties": {
    "document_id": {
      "type": "string"
    },
    "signer_id": {
      "type": "string"
    },
    "event_type": {
      "type": "string",
      "enum": [
        "created",
        "sent",
        "opened",
        "viewed",
        "field_completed",
        "signed",
        "declined",
        "completed",
        "voided",
        "consent_given"
      ]
    },
    "ip_address": {
      "type": "string"
    },
    "user_agent": {
      "type": "string"
    },
    "metadata": {
      "type": "string"
    }
  },
  "required": [
    "document_id",
    "event_type"
  ],
  "rls": {
    "create": {
      "$or": [
        {
          "user_condition": {
            "role": "admin"
          }
        },
        {
          "user_condition": {
            "role": "user"
          }
        }
      ]
    },
    "read": {
      "$or": [
        {
          "user_condition": {
            "role": "admin"
          }
        },
        {
          "user_condition": {
            "role": "user"
          }
        }
      ]
    },
    "update": {
      "user_condition": {
        "role": "admin"
      }
    },
    "delete": {
      "user_condition": {
        "role": "admin"
      }
    }
  }
}

{
  "name": "AuditLog",
  "type": "object",
  "properties": {
    "user_email": {
      "type": "string",
      "description": "Who performed the action"
    },
    "user_role": {
      "type": "string",
      "description": "Role at time of action"
    },
    "action": {
      "type": "string",
      "enum": [
        "create",
        "update",
        "delete"
      ],
      "description": "Type of action"
    },
    "entity_type": {
      "type": "string",
      "description": "Which entity was affected"
    },
    "entity_id": {
      "type": "string",
      "description": "ID of the affected record"
    },
    "summary": {
      "type": "string",
      "description": "Human-readable description of what changed"
    },
    "old_value": {
      "type": "string",
      "description": "JSON of old value (stringified)"
    },
    "new_value": {
      "type": "string",
      "description": "JSON of new value (stringified)"
    }
  },
  "required": [
    "action",
    "entity_type",
    "summary"
  ],
  "rls": {
    "create": {
      "$or": [
        {
          "user_condition": {
            "role": "admin"
          }
        },
        {
          "user_condition": {
            "role": "user"
          }
        }
      ]
    },
    "read": {
      "$or": [
        {
          "created_by_id": "{{user.id}}"
        },
        {
          "user_condition": {
            "role": "admin"
          }
        },
        {
          "user_condition": {
            "role": "user"
          }
        }
      ]
    },
    "update": {
      "user_condition": {
        "role": "admin"
      }
    },
    "delete": {
      "user_condition": {
        "role": "admin"
      }
    }
  }
}

{
  "name": "Bank",
  "type": "object",
  "properties": {
    "name": {
      "type": "string",
      "description": "Bank or account name (e.g. Barclays, HSBC, Cash Account)"
    },
    "type": {
      "type": "string",
      "enum": [
        "bank",
        "cash"
      ],
      "default": "bank",
      "description": "Whether this is a bank account or cash account"
    },
    "account_number": {
      "type": "string",
      "description": "Last 4 digits or reference"
    },
    "notes": {
      "type": "string"
    },
    "is_active": {
      "type": "boolean",
      "default": true
    }
  },
  "required": [
    "name",
    "type"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "admin"
      }
    },
    "read": {
      "user_condition": {
        "role": "admin"
      }
    },
    "update": {
      "user_condition": {
        "role": "admin"
      }
    },
    "delete": {
      "user_condition": {
        "role": "admin"
      }
    }
  }
}

{
  "name": "CRMEntry",
  "type": "object",
  "properties": {
    "landlord_id": {
      "type": "string",
      "description": "FK to Landlord"
    },
    "property_id": {
      "type": "string",
      "description": "FK to Property (optional, for property-scoped notes)"
    },
    "type": {
      "type": "string",
      "enum": [
        "note",
        "call",
        "email",
        "message",
        "meeting",
        "task"
      ],
      "default": "note"
    },
    "subject": {
      "type": "string"
    },
    "content": {
      "type": "string"
    },
    "due_date": {
      "type": "string",
      "format": "date",
      "description": "For tasks/reminders"
    },
    "completed": {
      "type": "boolean",
      "default": false
    },
    "file_url": {
      "type": "string",
      "description": "Attached document URL"
    }
  },
  "required": [
    "landlord_id",
    "type",
    "subject"
  ],
  "rls": {
    "create": {
      "$or": [
        {
          "user_condition": {
            "role": "admin"
          }
        },
        {
          "user_condition": {
            "role": "user"
          }
        }
      ]
    },
    "read": {
      "$or": [
        {
          "created_by_id": "{{user.id}}"
        },
        {
          "user_condition": {
            "role": "admin"
          }
        },
        {
          "user_condition": {
            "role": "user"
          }
        }
      ]
    },
    "update": {
      "$or": [
        {
          "created_by_id": "{{user.id}}"
        },
        {
          "user_condition": {
            "role": "admin"
          }
        },
        {
          "user_condition": {
            "role": "user"
          }
        }
      ]
    },
    "delete": {
      "user_condition": {
        "role": "admin"
      }
    }
  }
}

{
  "name": "CashEntry",
  "type": "object",
  "properties": {
    "date": {
      "type": "string",
      "format": "date"
    },
    "description": {
      "type": "string"
    },
    "amount": {
      "type": "number"
    },
    "type": {
      "type": "string",
      "enum": [
        "Income",
        "Expense"
      ],
      "default": "Income"
    },
    "category": {
      "type": "string",
      "default": "Cash"
    },
    "notes": {
      "type": "string"
    },
    "added_by": {
      "type": "string"
    },
    "property_id": {
      "type": "string",
      "description": "FK to Property (optional)"
    },
    "landlord_id": {
      "type": "string",
      "description": "FK to Landlord (optional)"
    }
  },
  "required": [
    "date",
    "description",
    "amount",
    "type"
  ],
  "rls": {
    "create": {
      "$or": [
        {
          "user_condition": {
            "role": "admin"
          }
        },
        {
          "user_condition": {
            "role": "user"
          }
        }
      ]
    },
    "read": {
      "$or": [
        {
          "data.added_by": "{{user.email}}"
        },
        {
          "user_condition": {
            "role": "admin"
          }
        }
      ]
    },
    "update": {
      "$or": [
        {
          "data.added_by": "{{user.email}}"
        },
        {
          "user_condition": {
            "role": "admin"
          }
        }
      ]
    },
    "delete": {
      "user_condition": {
        "role": "admin"
      }
    }
  }
}

{
  "name": "CommissionAgreement",
  "type": "object",
  "properties": {
    "landlord_id": {
      "type": "string",
      "description": "FK to Landlord"
    },
    "property_id": {
      "type": "string",
      "description": "Optional: override per property. Null = landlord-level default"
    },
    "type": {
      "type": "string",
      "enum": [
        "percentage",
        "fixed_monthly",
        "one_time"
      ],
      "default": "percentage"
    },
    "value": {
      "type": "number",
      "description": "Percentage (e.g. 10) or fixed amount (e.g. 100)"
    },
    "min_commission": {
      "type": "number",
      "description": "Floor: minimum commission amount (\u00a3) \u2014 only applies to percentage type"
    },
    "max_commission": {
      "type": "number",
      "description": "Ceiling: maximum commission amount (\u00a3) \u2014 only applies to percentage type"
    },
    "one_time_applied": {
      "type": "boolean",
      "default": false,
      "description": "Whether one-time fee has been applied"
    },
    "effective_from": {
      "type": "string",
      "description": "Period (YYYY-MM) from which this agreement applies"
    },
    "effective_to": {
      "type": "string",
      "description": "Period (YYYY-MM) this agreement ends (inclusive). Leave blank = still active"
    },
    "notes": {
      "type": "string"
    }
  },
  "required": [
    "landlord_id",
    "type",
    "value"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "admin"
      }
    },
    "read": {
      "user_condition": {
        "role": "admin"
      }
    },
    "update": {
      "user_condition": {
        "role": "admin"
      }
    },
    "delete": {
      "user_condition": {
        "role": "admin"
      }
    }
  }
}

{
  "name": "CommissionHistory",
  "type": "object",
  "properties": {
    "landlord_id": {
      "type": "string",
      "description": "FK to Landlord"
    },
    "property_id": {
      "type": "string",
      "description": "FK to Property (null = applies to all landlord properties)"
    },
    "commission_type": {
      "type": "string",
      "enum": [
        "percentage",
        "fixed_monthly"
      ],
      "default": "percentage",
      "description": "Type of commission"
    },
    "commission_value": {
      "type": "number",
      "description": "Percentage or fixed amount"
    },
    "start_date": {
      "type": "string",
      "format": "date",
      "description": "Date this commission rate becomes effective"
    },
    "end_date": {
      "type": "string",
      "format": "date",
      "description": "Date this rate ended (null = currently active)"
    },
    "notes": {
      "type": "string",
      "description": "Optional notes about this commission change"
    }
  },
  "required": [
    "landlord_id",
    "commission_type",
    "commission_value",
    "start_date"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "admin"
      }
    },
    "read": {
      "user_condition": {
        "role": "admin"
      }
    },
    "update": {
      "user_condition": {
        "role": "admin"
      }
    },
    "delete": {
      "user_condition": {
        "role": "admin"
      }
    }
  }
}

{
  "name": "CommissionLedger",
  "type": "object",
  "properties": {
    "rent_payment_id": {
      "type": "string",
      "description": "FK to the first/trigger RentPayment that caused this commission entry"
    },
    "landlord_id": {
      "type": "string",
      "description": "FK to Landlord"
    },
    "property_id": {
      "type": "string",
      "description": "FK to Property"
    },
    "period_month": {
      "type": "string",
      "description": "Rent period this commission covers (YYYY-MM) \u2014 ONE entry per property per period"
    },
    "rent_amount": {
      "type": "number",
      "description": "Full agreed monthly rent (not per-payment amount)"
    },
    "commission_amount": {
      "type": "number"
    },
    "landlord_share": {
      "type": "number"
    },
    "commission_type": {
      "type": "string",
      "enum": [
        "percentage",
        "fixed_monthly",
        "one_time"
      ]
    },
    "commission_rate": {
      "type": "number",
      "description": "The rate/value used for calculation"
    },
    "date": {
      "type": "string",
      "format": "date"
    }
  },
  "required": [
    "rent_payment_id",
    "landlord_id",
    "property_id",
    "rent_amount",
    "commission_amount",
    "landlord_share"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "admin"
      }
    },
    "read": {
      "user_condition": {
        "role": "admin"
      }
    },
    "update": {
      "user_condition": {
        "role": "admin"
      }
    },
    "delete": {
      "user_condition": {
        "role": "admin"
      }
    }
  }
}

{
  "name": "DepositPayment",
  "type": "object",
  "properties": {
    "tenant_id": {
      "type": "string",
      "description": "FK to Tenant"
    },
    "property_id": {
      "type": "string",
      "description": "FK to Property"
    },
    "amount": {
      "type": "number",
      "description": "Amount paid in this instalment"
    },
    "payment_date": {
      "type": "string",
      "format": "date"
    },
    "method": {
      "type": "string",
      "enum": [
        "bank_transfer",
        "cash",
        "card",
        "standing_order",
        "other"
      ],
      "default": "bank_transfer"
    },
    "notes": {
      "type": "string"
    }
  },
  "required": [
    "tenant_id",
    "property_id",
    "amount",
    "payment_date"
  ],
  "rls": {
    "create": {
      "$or": [
        {
          "user_condition": {
            "role": "admin"
          }
        },
        {
          "user_condition": {
            "role": "user"
          }
        }
      ]
    },
    "read": {
      "$or": [
        {
          "created_by_id": "{{user.id}}"
        },
        {
          "user_condition": {
            "role": "admin"
          }
        },
        {
          "user_condition": {
            "role": "user"
          }
        }
      ]
    },
    "update": {
      "$or": [
        {
          "created_by_id": "{{user.id}}"
        },
        {
          "user_condition": {
            "role": "admin"
          }
        },
        {
          "user_condition": {
            "role": "user"
          }
        }
      ]
    },
    "delete": {
      "user_condition": {
        "role": "admin"
      }
    }
  }
}

{
  "name": "Document",
  "type": "object",
  "properties": {
    "title": {
      "type": "string"
    },
    "status": {
      "type": "string",
      "enum": [
        "draft",
        "sent",
        "viewed",
        "partially_signed",
        "completed",
        "voided",
        "declined"
      ],
      "default": "draft"
    },
    "original_file_url": {
      "type": "string",
      "format": "uri"
    },
    "signed_file_url": {
      "type": "string",
      "format": "uri"
    },
    "final_file_url": {
      "type": "string",
      "format": "uri"
    },
    "message": {
      "type": "string"
    },
    "sent_at": {
      "type": "string",
      "format": "date-time"
    },
    "completed_at": {
      "type": "string",
      "format": "date-time"
    },
    "page_count": {
      "type": "number"
    }
  },
  "required": [
    "title"
  ],
  "rls": {
    "create": {
      "$or": [
        {
          "user_condition": {
            "role": "admin"
          }
        },
        {
          "user_condition": {
            "role": "user"
          }
        }
      ]
    },
    "read": {
      "$or": [
        {
          "user_condition": {
            "role": "admin"
          }
        },
        {
          "user_condition": {
            "role": "user"
          }
        }
      ]
    },
    "update": {
      "$or": [
        {
          "user_condition": {
            "role": "admin"
          }
        },
        {
          "user_condition": {
            "role": "user"
          }
        }
      ]
    },
    "delete": {
      "user_condition": {
        "role": "admin"
      }
    }
  }
}

{
  "name": "EmailLog",
  "type": "object",
  "properties": {
    "recipient_email": {
      "type": "string"
    },
    "recipient_name": {
      "type": "string"
    },
    "subject": {
      "type": "string"
    },
    "body_preview": {
      "type": "string",
      "description": "First 300 chars of body"
    },
    "type": {
      "type": "string",
      "enum": [
        "tenant_invoice",
        "landlord_statement",
        "rent_reminder",
        "other"
      ],
      "default": "other"
    },
    "reference_id": {
      "type": "string",
      "description": "Invoice or statement key"
    },
    "status": {
      "type": "string",
      "enum": [
        "opened",
        "failed"
      ],
      "default": "opened"
    },
    "sent_by": {
      "type": "string",
      "description": "User email who triggered it"
    },
    "notes": {
      "type": "string"
    }
  },
  "required": [
    "recipient_email",
    "subject",
    "type"
  ],
  "rls": {
    "create": {
      "$or": [
        {
          "user_condition": {
            "role": "admin"
          }
        },
        {
          "user_condition": {
            "role": "user"
          }
        }
      ]
    },
    "read": {
      "$or": [
        {
          "data.sent_by": "{{user.email}}"
        },
        {
          "user_condition": {
            "role": "admin"
          }
        }
      ]
    },
    "update": {
      "$or": [
        {
          "data.sent_by": "{{user.email}}"
        },
        {
          "user_condition": {
            "role": "admin"
          }
        }
      ]
    },
    "delete": {
      "user_condition": {
        "role": "admin"
      }
    }
  }
}

{
  "name": "Expense",
  "type": "object",
  "properties": {
    "property_id": {
      "type": "string",
      "description": "FK to Property"
    },
    "landlord_id": {
      "type": "string",
      "description": "FK to Landlord (auto-linked via property)"
    },
    "tenant_id": {
      "type": "string",
      "description": "FK to Tenant (optional)"
    },
    "date": {
      "type": "string",
      "format": "date"
    },
    "category": {
      "type": "string",
      "enum": [
        "maintenance",
        "repairs",
        "insurance",
        "utilities",
        "management_fee",
        "legal",
        "cleaning",
        "other"
      ],
      "default": "maintenance"
    },
    "description": {
      "type": "string"
    },
    "amount": {
      "type": "number"
    },
    "paid_by": {
      "type": "string",
      "enum": [
        "agency",
        "landlord"
      ],
      "default": "agency",
      "description": "Who bears this expense"
    },
    "reference": {
      "type": "string"
    },
    "notes": {
      "type": "string"
    },
    "approved": {
      "type": "boolean",
      "default": false,
      "description": "Whether this landlord expense has been approved to affect the ledger"
    }
  },
  "required": [
    "property_id",
    "date",
    "amount",
    "description"
  ],
  "rls": {
    "create": {
      "$or": [
        {
          "user_condition": {
            "role": "admin"
          }
        },
        {
          "user_condition": {
            "role": "user"
          }
        }
      ]
    },
    "read": {
      "$or": [
        {
          "created_by_id": "{{user.id}}"
        },
        {
          "user_condition": {
            "role": "admin"
          }
        },
        {
          "user_condition": {
            "role": "user"
          }
        }
      ]
    },
    "update": {
      "$or": [
        {
          "created_by_id": "{{user.id}}"
        },
        {
          "user_condition": {
            "role": "admin"
          }
        },
        {
          "user_condition": {
            "role": "user"
          }
        }
      ]
    },
    "delete": {
      "user_condition": {
        "role": "admin"
      }
    }
  }
}

{
  "name": "HouseKey",
  "type": "object",
  "properties": {
    "key_number": {
      "type": "number",
      "description": "Reference number"
    },
    "address": {
      "type": "string",
      "description": "Property address"
    },
    "notes": {
      "type": "string",
      "description": "Any notes (e.g. keys with tenant, back door key)"
    },
    "status": {
      "type": "string",
      "enum": [
        "in_office",
        "with_tenant",
        "with_landlord",
        "missing"
      ],
      "default": "in_office",
      "description": "Current key status"
    }
  },
  "required": [
    "address"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "admin"
      }
    },
    "read": {
      "user_condition": {
        "role": "admin"
      }
    },
    "update": {
      "user_condition": {
        "role": "admin"
      }
    },
    "delete": {
      "user_condition": {
        "role": "admin"
      }
    }
  }
}

{
  "name": "Inquiry",
  "type": "object",
  "rls": {
    "create": true,
    "read": {
