// ─────────────────────────────────────────────────────────────────────
// DAILY CERTIFICATE / DOCUMENT EXPIRY DIGEST
//
// Runs on a schedule (see setup below) and emails ONE summary to the admin
// listing every document that is expired or expiring soon, grouped and sorted
// by urgency, with the property it belongs to.
//
// SETUP:
//   1. Secrets (Settings → Environment Variables):
//        RESEND_API_KEY        – already set (used by sendEmail)
//        RESEND_FROM_EMAIL     – already set
//        EXPIRY_DIGEST_TO      – your email address (where the digest is sent)
//        BASE44_APP_ID         – this app's id (for building deep links; optional)
//        EXPIRY_SOON_DAYS      – optional, days ahead to warn (default 30)
//   2. Schedule it: Base44 → this function → add a daily schedule (cron),
//        e.g. "0 7 * * *" for 7am every day.
//
// The function also works if you POST { "to": "someone@x.com" } to override
// the recipient, and returns a JSON preview so you can test it manually.
// ─────────────────────────────────────────────────────────────────────

const CATEGORY_LABELS = {
  gas_cert: 'Gas Safety Certificate',
  electrical_cert: 'Electrical (EICR) Certificate',
  epc_cert: 'EPC Certificate',
  license: 'Property Licence',
  insurance: 'Insurance',
  deposit_protection: 'Deposit Protection',
  lease_agreement: 'Lease Agreement',
  tenancy_agreement: 'Tenancy Agreement',
  sale_deed: 'Sale Deed',
  inventory: 'Inventory',
  other: 'Document',
};

function daysBetween(a, b) {
  return Math.round((a.getTime() - b.getTime()) / 86400000);
}

function fmtDate(d) {
  return d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
}

Deno.serve(async (req) => {
  try {
    // Service-role reads work when the client is built from the request —
    // this is how the app's other functions (flattenSignedDocument, etc.) do it,
    // and it supplies the service token that asServiceRole needs in scheduled runs.
    const base44 = createClientFromRequest(req);

    // Optional manual override of recipient when POSTed
    let overrideTo = null;
    try { if (req.method === 'POST') { const b = await req.json(); overrideTo = b?.to || null; } } catch { /* no body */ }

    const soonDays = Number(Deno.env.get('EXPIRY_SOON_DAYS') || 30);
    const recipient = overrideTo || Deno.env.get('EXPIRY_DIGEST_TO');
    if (!recipient) {
      return Response.json({ error: 'EXPIRY_DIGEST_TO is not set. Add your email in Settings → Environment Variables.' }, { status: 500 });
    }

    // Load documents + properties (service role reads everything)
    const [docs, properties] = await Promise.all([
      base44.asServiceRole.entities.PropertyDocument.list('-expiry_date', 5000),
      base44.asServiceRole.entities.Property.list('', 5000),
    ]);
    const propById = {};
    (properties || []).forEach((p) => { propById[p.id] = p; });

    const today = new Date();
    today.setHours(0, 0, 0, 0);

    // Keep only the MOST RECENT document per property + category. If a newer gas
    // cert has been uploaded for a property, an older expired one for the same
    // property must not appear in the digest. "Most recent" = latest issue_date,
    // falling back to latest expiry_date, then latest created_date.
    const latestByKey = {};
    (docs || []).forEach((d) => {
      if (d.is_archived) return;
      if (!d.property_id || !d.category) return;
      const key = `${d.property_id}__${d.category}`;
      const rank = (x) => x?.issue_date || x?.expiry_date || x?.created_date || '';
      const cur = latestByKey[key];
      if (!cur || rank(d) > rank(cur)) latestByKey[key] = d;
    });
    const currentDocs = Object.values(latestByKey);

    const expired = [];
    const expiring = [];

    currentDocs.forEach((d) => {
      if (!d.expiry_date) return;
      const exp = new Date(d.expiry_date);
      if (isNaN(exp.getTime())) return;
      exp.setHours(0, 0, 0, 0);
      const diff = daysBetween(exp, today); // negative = past

      const prop = propById[d.property_id];
      const row = {
        title: d.title || CATEGORY_LABELS[d.category] || 'Document',
        type: CATEGORY_LABELS[d.category] || d.category || 'Document',
        property: prop?.address || 'Unknown property',
        expiry: exp,
        diff,
        file_url: d.file_url || '',
      };
      if (diff < 0) expired.push(row);
      else if (diff <= soonDays) expiring.push(row);
    });

    expired.sort((a, b) => a.diff - b.diff);   // most overdue first
    expiring.sort((a, b) => a.diff - b.diff);  // soonest first

    const total = expired.length + expiring.length;

    // Build the email
    const rowHtml = (r, kind) => {
      const badge = kind === 'expired'
        ? `<span style="color:#b91c1c;font-weight:600;">Expired ${Math.abs(r.diff)} day${Math.abs(r.diff) === 1 ? '' : 's'} ago</span>`
        : `<span style="color:#b45309;font-weight:600;">${r.diff === 0 ? 'Expires today' : `In ${r.diff} day${r.diff === 1 ? '' : 's'}`}</span>`;
      return `<tr>
        <td style="padding:8px 12px;border-bottom:1px solid #eee;">${r.type}</td>
        <td style="padding:8px 12px;border-bottom:1px solid #eee;">${r.property}</td>
        <td style="padding:8px 12px;border-bottom:1px solid #eee;white-space:nowrap;">${fmtDate(r.expiry)}</td>
        <td style="padding:8px 12px;border-bottom:1px solid #eee;white-space:nowrap;">${badge}</td>
        <td style="padding:8px 12px;border-bottom:1px solid #eee;">${r.file_url ? `<a href="${r.file_url}" style="color:#1d4ed8;">View</a>` : '—'}</td>
      </tr>`;
    };

    const section = (title, rows, kind, color) => {
      if (rows.length === 0) return '';
      return `<h3 style="color:${color};margin:24px 0 8px;">${title} (${rows.length})</h3>
        <table style="border-collapse:collapse;width:100%;font-size:14px;">
          <thead><tr style="text-align:left;color:#666;">
            <th style="padding:8px 12px;border-bottom:2px solid #ddd;">Type</th>
            <th style="padding:8px 12px;border-bottom:2px solid #ddd;">Property</th>
            <th style="padding:8px 12px;border-bottom:2px solid #ddd;">Expiry</th>
            <th style="padding:8px 12px;border-bottom:2px solid #ddd;">Status</th>
            <th style="padding:8px 12px;border-bottom:2px solid #ddd;">File</th>
          </tr></thead>
          <tbody>${rows.map((r) => rowHtml(r, kind)).join('')}</tbody>
        </table>`;
    };

    const html = `<div style="font-family:Arial,sans-serif;max-width:720px;margin:0 auto;color:#111;">
      <h2 style="color:#16205c;margin-bottom:4px;">Certificate &amp; Document Expiry — ${fmtDate(today)}</h2>
      <p style="color:#555;margin-top:0;">
        ${total === 0
          ? 'Good news — nothing is expired or expiring within the next ' + soonDays + ' days.'
          : `${expired.length} expired and ${expiring.length} expiring within ${soonDays} days.`}
      </p>
      ${section('🔴 Expired', expired, 'expired', '#b91c1c')}
      ${section('🟠 Expiring soon', expiring, 'expiring', '#b45309')}
      <p style="color:#999;font-size:12px;margin-top:28px;">Automated daily summary from ASA Estates. Documents without an expiry date, and archived documents, are not included.</p>
    </div>`;

    // Send via Resend directly (no logged-in user in a scheduled run)
    const apiKey = Deno.env.get('RESEND_API_KEY');
    if (!apiKey) return Response.json({ error: 'RESEND_API_KEY is not set.' }, { status: 500 });
    const fromEmail = Deno.env.get('RESEND_FROM_EMAIL') || 'info@asaestates.com';

    const sendRes = await fetch('https://api.resend.com/emails', {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        from: `ASA Estates Ltd <${fromEmail}>`,
        to: recipient,
        subject: total === 0
          ? `✅ Certificates OK — ${fmtDate(today)}`
          : `⚠️ ${expired.length} expired, ${expiring.length} expiring — ${fmtDate(today)}`,
        html,
      }),
    });

    if (!sendRes.ok) {
      const detail = await sendRes.text();
      return Response.json({ error: `Resend error: ${sendRes.status} — ${detail}` }, { status: 502 });
    }

    return Response.json({ ok: true, sent_to: recipient, expired: expired.length, expiring: expiring.length });
  } catch (error) {
    console.error('dailyExpiryDigest error:', error);
    return Response.json({ error: error?.message || 'Failed to build expiry digest' }, { status: 500 });
  }
});

{
