import { createClientFromRequest } from 'npm:@base44/sdk@0.8.44';

// Lists and serves the monthly Google Drive backups created by monthlyDriveBackup.
//   action 'list'     -> [{ month: '2026-09', files: [{ id, name, size, modifiedTime }] }]
//   action 'download' -> { base64 } file contents for one file id
const ROOT_FOLDER = 'ASA Estates Backups';
const FOLDER_MIME = 'application/vnd.google-apps.folder';

export default async function(req) {
  try {
    const base44 = createClientFromRequest(req);
    const user = await base44.auth.me();
    if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 });
    const { accessToken } = await base44.asServiceRole.connectors.getConnection('googledrive');
    const authHeader = { Authorization: `Bearer ${accessToken}` };

    const payload = await req.json().catch(() => ({}));

    // Download a single backup file
    if (payload.action === 'download' && payload.fileId) {
      const res = await fetch(`https://www.googleapis.com/drive/v3/files/${payload.fileId}?alt=media`, { headers: authHeader });
      if (!res.ok) return Response.json({ error: `Drive download failed: ${res.status}` }, { status: 502 });
      const buf = new Uint8Array(await res.arrayBuffer());
      let binary = '';
      for (let i = 0; i < buf.length; i += 8192) {
        binary += String.fromCharCode(...buf.subarray(i, i + 8192));
      }
      return Response.json({ base64: btoa(binary) });
    }

    // Default: list month folders and their files
    const listFiles = async (q) => {
      const res = await fetch(
        `https://www.googleapis.com/drive/v3/files?q=${encodeURIComponent(q)}&fields=files(id,name,mimeType,size,modifiedTime)&pageSize=200`,
        { headers: authHeader }
      );
      if (!res.ok) throw new Error(`Drive list failed: ${res.status}`);
      return (await res.json()).files || [];
    };

    const rootFiles = await listFiles(`name='${ROOT_FOLDER}' and mimeType='${FOLDER_MIME}' and trashed=false`);
    if (rootFiles.length === 0) return Response.json({ months: [] });
    const rootId = rootFiles[0].id;

    const monthFolders = (await listFiles(`'${rootId}' in parents and mimeType='${FOLDER_MIME}' and trashed=false`))
      .sort((a, b) => b.name.localeCompare(a.name));

    const months = [];
    for (const folder of monthFolders) {
      const files = (await listFiles(`'${folder.id}' in parents and trashed=false`))
        .sort((a, b) => a.name.localeCompare(b.name));
      months.push({ month: folder.name, files });
    }
    return Response.json({ months });
  } catch (error) {
    return Response.json({ error: error?.message || 'Request failed' }, { status: 500 });
  }
}

import { createClientFromRequest } from 'npm:@base44/sdk@0.8.31';
import { PDFDocument, rgb, StandardFonts } from 'npm:pdf-lib@1.17.1';

Deno.serve(async (req) => {
  try {
    const base44 = createClientFromRequest(req);
    const { documentId } = await req.json();

    if (!documentId) {
      return Response.json({ error: 'documentId required' }, { status: 400 });
    }

    const document = await base44.asServiceRole.entities.Document.get(documentId);
    if (!document || !document.original_file_url) {
      return Response.json({ error: 'Document or original file not found' }, { status: 404 });
    }

    // Fetch the original PDF
    const pdfResponse = await fetch(document.original_file_url);
    if (!pdfResponse.ok) {
      return Response.json({ error: 'Failed to fetch original PDF' }, { status: 500 });
    }
    const pdfBytes = new Uint8Array(await pdfResponse.arrayBuffer());

    const pdfDoc = await PDFDocument.load(pdfBytes);
    const helveticaFont = await pdfDoc.embedFont(StandardFonts.Helvetica);
    const helveticaBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
    const pages = pdfDoc.getPages();

    const fitText = (str, font, size, maxWidth) => {
      let s = String(str || '');
      if (font.widthOfTextAtSize(s, size) <= maxWidth) return s;
      while (s.length > 1 && font.widthOfTextAtSize(s + '...', size) > maxWidth) {
        s = s.slice(0, -1);
      }
      return s + '...';
    };

    // Get all signature fields with values for this document
    const fields = await base44.asServiceRole.entities.SignatureField.filter({ document_id: documentId });

    for (const field of fields) {
      if (!field.value && field.type !== 'checkbox') continue;

      const pageIdx = (field.page || 1) - 1;
      const page = pages[pageIdx];
      if (!page) continue;

      const { width: pageWidth, height: pageHeight } = page.getSize();
      const x = (field.x || 0) * pageWidth;
      const fieldW = (field.width || 0.15) * pageWidth;
      const fieldH = (field.height || 0.04) * pageHeight;
      // PDF y is from bottom; our y is from top
      const y = pageHeight - (field.y || 0) * pageHeight - fieldH;

      if (field.type === 'signature' || field.type === 'initials') {
        // value is a data URL: data:image/png;base64,xxxx
        const dataUrl = field.value || '';
        const base64Match = dataUrl.match(/^data:image\/(png|jpeg|jpg);base64,(.+)$/);
        if (base64Match) {
          const isPng = base64Match[1] === 'png';
          const base64Data = base64Match[2];
          const binaryString = atob(base64Data);
          const imgBytes = new Uint8Array(binaryString.length);
          for (let i = 0; i < binaryString.length; i++) {
            imgBytes[i] = binaryString.charCodeAt(i);
          }
          let img;
          if (isPng) {
            img = await pdfDoc.embedPng(imgBytes);
          } else {
            img = await pdfDoc.embedJpg(imgBytes);
          }
          // Scale image to fit field bounds while maintaining aspect ratio
          const imgAspect = img.width / img.height;
          const fieldAspect = fieldW / fieldH;
          let drawW = fieldW;
          let drawH = fieldH;
          if (imgAspect > fieldAspect) {
            drawH = fieldW / imgAspect;
          } else {
            drawW = fieldH * imgAspect;
          }
          const drawX = x + (fieldW - drawW) / 2;
          const drawY = y + (fieldH - drawH) / 2;
          page.drawImage(img, { x: drawX, y: drawY, width: drawW, height: drawH });
        }
      } else if (field.type === 'text' || field.type === 'name' || field.type === 'date') {
        const fontSize = Math.min(fieldH * 0.65, 12);
        const text = fitText(field.value || '', helveticaFont, fontSize, fieldW - 8);
        page.drawText(text, {
          x: x + 4,
          y: y + fieldH / 2 - fontSize / 3,
          size: fontSize,
          font: helveticaFont,
          color: rgb(0.08, 0.08, 0.08),
        });
      } else if (field.type === 'checkbox') {
        // Draw a checkmark if value is truthy
        if (field.value === 'true' || field.value === true) {
          const fontSize = Math.min(fieldH * 0.8, 14);
          page.drawText('✓', {
            x: x + fieldW / 2 - fontSize / 3,
            y: y + fieldH / 2 - fontSize / 3,
            size: fontSize,
            font: helveticaBold,
            color: rgb(0.08, 0.08, 0.08),
          });
        }
      }
    }

    // ── Append Audit Trail pages ──
    const signers = await base44.asServiceRole.entities.Signer.filter({ document_id: documentId });
    const events = await base44.asServiceRole.entities.AuditEvent.filter({ document_id: documentId }, 'created_date');
    const signerMap = {};
    for (const s of signers) signerMap[s.id] = s.name;

    const blue = rgb(30 / 255, 64 / 255, 175 / 255);
    const gray = rgb(120 / 255, 120 / 255, 120 / 255);
    const darkGray = rgb(80 / 255, 80 / 255, 80 / 255);
    const lightLine = rgb(220 / 255, 220 / 255, 220 / 255);
    const text = rgb(40 / 255, 40 / 255, 40 / 255);

    const auditPageW = 595.28; // A4 width in pt
    const auditPageH = 841.89; // A4 height in pt
    const m = 50;
    const colTs = m;
    const colEv = m + 120;
    const colSn = m + 210;
    const colIp = m + 310;
    const colUa = m + 390;
    const colEnd = auditPageW - m; // 545.28

    const addAuditHeader = (page) => {
      page.drawRectangle({ x: 0, y: auditPageH - 8, width: auditPageW, height: 8, color: blue });
      page.drawText('Audit Trail', { x: auditPageW / 2 - 55, y: auditPageH - 60, size: 18, font: helveticaBold, color: blue });
      const titleStr = String(document.title || '').substring(0, 70);
      page.drawText(titleStr, { x: auditPageW / 2 - helveticaFont.widthOfTextAtSize(titleStr, 10) / 2, y: auditPageH - 78, size: 10, font: helveticaFont, color: gray });
    };

    let auditPage = pdfDoc.addPage([auditPageW, auditPageH]);
    addAuditHeader(auditPage);
    let ay = auditPageH - 110;
    auditPage.drawText('Timestamp', { x: colTs, y: ay, size: 8, font: helveticaBold, color: darkGray });
    auditPage.drawText('Event', { x: colEv, y: ay, size: 8, font: helveticaBold, color: darkGray });
    auditPage.drawText('Signer', { x: colSn, y: ay, size: 8, font: helveticaBold, color: darkGray });
    auditPage.drawText('IP Address', { x: colIp, y: ay, size: 8, font: helveticaBold, color: darkGray });
    auditPage.drawText('User Agent', { x: colUa, y: ay, size: 8, font: helveticaBold, color: darkGray });
    ay -= 6;
    auditPage.drawLine({ start: { x: m, y: ay }, end: { x: auditPageW - m, y: ay }, thickness: 0.5, color: lightLine });
    ay -= 14;

    for (const ev of events) {
      if (ay < 60) {
        auditPage = pdfDoc.addPage([auditPageW, auditPageH]);
        addAuditHeader(auditPage);
        ay = auditPageH - 110;
      }
      const ts = new Date(ev.created_date).toLocaleString('en-GB', { timeZone: 'Europe/London' });
      auditPage.drawText(fitText(ts, helveticaFont, 8, colEv - colTs - 4), { x: colTs, y: ay, size: 8, font: helveticaFont, color: text });
      auditPage.drawText(fitText(String(ev.event_type || '').replace(/_/g, ' '), helveticaFont, 8, colSn - colEv - 4), { x: colEv, y: ay, size: 8, font: helveticaFont, color: text });
      auditPage.drawText(fitText(signerMap[ev.signer_id] || '—', helveticaFont, 8, colIp - colSn - 4), { x: colSn, y: ay, size: 8, font: helveticaFont, color: text });
      auditPage.drawText(fitText(ev.ip_address || '—', helveticaFont, 8, colUa - colIp - 4), { x: colIp, y: ay, size: 8, font: helveticaFont, color: text });
      auditPage.drawText(fitText(ev.user_agent || '', helveticaFont, 7, colEnd - colUa - 2), { x: colUa, y: ay, size: 7, font: helveticaFont, color: text });
      ay -= 16;
    }

    // Footer on audit pages
    const totalPages = pdfDoc.getPageCount();
    const origPageCount = pages.length;
    for (let i = origPageCount; i < totalPages; i++) {
      const p = pdfDoc.getPage(i);
      p.drawText(`ASA Estates — Audit Trail — ${String(document.title || '').substring(0, 50)}`, { x: m, y: 20, size: 7, font: helveticaFont, color: gray });
      p.drawText(`Page ${i + 1} of ${totalPages}`, { x: auditPageW - m - 60, y: 20, size: 7, font: helveticaFont, color: gray });
    }

    const flattenedBytes = await pdfDoc.save();
    const file = new File([flattenedBytes], `signed-${documentId}.pdf`, { type: 'application/pdf' });
    const { file_url } = await base44.asServiceRole.integrations.Core.UploadFile({ file });

    return Response.json({ file_url });
  } catch (error) {
    return Response.json({ error: error.message }, { status: 500 });
  }
});

import { createClientFromRequest } from 'npm:@base44/sdk@0.8.31';
import { jsPDF } from 'npm:jspdf@4.2.1';

Deno.serve(async (req) => {
  try {
    const base44 = createClientFromRequest(req);
    const { documentId } = await req.json();

    if (!documentId) {
      return Response.json({ error: 'documentId required' }, { status: 400 });
    }

    const document = await base44.asServiceRole.entities.Document.get(documentId);
    if (!document) {
      return Response.json({ error: 'Document not found' }, { status: 404 });
    }

    const signers = await base44.asServiceRole.entities.Signer.filter({ document_id: documentId });
    const events = await base44.asServiceRole.entities.AuditEvent.filter({ document_id: documentId }, "created_date");

    const doc = new jsPDF({ unit: 'pt', format: 'a4' });
    const pageWidth = doc.internal.pageSize.getWidth();
    const pageHeight = doc.internal.pageSize.getHeight();
    const margin = 50;
    const contentWidth = pageWidth - margin * 2;

    // ── Page 1: Certificate ──
    doc.setFillColor(30, 64, 175);
    doc.rect(0, 0, pageWidth, 8, 'F');

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(26);
    doc.setTextColor(30, 64, 175);
    doc.text('Certificate of Completion', pageWidth / 2, 90, { align: 'center' });

    doc.setDrawColor(200, 200, 200);
    doc.setLineWidth(0.5);
    doc.line(margin, 110, pageWidth - margin, 110);

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(11);
    doc.setTextColor(90, 90, 90);
    doc.text('This certifies that the following document has been electronically signed', pageWidth / 2, 140, { align: 'center' });
    doc.text('by all required parties.', pageWidth / 2, 156, { align: 'center' });

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(16);
    doc.setTextColor(20, 20, 20);
    const titleLines = doc.splitTextToSize(document.title, contentWidth);
    doc.text(titleLines, pageWidth / 2, 190, { align: 'center' });

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(10);
    doc.setTextColor(120, 120, 120);
    const completedAt = document.completed_at ? new Date(document.completed_at) : new Date();
    doc.text(`Completed on ${completedAt.toLocaleString('en-GB', { timeZone: 'Europe/London' })}`, pageWidth / 2, 190 + titleLines.length * 18 + 10, { align: 'center' });

    // Signers table
    let y = 190 + titleLines.length * 18 + 50;
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(12);
    doc.setTextColor(30, 64, 175);
    doc.text('Signatures', margin, y);

    y += 10;
    doc.setDrawColor(220, 220, 220);
    doc.setLineWidth(0.5);
    doc.line(margin, y, pageWidth - margin, y);
    y += 18;

    doc.setFontSize(9);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(80, 80, 80);
    doc.text('Name', margin, y);
    doc.text('Email', margin + 160, y);
    doc.text('Signed At', margin + 320, y);
    doc.text('IP Address', margin + 430, y);
    y += 6;
    doc.line(margin, y, pageWidth - margin, y);
    y += 16;

    doc.setFont('helvetica', 'normal');
    doc.setTextColor(40, 40, 40);
    for (const s of signers) {
      if (y > pageHeight - 60) {
        doc.addPage();
        y = margin + 20;
      }
