    doc.setFontSize(10);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(120, 120, 120);
    doc.text(document.title, pageWidth / 2, 78, { align: 'center' });

    y = 110;
    doc.setFontSize(8);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(80, 80, 80);
    doc.text('Timestamp', margin, y);
    doc.text('Event', margin + 130, y);
    doc.text('Signer', margin + 220, y);
    doc.text('IP Address', margin + 340, y);
    doc.text('User Agent', margin + 430, y);
    y += 6;
    doc.setDrawColor(220, 220, 220);
    doc.line(margin, y, pageWidth - margin, y);
    y += 14;

    doc.setFont('helvetica', 'normal');
