      doc.text(String(signerMap[ev.signer_id] || '—').substring(0, 20), margin + 220, y);
      doc.text(String(ev.ip_address || '—').substring(0, 18), margin + 340, y);
      const uaLines = doc.splitTextToSize(String(ev.user_agent || ''), pageWidth - margin - 430);
      doc.text(uaLines[0] || '', margin + 430, y);
      y += 16;
