import { createClientFromRequest } from 'npm:@base44/sdk@0.8.25';
import PizZip from 'npm:pizzip@3.1.7';

const TEMPLATE_URL = 'https://media.base44.com/files/public/69c6590f7634ba358a23028f/db2d3b922_APT_Agreement_TEMPLATE_PLACEHOLDERS.docx';

function formatDate(dateStr) {
  if (!dateStr) return '';
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return '';
  const day = d.getDate();
  const month = d.toLocaleString('en-GB', { month: 'long' });
  const year = d.getFullYear();
  return `${day} ${month} ${year}`;
}

function ordinal(n) {
  if (!n) return '';
  const v = Number(n) % 100;
  const s = ['th','st','nd','rd'];
  return n + (s[(v-20)%10] || s[v] || s[0]);
}

function numToWords(n) {
  const ones = ['','one','two','three','four','five','six','seven','eight','nine','ten',
    'eleven','twelve','thirteen','fourteen','fifteen','sixteen','seventeen','eighteen','nineteen'];
  const tens = ['','','twenty','thirty','forty','fifty','sixty','seventy','eighty','ninety'];
  if (n === 0) return 'zero';
  if (n < 20) return ones[n];
  if (n < 100) return tens[Math.floor(n/10)] + (n % 10 ? '-' + ones[n%10] : '');
  if (n < 1000) return ones[Math.floor(n/100)] + ' hundred' + (n%100 ? ' and ' + numToWords(n%100) : '');
  return String(n);
}

function rentInWords(amount) {
  const n = Math.round(Number(amount));
  const pounds = Math.floor(n);
  return `${numToWords(pounds).charAt(0).toUpperCase() + numToWords(pounds).slice(1)} Pounds`;
}

// Escape XML special chars
function escXml(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

Deno.serve(async (req) => {
  try {
    const base44 = createClientFromRequest(req);
    const user = await base44.auth.me();
    if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 });

    const body = await req.json();
    const {
      tenant_name, tenant_email, tenant_phone,
      property_address, landlord_name, landlord_address,
      monthly_rent, deposit, lease_start, payment_day,
      unit_description
    } = body;

    // Fetch template
    const templateRes = await fetch(TEMPLATE_URL);
    if (!templateRes.ok) throw new Error('Failed to fetch template DOCX');
    const templateBuf = await templateRes.arrayBuffer();

    const zip = new PizZip(templateBuf);

    const rentNum = Number(monthly_rent) || 0;
    const depositNum = Number(deposit) || 0;
    const rentStr = `£${rentNum.toLocaleString('en-GB', { minimumFractionDigits: 2 })}`;
    const depositStr = `£${depositNum.toLocaleString('en-GB', { minimumFractionDigits: 2 })}`;
    const payDay = payment_day ? `the ${ordinal(Number(payment_day))}` : 'the 1st';
    const startDateStr = formatDate(lease_start);
    const todayStr = formatDate(new Date().toISOString().split('T')[0]);
    const rentWords = rentInWords(rentNum);
    const propertyFull = unit_description
      ? `${property_address}\n${unit_description}`
      : property_address || '';

    // Split tenant name into two for joint tenancy fields
    const tenantNameStr = tenant_name || '';
    const nameParts = tenantNameStr.split(/\s+and\s+|\s*&\s*|,/).map(s => s.trim()).filter(Boolean);
    const tenant1Name = nameParts[0] || tenantNameStr;
    const tenant2Name = nameParts[1] || '';

    // Placeholder → value mapping
    const replacements = {
      '{{PREMISES}}': escXml(propertyFull),
      '{{AGREEMENT_DATE}}': escXml(todayStr),
      '{{LANDLORD_NAME}}': escXml(landlord_name || ''),
      '{{LANDLORD_ADDRESS}}': escXml(landlord_address || ''),
      '{{TENANT_NAMES}}': escXml(tenantNameStr),
      '{{TENANT_EMAILS}}': escXml(tenant_email || ''),
      '{{TENANT_PHONE}}': escXml(tenant_phone || ''),
      '{{START_DATE}}': escXml(startDateStr),
      '{{RENT}}': escXml(`${rentStr} (${rentWords})`),
      '{{RENT_DAY}}': escXml(payDay),
      '{{DEPOSIT}}': escXml(depositStr),
      '{{TENANT1_NAME}}': escXml(tenant1Name),
      '{{TENANT2_NAME}}': escXml(tenant2Name),
      // Document reference placeholders — left blank (filled manually if needed)
      '{{DOC_1}}': '', '{{DOC_2}}': '', '{{DOC_3}}': '', '{{DOC_4}}': '', '{{DOC_5}}': '',
      '{{DOC_6}}': '', '{{DOC_7}}': '', '{{DOC_8}}': '', '{{DOC_9}}': '', '{{DOC_10}}': '',
      '{{DOC_11}}': '',
    };

    let docXml = zip.files['word/document.xml'].asText();

    // Apply all placeholder replacements
    for (const [search, replacement] of Object.entries(replacements)) {
      docXml = docXml.split(search).join(replacement);
    }

    zip.file('word/document.xml', docXml);

    const out = zip.generate({
      type: 'base64',
      mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      compression: 'DEFLATE',
    });

    return Response.json({ base64: out });
  } catch (error) {
    console.error('generateTenancyAgreement error:', error);
    return Response.json({ error: error.message }, { status: 500 });
  }
});

