import { createClientFromRequest } from 'npm:@base44/sdk@0.8.31';
import * as XLSX from 'npm:xlsx@0.18.5';

// ─────────────────────────────────────────────────────────────────────
// MONTHLY DATA BACKUP TO GOOGLE DRIVE
//
// Every month creates a folder structure in Google Drive:
//
//   ASA Estates Backups/
//     └─ 2026-09/
//         ├─ asa-estates-backup-2026-09.json   (full machine-readable backup)
//         ├─ Properties & Tenants.xlsx         (one sheet per data type)
//         ├─ Payments & Payouts.xlsx
//         ├─ Commission & Invoices.xlsx
//         ├─ Ledger & Banking.xlsx
//         ├─ Maintenance & Inspections.xlsx
//         ├─ CRM & Communications.xlsx
//         ├─ Documents & Signatures.xlsx
//         └─ Admin & Audit.xlsx
//
// Runs on the 1st of every month via the "Monthly Data Backup" workflow.
// Re-runs in the same month overwrite the same files (no duplicates).
// ─────────────────────────────────────────────────────────────────────

const ROOT_FOLDER = 'ASA Estates Backups';
const FOLDER_MIME = 'application/vnd.google-apps.folder';
const XLSX_MIME = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';

// Every business entity in the app
const ENTITIES = [
  'Property', 'Tenant', 'Landlord', 'RentPayment', 'RentHistory', 'LandlordPayout',
  'CommissionLedger', 'CommissionAgreement', 'CommissionHistory', 'ManualInvoice',
  'TenantManualInvoice', 'TenantInvoiceCharge', 'TenantCarriedBalance', 'DepositPayment',
  'PaymentExtra', 'Expense', 'LedgerAdjustment', 'CashEntry', 'Bank',
  'MonthlyLedgerSnapshot', 'LedgerDayCount', 'HouseKey', 'MaintenanceRequest',
  'Inspection', 'InspectionReport', 'PropertyDocument', 'Inquiry', 'ProspectiveTenant',
  'CRMEntry', 'EmailLog', 'Task', 'TeamMember', 'AuditLog', 'Document', 'Signer',
  'SignatureField', 'AuditEvent', 'SignatureRequest',
];

// How entities are grouped into Excel workbooks (one sheet per entity)
const EXCEL_GROUPS = [
  { file: 'Properties & Tenants.xlsx', entities: ['Property', 'Tenant', 'HouseKey', 'PropertyDocument'] },
  { file: 'Payments & Payouts.xlsx', entities: ['RentPayment', 'RentHistory', 'DepositPayment', 'LandlordPayout', 'Landlord'] },
  { file: 'Commission & Invoices.xlsx', entities: ['CommissionLedger', 'CommissionAgreement', 'CommissionHistory', 'ManualInvoice', 'TenantManualInvoice', 'TenantInvoiceCharge', 'TenantCarriedBalance', 'PaymentExtra'] },
  { file: 'Ledger & Banking.xlsx', entities: ['Bank', 'CashEntry', 'LedgerAdjustment', 'MonthlyLedgerSnapshot', 'LedgerDayCount', 'Expense'] },
  { file: 'Maintenance & Inspections.xlsx', entities: ['MaintenanceRequest', 'Inspection', 'InspectionReport', 'Task'] },
  { file: 'CRM & Communications.xlsx', entities: ['CRMEntry', 'Inquiry', 'ProspectiveTenant', 'EmailLog', 'TeamMember'] },
  { file: 'Documents & Signatures.xlsx', entities: ['Document', 'Signer', 'SignatureField', 'AuditEvent', 'SignatureRequest'] },
  { file: 'Admin & Audit.xlsx', entities: ['AuditLog'] },
];

// Flatten a record for a spreadsheet cell: nested objects/arrays (e.g. monthly_notes)
// become readable JSON text, capped at Excel's cell size limit.
function toRow(rec) {
  const row = {};
  for (const [k, v] of Object.entries(rec)) {
    row[k] = (v !== null && typeof v === 'object')
      ? JSON.stringify(v).slice(0, 32000)
      : v;
  }
  return row;
}

async function findId(authHeader, query) {
  const res = await fetch(`https://www.googleapis.com/drive/v3/files?q=${encodeURIComponent(query)}`, { headers: authHeader });
  if (!res.ok) return null;
  const files = (await res.json()).files || [];
  return files.length > 0 ? files[0].id : null;
}

async function findOrCreateFolder(authHeader, name, parentId) {
  const q = `name='${name}' and mimeType='${FOLDER_MIME}' and trashed=false` +
    (parentId ? ` and '${parentId}' in parents` : '');
  const existing = await findId(authHeader, q);
  if (existing) return existing;
  const res = await fetch('https://www.googleapis.com/drive/v3/files', {
    method: 'POST',
    headers: { ...authHeader, 'Content-Type': 'application/json' },
    body: JSON.stringify({ name, mimeType: FOLDER_MIME, ...(parentId ? { parents: [parentId] } : {}) }),
  });
  if (!res.ok) throw new Error(`Could not create folder '${name}': ${res.status} — ${await res.text()}`);
  return (await res.json()).id;
}

async function uploadFile(authHeader, name, parentId, mimeType, body, existingId) {
  const initUrl = existingId
    ? `https://www.googleapis.com/upload/drive/v3/files/${existingId}?uploadType=resumable`
    : 'https://www.googleapis.com/upload/drive/v3/files?uploadType=resumable';
  const metadata = existingId ? { name } : { name, mimeType, parents: [parentId] };
  const initRes = await fetch(initUrl, {
    method: existingId ? 'PATCH' : 'POST',
    headers: { ...authHeader, 'Content-Type': 'application/json', 'X-Upload-Content-Type': mimeType },
    body: JSON.stringify(metadata),
  });
  const location = initRes.headers.get('Location');
  if (!initRes.ok || !location) throw new Error(`Drive upload init failed for '${name}': ${initRes.status} — ${await initRes.text()}`);
  const upRes = await fetch(location, {
    method: 'PUT',
    headers: { ...authHeader, 'Content-Type': mimeType },
    body,
  });
  if (!upRes.ok) throw new Error(`Drive upload failed for '${name}': ${upRes.status} — ${await upRes.text()}`);
  return (await upRes.json()).id;
}

// Upload a file, overwriting an existing file of the same name in the folder
async function uploadToFolder(authHeader, name, parentId, mimeType, body) {
  const existingId = await findId(
    authHeader,
    `name='${name}' and '${parentId}' in parents and trashed=false`
  );
  return uploadFile(authHeader, name, parentId, mimeType, body, existingId);
}

Deno.serve(async (req) => {
  try {
    const base44 = createClientFromRequest(req);
    const { accessToken } = await base44.asServiceRole.connectors.getConnection('googledrive');
    const authHeader = { Authorization: `Bearer ${accessToken}` };

    // 1. Collect all entity data
    const backup = { generated_at: new Date().toISOString(), entities: {} };
    const skipped = [];
    for (const name of ENTITIES) {
      try {
        const records = await base44.asServiceRole.entities[name].list('', 10000);
        backup.entities[name] = records || [];
      } catch (e) {
        skipped.push(name); // entity missing or unreadable — back up the rest
      }
    }

    // 2. Which months to back up — payload.months for backfills, else the current month
    let payload = {};
    try { payload = await req.json(); } catch (e) {}
    const now = new Date();
    const currentMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    const months = Array.isArray(payload?.months) && payload.months.length > 0
      ? payload.months
      : [currentMonth];

    // 3. Build the Excel workbooks once (same data across months in a single run)
    const jsonBytes = JSON.stringify(backup);
    const excelFiles = EXCEL_GROUPS.map(group => {
      const wb = XLSX.utils.book_new();
      for (const entityName of group.entities) {
        const records = backup.entities[entityName] || [];
        const ws = records.length > 0
          ? XLSX.utils.json_to_sheet(records.map(toRow))
          : XLSX.utils.aoa_to_sheet([['No records']]);
        XLSX.utils.book_append_sheet(wb, ws, entityName.slice(0, 31));
      }
      return { name: group.file, bytes: XLSX.write(wb, { bookType: 'xlsx', type: 'array' }) };
    });

    // 4. One folder per month, each with the JSON + all Excel workbooks
    const rootId = await findOrCreateFolder(authHeader, ROOT_FOLDER, null);
    const results = [];
    for (const monthKey of months) {
      const monthId = await findOrCreateFolder(authHeader, monthKey, rootId);
      const uploaded = [];
      const jsonName = `asa-estates-backup-${monthKey}.json`;
      await uploadToFolder(authHeader, jsonName, monthId, 'application/json', jsonBytes);
      uploaded.push(jsonName);
      for (const f of excelFiles) {
        await uploadToFolder(authHeader, f.name, monthId, XLSX_MIME, f.bytes);
        uploaded.push(f.name);
      }
      results.push({ month: monthKey, files: uploaded });
    }

    const totalRecords = Object.values(backup.entities).reduce((sum, arr) => sum + arr.length, 0);
    return Response.json({
      ok: true,
      root: ROOT_FOLDER,
      months: results,
      size_kb: Math.round(jsonBytes.length / 1024),
      entities: Object.keys(backup.entities).length,
      total_records: totalRecords,
      ...(skipped.length ? { skipped } : {}),
    });
  } catch (error) {
    console.error('monthlyDriveBackup error:', error);
    return Response.json({ error: error?.message || 'Backup failed' }, { status: 500 });
  }
});

// Returns nearby railway/tube stations and schools for a property, using free
// OpenStreetMap services (Nominatim for geocoding, Overpass for places).
// Input JSON: { address?: string, lat?: number, lng?: number }
// Output: { lat, lng, stations: [{name,type,miles}], schools: [{name,ages,miles}] }

const UA = 'ASA-Estates/1.0 (info@asaestates.com)';

function haversineMiles(aLat: number, aLng: number, bLat: number, bLng: number) {
  const R = 3958.8; // miles
  const dLat = (bLat - aLat) * Math.PI / 180;
  const dLng = (bLng - aLng) * Math.PI / 180;
  const s = Math.sin(dLat / 2) ** 2 +
    Math.cos(aLat * Math.PI / 180) * Math.cos(bLat * Math.PI / 180) * Math.sin(dLng / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(s), Math.sqrt(1 - s));
}

function stationType(tags: Record<string, string> = {}) {
  if (tags.station === 'subway') return 'Underground';
  if (tags.station === 'light_rail' || tags.light_rail === 'yes') return 'Light rail / DLR';
  if (tags.tram === 'yes' || tags.railway === 'tram_stop') return 'Tram';
  if (tags.railway === 'station' || tags.railway === 'halt') return 'Rail';
  return 'Station';
}

function schoolAges(tags: Record<string, string> = {}) {
  const min = tags['min_age'] || tags['school:age:min'];
  const max = tags['max_age'] || tags['school:age:max'];
  if (min && max) return `Age ${min} - ${max}`;
  return '';
}

async function geocode(address: string) {
  const url = `https://nominatim.openstreetmap.org/search?format=json&limit=1&q=${encodeURIComponent(address)}`;
  const res = await fetch(url, { headers: { 'User-Agent': UA, 'Accept-Language': 'en-GB' } });
  if (!res.ok) throw new Error(`Geocode failed (${res.status})`);
  const data = await res.json();
  if (!data || !data.length) throw new Error('Address could not be located');
  return { lat: parseFloat(data[0].lat), lng: parseFloat(data[0].lon) };
}

async function overpass(lat: number, lng: number) {
  const q = `[out:json][timeout:25];
(
  node(around:2500,${lat},${lng})[railway=station];
  node(around:2500,${lat},${lng})[railway=halt];
  node(around:2500,${lat},${lng})[station=subway];
  node(around:2500,${lat},${lng})[railway=tram_stop];
  node(around:1800,${lat},${lng})[amenity=school];
  way(around:1800,${lat},${lng})[amenity=school];
);
out center tags;`;
  const res = await fetch('https://overpass-api.de/api/interpreter', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded', 'User-Agent': UA },
    body: 'data=' + encodeURIComponent(q),
  });
  if (!res.ok) throw new Error(`Overpass failed (${res.status})`);
  return res.json();
}

Deno.serve(async (req) => {
  try {
    const { address, lat, lng } = await req.json().catch(() => ({}));
    let plat = typeof lat === 'number' ? lat : NaN;
    let plng = typeof lng === 'number' ? lng : NaN;

    if (Number.isNaN(plat) || Number.isNaN(plng)) {
      if (!address) return Response.json({ error: 'address or lat/lng required' }, { status: 400 });
      const g = await geocode(address);
      plat = g.lat; plng = g.lng;
    }

    const data = await overpass(plat, plng);
    const elements: any[] = data.elements || [];

    const stations: any[] = [];
    const schools: any[] = [];
    const seenS = new Set<string>();
    const seenSch = new Set<string>();

    for (const el of elements) {
      const tags = el.tags || {};
      const name = tags.name;
      if (!name) continue;
      const elat = el.lat ?? el.center?.lat;
      const elng = el.lon ?? el.center?.lon;
      if (typeof elat !== 'number' || typeof elng !== 'number') continue;
      const miles = haversineMiles(plat, plng, elat, elng);

      if (tags.amenity === 'school') {
        if (seenSch.has(name)) continue;
        seenSch.add(name);
        schools.push({ name, ages: schoolAges(tags), miles: Math.round(miles * 10) / 10 });
      } else {
        if (seenS.has(name)) continue;
        seenS.add(name);
        stations.push({ name, type: stationType(tags), miles: Math.round(miles * 10) / 10 });
      }
    }

    stations.sort((a, b) => a.miles - b.miles);
    schools.sort((a, b) => a.miles - b.miles);

    return Response.json({
      lat: plat,
      lng: plng,
      stations: stations.slice(0, 6),
      schools: schools.slice(0, 6),
    });
  } catch (error) {
    return Response.json({ error: (error as Error).message }, { status: 500 });
  }
});

