// ─────────────────────────────────────────────────────────────────────
// Sends a WhatsApp message to the manager/admin phone number(s).
// Generic: pass { message } — reusable for any alert, not just maintenance.
//
// Supports two providers, chosen by the WHATSAPP_PROVIDER secret:
//
// 1) "callmebot" (default — free, 5-minute setup, ideal for internal alerts)
//    Each recipient does a ONE-TIME setup:
//      a. Save +34 621 331 709 in their phone contacts (CallMeBot)
//      b. Send it the WhatsApp message: "I allow callmebot to send me messages"
//      c. They receive their personal API key by reply
//    Then set the secret:
//      WHATSAPP_RECIPIENTS = 447700900001:APIKEY1,447700900002:APIKEY2
//    (number with country code, no + or spaces, colon, then their key;
//     comma-separate multiple admins)
//
// 2) "meta" (official WhatsApp Business Cloud API)
//    Secrets required:
//      WHATSAPP_TOKEN            – permanent access token
//      WHATSAPP_PHONE_NUMBER_ID  – sender phone number ID
//      WHATSAPP_RECIPIENTS       = 447700900001,447700900002
//    Note: business-initiated messages need an approved template unless the
//    recipient has messaged the business within the last 24 hours.
//    WHATSAPP_TEMPLATE_NAME (optional) – if set, sends that template with the
//    message as its single {{1}} body parameter; otherwise sends free text.
// ─────────────────────────────────────────────────────────────────────

const cors = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Authorization',
};

Deno.serve(async (req) => {
  try {
    if (req.method === 'OPTIONS') return new Response(null, { status: 204, headers: cors });

    const base44 = createClientFromRequest(req);
    const user = await base44.auth.me();
    if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401, headers: cors });

    const { message, to, target } = await req.json();
    if (!message || typeof message !== 'string') {
      return Response.json({ error: 'message is required' }, { status: 400, headers: cors });
    }
    // WhatsApp hard limit safety
    const text = message.slice(0, 3000);

    const provider = (Deno.env.get('WHATSAPP_PROVIDER') || 'callmebot').toLowerCase();

    // Recipients resolution:
    //  • target === 'contractor'  → WHATSAPP_CONTRACTOR secret (the fixed maintenance guy)
    //  • explicit `to` provided    → use it (phone:apikey for callmebot, phone for meta)
    //  • otherwise                 → WHATSAPP_RECIPIENTS (admin alerts, the default)
    // Keeping the contractor's number in a secret means it never has to live in
    // the frontend code.
    let recipientsRaw;
    if (target === 'contractor') {
      recipientsRaw = Deno.env.get('WHATSAPP_CONTRACTOR') || '';
      if (!recipientsRaw) {
        return Response.json({
          error: 'No contractor number configured. Add WHATSAPP_CONTRACTOR in Settings → Environment Variables (format phone:apikey for CallMeBot, or just the phone for the meta provider).',
        }, { status: 500, headers: cors });
      }
    } else if (to) {
      recipientsRaw = Array.isArray(to) ? to.join(',') : String(to);
    } else {
      recipientsRaw = Deno.env.get('WHATSAPP_RECIPIENTS') || '';
    }
    const recipients = recipientsRaw.split(',').map(r => r.trim()).filter(Boolean);
    if (recipients.length === 0) {
      return Response.json({
        error: 'WHATSAPP_RECIPIENTS is not set. Add it in Settings → Environment Variables.',
      }, { status: 500, headers: cors });
    }

    const results = [];

    if (provider === 'meta') {
      const token = Deno.env.get('WHATSAPP_TOKEN');
      const phoneNumberId = Deno.env.get('WHATSAPP_PHONE_NUMBER_ID');
      if (!token || !phoneNumberId) {
        return Response.json({
          error: 'WHATSAPP_TOKEN and WHATSAPP_PHONE_NUMBER_ID must be set for the meta provider.',
        }, { status: 500, headers: cors });
      }
      const templateName = Deno.env.get('WHATSAPP_TEMPLATE_NAME');

      for (const to of recipients) {
        const payload = templateName
          ? {
              messaging_product: 'whatsapp',
              to,
              type: 'template',
              template: {
                name: templateName,
                language: { code: 'en' },
                components: [{ type: 'body', parameters: [{ type: 'text', text }] }],
              },
            }
          : { messaging_product: 'whatsapp', to, type: 'text', text: { body: text } };

        try {
          const res = await fetch(`https://graph.facebook.com/v21.0/${phoneNumberId}/messages`, {
            method: 'POST',
            headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
            body: JSON.stringify(payload),
          });
          const body = await res.text();
          results.push({ to, ok: res.ok, status: res.status, detail: res.ok ? undefined : body.slice(0, 300) });
        } catch (err) {
          results.push({ to, ok: false, detail: err?.message || 'fetch failed' });
        }
      }
    } else {
      // CallMeBot — recipients are "phone:apikey" pairs
      for (const entry of recipients) {
        const [phone, apikey] = entry.split(':').map(s => s?.trim());
        if (!phone || !apikey) {
          results.push({ to: entry, ok: false, detail: 'Expected format phone:apikey (e.g. 447700900001:123456)' });
          continue;
        }
        try {
          const url = `https://api.callmebot.com/whatsapp.php?phone=${encodeURIComponent(phone)}&apikey=${encodeURIComponent(apikey)}&text=${encodeURIComponent(text)}`;
          const res = await fetch(url);
          const body = await res.text();
          // CallMeBot returns 200 even for some errors — check the body
          const failed = !res.ok || /error|invalid|not registered/i.test(body);
          results.push({ to: phone, ok: !failed, status: res.status, detail: failed ? body.slice(0, 300) : undefined });
        } catch (err) {
          results.push({ to: phone, ok: false, detail: err?.message || 'fetch failed' });
        }
      }
    }

    const sent = results.filter(r => r.ok).length;
    return Response.json({ ok: sent > 0, sent, total: results.length, provider, results }, { headers: cors });
  } catch (error) {
    return Response.json({ error: error?.message || 'Failed to send WhatsApp alert' }, { status: 500, headers: cors });
  }
});

