import { createClientFromRequest } from 'npm:@base44/sdk@0.8.31';

Deno.serve(async (req) => {
  try {
    const base44 = createClientFromRequest(req);
    const { token, signature_image, action } = await req.json();

    if (!token) return Response.json({ error: 'Token required' }, { status: 400 });

    const records = await base44.asServiceRole.entities.SignatureRequest.filter({ token });

    if (!records || records.length === 0) {
      return Response.json({ error: 'Invalid link' }, { status: 404 });
    }

    const record = records[0];

    if (record.status !== 'pending') {
      return Response.json({ error: 'This document has already been actioned' }, { status: 409 });
    }

    if (action === 'decline') {
      await base44.asServiceRole.entities.SignatureRequest.update(record.id, {
        status: 'declined',
        signed_at: new Date().toISOString(),
      });
      return Response.json({ success: true, status: 'declined' });
    }

    if (!signature_image) {
      return Response.json({ error: 'Signature required' }, { status: 400 });
    }

    await base44.asServiceRole.entities.SignatureRequest.update(record.id, {
      status: 'signed',
      signed_at: new Date().toISOString(),
      signature_image,
    });

    // Notify the sender
    if (record.sent_by) {
      await base44.asServiceRole.integrations.Core.SendEmail({
        to: record.sent_by,
        subject: `✅ Signed: ${record.title}`,
        body: `<p>${record.recipient_name} has signed the document "<strong>${record.title}</strong>".</p><p>Signed at: ${new Date().toLocaleString()}</p>`,
      });
    }

    return Response.json({ success: true, status: 'signed' });
  } catch (error) {
    return Response.json({ error: error.message }, { status: 500 });
  }
});

import { createClientFromRequest } from 'npm:@base44/sdk@0.8.25';

const SHEET_ID = '14MhAZom4rNzGAC-wLwPc4G4cmcJWoHF1XXBSKD374Vw';
const SHEET_NAME = 'Sheet1';

// Month columns based on the screenshot: Jan=E, Feb=F, Mar=G, Apr=H, May=I, Jun=J, Jul=K, Aug=L, Sep=M, Oct=N, Nov=O, Dec=P
const MONTH_COLUMNS = {
  '01': 'E', '02': 'F', '03': 'G', '04': 'H',
  '05': 'I', '06': 'J', '07': 'K', '08': 'L',
  '09': 'M', '10': 'N', '11': 'O', '12': 'P',
};

Deno.serve(async (req) => {
  try {
    const base44 = createClientFromRequest(req);
    const body = await req.json();

    // Accept both direct calls and automation payloads
    const eventType = body.event?.type || body.action; // 'create' or 'delete'
    const payment = body.data || body.payment;

    if (!payment || !eventType) {
      return Response.json({ error: 'Missing payment data or event type' }, { status: 400 });
    }

    // Get property address
    let propertyAddress = payment.property_address;
    if (!propertyAddress && payment.property_id) {
      const props = await base44.asServiceRole.entities.Property.filter({ id: payment.property_id });
      propertyAddress = props[0]?.address || '';
    }

    if (!propertyAddress) {
      return Response.json({ error: 'Could not resolve property address' }, { status: 400 });
    }

    // Get period month (YYYY-MM)
    const periodMonth = payment.period_month || payment.payment_date?.substring(0, 7);
    if (!periodMonth) {
      return Response.json({ error: 'Missing period_month' }, { status: 400 });
    }

    const monthNum = periodMonth.substring(5, 7); // e.g. "06"
    const col = MONTH_COLUMNS[monthNum];
    if (!col) {
      return Response.json({ error: `No column mapped for month ${monthNum}` }, { status: 400 });
    }

    // Get Google Sheets access token
    const { accessToken } = await base44.asServiceRole.connectors.getConnection('googlesheets');

    // Fetch all rows from column B to find the matching property row
    const rangeB = `${SHEET_NAME}!B:B`;
    const fetchRes = await fetch(
      `https://sheets.googleapis.com/v4/spreadsheets/${SHEET_ID}/values/${encodeURIComponent(rangeB)}`,
      { headers: { Authorization: `Bearer ${accessToken}` } }
    );
    const fetchData = await fetchRes.json();
    const rows = fetchData.values || [];

    // Extract postcode and house number from an address string
    const extractPostcode = (addr) => {
      const match = addr.match(/[A-Z]{1,2}\d{1,2}[A-Z]?\s?\d[A-Z]{2}/i);
      return match ? match[0].replace(/\s/g, '').toLowerCase() : '';
    };
    const extractHouseNumber = (addr) => {
      const match = addr.trim().match(/^(\d+[A-Za-z]?)/);
      return match ? match[1].toLowerCase() : '';
    };

    // Find row index (1-based for Sheets API) where column B matches the property address
    let matchedRow = -1;
    const addressLower = propertyAddress.toLowerCase().trim();
    const sysPostcode = extractPostcode(propertyAddress);
    const sysHouseNum = extractHouseNumber(propertyAddress);

    for (let i = 0; i < rows.length; i++) {
      const cellVal = (rows[i][0] || '').toLowerCase().trim();
      if (!cellVal) continue;

      // 1. Exact / substring match
      if (addressLower.includes(cellVal) || cellVal.includes(addressLower)) {
        matchedRow = i + 1;
        break;
      }

      // 2. House number + postcode match (handles abbreviated street names)
      if (sysPostcode && sysHouseNum) {
        const cellPostcode = extractPostcode(cellVal);
        const cellHouseNum = extractHouseNumber(cellVal);
        if (cellPostcode && cellHouseNum && cellPostcode === sysPostcode && cellHouseNum === sysHouseNum) {
          matchedRow = i + 1;
          break;
        }
      }
    }

    if (matchedRow === -1) {
      return Response.json({
        warning: `No matching row found for address: ${propertyAddress}`,
        searched: rows.length,
      });
    }

    // Determine the value to write
    // On create: write the bank name or payment method. On delete: clear it.
    let cellValue = '';
    if (eventType === 'create') {
      cellValue = payment.received_in_bank_name || payment.method || 'paid';
    }
    // on delete: leave as empty string to clear

    // Update the cell
    const range = `${SHEET_NAME}!${col}${matchedRow}`;
    const updateRes = await fetch(
      `https://sheets.googleapis.com/v4/spreadsheets/${SHEET_ID}/values/${encodeURIComponent(range)}?valueInputOption=RAW`,
      {
        method: 'PUT',
        headers: {
          Authorization: `Bearer ${accessToken}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ values: [[cellValue]] }),
      }
    );
    const updateData = await updateRes.json();

    return Response.json({
      success: true,
      action: eventType,
      row: matchedRow,
      cell: range,
      value: cellValue,
      address: propertyAddress,
      sheetsResponse: updateData,
    });
  } catch (error) {
    return Response.json({ error: error.message }, { status: 500 });
  }
});

