function endOfDay(d: Date) { const x = new Date(d); x.setHours(23, 59, 59, 999); return x; }

Deno.serve(async (req) => {
  try {
    const base44 = createClientFromRequest(req);

    const tenants = await base44.asServiceRole.entities.Tenant.list('', 5000);
    const now = new Date();
    let toEnded = 0, toActive = 0;
    const changes: any[] = [];

    for (const t of (tenants || [])) {
      const end = t.lease_end ? new Date(t.lease_end) : null;
      const validEnd = end && !isNaN(end.getTime()) ? end : null;

      let target = t.status;
      if (validEnd && endOfDay(validEnd) < now) {
        target = 'ended';
      } else if (t.status === 'ended') {
        // no end date or future end → reinstate
        target = 'active';
      }

      if (target !== t.status && (t.status === 'active' || t.status === 'ended' || target === 'ended')) {
        // Only auto-toggle between active/ended; never touch 'notice'.
        if (t.status === 'notice') continue;
        await base44.asServiceRole.entities.Tenant.update(t.id, { status: target });
        if (target === 'ended') toEnded++; else toActive++;
        changes.push({ id: t.id, name: t.name, from: t.status, to: target, lease_end: t.lease_end || null });
      }
    }

    return Response.json({ ok: true, checked: (tenants || []).length, set_ended: toEnded, set_active: toActive, changes });
  } catch (error) {
    console.error('syncTenantStatus error:', error);
    return Response.json({ error: (error as Error)?.message || 'Failed to sync tenant statuses' }, { status: 500 });
  }
});

