import { createClientFromRequest } from 'npm:@base44/sdk@0.8.31';

// ─────────────────────────────────────────────────────────────────────
// DAILY TASK REMINDERS
//
// Runs on a schedule and emails ONE summary of every task whose "check again"
// date (remind_at) has arrived (today or earlier) and which isn't done yet.
// After emailing, it stamps reminder_sent_at so the same reminder isn't sent
// again on subsequent days (unless remind_at is later moved forward).
//
// SETUP (mostly already done — same secrets as dailyExpiryDigest):
//   RESEND_API_KEY, RESEND_FROM_EMAIL  – already set
//   EXPIRY_DIGEST_TO                   – reused as the reminder recipient,
//                                        or set TASK_REMINDER_TO to override
//   Schedule: this function runs daily via function.jsonc cron.
//
// POST { "to": "x@y.com" } to test manually with a custom recipient.
// ─────────────────────────────────────────────────────────────────────

const TYPE_LABELS = {
  general: 'General',
  rent_increase: 'Rent Increase',
  gas_safety: 'Gas Safety',
  certificate: 'Certificate',
  deposit_return: 'Deposit Return',
  eviction_notice: 'Eviction Notice',
  inspection: 'Inspection',
  maintenance: 'Maintenance',
};

// Last step of each type = "done" (kept in sync with src/lib/taskConfig.js).
const DONE_STEP = {
  general: 'Done',
  rent_increase: 'Effective',
  gas_safety: 'Uploaded',
  certificate: 'Uploaded',
  deposit_return: 'Confirmed',
  eviction_notice: 'Resolved',
  inspection: 'Report Filed',
  maintenance: 'Fixed',
};

function fmtDate(d) {
  return d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
}

Deno.serve(async (req) => {
  try {
    const base44 = createClientFromRequest(req);

    let overrideTo = null;
    try { if (req.method === 'POST') { const b = await req.json(); overrideTo = b?.to || null; } } catch { /* no body */ }

    const recipient = overrideTo || Deno.env.get('TASK_REMINDER_TO') || Deno.env.get('EXPIRY_DIGEST_TO');
    if (!recipient) {
      return Response.json({ error: 'No recipient. Set TASK_REMINDER_TO (or EXPIRY_DIGEST_TO) in Settings → Environment Variables.' }, { status: 500 });
    }

    const [tasks, properties, tenants] = await Promise.all([
      base44.asServiceRole.entities.Task.list('-created_date', 5000),
      base44.asServiceRole.entities.Property.list('', 5000),
      base44.asServiceRole.entities.Tenant.list('', 5000),
    ]);
    const propById = {}; (properties || []).forEach(p => { propById[p.id] = p; });
    const tenantById = {}; (tenants || []).forEach(t => { tenantById[t.id] = t; });

    const today = new Date(); today.setHours(0, 0, 0, 0);
    const todayStr = today.toISOString().slice(0, 10);

    // Due reminders: remind_at set and <= today, task not done, and not already
    // reminded for this remind_at date.
    const due = (tasks || []).filter(t => {
      if (!t.remind_at) return false;
      if (t.remind_at > todayStr) return false;
      if ((t.status || '') === DONE_STEP[t.type]) return false;
      // Skip if we already sent a reminder on/after the remind_at date.
      if (t.reminder_sent_at && t.reminder_sent_at.slice(0, 10) >= t.remind_at) return false;
      return true;
    });

    if (due.length === 0) {
      return Response.json({ ok: true, reminders: 0, message: 'No task reminders due today.' });
    }

    // Sort by how overdue the reminder is (oldest remind_at first).
    due.sort((a, b) => (a.remind_at || '').localeCompare(b.remind_at || ''));

    const rowHtml = (t) => {
      const prop = t.property_id ? propById[t.property_id] : null;
      const tenant = t.tenant_id ? tenantById[t.tenant_id] : null;
      const linked = prop?.address || tenant?.name || '—';
      const remindDate = new Date(t.remind_at); remindDate.setHours(0, 0, 0, 0);
      const overdueDays = Math.round((today.getTime() - remindDate.getTime()) / 86400000);
      const when = overdueDays === 0 ? 'Today' : `${overdueDays} day${overdueDays === 1 ? '' : 's'} ago`;
      return `<tr>
        <td style="padding:8px 12px;border-bottom:1px solid #eee;font-weight:600;">${t.title || 'Task'}</td>
        <td style="padding:8px 12px;border-bottom:1px solid #eee;">${TYPE_LABELS[t.type] || t.type}</td>
        <td style="padding:8px 12px;border-bottom:1px solid #eee;">${linked}</td>
        <td style="padding:8px 12px;border-bottom:1px solid #eee;">${t.status || '—'}</td>
        <td style="padding:8px 12px;border-bottom:1px solid #eee;">${t.assigned_to || '—'}</td>
        <td style="padding:8px 12px;border-bottom:1px solid #eee;white-space:nowrap;">${when}</td>
        ${t.reminder_note ? `<td style="padding:8px 12px;border-bottom:1px solid #eee;font-style:italic;color:#555;">${t.reminder_note}</td>` : '<td style="padding:8px 12px;border-bottom:1px solid #eee;">—</td>'}
      </tr>`;
    };

    const html = `<div style="font-family:Arial,sans-serif;max-width:760px;margin:0 auto;color:#111;">
      <h2 style="color:#16205c;margin-bottom:4px;">Task reminders — ${fmtDate(today)}</h2>
      <p style="color:#555;margin-top:0;">${due.length} task${due.length === 1 ? '' : 's'} flagged to check again.</p>
      <table style="border-collapse:collapse;width:100%;font-size:14px;">
        <thead><tr style="text-align:left;color:#666;">
          <th style="padding:8px 12px;border-bottom:2px solid #ddd;">Task</th>
          <th style="padding:8px 12px;border-bottom:2px solid #ddd;">Type</th>
          <th style="padding:8px 12px;border-bottom:2px solid #ddd;">Linked to</th>
          <th style="padding:8px 12px;border-bottom:2px solid #ddd;">Status</th>
          <th style="padding:8px 12px;border-bottom:2px solid #ddd;">Assignee</th>
          <th style="padding:8px 12px;border-bottom:2px solid #ddd;">Reminder</th>
          <th style="padding:8px 12px;border-bottom:2px solid #ddd;">Note</th>
        </tr></thead>
        <tbody>${due.map(rowHtml).join('')}</tbody>
      </table>
      <p style="color:#999;font-size:12px;margin-top:28px;">Automated task reminders from ASA Estates. Set a task's "check again" date to appear here.</p>
    </div>`;

    const apiKey = Deno.env.get('RESEND_API_KEY');
    if (!apiKey) return Response.json({ error: 'RESEND_API_KEY is not set.' }, { status: 500 });
    const fromEmail = Deno.env.get('RESEND_FROM_EMAIL') || 'info@asaestates.com';

    const sendRes = await fetch('https://api.resend.com/emails', {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        from: `ASA Estates Ltd <${fromEmail}>`,
        to: recipient,
        subject: `🔔 ${due.length} task reminder${due.length === 1 ? '' : 's'} — ${fmtDate(today)}`,
        html,
      }),
    });

    if (!sendRes.ok) {
      const detail = await sendRes.text();
      return Response.json({ error: `Resend error: ${sendRes.status} — ${detail}` }, { status: 502 });
    }

    // Stamp reminder_sent_at so we don't re-send the same reminders tomorrow.
    const nowIso = new Date().toISOString();
    await Promise.all(due.map(t =>
      base44.asServiceRole.entities.Task.update(t.id, { reminder_sent_at: nowIso }).catch(() => {})
    ));

    return Response.json({ ok: true, reminders: due.length, sent_to: recipient });
  } catch (error) {
    console.error('taskReminders error:', error);
    return Response.json({ error: error?.message || 'Failed to send task reminders' }, { status: 500 });
  }
});

