import { createClientFromRequest } from 'npm:@base44/sdk@0.8.25';

const SHEET_ID = '14MhAZom4rNzGAC-wLwPc4G4cmcJWoHF1XXBSKD374Vw';
const SHEET_NAME = 'Sheet1';

Deno.serve(async (req) => {
  try {
    const base44 = createClientFromRequest(req);
    const user = await base44.auth.me();
    if (!user || user.role !== 'admin') {
      return Response.json({ error: 'Forbidden' }, { status: 403 });
    }

    // Get Google Sheets access token
    const { accessToken } = await base44.asServiceRole.connectors.getConnection('googlesheets');

    // Fetch current Column B to see how many rows there are
    const rangeB = `${SHEET_NAME}!B:B`;
    const fetchRes = await fetch(
      `https://sheets.googleapis.com/v4/spreadsheets/${SHEET_ID}/values/${encodeURIComponent(rangeB)}`,
      { headers: { Authorization: `Bearer ${accessToken}` } }
    );
    const fetchData = await fetchRes.json();
    const existingRows = fetchData.values || [];
    const totalRows = existingRows.length;

    if (totalRows === 0) {
      return Response.json({ error: 'Sheet appears empty' }, { status: 400 });
    }

    // Fetch all properties from the system
    const properties = await base44.asServiceRole.entities.Property.list();
    const addresses = properties.map(p => p.address).filter(Boolean);

    // Build an update: replace each row in column B (skip row 1 = header) with system addresses
    // We'll match by row position: row 2 = first property, row 3 = second, etc.
    // Instead, we write addresses into B2:B(N) in order
    const values = addresses.map(addr => [addr]);

    const startRow = 2; // row 1 is header
    const endRow = startRow + values.length - 1;
    const updateRange = `${SHEET_NAME}!B${startRow}:B${endRow}`;

    const updateRes = await fetch(
      `https://sheets.googleapis.com/v4/spreadsheets/${SHEET_ID}/values/${encodeURIComponent(updateRange)}?valueInputOption=RAW`,
      {
        method: 'PUT',
        headers: {
          Authorization: `Bearer ${accessToken}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ values }),
      }
    );
    const updateData = await updateRes.json();

    return Response.json({
      success: true,
      updated: addresses.length,
      addresses,
      sheetsResponse: updateData,
    });
  } catch (error) {
    return Response.json({ error: error.message }, { status: 500 });
  }
});

import { createClientFromRequest } from 'npm:@base44/sdk@0.8.31';

Deno.serve(async (req) => {
  try {
    const base44 = createClientFromRequest(req);
    const { token, action, fieldValues, ip_address, user_agent } = await req.json();

    if (!token) {
      return Response.json({ error: 'Token required' }, { status: 400 });
    }

    // Find signer by access token
    const signers = await base44.asServiceRole.entities.Signer.filter({ access_token: token });
    if (signers.length === 0) {
      return Response.json({ error: 'Invalid or expired link' }, { status: 404 });
    }

    const signer = signers[0];

    // Get document
    const document = await base44.asServiceRole.entities.Document.get(signer.document_id);
    if (!document || document.status === 'voided' || document.status === 'completed') {
      return Response.json({ error: 'This document is no longer available for signing' }, { status: 400 });
    }

    if (signer.status === 'signed') {
      return Response.json({ error: 'You have already signed this document' }, { status: 400 });
    }

    // Resend email helper
    const resendKey = Deno.env.get('RESEND_API_KEY');
    const fromEmail = Deno.env.get('RESEND_FROM_EMAIL') || 'onboarding@resend.dev';
    const sendResendEmail = async (to, subject, html) => {
      if (!resendKey) return;
      try {
        await fetch('https://api.resend.com/emails', {
          method: 'POST',
          headers: { 'Authorization': `Bearer ${resendKey}`, 'Content-Type': 'application/json' },
          body: JSON.stringify({ from: `ASA Estates <${fromEmail}>`, to, subject, html }),
        });
      } catch (e) { console.error('Email send failed:', e.message); }
    };

    // Action: view - load data
    if (action === 'view') {
      // Get fields for this signer
      const fields = await base44.asServiceRole.entities.SignatureField.filter({
        document_id: signer.document_id,
        signer_id: signer.id,
      });

      // Mark as viewed if not already
      if (signer.status === 'pending') {
        await base44.asServiceRole.entities.Signer.update(signer.id, {
          status: 'viewed',
          viewed_at: new Date().toISOString(),
          ip_address: ip_address || '',
          user_agent: user_agent || '',
        });

        await base44.asServiceRole.entities.AuditEvent.create({
          document_id: signer.document_id,
          signer_id: signer.id,
          event_type: 'viewed',
          ip_address: ip_address || '',
          user_agent: user_agent || '',
        });

        // Update document status
        if (document.status === 'sent') {
          await base44.asServiceRole.entities.Document.update(document.id, { status: 'viewed' });
        }
      }

      return Response.json({
        signer: { id: signer.id, name: signer.name, email: signer.email, role_label: signer.role_label },
        document: { id: document.id, title: document.title, original_file_url: document.original_file_url, page_count: document.page_count },
        fields,
      });
    }

    // Action: sign - complete the signing
    if (action === 'sign') {
      // Update field values
      if (fieldValues && typeof fieldValues === 'object') {
        for (const [fieldId, value] of Object.entries(fieldValues)) {
          await base44.asServiceRole.entities.SignatureField.update(fieldId, { value });

          await base44.asServiceRole.entities.AuditEvent.create({
            document_id: signer.document_id,
            signer_id: signer.id,
            event_type: 'field_completed',
            ip_address: ip_address || '',
            user_agent: user_agent || '',
            metadata: JSON.stringify({ field_id: fieldId }),
          });
        }
      }

      // Mark signer as signed
      await base44.asServiceRole.entities.Signer.update(signer.id, {
        status: 'signed',
        signed_at: new Date().toISOString(),
        ip_address: ip_address || '',
        user_agent: user_agent || '',
      });

      await base44.asServiceRole.entities.AuditEvent.create({
        document_id: signer.document_id,
        signer_id: signer.id,
        event_type: 'signed',
        ip_address: ip_address || '',
        user_agent: user_agent || '',
      });

      // Check if all signers are done
      const allSigners = await base44.asServiceRole.entities.Signer.filter({ document_id: signer.document_id });
      const allSigned = allSigners.every((s) => s.status === 'signed');

      if (allSigned) {
        // Flatten signatures onto the original PDF
        let signedUrl = null;
        try {
          const signedRes = await base44.asServiceRole.functions.invoke('flattenSignedDocument', { documentId: document.id });
          signedUrl = signedRes?.file_url || signedRes?.data?.file_url || null;
        } catch (flattenErr) {
          console.error('Flatten failed:', flattenErr.message);
        }

        // Generate the completion certificate PDF
        let certificateUrl = null;
        try {
          const certRes = await base44.asServiceRole.functions.invoke('generateCompletionCertificate', { documentId: document.id });
          certificateUrl = certRes?.file_url || certRes?.data?.file_url || null;
        } catch (certErr) {
          console.error('Certificate generation failed:', certErr.message);
        }

        await base44.asServiceRole.entities.Document.update(document.id, {
          status: 'completed',
          completed_at: new Date().toISOString(),
          signed_file_url: signedUrl,
          final_file_url: certificateUrl,
        });

        await base44.asServiceRole.entities.AuditEvent.create({
          document_id: signer.document_id,
          event_type: 'completed',
        });

        if (!signedUrl && !certificateUrl) {
          console.error(`Both flatten and certificate generation failed for document ${document.id} — completion emails withheld to avoid sending a broken link.`);
        } else {

        // Email all parties completion notice with download links for BOTH the
        // fully-signed document (with every signature + the appended audit trail
        // pages) and the certificate of completion. Previously only the
        // certificate was linked here, so signees never received the actual
        // signed contract — just its audit summary.
        for (const s of allSigners) {
          await sendResendEmail(
            s.email,
            `Completed: ${document.title}`,
            `<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;">
              <h2 style="color: #059669;">Document Completed</h2>
              <p>Hello ${s.name},</p>
              <p>All parties have signed <strong>${document.title}</strong>.</p>
              <p>You can download the fully signed document below. It includes every signature and the full audit trail as extra pages at the end.</p>
              ${signedUrl ? `<a href="${signedUrl}" style="display: inline-block; background: #2563eb; color: white; padding: 12px 24px; border-radius: 8px; text-decoration: none; font-weight: 600; margin-top: 8px;">Download Signed Document (PDF)</a>` : ''}
              <br/>
              ${certificateUrl ? `<a href="${certificateUrl}" style="display: inline-block; background: #059669; color: white; padding: 12px 24px; border-radius: 8px; text-decoration: none; font-weight: 600; margin-top: 12px;">Download Certificate of Completion (PDF)</a>` : ''}
            </div>`
          );
        }
        }

        return Response.json({ success: true, completed: true, signed_file_url: signedUrl, final_file_url: certificateUrl });
      } else {
        // Update document to partially signed
        const signedCount = allSigners.filter((s) => s.status === 'signed').length;
        if (signedCount > 0 && signedCount < allSigners.length) {
          await base44.asServiceRole.entities.Document.update(document.id, { status: 'partially_signed' });
        }

        // Check for sequential signing — notify next signer
        const sortedSigners = allSigners.sort((a, b) => (a.signing_order || 1) - (b.signing_order || 1));
        const nextPending = sortedSigners.find((s) => s.status === 'pending');
        if (nextPending) {
          const origin = req.headers.get('origin') || 'https://app.base44.com';
          const signingUrl = `${origin}/sign/${nextPending.access_token}`;
          await sendResendEmail(
            nextPending.email,
            `Please sign: ${document.title}`,
            `<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;">
              <h2 style="color: #1e40af;">Your Turn to Sign</h2>
              <p>Hello ${nextPending.name},</p>
              <p>It's your turn to sign <strong>${document.title}</strong>.</p>
              <a href="${signingUrl}" style="display: inline-block; background: #2563eb; color: white; padding: 12px 24px; border-radius: 8px; text-decoration: none; font-weight: 600; margin-top: 16px;">
                Review & Sign Document
              </a>
            </div>`
          );
        }
      }

      return Response.json({ success: true, completed: allSigned });
    }

    // Action: decline
    if (action === 'decline') {
      await base44.asServiceRole.entities.Signer.update(signer.id, { status: 'declined' });
      await base44.asServiceRole.entities.Document.update(document.id, { status: 'declined' });
      await base44.asServiceRole.entities.AuditEvent.create({
        document_id: signer.document_id,
        signer_id: signer.id,
        event_type: 'declined',
        ip_address: ip_address || '',
        user_agent: user_agent || '',
      });
      return Response.json({ success: true });
    }

    return Response.json({ error: 'Invalid action' }, { status: 400 });
  } catch (error) {
    return Response.json({ error: error.message }, { status: 500 });
  }
});

