const DefaultFallback = () => (
  <div className="fixed inset-0 flex items-center justify-center">
    <div className="w-8 h-8 border-4 border-slate-200 border-t-slate-800 rounded-full animate-spin"></div>
  </div>
);

export default function ProtectedRoute({ fallback = <DefaultFallback />, unauthenticatedElement }) {
  const { isAuthenticated, isLoadingAuth, authError } = useAuth();

  if (isLoadingAuth) {
    return fallback;
  }

  if (authError) {
    if (authError.type === 'user_not_registered') {
      return <UserNotRegisteredError />;
    }
    // auth_required or other errors = treat as unauthenticated
    return unauthenticatedElement;
  }

  if (!isAuthenticated) {
    return unauthenticatedElement;
  }

  return <Outlet />;
}

import React, { useEffect, useState } from 'react';
import { base44 } from '@/api/base44Client';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { buildBackupZip } from '@/lib/backupZip';
import { saveAs } from 'file-saver';
import { format } from 'date-fns';
import { CalendarClock, Download, FolderArchive, Loader2 } from 'lucide-react';

const XLSX_MIME = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';

const mimeFor = (name) =>
  name.endsWith('.json') ? 'application/json'
  : name.endsWith('.xlsx') ? XLSX_MIME
  : 'application/octet-stream';

const fmtSize = (bytes) => {
  const n = Number(bytes) || 0;
  if (n < 1024 * 1024) return `${Math.max(1, Math.round(n / 1024))} KB`;
  return `${(n / (1024 * 1024)).toFixed(1)} MB`;
};

function b64ToBytes(b64) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

export default function MonthlyDriveDownloads() {
  const [months, setMonths] = useState(null);   // [{ month, files }]
  const [selected, setSelected] = useState(null); // month key
  const [busyFile, setBusyFile] = useState(null); // file id being downloaded
  const [downloadingAll, setDownloadingAll] = useState(false);
  const [buildingZip, setBuildingZip] = useState(false);
  const [zipDone, setZipDone] = useState(null);   // { month, total }
  const [error, setError] = useState(null);

  useEffect(() => {
    let mounted = true;
    base44.functions.invoke('driveBackupFiles', { action: 'list' })
      .then((res) => {
        if (!mounted) return;
        const list = res.data?.months || [];
        setMonths(list);
        if (list.length > 0) setSelected(list[0].month);
      })
      .catch((e) => mounted && setError(e?.response?.data?.error || e?.message || 'Could not load backups'));
    return () => { mounted = false; };
  }, []);

  const current = months?.find((m) => m.month === selected);

  const fetchJsonBackup = async () => {
    const jsonFile = current?.files.find((f) => f.name.endsWith('.json'));
    if (!jsonFile) throw new Error('No JSON backup found for this month');
    const res = await base44.functions.invoke('driveBackupFiles', { action: 'download', fileId: jsonFile.id });
    const parsed = JSON.parse(new TextDecoder().decode(b64ToBytes(res.data.base64)));
    return parsed.entities || parsed;
  };

  const downloadMonthZip = async () => {
    if (!current) return;
    setBuildingZip(true); setError(null); setZipDone(null);
    try {
      const data = await fetchJsonBackup();
      const { blob, totalRecords } = await buildBackupZip(data, {
        monthKey: current.month,
        dateStamp: format(new Date(), 'yyyy-MM-dd'),
      });
      saveAs(blob, `ASA-Estates-Backup-${current.month}.zip`);
      setZipDone({ month: current.month, total: totalRecords });
    } catch (e) {
      setError(e?.response?.data?.error || e?.message || 'Could not build the backup ZIP');
    } finally {
      setBuildingZip(false);
    }
  };

  const downloadFile = async (file) => {
    setBusyFile(file.id);
    setError(null);
    try {
      const res = await base44.functions.invoke('driveBackupFiles', { action: 'download', fileId: file.id });
      saveAs(new Blob([b64ToBytes(res.data.base64)], { type: mimeFor(file.name) }), file.name);
    } catch (e) {
      setError(e?.response?.data?.error || e?.message || 'Download failed');
    } finally {
      setBusyFile(null);
    }
  };

  const downloadAll = async () => {
    if (!current) return;
    setDownloadingAll(true);
    setError(null);
    try {
      for (const file of current.files) {
        const res = await base44.functions.invoke('driveBackupFiles', { action: 'download', fileId: file.id });
        saveAs(new Blob([b64ToBytes(res.data.base64)], { type: mimeFor(file.name) }), file.name);
      }
    } catch (e) {
      setError(e?.response?.data?.error || e?.message || 'Download failed');
    } finally {
      setDownloadingAll(false);
    }
  };

  if (error && !months) {
    return (
      <div className="mt-4 bg-card border border-border rounded-xl p-6 text-sm text-muted-foreground">
        Could not load Drive backups: {error}
      </div>
    );
  }
  if (!months) {
    return (
      <div className="mt-4 bg-card border border-border rounded-xl p-6 flex items-center gap-2 text-sm text-muted-foreground">
        <Loader2 className="w-4 h-4 animate-spin" /> Loading monthly backups…
      </div>
    );
  }

  return (
    <div className="mt-4 bg-card border border-border rounded-xl p-6">
      <div className="flex items-start gap-4">
        <div className="w-12 h-12 rounded-xl bg-primary/10 flex items-center justify-center flex-shrink-0">
          <CalendarClock className="w-6 h-6 text-primary" />
        </div>
        <div className="flex-1">
          <h2 className="font-semibold text-lg">Download a previous month&rsquo;s backup</h2>
          <p className="text-sm text-muted-foreground mt-1 leading-relaxed">
            Pick any month stored in your Google Drive backup folder and download the same organised ZIP
            as &ldquo;Back up now&rdquo; &mdash; every data set as a formatted Excel file (plus CSV), a master
            workbook, a branded summary, and a raw-JSON copy for restore. You can also grab individual files.
          </p>

          {months.length === 0 ? (
            <p className="mt-4 text-sm text-muted-foreground">No monthly backups in Drive yet.</p>
          ) : (
            <>
              <div className="mt-4 flex items-center gap-3 flex-wrap">
                <Select value={selected} onValueChange={(v) => { setSelected(v); setZipDone(null); }}>
                  <SelectTrigger className="w-48">
                    <SelectValue placeholder="Choose month" />
                  </SelectTrigger>
                  <SelectContent>
                    {months.map((m) => (
                      <SelectItem key={m.month} value={m.month}>{m.month}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <Button onClick={downloadMonthZip} disabled={buildingZip}>
                  {buildingZip
                    ? <><Loader2 className="w-4 h-4 mr-2 animate-spin" /> Building ZIP&hellip;</>
                    : <><FolderArchive className="w-4 h-4 mr-2" /> Download full backup ZIP</>}
                </Button>
                {current && current.files.length > 0 && (
                  <Button variant="outline" onClick={downloadAll} disabled={downloadingAll || buildingZip || busyFile}>
                    {downloadingAll ? <><Loader2 className="w-4 h-4 mr-2 animate-spin" /> Downloading…</>
                                     : <><Download className="w-4 h-4 mr-2" /> Download all files</>}
                  </Button>
                )}
              </div>

              {zipDone && (
                <p className="mt-3 text-sm text-emerald-700">
                  Backup for <strong>{zipDone.month}</strong> downloaded &mdash; {zipDone.total} records.
                </p>
              )}

              {current && (
                <div className="mt-4 border border-border rounded-lg divide-y divide-border">
                  {current.files.map((f) => (
                    <div key={f.id} className="flex items-center justify-between gap-3 px-4 py-2.5">
                      <div className="min-w-0">
                        <p className="text-sm font-medium truncate">{f.name}</p>
                        <p className="text-xs text-muted-foreground">{fmtSize(f.size)}</p>
                      </div>
                      <Button variant="ghost" size="sm" onClick={() => downloadFile(f)} disabled={busyFile === f.id || downloadingAll || buildingZip}>
                        {busyFile === f.id ? <Loader2 className="w-4 h-4 animate-spin" />
                                           : <><Download className="w-4 h-4" /> Download</>}
                      </Button>
                    </div>
                  ))}
                </div>
              )}

              {error && <p className="mt-3 text-sm text-destructive">{error}</p>}
            </>
          )}
        </div>
      </div>
    </div>
  );
}

