import React, { useState, useRef, useEffect } from "react";
import { Trash2, Move, PenTool, Type, Calendar, Hash, CheckSquare, User } from "lucide-react";
import { getSignerColor } from "@/lib/signerColors";

const FIELD_ICONS = {
  signature: PenTool,
  initials: Type,
  name: User,
  date: Calendar,
  text: Hash,
  checkbox: CheckSquare,
};

const DEFAULT_SIZES = {
  signature: { width: 0.2, height: 0.05 },
  initials: { width: 0.08, height: 0.04 },
  name: { width: 0.2, height: 0.035 },
  date: { width: 0.12, height: 0.035 },
  text: { width: 0.2, height: 0.035 },
  checkbox: { width: 0.025, height: 0.025 },
};

export default function PDFFieldCanvas({
  pageNumber,
  fields,
  signers,
  onUpdateField,
  onDeleteField,
  containerRef,
}) {
  const [dragging, setDragging] = useState(null);
  const [resizing, setResizing] = useState(null);
  const dragOffset = useRef({ x: 0, y: 0 });

  const pageFields = fields.filter((f) => f.page === pageNumber);

  const getContainerRect = () => containerRef?.current?.getBoundingClientRect();

  const handleMouseDown = (e, field) => {
    e.stopPropagation();
    e.preventDefault();
    const rect = getContainerRect();
    if (!rect) return;
    dragOffset.current = {
      x: e.clientX - field.x * rect.width,
      y: e.clientY - field.y * rect.height,
    };
    setDragging(field._tempId);
  };

  const handleResizeDown = (e, field) => {
    e.stopPropagation();
    e.preventDefault();
    setResizing(field._tempId);
  };

  useEffect(() => {
    const handleMouseMove = (e) => {
      const rect = getContainerRect();
      if (!rect) return;

      if (dragging) {
        const x = Math.max(0, Math.min(1, (e.clientX - dragOffset.current.x) / rect.width));
        const y = Math.max(0, Math.min(1, (e.clientY - dragOffset.current.y) / rect.height));
        onUpdateField(dragging, { x, y });
      }

      if (resizing) {
        const field = fields.find((f) => f._tempId === resizing);
        if (!field) return;
        const w = Math.max(0.04, Math.min(0.5, (e.clientX - rect.left) / rect.width - field.x));
        const h = Math.max(0.02, Math.min(0.2, (e.clientY - rect.top) / rect.height - field.y));
        onUpdateField(resizing, { width: w, height: h });
      }
    };

    const handleMouseUp = () => {
      setDragging(null);
      setResizing(null);
    };

    if (dragging || resizing) {
      window.addEventListener("mousemove", handleMouseMove);
      window.addEventListener("mouseup", handleMouseUp);
      return () => {
        window.removeEventListener("mousemove", handleMouseMove);
        window.removeEventListener("mouseup", handleMouseUp);
      };
    }
  }, [dragging, resizing]);

  return (
    <>
      {pageFields.map((field) => {
        const signerIndex = signers.findIndex((s, i) => i === field._signerIndex);
        const color = getSignerColor(signerIndex >= 0 ? signerIndex : 0);
        const Icon = FIELD_ICONS[field.type] || Hash;
        const isDragging = dragging === field._tempId;

        return (
          <div
            key={field._tempId}
            className={`absolute group cursor-move flex items-center gap-1 px-1.5 border-2 rounded select-none ${
              isDragging ? "opacity-70 z-50" : "z-10"
            }`}
            style={{
              left: `${field.x * 100}%`,
              top: `${field.y * 100}%`,
              width: `${field.width * 100}%`,
              height: `${field.height * 100}%`,
              borderColor: color.hex,
              backgroundColor: color.light + "cc",
            }}
            onMouseDown={(e) => handleMouseDown(e, field)}
          >
            <Icon className="w-3 h-3 shrink-0" style={{ color: color.hex }} />
            <span className="text-[10px] font-medium truncate" style={{ color: color.hex }}>
              {field.type}
            </span>

            <button
              className="absolute -top-2 -right-2 w-4 h-4 rounded-full bg-destructive text-white flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity"
              onClick={(e) => { e.stopPropagation(); onDeleteField(field._tempId); }}
            >
              <Trash2 className="w-2.5 h-2.5" />
            </button>

            <div
              className="absolute bottom-0 right-0 w-3 h-3 cursor-se-resize opacity-0 group-hover:opacity-100"
              style={{ backgroundColor: color.hex }}
              onMouseDown={(e) => handleResizeDown(e, field)}
            />
          </div>
        );
      })}
    </>
  );
}

export { DEFAULT_SIZES };

import React, { useEffect, useRef, useState } from "react";
import * as pdfjsLib from "pdfjs-dist";

// Use CDN worker matching the installed library version — avoids Vite bundling issues
pdfjsLib.GlobalWorkerOptions.workerSrc = `https://cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.mjs`;

/**
 * Renders a single page of a PDF as a canvas background.
 * Props:
 *  - url: PDF file URL
 *  - pageNumber: which page to render (1-based)
 *  - onDocumentLoaded: callback receiving { numPages } when the PDF is first loaded
 *  - className: applied to the canvas wrapper
 */
export default function PDFPageViewer({ url, pageNumber, onDocumentLoaded, className }) {
  const canvasRef = useRef(null);
  const containerRef = useRef(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const pdfDocRef = useRef(null);
  const renderTaskRef = useRef(null);

  // Load the PDF document once per URL
  useEffect(() => {
    let cancelled = false;
    if (!url) return;

    setLoading(true);
    setError(null);

    const loadingTask = pdfjsLib.getDocument(url);
    loadingTask.promise
      .then((pdf) => {
        if (cancelled) return;
        pdfDocRef.current = pdf;
        onDocumentLoaded?.({ numPages: pdf.numPages });
        setLoading(false);
      })
      .catch((err) => {
        if (cancelled) return;
        console.error("PDF load error:", err);
        setError(err?.message || "Failed to load PDF");
        setLoading(false);
      });

    return () => {
      cancelled = true;
      if (renderTaskRef.current) {
        renderTaskRef.current.cancel();
        renderTaskRef.current = null;
      }
      if (pdfDocRef.current) {
        pdfDocRef.current.destroy();
        pdfDocRef.current = null;
      }
      loadingTask.destroy();
    };
  }, [url]);

  // Render the requested page whenever it changes or loading completes
  useEffect(() => {
    let cancelled = false;

    const render = async () => {
      const pdf = pdfDocRef.current;
      const canvas = canvasRef.current;
      if (!pdf || !canvas || loading) return;
      if (pageNumber < 1 || pageNumber > pdf.numPages) return;

      // Cancel any in-progress render
      if (renderTaskRef.current) {
        renderTaskRef.current.cancel();
        renderTaskRef.current = null;
      }

      try {
        const page = await pdf.getPage(pageNumber);
        if (cancelled) return;

        const containerWidth = containerRef.current?.clientWidth || canvas.parentElement.clientWidth;
        if (!containerWidth) return;

        const baseViewport = page.getViewport({ scale: 1 });
        const scale = containerWidth / baseViewport.width;
        const viewport = page.getViewport({ scale });

        // Set the parent container's aspect ratio to match the actual PDF page
        const parent = containerRef.current?.parentElement;
        if (parent) {
          parent.style.aspectRatio = `${baseViewport.width} / ${baseViewport.height}`;
        }

        const ctx = canvas.getContext("2d");
        canvas.width = viewport.width;
        canvas.height = viewport.height;
        canvas.style.width = "100%";
        canvas.style.height = "100%";

        const task = page.render({ canvasContext: ctx, viewport });
        renderTaskRef.current = task;
        await task.promise;
      } catch (err) {
        if (cancelled || err?.name === "RenderingCancelledException") return;
        console.error("PDF render error:", err);
        setError(err?.message || "Failed to render page");
      }
    };

    render();
    return () => { cancelled = true; };
  }, [pageNumber, loading]);

  if (error) {
    return (
      <div className="absolute inset-0 flex items-center justify-center text-destructive/60 text-sm p-4 text-center">
        Could not load PDF: {error}
      </div>
    );
  }

  return (
    <div ref={containerRef} className={className} style={{ position: "absolute", inset: 0 }}>
      {loading && (
        <div className="absolute inset-0 flex items-center justify-center">
          <div className="w-8 h-8 border-4 border-primary/20 border-t-primary rounded-full animate-spin" />
        </div>
      )}
      <canvas ref={canvasRef} className="w-full h-full block" />
    </div>
  );
}

