      </div>
    </div>
  );
}

import React from "react";
import { Plus, Trash2, GripVertical } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { getSignerColor } from "@/lib/signerColors";

export default function SignersStep({ signersList, setSignersList, onNext, onBack }) {
  const addSigner = () => {
    setSignersList((prev) => [
      ...prev,
      { name: "", email: "", role_label: "", signing_order: prev.length + 1 },
    ]);
  };

  const updateSigner = (index, field, value) => {
    setSignersList((prev) =>
      prev.map((s, i) => (i === index ? { ...s, [field]: value } : s))
    );
  };

  const removeSigner = (index) => {
    setSignersList((prev) => prev.filter((_, i) => i !== index));
  };

  const canProceed = signersList.length > 0 && signersList.every((s) => s.name && s.email);

  return (
    <div className="max-w-xl mx-auto">
      <h2 className="text-xl font-semibold text-foreground mb-1">Add Signers</h2>
      <p className="text-sm text-muted-foreground mb-6">
        Who needs to sign this document? Add one or more signers.
      </p>

      <div className="space-y-4">
        {signersList.map((signer, index) => {
          const color = getSignerColor(index);
          return (
            <div
              key={index}
              className="p-4 rounded-xl border-2 bg-white"
              style={{ borderColor: color.hex + "60" }}
            >
              <div className="flex items-center justify-between mb-3">
                <div className="flex items-center gap-2">
                  <div className="w-3 h-3 rounded-full" style={{ backgroundColor: color.hex }} />
                  <span className="text-sm font-medium text-foreground">
                    Signer {index + 1}
                  </span>
                </div>
                {signersList.length > 1 && (
                  <Button variant="ghost" size="icon" className="h-7 w-7" onClick={() => removeSigner(index)}>
                    <Trash2 className="w-4 h-4 text-muted-foreground" />
                  </Button>
                )}
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div>
                  <Label className="text-xs">Full Name</Label>
                  <Input
                    value={signer.name}
                    onChange={(e) => updateSigner(index, "name", e.target.value)}
                    placeholder="John Doe"
                    className="mt-1"
                  />
                </div>
                <div>
                  <Label className="text-xs">Email</Label>
                  <Input
                    type="email"
                    value={signer.email}
                    onChange={(e) => updateSigner(index, "email", e.target.value)}
                    placeholder="john@example.com"
                    className="mt-1"
                  />
                </div>
                <div>
                  <Label className="text-xs">Role Label (optional)</Label>
                  <Input
                    value={signer.role_label}
                    onChange={(e) => updateSigner(index, "role_label", e.target.value)}
                    placeholder="e.g. Tenant, Landlord"
                    className="mt-1"
                  />
                </div>
                <div>
                  <Label className="text-xs">Signing Order</Label>
                  <Input
                    type="number"
                    min={1}
                    value={signer.signing_order}
                    onChange={(e) => updateSigner(index, "signing_order", parseInt(e.target.value) || 1)}
                    className="mt-1"
                  />
                </div>
              </div>
            </div>
          );
        })}

        <Button variant="outline" onClick={addSigner} className="w-full gap-2 border-dashed">
          <Plus className="w-4 h-4" />
          Add Signer
        </Button>
      </div>

      <div className="flex justify-between mt-8">
        <Button variant="outline" onClick={onBack}>
          Back
        </Button>
        <Button onClick={onNext} disabled={!canProceed}>
          Continue
        </Button>
      </div>
    </div>
  );
}

