import React, { useRef, useState } from "react";
import { Upload, FileText, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { base44 } from "@/api/base44Client";
import * as pdfjsLib from "pdfjs-dist";
pdfjsLib.GlobalWorkerOptions.workerSrc = `https://cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.mjs`;

export default function UploadStep({ documentData, setDocumentData, onNext }) {
  const fileInputRef = useRef(null);
  const [uploading, setUploading] = useState(false);
  const [dragActive, setDragActive] = useState(false);

  const handleFile = async (file) => {
    if (!file || file.type !== "application/pdf") return;
    setUploading(true);
    try {
      const { file_url } = await base44.integrations.Core.UploadFile({ file });
      // Read actual page count from the PDF
      let pageCount = 1;
      try {
        const arrayBuffer = await file.arrayBuffer();
        const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
        pageCount = pdf.numPages;
        pdf.destroy();
      } catch { /* fall back to default */ }
      setDocumentData((d) => ({
        ...d,
        original_file_url: file_url,
        fileName: file.name,
        title: d.title || file.name.replace(/\.pdf$/i, ""),
        pageCount,
      }));
    } finally {
      setUploading(false);
    }
  };

  const handleDrop = (e) => {
    e.preventDefault();
    setDragActive(false);
    if (e.dataTransfer.files?.[0]) handleFile(e.dataTransfer.files[0]);
  };

  const canProceed = documentData.original_file_url && documentData.title;

  return (
    <div className="max-w-xl mx-auto">
      <h2 className="text-xl font-semibold text-foreground mb-1">Upload Document</h2>
      <p className="text-sm text-muted-foreground mb-6">Upload a PDF file to get started.</p>

      <div className="space-y-4">
        <div>
          <Label htmlFor="title">Document Title</Label>
          <Input
            id="title"
            value={documentData.title || ""}
            onChange={(e) => setDocumentData((d) => ({ ...d, title: e.target.value }))}
            placeholder="e.g. Lease Agreement"
            className="mt-1.5"
          />
        </div>

        {!documentData.original_file_url ? (
          <div
            onDragOver={(e) => { e.preventDefault(); setDragActive(true); }}
            onDragLeave={() => setDragActive(false)}
            onDrop={handleDrop}
            onClick={() => fileInputRef.current?.click()}
            className={`border-2 border-dashed rounded-xl p-10 text-center cursor-pointer transition-colors ${
              dragActive ? "border-primary bg-primary/5" : "border-border hover:border-primary/50"
            }`}
          >
            {uploading ? (
              <div className="flex flex-col items-center gap-3">
                <div className="w-8 h-8 border-4 border-primary/20 border-t-primary rounded-full animate-spin" />
                <p className="text-sm text-muted-foreground">Uploading...</p>
              </div>
            ) : (
              <div className="flex flex-col items-center gap-3">
                <div className="w-12 h-12 rounded-xl bg-primary/10 flex items-center justify-center">
                  <Upload className="w-6 h-6 text-primary" />
                </div>
                <div>
                  <p className="text-sm font-medium text-foreground">Drop your PDF here or click to browse</p>
                  <p className="text-xs text-muted-foreground mt-1">PDF files only</p>
                </div>
              </div>
            )}
            <input
              ref={fileInputRef}
              type="file"
              accept=".pdf"
              className="hidden"
              onChange={(e) => e.target.files?.[0] && handleFile(e.target.files[0])}
            />
          </div>
        ) : (
          <div className="flex items-center gap-3 p-4 bg-emerald-50 rounded-xl border border-emerald-200">
            <FileText className="w-5 h-5 text-emerald-600" />
            <span className="text-sm font-medium text-emerald-800 flex-1 truncate">
              {documentData.fileName || "Document uploaded"}
            </span>
            <Button
              variant="ghost"
              size="icon"
              className="h-7 w-7"
              onClick={(e) => {
                e.stopPropagation();
                setDocumentData((d) => ({ ...d, original_file_url: null, fileName: null }));
              }}
            >
              <X className="w-4 h-4" />
            </Button>
          </div>
        )}
      </div>

      <div className="flex justify-end mt-8">
        <Button onClick={onNext} disabled={!canProceed}>
          Continue
        </Button>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { base44 } from '@/api/base44Client';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Mail, CheckCircle2 } from 'lucide-react';
import { useQueryClient } from '@tanstack/react-query';
import { businessConfig as biz } from '@/lib/businessConfig';

/**
 * EmailComposer — sends email directly via base44 SendEmail integration
 * and logs it in EmailLog.
 * Optional: attachmentBlobFn (async fn that returns a Blob), attachmentName
 */
export default function EmailComposer({ open, onClose, to, toName, subject: initSubject, body: initBody, type = 'other', referenceId, attachmentBlobFn, attachmentName }) {
  const [subject, setSubject] = useState(initSubject || '');
  const [body, setBody] = useState(initBody || '');
  const [sent, setSent] = useState(false);
  const [sending, setSending] = useState(false);
  const [error, setError] = useState(null);
  const queryClient = useQueryClient();

  useEffect(() => {
    if (open) { setSubject(initSubject || ''); setBody(initBody || ''); setSent(false); setError(null); }
  }, [open, initSubject, initBody]);

  const handleSend = async () => {
    setSending(true);
    setError(null);
    const me = await base44.auth.me();

    // Upload PDF attachment if provided
    let attachmentUrl = null;
    if (attachmentBlobFn) {
      const blob = await attachmentBlobFn();
      const file = new File([blob], attachmentName || 'attachment.pdf', { type: 'application/pdf' });
      const { file_url } = await base44.integrations.Core.UploadFile({ file });
      attachmentUrl = file_url;
    }

    // Build HTML body with proper formatting
    const htmlBody = body
      .split('\n')
      .map(line => line.trim() === '' ? '<br/>' : `<p style="margin:0 0 8px 0;">${line}</p>`)
      .join('\n') +
      (attachmentUrl ? `<br/><p style="margin:0 0 8px 0;"><a href="${attachmentUrl}" style="color:#2563eb;">📎 Download ${attachmentName || 'Attachment'}</a></p>` : '');

    const res = await base44.functions.invoke('sendEmail', {
      from_name: biz.name,
      to,
      subject,
      body: `<div style="font-family:Arial,sans-serif;font-size:14px;line-height:1.6;color:#333;max-width:600px;">${htmlBody}</div>`,
    });
    if (res?.data?.error) throw new Error(res.data.error);
    await base44.entities.EmailLog.create({
      recipient_email: to,
      recipient_name: toName || to,
      subject,
      body_preview: body.substring(0, 300),
      type,
      reference_id: referenceId || '',
      status: 'opened',
      sent_by: me?.email || '',
    });
    queryClient.invalidateQueries({ queryKey: ['email_logs'] });
    setSending(false);
    setSent(true);
  };

  return (
    <Dialog open={open} onOpenChange={v => { if (!v) onClose(); }}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Mail className="w-5 h-5 text-primary" />
            Compose Email
          </DialogTitle>
        </DialogHeader>

        {sent ? (
          <div className="flex flex-col items-center gap-3 py-10 text-emerald-600">
            <CheckCircle2 className="w-12 h-12" />
            <p className="font-semibold text-lg">Email sent successfully!</p>
            <p className="text-sm text-muted-foreground text-center max-w-sm">
              Your email has been sent to <strong>{toName || to}</strong> and logged.
            </p>
            <Button variant="outline" onClick={onClose} className="mt-2">Close</Button>
          </div>
        ) : (
          <>
            <div className="space-y-4">
              <div className="bg-blue-50 border border-blue-200 rounded-lg px-4 py-3 text-sm text-blue-800">
                <p>Email will be sent directly from <strong>{biz.name}</strong> and logged automatically.</p>
              </div>
              {error && <p className="text-sm text-destructive bg-red-50 border border-red-200 rounded-lg px-3 py-2">{error}</p>}

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <Label>From</Label>
                  <Input value={biz.email} disabled className="bg-muted/50" />
                </div>
                <div className="space-y-1.5">
                  <Label>To</Label>
                  <Input value={toName ? `${toName} <${to}>` : to} disabled className="bg-muted/50" />
                </div>
              </div>

              <div className="space-y-1.5">
                <Label>Subject</Label>
                <Input value={subject} onChange={e => setSubject(e.target.value)} />
              </div>

              <div className="space-y-1.5">
                <Label>Message</Label>
                <Textarea value={body} onChange={e => setBody(e.target.value)} rows={16} className="text-sm font-mono" />
              </div>

              {!to && <p className="text-sm text-destructive">No email address on record for this recipient.</p>}
            </div>

            <DialogFooter className="pt-2">
              <Button variant="outline" onClick={onClose} disabled={sending}>Cancel</Button>
              <Button onClick={handleSend} disabled={!to || sending}>
                <Mail className="w-4 h-4 mr-2" />
                {sending ? 'Sending...' : 'Send Email'}
              </Button>
            </DialogFooter>
          </>
        )}
      </DialogContent>
    </Dialog>
  );
}

import React, { useRef, useEffect, useState } from 'react';
import { Button } from '@/components/ui/button';

export default function SignaturePad({ onChange }) {
  const canvasRef = useRef(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [hasSignature, setHasSignature] = useState(false);

  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    ctx.strokeStyle = '#1e3a8a';
    ctx.lineWidth = 2.5;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
  }, []);

  const getPos = (e) => {
    const canvas = canvasRef.current;
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    if (e.touches) {
      return {
        x: (e.touches[0].clientX - rect.left) * scaleX,
        y: (e.touches[0].clientY - rect.top) * scaleY,
      };
    }
    return {
      x: (e.clientX - rect.left) * scaleX,
      y: (e.clientY - rect.top) * scaleY,
    };
  };

  const startDrawing = (e) => {
    e.preventDefault();
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    const pos = getPos(e);
    ctx.beginPath();
    ctx.moveTo(pos.x, pos.y);
    setIsDrawing(true);
  };

  const draw = (e) => {
    if (!isDrawing) return;
    e.preventDefault();
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    const pos = getPos(e);
    ctx.lineTo(pos.x, pos.y);
    ctx.stroke();
    setHasSignature(true);
  };

  const stopDrawing = (e) => {
    if (!isDrawing) return;
    e.preventDefault();
    setIsDrawing(false);
    if (hasSignature) {
      onChange(canvasRef.current.toDataURL('image/png'));
    }
  };

  const clear = () => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    setHasSignature(false);
    onChange(null);
  };

  return (
    <div className="space-y-2">
      <div className="relative border-2 border-dashed border-border rounded-lg bg-white overflow-hidden" style={{ touchAction: 'none' }}>
        <canvas
          ref={canvasRef}
          width={600}
          height={180}
          className="w-full cursor-crosshair"
          onMouseDown={startDrawing}
          onMouseMove={draw}
          onMouseUp={stopDrawing}
          onMouseLeave={stopDrawing}
          onTouchStart={startDrawing}
          onTouchMove={draw}
          onTouchEnd={stopDrawing}
        />
        {!hasSignature && (
          <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
            <p className="text-muted-foreground text-sm">Draw your signature here</p>
          </div>
        )}
      </div>
      <Button type="button" variant="ghost" size="sm" onClick={clear} disabled={!hasSignature}>
        Clear
      </Button>
    </div>
  );
}

