import React, { useState } from 'react';
import { base44 } from '@/api/base44Client';
import { Button } from '@/components/ui/button';
import { Upload, X, Loader2, ImagePlus } from 'lucide-react';

export default function PhotoUploader({ photoUrls, value, onChange }) {
  // Accept either `photoUrls` or `value` (some callers pass `value`).
  const urls = photoUrls || value || [];
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState('');

  const handleSelect = async (e) => {
    const files = Array.from(e.target.files || []);
    if (!files.length) return;
    setUploading(true);
    setError('');
    const uploaded = [];
    try {
      for (const file of files) {
        const res = await base44.integrations.Core.UploadFile({ file });
        const url = res?.file_url || res?.url || res?.data?.file_url;
        if (url) uploaded.push(url);
        else throw new Error('Upload did not return a file URL');
      }
      if (uploaded.length) onChange([...(urls || []), ...uploaded]);
    } catch (err) {
      console.error('Photo upload failed:', err);
      setError(err?.message || 'Upload failed. Please try again.');
    } finally {
      setUploading(false);
      e.target.value = '';
    }
  };

  const remove = (idx) => {
    const next = [...urls];
    next.splice(idx, 1);
    onChange(next);
  };

  return (
    <div className="space-y-2">
      <div className="grid grid-cols-3 sm:grid-cols-4 gap-2">
        {urls.map((url, i) => (
          <div key={url + i} className="relative aspect-square rounded-lg overflow-hidden bg-muted border border-border group">
            <img src={url} alt="" className="w-full h-full object-cover" />
            <button
              type="button"
              onClick={() => remove(i)}
              className="absolute top-1 right-1 w-6 h-6 rounded-full bg-black/60 text-white flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity"
              aria-label="Remove photo"
            >
              <X className="w-3.5 h-3.5" />
            </button>
            {i === 0 && (
              <span className="absolute bottom-1 left-1 px-1.5 py-0.5 rounded bg-primary text-primary-foreground text-[9px] font-semibold uppercase tracking-wider">
                Cover
              </span>
            )}
          </div>
        ))}
        <label className="aspect-square rounded-lg border-2 border-dashed border-border flex flex-col items-center justify-center text-muted-foreground hover:border-primary hover:text-primary cursor-pointer transition-colors">
          {uploading ? (
            <Loader2 className="w-5 h-5 animate-spin" />
          ) : (
            <>
              <ImagePlus className="w-5 h-5 mb-1" />
              <span className="text-[10px]">Add photo</span>
            </>
          )}
          <input
            type="file"
            accept="image/*"
            multiple
            onChange={handleSelect}
            disabled={uploading}
            className="sr-only"
          />
        </label>
      </div>
      <p className="text-[11px] text-muted-foreground">First photo is used as the cover image. You can add multiple.</p>
      {error && <p className="text-[11px] text-red-600">{error}</p>}
    </div>
  );
}

