import React, { useState } from 'react';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Switch } from '@/components/ui/switch';
import FileUpload from '@/components/forms/FileUpload';
import PhotoUploader from '@/components/forms/PhotoUploader.jsx';
import LandlordCombobox from '@/components/forms/LandlordCombobox.jsx';
import { getLandlordShares, totalShare } from '@/lib/landlordShares';
import { FileText, Globe, Plus, Trash2, Users, Check, Sparkles } from 'lucide-react';
import { base44 } from '@/api/base44Client';

export default function PropertyForm({ property, landlords, onSubmit, onCancel }) {
  const [submitting, setSubmitting] = useState(false);
  const [data, setData] = useState(property || {
    landlord_id: '', address: '', type: 'flat', bedrooms: 1, bathrooms: 1, monthly_rent: 0, deposit_amount: 0, council_tax_band: '', status: 'vacant', payment_day: '',
    floor_level: '', utilities: { water: true, gas: true, electricity: true, broadband: true }, parking: { available: false }, bills_included: [],
    epc_rating: '', gas_safety_cert: '', eicr_status: '',
    floor_plan_file: '', inventory_report_file: '', notes: '',
    show_on_website: false, listing_type: 'rent', let_agreed: false, sale_price: '', public_title: '', public_description: '', photo_urls: [], size_sqft: '',
  });

  const [error, setError] = useState('');
  const [genDesc, setGenDesc] = useState(false);

  const generateDescription = async () => {
    if (genDesc) return;
    setError('');
    if (!data.address?.trim()) { setError('Add the address first so the AI has something to describe.'); return; }
    setGenDesc(true);
    try {
      const feats = [];
      if (data.bedrooms) feats.push(`${data.bedrooms} bedroom${data.bedrooms > 1 ? 's' : ''}`);
      if (data.bathrooms) feats.push(`${data.bathrooms} bathroom${data.bathrooms > 1 ? 's' : ''}`);
      if (data.floor_level) feats.push(`${data.floor_level} floor`);
      if (data.parking?.available) feats.push('parking available');
      if (data.parking?.ev_charging) feats.push('EV charging');
      const utils = ['water', 'gas', 'electricity', 'broadband'].filter(k => data.utilities?.[k] !== false);
      const isSale = data.listing_type === 'sale';
      const prompt = `You are a professional UK letting agent writing a property advert for ASA Estates, an East London agency.
Write an appealing, accurate ${isSale ? 'sales' : 'lettings'} description of about 90-120 words for the property below.
Rules: use British English; warm but professional tone; do NOT invent features that are not listed; do not state the price; refer naturally to the local area based on the address; finish with a short call to action to arrange a viewing. Return only the description text.

Property type: ${data.type || 'property'}
Address / area: ${data.address}
${feats.length ? `Features: ${feats.join(', ')}` : ''}
Council tax band: ${data.council_tax_band || 'not specified'}
Utilities connected: ${utils.join(', ') || 'not specified'}
${data.utilities?.mobile_signal ? `Mobile signal: ${data.utilities.mobile_signal}` : ''}
${data.public_title ? `Headline: ${data.public_title}` : ''}`;

      const result = await base44.integrations.Core.InvokeLLM({ prompt });
      const text = typeof result === 'string'
        ? result
        : (result?.text || result?.output || result?.response || result?.content || '');
      if (text && String(text).trim()) {
        setData(d => ({ ...d, public_description: String(text).trim() }));
      } else {
        setError('The AI did not return any text. Please try again.');
      }
    } catch (e) {
      setError(e?.message || 'Could not generate a description. Please try again.');
    } finally {
      setGenDesc(false);
    }
  };

  // Co-ownership: one or more landlords with a share %. Defaults to a single
  // landlord at 100% (which behaves exactly like the old single-landlord field).
  // Stable unique id per share row so React doesn't reuse the wrong row
  // instance when one is deleted (index-based keys break on removal).
  const uid = () => (crypto.randomUUID ? crypto.randomUUID() : Math.random().toString(36).slice(2));

  const [shares, setShares] = useState(() => {
    const init = getLandlordShares(property).map(s => ({ ...s, _uid: uid() }));
    return init.length ? init : [{ landlord_id: '', share_pct: 100, _uid: uid() }];
  });
  // The ownership split as it was when the form opened, to detect a real change.
  const originalShares = React.useMemo(() => getLandlordShares(property), [property]);
  // Month from which a changed split takes effect. Earlier months keep the old
  // split (frozen). Defaults to the current month.
  const [ownershipEffectiveMonth, setOwnershipEffectiveMonth] = useState(() => new Date().toISOString().slice(0, 7));

  const updateShare = (idx, patch) =>
    setShares(prev => prev.map((s, i) => (i === idx ? { ...s, ...patch } : s)));
  const addShare = () => setShares(prev => [...prev, { landlord_id: '', share_pct: 0, _uid: uid() }]);
  const removeShare = (targetUid) => setShares(prev => {
    const next = prev.filter(s => s._uid !== targetUid);
    // When a co-landlord is removed, the remaining owner takes 100%.
    if (next.length === 1) next[0] = { ...next[0], share_pct: 100 };
    return next;
  });
  const splitEvenly = () => {
    const n = shares.length;
    if (!n) return;
    const base = Math.floor((100 / n) * 100) / 100;
    const next = shares.map(s => ({ ...s, share_pct: base }));
    const drift = Math.round((100 - base * n) * 100) / 100;
    next[0].share_pct = Math.round((next[0].share_pct + drift) * 100) / 100;
    setShares(next);
  };

  const sharesTotal = totalShare(shares.filter(s => s.landlord_id));
  const isMulti = shares.filter(s => s.landlord_id).length > 1;

  // Whether the live shares differ from what the form opened with (drives the
  // "apply from" month picker so past statements can be preserved).
  const ownershipChanged = React.useMemo(() => {
    const live = shares.filter(s => s.landlord_id).map(s => `${s.landlord_id}:${Number(s.share_pct) || 0}`).sort().join('|');
    const orig = originalShares.map(s => `${s.landlord_id}:${Number(s.share_pct) || 0}`).sort().join('|');
    return live !== orig;
  }, [shares, originalShares]);

  // Per-property payout bank accounts (keyed by landlord_id). Overrides the
  // landlord's default account for THIS property.
  const [payoutMap, setPayoutMap] = useState(() => {
    const m = {};
    (Array.isArray(property?.payout_bank_accounts) ? property.payout_bank_accounts : []).forEach(a => {
      if (a && a.landlord_id) m[a.landlord_id] = {
        account_name: a.account_name || '', bank_name: a.bank_name || '',
        sort_code: a.sort_code || '', account_number: a.account_number || '', reference: a.reference || '',
      };
    });
    return m;
  });
  const updatePayout = (lid, field, val) =>
    setPayoutMap(prev => ({ ...prev, [lid]: { ...(prev[lid] || {}), [field]: val } }));

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (submitting) return;
    setError('');
    const validShares = shares
      .filter(s => s.landlord_id)
      .map(s => ({ landlord_id: s.landlord_id, share_pct: Number(s.share_pct) || 0 }));

    if (validShares.length === 0) { setError('Please select at least one landlord.'); return; }
    const ids = validShares.map(s => s.landlord_id);
    if (new Set(ids).size !== ids.length) { setError('The same landlord is listed more than once.'); return; }
    if (validShares.length > 1) {
      if (validShares.some(s => s.share_pct <= 0)) { setError('Each landlord must have a share greater than 0%.'); return; }
      const total = validShares.reduce((s, x) => s + x.share_pct, 0);
      if (Math.abs(total - 100) > 0.01) { setError(`Shares must add up to 100% (currently ${total}%).`); return; }
    }
    // Primary landlord = largest share (ties → first listed)
    const primary = [...validShares].sort((a, b) => b.share_pct - a.share_pct)[0].landlord_id;

    if (!data.address?.trim()) { setError('Please enter an address.'); return; }
    if (!data.monthly_rent || data.monthly_rent <= 0) { setError('Please enter a monthly rent.'); return; }
    setSubmitting(true);
    try {
      const payload = { ...data, landlord_id: primary };
      // Store the split only when there's genuine co-ownership. For a single
      // landlord we must EXPLICITLY clear landlord_shares (set to []), not just
      // omit it — omitting leaves the old co-owner split in the database, so a
      // removed co-landlord would silently persist.
      if (validShares.length > 1) payload.landlord_shares = validShares;
      else payload.landlord_shares = [];

      // If the ownership split actually changed, freeze the OLD split into
      // ownership_history so past statements keep it. The old split applied
      // through the month before the chosen effective month.
      const sharesChanged = (() => {
        if (originalShares.length !== validShares.length) return true;
        const norm = arr => [...arr].map(s => `${s.landlord_id}:${Number(s.share_pct)}`).sort().join('|');
        return norm(originalShares) !== norm(validShares);
      })();
      if (sharesChanged && originalShares.length > 0) {
        const [ey, em] = ownershipEffectiveMonth.split('-').map(Number);
        const prev = new Date(ey, em - 2, 1); // month before effective month
        const effectiveTo = `${prev.getFullYear()}-${String(prev.getMonth() + 1).padStart(2, '0')}`;
        const priorHistory = Array.isArray(property?.ownership_history) ? property.ownership_history : [];
        payload.ownership_history = [
          ...priorHistory,
          { effective_to: effectiveTo, shares: originalShares },
        ];
      } else if (Array.isArray(property?.ownership_history)) {
        // Preserve any existing history untouched.
        payload.ownership_history = property.ownership_history;
      }
      // Per-property payout accounts (only keep entries with at least one field filled).
      const accounts = validShares
        .map(s => ({ landlord_id: s.landlord_id, ...(payoutMap[s.landlord_id] || {}) }))
        .filter(a => a.account_name || a.bank_name || a.sort_code || a.account_number || a.reference);
      // Explicitly clear when empty so removed accounts don't linger.
      payload.payout_bank_accounts = accounts.length > 0 ? accounts : [];
      // Strip empty-string numerics so backend validation doesn't reject them
      ['sale_price', 'size_sqft', 'payment_day', 'bedrooms', 'bathrooms'].forEach(k => {
        if (payload[k] === '' || payload[k] === null) delete payload[k];
      });
      await onSubmit(payload);
    } catch (err) {
      setError(err?.message || 'Failed to save property. Please try again.');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <div className="space-y-3 border border-border rounded-lg p-4 bg-muted/20">
        <div className="flex items-center justify-between">
          <Label className="flex items-center gap-2">
            <Users className="w-4 h-4 text-primary" /> Landlord(s) *
          </Label>
          {isMulti && (
            <span className={`text-xs font-medium ${Math.abs(sharesTotal - 100) < 0.01 ? 'text-emerald-600' : 'text-destructive'}`}>
              Total: {sharesTotal}%
            </span>
          )}
        </div>

        {shares.map((s, idx) => (
          <div key={s._uid} className="flex items-end gap-2">
            <div className="flex-1 space-y-1">
              {idx === 0 && shares.length > 1 && <span className="text-xs text-muted-foreground">Landlord</span>}
              <LandlordCombobox
                landlords={landlords}
                value={s.landlord_id}
                onChange={v => updateShare(idx, { landlord_id: v })}
                placeholder="Select landlord"
              />
            </div>
            {shares.length > 1 && (
              <div className="w-24 space-y-1">
                {idx === 0 && <span className="text-xs text-muted-foreground">Share %</span>}
                <Input
                  type="number" min="0" max="100" step="0.01"
                  value={s.share_pct ?? ''}
                  onChange={e => updateShare(idx, { share_pct: e.target.value === '' ? '' : Number(e.target.value) })}
                />
              </div>
            )}
            {shares.length > 1 && (
              <Button type="button" variant="ghost" size="icon" className="text-muted-foreground hover:text-destructive" onClick={() => removeShare(s._uid)}>
                <Trash2 className="w-4 h-4" />
              </Button>
            )}
          </div>
        ))}

        <div className="flex items-center gap-2 pt-1">
          <Button type="button" variant="outline" size="sm" onClick={addShare}>
            <Plus className="w-3.5 h-3.5 mr-1" /> Add co-landlord
          </Button>
          {isMulti && (
            <Button type="button" variant="ghost" size="sm" onClick={splitEvenly}>Split evenly</Button>
          )}
        </div>
        {isMulti && (
          <p className="text-xs text-muted-foreground">
            Rent and payouts are split by these shares. Commission is charged once on the property, then divided the same way. Each landlord gets their own statement.
          </p>
        )}
        {ownershipChanged && originalShares.length > 0 && (
          <div className="mt-1 rounded-lg border border-amber-300 bg-amber-50 px-3 py-2 space-y-1.5">
            <p className="text-xs font-medium text-amber-900">Ownership split changed — apply from:</p>
            <input
              type="month"
              value={ownershipEffectiveMonth}
              onChange={e => setOwnershipEffectiveMonth(e.target.value)}
              className="w-40 px-2 py-1.5 text-sm border border-input rounded-md bg-background"
            />
            <p className="text-[11px] text-amber-700">
              Statements before this month keep the previous split; this month onward uses the new split.
            </p>
          </div>
        )}
      </div>

      {shares.filter(s => s.landlord_id).length > 0 && (
        <div className="space-y-3 border border-border rounded-lg p-4 bg-muted/10">
