import React, { useState, useEffect } from 'react';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { format } from 'date-fns';
import PropertyCombobox from '@/components/forms/PropertyCombobox';
import { getFrequency, forPeriod, cycleStartMonth } from '@/lib/rentFrequency';

const MONTHS = [
  { value: '01', label: 'January' },  { value: '02', label: 'February' },
  { value: '03', label: 'March' },    { value: '04', label: 'April' },
  { value: '05', label: 'May' },      { value: '06', label: 'June' },
  { value: '07', label: 'July' },     { value: '08', label: 'August' },
  { value: '09', label: 'September' },{ value: '10', label: 'October' },
  { value: '11', label: 'November' }, { value: '12', label: 'December' },
];

const YEARS = Array.from({ length: 15 }, (_, i) => String(new Date().getFullYear() - 5 + i));

function PeriodPicker({ value, onChange }) {
  const parse = (v) => {
    const p = (v || format(new Date(), 'yyyy-MM')).split('-');
    return { yr: p[0] || String(new Date().getFullYear()), mo: p[1] || format(new Date(), 'MM') };
  };
  const [month, setMonth] = React.useState(() => parse(value).mo);
  const [year,  setYear]  = React.useState(() => parse(value).yr);

  React.useEffect(() => {
    const { yr, mo } = parse(value);
    setMonth(mo);
    setYear(yr);
  }, [value]);

  const handleMonth = (m) => { setMonth(m); onChange(`${year}-${m}`); };
  const handleYear  = (y) => { setYear(y);  onChange(`${y}-${month}`); };

  return (
    <div className="flex gap-2">
      <Select value={month} onValueChange={handleMonth}>
        <SelectTrigger className="flex-1"><SelectValue placeholder="Month" /></SelectTrigger>
        <SelectContent>
          {MONTHS.map(m => <SelectItem key={m.value} value={m.value}>{m.label}</SelectItem>)}
        </SelectContent>
      </Select>
      <Select value={year} onValueChange={handleYear}>
        <SelectTrigger className="w-28"><SelectValue placeholder="Year" /></SelectTrigger>
        <SelectContent>
          {YEARS.map(y => <SelectItem key={y} value={y}>{y}</SelectItem>)}
        </SelectContent>
      </Select>
    </div>
  );
}

export default function RentPaymentForm({ payment, tenants, properties, onSubmit, onCancel }) {
  const [submitting, setSubmitting] = useState(false);
  const [data, setData] = useState(payment || {
    tenant_id: '', property_id: '', landlord_id: '', amount: 0,
    payment_date: format(new Date(), 'yyyy-MM-dd'),
    period_month: format(new Date(), 'yyyy-MM'),
    method: 'bank_transfer', notes: '', reference: ''
  });

  const selectedTenant   = tenants.find(t => t.id === data.tenant_id);
  const selectedProperty = properties.find(p => p.id === data.property_id);
  const agreedRent       = selectedTenant?.monthly_rent || 0;

  // When tenant is selected, auto-fill property, landlord and amount
  useEffect(() => {
    if (data.tenant_id && !payment) {
      const tenant = tenants.find(t => t.id === data.tenant_id);
      if (tenant) {
        const property = properties.find(p => p.id === tenant.property_id);
        const freq = getFrequency(tenant);
        const amount = forPeriod(tenant.monthly_rent, freq) || 0;
        let period = data.period_month || format(new Date(), 'yyyy-MM');
        if (freq === 'quarterly' && tenant.lease_start) {
          period = cycleStartMonth(tenant.lease_start.substring(0, 7), period, 'quarterly');
        }
        setData(prev => ({
          ...prev,
          property_id: tenant.property_id || prev.property_id,
          landlord_id: property?.landlord_id || prev.landlord_id,
          amount,
          period_month: period,
        }));
      }
    }
  }, [data.tenant_id]);

  const handlePropertyChange = (propertyId) => {
    const property = properties.find(p => p.id === propertyId);
    setData(prev => ({ ...prev, property_id: propertyId, landlord_id: property?.landlord_id || prev.landlord_id }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (submitting) return;
    setSubmitting(true);
    try {
      const tenant = tenants.find(t => t.id === data.tenant_id);
      const freq = getFrequency(tenant);
      let period_month = data.period_month;
      if (freq === 'quarterly' && tenant?.lease_start) {
        period_month = cycleStartMonth(tenant.lease_start.substring(0, 7), period_month, 'quarterly');
      }
      await onSubmit({ ...data, period_month });
    } finally { setSubmitting(false); }
  };

  const activeTenants       = tenants.filter(t => t.status !== 'ended');
  const availableProperties = properties.filter(p => p.status !== 'maintenance');

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">

        <div className="space-y-2">
          <Label>Tenant *</Label>
          <Select value={data.tenant_id} onValueChange={v => setData({ ...data, tenant_id: v })}>
            <SelectTrigger><SelectValue placeholder="Select tenant" /></SelectTrigger>
            <SelectContent>
              {activeTenants.map(t => <SelectItem key={t.id} value={t.id}>{t.name}</SelectItem>)}
            </SelectContent>
          </Select>
        </div>

        <div className="space-y-2">
          <Label>Property *</Label>
          <PropertyCombobox
            properties={availableProperties}
            value={data.property_id}
            onChange={handlePropertyChange}
            placeholder="Search property..."
          />
        </div>

        {agreedRent > 0 && (
          <div className="sm:col-span-2">
            <div className="flex items-center gap-3 rounded-lg bg-blue-50 border border-blue-200 px-4 py-2.5 text-sm">
              <span className="text-blue-700 font-medium">{getFrequency(selectedTenant) === 'quarterly' ? 'Agreed Quarterly Rent:' : 'Agreed Monthly Rent:'}</span>
              <span className="font-bold text-blue-900">£{forPeriod(agreedRent, getFrequency(selectedTenant)).toFixed(2)}</span>
              {getFrequency(selectedTenant) === 'quarterly' && <span className="text-blue-500 text-xs">(3 × £{agreedRent.toFixed(2)})</span>}
              <span className="text-blue-500 text-xs ml-auto">Pre-filled — adjust if partial payment</span>
            </div>
          </div>
        )}

        <div className="space-y-2">
          <Label>Amount Paid (£) *</Label>
          <Input type="number" min="0" step="0.01" value={data.amount || ''} onChange={e => setData({ ...data, amount: Number(e.target.value) })} required />
        </div>

        <div className="space-y-2">
          <Label>Payment Date *</Label>
          <Input type="date" value={data.payment_date} onChange={e => setData({ ...data, payment_date: e.target.value })} required />
        </div>

        <div className="space-y-2 sm:col-span-2">
