      <div className="flex gap-3 justify-end pt-2">
        {onCancel && <Button type="button" variant="outline" onClick={onCancel} disabled={submitting}>Cancel</Button>}
        <Button type="submit" disabled={submitting || (data.method === 'cash' && !String(data.reference || '').trim())}>{submitting ? 'Saving...' : payment ? 'Update' : 'Record Payment'}</Button>
      </div>
    </form>
  );
}

