  const handleImport = async () => {
    setImporting(true);
    const success = [], errors = [];
    for (let i = 0; i < rows.length; i++) {
      const parsed = parseRow(rows[i]);
      if (!parsed) { errors.push({ row: i + 2, reason: 'Missing required field: Name' }); continue; }
