                    {rows.length > 20 && <tr><td colSpan={TEMPLATE_COLS.length} className="px-3 py-2 text-muted-foreground italic">… and {rows.length - 20} more rows</td></tr>}
                  </tbody>
                </table>
              </div>
              <div className="flex justify-end gap-2">
                <Button variant="outline" onClick={reset}>Clear</Button>
                <Button onClick={handleImport} disabled={importing}>
                  {importing ? 'Importing…' : `Import ${rows.length} Landlords`}
                </Button>
              </div>
            </>
          )}

          {results && (
            <div className="space-y-3">
              {results.success.length > 0 && (
                <div className="flex items-start gap-2 rounded-lg bg-emerald-50 border border-emerald-200 px-4 py-3 text-sm text-emerald-700">
