import { Button } from '@/components/ui/button';
import { Upload, Download, CheckCircle, XCircle, AlertCircle } from 'lucide-react';

const TEMPLATE_COLS = [
  'Address *', 'Landlord Name (partial match) *', 'Type (house/flat/studio/commercial/hmo)',
  'Bedrooms', 'Monthly Rent (£) *', 'Status (occupied/vacant/maintenance)',
  'Payment Day (1-31)', 'Notes',
  'Tenant Name', 'Tenant Email', 'Tenant Phone',
  'Tenant Rent (£)', 'Lease Start (YYYY-MM-DD)', 'Lease End (YYYY-MM-DD)', 'Deposit (£)',
];

const SAMPLE_ROWS = [
  ['141 Sherrard Road, London E12 5HQ', 'John Smith', 'flat', 2, 1200, 'occupied', 25, '', 'Alice Brown', 'alice@email.com', '07700000001', 1200, '2024-01-01', '2025-01-01', 1200],
  ['72 Baker Street, Manchester M1 2AB', 'Sarah Jones', 'house', 3, 1850, 'vacant', 28, 'Recently refurbished', '', '', '', '', '', '', ''],
];

const VALID_TYPES = ['house', 'flat', 'studio', 'commercial', 'hmo'];
const VALID_STATUSES = ['occupied', 'vacant', 'maintenance'];

function downloadTemplate() {
  const ws = XLSX.utils.aoa_to_sheet([TEMPLATE_COLS, ...SAMPLE_ROWS]);
  ws['!cols'] = TEMPLATE_COLS.map((_, i) => ({ wch: i === 0 || i === 1 ? 32 : 22 }));
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Properties');
  XLSX.writeFile(wb, 'Property_Import_Template.xlsx');
}

function parseRow(row, landlords) {
  const address = (row['Address *'] || row['Address'] || '').toString().trim();
  const landlordPartial = (row['Landlord Name (partial match) *'] || row['Landlord Name'] || '').toString().trim();
  const rentRaw = parseFloat(row['Monthly Rent (£) *'] || row['Monthly Rent'] || 0);

  const errors = [];
  if (!address) errors.push('Address is required');
  if (!landlordPartial) errors.push('Landlord Name is required');
  if (!rentRaw || isNaN(rentRaw)) errors.push('Monthly Rent is required');
  if (errors.length) return { error: errors.join('; ') };

  const landlord = landlords.find(l => l.name?.toLowerCase().includes(landlordPartial.toLowerCase()));
  if (!landlord) return { error: 'No landlord found matching "' + landlordPartial + '"' };

  const typeRaw = (row['Type (house/flat/studio/commercial/hmo)'] || '').toString().trim().toLowerCase();
  const type = VALID_TYPES.includes(typeRaw) ? typeRaw : 'flat';

  const statusRaw = (row['Status (occupied/vacant/maintenance)'] || '').toString().trim().toLowerCase();
  const status = VALID_STATUSES.includes(statusRaw) ? statusRaw : 'vacant';

  const bedrooms = parseInt(row['Bedrooms'] || 0) || undefined;
  const payment_day = parseInt(row['Payment Day (1-31)'] || 0) || undefined;
  const notes = (row['Notes'] || '').toString().trim() || undefined;

  const tenantName = (row['Tenant Name'] || '').toString().trim();
  const tenant = tenantName ? {
    name: tenantName,
    email: (row['Tenant Email'] || '').toString().trim() || undefined,
    phone: (row['Tenant Phone'] || '').toString().trim() || undefined,
    monthly_rent: parseFloat(row['Tenant Rent (£)'] || rentRaw) || rentRaw,
    lease_start: (row['Lease Start (YYYY-MM-DD)'] || '').toString().trim() || undefined,
    lease_end: (row['Lease End (YYYY-MM-DD)'] || '').toString().trim() || undefined,
    deposit: parseFloat(row['Deposit (£)'] || 0) || undefined,
    status: 'active',
  } : null;

  return { address, landlord_id: landlord.id, type, bedrooms, monthly_rent: rentRaw, status, payment_day, notes, _tenant: tenant };
}

