                        {TEMPLATE_COLS.map(c => <td key={c} className="px-3 py-1.5 whitespace-nowrap">{r[c] ?? ''}</td>)}
                      </tr>
                    ))}
                    {rows.length > 20 && <tr><td colSpan={TEMPLATE_COLS.length} className="px-3 py-2 text-muted-foreground italic">… and {rows.length - 20} more rows</td></tr>}
                  </tbody>
                </table>
              </div>
              <div className="flex justify-end gap-2">
                <Button variant="outline" onClick={reset}>Clear</Button>
                <Button onClick={handleImport} disabled={importing}>
                  {importing ? 'Importing…' : `Import ${rows.length} Tenants`}
                </Button>
              </div>
            </>
          )}

          {results && (
            <div className="space-y-3">
              {results.success.length > 0 && (
                <div className="flex items-start gap-2 rounded-lg bg-emerald-50 border border-emerald-200 px-4 py-3 text-sm text-emerald-700">
                  <CheckCircle className="w-4 h-4 mt-0.5 shrink-0" />
                  <span><strong>{results.success.length}</strong> tenant{results.success.length > 1 ? 's' : ''} imported successfully.</span>
                </div>
              )}
              {results.errors.length > 0 && (
                <div className="rounded-lg bg-red-50 border border-red-200 px-4 py-3 text-sm text-red-700 space-y-1">
                  <div className="flex items-center gap-2 font-semibold"><XCircle className="w-4 h-4" />{results.errors.length} row(s) failed:</div>
                  {results.errors.map((e, i) => <div key={i} className="pl-6 text-xs">Row {e.row}: {e.reason}</div>)}
                </div>
              )}
              <div className="flex justify-end gap-2">
                <Button variant="outline" onClick={reset}>Import More</Button>
                <Button onClick={() => { reset(); onClose(); }}>Done</Button>
              </div>
            </div>
          )}

          {rows.length === 0 && !results && (
            <div className="rounded-lg border-2 border-dashed border-border px-6 py-10 text-center text-sm text-muted-foreground">
              <AlertCircle className="w-8 h-8 mx-auto mb-2 opacity-40" />
              Download the template, fill it in, then upload it here.<br />
              <span className="text-xs">Columns marked * are required. Property address needs a partial match only.</span>
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

