export default function CarriedBalanceForm({ record, tenants, properties, onSubmit, onCancel, defaultTenantId }) {
  const [submitting, setSubmitting] = useState(false);
  const [data, setData] = useState(() => ({
    tenant_id: defaultTenantId || '',
    amount: '',
    as_of_date: format(new Date(), 'yyyy-MM-dd'),
    description: 'Outstanding balance carried forward',
    notes: '',
    is_cleared: false,
    ...(record || {}),
  }));

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (submitting) return;
    setSubmitting(true);
    try {
      const tenant = tenants.find(t => t.id === data.tenant_id);
      await onSubmit({
        ...data,
        amount: Number(data.amount),
        property_id: tenant?.property_id || data.property_id || '',
      });
    } finally { setSubmitting(false); }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <div className="space-y-2">
        <Label>Tenant *</Label>
        {defaultTenantId ? (
          <div className="flex items-center gap-2 rounded-md border border-border bg-muted/50 px-3 py-2 text-sm">
            <span className="font-medium">{tenants.find(t => t.id === defaultTenantId)?.name || defaultTenantId}</span>
            <span className="ml-auto text-xs text-muted-foreground">auto-selected</span>
          </div>
        ) : (
          <TenantCombobox tenants={tenants} properties={properties} value={data.tenant_id} onChange={v => setData(prev => ({ ...prev, tenant_id: v }))} />
        )}
      </div>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label>Amount Owed (£) *</Label>
          <Input type="number" min="0" step="0.01" value={data.amount} onChange={e => setData(prev => ({ ...prev, amount: e.target.value }))} required />
        </div>
        <div className="space-y-2">
          <Label>As Of Date *</Label>
          <Input type="date" value={data.as_of_date} onChange={e => setData(prev => ({ ...prev, as_of_date: e.target.value }))} required />
        </div>
      </div>
      <div className="space-y-2">
        <Label>Description *</Label>
        <Input value={data.description} onChange={e => setData(prev => ({ ...prev, description: e.target.value }))} required placeholder="e.g. Pre-existing arrears from previous system" />
      </div>
      <div className="space-y-2">
        <Label>Notes</Label>
        <Textarea value={data.notes || ''} onChange={e => setData(prev => ({ ...prev, notes: e.target.value }))} rows={2} />
      </div>
      {record && (
        <div className="space-y-2">
          <Label>Status</Label>
          <Select value={data.is_cleared ? 'cleared' : 'active'} onValueChange={v => setData(prev => ({ ...prev, is_cleared: v === 'cleared' }))}>
            <SelectTrigger><SelectValue /></SelectTrigger>
            <SelectContent>
              <SelectItem value="active">Active — appears on invoices</SelectItem>
              <SelectItem value="cleared">Cleared / Written off — excluded from invoices</SelectItem>
            </SelectContent>
          </Select>
        </div>
      )}
      <div className="rounded-lg bg-amber-50 border border-amber-200 px-4 py-3 text-xs text-amber-800">
        <strong>How this works:</strong> The amount will appear as an "Opening Balance" line item on the tenant's earliest invoice. As payments are recorded, the balance gets paid down naturally. Once fully cleared, mark this record as "Cleared".
      </div>
      <div className="flex gap-3 justify-end pt-2">
        <Button type="button" variant="outline" onClick={onCancel} disabled={submitting}>Cancel</Button>
        <Button type="submit" disabled={submitting || !data.tenant_id}>{submitting ? 'Saving...' : record ? 'Update' : 'Add Balance'}</Button>
      </div>
    </form>
  );
}

import React, { useState, useMemo } from 'react';
import { base44 } from '@/api/base44Client';
import { useQueryClient } from '@tanstack/react-query';
import { useRole } from '@/hooks/useRole';
import { logAction } from '@/lib/audit';
import { formatCurrency } from '@/lib/computations';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import StatusBadge from '@/components/ui/StatusBadge';
import StatCard from '@/components/ui/StatCard';
import ConfirmDialog from '@/components/ui/ConfirmDialog';
import CarriedBalanceForm from './CarriedBalanceForm';
import { Plus, Pencil, Trash2, Search, Wallet, AlertTriangle, CheckCircle2 } from 'lucide-react';
import { format, parseISO } from 'date-fns';

export default function CarriedBalancesTab({ tenants, properties, carriedBalances, defaultTenantId, defaultPropertyId }) {
  const { user, isAdmin } = useRole();
  const queryClient = useQueryClient();
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(null);
  const [search, setSearch] = useState('');
  const [showCleared, setShowCleared] = useState(false);

  // Apply scope filter (e.g. when used in property/tenant detail)
  const scopedBalances = useMemo(() => {
    let list = carriedBalances || [];
    if (defaultPropertyId) list = list.filter(b => b.property_id === defaultPropertyId);
    if (defaultTenantId) list = list.filter(b => b.tenant_id === defaultTenantId);
    return list;
  }, [carriedBalances, defaultPropertyId, defaultTenantId]);

  const filtered = useMemo(() => {
    return scopedBalances
      .filter(b => showCleared || !b.is_cleared)
      .filter(b => {
        if (!search) return true;
        const q = search.toLowerCase();
        const tenant = (tenants || []).find(t => t.id === b.tenant_id);
        return (tenant?.name || '').toLowerCase().includes(q) || (b.description || '').toLowerCase().includes(q);
      })
      .sort((a, b) => (b.as_of_date || '').localeCompare(a.as_of_date || ''));
  }, [scopedBalances, search, showCleared, tenants]);

  const totals = useMemo(() => {
    const active = scopedBalances.filter(b => !b.is_cleared);
    const cleared = scopedBalances.filter(b => b.is_cleared);
    return {
      activeCount: active.length,
      activeAmount: active.reduce((s, b) => s + (b.amount || 0), 0),
      clearedCount: cleared.length,
    };
  }, [scopedBalances]);

  const tenantName = (id) => (tenants || []).find(t => t.id === id)?.name || 'Unknown';
  const propertyAddr = (id) => (properties || []).find(p => p.id === id)?.address?.split(',')[0] || '—';

  const handleSubmit = async (data) => {
    if (editing) {
      await base44.entities.TenantCarriedBalance.update(editing.id, data);
      await logAction({ user, action: 'update', entityType: 'TenantCarriedBalance', entityId: editing.id, summary: `Updated carried balance for ${tenantName(data.tenant_id)}`, oldValue: editing, newValue: data });
    } else {
      const created = await base44.entities.TenantCarriedBalance.create(data);
      await logAction({ user, action: 'create', entityType: 'TenantCarriedBalance', entityId: created.id, summary: `Added carried balance ${formatCurrency(data.amount)} for ${tenantName(data.tenant_id)}`, newValue: data });
    }
    queryClient.invalidateQueries({ queryKey: ['tenant_carried_balances'] });
    setShowForm(false);
    setEditing(null);
  };

  const handleDelete = async (record) => {
    await base44.entities.TenantCarriedBalance.delete(record.id);
    await logAction({ user, action: 'delete', entityType: 'TenantCarriedBalance', entityId: record.id, summary: `Deleted carried balance for ${tenantName(record.tenant_id)}`, oldValue: record });
    queryClient.invalidateQueries({ queryKey: ['tenant_carried_balances'] });
    setConfirmDelete(null);
  };

  const toggleCleared = async (record) => {
    const newVal = !record.is_cleared;
    await base44.entities.TenantCarriedBalance.update(record.id, { is_cleared: newVal });
    await logAction({ user, action: 'update', entityType: 'TenantCarriedBalance', entityId: record.id, summary: `Marked carried balance as ${newVal ? 'cleared' : 'active'} for ${tenantName(record.tenant_id)}`, oldValue: record, newValue: { ...record, is_cleared: newVal } });
    queryClient.invalidateQueries({ queryKey: ['tenant_carried_balances'] });
  };

  return (
    <div>
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-6">
        <StatCard label="Active Balances" value={totals.activeCount} icon={Wallet} color="warning" />
        <StatCard label="Total Outstanding" value={formatCurrency(totals.activeAmount)} icon={AlertTriangle} color="destructive" />
        <StatCard label="Cleared Records" value={totals.clearedCount} icon={CheckCircle2} color="success" />
      </div>

      <div className="bg-card rounded-xl border border-border overflow-hidden">
        <div className="px-5 py-4 border-b border-border flex flex-wrap items-center justify-between gap-3">
          <div>
            <h2 className="text-sm font-semibold">Carried Forward Balances</h2>
            <p className="text-xs text-muted-foreground mt-0.5">Pre-existing or outstanding amounts that appear on the tenant's earliest invoice</p>
          </div>
          <div className="flex items-center gap-2">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
              <Input className="pl-9 h-9 w-48" placeholder="Search..." value={search} onChange={e => setSearch(e.target.value)} />
            </div>
            <Button variant="outline" size="sm" onClick={() => setShowCleared(s => !s)}>
              {showCleared ? 'Hide cleared' : 'Show cleared'}
            </Button>
            {isAdmin && (
              <Button size="sm" onClick={() => { setEditing(null); setShowForm(true); }}>
                <Plus className="w-4 h-4 mr-1" />Add Balance
              </Button>
            )}
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-muted/50">
                <th className="text-left px-4 py-3 font-medium text-muted-foreground">Tenant</th>
                <th className="text-left px-4 py-3 font-medium text-muted-foreground">Property</th>
                <th className="text-left px-4 py-3 font-medium text-muted-foreground">Description</th>
                <th className="text-left px-4 py-3 font-medium text-muted-foreground">As Of</th>
                <th className="text-right px-4 py-3 font-medium text-muted-foreground">Amount</th>
                <th className="text-left px-4 py-3 font-medium text-muted-foreground">Status</th>
                {isAdmin && <th className="px-4 py-3"></th>}
              </tr>
            </thead>
            <tbody>
              {filtered.map(b => (
                <tr key={b.id} className="border-t border-border hover:bg-muted/30 transition-colors">
                  <td className="px-4 py-3 font-medium">{tenantName(b.tenant_id)}</td>
                  <td className="px-4 py-3 text-xs text-muted-foreground">{propertyAddr(b.property_id)}</td>
                  <td className="px-4 py-3">{b.description}</td>
                  <td className="px-4 py-3 text-muted-foreground">{b.as_of_date ? format(parseISO(b.as_of_date), 'dd MMM yyyy') : '-'}</td>
                  <td className="px-4 py-3 text-right font-semibold text-red-600">{formatCurrency(b.amount)}</td>
                  <td className="px-4 py-3">
                    {b.is_cleared
                      ? <StatusBadge color="green">Cleared</StatusBadge>
                      : <StatusBadge color="yellow">Active</StatusBadge>}
                  </td>
                  {isAdmin && (
                    <td className="px-4 py-3">
                      <div className="flex gap-1">
                        <Button variant="ghost" size="sm" title={b.is_cleared ? 'Reactivate' : 'Mark as cleared'} onClick={() => toggleCleared(b)}>
                          <CheckCircle2 className={`w-4 h-4 ${b.is_cleared ? 'text-emerald-600' : 'text-muted-foreground'}`} />
                        </Button>
                        <Button variant="ghost" size="sm" onClick={() => { setEditing(b); setShowForm(true); }}>
                          <Pencil className="w-4 h-4" />
                        </Button>
                        <Button variant="ghost" size="sm" className="text-destructive hover:text-destructive" onClick={() => setConfirmDelete(b)}>
                          <Trash2 className="w-4 h-4" />
                        </Button>
                      </div>
                    </td>
                  )}
                </tr>
              ))}
              {filtered.length === 0 && (
                <tr><td colSpan={isAdmin ? 7 : 6} className="px-4 py-10 text-center text-muted-foreground">
                  No carried balances {showCleared ? '' : '— click "Add Balance" to record one'}
                </td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      <Dialog open={showForm} onOpenChange={v => { if (!v) { setShowForm(false); setEditing(null); } }}>
        <DialogContent className="max-w-lg">
          <DialogHeader><DialogTitle>{editing ? 'Edit Carried Balance' : 'Add Carried Balance'}</DialogTitle></DialogHeader>
          <CarriedBalanceForm
            record={editing}
            tenants={tenants}
            properties={properties}
            onSubmit={handleSubmit}
            onCancel={() => { setShowForm(false); setEditing(null); }}
            defaultTenantId={!editing ? defaultTenantId : undefined}
          />
        </DialogContent>
      </Dialog>

      <ConfirmDialog
        open={!!confirmDelete}
        title="Delete Carried Balance"
        description={`Permanently delete the carried balance of ${formatCurrency(confirmDelete?.amount)} for ${tenantName(confirmDelete?.tenant_id)}? Use 'Mark as cleared' instead if the balance has been paid.`}
        onConfirm={() => handleDelete(confirmDelete)}
        onCancel={() => setConfirmDelete(null)}
      />
    </div>
  );
}

import React, { useState } from 'react';
import { base44 } from '@/api/base44Client';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { useRole } from '@/hooks/useRole';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import ConfirmDialog from '@/components/ui/ConfirmDialog';
import StatusBadge from '@/components/ui/StatusBadge';
import { Checkbox } from '@/components/ui/checkbox';
import { Plus, Trash2, Pencil, Lock, Download, Copy } from 'lucide-react';
import { formatCurrency } from '@/lib/computations';
import { format, parseISO } from 'date-fns';
import jsPDF from 'jspdf';

const STATUS_COLORS = { draft: 'gray', sent: 'blue', paid: 'green', cancelled: 'red' };

function newLineItem(currentMonth) {
  return { property_id: '', period_month: currentMonth, description: '', amount: '' };
}

function migrateToLineItems(inv, currentMonth) {
  // If already has line_items, use them
  if (inv.line_items && inv.line_items.length > 0) return inv.line_items;
  // Migrate from legacy property_ids / property_amounts
  const ids = inv.property_ids || (inv.property_id ? [inv.property_id] : []);
  const amounts = inv.property_amounts || {};
  const descs = inv.property_descriptions || {};
  const month = (inv.period_months && inv.period_months[0]) || inv.period_month || currentMonth;
  if (ids.length > 0) {
    return ids.map(pid => ({
      property_id: pid,
      period_month: month,
      description: descs[pid] || '',
      amount: amounts[pid] || '',
    }));
  }
  return [newLineItem(month)];
}

function InvoiceForm({ tenants, properties, onSubmit, onCancel, initialData }) {
  const today = format(new Date(), 'yyyy-MM-dd');
  const currentMonth = format(new Date(), 'yyyy-MM');

  const [data, setData] = useState(() => ({
    invoice_number: '',
    tenant_id: '',
    invoice_date: today,
    description: '',
    status: 'draft',
    notes: '',
    ...(initialData || {}),
    line_items: initialData ? migrateToLineItems(initialData, currentMonth) : [newLineItem(currentMonth)],
  }));
  const [submitting, setSubmitting] = useState(false);

  const landlordProperties = properties.filter(p => !data.tenant_id || p.tenant_id === data.tenant_id);

  const totalAmount = (data.line_items || []).reduce((s, r) => s + (Number(r.amount) || 0), 0);

  const updateLine = (idx, field, val) => {
    setData(prev => {
      const lines = prev.line_items.map((r, i) => i === idx ? { ...r, [field]: val } : r);
      return { ...prev, line_items: lines };
    });
  };

  const addLine = () => {
    const lastMonth = data.line_items.length > 0
      ? data.line_items[data.line_items.length - 1].period_month
      : currentMonth;
    setData(prev => ({ ...prev, line_items: [...prev.line_items, newLineItem(lastMonth)] }));
  };

  const removeLine = (idx) => {
    setData(prev => ({ ...prev, line_items: prev.line_items.filter((_, i) => i !== idx) }));
  };

  const handleTenantChange = (v) => {
    const t = tenants.find(x => x.id === v);
    setData(prev => ({ ...prev, tenant_id: v, line_items: prev.line_items.map(l => ({ ...l, property_id: t?.property_id || '' })) }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (submitting) return;
    setSubmitting(true);
    const lines = data.line_items || [];
    const uniqueMonths = [...new Set(lines.map(l => l.period_month).filter(Boolean))].sort();
    const usedPropertyIds = [...new Set(lines.map(l => l.property_id).filter(Boolean))];
    try {
      await onSubmit({
        ...data,
        line_items: lines,
        amount: totalAmount,
        period_months: uniqueMonths,
        period_month: uniqueMonths[0] || '',
        property_ids: usedPropertyIds,
      });
    } finally { setSubmitting(false); }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label>Invoice Number</Label>
          <Input placeholder="e.g. INV-001" value={data.invoice_number} onChange={e => setData({ ...data, invoice_number: e.target.value })} />
        </div>
        <div className="space-y-2">
          <Label>Invoice Date *</Label>
          <Input type="date" value={data.invoice_date} onChange={e => setData({ ...data, invoice_date: e.target.value })} required />
        </div>
        <div className="space-y-2 sm:col-span-2">
          <Label>Tenant</Label>
          <select className="w-full h-9 rounded-md border border-input bg-background px-2 text-sm" value={data.tenant_id || ''} onChange={e => handleTenantChange(e.target.value)}>
            <option value="">Select tenant</option>
            {tenants.map(t => (<option key={t.id} value={t.id}>{t.name}{t.unit_description ? ` (${t.unit_description})` : ''}</option>))}
          </select>
        </div>
      </div>

      {/* Line items */}
      <div className="space-y-2">
        <Label>Line Items</Label>
        <div className="border border-border rounded-lg overflow-x-auto">
          <table className="w-full text-sm min-w-[560px]">
            <thead>
              <tr className="bg-muted/50 text-xs text-muted-foreground">
                <th className="text-left px-3 py-2 w-[34%]">Property</th>
                <th className="text-left px-3 py-2 w-[18%]">Period</th>
                <th className="text-left px-3 py-2 w-[32%]">Description</th>
                <th className="text-left px-3 py-2 w-[16%]">Amount (£)</th>
                <th className="px-2 py-2 w-8"></th>
              </tr>
            </thead>
            <tbody>
              {(data.line_items || []).map((line, idx) => (
                <tr key={idx} className="border-t border-border">
                  <td className="px-2 py-1.5">
                    <select
                      className="w-full h-8 rounded border border-input bg-background px-2 text-xs"
                      value={line.property_id || ''}
                      onChange={e => updateLine(idx, 'property_id', e.target.value)}
                    >
                      <option value="">— none —</option>
                      {landlordProperties.map(p => (
                        <option key={p.id} value={p.id}>{p.address}</option>
                      ))}
                    </select>
                  </td>
                  <td className="px-2 py-1.5">
                    <Input
                      type="month"
                      className="h-8 text-xs w-full"
                      value={line.period_month || ''}
                      onChange={e => updateLine(idx, 'period_month', e.target.value)}
                    />
                  </td>
                  <td className="px-2 py-1.5">
                    <Input
                      className="h-8 text-xs w-full min-w-[140px]"
                      placeholder="Description"
                      value={line.description || ''}
                      onChange={e => updateLine(idx, 'description', e.target.value)}
                    />
                  </td>
                  <td className="px-2 py-1.5">
                    <Input
                      type="number"
                      min="0"
                      step="0.01"
                      className="h-8 text-xs w-full min-w-[80px]"
                      placeholder="0.00"
                      value={line.amount || ''}
                      onChange={e => updateLine(idx, 'amount', e.target.value)}
                    />
                  </td>
                  <td className="px-2 py-1.5">
                    <Button type="button" variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-destructive" onClick={() => removeLine(idx)}>
                      <Trash2 className="w-3.5 h-3.5" />
                    </Button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          <div className="px-3 py-2 border-t border-border flex items-center justify-between">
            <Button type="button" variant="ghost" size="sm" onClick={addLine} className="text-xs h-7">
              <Plus className="w-3.5 h-3.5 mr-1" />Add line
            </Button>
            <span className="text-sm font-semibold">Total: £{totalAmount.toFixed(2)}</span>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div className="space-y-2 sm:col-span-2">
          <Label>Description *</Label>
          <Input placeholder="e.g. Management fee for May 2026" value={data.description} onChange={e => setData({ ...data, description: e.target.value })} required />
        </div>
        <div className="space-y-2">
          <Label>Status</Label>
          <Select value={data.status} onValueChange={v => setData({ ...data, status: v })}>
            <SelectTrigger><SelectValue /></SelectTrigger>
            <SelectContent>
              <SelectItem value="draft">Draft</SelectItem>
              <SelectItem value="sent">Sent</SelectItem>
              <SelectItem value="paid">Paid</SelectItem>
              <SelectItem value="cancelled">Cancelled</SelectItem>
            </SelectContent>
          </Select>
        </div>
        <div className="space-y-2 sm:col-span-2">
          <Label>Notes</Label>
          <Textarea rows={2} value={data.notes} onChange={e => setData({ ...data, notes: e.target.value })} />
        </div>
      </div>
      <div className="flex gap-3 justify-end pt-2">
        {onCancel && <Button type="button" variant="outline" onClick={onCancel} disabled={submitting}>Cancel</Button>}
        <Button type="submit" disabled={submitting}>{submitting ? 'Saving...' : initialData ? 'Save Changes' : 'Create Invoice'}</Button>
      </div>
    </form>
  );
}

export default function TenantManualInvoicesTab({ tenants, properties }) {
  const { isAdmin } = useRole();
  const queryClient = useQueryClient();
  const [showForm, setShowForm] = useState(false);
  const [editInvoice, setEditInvoice] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(null);
  const [duplicateSource, setDuplicateSource] = useState(null);

  const { data: invoices = [] } = useQuery({
    queryKey: ['tenant_manual_invoices'],
    queryFn: () => base44.entities.TenantManualInvoice.list('-invoice_date', 200),
    placeholderData: [],
  });

  const getTenantName = (id) => tenants.find(l => l.id === id)?.name || '—';
  const getPropertyAddress = (id) => properties.find(p => p.id === id)?.address || '—';

  const getPropertiesLabel = (inv) => {
    const ids = inv.property_ids || (inv.property_id ? [inv.property_id] : []);
    if (ids.length === 0) return '—';
    if (ids.length === 1) return getPropertyAddress(ids[0]);
    return `${ids.length} properties`;
  };

  const handleCreate = async (data) => {
    await base44.entities.TenantManualInvoice.create(data);
    queryClient.invalidateQueries({ queryKey: ['tenant_manual_invoices'] });
    setShowForm(false);
  };

  const handleEdit = async (data) => {
    await base44.entities.TenantManualInvoice.update(editInvoice.id, data);
    queryClient.invalidateQueries({ queryKey: ['tenant_manual_invoices'] });
    setEditInvoice(null);
  };
const handleDuplicate = (inv) => {
    // Strip server-generated/identity fields so it's saved as a NEW invoice.
    // Keep all the content (landlord, properties, amounts, descriptions) so user just edits what's different.
    const { id, invoice_number, created_date, updated_date, created_by, updated_by, ...rest } = inv;
    setDuplicateSource({
      ...rest,
      property_ids: inv.property_ids || (inv.property_id ? [inv.property_id] : []),
      invoice_date: new Date().toISOString().slice(0, 10),  // default to today
      status: 'issued',                                      // reset status
    });
    setShowForm(true);
  };
  const handleDelete = async () => {
    const id = confirmDelete?.id;
    if (!id) return;
    setConfirmDelete(null);
    await base44.entities.TenantManualInvoice.delete(id);
    queryClient.invalidateQueries({ queryKey: ['tenant_manual_invoices'] });
  };

  const handleStatusChange = async (invoice, newStatus) => {
    await base44.entities.TenantManualInvoice.update(invoice.id, { status: newStatus });
    queryClient.invalidateQueries({ queryKey: ['tenant_manual_invoices'] });
  };

  // Normalize old single property_id to property_ids when editing
  const normalizeForEdit = (inv) => ({
    ...inv,
    property_ids: inv.property_ids || (inv.property_id ? [inv.property_id] : []),
  });

  const downloadPDF = async (inv) => {
    const LOGO_URL = 'https://media.base44.com/images/public/69bbedde54616d2e6e0c7394/55bf25b3e_Logo.png';
    const BRAND_PRIMARY = [50, 50, 50];

    // Load logo
    const logoDataUrl = await new Promise((resolve) => {
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = () => {
        const canvas = document.createElement('canvas');
        canvas.width = img.width; canvas.height = img.height;
        canvas.getContext('2d').drawImage(img, 0, 0);
        resolve(canvas.toDataURL('image/png'));
      };
      img.onerror = () => resolve(null);
      img.src = LOGO_URL;
    });

    const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
    const tenant = tenants.find(t => t.id === inv.tenant_id);
    const propIds = inv.property_ids || (inv.property_id ? [inv.property_id] : []);
    const propAmounts = inv.property_amounts || {};
    const propDescs = inv.property_descriptions || {};
    const invDate = inv.invoice_date ? format(parseISO(inv.invoice_date), 'dd MMM yyyy') : format(new Date(), 'dd MMM yyyy');
    const fmtC = (v) => new Intl.NumberFormat('en-GB', { style: 'currency', currency: 'GBP' }).format(v || 0);

    // --- Header (white bar with logo) ---
    doc.setFillColor(255, 255, 255);
    doc.rect(0, 0, 210, 28, 'F');
    doc.setDrawColor(200, 200, 200);
    doc.setLineWidth(0.5);
    doc.line(0, 28, 210, 28);
    if (logoDataUrl) {
      doc.addImage(logoDataUrl, 'PNG', 14, 2, 40, 24);
    } else {
      doc.setFontSize(18); doc.setFont('helvetica', 'bold'); doc.setTextColor(50, 50, 50);
      doc.text('ASA Estates Ltd', 14, 12);
      doc.setFontSize(8); doc.setFont('helvetica', 'normal'); doc.setTextColor(100, 100, 100);
      doc.text('Professional Property Management', 14, 18);
    }

    // Company details next to logo
    doc.setFontSize(8); doc.setFont('helvetica', 'normal'); doc.setTextColor(60, 60, 60);
    doc.setFont('helvetica', 'bold');
    doc.text('ASA Estates Ltd.', 58, 8);
    doc.setFont('helvetica', 'normal');
    doc.text('320 Romford Road, London, E7 8BD', 58, 13);
    doc.text('Ph: 02084724466 | Fax: 02084724466', 58, 17);
    doc.text('Email: info@asaestates.com', 58, 21);

    // Title
    doc.setFontSize(22); doc.setFont('helvetica', 'bold'); doc.setTextColor(...BRAND_PRIMARY);
    doc.text('INVOICE', 14, 42);

    doc.setFontSize(10); doc.setFont('helvetica', 'normal'); doc.setTextColor(80, 80, 80);
    doc.text(`${inv.invoice_number || '—'}`, 14, 50);
    doc.text(`Date: ${invDate}`, 130, 42);
    doc.setDrawColor(...BRAND_PRIMARY); doc.setLineWidth(0.5);
    doc.line(14, 55, 196, 55);

    // Status badge
    let y = 62;
    const statusColors = { draft: [100,100,100], sent: [37,99,235], paid: [16,185,129], cancelled: [239,68,68] };
    const [sr, sg, sb] = statusColors[inv.status] || [100,100,100];
    doc.setFillColor(sr, sg, sb);
    doc.roundedRect(14, y, 28, 8, 2, 2, 'F');
    doc.setFont('helvetica', 'bold'); doc.setFontSize(9); doc.setTextColor(255, 255, 255);
    doc.text((inv.status || 'draft').toUpperCase(), 28, y + 5.5, { align: 'center' });
    y += 16;

    // Info block
    doc.setFontSize(9); doc.setFont('helvetica', 'bold'); doc.setTextColor(...BRAND_PRIMARY);
    doc.text('BILLED TO', 14, y);
    doc.text('INVOICE DETAILS', 110, y);
    doc.setFont('helvetica', 'normal'); doc.setTextColor(60, 60, 60);
    let ly = y + 6;
    const billedLines = [];
    [tenant?.name || '—', tenant?.email || '', tenant?.phone || '']
      .filter(Boolean)
      .forEach(v => { doc.splitTextToSize(String(v), 88).forEach(s => billedLines.push(s)); });
    billedLines.forEach(line => { doc.text(line, 14, ly); ly += 5; });

    let ry = y + 6;
    const months = (inv.period_months && inv.period_months.length > 0)
      ? [...inv.period_months].sort()
      : (inv.period_month ? [inv.period_month] : []);
    let periodLabel;
    if (months.length === 0) periodLabel = '—';
    else if (months.length <= 3) periodLabel = months.join(', ');
    else periodLabel = `${months[0]} to ${months[months.length - 1]} (${months.length} months)`;
    const detailLines = [`Invoice No: ${inv.invoice_number || '—'}`];
    doc.splitTextToSize(`Period: ${periodLabel}`, 86).forEach(s => detailLines.push(s));
    detailLines.push(`Status: ${(inv.status || '').toUpperCase()}`);
    detailLines.forEach(line => { doc.text(line, 110, ry); ry += 5; });
    y = Math.max(ly, ry) + 8;

    // Description
    doc.setFontSize(9); doc.setFont('helvetica', 'bold'); doc.setTextColor(...BRAND_PRIMARY);
    doc.text('DESCRIPTION', 14, y); y += 4;
    doc.setFont('helvetica', 'normal'); doc.setTextColor(60, 60, 60); doc.setFontSize(9);
    doc.text(inv.description || '—', 14, y + 5.5); y += 12;

    // Line items table
    const lineItems = inv.line_items && inv.line_items.length > 0
      ? inv.line_items
      : propIds.map(pid => ({ property_id: pid, description: propDescs[pid] || '—', amount: propAmounts[pid] || 0, period_month: inv.period_month || '' }));

    if (lineItems.length > 0) {
      doc.setFontSize(9); doc.setFont('helvetica', 'bold'); doc.setTextColor(...BRAND_PRIMARY);
      doc.text('BREAKDOWN', 14, y); y += 4;

      const colX = [14, 80, 124, 156];
      const colWidths = [64, 42, 30, 40];
      doc.setFillColor(245, 247, 255);
      doc.rect(14, y, 182, 8, 'F');
      doc.setFontSize(8.5); doc.setFont('helvetica', 'bold'); doc.setTextColor(...BRAND_PRIMARY);
      doc.text('Property', colX[0] + 2, y + 5.5);
      doc.text('Period', colX[1] + 2, y + 5.5);
      doc.text('Description', colX[2] + 2, y + 5.5);
      doc.text('Amount', colX[3] + colWidths[3] - 2, y + 5.5, { align: 'right' });
      y += 8;

      doc.setFont('helvetica', 'normal'); doc.setTextColor(50, 50, 50);
      lineItems.forEach((line, ri) => {
        const addr = line.property_id ? getPropertyAddress(line.property_id) : '—';
        const period = line.period_month || '—';
        const desc = line.description || '—';
        const amt = line.amount ? fmtC(Number(line.amount)) : '—';
        const addrLines = doc.splitTextToSize(addr, colWidths[0] - 4);
        const descLines = doc.splitTextToSize(desc, colWidths[2] - 4);
        const rowH = Math.max(addrLines.length, descLines.length) * 5 + 4;
        if (ri % 2 === 0) { doc.setFillColor(252, 252, 255); doc.rect(14, y, 182, rowH, 'F'); }
        doc.setFontSize(8.5);
        doc.text(addrLines, colX[0] + 2, y + 5);
        doc.text(period, colX[1] + 2, y + 5);
        doc.text(descLines, colX[2] + 2, y + 5);
        doc.text(amt, colX[3] + colWidths[3] - 2, y + 5, { align: 'right' });
        y += rowH;
      });
      doc.setDrawColor(200, 210, 240); doc.setLineWidth(0.3);
      doc.line(14, y, 196, y);
      y += 4;
    }

    // Totals box
    const boxW = 90, boxX = 196 - boxW;
    y += 4;
    doc.setFont('helvetica', 'bold'); doc.setFillColor(...BRAND_PRIMARY);
    doc.rect(boxX - 2, y - 4, boxW + 4, 8, 'F');
    doc.setTextColor(255, 255, 255); doc.setFontSize(9);
    doc.text('TOTAL', boxX + 2, y);
    doc.text(fmtC(inv.amount), 194, y, { align: 'right' });
    y += 12;

    // Notes
    if (inv.notes) {
      doc.setFontSize(9); doc.setFont('helvetica', 'bold'); doc.setTextColor(...BRAND_PRIMARY);
      doc.text('NOTES', 14, y); y += 5;
      doc.setFont('helvetica', 'normal'); doc.setTextColor(60, 60, 60);
      const lines = doc.splitTextToSize(inv.notes, 182);
      doc.text(lines, 14, y);
    }

    // Footer
    const pageH = doc.internal.pageSize.height;
    doc.setFillColor(255, 255, 255);
    doc.rect(0, pageH - 14, 210, 14, 'F');
    doc.setFontSize(7.5); doc.setFont('helvetica', 'normal'); doc.setTextColor(130, 130, 160);
    doc.text(`ASA Estates Ltd · Generated ${format(new Date(), 'dd MMM yyyy HH:mm')}`, 14, pageH - 5);
    doc.text('This is a system-generated document', 196, pageH - 5, { align: 'right' });

    doc.save(`Invoice_${inv.invoice_number || inv.id}.pdf`);
  };

  return (
    <div>
      <div className="flex justify-between items-center mb-4">
        <p className="text-sm text-muted-foreground">{invoices.length} invoice{invoices.length !== 1 ? 's' : ''}</p>
        {isAdmin
          ? <Button size="sm" onClick={() => setShowForm(true)}><Plus className="w-4 h-4 mr-1" />New Invoice</Button>
          : <span className="text-xs text-muted-foreground flex items-center gap-1"><Lock className="w-3 h-3" />Admin only</span>
        }
      </div>

      <div className="bg-card rounded-xl border border-border overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-muted/50">
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Invoice #</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Date</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Tenant</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Properties</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Period</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Description</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Amount</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Status</th>
                {isAdmin && <th className="text-left px-5 py-3 font-medium text-muted-foreground">Actions</th>}
              </tr>
            </thead>
            <tbody>
              {invoices.map(inv => (
                <tr key={inv.id} className="border-t border-border hover:bg-muted/30 transition-colors">
                  <td className="px-5 py-3 font-mono text-xs text-muted-foreground">{inv.invoice_number || '—'}</td>
                  <td className="px-5 py-3 text-muted-foreground whitespace-nowrap">
                    {inv.invoice_date ? format(parseISO(inv.invoice_date), 'dd MMM yyyy') : '—'}
                  </td>
                  <td className="px-5 py-3 font-medium">{getTenantName(inv.tenant_id)}</td>
                  <td className="px-5 py-3 text-muted-foreground text-xs max-w-[160px] truncate" title={
                    (inv.property_ids || []).map(id => getPropertyAddress(id)).join(', ')
                  }>
                    {getPropertiesLabel(inv)}
                  </td>
                  <td className="px-5 py-3 text-muted-foreground text-xs">
                    {(() => {
                      const ms = (inv.period_months && inv.period_months.length > 0) ? [...inv.period_months].sort() : (inv.period_month ? [inv.period_month] : []);
                      if (ms.length === 0) return '—';
                      if (ms.length <= 3) return ms.join(', ');
                      return `${ms[0]} to ${ms[ms.length - 1]} (${ms.length})`;
                    })()}
                  </td>
                  <td className="px-5 py-3 max-w-[200px] truncate" title={inv.description}>{inv.description}</td>
                  <td className="px-5 py-3 font-semibold">{formatCurrency(inv.amount)}</td>
                  <td className="px-5 py-3">
                    {isAdmin ? (
                      <Select value={inv.status} onValueChange={v => handleStatusChange(inv, v)}>
                        <SelectTrigger className="h-7 text-xs w-28 border-0 shadow-none p-0 bg-transparent focus:ring-0">
                          <StatusBadge color={STATUS_COLORS[inv.status]}>{inv.status}</StatusBadge>
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="draft">Draft</SelectItem>
                          <SelectItem value="sent">Sent</SelectItem>
                          <SelectItem value="paid">Paid</SelectItem>
                          <SelectItem value="cancelled">Cancelled</SelectItem>
                        </SelectContent>
                      </Select>
                    ) : (
                      <StatusBadge color={STATUS_COLORS[inv.status]}>{inv.status}</StatusBadge>
                    )}
                  </td>
                  {isAdmin && (
                    <td className="px-5 py-3">
                      <div className="flex gap-1">
                        <Button variant="ghost" size="sm" title="Download PDF" onClick={() => downloadPDF(inv)}><Download className="w-4 h-4" /></Button>
                        <Button variant="ghost" size="sm" title="Duplicate" onClick={() => handleDuplicate(inv)}><Copy className="w-4 h-4" /></Button>
                        <Button variant="ghost" size="sm" title="Edit" onClick={() => setEditInvoice(normalizeForEdit(inv))}><Pencil className="w-4 h-4" /></Button>
                        <Button variant="ghost" size="sm" title="Delete" className="text-destructive hover:text-destructive" onClick={() => setConfirmDelete(inv)}><Trash2 className="w-4 h-4" /></Button>
                      </div>
                    </td>
                  )}
                </tr>
              ))}
              {invoices.length === 0 && (
                <tr><td colSpan={isAdmin ? 9 : 8} className="px-5 py-10 text-center text-muted-foreground">No manual invoices yet</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Create */}
       <Dialog
        open={showForm}
        onOpenChange={(v) => { setShowForm(v); if (!v) setDuplicateSource(null); }}
      >
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>{duplicateSource ? 'Duplicate Invoice' : 'Create Manual Invoice'}</DialogTitle>
          </DialogHeader>
          <InvoiceForm
            tenants={tenants}
            properties={properties}
            initialData={duplicateSource || undefined}
            onSubmit={async (data) => { await handleCreate(data); setDuplicateSource(null); }}
            onCancel={() => { setShowForm(false); setDuplicateSource(null); }}
          />
        </DialogContent>
      </Dialog>

      {/* Edit */}
      <Dialog open={!!editInvoice} onOpenChange={v => { if (!v) setEditInvoice(null); }}>
        <DialogContent className="max-w-2xl">
          <DialogHeader><DialogTitle>Edit Invoice</DialogTitle></DialogHeader>
          {editInvoice && (
            <InvoiceForm
              tenants={tenants}
              properties={properties}
              onSubmit={handleEdit}
              onCancel={() => setEditInvoice(null)}
              initialData={editInvoice}
            />
          )}
        </DialogContent>
      </Dialog>

      <ConfirmDialog
        open={!!confirmDelete}
        title="Delete Invoice"
        description={`Delete invoice "${confirmDelete?.invoice_number || confirmDelete?.description}"? This cannot be undone.`}
        onConfirm={handleDelete}
        onCancel={() => setConfirmDelete(null)}
      />
    </div>
  );
}

import React from 'react';
import { format, parseISO } from 'date-fns';
import { formatCurrency } from '@/lib/computations';
import { ArrowRight, TrendingUp, TrendingDown, Minus } from 'lucide-react';

const fmtRate = (r) => {
  if (!r) return '—';
  return r.commission_type === 'percentage' ? `${r.commission_value}%` : formatCurrency(r.commission_value);
};
const fmtDate = (d) => (d ? format(parseISO(d), 'dd MMM yyyy') : '—');

export default function CommissionChanges({ records, properties }) {
  if (!records || records.length === 0) {
    return <p className="text-sm text-muted-foreground">No commission set yet.</p>;
  }

  // group by property (null = applies to all properties)
  const groups = {};
  records.forEach((r) => {
    const k = r.property_id || 'all';
    (groups[k] = groups[k] || []).push(r);
  });

  const rows = Object.entries(groups).map(([k, list]) => {
    const sorted = [...list].sort((a, b) => (a.start_date || '').localeCompare(b.start_date || ''));
    const current = sorted[sorted.length - 1];
    const previous = sorted.length > 1 ? sorted[sorted.length - 2] : null;
    const prop = k === 'all' ? null : properties?.find((p) => p.id === k);
    return { key: k, propLabel: prop ? prop.address : 'All properties', current, previous };
  });

  const changeInfo = (prev, curr) => {
    if (!prev || !curr || prev.commission_type !== 'percentage' || curr.commission_type !== 'percentage') return null;
    const a = Number(prev.commission_value) || 0;
    const b = Number(curr.commission_value) || 0;
    if (b > a) return { label: `Up ${Math.round((b - a) * 100) / 100}%`, color: 'text-emerald-600', Icon: TrendingUp };
    if (b < a) return { label: `Down ${Math.round((a - b) * 100) / 100}%`, color: 'text-red-600', Icon: TrendingDown };
    return { label: 'No change', color: 'text-muted-foreground', Icon: Minus };
  };

  return (
    <div className="space-y-3">
      {rows.map((row) => {
        const change = changeInfo(row.previous, row.current);
        return (
          <div key={row.key} className="bg-card border border-border rounded-xl p-4">
            <p className="text-sm font-medium mb-3">{row.propLabel}</p>
            <div className="flex items-center gap-3 sm:gap-5 flex-wrap">
              {/* Previous */}
              <div className="flex-1 min-w-[120px]">
                <p className="text-[11px] uppercase tracking-wide text-muted-foreground mb-0.5">Previous</p>
                <p className="text-xl font-bold text-muted-foreground">{fmtRate(row.previous)}</p>
                {row.previous && (
                  <p className="text-[11px] text-muted-foreground">
                    {fmtDate(row.previous.start_date)}{row.previous.end_date ? ` – ${fmtDate(row.previous.end_date)}` : ''}
                  </p>
                )}
              </div>

              <ArrowRight className="w-5 h-5 text-muted-foreground shrink-0" />

              {/* New / current */}
              <div className="flex-1 min-w-[120px]">
                <p className="text-[11px] uppercase tracking-wide text-primary mb-0.5">New (current)</p>
                <p className="text-xl font-bold text-primary">{fmtRate(row.current)}</p>
                <p className="text-[11px] text-muted-foreground">
                  From {fmtDate(row.current.start_date)}{row.current.end_date ? ` – ${fmtDate(row.current.end_date)}` : ''}
                </p>
              </div>

              {/* Change badge */}
              {change && (
                <div className={`flex items-center gap-1 text-xs font-semibold ${change.color}`}>
                  <change.Icon className="w-4 h-4" /> {change.label}
                </div>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

import React from 'react';
import { format, parseISO, isAfter } from 'date-fns';
import { formatCurrency } from '@/lib/computations';
import StatusBadge from '@/components/ui/StatusBadge';

export default function CommissionHistoryTable({ records, properties }) {
  if (!records || records.length === 0) {
    return <p className="text-sm text-muted-foreground">No commission history recorded yet.</p>;
  }

  const today = new Date();
  const sorted = [...records].sort((a, b) => b.start_date.localeCompare(a.start_date));

  const getStatus = (r) => {
    const start = parseISO(r.start_date);
    if (r.end_date) return { label: 'Past', color: 'gray' };
    if (isAfter(start, today)) return { label: 'Scheduled', color: 'yellow' };
    return { label: 'Active', color: 'green' };
  };

  return (
    <div className="bg-card rounded-xl border border-border overflow-hidden">
      <table className="w-full text-sm">
        <thead>
          <tr className="bg-muted/50">
            <th className="text-left px-4 py-3 font-medium text-muted-foreground">Rate</th>
            <th className="text-left px-4 py-3 font-medium text-muted-foreground">Type</th>
            <th className="text-left px-4 py-3 font-medium text-muted-foreground">Property</th>
            <th className="text-left px-4 py-3 font-medium text-muted-foreground">From</th>
            <th className="text-left px-4 py-3 font-medium text-muted-foreground">To</th>
            <th className="text-left px-4 py-3 font-medium text-muted-foreground">Status</th>
          </tr>
        </thead>
        <tbody>
          {sorted.map(r => {
            const status = getStatus(r);
            const prop = properties?.find(p => p.id === r.property_id);
            return (
              <tr key={r.id} className="border-t border-border hover:bg-muted/20 transition-colors">
                <td className="px-4 py-3 font-semibold">
                  {r.commission_type === 'percentage' ? `${r.commission_value}%` : formatCurrency(r.commission_value)}
                </td>
                <td className="px-4 py-3 text-muted-foreground capitalize">{r.commission_type?.replace(/_/g, ' ')}</td>
                <td className="px-4 py-3 text-muted-foreground text-xs">{prop ? prop.address : 'All properties'}</td>
                <td className="px-4 py-3 text-muted-foreground">{format(parseISO(r.start_date), 'dd MMM yyyy')}</td>
                <td className="px-4 py-3 text-muted-foreground">{r.end_date ? format(parseISO(r.end_date), 'dd MMM yyyy') : '—'}</td>
                <td className="px-4 py-3"><StatusBadge color={status.color}>{status.label}</StatusBadge></td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

import React, { useState } from 'react';
import { base44 } from '@/api/base44Client';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { format, subDays, parseISO } from 'date-fns';
import { Percent } from 'lucide-react';
import { formatCurrency } from '@/lib/computations';

export default function CommissionUpdateModal({ open, onClose, landlord, properties, currentAgreement, onSuccess }) {
  const [form, setForm] = useState({
    property_id: '',
    commission_type: 'percentage',
    commission_value: '',
    start_date: format(new Date(), 'yyyy-MM-dd'),
    notes: '',
  });
  const [saving, setSaving] = useState(false);

  const update = (k, v) => setForm(f => ({ ...f, [k]: v }));

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (saving) return;
    setSaving(true);

    const newStart = form.start_date;
    const propId = form.property_id || null;

    // Close existing active commission history records for this landlord/property
    const existing = await base44.entities.CommissionHistory.filter({ landlord_id: landlord.id });
    const active = existing.filter(r =>
      !r.end_date &&
      (propId ? r.property_id === propId : !r.property_id)
    );

    if (active.length > 0) {
      const endDate = format(subDays(parseISO(newStart), 1), 'yyyy-MM-dd');
      await Promise.all(active.map(r => base44.entities.CommissionHistory.update(r.id, { end_date: endDate })));
    }

    // Create new commission history record
    await base44.entities.CommissionHistory.create({
      landlord_id: landlord.id,
      property_id: propId,
      commission_type: form.commission_type,
      commission_value: Number(form.commission_value),
      start_date: newStart,
      end_date: null,
      notes: form.notes || null,
    });

    // Also update the CommissionAgreement record if one exists
    if (currentAgreement) {
      await base44.entities.CommissionAgreement.update(currentAgreement.id, {
        type: form.commission_type,
        value: Number(form.commission_value),
      });
    } else {
      // Create a new CommissionAgreement
      await base44.entities.CommissionAgreement.create({
        landlord_id: landlord.id,
        property_id: propId || undefined,
        type: form.commission_type,
        value: Number(form.commission_value),
        notes: form.notes || undefined,
      });
    }

    setSaving(false);
    onSuccess?.();
    onClose();
  };

  return (
    <Dialog open={open} onOpenChange={v => { if (!v) onClose(); }}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Percent className="w-5 h-5 text-primary" />
            Update Commission — {landlord?.name}
          </DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4">
          {currentAgreement && (
            <div className="bg-muted/40 border border-border rounded-lg px-4 py-3 text-sm">
              <p className="text-muted-foreground">
                Current: <span className="font-semibold text-foreground">
                  {currentAgreement.type === 'percentage' ? `${currentAgreement.value}%` : formatCurrency(currentAgreement.value)} ({currentAgreement.type?.replace(/_/g, ' ')})
                </span>
              </p>
            </div>
          )}
          <div className="space-y-1">
            <Label>Property (leave blank for all)</Label>
            <Select value={form.property_id} onValueChange={v => update('property_id', v)}>
              <SelectTrigger><SelectValue placeholder="All properties" /></SelectTrigger>
              <SelectContent>
                <SelectItem value={null}>All properties</SelectItem>
                {properties.map(p => (
                  <SelectItem key={p.id} value={p.id}>{p.address}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1">
              <Label>Commission Type *</Label>
              <Select value={form.commission_type} onValueChange={v => update('commission_type', v)}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="percentage">Percentage (%)</SelectItem>
                  <SelectItem value="fixed_monthly">Fixed Monthly (£)</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1">
              <Label>{form.commission_type === 'percentage' ? 'Percentage (%)' : 'Amount (£)'} *</Label>
              <Input
                type="number"
                min="0"
                step="0.01"
                placeholder={form.commission_type === 'percentage' ? 'e.g. 10' : 'e.g. 150'}
                value={form.commission_value}
                onChange={e => update('commission_value', e.target.value)}
                required
              />
            </div>
          </div>
          <div className="space-y-1">
            <Label>Effective Start Date *</Label>
            <Input
              type="date"
              value={form.start_date}
              onChange={e => update('start_date', e.target.value)}
              required
            />
            <p className="text-xs text-muted-foreground">Previous agreement will automatically close the day before.</p>
          </div>
          <div className="space-y-1">
            <Label>Notes (optional)</Label>
            <Input
              placeholder="Reason for change..."
              value={form.notes}
              onChange={e => update('notes', e.target.value)}
            />
          </div>
          <div className="flex justify-end gap-2 pt-2">
            <Button type="button" variant="outline" onClick={onClose}>Cancel</Button>
            <Button type="submit" disabled={saving}>{saving ? 'Saving...' : 'Apply Update'}</Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState } from 'react';
