function LandlordCombobox({ landlords, value, onChange }) {
  const [open, setOpen] = useState(false);
  const selected = landlords.find(l => l.id === value);
  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button variant="outline" role="combobox" className="w-full justify-between font-normal">
          {selected ? selected.name : 'Search landlord...'}
          <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-full p-0" align="start">
        <Command>
          <CommandInput placeholder="Type a name..." />
          <CommandList>
            <CommandEmpty>No landlord found.</CommandEmpty>
            <CommandGroup>
              {landlords.map(l => (
                <CommandItem key={l.id} value={l.name} onSelect={() => { onChange(l.id); setOpen(false); }}>
                  <Check className={`mr-2 h-4 w-4 ${value === l.id ? 'opacity-100' : 'opacity-0'}`} />
                  {l.name}
