const CATEGORIES = ['maintenance', 'certificate', 'repairs', 'insurance', 'cleaning', 'other'];

const MONTHS = [
  { value: '01', label: 'January' }, { value: '02', label: 'February' },
  { value: '03', label: 'March' },   { value: '04', label: 'April' },
  { value: '05', label: 'May' },     { value: '06', label: 'June' },
  { value: '07', label: 'July' },    { value: '08', label: 'August' },
  { value: '09', label: 'September'},{ value: '10', label: 'October' },
  { value: '11', label: 'November'}, { value: '12', label: 'December' },
];

const YEARS = Array.from({ length: 15 }, (_, i) => String(new Date().getFullYear() - 5 + i));

function PeriodPicker({ value, onChange }) {
  const parts = (value || format(new Date(), 'yyyy-MM')).split('-');
  const [month, setMonth] = React.useState(parts[1] || format(new Date(), 'MM'));
  const [year, setYear]   = React.useState(parts[0] || String(new Date().getFullYear()));

  React.useEffect(() => {
    if (!value) return;
    const p = value.split('-');
    setMonth(p[1] || format(new Date(), 'MM'));
    setYear(p[0] || String(new Date().getFullYear()));
  }, [value]);

  const handleMonth = (m) => { setMonth(m); onChange(`${year}-${m}`); };
  const handleYear  = (y) => { setYear(y);  onChange(`${y}-${month}`); };

  return (
    <div className="flex gap-2">
      <Select value={month} onValueChange={handleMonth}>
        <SelectTrigger className="flex-1"><SelectValue placeholder="Month" /></SelectTrigger>
        <SelectContent>
          {MONTHS.map(m => <SelectItem key={m.value} value={m.value}>{m.label}</SelectItem>)}
        </SelectContent>
      </Select>
      <Select value={year} onValueChange={handleYear}>
        <SelectTrigger className="w-28"><SelectValue placeholder="Year" /></SelectTrigger>
        <SelectContent>
          {YEARS.map(y => <SelectItem key={y} value={y}>{y}</SelectItem>)}
        </SelectContent>
      </Select>
    </div>
  );
}

function ExtraForm({ extra, landlords, properties, onSubmit, onCancel, defaultLandlordId, defaultPropertyId, coOwnerShares = [] }) {
  const [submitting, setSubmitting] = useState(false);
  const [data, setData] = useState(() => ({
    landlord_id: defaultLandlordId || '', property_id: defaultPropertyId || '', description: '', amount: '',
    date: format(new Date(), 'yyyy-MM-dd'),
    period_month: format(new Date(), 'yyyy-MM'),
    category: 'other', notes: '',
    ...(extra || {}),
    // ensure period_month is always set even on old records without it
    period_month: extra?.period_month || (extra?.date ? extra.date.substring(0, 7) : format(new Date(), 'yyyy-MM')),
  }));

  const landlordProperties = properties.filter(p => p.landlord_id === data.landlord_id);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (submitting) return;
    setSubmitting(true);
    try { await onSubmit({ ...data, amount: Number(data.amount) }); } finally { setSubmitting(false); }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label>Landlord *</Label>
          {defaultLandlordId ? (
            <div className="flex items-center gap-2 rounded-md border border-border bg-muted/50 px-3 py-2 text-sm">
              <span className="font-medium">{landlords.find(l => l.id === defaultLandlordId)?.name || defaultLandlordId}</span>
              <span className="ml-auto text-xs text-muted-foreground">auto-selected</span>
            </div>
          ) : (
            <LandlordCombobox landlords={landlords} value={data.landlord_id} onChange={v => setData(prev => ({ ...prev, landlord_id: v, property_id: '' }))} />
          )}
        </div>
        <div className="space-y-2">
          <Label>Property (optional)</Label>
          {defaultPropertyId ? (
            <div className="flex items-center gap-2 rounded-md border border-border bg-muted/50 px-3 py-2 text-sm">
              <span className="font-medium">{properties.find(p => p.id === defaultPropertyId)?.address?.split(',')[0] || defaultPropertyId}</span>
              <span className="ml-auto text-xs text-muted-foreground">auto-selected</span>
            </div>
          ) : (
            <PropertyCombobox
              properties={landlordProperties}
              value={data.property_id || ''}
              onChange={v => setData(prev => ({ ...prev, property_id: v }))}
              placeholder={data.landlord_id ? 'Search property...' : 'Select landlord first'}
            />
          )}
        </div>
        <div className="space-y-2 sm:col-span-2">
          <Label>Description *</Label>
          <Input value={data.description} onChange={e => setData(prev => ({ ...prev, description: e.target.value }))} required />
        </div>
        <div className="space-y-2">
          <Label>Amount (£) *</Label>
          <Input type="number" min="0" step="0.01" value={data.amount} onChange={e => setData(prev => ({ ...prev, amount: e.target.value }))} required />
        </div>
        <div className="space-y-2">
          <Label>Date *</Label>
          <Input type="date" value={data.date} onChange={e => setData(prev => ({ ...prev, date: e.target.value }))} required />
        </div>
        <div className="space-y-2 sm:col-span-2">
          <Label>Deduct from Pay Period *</Label>
          <PeriodPicker value={data.period_month} onChange={v => setData(prev => ({ ...prev, period_month: v }))} />
          <p className="text-xs text-muted-foreground">Which invoice/statement should this deduction appear on?</p>
        </div>
        <div className="space-y-2">
          <Label>Category</Label>
          <Select value={data.category} onValueChange={v => setData(prev => ({ ...prev, category: v }))}>
            <SelectTrigger><SelectValue /></SelectTrigger>
            <SelectContent>{CATEGORIES.map(c => <SelectItem key={c} value={c}>{c}</SelectItem>)}</SelectContent>
          </Select>
        </div>
        {coOwnerShares.length > 1 && (
          <div className="space-y-2 sm:col-span-2">
            <Label>Charge to</Label>
            <Select
              value={data.deduct_from_landlord_id || '__split__'}
              onValueChange={v => setData(prev => ({ ...prev, deduct_from_landlord_id: v === '__split__' ? '' : v }))}
            >
              <SelectTrigger><SelectValue /></SelectTrigger>
              <SelectContent>
                <SelectItem value="__split__">All owners — split by share</SelectItem>
                {coOwnerShares.map(sh => {
                  const ll = landlords.find(l => l.id === sh.landlord_id);
                  return <SelectItem key={sh.landlord_id} value={sh.landlord_id}>{ll?.name || 'Owner'} only ({sh.share_pct}% owner)</SelectItem>;
                })}
              </SelectContent>
            </Select>
            <p className="text-xs text-muted-foreground">
              {data.deduct_from_landlord_id
                ? 'This deduction will be taken entirely from this owner\'s payout.'
                : 'This deduction will be split across all owners by their ownership share.'}
            </p>
          </div>
        )}
      </div>
      <div className="space-y-2">
        <Label>Notes</Label>
        <Textarea value={data.notes || ''} onChange={e => setData(prev => ({ ...prev, notes: e.target.value }))} rows={2} />
      </div>
      <div className="flex gap-3 justify-end pt-2">
        <Button type="button" variant="outline" onClick={onCancel} disabled={submitting}>Cancel</Button>
        <Button type="submit" disabled={submitting || !data.landlord_id}>{submitting ? 'Saving...' : extra ? 'Update' : 'Add Deduction'}</Button>
      </div>
    </form>
  );
}

export default function ExtrasSection({ extras, landlords, properties, user, isAdmin, filterLandlordId, filterPropertyId, property }) {
  const queryClient = useQueryClient();
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(null);

  // When the property is co-owned, deductions are property-level and split by share.
  const coOwned = property ? isMultiLandlord(property) : false;
  const shares = property ? getLandlordShares(property) : [];
  const ownerSplitLabel = (amount) =>
    splitByShares(amount, shares)
      .map(p => `${landlords.find(l => l.id === p.landlord_id)?.name?.split(' ')[0] || '?'} ${formatCurrency(p.amount)}`)
      .join(' · ');

  const getLandlordName = id => landlords.find(l => l.id === id)?.name || '-';
  const getPropertyName = id => properties.find(p => p.id === id)?.address?.split(',')[0] || 'All';

  const handleSubmit = async (data) => {
    if (editing) {
      await base44.entities.PaymentExtra.update(editing.id, data);
      await logAction({ user, action: 'update', entityType: 'PaymentExtra', entityId: editing.id, summary: `Updated deduction: ${data.description}`, oldValue: editing, newValue: data });
    } else {
      const created = await base44.entities.PaymentExtra.create(data);
      await logAction({ user, action: 'create', entityType: 'PaymentExtra', entityId: created.id, summary: `Added deduction: ${data.description} (${formatCurrency(data.amount)})`, newValue: data });
    }
    queryClient.invalidateQueries({ queryKey: ['payment_extras'] });
    setShowForm(false);
    setEditing(null);
  };

  const handleDelete = async (item) => {
    await base44.entities.PaymentExtra.delete(item.id);
    await logAction({ user, action: 'delete', entityType: 'PaymentExtra', entityId: item.id, summary: `Deleted deduction: ${item.description}`, oldValue: item });
    queryClient.invalidateQueries({ queryKey: ['payment_extras'] });
    setConfirmDelete(null);
  };

  const totalExtras = extras.reduce((s, e) => s + (e.amount || 0), 0);

  return (
    <div className="bg-card rounded-xl border border-border overflow-hidden mb-8">
      <div className="px-5 py-4 border-b border-border flex items-center justify-between">
        <div>
          <h2 className="text-sm font-semibold">Landlord Deductions / Extras</h2>
          <p className="text-xs text-muted-foreground mt-0.5">Deductions subtracted from landlord payable amounts (maintenance, certificates, repairs, etc.)</p>
        </div>
        <div className="flex items-center gap-3">
          <span className="text-sm font-medium text-red-600">Total: {formatCurrency(totalExtras)}</span>
          {isAdmin && (
            <Button size="sm" onClick={() => { setEditing(null); setShowForm(true); }}>
              <Plus className="w-4 h-4 mr-1" />Add Deduction
            </Button>
          )}
        </div>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="bg-muted/50">
              <th className="text-left px-4 py-3 font-medium text-muted-foreground">Date</th>
              <th className="text-left px-4 py-3 font-medium text-muted-foreground">Pay Period</th>
              <th className="text-left px-4 py-3 font-medium text-muted-foreground">Landlord</th>
              <th className="text-left px-4 py-3 font-medium text-muted-foreground">Property</th>
              <th className="text-left px-4 py-3 font-medium text-muted-foreground">Description</th>
              <th className="text-left px-4 py-3 font-medium text-muted-foreground">Category</th>
              <th className="text-right px-4 py-3 font-medium text-muted-foreground">Amount</th>
              {isAdmin && <th className="px-4 py-3"></th>}
            </tr>
          </thead>
          <tbody>
            {extras.map(item => (
              <tr key={item.id} className="border-t border-border hover:bg-muted/30 transition-colors">
                <td className="px-4 py-3 text-muted-foreground">{item.date ? format(parseISO(item.date), 'dd MMM yyyy') : '-'}</td>
                <td className="px-4 py-3">
                  {item.period_month
                    ? <span className="text-xs font-medium bg-blue-50 text-blue-700 border border-blue-200 px-2 py-0.5 rounded-full">{format(parseISO(item.period_month + '-01'), 'MMM yyyy')}</span>
                    : <span className="text-xs text-muted-foreground">—</span>}
                </td>
                <td className="px-4 py-3 font-medium">
                  {coOwned
                    ? (item.deduct_from_landlord_id
                        ? <span className="text-xs">{getLandlordName(item.deduct_from_landlord_id)} <span className="text-muted-foreground">(only)</span></span>
                        : <span className="text-primary text-xs">All owners <span className="text-muted-foreground">(split)</span></span>)
                    : getLandlordName(item.landlord_id)}
                </td>
                <td className="px-4 py-3 text-muted-foreground">{item.property_id ? getPropertyName(item.property_id) : 'All'}</td>
                <td className="px-4 py-3">{item.description}</td>
                <td className="px-4 py-3"><StatusBadge color="yellow">{item.category}</StatusBadge></td>
                <td className="px-4 py-3 text-right font-medium text-red-600">
                  {formatCurrency(item.amount)}
                  {coOwned && !item.deduct_from_landlord_id && <div className="text-xs font-normal text-muted-foreground mt-0.5">{ownerSplitLabel(item.amount)}</div>}
                  {coOwned && item.deduct_from_landlord_id && <div className="text-xs font-normal text-muted-foreground mt-0.5">{getLandlordName(item.deduct_from_landlord_id).split(' ')[0]} only</div>}
                </td>
                {isAdmin && (
                  <td className="px-4 py-3">
                    <div className="flex gap-1">
                      <Button variant="ghost" size="sm" onClick={() => { setEditing(item); setShowForm(true); }}>
                        <Pencil className="w-3 h-3" />
                      </Button>
                      <Button variant="ghost" size="sm" className="text-destructive hover:text-destructive" onClick={() => setConfirmDelete(item)}>
                        <Trash2 className="w-3 h-3" />
                      </Button>
                    </div>
                  </td>
                )}
              </tr>
            ))}
            {extras.length === 0 && (
              <tr><td colSpan={isAdmin ? 8 : 7} className="px-4 py-8 text-center text-muted-foreground">No deductions recorded</td></tr>
            )}
          </tbody>
        </table>
      </div>

      <Dialog open={showForm} onOpenChange={v => { if (!v) { setShowForm(false); setEditing(null); } }}>
        <DialogContent className="max-w-lg">
          <DialogHeader><DialogTitle>{editing ? 'Edit Deduction' : 'Add Deduction'}</DialogTitle></DialogHeader>
          {coOwned && (
            <p className="text-xs text-primary bg-primary/10 rounded px-3 py-2">
              This property is co-owned. The deduction will be shared across all owners by their share ({shares.map(s => `${landlords.find(l => l.id === s.landlord_id)?.name?.split(' ')[0] || '?'} ${s.share_pct}%`).join(' · ')}).
            </p>
          )}
          <ExtraForm extra={editing} landlords={landlords} properties={properties} onSubmit={handleSubmit} onCancel={() => { setShowForm(false); setEditing(null); }} defaultLandlordId={!editing ? filterLandlordId : undefined} defaultPropertyId={!editing ? filterPropertyId : undefined} coOwnerShares={coOwned ? shares : []} />
        </DialogContent>
      </Dialog>

      <ConfirmDialog
        open={!!confirmDelete}
        title="Delete Deduction"
        description={`Delete "${confirmDelete?.description}" (${formatCurrency(confirmDelete?.amount)})? This will affect the landlord statement.`}
        onConfirm={() => handleDelete(confirmDelete)}
        onCancel={() => setConfirmDelete(null)}
      />
    </div>
  );
}

import React, { useState } from 'react';
import { base44 } from '@/api/base44Client';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Plus, Trash2, Check, CreditCard } from 'lucide-react';
import { getLandlordAccounts, genAccountId, resolvePayoutAccount, setPropertyPayoutAccount, accountLine } from '@/lib/payoutAccounts';

export default function LandlordPaymentAccounts({ landlord, properties = [], onSaved }) {
  const [accounts, setAccounts] = useState(() => {
    const a = getLandlordAccounts(landlord);
    return a.length ? a.map(x => ({ ...x, id: x.id || genAccountId() })) : [];
  });
  const [saving, setSaving] = useState(false);
  const [savedMsg, setSavedMsg] = useState('');

  const update = (id, patch) => setAccounts(prev => prev.map(a => (a.id === id ? { ...a, ...patch } : a)));
  const addAccount = () => setAccounts(prev => [
    ...prev,
    { id: genAccountId(), label: prev.length === 0 ? 'Main account' : 'Account', account_name: '', bank_name: '', sort_code: '', account_number: '', payment_reference: '', is_default: prev.length === 0 },
  ]);
  const removeAccount = (id) => setAccounts(prev => {
    const next = prev.filter(a => a.id !== id);
    if (next.length && !next.some(a => a.is_default)) next[0].is_default = true;
    return next;
  });
  const setDefault = (id) => setAccounts(prev => prev.map(a => ({ ...a, is_default: a.id === id })));

  const saveAccounts = async () => {
    setSaving(true);
    try {
      await base44.entities.Landlord.update(landlord.id, { bank_accounts: accounts });
      setSavedMsg('Saved');
      setTimeout(() => setSavedMsg(''), 1500);
      onSaved && await onSaved();
    } catch (e) { alert(`Could not save: ${e.message || e}`); }
    finally { setSaving(false); }
  };

  // Per-property account choice (auto-saves on change).
  const assignProperty = async (property, accountId) => {
    try {
      const mapping = setPropertyPayoutAccount(property, landlord.id, accountId);
      await base44.entities.Property.update(property.id, { payout_accounts: mapping });
      onSaved && await onSaved();
    } catch (e) { alert(`Could not save: ${e.message || e}`); }
  };

  const currentAccountId = (property) => {
    const acc = resolvePayoutAccount({ ...property, payout_accounts: property.payout_accounts }, { ...landlord, bank_accounts: accounts });
    // Prefer an explicit mapping; fall back to resolved (default)
    const m = (property.payout_accounts || []).find(x => x.landlord_id === landlord.id);
    return m?.account_id || acc?.id || '';
  };

  return (
    <div className="space-y-6">
      {/* Accounts */}
      <div className="space-y-3">
        {accounts.length === 0 && (
          <p className="text-sm text-muted-foreground">No bank accounts yet. Add one to record where this landlord is paid.</p>
        )}
        {accounts.map((a) => (
          <div key={a.id} className="border border-border rounded-lg p-4 space-y-3 bg-muted/10">
            <div className="flex items-center justify-between gap-2">
              <div className="flex items-center gap-2 flex-1">
                <CreditCard className="w-4 h-4 text-primary shrink-0" />
                <Input className="h-8 font-medium" value={a.label || ''} onChange={e => update(a.id, { label: e.target.value })} placeholder="Account label (e.g. Main account)" />
              </div>
              <button
                onClick={() => setDefault(a.id)}
                className={`text-xs px-2 py-1 rounded-md border ${a.is_default ? 'bg-emerald-50 text-emerald-700 border-emerald-200' : 'text-muted-foreground border-input hover:bg-muted'}`}
                title="Use as the default account for new properties">
                {a.is_default ? <span className="inline-flex items-center gap-1"><Check className="w-3 h-3" />Default</span> : 'Set default'}
              </button>
              <Button type="button" variant="ghost" size="icon" className="text-muted-foreground hover:text-destructive" onClick={() => removeAccount(a.id)}>
                <Trash2 className="w-4 h-4" />
              </Button>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <div className="space-y-1"><Label className="text-xs">Account Name</Label><Input value={a.account_name || ''} onChange={e => update(a.id, { account_name: e.target.value })} /></div>
              <div className="space-y-1"><Label className="text-xs">Bank</Label><Input value={a.bank_name || ''} onChange={e => update(a.id, { bank_name: e.target.value })} placeholder="e.g. Barclays" /></div>
              <div className="space-y-1"><Label className="text-xs">Sort Code</Label><Input value={a.sort_code || ''} onChange={e => update(a.id, { sort_code: e.target.value })} placeholder="00-00-00" /></div>
              <div className="space-y-1"><Label className="text-xs">Account Number</Label><Input value={a.account_number || ''} onChange={e => update(a.id, { account_number: e.target.value })} placeholder="12345678" /></div>
              <div className="space-y-1 sm:col-span-2"><Label className="text-xs">Payment Reference</Label><Input value={a.payment_reference || ''} onChange={e => update(a.id, { payment_reference: e.target.value })} /></div>
            </div>
          </div>
        ))}
        <div className="flex items-center gap-2">
          <Button type="button" variant="outline" size="sm" onClick={addAccount}><Plus className="w-3.5 h-3.5 mr-1" />Add account</Button>
          <Button type="button" size="sm" onClick={saveAccounts} disabled={saving}>{saving ? 'Saving…' : 'Save accounts'}</Button>
          {savedMsg && <span className="text-xs text-emerald-600">{savedMsg}</span>}
        </div>
      </div>

      {/* Property → account mapping */}
      {accounts.length > 0 && properties.length > 0 && (
        <div className="space-y-2">
          <p className="text-sm font-medium">Which account pays each property</p>
          <p className="text-xs text-muted-foreground">Save the accounts above first so they appear here. Changes save automatically.</p>
          <div className="border border-border rounded-lg overflow-hidden">
            <table className="w-full text-sm">
              <thead className="bg-muted/40">
                <tr>
                  <th className="text-left px-3 py-2 font-medium">Property</th>
                  <th className="text-left px-3 py-2 font-medium">Paid into</th>
                </tr>
              </thead>
              <tbody>
                {properties.map((p) => (
                  <tr key={p.id} className="border-t border-border">
                    <td className="px-3 py-2">{p.address}</td>
                    <td className="px-3 py-2">
                      <select
                        value={currentAccountId(p)}
                        onChange={(e) => assignProperty(p, e.target.value)}
                        className="px-2 py-1.5 text-sm border border-input rounded-md bg-background focus:outline-none focus:ring-2 focus:ring-primary"
                      >
                        {accounts.map((a) => (
                          <option key={a.id} value={a.id}>
                            {a.label || 'Account'} — {accountLine(a) || 'no details'}{a.is_default ? ' (default)' : ''}
                          </option>
                        ))}
                      </select>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useMemo } from 'react';
import { Link } from 'react-router-dom';
import { buildPropertyCycleSummary } from '@/lib/paymentSchedule';
import { formatCurrency } from '@/lib/computations';
import { format, parseISO } from 'date-fns';
import { Wallet, AlertTriangle, Clock, CheckCircle } from 'lucide-react';
import StatusBadge from '@/components/ui/StatusBadge';

const STATUS_COLOR = { Paid: 'green', Partial: 'yellow', Pending: 'blue', Overdue: 'red' };
const STATUS_ICON = { Paid: CheckCircle, Partial: Clock, Pending: Clock, Overdue: AlertTriangle };

export default function UpcomingPaymentsPanel({ landlords, properties = [], rentPayments, commissionLedger, expenses, landlordPayouts, paymentExtras }) {
  const cycles = useMemo(() => {
    const summaries = [];
    properties.forEach(prop => {
      if (!prop.payment_day) return;
      const landlord = landlords.find(l => l.id === prop.landlord_id);
      if (!landlord || landlord.status !== 'active') return;
      const s = buildPropertyCycleSummary({ property: prop, landlord, rentPayments, commissionLedger, expenses, landlordPayouts, paymentExtras });
      if (s) summaries.push(s);
    });
    return summaries.sort((a, b) => a.payDate.localeCompare(b.payDate));
  }, [landlords, properties, rentPayments, commissionLedger, expenses, landlordPayouts, paymentExtras]);

  const upcoming = cycles.filter(c => !c.isOverdue && c.daysUntilPay <= 7);
  const overdue = cycles.filter(c => c.isOverdue && c.status !== 'Paid');
  const dueToday = cycles.filter(c => c.daysUntilPay === 0 && c.status !== 'Paid');

  if (cycles.length === 0) return null;

  return (
    <div className="mb-8">
      <div className="flex items-center justify-between mb-3">
        <h2 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Landlord Payment Schedule</h2>
        <Link to="/LandlordPayments" className="text-xs text-primary hover:underline">View all →</Link>
      </div>

      {overdue.length > 0 && (
        <div className="mb-3 space-y-2">
          {overdue.map(c => (
            <div key={`${c.landlord.id}-${c.property.id}`} className="flex items-center justify-between bg-red-50 border border-red-200 rounded-lg px-4 py-3 text-sm">
              <div className="flex items-center gap-2 text-red-700 font-medium">
                <AlertTriangle className="w-4 h-4" />
                <span>OVERDUE: {c.landlord.name} / {c.property.address.split(',')[0]} — {c.label}</span>
              </div>
              <span className="text-red-700 font-bold">{formatCurrency(c.balance)} pending</span>
            </div>
          ))}
        </div>
      )}

      {dueToday.length > 0 && (
        <div className="mb-3 space-y-2">
          {dueToday.map(c => (
            <div key={`${c.landlord.id}-${c.property.id}`} className="flex items-center justify-between bg-amber-50 border border-amber-200 rounded-lg px-4 py-3 text-sm">
              <div className="flex items-center gap-2 text-amber-700 font-medium">
                <Wallet className="w-4 h-4" />
                <span>DUE TODAY: {c.landlord.name} / {c.property.address.split(',')[0]} — {c.label}</span>
              </div>
              <span className="text-amber-700 font-bold">{formatCurrency(c.balance)} to pay</span>
            </div>
          ))}
        </div>
      )}

      <div className="bg-card rounded-xl border border-border overflow-hidden">
        <table className="w-full text-sm">
          <thead>
            <tr className="bg-muted/50">
              <th className="text-left px-4 py-3 font-medium text-muted-foreground">Landlord</th>
              <th className="text-left px-4 py-3 font-medium text-muted-foreground">Cycle</th>
              <th className="text-left px-4 py-3 font-medium text-muted-foreground">Pay Date</th>
              <th className="text-right px-4 py-3 font-medium text-muted-foreground">Rent Collected</th>
              <th className="text-right px-4 py-3 font-medium text-muted-foreground">Payable</th>
              <th className="text-right px-4 py-3 font-medium text-muted-foreground">Paid</th>
              <th className="text-right px-4 py-3 font-medium text-muted-foreground">Balance</th>
              <th className="text-left px-4 py-3 font-medium text-muted-foreground">Status</th>
            </tr>
          </thead>
          <tbody>
            {cycles.map(c => {
              const Icon = STATUS_ICON[c.status] || Clock;
              return (
                <tr key={`${c.landlord.id}-${c.property.id}`} className="border-t border-border hover:bg-muted/30 transition-colors">
                  <td className="px-4 py-3">
                    <div className="font-medium">{c.landlord.name}</div>
                    <div className="text-xs text-muted-foreground">{c.property.address.split(',')[0]}</div>
                  </td>
                  <td className="px-4 py-3 text-xs text-muted-foreground">{c.label}</td>
                  <td className="px-4 py-3">
                    <span className={c.daysUntilPay <= 0 ? 'text-red-600 font-bold' : c.daysUntilPay <= 5 ? 'text-amber-600 font-semibold' : ''}>
                      {format(parseISO(c.payDate), 'dd MMM yyyy')}
                      {c.daysUntilPay > 0 && <span className="text-xs text-muted-foreground ml-1">({c.daysUntilPay}d)</span>}
                      {c.daysUntilPay <= 0 && <span className="text-xs ml-1">({Math.abs(c.daysUntilPay)}d ago)</span>}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-right text-emerald-600">{formatCurrency(c.rentCollected)}</td>
                  <td className="px-4 py-3 text-right font-semibold">{formatCurrency(c.payable)}</td>
                  <td className="px-4 py-3 text-right text-emerald-600">{formatCurrency(c.alreadyPaid)}</td>
                  <td className={`px-4 py-3 text-right font-bold ${c.balance > 0 ? 'text-red-600' : 'text-emerald-600'}`}>{formatCurrency(c.balance)}</td>
                  <td className="px-4 py-3"><StatusBadge color={STATUS_COLOR[c.status]}>{c.status}</StatusBadge></td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { Outlet, useLocation } from 'react-router-dom';
import Sidebar from './Sidebar';
import TopBar from './TopBar';
import WhatsNewBanner from '@/components/ui/WhatsNewBanner';
import SplitView from './SplitView';

// Once a window/iframe has loaded in embed (chromeless) mode, keep it
// chromeless for the lifetime of that JS realm across in-app SPA navigations
// (which drop the ?embed=1 query param). Each iframe is its own realm, so
// this flag never leaks to the main app window.
let embedOnce = false;

export default function AppLayout() {
  const [collapsed, setCollapsed] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  const location = useLocation();

  const urlEmbed = new URLSearchParams(location.search).has('embed');
  if (urlEmbed) embedOnce = true;
  const isEmbed = urlEmbed || embedOnce;

  // Close mobile drawer when route changes
  useEffect(() => {
    setMobileOpen(false);
  }, [location.pathname]);

  // Lock body scroll when mobile drawer is open
  useEffect(() => {
    if (mobileOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }
    return () => { document.body.style.overflow = ''; };
  }, [mobileOpen]);

  if (isEmbed) {
    return (
      <div className="min-h-screen bg-background font-inter">
        <main className="px-4 py-5 sm:px-6 sm:py-6 max-w-[1600px] w-full mx-auto pb-safe">
          <Outlet />
        </main>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background font-inter">
      <Sidebar
        collapsed={collapsed}
        onToggle={() => setCollapsed(!collapsed)}
        mobileOpen={mobileOpen}
        onMobileClose={() => setMobileOpen(false)}
      />

      {/* Mobile overlay */}
      {mobileOpen && (
        <div
          className="fixed inset-0 z-30 bg-slate-900/60 backdrop-blur-sm lg:hidden animate-in fade-in duration-200"
          onClick={() => setMobileOpen(false)}
          aria-hidden="true"
        />
      )}

      <div className={`min-h-screen flex flex-col transition-[margin] duration-300 ${collapsed ? 'lg:ml-16' : 'lg:ml-64'}`}>
        <TopBar onMenuClick={() => setMobileOpen(true)} />
        <WhatsNewBanner />
        <main className="flex-1 flex flex-col px-4 py-5 sm:px-6 sm:py-6 lg:px-8 lg:py-8 max-w-[1600px] w-full mx-auto pb-safe min-h-0">
          <SplitView main={<Outlet />} />
        </main>
      </div>
    </div>
  );
}

