  { type: 'item', label: 'Send Email', path: '/SendEmail' },
  { type: 'item', label: 'AI Letter Writer', path: '/AILetterWriter' },
];

const COMP_BY_PATH = {
  '/Dashboard': Dashboard,
  '/AIAssistant': AIAssistant,
  '/Properties': Properties,
  '/Landlords': Landlords,
  '/LandlordPaymentSchedule': LandlordPaymentSchedule,
  '/LandlordStatements': LandlordStatements,
  '/AnnualRentStatement': AnnualRentStatement,
  '/Commission': Commission,
  '/Tenants': Tenants,
  '/TenantInvoices': TenantInvoices,
  '/Arrears': Arrears,
  '/Notifications': Notifications,
  '/Ledger': Ledger,
  '/Expenses': Expenses,
  '/Reports': Reports,
  '/Maintenance': Maintenance,
  '/Inspections': Inspections,
  '/Certificates': Certificates,
  '/ProspectiveTenants': ProspectiveTenants,
  '/Inquiries': Inquiries,
  '/CRM': CRM,
  '/ESignatures': ESignatures,
  '/SendEmail': SendEmail,
  '/AILetterWriter': AILetterWriter,
};

const CURRENT = 'current';

const labelByPath = (path) => {
  for (const g of HIERARCHY) {
    if (g.type === 'item' && g.path === path) return g.label;
    if (g.type === 'group') {
      const f = g.items.find(i => i.path === path);
      if (f) return f.label;
    }
  }
  return '';
};

export default function SplitView({ main }) {
  const location = useLocation();
  const [open, setOpen] = useState(false);
  const [leftKey, setLeftKey] = useState(CURRENT);
  const [rightKey, setRightKey] = useState('/Properties');

  const resolvePath = (key) => (key === CURRENT ? location.pathname : key);

  const renderPane = (key) => {
    const Comp = COMP_BY_PATH[resolvePath(key)];
    if (!Comp) {
      return (
        <div className="h-full grid place-items-center text-sm text-muted-foreground p-6 text-center">
          Select a page to display in this pane.
        </div>
      );
    }
    return (
      <div className="h-full overflow-auto">
        <Comp />
      </div>
    );
  };

  const swap = () => {
    const newLeft = rightKey;
    const newRight = leftKey === CURRENT ? '/Dashboard' : leftKey;
    setLeftKey(newLeft);
    setRightKey(newRight);
  };

  const PaneSelect = ({ value, onChange }) => (
    <Select value={value} onValueChange={onChange}>
      <SelectTrigger className="h-8 w-[200px] text-sm">
        <SelectValue>{value === CURRENT ? 'Current page' : labelByPath(value)}</SelectValue>
      </SelectTrigger>
      <SelectContent>
        <SelectItem value={CURRENT}>Current page</SelectItem>
        {HIERARCHY.map((g) =>
          g.type === 'item' ? (
            <SelectItem key={g.path} value={g.path}>{g.label}</SelectItem>
          ) : (
            <SelectGroup key={g.label}>
              <SelectLabel className="text-[10px] uppercase tracking-wider text-muted-foreground">{g.label}</SelectLabel>
              {g.items.map(i => (
                <SelectItem key={i.path} value={i.path} className="pl-6">{i.label}</SelectItem>
              ))}
            </SelectGroup>
          )
        )}
      </SelectContent>
    </Select>
  );

  if (!open) {
    return (
      <>
        <div className="shrink-0 hidden lg:flex justify-end mb-3">
          <button onClick={() => setOpen(true)} className="inline-flex items-center gap-1.5 h-8 px-3 rounded-md text-xs font-medium text-muted-foreground hover:bg-muted hover:text-foreground transition-colors">
            <Columns2 className="w-4 h-4" /> Split screen
          </button>
        </div>
        <div className="flex-1 min-h-0">{main}</div>
      </>
    );
  }

  return (
    <>
      <div className="shrink-0 hidden lg:flex items-center gap-3 mb-3 flex-wrap">
        <span className="text-[11px] font-semibold uppercase tracking-[0.18em] text-muted-foreground">Split</span>
        <PaneSelect value={leftKey} onChange={setLeftKey} />
        <button onClick={swap} title="Swap panes" className="inline-flex items-center justify-center h-8 w-8 rounded-md text-muted-foreground hover:bg-muted hover:text-foreground transition-colors">
          <ArrowLeftRight className="w-4 h-4" />
        </button>
        <PaneSelect value={rightKey} onChange={setRightKey} />
        <button onClick={() => setOpen(false)} className="inline-flex items-center gap-1.5 h-8 px-3 rounded-md text-xs font-medium text-muted-foreground hover:bg-muted hover:text-foreground transition-colors">
          <X className="w-3.5 h-3.5" /> Close
        </button>
      </div>
      {/* Desktop: side-by-side resizable panes, rendering the selected page components directly */}
      <div className="hidden lg:block flex-1 min-h-0">
        <PanelGroup direction="horizontal" className="h-full">
          <Panel defaultSize={50} minSize={28}>
            <div className="h-full rounded-lg border border-border overflow-hidden bg-background elev-1">
              {renderPane(leftKey)}
            </div>
          </Panel>
          <PanelResizeHandle className="w-1.5 mx-1 rounded-full bg-border hover:bg-primary/40 transition-colors" />
          <Panel defaultSize={50} minSize={28}>
            <div className="h-full rounded-lg border border-border overflow-hidden bg-background elev-1">
              {renderPane(rightKey)}
            </div>
          </Panel>
        </PanelGroup>
      </div>
      {/* Mobile: just the current page */}
      <div className="lg:hidden flex-1 min-h-0">{main}</div>
    </>
  );
}

