import { Archive, Download, ChevronDown, ChevronUp, Pencil, Check, X, Trash2 } from 'lucide-react';
import * as XLSX from 'xlsx';

// --- helpers ---
const prevMonth = () => {
  return format(new Date(), 'yyyy-MM');
};

const monthLabel = (ym) => {
  if (!ym) return '';
  const [y, m] = ym.split('-');
  return format(new Date(Number(y), Number(m) - 1, 1), 'MMMM yyyy');
};

const downloadSnapshot = async (snap) => {
  let entries = [];
  if (snap.entries_json) {
    const res = await fetch(snap.entries_json);
    entries = await res.json();
    if (!Array.isArray(entries)) entries = [];
  }
  const rows = entries.map(e => ({
    Date: e.date ? format(parseISO(e.date), 'dd MMM yyyy') : '-',
    Type: e.type,
    Category: e.category,
    Description: e.description,
    'Bank Account': e.received_in_bank_name || '-',
    'Income (£)': e.type === 'Income' ? e.amount : '',
    'Expense (£)': e.type === 'Expense' ? e.amount : '',
    'Balance (£)': e.running_balance ?? '',
  }));
  const snapClosing = snap.closing_balance ?? 0;
  // Add summary rows
  rows.push({});
  rows.push({ Date: 'SUMMARY', Description: `Opening Balance: ${formatCurrency(snap.opening_balance || 0)}` });
  rows.push({ Date: '', Description: `Total Income: ${formatCurrency(snap.total_income || 0)}` });
  rows.push({ Date: '', Description: `Total Expense: ${formatCurrency(snap.total_expense || 0)}` });
  rows.push({ Date: '', Description: `Closing Balance: ${formatCurrency(snapClosing)}` });
  if (snap.notes) rows.push({ Date: 'Notes', Description: snap.notes });

  const ws = XLSX.utils.json_to_sheet(rows);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, `${snap.ledger_type}_${snap.period_month}`);
  XLSX.writeFile(wb, `Ledger_${snap.ledger_type}_${snap.period_month}.xlsx`);
};

// --- Archived snapshot row ---
function SnapshotRow({ snap, onEdit }) {
  const [open, setOpen] = useState(false);
  const [editing, setEditing] = useState(false);
  const [notes, setNotes] = useState(snap.notes || '');
  const queryClient = useQueryClient();

  const [entries, setEntries] = useState([]);
  const [loadingEntries, setLoadingEntries] = useState(false);
  const [confirmingDelete, setConfirmingDelete] = useState(false);
  const [deleting, setDeleting] = useState(false);

  const loadEntries = async () => {
    if (!snap.entries_json || entries.length > 0) return;
    setLoadingEntries(true);
    const res = await fetch(snap.entries_json);
    const data = await res.json();
    setEntries(Array.isArray(data) ? data : []);
    setLoadingEntries(false);
  };

  const saveNotes = async () => {
    await base44.entities.MonthlyLedgerSnapshot.update(snap.id, { notes });
    queryClient.invalidateQueries({ queryKey: ['monthly_ledger_snapshots'] });
    setEditing(false);
  };

  const handleDelete = async (e) => {
    e?.stopPropagation?.();
    if (!confirmingDelete) { setConfirmingDelete(true); return; }
    setDeleting(true);
    try {
      await base44.entities.MonthlyLedgerSnapshot.deleteMany({
        period_month: snap.period_month,
        ledger_type: snap.ledger_type,
      });
      queryClient.invalidateQueries({ queryKey: ['monthly_ledger_snapshots'] });
    } catch (err) {
      alert('Failed to delete snapshot: ' + (err?.message || err));
    } finally {
      setDeleting(false);
      setConfirmingDelete(false);
    }
  };

  return (
    <div className="border border-border rounded-lg overflow-hidden">
      <div className="flex items-center justify-between px-4 py-3 bg-muted/40 cursor-pointer hover:bg-muted/60 transition-colors" onClick={() => { setOpen(o => !o); loadEntries(); }}>
        <div className="flex items-center gap-3">
          <StatusBadge color={snap.ledger_type === 'bank' ? 'blue' : 'green'}>
            {snap.ledger_type === 'bank' ? '🏦 Bank' : '💵 Cash'}
          </StatusBadge>
          <span className="font-semibold text-sm">{monthLabel(snap.period_month)}</span>
          <span className="text-xs text-muted-foreground">{snap.entry_count || 0} entries</span>
          <StatusBadge color={snap.status === 'closed' ? 'gray' : 'yellow'}>{snap.status}</StatusBadge>
        </div>
        <div className="flex items-center gap-3">
          <span className="text-sm font-bold tabular-nums" style={{ color: (snap.closing_balance ?? 0) >= 0 ? '#059669' : '#dc2626' }}>
            {formatCurrency(snap.closing_balance ?? 0)}
          </span>
          <Button variant="ghost" size="sm" onClick={e => { e.stopPropagation(); downloadSnapshot(snap); }} title="Download Excel" disabled={loadingEntries}>
            <Download className="w-4 h-4" />
          </Button>
          <Button variant="ghost" size="sm" className={confirmingDelete ? 'text-destructive bg-destructive/10' : 'text-destructive/70 hover:text-destructive'} onClick={handleDelete} title={confirmingDelete ? 'Click again to confirm deletion' : 'Delete snapshot'} disabled={deleting}>
            <Trash2 className="w-4 h-4" />
            {confirmingDelete && <span className="text-xs ml-1 font-medium">Confirm?</span>}
          </Button>
          {open ? <ChevronUp className="w-4 h-4 text-muted-foreground" /> : <ChevronDown className="w-4 h-4 text-muted-foreground" />}
        </div>
      </div>

      {open && (
        <div className="px-4 py-3 space-y-3">
          {/* Summary stats */}
          <div className="grid grid-cols-3 gap-3 text-sm">
            <div className="bg-muted/30 rounded-lg p-3 text-center">
              <p className="text-xs text-muted-foreground mb-1">Opening</p>
              <p className="font-bold tabular-nums">{formatCurrency(snap.opening_balance || 0)}</p>
            </div>
            <div className="bg-emerald-50 rounded-lg p-3 text-center">
              <p className="text-xs text-emerald-600 mb-1">Income</p>
              <p className="font-bold tabular-nums text-emerald-700">{formatCurrency(snap.total_income || 0)}</p>
            </div>
            <div className="bg-red-50 rounded-lg p-3 text-center">
              <p className="text-xs text-red-600 mb-1">Expense</p>
              <p className="font-bold tabular-nums text-red-700">{formatCurrency(snap.total_expense || 0)}</p>
            </div>
          </div>

          {/* Notes */}
          <div>
            <div className="flex items-center gap-2 mb-1">
              <Label className="text-xs">Notes</Label>
              {!editing && (
                <button onClick={() => setEditing(true)} className="text-muted-foreground hover:text-foreground">
                  <Pencil className="w-3 h-3" />
                </button>
              )}
            </div>
            {editing ? (
              <div className="flex gap-2">
                <Textarea value={notes} onChange={e => setNotes(e.target.value)} rows={2} className="text-sm" />
                <div className="flex flex-col gap-1">
                  <Button size="sm" onClick={saveNotes}><Check className="w-3 h-3" /></Button>
                  <Button size="sm" variant="outline" onClick={() => { setEditing(false); setNotes(snap.notes || ''); }}><X className="w-3 h-3" /></Button>
                </div>
              </div>
            ) : (
              <p className="text-sm text-muted-foreground italic">{snap.notes || 'No notes.'}</p>
            )}
          </div>

          {/* Entry table */}
          <div className="overflow-x-auto border border-border rounded-lg max-h-64 overflow-y-auto">
            <table className="w-full text-xs">
              <thead className="sticky top-0 bg-muted">
                <tr>
                  <th className="text-left px-3 py-2 font-medium">Date</th>
                  <th className="text-left px-3 py-2 font-medium">Description</th>
                  <th className="text-right px-3 py-2 font-medium text-emerald-600">Income</th>
                  <th className="text-right px-3 py-2 font-medium text-red-600">Expense</th>
                  <th className="text-right px-3 py-2 font-medium">Balance</th>
                </tr>
              </thead>
              <tbody>
                {entries.map((e, i) => (
                  <tr key={i} className="border-t border-border hover:bg-muted/20">
                    <td className="px-3 py-1.5 text-muted-foreground whitespace-nowrap">{e.date ? format(parseISO(e.date), 'dd MMM') : '-'}</td>
                    <td className="px-3 py-1.5 max-w-[200px] truncate" title={e.description}>{e.description}</td>
                    <td className="px-3 py-1.5 text-right text-emerald-600">{e.type === 'Income' ? formatCurrency(e.amount) : ''}</td>
                    <td className="px-3 py-1.5 text-right text-red-600">{e.type === 'Expense' ? formatCurrency(e.amount) : ''}</td>
                    <td className={`px-3 py-1.5 text-right font-medium ${(e.running_balance ?? 0) >= 0 ? 'text-emerald-600' : 'text-red-600'}`}>{formatCurrency(e.running_balance ?? 0)}</td>
                  </tr>
                ))}
                {entries.length === 0 && (
                  <tr><td colSpan={5} className="px-3 py-4 text-center text-muted-foreground">No entries</td></tr>
                )}
              </tbody>
            </table>
          </div>
          <p className="text-xs text-muted-foreground">Closed by {snap.closed_by || 'unknown'} · {snap.created_date ? format(parseISO(snap.created_date), 'dd MMM yyyy HH:mm') : ''}</p>
        </div>
      )}
    </div>
  );
}

// --- Main Modal ---
export default function CloseLedgerModal({ open, onClose, bankEntries, cashEntries }) {
  const { user } = useRole();
  const queryClient = useQueryClient();
  const [tab, setTab] = useState('close'); // 'close' | 'history'
  const [notes, setNotes] = useState('');
  const [closing, setClosing] = useState(false);
  const [done, setDone] = useState(false);
  const [selectedMonth, setSelectedMonth] = useState(prevMonth());

  const { data: snapshotsRaw = [] } = useQuery({
    queryKey: ['monthly_ledger_snapshots'],
    queryFn: () => base44.entities.MonthlyLedgerSnapshot.list('-period_month', 100),
  });

  // Deduplicate by (period_month + ledger_type) — keep the most recently created
  const snapshots = useMemo(() => {
    const map = new Map();
    snapshotsRaw.forEach(s => {
      const key = `${s.period_month}_${s.ledger_type}`;
      const existing = map.get(key);
      if (!existing || (s.created_date || '') > (existing.created_date || '')) {
        map.set(key, s);
      }
    });
    return Array.from(map.values()).sort((a, b) =>
      (b.period_month || '').localeCompare(a.period_month || '')
    );
  }, [snapshotsRaw]);

  const target = selectedMonth;

  // Check if already closed for selected month
  const alreadyClosedBank = snapshots.some(s => s.period_month === target && s.ledger_type === 'bank');
  const alreadyClosedCash = snapshots.some(s => s.period_month === target && s.ledger_type === 'cash');
  const alreadyClosed = alreadyClosedBank && alreadyClosedCash;

  // Check if previous month is closed
  const prevMonthStr = format(subMonths(parseISO(`${target}-01`), 1), 'yyyy-MM');
  const prevMonthClosedBank = snapshots.some(s => s.period_month === prevMonthStr && s.ledger_type === 'bank');
  const prevMonthClosedCash = snapshots.some(s => s.period_month === prevMonthStr && s.ledger_type === 'cash');
  const prevMonthClosed = prevMonthClosedBank && prevMonthClosedCash;
  const isFirstSnapshot = snapshots.length === 0;

  // Filter entries for the target month
  const targetStart = `${target}-01`;
  const targetEnd = format(endOfMonth(parseISO(targetStart)), 'yyyy-MM-dd');

  const monthBankEntries = useMemo(() =>
    bankEntries.filter(e => e.date && e.date >= targetStart && e.date <= targetEnd),
    [bankEntries, targetStart, targetEnd]
  );
  const monthCashEntries = useMemo(() =>
    cashEntries.filter(e => e.date && e.date >= targetStart && e.date <= targetEnd),
    [cashEntries, targetStart, targetEnd]
  );

  // Opening balance = closing balance of last entry BEFORE this month
  const bankOpeningBalance = useMemo(() => {
    const prev = bankEntries.filter(e => e.date && e.date < targetStart);
    return prev.length > 0 ? (prev[prev.length - 1].running_balance ?? 0) : 0;
  }, [bankEntries, targetStart]);

  const cashOpeningBalance = useMemo(() => {
    const prev = cashEntries.filter(e => e.date && e.date < targetStart);
    return prev.length > 0 ? (prev[prev.length - 1].running_balance ?? 0) : 0;
  }, [cashEntries, targetStart]);

  const computeMonthEntries = (entries, openingBal) => {
    let bal = openingBal;
    return entries.map(e => {
      bal += e.type === 'Income' ? e.amount : -e.amount;
      return { ...e, running_balance: bal };
    });
  };

  const bankMonthWithBal = useMemo(() => computeMonthEntries(monthBankEntries, bankOpeningBalance), [monthBankEntries, bankOpeningBalance]);
  const cashMonthWithBal = useMemo(() => computeMonthEntries(monthCashEntries, cashOpeningBalance), [monthCashEntries, cashOpeningBalance]);

  const bankIncome = monthBankEntries.filter(e => e.type === 'Income').reduce((s, e) => s + e.amount, 0);
  const bankExpense = monthBankEntries.filter(e => e.type === 'Expense').reduce((s, e) => s + e.amount, 0);
  const cashIncome = monthCashEntries.filter(e => e.type === 'Income').reduce((s, e) => s + e.amount, 0);
  const cashExpense = monthCashEntries.filter(e => e.type === 'Expense').reduce((s, e) => s + e.amount, 0);

  // Closing balance = income − expense for the month (matches the live ledger's
  // stat card, which rebalances from 0 for the filtered period).
  const bankClosing = bankIncome - bankExpense;
  const cashClosing = cashIncome - cashExpense;

  const uploadEntriesJson = async (entries) => {
    const blob = new Blob([JSON.stringify(entries)], { type: 'application/json' });
    const file = new File([blob], 'entries.json', { type: 'application/json' });
    const { file_url } = await base44.integrations.Core.UploadFile({ file });
    return file_url;
  };

  const handleClose = async () => {
    setClosing(true);

    const [bankUrl, cashUrl] = await Promise.all([
      alreadyClosedBank ? null : uploadEntriesJson(bankMonthWithBal),
      alreadyClosedCash ? null : uploadEntriesJson(cashMonthWithBal),
    ]);

    const makePayload = (type, entries, url, openingBal, closingBal, income, expense) => ({
      period_month: target,
      ledger_type: type,
      opening_balance: openingBal,
      closing_balance: closingBal,
      total_income: income,
      total_expense: expense,
      entry_count: entries.length,
      entries_json: url,
      notes,
      closed_by: user?.email || 'unknown',
      status: 'closed',
    });

    const promises = [];
    if (!alreadyClosedBank) promises.push(base44.entities.MonthlyLedgerSnapshot.create(makePayload('bank', bankMonthWithBal, bankUrl, bankOpeningBalance, bankClosing, bankIncome, bankExpense)));
    if (!alreadyClosedCash) {
      promises.push(base44.entities.MonthlyLedgerSnapshot.create(makePayload('cash', cashMonthWithBal, cashUrl, cashOpeningBalance, cashClosing, cashIncome, cashExpense)));
    }

    await Promise.all(promises);

    // Create "Balance carried forward" entries on the 1st of the next month
    const nextMonthStart = format(addMonths(parseISO(`${target}-01`), 1), 'yyyy-MM-dd');
    const carryLabel = `Balance carried forward — ${monthLabel(target)}`;

    // Fetch existing carry-forward entries directly from DB to avoid stale props
    const [existingAdjs, existingCash] = await Promise.all([
      base44.entities.LedgerAdjustment.filter({ date: nextMonthStart }),
      base44.entities.CashEntry.filter({ date: nextMonthStart }),
    ]);
    const isCarryDesc = (desc) =>
      typeof desc === 'string' && desc.toLowerCase().startsWith('balance carried forward');
    const bankHasCarry = existingAdjs.some(a => isCarryDesc(a.description));
    const cashHasCarry = existingCash.some(c => isCarryDesc(c.description));

    const carryPromises = [];
    if (!alreadyClosedBank && !bankHasCarry) {
      carryPromises.push(
        base44.entities.LedgerAdjustment.create({
          date: nextMonthStart,
          type: bankClosing >= 0 ? 'Income' : 'Expense',
          description: carryLabel,
          amount: Math.abs(bankClosing),
          reason: `Auto carry-forward from ${monthLabel(target)} bank ledger close`,
          edited_by: user?.email || 'unknown',
        })
      );
    }
    if (!alreadyClosedCash && !cashHasCarry) {
      carryPromises.push(
        base44.entities.CashEntry.create({
          date: nextMonthStart,
          type: cashClosing >= 0 ? 'Income' : 'Expense',
          description: carryLabel,
          amount: Math.abs(cashClosing),
          category: 'Carry Forward',
          notes: `Auto carry-forward from ${monthLabel(target)} cash ledger close`,
          added_by: user?.email || 'unknown',
        })
      );
    }
    await Promise.all(carryPromises);

    queryClient.invalidateQueries({ queryKey: ['monthly_ledger_snapshots'] });
    queryClient.invalidateQueries({ queryKey: ['cash_entries'] });
    queryClient.invalidateQueries({ queryKey: ['ledger_adjustments'] });
    setClosing(false);
    setDone(true);
  };

  const handleReset = () => { setDone(false); setNotes(''); };

  // Build month options: last 12 months up to current month
  const monthOptions = useMemo(() => {
    const opts = [];
    for (let i = 0; i < 12; i++) {
      const d = subMonths(new Date(), i);
      opts.push(format(d, 'yyyy-MM'));
    }
    return opts;
  }, []);

  return (
    <Dialog open={open} onOpenChange={v => { if (!v) { onClose(); handleReset(); } }}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Archive className="w-5 h-5" /> Monthly Ledger Management
          </DialogTitle>
        </DialogHeader>

        {/* Tab switcher */}
        <div className="flex gap-2 mb-4">
          {['close', 'history'].map(t => (
            <button key={t} onClick={() => setTab(t)}
              className={`px-4 py-1.5 rounded-lg text-sm font-medium transition-colors border ${tab === t ? 'bg-primary text-primary-foreground border-primary' : 'bg-card border-border hover:bg-muted'}`}>
              {t === 'close' ? 'Close Month' : 'Archived Months'}
            </button>
          ))}
        </div>

        {/* CLOSE TAB */}
        {tab === 'close' && (
          <div className="space-y-4">
            {/* Month picker */}
            <div className="flex items-center gap-3">
              <Label className="text-sm shrink-0">Select month to close:</Label>
              <Select value={selectedMonth} onValueChange={v => { setSelectedMonth(v); setDone(false); }}>
                <SelectTrigger className="w-48">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {monthOptions.map(m => (
                    <SelectItem key={m} value={m}>
                      {monthLabel(m)}
                      {snapshots.some(s => s.period_month === m && s.ledger_type === 'bank') &&
                       snapshots.some(s => s.period_month === m && s.ledger_type === 'cash')
                        ? ' ✓' : ''}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Reminder if previous month not closed */}
            {!isFirstSnapshot && !prevMonthClosed && !alreadyClosed && (
              <div className="bg-amber-50 border border-amber-200 rounded-lg px-4 py-3 text-sm text-amber-800 flex items-start gap-2">
                <span className="text-lg leading-none">⚠️</span>
                <div>
                  <strong>Previous month not closed:</strong> {monthLabel(prevMonthStr)} has not been archived yet.
                  Consider closing it first to maintain accurate carry-forward balances.
                  <button className="ml-2 underline font-medium" onClick={() => { setSelectedMonth(prevMonthStr); setDone(false); }}>
                    Close {monthLabel(prevMonthStr)} instead
                  </button>
                </div>
              </div>
            )}

            {done ? (
              <div className="text-center py-8 space-y-3">
                <div className="w-12 h-12 bg-emerald-100 rounded-full flex items-center justify-center mx-auto">
                  <Check className="w-6 h-6 text-emerald-600" />
                </div>
                <p className="font-semibold text-lg">Month Closed Successfully</p>
                <p className="text-sm text-muted-foreground">{monthLabel(target)} has been archived.</p>
                <div className="flex gap-2 justify-center mt-4">
                  <Button variant="outline" onClick={() => setTab('history')}>View Archive</Button>
                  <Button onClick={() => { onClose(); handleReset(); }}>Done</Button>
                </div>
              </div>
            ) : alreadyClosed ? (
              <div className="text-center py-6 space-y-2">
                <StatusBadge color="gray">Already Closed</StatusBadge>
                <p className="text-sm text-muted-foreground mt-2">{monthLabel(target)} ledgers are already archived.</p>
                <Button variant="outline" className="mt-3" onClick={() => setTab('history')}>View Archive</Button>
              </div>
            ) : (
              <>
                {/* Summary preview */}
                <div className="grid grid-cols-2 gap-3">
                  <div className="border border-border rounded-lg p-4 space-y-2">
                    <div className="flex items-center gap-2 mb-2">
                      <StatusBadge color="blue">🏦 Bank Ledger</StatusBadge>
                      {alreadyClosedBank && <StatusBadge color="gray">Closed</StatusBadge>}
                    </div>
                    <div className="text-xs space-y-1">
                      <div className="flex justify-between"><span className="text-muted-foreground">Entries</span><span className="font-medium">{monthBankEntries.length}</span></div>
                      <div className="flex justify-between"><span className="text-muted-foreground">Opening</span><span className="font-medium tabular-nums">{formatCurrency(bankOpeningBalance)}</span></div>
                      <div className="flex justify-between"><span className="text-emerald-600">+ Income</span><span className="font-medium text-emerald-600 tabular-nums">{formatCurrency(bankIncome)}</span></div>
                      <div className="flex justify-between"><span className="text-red-600">- Expense</span><span className="font-medium text-red-600 tabular-nums">{formatCurrency(bankExpense)}</span></div>
                      <div className="flex justify-between border-t border-border pt-1 mt-1"><span className="font-semibold">Closing</span><span className={`font-bold tabular-nums ${bankClosing >= 0 ? 'text-emerald-600' : 'text-red-600'}`}>{formatCurrency(bankClosing)}</span></div>
                    </div>
                  </div>

                  <div className="border border-border rounded-lg p-4 space-y-2">
                    <div className="flex items-center gap-2 mb-2">
                      <StatusBadge color="green">💵 Cash Ledger</StatusBadge>
                      {alreadyClosedCash && <StatusBadge color="gray">Closed</StatusBadge>}
                    </div>
                    <div className="text-xs space-y-1">
                      <div className="flex justify-between"><span className="text-muted-foreground">Entries</span><span className="font-medium">{monthCashEntries.length}</span></div>
                      <div className="flex justify-between"><span className="text-muted-foreground">Opening</span><span className="font-medium tabular-nums">{formatCurrency(cashOpeningBalance)}</span></div>
                      <div className="flex justify-between"><span className="text-emerald-600">+ Income</span><span className="font-medium text-emerald-600 tabular-nums">{formatCurrency(cashIncome)}</span></div>
                      <div className="flex justify-between"><span className="text-red-600">- Expense</span><span className="font-medium text-red-600 tabular-nums">{formatCurrency(cashExpense)}</span></div>
                      <div className="flex justify-between border-t border-border pt-1 mt-1"><span className="font-semibold">Closing</span><span className={`font-bold tabular-nums ${cashClosing >= 0 ? 'text-emerald-600' : 'text-red-600'}`}>{formatCurrency(cashClosing)}</span></div>
                    </div>
                  </div>
                </div>

                <div className="space-y-1">
                  <Label className="text-sm">Notes (optional)</Label>
                  <Textarea value={notes} onChange={e => setNotes(e.target.value)} rows={2} placeholder="Add any notes about this month-end close..." />
                </div>

                <div className="flex gap-2 justify-end">
                  <Button variant="outline" onClick={onClose}>Cancel</Button>
                  <Button onClick={handleClose} disabled={closing}>
                    <Archive className="w-4 h-4 mr-2" />
                    {closing ? 'Archiving...' : `Close ${monthLabel(target)}`}
                  </Button>
                </div>
              </>
            )}
          </div>
        )}

        {/* HISTORY TAB */}
        {tab === 'history' && (
          <div className="space-y-3">
            {snapshots.length === 0 ? (
              <div className="text-center py-12 text-muted-foreground text-sm">No archived months yet.</div>
            ) : (
              snapshots.map(snap => <SnapshotRow key={snap.id} snap={snap} />)
            )}
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

import React, { useState } from 'react';
import { StatusBadge, PriorityBadge } from './MaintenanceStatusBadge';
import { formatCurrency } from '@/lib/computations';
import { format, parseISO } from 'date-fns';
import { MapPin, User, Wrench, Calendar, Image, Building2, Users, Send, Check, Loader2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { sendToContractor, buildContractorMessage } from '@/lib/whatsappAlerts';
import { useToast } from '@/components/ui/use-toast';

export default function MaintenanceCard({ request, property, tenant, onEdit }) {
  const categoryLabel = (request.category || 'other').replace('_', ' ');
  const { toast } = useToast();
  const [sending, setSending] = useState(false);
  const [sent, setSent] = useState(false);

  const handleSendContractor = async () => {
    if (sending) return;
    setSending(true);
    try {
      const res = await sendToContractor(buildContractorMessage({ request, property, tenant }));
      if (res?.ok) {
        setSent(true);
        toast({ title: 'Sent to contractor', description: 'The job details were sent on WhatsApp.' });
        setTimeout(() => setSent(false), 4000);
      } else {
        toast({ title: 'Could not send', description: res?.error || res?.results?.[0]?.detail || 'Check the WHATSAPP_CONTRACTOR setting.', variant: 'destructive' });
      }
    } catch (e) {
      toast({ title: 'Could not send', description: e?.message || 'Unknown error', variant: 'destructive' });
    } finally {
      setSending(false);
    }
  };

  return (
    <div className="bg-card border border-border rounded-xl p-4 hover:shadow-md transition-shadow">
      <div className="flex items-start justify-between gap-3">
        <div className="flex-1 min-w-0">
          <div className="flex flex-wrap items-center gap-2 mb-1">
            <StatusBadge status={request.status} />
            <PriorityBadge priority={request.priority} />
            <span className="text-xs text-muted-foreground capitalize bg-muted px-2 py-0.5 rounded-full">{categoryLabel}</span>
            {request.charge_to_landlord ? (
              <span className="inline-flex items-center gap-1 text-xs font-medium px-2 py-0.5 rounded-full bg-amber-100 text-amber-800 border border-amber-200">
                <Building2 className="w-3 h-3" />Charged to Landlord
              </span>
            ) : (
              <span className="inline-flex items-center gap-1 text-xs font-medium px-2 py-0.5 rounded-full bg-blue-50 text-blue-700 border border-blue-200">
                <Users className="w-3 h-3" />{request.cost_bearer === 'tenant' ? 'Tenant Cost' : 'Agency Cost'}
              </span>
            )}
          </div>
          <h3 className="font-semibold text-foreground mt-1 truncate">{request.title}</h3>
          {request.description && (
            <p className="text-sm text-muted-foreground mt-0.5 line-clamp-2">{request.description}</p>
          )}
        </div>
        <div className="flex flex-col gap-1.5 shrink-0">
          <Button variant="outline" size="sm" onClick={() => onEdit(request)}>Manage</Button>
          <Button variant="outline" size="sm" onClick={handleSendContractor} disabled={sending} className="gap-1.5 text-emerald-700 border-emerald-200 hover:bg-emerald-50">
            {sending ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : sent ? <Check className="w-3.5 h-3.5" /> : <Send className="w-3.5 h-3.5" />}
            {sent ? 'Sent' : 'Contractor'}
          </Button>
        </div>
      </div>

      <div className="flex flex-wrap gap-x-4 gap-y-1 mt-3 text-xs text-muted-foreground">
        {property && (
          <span className="flex items-center gap-1"><MapPin className="w-3 h-3" />{property.address.split(',')[0]}</span>
        )}
        {tenant && (
          <span className="flex items-center gap-1"><User className="w-3 h-3" />{tenant.name}</span>
        )}
        {request.contractor_name && (
          <span className="flex items-center gap-1"><Wrench className="w-3 h-3" />{request.contractor_name}</span>
        )}
        {request.scheduled_date && (
          <span className="flex items-center gap-1"><Calendar className="w-3 h-3" />Scheduled: {format(parseISO(request.scheduled_date), 'dd MMM yyyy')}</span>
        )}
        {(request.photo_urls || []).length > 0 && (
          <span className="flex items-center gap-1"><Image className="w-3 h-3" />{request.photo_urls.length} photo{request.photo_urls.length > 1 ? 's' : ''}</span>
        )}
        {request.estimated_cost && (
          <span>Est: {formatCurrency(request.estimated_cost)}</span>
        )}
        {request.actual_cost && (
          <span>Actual: {formatCurrency(request.actual_cost)}</span>
        )}
      </div>

      {/* Photo thumbnails */}
      {(request.photo_urls || []).length > 0 && (
        <div className="flex gap-2 mt-3 flex-wrap">
          {request.photo_urls.slice(0, 4).map((url, i) => (
            <a key={i} href={url} target="_blank" rel="noopener noreferrer">
              <img src={url} alt="" className="w-14 h-14 object-cover rounded-md border border-border hover:opacity-80 transition-opacity" />
            </a>
          ))}
          {request.photo_urls.length > 4 && (
            <div className="w-14 h-14 rounded-md border border-border bg-muted flex items-center justify-center text-xs text-muted-foreground">
              +{request.photo_urls.length - 4}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Switch } from '@/components/ui/switch';
import { base44 } from '@/api/base44Client';
import { Upload, X, Loader2, AlertTriangle, Info } from 'lucide-react';
import PropertyCombobox from '@/components/forms/PropertyCombobox';
import { format } from 'date-fns';


const MONTHS = [
  { value: '01', label: 'January' },  { value: '02', label: 'February' },
  { value: '03', label: 'March' },    { value: '04', label: 'April' },
  { value: '05', label: 'May' },      { value: '06', label: 'June' },
  { value: '07', label: 'July' },     { value: '08', label: 'August' },
  { value: '09', label: 'September' },{ value: '10', label: 'October' },
  { value: '11', label: 'November' }, { value: '12', label: 'December' },
];
const YEARS = Array.from({ length: 15 }, (_, i) => String(new Date().getFullYear() - 5 + i));

function PeriodPicker({ value, onChange }) {
  const parse = (v) => {
    const p = (v || format(new Date(), 'yyyy-MM')).split('-');
    return { yr: p[0] || String(new Date().getFullYear()), mo: p[1] || format(new Date(), 'MM') };
  };
  const [month, setMonth] = React.useState(() => parse(value).mo);
  const [year,  setYear]  = React.useState(() => parse(value).yr);

  React.useEffect(() => {
    const { yr, mo } = parse(value);
    setMonth(mo);
    setYear(yr);
  }, [value]);

  const handleMonth = (m) => { setMonth(m); onChange(`${year}-${m}`); };
  const handleYear  = (y) => { setYear(y);  onChange(`${y}-${month}`); };

  return (
    <div className="flex gap-2">
      <Select value={month} onValueChange={handleMonth}>
        <SelectTrigger className="flex-1"><SelectValue placeholder="Month" /></SelectTrigger>
        <SelectContent>
          {MONTHS.map(m => <SelectItem key={m.value} value={m.value}>{m.label}</SelectItem>)}
        </SelectContent>
      </Select>
      <Select value={year} onValueChange={handleYear}>
        <SelectTrigger className="w-28"><SelectValue placeholder="Year" /></SelectTrigger>
        <SelectContent>
          {YEARS.map(y => <SelectItem key={y} value={y}>{y}</SelectItem>)}
        </SelectContent>
      </Select>
    </div>
  );
}

export default function MaintenanceForm({ request, properties, tenants, landlords = [], onSubmit, onCancel, isAdminForm = false }) {
