    property_id: '', tenant_id: '', title: '', description: '',
    category: 'other', priority: 'medium', status: 'pending',
    photo_urls: [], contractor_name: '', contractor_phone: '', contractor_email: '',
    estimated_cost: '', actual_cost: '', scheduled_date: '', resolved_date: '', admin_notes: '',
    charge_to_landlord: false, landlord_id: '', cost_bearer: 'agency', linked_expense_id: '', charge_period: ''
  });
  const [uploading, setUploading] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  // Auto-link landlord when property changes
  useEffect(() => {
    if (data.property_id) {
      const prop = properties.find(p => p.id === data.property_id);
      if (prop?.landlord_id && prop.landlord_id !== data.landlord_id) {
        setData(prev => ({ ...prev, landlord_id: prop.landlord_id }));
      }
    }
  }, [data.property_id, properties]);

  const handlePhotoUpload = async (e) => {
    const files = Array.from(e.target.files);
    if (!files.length) return;
    setUploading(true);
    const uploads = await Promise.all(files.map(file => base44.integrations.Core.UploadFile({ file })));
    const urls = uploads.map(u => u.file_url);
    setData(prev => ({ ...prev, photo_urls: [...(prev.photo_urls || []), ...urls] }));
    setUploading(false);
  };

  const removePhoto = (idx) => {
    setData(prev => ({ ...prev, photo_urls: prev.photo_urls.filter((_, i) => i !== idx) }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (submitting) return;
    setSubmitting(true);
    const cleaned = {
      ...data,
      estimated_cost: data.estimated_cost !== '' && data.estimated_cost != null ? Number(data.estimated_cost) : null,
      actual_cost: data.actual_cost !== '' && data.actual_cost != null ? Number(data.actual_cost) : null,
    };
    try { await onSubmit(cleaned); } finally { setSubmitting(false); }
  };

