            </SelectContent>
          </Select>
        </div>
        <div className="space-y-2 sm:col-span-2">
          <Label>Issue Title *</Label>
          <Input value={data.title} onChange={e => setData({ ...data, title: e.target.value })} placeholder="e.g. Boiler not working" required />
        </div>
        <div className="space-y-2">
          <Label>Category</Label>
          <Select value={data.category} onValueChange={v => setData({ ...data, category: v })}>
            <SelectTrigger><SelectValue /></SelectTrigger>
            <SelectContent>
              {['plumbing','electrical','heating','structural','appliances','pest_control','cleaning','other'].map(c => (
                <SelectItem key={c} value={c}>{c.replace('_', ' ')}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
        <div className="space-y-2">
          <Label>Priority</Label>
          <Select value={data.priority} onValueChange={v => setData({ ...data, priority: v })}>
            <SelectTrigger><SelectValue /></SelectTrigger>
            <SelectContent>
              <SelectItem value="low">Low</SelectItem>
              <SelectItem value="medium">Medium</SelectItem>
              <SelectItem value="high">High</SelectItem>
              <SelectItem value="emergency">Emergency</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>

      <div className="space-y-2">
        <Label>Description</Label>
        <Textarea value={data.description || ''} onChange={e => setData({ ...data, description: e.target.value })} rows={3} placeholder="Describe the issue in detail..." />
      </div>

