              </div>
              <div className="space-y-2">
                <Label>Phone</Label>
                <Input value={data.contractor_phone || ''} onChange={e => setData({ ...data, contractor_phone: e.target.value })} />
              </div>
              <div className="space-y-2">
                <Label>Email</Label>
                <Input type="email" value={data.contractor_email || ''} onChange={e => setData({ ...data, contractor_email: e.target.value })} />
              </div>
            </div>
          </div>

          <div className="border-t border-border pt-4">
            <p className="text-sm font-medium text-muted-foreground mb-3">Costs</p>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Estimated Cost (£)</Label>
                <Input type="number" min="0" step="0.01" value={data.estimated_cost || ''} onChange={e => setData({ ...data, estimated_cost: Number(e.target.value) })} />
              </div>
              <div className="space-y-2">
