import React, { useState } from 'react';
import { format, parseISO, getDate, getDaysInMonth, setDate } from 'date-fns';
import { Mail, Bell } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { formatCurrency } from '@/lib/computations';
import RentReminderModal from './RentReminderModal';

// Returns how many days until next due date for this tenant (based on lease_start day)
function getDaysUntilDue(tenant) {
  if (!tenant.lease_start) return null;
  const today = new Date();
  const dueDay = getDate(parseISO(tenant.lease_start));
  const daysInMonth = getDaysInMonth(today);
  const safeDueDay = Math.min(dueDay, daysInMonth);

  let nextDue = setDate(today, safeDueDay);
  if (nextDue <= today) {
    const nextMonth = new Date(today.getFullYear(), today.getMonth() + 1, 1);
    const daysInNextMonth = getDaysInMonth(nextMonth);
    nextDue = setDate(nextMonth, Math.min(dueDay, daysInNextMonth));
  }
  const diff = Math.ceil((nextDue - today) / (1000 * 60 * 60 * 24));
  return { days: diff, nextDue };
}

export default function RentDuePanel({ tenants, properties }) {
  const [reminderTarget, setReminderTarget] = useState(null);

  const activeTenants = tenants.filter(t => t.status === 'active' && t.email);

  const upcoming = activeTenants
    .map(t => {
      const result = getDaysUntilDue(t);
      if (!result) return null;
      const property = properties.find(p => p.id === t.property_id);
      return { tenant: t, property, ...result };
    })
    .filter(Boolean)
    .filter(x => x.days <= 7)
    .sort((a, b) => a.days - b.days);

  if (upcoming.length === 0) return null;

  return (
    <>
      <div className="bg-card rounded-xl border border-border overflow-hidden mb-8">
        <div className="px-5 py-4 border-b border-border flex items-center gap-2">
          <Bell className="w-4 h-4 text-amber-500" />
          <h2 className="text-sm font-semibold text-foreground">Rent Due Soon (Next 7 Days)</h2>
          <span className="ml-auto bg-amber-100 text-amber-700 text-xs font-semibold px-2 py-0.5 rounded-full">{upcoming.length}</span>
        </div>
        <div className="divide-y divide-border">
          {upcoming.map(({ tenant, property, days, nextDue }) => (
            <div key={tenant.id} className="flex items-center justify-between px-5 py-3 hover:bg-muted/30 transition-colors">
              <div className="min-w-0">
                <p className="text-sm font-medium text-foreground truncate">{tenant.name}</p>
                <p className="text-xs text-muted-foreground truncate">{property?.address}</p>
              </div>
              <div className="flex items-center gap-4 shrink-0 ml-4">
                <div className="text-right">
                  <p className="text-sm font-semibold text-foreground">{formatCurrency(tenant.monthly_rent)}</p>
                  <p className={`text-xs font-medium ${days === 0 ? 'text-red-600' : days <= 2 ? 'text-amber-600' : 'text-emerald-600'}`}>
                    {days === 0 ? 'Due today' : `Due in ${days}d`} · {format(nextDue, 'dd MMM')}
                  </p>
                </div>
                <Button size="sm" variant="outline" className="gap-1.5 text-xs" onClick={() => setReminderTarget({ tenant, property })}>
                  <Mail className="w-3.5 h-3.5" />
                  Remind
                </Button>
              </div>
            </div>
          ))}
        </div>
      </div>

      {reminderTarget && (
        <RentReminderModal
          open={!!reminderTarget}
          tenant={reminderTarget.tenant}
          property={reminderTarget.property}
          onClose={() => setReminderTarget(null)}
        />
      )}
    </>
  );
}

import React, { useState } from 'react';
import { base44 } from '@/api/base44Client';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { Loader2, Mail, CheckCircle2 } from 'lucide-react';
import { formatCurrency } from '@/lib/computations';
import { format, parseISO } from 'date-fns';

export default function RentReminderModal({ tenant, property, open, onClose }) {
  const [sending, setSending] = useState(false);
  const [sent, setSent] = useState(false);
  const [error, setError] = useState('');

  const dueDay = tenant?.lease_start ? format(parseISO(tenant.lease_start), 'd') : '1st';
  const defaultSubject = `Rent Payment Reminder – ${property?.address || ''}`;
  const defaultBody = `Dear ${tenant?.name || 'Tenant'},

We hope you are well. This is a friendly reminder that your monthly rent payment of ${formatCurrency(tenant?.monthly_rent || 0)} is due.

Property: ${property?.address || ''}
Amount Due: ${formatCurrency(tenant?.monthly_rent || 0)}
Payment Due Date: ${dueDay}${getOrdinalSuffix(dueDay)} of each month

Please ensure your payment is made on time to avoid any late fees. If you have already made your payment, please disregard this message.

If you have any questions or concerns, please don't hesitate to contact us.

Kind regards,
Property Management Team`;

  const [subject, setSubject] = useState(defaultSubject);
  const [body, setBody] = useState(defaultBody);

  const handleSend = async () => {
    if (!tenant?.email) return;
    setSending(true);
    setError('');
    try {
      await base44.integrations.Core.SendEmail({ to: tenant.email, subject, body, from_name: 'ASA Estates Ltd' });
      setSent(true);
      setTimeout(() => { setSent(false); onClose(); }, 1500);
    } catch (err) {
      setError('Email could not be sent automatically. Please copy the message below and send it manually to: ' + tenant.email);
    } finally {
      setSending(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Mail className="w-5 h-5 text-primary" />
            Send Rent Reminder
          </DialogTitle>
        </DialogHeader>

        {sent ? (
          <div className="flex flex-col items-center gap-3 py-8 text-emerald-600">
            <CheckCircle2 className="w-12 h-12" />
            <p className="font-medium">Reminder sent to {tenant?.email}</p>
          </div>
        ) : (
          <div className="space-y-4">
            <div className="bg-muted rounded-lg px-4 py-3 text-sm space-y-1">
              <p><span className="text-muted-foreground">To:</span> <span className="font-medium">{tenant?.name}</span> &lt;{tenant?.email}&gt;</p>
              <p><span className="text-muted-foreground">Property:</span> {property?.address}</p>
              <p><span className="text-muted-foreground">Rent:</span> {formatCurrency(tenant?.monthly_rent || 0)}/month</p>
            </div>

            <div className="space-y-2">
              <Label>Subject</Label>
              <Input value={subject} onChange={e => setSubject(e.target.value)} />
            </div>

            <div className="space-y-2">
              <Label>Message</Label>
              <Textarea value={body} onChange={e => setBody(e.target.value)} rows={14} className="text-sm font-mono" />
            </div>

            {!tenant?.email && (
              <p className="text-sm text-destructive">This tenant has no email address on record.</p>
            )}
            {error && (
              <div className="rounded-lg bg-amber-50 border border-amber-200 px-4 py-3 text-sm text-amber-800">
                <p className="font-medium mb-1">⚠ Could not send automatically</p>
                <p>{error}</p>
              </div>
            )}
          </div>
        )}

        {!sent && (
          <DialogFooter>
            <Button variant="outline" onClick={onClose}>Cancel</Button>
            <Button onClick={handleSend} disabled={sending || !tenant?.email}>
              {sending ? <><Loader2 className="w-4 h-4 mr-2 animate-spin" /> Sending...</> : <><Mail className="w-4 h-4 mr-2" /> Send Reminder</>}
            </Button>
          </DialogFooter>
        )}
      </DialogContent>
    </Dialog>
  );
}

function getOrdinalSuffix(n) {
  const num = parseInt(n);
  if (num >= 11 && num <= 13) return 'th';
  switch (num % 10) {
    case 1: return 'st';
    case 2: return 'nd';
    case 3: return 'rd';
    default: return 'th';
  }
}

