 *   editing                       — an existing TenantInvoiceCharge to edit (optional)
 */
export default function AddTenantChargeDialog({ open, onClose, tenantId, propertyId, periodMonth, tenantName, monthLabel, editing }) {
  const qc = useQueryClient();
  const [data, setData] = useState({
    amount: editing?.amount ?? '',
    description: editing?.description ?? '',
    category: editing?.category ?? 'other',
    notes: editing?.notes ?? '',
  });
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  const save = async () => {
    const amt = Number(data.amount);
    if (!data.description.trim()) { setError('Please enter a description.'); return; }
    if (!amt || amt <= 0) { setError('Please enter an amount greater than zero.'); return; }
    setError('');
    setSaving(true);
    try {
      const payload = {
        tenant_id: tenantId,
        property_id: propertyId,
        period_month: periodMonth,
        amount: amt,
        description: data.description.trim(),
        category: data.category,
        notes: data.notes?.trim() || undefined,
      };
      if (editing?.id) {
        await base44.entities.TenantInvoiceCharge.update(editing.id, payload);
      } else {
        await base44.entities.TenantInvoiceCharge.create(payload);
      }
      qc.invalidateQueries({ queryKey: ['tenant_invoice_charges'] });
      onClose(true);
    } catch (e) {
      setError(e?.message || 'Could not save the charge.');
    } finally {
      setSaving(false);
    }
  };

  const label = monthLabel || (periodMonth ? format(parseISO(periodMonth + '-01'), 'MMM yyyy') : '');

  return (
    <Dialog open={open} onOpenChange={(o) => { if (!o && !saving) onClose(false); }}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>{editing ? 'Edit charge' : 'Add charge to invoice'}</DialogTitle>
          <p className="text-sm text-muted-foreground">
            {tenantName ? `${tenantName} — ` : ''}{label}. This adds to what the tenant owes for this month.
          </p>
        </DialogHeader>

        <div className="grid grid-cols-2 gap-4 py-1">
          <div className="space-y-2">
            <Label>Amount (£) *</Label>
            <Input
              type="number" step="0.01" min="0" inputMode="decimal"
              value={data.amount}
              onChange={(e) => setData(d => ({ ...d, amount: e.target.value }))}
              placeholder="0.00"
            />
          </div>
          <div className="space-y-2">
            <Label>Category</Label>
            <Select value={data.category} onValueChange={(v) => setData(d => ({ ...d, category: v }))}>
              <SelectTrigger><SelectValue /></SelectTrigger>
              <SelectContent>
                {CATEGORIES.map(c => <SelectItem key={c} value={c}><span className="capitalize">{c.replace('_', ' ')}</span></SelectItem>)}
              </SelectContent>
            </Select>
          </div>
          <div className="space-y-2 col-span-2">
            <Label>Description *</Label>
            <Input
              value={data.description}
              onChange={(e) => setData(d => ({ ...d, description: e.target.value }))}
              placeholder="e.g. Carpet cleaning, replacement key"
            />
          </div>
          <div className="space-y-2 col-span-2">
            <Label>Notes (optional)</Label>
            <Textarea
              rows={2}
              value={data.notes}
              onChange={(e) => setData(d => ({ ...d, notes: e.target.value }))}
              placeholder="Any extra detail…"
              className="resize-none"
            />
          </div>
        </div>

        {error && <p className="text-sm font-medium text-red-600">{error}</p>}

        <DialogFooter className="gap-2">
          <Button variant="outline" onClick={() => onClose(false)} disabled={saving}>Cancel</Button>
          <Button onClick={save} disabled={saving}>{saving ? 'Saving…' : (editing ? 'Save changes' : 'Add charge')}</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

