  const updateItem = (idx, field, val) => {
    const items = section.items.map((item, i) => i === idx ? { ...item, [field]: val } : item);
    onChange({ ...section, items });
  };

  const addItem = () => {
    onChange({ ...section, items: [...section.items, { name: '', options: ['Good', 'Fair', 'Poor'], value: '', comment: '' }] });
  };

  const removeItem = (idx) => {
    onChange({ ...section, items: section.items.filter((_, i) => i !== idx) });
