export default function InspectionForm({ property, tenants = [], initialData, onSubmit, onCancel }) {
  const parseSections = () => {
    if (initialData?.sections) {
      try { return JSON.parse(initialData.sections); } catch {}
    }
    return DEFAULT_SECTIONS.map(s => ({ ...s, items: s.items.map(i => ({ ...i })) }));
  };

  const [meta, setMeta] = useState({
    tenant_name: initialData?.tenant_name || '',
    inspection_date: initialData?.inspection_date || format(new Date(), 'yyyy-MM-dd'),
    inspection_type: initialData?.inspection_type || 'routine',
    inspector_name: initialData?.inspector_name || '',
    status: initialData?.status || 'draft',
  });
  const [sections, setSections] = useState(parseSections);
  const [summaryTenant, setSummaryTenant] = useState(initialData?.summary_tenant || '');
  const [summaryAgent, setSummaryAgent] = useState(initialData?.summary_agent || '');
  const [saving, setSaving] = useState(false);

  const updateSection = (idx, updated) => {
    setSections(s => s.map((sec, i) => i === idx ? updated : sec));
  };

  const deleteSection = (idx) => {
    setSections(s => s.filter((_, i) => i !== idx));
  };

  const addRoom = (type) => {
    const existing = sections.filter(s => s.id?.startsWith(type === 'bedroom' ? 'bedroom_' : type === 'reception' ? 'reception_' : 'bathroom_'));
    const num = existing.length + 1;
    if (type === 'bedroom') setSections(s => [...s, BEDROOM_TEMPLATE(`Bedroom ${num}`)]);
    else if (type === 'reception') setSections(s => [...s, RECEPTION_TEMPLATE(`Reception ${num}`)]);
    else if (type === 'bathroom') setSections(s => [...s, BATHROOM_TEMPLATE(`Bathroom ${num}`)]);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (saving) return;
    setSaving(true);
    await onSubmit({
      ...meta,
      property_id: property.id,
      sections: JSON.stringify(sections),
      summary_tenant: summaryTenant,
      summary_agent: summaryAgent,
    });
    setSaving(false);
  };

  // Populate tenant name from selected tenant
  const handleTenantSelect = (tenantId) => {
    const t = tenants.find(t => t.id === tenantId);
    if (t) setMeta(m => ({ ...m, tenant_name: t.name }));
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-6">
      {/* Header info */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 bg-muted/30 rounded-xl p-4 border border-border">
        <div className="space-y-1">
          <Label>Inspection Date *</Label>
          <Input type="date" value={meta.inspection_date} onChange={e => setMeta(m => ({ ...m, inspection_date: e.target.value }))} required />
        </div>
        <div className="space-y-1">
          <Label>Type of Inspection *</Label>
          <Select value={meta.inspection_type} onValueChange={v => setMeta(m => ({ ...m, inspection_type: v }))}>
            <SelectTrigger><SelectValue /></SelectTrigger>
            <SelectContent>
              <SelectItem value="check_in">Check-in</SelectItem>
              <SelectItem value="check_out">Check-out</SelectItem>
              <SelectItem value="routine">Routine</SelectItem>
            </SelectContent>
          </Select>
        </div>
        <div className="space-y-1">
          <Label>Tenant Name</Label>
          {tenants.length > 0 ? (
            <Select value={''} onValueChange={handleTenantSelect}>
              <SelectTrigger><SelectValue placeholder={meta.tenant_name || 'Select or type below'} /></SelectTrigger>
              <SelectContent>
                {tenants.map(t => <SelectItem key={t.id} value={t.id}>{t.name}</SelectItem>)}
              </SelectContent>
            </Select>
          ) : (
            <Input value={meta.tenant_name} onChange={e => setMeta(m => ({ ...m, tenant_name: e.target.value }))} placeholder="Tenant full name" />
          )}
          {tenants.length > 0 && (
            <Input value={meta.tenant_name} onChange={e => setMeta(m => ({ ...m, tenant_name: e.target.value }))} placeholder="Or type manually" className="mt-1" />
          )}
        </div>
        <div className="space-y-1">
          <Label>Inspector Name</Label>
          <Input value={meta.inspector_name} onChange={e => setMeta(m => ({ ...m, inspector_name: e.target.value }))} placeholder="Name of inspector" />
        </div>
        <div className="space-y-1">
          <Label>Status</Label>
          <Select value={meta.status} onValueChange={v => setMeta(m => ({ ...m, status: v }))}>
            <SelectTrigger><SelectValue /></SelectTrigger>
            <SelectContent>
              <SelectItem value="draft">Draft</SelectItem>
              <SelectItem value="completed">Completed</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>

      {/* Add room buttons */}
      <div className="flex flex-wrap gap-2 items-center">
        <span className="text-sm text-muted-foreground font-medium">Add room:</span>
        <Button type="button" variant="outline" size="sm" onClick={() => addRoom('bedroom')}>
          <Plus className="w-3.5 h-3.5 mr-1" />Bedroom
        </Button>
        <Button type="button" variant="outline" size="sm" onClick={() => addRoom('reception')}>
          <Plus className="w-3.5 h-3.5 mr-1" />Reception
        </Button>
        <Button type="button" variant="outline" size="sm" onClick={() => addRoom('bathroom')}>
          <Plus className="w-3.5 h-3.5 mr-1" />Bathroom
        </Button>
      </div>

      {/* Section panels */}
      <div className="space-y-4">
        {sections.map((section, idx) => (
          <SectionPanel
            key={section.id || idx}
            section={section}
            onChange={(updated) => updateSection(idx, updated)}
            onDelete={() => deleteSection(idx)}
            canDelete={true}
          />
        ))}
      </div>

      {/* Summary */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div className="space-y-1">
          <Label>Summary — Maintenance by Tenant</Label>
          <Textarea value={summaryTenant} onChange={e => setSummaryTenant(e.target.value)} rows={3} placeholder="Items tenant is responsible for..." />
        </div>
        <div className="space-y-1">
          <Label>Summary — Maintenance by Agent / Landlord</Label>
          <Textarea value={summaryAgent} onChange={e => setSummaryAgent(e.target.value)} rows={3} placeholder="Items agent/landlord is responsible for..." />
        </div>
      </div>

      <div className="flex gap-2 justify-end pt-2">
        <Button type="button" variant="outline" onClick={onCancel}>Cancel</Button>
        <Button type="submit" disabled={saving}>{saving ? 'Saving...' : initialData ? 'Save Changes' : 'Save Report'}</Button>
      </div>
    </form>
  );
}

import React, { useState } from 'react';
import { formatCurrency, calculateArrears, calculatePeriodArrears } from '@/lib/computations';
import { useRentHistoryAll } from '@/hooks/useAllData';
import { Link } from 'react-router-dom';
import { Button } from '@/components/ui/button';
import StatusBadge from '@/components/ui/StatusBadge';
import { Eye, AlertTriangle, ChevronDown, ChevronRight } from 'lucide-react';
import StatCard from '@/components/ui/StatCard';
import { format, parseISO } from 'date-fns';

function formatPeriodLabel(yyyyMM) {
  try { return format(parseISO(`${yyyyMM}-01`), 'MMMM yyyy'); } catch { return yyyyMM; }
}

function PeriodBreakdown({ tenant, pPayments, rentHistory }) {
  const periods = calculatePeriodArrears(tenant, pPayments, rentHistory);
  return (
    <div className="mt-2 ml-4 border-l-2 border-border pl-4 space-y-1">
      {periods.map(p => (
        <div key={p.period} className="flex items-center gap-3 text-xs py-1">
          <span className="w-28 text-muted-foreground">{formatPeriodLabel(p.period)}</span>
          <span className="w-20 text-right">{formatCurrency(p.rent)}</span>
          <span className="w-20 text-right text-emerald-600">{formatCurrency(p.paid)}</span>
          <span className={`w-20 text-right font-semibold ${p.arrears > 0 ? 'text-red-600' : 'text-emerald-600'}`}>{p.arrears > 0 ? formatCurrency(p.arrears) : '✓'}</span>
          <span>
            {p.status === 'paid' && <StatusBadge color="green">Paid</StatusBadge>}
            {p.status === 'partial' && <StatusBadge color="yellow">Partial</StatusBadge>}
            {p.status === 'unpaid' && <StatusBadge color="red">Unpaid</StatusBadge>}
          </span>
          {p.creditForward > 0 && <span className="text-xs text-blue-600">+{formatCurrency(p.creditForward)} fwd</span>}
        </div>
      ))}
    </div>
  );
}

export default function PropertyArrears({ property, pTenants, pPayments }) {
  const [expanded, setExpanded] = useState({});
  const { data: rentHistory = [] } = useRentHistoryAll();

  const arrearsData = pTenants
    .filter(t => t.status !== 'ended')
    .map(t => {
      const tPayments = pPayments.filter(p => p.tenant_id === t.id);
      const tHistory = rentHistory.filter(r => r.tenant_id === t.id);
      const arrears = calculateArrears(t, tPayments, tHistory);
      const totalPaid = tPayments.reduce((s, p) => s + (p.amount || 0), 0);
      return { tenant: t, tPayments, tHistory, arrears, totalPaid };
    })
    .sort((a, b) => b.arrears - a.arrears);

  const inArrears = arrearsData.filter(d => d.arrears > 0);
  const totalArrears = inArrears.reduce((s, d) => s + d.arrears, 0);
  const clearTenants = arrearsData.length - inArrears.length;

  return (
    <div>
      <div className="flex items-center justify-between mb-4">
        <div>
          <h2 className="text-sm font-semibold">Arrears</h2>
          <p className="text-xs text-muted-foreground">Calculated per rent period — Payment Date ≠ Rent Period</p>
        </div>
      </div>

      <div className="grid grid-cols-3 gap-4 mb-6">
        <StatCard label="Total Arrears" value={formatCurrency(totalArrears)} icon={AlertTriangle} color={totalArrears > 0 ? 'destructive' : 'success'} />
        <StatCard label="Tenants in Arrears" value={inArrears.length} icon={AlertTriangle} color={inArrears.length > 0 ? 'destructive' : 'success'} />
        <StatCard label="Tenants Clear" value={clearTenants} icon={AlertTriangle} color="success" />
      </div>

      {arrearsData.length === 0 ? (
        <div className="text-center py-16 bg-muted/30 rounded-xl border border-border">
          <p className="text-muted-foreground font-semibold">No active tenants</p>
        </div>
      ) : (
        <div className="bg-card rounded-xl border border-border overflow-hidden">
          {arrearsData.map(d => (
            <div key={d.tenant.id} className="border-b border-border last:border-0">
              <div
                className={`flex items-center gap-3 px-5 py-3 cursor-pointer hover:bg-muted/30 transition-colors ${d.arrears > 0 ? 'bg-red-50/30' : ''}`}
                onClick={() => setExpanded(e => ({ ...e, [d.tenant.id]: !e[d.tenant.id] }))}
              >
                <div className="flex-1 flex items-center gap-3">
                  {expanded[d.tenant.id] ? <ChevronDown className="w-4 h-4 text-muted-foreground" /> : <ChevronRight className="w-4 h-4 text-muted-foreground" />}
                  <span className="font-medium text-sm">{d.tenant.name}</span>
                  <StatusBadge color={d.tenant.status === 'active' ? 'green' : 'yellow'}>{d.tenant.status}</StatusBadge>
                </div>
                <div className="text-xs text-muted-foreground">Rent: {formatCurrency(d.tenant.monthly_rent)}</div>
                <div className="text-xs text-emerald-600">Paid: {formatCurrency(d.totalPaid)}</div>
                <div className={`text-sm font-bold w-24 text-right ${d.arrears > 0 ? 'text-red-600' : 'text-emerald-600'}`}>
                  {d.arrears > 0 ? `${formatCurrency(d.arrears)} owed` : '✓ Clear'}
                </div>
                <Link to={`/TenantDetail?id=${d.tenant.id}`} onClick={e => e.stopPropagation()}>
                  <Button variant="ghost" size="sm"><Eye className="w-4 h-4" /></Button>
                </Link>
              </div>
              {expanded[d.tenant.id] && (
                <div className="px-5 pb-4 bg-muted/10">
                  <div className="flex items-center gap-3 text-xs font-semibold text-muted-foreground mb-1 ml-4 pl-4">
                    <span className="w-28">Period</span>
                    <span className="w-20 text-right">Expected</span>
                    <span className="w-20 text-right">Paid</span>
                    <span className="w-20 text-right">Arrears</span>
                    <span>Status</span>
                  </div>
                  <PeriodBreakdown tenant={d.tenant} pPayments={d.tPayments} rentHistory={d.tHistory} />
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { base44 } from '@/api/base44Client';
import { useQueryClient } from '@tanstack/react-query';
import { useRole } from '@/hooks/useRole';
import { logAction } from '@/lib/audit';
import { useCRMEntries } from '@/hooks/useAllData';
import StatusBadge from '@/components/ui/StatusBadge';
import ConfirmDialog from '@/components/ui/ConfirmDialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import {
  Plus, FileText, Phone, Mail, MessageSquare, Calendar, CheckSquare,
  User, Building2, Trash2, Pencil, CheckCircle2, Circle
} from 'lucide-react';
import { format, parseISO } from 'date-fns';

// =============================================================================
// ENTRY-TYPE METADATA
// =============================================================================
const TYPE_DEFS = {
  note:    { label: 'Note',    icon: FileText,        color: 'blue'   },
  call:    { label: 'Call',    icon: Phone,           color: 'green'  },
  email:   { label: 'Email',   icon: Mail,            color: 'blue'   },
  message: { label: 'Message', icon: MessageSquare,   color: 'gray'   },
  meeting: { label: 'Meeting', icon: Calendar,        color: 'yellow' },
  task:    { label: 'Task',    icon: CheckSquare,     color: 'yellow' },
};

const TYPE_BG = {
  note:    'bg-sky-50 border-sky-200',
  call:    'bg-emerald-50 border-emerald-200',
  email:   'bg-blue-50 border-blue-200',
  message: 'bg-slate-50 border-slate-200',
  meeting: 'bg-amber-50 border-amber-200',
  task:    'bg-amber-50 border-amber-200',
};

const getTypeDef = (t) => TYPE_DEFS[t] || TYPE_DEFS.note;

// =============================================================================
// MAIN COMPONENT
// =============================================================================
export default function PropertyCRM({ property, landlord, pTenants }) {
  const { user, isAdmin } = useRole();
  const queryClient = useQueryClient();
  const { data: allEntries } = useCRMEntries();

  // Filter to entries for this property
  const entries = useMemo(() => {
    return allEntries
      .filter(e => e.property_id === property.id)
      .sort((a, b) => (b.created_date || '').localeCompare(a.created_date || ''));
  }, [allEntries, property.id]);

  // UI state
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(null);

  const openNew = () => { setEditing(null); setShowForm(true); };
  const openEdit = (entry) => { setEditing(entry); setShowForm(true); };

  const handleSave = async (formData) => {
    const payload = {
      ...formData,
      property_id: property.id,
      landlord_id: property.landlord_id,
    };
    if (editing) {
      await base44.entities.CRMEntry.update(editing.id, payload);
      await logAction({
        user, action: 'update', entityType: 'CRMEntry', entityId: editing.id,
        summary: `Updated ${getTypeDef(formData.type).label} on ${property.address}`,
        oldValue: editing, newValue: payload,
      });
    } else {
      const created = await base44.entities.CRMEntry.create(payload);
      await logAction({
        user, action: 'create', entityType: 'CRMEntry', entityId: created.id,
        summary: `Added ${getTypeDef(formData.type).label} "${formData.subject}" on ${property.address}`,
        newValue: payload,
      });
    }
    queryClient.invalidateQueries({ queryKey: ['crm_entries'] });
    setShowForm(false);
    setEditing(null);
  };

  const handleDelete = async (entry) => {
    await base44.entities.CRMEntry.delete(entry.id);
    await logAction({
      user, action: 'delete', entityType: 'CRMEntry', entityId: entry.id,
      summary: `Deleted ${getTypeDef(entry.type).label} "${entry.subject}" from ${property.address}`,
      oldValue: entry,
    });
    queryClient.invalidateQueries({ queryKey: ['crm_entries'] });
    setConfirmDelete(null);
  };

  const handleToggleComplete = async (entry) => {
    await base44.entities.CRMEntry.update(entry.id, { completed: !entry.completed });
    queryClient.invalidateQueries({ queryKey: ['crm_entries'] });
  };

  const activeTenants = pTenants.filter(t => t.status === 'active');

  return (
    <div>
      {/* Header */}
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between mb-5 sm:mb-6">
        <div>
          <h2 className="text-sm font-semibold text-foreground">Notes & Activity</h2>
          <p className="text-xs text-muted-foreground mt-0.5">Calls, emails, meetings and tasks for this property</p>
        </div>
        <Button size="sm" onClick={openNew}>
          <Plus className="w-4 h-4 mr-1.5" />Add Entry
        </Button>
      </div>

      {/* Contact summary */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-3 mb-6">
        {landlord && (
          <div className="bg-card border border-border rounded-xl p-4 elev-1">
            <div className="flex items-center gap-2 mb-2.5">
              <User className="w-4 h-4 text-primary" />
              <p className="text-sm font-semibold">Landlord</p>
            </div>
            <div className="space-y-1 text-sm">
              <p className="font-medium">{landlord.name}</p>
              {landlord.email && (
                <a href={`mailto:${landlord.email}`} className="text-muted-foreground hover:text-foreground flex items-center gap-1.5 text-xs">
                  <Mail className="w-3.5 h-3.5" />{landlord.email}
                </a>
              )}
              {landlord.phone && (
                <a href={`tel:${landlord.phone}`} className="text-muted-foreground hover:text-foreground flex items-center gap-1.5 text-xs">
                  <Phone className="w-3.5 h-3.5" />{landlord.phone}
                </a>
              )}
            </div>
          </div>
        )}
        <div className="bg-card border border-border rounded-xl p-4 elev-1">
          <div className="flex items-center gap-2 mb-2.5">
            <Building2 className="w-4 h-4 text-primary" />
            <p className="text-sm font-semibold">Active Tenants ({activeTenants.length})</p>
          </div>
          {activeTenants.length === 0 ? (
            <p className="text-xs text-muted-foreground">No active tenants</p>
          ) : (
            <div className="space-y-2">
              {activeTenants.map(t => (
                <div key={t.id} className="text-sm">
                  <p className="font-medium">{t.name}</p>
                  {t.email && (
                    <a href={`mailto:${t.email}`} className="text-muted-foreground hover:text-foreground flex items-center gap-1.5 text-xs">
                      <Mail className="w-3 h-3" />{t.email}
                    </a>
                  )}
                  {t.phone && (
                    <a href={`tel:${t.phone}`} className="text-muted-foreground hover:text-foreground flex items-center gap-1.5 text-xs">
                      <Phone className="w-3 h-3" />{t.phone}
                    </a>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Activity log */}
      <div>
        <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider mb-3">
          Activity Log ({entries.length})
        </p>

        {entries.length === 0 ? (
          <div className="text-center py-12 bg-muted/30 rounded-xl border border-dashed border-border">
            <FileText className="w-8 h-8 mx-auto mb-2 text-muted-foreground opacity-40" />
            <p className="text-sm text-muted-foreground">No entries yet</p>
            <p className="text-xs text-muted-foreground mt-1">Log calls, emails, meetings or notes about this property</p>
          </div>
        ) : (
          <div className="space-y-2.5">
            {entries.map(entry => (
              <EntryCard
                key={entry.id}
                entry={entry}
                canEdit={isAdmin}
                onEdit={() => openEdit(entry)}
                onDelete={() => setConfirmDelete(entry)}
                onToggleComplete={() => handleToggleComplete(entry)}
              />
            ))}
          </div>
        )}
      </div>

      <CRMDialog
        open={showForm}
        onClose={() => { setShowForm(false); setEditing(null); }}
        existing={editing}
        onSave={handleSave}
      />

      <ConfirmDialog
        open={!!confirmDelete}
        title="Delete entry"
        description={`Delete "${confirmDelete?.subject}"? This cannot be undone.`}
        onConfirm={() => handleDelete(confirmDelete)}
        onCancel={() => setConfirmDelete(null)}
      />
    </div>
  );
}

// =============================================================================
// ENTRY CARD
// =============================================================================
function EntryCard({ entry, canEdit, onEdit, onDelete, onToggleComplete }) {
  const def = getTypeDef(entry.type);
  const Icon = def.icon;
  const isTask = entry.type === 'task';
  const overdue = isTask && entry.due_date && !entry.completed && parseISO(entry.due_date) < new Date();

  return (
    <div className={`rounded-xl border p-4 ${TYPE_BG[entry.type] || 'bg-card border-border'} ${entry.completed ? 'opacity-60' : ''}`}>
      <div className="flex items-start gap-3">
        {/* Task checkbox or type icon */}
        {isTask ? (
          <button onClick={onToggleComplete} className="mt-0.5 shrink-0" title={entry.completed ? 'Mark incomplete' : 'Mark complete'}>
            {entry.completed
              ? <CheckCircle2 className="w-5 h-5 text-emerald-600" />
              : <Circle className="w-5 h-5 text-muted-foreground hover:text-foreground" />
            }
          </button>
        ) : (
          <Icon className="w-4 h-4 mt-1 shrink-0 text-muted-foreground" />
        )}

        {/* Body */}
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 flex-wrap">
            <p className={`text-sm font-semibold ${entry.completed ? 'line-through' : ''}`}>{entry.subject}</p>
            <StatusBadge color={def.color}>{def.label}</StatusBadge>
            {overdue && <StatusBadge color="red">Overdue</StatusBadge>}
          </div>
          {entry.content && (
            <p className="text-sm text-muted-foreground mt-1 whitespace-pre-wrap">{entry.content}</p>
          )}
          <div className="flex items-center gap-3 mt-2 text-[11px] text-muted-foreground flex-wrap">
            {entry.created_date && (
              <span>{format(parseISO(entry.created_date), 'd MMM yyyy, HH:mm')}</span>
            )}
            {entry.due_date && (
              <span className={overdue ? 'text-red-600 font-medium' : ''}>
                Due {format(parseISO(entry.due_date), 'd MMM yyyy')}
              </span>
            )}
            {entry.created_by && <span className="truncate">by {entry.created_by}</span>}
          </div>
        </div>

        {/* Actions */}
        {canEdit && (
          <div className="flex items-center gap-0.5 shrink-0">
            <Button variant="ghost" size="icon" className="h-7 w-7" onClick={onEdit} title="Edit">
              <Pencil className="w-3.5 h-3.5" />
            </Button>
            <Button variant="ghost" size="icon" className="h-7 w-7 text-destructive hover:text-destructive" onClick={onDelete} title="Delete">
              <Trash2 className="w-3.5 h-3.5" />
            </Button>
          </div>
        )}
      </div>
    </div>
  );
}

// =============================================================================
// ADD / EDIT DIALOG
// =============================================================================
function CRMDialog({ open, onClose, existing, onSave }) {
  const [data, setData] = useState({
    type: 'note',
    subject: '',
    content: '',
    due_date: '',
    completed: false,
  });
  const [saving, setSaving] = useState(false);

  React.useEffect(() => {
    if (open) {
      if (existing) {
        setData({
          type: existing.type || 'note',
          subject: existing.subject || '',
          content: existing.content || '',
          due_date: existing.due_date || '',
          completed: !!existing.completed,
        });
      } else {
        setData({ type: 'note', subject: '', content: '', due_date: '', completed: false });
      }
    }
  }, [open, existing]);

  const isTask = data.type === 'task';
  const canSave = data.subject.trim().length > 0;

  const handleSubmit = async () => {
    if (!canSave) return;
    setSaving(true);
    try {
      await onSave(data);
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={v => { if (!v) onClose(); }}>
      <DialogContent className="max-w-md max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{existing ? 'Edit Entry' : 'Add Entry'}</DialogTitle>
        </DialogHeader>
        <div className="space-y-4">
          <div className="space-y-1.5">
            <Label>Type *</Label>
            <Select value={data.type} onValueChange={v => setData(d => ({ ...d, type: v }))}>
              <SelectTrigger><SelectValue /></SelectTrigger>
              <SelectContent>
                {Object.entries(TYPE_DEFS).map(([k, def]) => (
                  <SelectItem key={k} value={k}>{def.label}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-1.5">
            <Label>Subject *</Label>
            <Input
              value={data.subject}
              onChange={e => setData(d => ({ ...d, subject: e.target.value }))}
              placeholder={isTask ? 'e.g. Schedule gas cert renewal' : 'Brief subject'}
              required
            />
          </div>

          <div className="space-y-1.5">
            <Label>Details</Label>
            <Textarea
              rows={3}
              value={data.content}
              onChange={e => setData(d => ({ ...d, content: e.target.value }))}
              placeholder="Optional notes"
            />
          </div>

          {isTask && (
            <div className="space-y-1.5">
              <Label>Due Date</Label>
              <Input
                type="date"
                value={data.due_date}
                onChange={e => setData(d => ({ ...d, due_date: e.target.value }))}
              />
            </div>
          )}

          <div className="flex gap-2 justify-end pt-2">
            <Button variant="outline" onClick={onClose} disabled={saving}>Cancel</Button>
            <Button onClick={handleSubmit} disabled={!canSave || saving}>
              {saving ? 'Saving…' : existing ? 'Save' : 'Add'}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import React from 'react';
import { useNavigate } from 'react-router-dom';
import { useRole } from '@/hooks/useRole';
import { usePropertyDocuments } from '@/hooks/useAllData';
import { getPropertyCertStatus, countPropertyDocs } from '@/lib/computations';
import StatusBadge from '@/components/ui/StatusBadge';
import { Button } from '@/components/ui/button';
import { ShieldCheck, AlertTriangle, Upload, FileText, ArrowRight } from 'lucide-react';
import { format, parseISO } from 'date-fns';

const CERTS = [
  { catKey: 'gas',        category: 'gas_cert',        label: 'Gas Safety Certificate', icon: '🔥' },
  { catKey: 'electrical', category: 'electrical_cert', label: 'Electrical Certificate', icon: '⚡' },
  { catKey: 'epc',        category: 'epc_cert',        label: 'EPC Certificate',        icon: '🌿' },
  { catKey: 'license',    category: 'license',         label: 'HMO / Property License', icon: '📋' },
];

export default function PropertyCertificates({ property }) {
  const { isAdmin } = useRole();
  const navigate = useNavigate();
  const { data: allDocuments } = usePropertyDocuments();

  // All cert statuses for this property in one go
  const status = getPropertyCertStatus(property.id, allDocuments);

  // Aggregate alerts across all 4 certs
  const expired = CERTS.filter(c => status[c.catKey].status === 'expired');
  const expiring = CERTS.filter(c => status[c.catKey].status === 'expiring');

  // Navigate to the Documents tab on this property
  const goToDocuments = () => {
    navigate(`/PropertyDetail?id=${property.id}&tab=documents`);
  };

  return (
    <div>
      {/* Header */}
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between mb-5 sm:mb-6">
        <div>
          <h2 className="text-sm font-semibold text-foreground">Certificates & License</h2>
          <p className="text-xs text-muted-foreground mt-0.5">Status derived from the most recent document on file per category</p>
        </div>
        {isAdmin && (
          <Button size="sm" onClick={goToDocuments}>
            <Upload className="w-4 h-4 mr-1.5" />
            Manage Documents
          </Button>
        )}
      </div>

      {/* Alerts */}
      {(expired.length > 0 || expiring.length > 0) && (
        <div className="mb-6 space-y-2">
          {expired.map(c => (
            <div key={c.category} className="flex items-center gap-3 px-4 py-2.5 rounded-lg bg-rose-50 border border-rose-200 text-sm text-rose-700">
              <AlertTriangle className="w-4 h-4 shrink-0" />
              <span className="font-medium">{c.icon} {c.label} has EXPIRED</span>
            </div>
          ))}
          {expiring.map(c => (
            <div key={c.category} className="flex items-center gap-3 px-4 py-2.5 rounded-lg bg-amber-50 border border-amber-200 text-sm text-amber-700">
              <AlertTriangle className="w-4 h-4 shrink-0" />
              <span className="font-medium">{c.icon} {c.label} is expiring soon</span>
            </div>
          ))}
        </div>
      )}

      {/* Cert summary cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-3 sm:gap-4">
        {CERTS.map(c => {
          const s = status[c.catKey];
          const expiry = s.expiry;
          const stat = s.status; // 'expired' | 'expiring' | 'valid' | 'missing'
          const docCount = countPropertyDocs(property.id, c.category, allDocuments);

          const cardBorder =
            stat === 'expired'  ? 'border-rose-200 bg-rose-50/40' :
            stat === 'expiring' ? 'border-amber-200 bg-amber-50/40' :
            'border-border bg-card';

          const iconColor =
            stat === 'expired'  ? 'text-rose-500' :
            stat === 'expiring' ? 'text-amber-500' :
            stat === 'valid'    ? 'text-emerald-500' :
            'text-muted-foreground';

          const badgeColor =
            stat === 'expired'  ? 'red' :
            stat === 'expiring' ? 'yellow' :
            stat === 'valid'    ? 'green' :
            'gray';

          const badgeLabel =
            stat === 'expired'  ? 'Expired' :
            stat === 'expiring' ? 'Expiring Soon' :
            stat === 'valid'    ? 'Valid' :
            'Missing';

          return (
            <div key={c.category} className={`p-4 sm:p-5 rounded-xl border elev-1 ${cardBorder}`}>
              <div className="flex items-start justify-between gap-3">
                <div className="min-w-0 flex-1">
                  <div className="flex items-center gap-2 mb-2">
                    <ShieldCheck className={`w-5 h-5 shrink-0 ${iconColor}`} />
                    <p className="font-medium text-sm truncate">{c.label}</p>
                  </div>

                  <p className="text-xl sm:text-2xl font-semibold tabular-nums leading-tight mb-2">
                    {expiry
                      ? format(parseISO(expiry), 'dd MMM yyyy')
                      : <span className="text-muted-foreground text-base font-normal">Not set</span>
                    }
                  </p>

                  <div className="flex items-center gap-2 flex-wrap">
                    <StatusBadge color={badgeColor}>{badgeLabel}</StatusBadge>
                    {docCount > 0 && (
                      <button
                        onClick={goToDocuments}
                        className="inline-flex items-center gap-1 text-[11px] text-muted-foreground hover:text-foreground transition-colors"
                      >
                        <FileText className="w-3 h-3" />
                        {docCount} on file
                        <ArrowRight className="w-3 h-3" />
                      </button>
                    )}
                  </div>
                </div>

                <span className="text-2xl shrink-0" aria-hidden="true">{c.icon}</span>
              </div>

              {isAdmin && stat === 'missing' && (
                <Button
                  variant="outline"
                  size="sm"
                  className="w-full mt-4"
                  onClick={goToDocuments}
                >
                  <Upload className="w-3.5 h-3.5 mr-1.5" />
                  Upload {c.label}
                </Button>
              )}
            </div>
          );
        })}
      </div>

      {/* Footer hint */}
      <p className="text-xs text-muted-foreground mt-6">
        Tip: Multiple certificates per category are kept as history. The most recent (latest expiry date) sets the status above.
      </p>
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { base44 } from '@/api/base44Client';
import { useQueryClient } from '@tanstack/react-query';
import { useRole } from '@/hooks/useRole';
import { logAction } from '@/lib/audit';
