import FileUpload from '@/components/forms/FileUpload';
import {
  Plus, FileText, Trash2, ExternalLink, Download, Archive, ArchiveRestore,
  ChevronDown, ChevronRight, Upload
} from 'lucide-react';
import { format, parseISO } from 'date-fns';

// =============================================================================
// CATEGORY DEFINITIONS
// =============================================================================
const CATEGORIES = [
  { value: 'gas_cert',          label: 'Gas Safety Certificate',  icon: '🔥', hasExpiry: true  },
  { value: 'electrical_cert',   label: 'Electrical Certificate',  icon: '⚡', hasExpiry: true  },
  { value: 'epc_cert',          label: 'EPC Certificate',         icon: '🌿', hasExpiry: true  },
  { value: 'license',           label: 'HMO / Property License',  icon: '📋', hasExpiry: true  },
  { value: 'lease_agreement',   label: 'Lease Agreement',         icon: '📄', hasExpiry: false },
  { value: 'tenancy_agreement', label: 'Tenancy Agreement',       icon: '📝', hasExpiry: false },
  { value: 'sale_deed',         label: 'Sale Deed',               icon: '🏛️', hasExpiry: false },
  { value: 'insurance',         label: 'Insurance',               icon: '🛡️', hasExpiry: true  },
  { value: 'inventory',         label: 'Inventory Report',        icon: '📦', hasExpiry: false },
  { value: 'deposit_protection',label: 'Deposit Protection',      icon: '🔐', hasExpiry: false },
  { value: 'other',             label: 'Other',                   icon: '📎', hasExpiry: false },
];

const getCategoryDef = (value) => CATEGORIES.find(c => c.value === value) || CATEGORIES[CATEGORIES.length - 1];

// =============================================================================
// MAIN COMPONENT
// =============================================================================
export default function PropertyDocuments({ property, landlord }) {
  const { user, isAdmin } = useRole();
  const queryClient = useQueryClient();
  const { data: allDocuments } = usePropertyDocuments();

  // Filter to this property
  const documents = useMemo(
    () => allDocuments.filter(d => d.property_id === property.id),
    [allDocuments, property.id]
  );

  // UI state
  const [showUpload, setShowUpload] = useState(false);
  const [editing, setEditing] = useState(null);          // existing doc being edited
  const [confirmDelete, setConfirmDelete] = useState(null);
  const [openGroups, setOpenGroups] = useState({});      // collapsed sections
  const [showArchived, setShowArchived] = useState(false);

  // Group docs by category
  const grouped = useMemo(() => {
    const visible = showArchived ? documents : documents.filter(d => !d.is_archived);
    const out = {};
    for (const cat of CATEGORIES) out[cat.value] = [];
    for (const doc of visible) {
      const key = doc.category || 'other';
      if (!out[key]) out[key] = [];
      out[key].push(doc);
    }
    // Sort each group by expiry_date (newest first), falling back to issue_date
    for (const key of Object.keys(out)) {
      out[key].sort((a, b) => {
        const aKey = a.expiry_date || a.issue_date || '';
        const bKey = b.expiry_date || b.issue_date || '';
        return bKey.localeCompare(aKey);
      });
    }
    return out;
  }, [documents, showArchived]);

  // Auto-open groups that have documents (on first load)
  React.useEffect(() => {
    setOpenGroups(prev => {
      if (Object.keys(prev).length > 0) return prev;
      const initial = {};
      for (const cat of CATEGORIES) {
        initial[cat.value] = (grouped[cat.value] || []).length > 0;
      }
      return initial;
    });
  }, [grouped]);

  const toggleGroup = (cat) => setOpenGroups(prev => ({ ...prev, [cat]: !prev[cat] }));

  // ---------------------------------------------------------------------------
  // HANDLERS
  // ---------------------------------------------------------------------------
  const openNewUpload = () => {
    setEditing(null);
    setShowUpload(true);
  };

  const openEditDoc = (doc) => {
    setEditing(doc);
    setShowUpload(true);
  };

  const handleSave = async (formData) => {
    if (editing) {
      await base44.entities.PropertyDocument.update(editing.id, formData);
      await logAction({
        user,
        action: 'update',
        entityType: 'PropertyDocument',
        entityId: editing.id,
        summary: `Updated ${getCategoryDef(formData.category).label} for ${property.address}`,
        oldValue: editing,
        newValue: formData,
      });
    } else {
      const created = await base44.entities.PropertyDocument.create({
        ...formData,
        property_id: property.id,
        landlord_id: property.landlord_id,
        uploaded_by: user?.email || '',
      });
      await logAction({
        user,
        action: 'create',
        entityType: 'PropertyDocument',
        entityId: created.id,
        summary: `Uploaded ${getCategoryDef(formData.category).label} for ${property.address}`,
        newValue: formData,
      });
    }
    queryClient.invalidateQueries({ queryKey: ['propertyDocuments'] });
    setShowUpload(false);
    setEditing(null);
  };

  const handleDelete = async (doc) => {
    await base44.entities.PropertyDocument.delete(doc.id);
    await logAction({
      user,
      action: 'delete',
      entityType: 'PropertyDocument',
      entityId: doc.id,
      summary: `Deleted ${getCategoryDef(doc.category).label} (${doc.title || doc.file_name || 'untitled'}) from ${property.address}`,
      oldValue: doc,
    });
    queryClient.invalidateQueries({ queryKey: ['propertyDocuments'] });
    setConfirmDelete(null);
  };

  const handleToggleArchive = async (doc) => {
    await base44.entities.PropertyDocument.update(doc.id, { is_archived: !doc.is_archived });
    await logAction({
      user,
      action: 'update',
      entityType: 'PropertyDocument',
      entityId: doc.id,
      summary: `${doc.is_archived ? 'Restored' : 'Archived'} ${getCategoryDef(doc.category).label} (${doc.title || doc.file_name || 'untitled'})`,
    });
    queryClient.invalidateQueries({ queryKey: ['propertyDocuments'] });
  };

  // ---------------------------------------------------------------------------
  // RENDER
  // ---------------------------------------------------------------------------
  const totalCount = documents.filter(d => !d.is_archived).length;
  const archivedCount = documents.filter(d => d.is_archived).length;

  return (
    <div>
      {/* Header */}
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between mb-5 sm:mb-6">
        <div className="min-w-0">
          <h2 className="text-sm font-semibold text-foreground">Documents</h2>
          <p className="text-xs text-muted-foreground mt-0.5">
            {totalCount} active document{totalCount === 1 ? '' : 's'}
            {archivedCount > 0 && ` · ${archivedCount} archived`}
          </p>
        </div>
        <div className="flex items-center gap-2">
          {archivedCount > 0 && (
            <Button
              variant="outline"
              size="sm"
              onClick={() => setShowArchived(s => !s)}
            >
              {showArchived ? <ArchiveRestore className="w-4 h-4 mr-1.5" /> : <Archive className="w-4 h-4 mr-1.5" />}
              {showArchived ? 'Hide' : 'Show'} Archived
            </Button>
          )}
          <Button size="sm" onClick={openNewUpload}>
            <Upload className="w-4 h-4 mr-1.5" />Upload Document
          </Button>
        </div>
      </div>

      {/* Empty state */}
      {totalCount === 0 && archivedCount === 0 && (
        <div className="text-center py-16 bg-muted/30 rounded-xl border border-dashed border-border">
          <FileText className="w-10 h-10 mx-auto mb-3 text-muted-foreground opacity-40" />
          <p className="text-sm font-medium text-foreground">No documents yet</p>
          <p className="text-xs text-muted-foreground mt-1">Upload certificates, agreements, or any property paperwork</p>
          <Button size="sm" className="mt-4" onClick={openNewUpload}>
            <Upload className="w-4 h-4 mr-1.5" />Upload First Document
          </Button>
        </div>
      )}

      {/* Grouped list */}
      {totalCount > 0 && (
        <div className="space-y-2">
          {CATEGORIES.map(cat => {
            const docs = grouped[cat.value] || [];
            if (docs.length === 0) return null;
            const isOpen = openGroups[cat.value] !== false;
            return (
              <div key={cat.value} className="bg-card border border-border rounded-xl overflow-hidden">
                <button
                  onClick={() => toggleGroup(cat.value)}
                  className="w-full flex items-center gap-3 px-4 py-3 hover:bg-muted/50 transition-colors"
                >
                  {isOpen ? <ChevronDown className="w-4 h-4 text-muted-foreground" /> : <ChevronRight className="w-4 h-4 text-muted-foreground" />}
                  <span className="text-base">{cat.icon}</span>
                  <span className="font-medium text-sm flex-1 text-left">{cat.label}</span>
                  <span className="text-xs text-muted-foreground">{docs.length} file{docs.length === 1 ? '' : 's'}</span>
                </button>
                {isOpen && (
                  <div className="border-t border-border">
                    {docs.map((doc, idx) => (
                      <DocumentRow
                        key={doc.id}
                        doc={doc}
                        isCurrent={idx === 0 && cat.hasExpiry && !doc.is_archived}
                        canEdit={isAdmin}
                        onEdit={() => openEditDoc(doc)}
                        onDelete={() => setConfirmDelete(doc)}
                        onToggleArchive={() => handleToggleArchive(doc)}
                      />
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* Upload / Edit dialog */}
      <DocumentDialog
        open={showUpload}
        onClose={() => { setShowUpload(false); setEditing(null); }}
        existing={editing}
        onSave={handleSave}
      />

      {/* Delete confirmation */}
      <ConfirmDialog
        open={!!confirmDelete}
        title="Delete document"
        description={`Permanently delete "${confirmDelete?.title || confirmDelete?.file_name || 'this document'}"? This cannot be undone.`}
        onConfirm={() => handleDelete(confirmDelete)}
        onCancel={() => setConfirmDelete(null)}
      />
    </div>
  );
}

// =============================================================================
// DOCUMENT ROW
// =============================================================================
function DocumentRow({ doc, isCurrent, canEdit, onEdit, onDelete, onToggleArchive }) {
  const expiry = doc.expiry_date;
  let expiryColor = 'gray';
  let expiryLabel = '';
  if (expiry) {
    if (isExpired(expiry)) { expiryColor = 'red';    expiryLabel = 'Expired'; }
    else if (isExpiringSoon(expiry)) { expiryColor = 'yellow'; expiryLabel = 'Expiring Soon'; }
    else { expiryColor = 'green'; expiryLabel = 'Valid'; }
  }

  const fileLabel = doc.title || doc.file_name || 'Untitled document';

  return (
    <div className={`flex flex-col sm:flex-row sm:items-center gap-3 px-4 py-3 border-b border-border last:border-b-0 ${doc.is_archived ? 'opacity-60' : ''}`}>
      {/* Title + badges */}
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-2 flex-wrap">
          <p className="text-sm font-medium text-foreground truncate">{fileLabel}</p>
          {isCurrent && <StatusBadge color="blue">Current</StatusBadge>}
          {doc.is_archived && <StatusBadge color="gray">Archived</StatusBadge>}
          {expiry && !doc.is_archived && <StatusBadge color={expiryColor}>{expiryLabel}</StatusBadge>}
        </div>
        <div className="flex items-center gap-3 mt-1 text-xs text-muted-foreground flex-wrap">
          {doc.issue_date && <span>Issued {format(parseISO(doc.issue_date), 'd MMM yyyy')}</span>}
          {doc.expiry_date && <span>Expires {format(parseISO(doc.expiry_date), 'd MMM yyyy')}</span>}
          {doc.uploaded_by && <span className="truncate">by {doc.uploaded_by}</span>}
        </div>
        {doc.notes && <p className="text-xs text-muted-foreground mt-1 line-clamp-2">{doc.notes}</p>}
      </div>

      {/* Actions */}
      <div className="flex items-center gap-1 shrink-0">
        {doc.file_url && (
          <a href={doc.file_url} target="_blank" rel="noopener noreferrer">
            <Button variant="ghost" size="icon" className="h-8 w-8" title="View / download">
              <ExternalLink className="w-4 h-4" />
            </Button>
          </a>
        )}
        {canEdit && (
          <>
            <Button variant="ghost" size="icon" className="h-8 w-8" onClick={onEdit} title="Edit details">
              <FileText className="w-4 h-4" />
            </Button>
            <Button variant="ghost" size="icon" className="h-8 w-8" onClick={onToggleArchive} title={doc.is_archived ? 'Restore' : 'Archive'}>
              {doc.is_archived ? <ArchiveRestore className="w-4 h-4" /> : <Archive className="w-4 h-4" />}
            </Button>
            <Button variant="ghost" size="icon" className="h-8 w-8 text-destructive hover:text-destructive" onClick={onDelete} title="Delete">
              <Trash2 className="w-4 h-4" />
            </Button>
          </>
        )}
      </div>
    </div>
  );
}

// =============================================================================
// UPLOAD / EDIT DIALOG
// =============================================================================
function DocumentDialog({ open, onClose, existing, onSave }) {
  const [data, setData] = useState({
    category: 'gas_cert',
    title: '',
    file_url: '',
    file_name: '',
    issue_date: '',
    expiry_date: '',
    notes: '',
  });
  const [saving, setSaving] = useState(false);

  // Reset form when dialog opens
  React.useEffect(() => {
    if (open) {
      if (existing) {
        setData({
          category: existing.category || 'gas_cert',
          title: existing.title || '',
          file_url: existing.file_url || '',
          file_name: existing.file_name || '',
          issue_date: existing.issue_date || '',
          expiry_date: existing.expiry_date || '',
          notes: existing.notes || '',
        });
      } else {
        setData({
          category: 'gas_cert',
          title: '',
          file_url: '',
          file_name: '',
          issue_date: '',
          expiry_date: '',
          notes: '',
        });
      }
    }
  }, [open, existing]);

  const catDef = getCategoryDef(data.category);

  const handleFileChange = (url, fileName) => {
    setData(d => ({
      ...d,
      file_url: url,
      // Auto-fill file_name and title if blank
      file_name: fileName || d.file_name,
      title: d.title || (fileName ? fileName.replace(/\.[^.]+$/, '') : d.title),
    }));
  };

  const canSave = data.category && data.file_url;

  const handleSubmit = async () => {
    if (!canSave) return;
    setSaving(true);
    try {
      await onSave(data);
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={v => { if (!v) onClose(); }}>
      <DialogContent className="max-w-md max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{existing ? 'Edit Document' : 'Upload Document'}</DialogTitle>
        </DialogHeader>
        <div className="space-y-4">
          <div className="space-y-1.5">
            <Label>Category *</Label>
            <Select value={data.category} onValueChange={v => setData(d => ({ ...d, category: v }))}>
              <SelectTrigger><SelectValue /></SelectTrigger>
              <SelectContent>
                {CATEGORIES.map(c => (
                  <SelectItem key={c.value} value={c.value}>
                    {c.icon} {c.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-1.5">
            <Label>Title</Label>
            <Input
              value={data.title}
              onChange={e => setData(d => ({ ...d, title: e.target.value }))}
              placeholder={`e.g. ${catDef.label} 2025`}
            />
            <p className="text-[11px] text-muted-foreground">Optional. Auto-fills from filename if left blank.</p>
          </div>

          <div className="space-y-1.5">
            <Label>File *</Label>
            <FileUpload
              label="Document"
              value={data.file_url}
              onChange={(url) => {
                // FileUpload returns just the URL — extract filename from it
                const fname = url ? url.split('/').pop().split('?')[0] : '';
                handleFileChange(url, fname);
              }}
              accept=".pdf,.jpg,.jpeg,.png,.doc,.docx"
            />
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label>Issue Date</Label>
              <Input
                type="date"
                value={data.issue_date}
                onChange={e => setData(d => ({ ...d, issue_date: e.target.value }))}
              />
            </div>
            <div className="space-y-1.5">
              <Label>Expiry Date {catDef.hasExpiry && <span className="text-muted-foreground">(recommended)</span>}</Label>
              <Input
                type="date"
                value={data.expiry_date}
                onChange={e => setData(d => ({ ...d, expiry_date: e.target.value }))}
              />
            </div>
          </div>

          <div className="space-y-1.5">
            <Label>Notes</Label>
            <Textarea
              rows={2}
              value={data.notes}
              onChange={e => setData(d => ({ ...d, notes: e.target.value }))}
              placeholder="Optional"
            />
          </div>

          <div className="flex gap-2 justify-end pt-2">
            <Button variant="outline" onClick={onClose} disabled={saving}>Cancel</Button>
            <Button onClick={handleSubmit} disabled={!canSave || saving}>
              {saving ? 'Saving…' : existing ? 'Save Changes' : 'Upload'}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState } from 'react';
import { base44 } from '@/api/base44Client';
import { useExpenses } from '@/hooks/useExpenses';
import { useTenants } from '@/hooks/useAllData';
import { useQueryClient } from '@tanstack/react-query';
import { useRole } from '@/hooks/useRole';
import { logAction } from '@/lib/audit';
import StatusBadge from '@/components/ui/StatusBadge';
import ConfirmDialog from '@/components/ui/ConfirmDialog';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Plus, Trash2, Pencil } from 'lucide-react';
import { formatCurrency } from '@/lib/computations';
import { format, parseISO } from 'date-fns';

const CATEGORIES = ['maintenance','repairs','insurance','utilities','management_fee','legal','cleaning','other'];
const catColors = { maintenance:'red',repairs:'red',insurance:'blue',utilities:'yellow',management_fee:'blue',legal:'yellow',cleaning:'green',other:'gray' };

function ExpenseForm({ expense, property, tenants, onSubmit, onCancel }) {
  const [data, setData] = useState(expense || {
    property_id: property.id, landlord_id: property.landlord_id, tenant_id: '',
    date: format(new Date(),'yyyy-MM-dd'), category:'maintenance', description:'', amount:'', paid_by:'agency', reference:'', notes:''
  });
  return (
    <form onSubmit={e => { e.preventDefault(); onSubmit({...data,amount:Number(data.amount)}); }} className="space-y-4">
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div className="space-y-2"><Label>Category *</Label>
          <Select value={data.category} onValueChange={v => setData({...data,category:v})}>
            <SelectTrigger><SelectValue /></SelectTrigger>
            <SelectContent>{CATEGORIES.map(c=><SelectItem key={c} value={c}>{c.replace(/_/g,' ')}</SelectItem>)}</SelectContent>
          </Select>
        </div>
        <div className="space-y-2"><Label>Date *</Label><Input type="date" value={data.date} onChange={e=>setData({...data,date:e.target.value})} required /></div>
        <div className="space-y-2"><Label>Amount (£) *</Label><Input type="number" min="0" step="0.01" value={data.amount} onChange={e=>setData({...data,amount:e.target.value})} required /></div>
        <div className="space-y-2"><Label>Paid By</Label>
          <Select value={data.paid_by} onValueChange={v=>setData({...data,paid_by:v})}>
            <SelectTrigger><SelectValue /></SelectTrigger>
            <SelectContent><SelectItem value="agency">Agency</SelectItem><SelectItem value="landlord">Landlord</SelectItem></SelectContent>
          </Select>
        </div>
        <div className="space-y-2 sm:col-span-2"><Label>Description *</Label><Input value={data.description} onChange={e=>setData({...data,description:e.target.value})} required /></div>
        <div className="space-y-2"><Label>Tenant (optional)</Label>
          <Select value={data.tenant_id||''} onValueChange={v=>setData({...data,tenant_id:v})}>
            <SelectTrigger><SelectValue placeholder="None" /></SelectTrigger>
            <SelectContent><SelectItem value={null}>None</SelectItem>{tenants.map(t=><SelectItem key={t.id} value={t.id}>{t.name}</SelectItem>)}</SelectContent>
          </Select>
        </div>
        <div className="space-y-2"><Label>Reference</Label><Input value={data.reference||''} onChange={e=>setData({...data,reference:e.target.value})} /></div>
      </div>
      <div className="space-y-2"><Label>Notes</Label><Textarea value={data.notes||''} onChange={e=>setData({...data,notes:e.target.value})} rows={2} /></div>
      <div className="flex gap-3 justify-end pt-2">
        <Button type="button" variant="outline" onClick={onCancel}>Cancel</Button>
        <Button type="submit">{expense ? 'Update' : 'Add Expense'}</Button>
      </div>
    </form>
  );
}

export default function PropertyExpensesTab({ property }) {
  const { user, isAdmin } = useRole();
  const { data: expenses } = useExpenses();
  const { data: tenants } = useTenants();
  const queryClient = useQueryClient();
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(null);

  const pExpenses = expenses.filter(e => e.property_id === property.id);
  const pTenants = tenants.filter(t => t.property_id === property.id);
  const total = pExpenses.reduce((s,e) => s+(e.amount||0), 0);

  const handleSubmit = async (data) => {
    const saveData = { ...data, approved: data.paid_by === 'landlord' ? false : true };
    if (editing) {
      await base44.entities.Expense.update(editing.id, saveData);
      await logAction({ user, action: 'update', entityType: 'Expense', entityId: editing.id, summary: `Updated expense: ${data.description}`, oldValue: editing, newValue: saveData });
    } else {
      const created = await base44.entities.Expense.create(saveData);
      await logAction({ user, action: 'create', entityType: 'Expense', entityId: created.id, summary: `Added expense: ${data.description} £${data.amount}`, newValue: saveData });
    }
    queryClient.invalidateQueries({ queryKey: ['expenses'] });
    setShowForm(false); setEditing(null);
  };

  const handleDelete = async (expense) => {
    await base44.entities.Expense.delete(expense.id);
    await logAction({ user, action: 'delete', entityType: 'Expense', entityId: expense.id, summary: `Deleted expense: ${expense.description}`, oldValue: expense });
    queryClient.invalidateQueries({ queryKey: ['expenses'] });
    setConfirmDelete(null);
  };

  const handleApprove = async (expense) => {
    await base44.entities.Expense.update(expense.id, { ...expense, approved: true });
    queryClient.invalidateQueries({ queryKey: ['expenses'] });
  };

  return (
    <div>
      <div className="flex items-center justify-between mb-4">
        <p className="text-sm text-muted-foreground">Total expenses: <span className="font-semibold text-foreground">{formatCurrency(total)}</span></p>
        <Button onClick={() => { setEditing(null); setShowForm(true); }}><Plus className="w-4 h-4 mr-2" />Add Expense</Button>
      </div>

      <div className="bg-card rounded-xl border border-border overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-muted/50">
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Date</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Category</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Description</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Amount</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Paid By</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Status</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Actions</th>
              </tr>
            </thead>
            <tbody>
              {pExpenses.map(e => (
                <tr key={e.id} className="border-t border-border hover:bg-muted/30 transition-colors">
                  <td className="px-5 py-3 text-muted-foreground">{e.date ? format(parseISO(e.date),'dd MMM yyyy') : '-'}</td>
                  <td className="px-5 py-3"><StatusBadge color={catColors[e.category]||'gray'}>{e.category?.replace(/_/g,' ')}</StatusBadge></td>
                  <td className="px-5 py-3">{e.description}</td>
                  <td className="px-5 py-3 font-medium text-red-600">{formatCurrency(e.amount)}</td>
                  <td className="px-5 py-3"><StatusBadge color={e.paid_by==='agency'?'blue':'yellow'}>{e.paid_by}</StatusBadge></td>
                  <td className="px-5 py-3">
                    {e.paid_by==='landlord' ? (e.approved ? <StatusBadge color="green">Approved</StatusBadge> : <StatusBadge color="yellow">Pending</StatusBadge>) : <StatusBadge color="blue">N/A</StatusBadge>}
                  </td>
                  <td className="px-5 py-3">
                    <div className="flex items-center gap-1">
                      {isAdmin && e.paid_by==='landlord' && !e.approved && (
                        <Button size="sm" className="bg-emerald-600 hover:bg-emerald-700 text-white text-xs px-2 h-7" onClick={() => handleApprove(e)}>✓ Approve</Button>
                      )}
                      <Button variant="ghost" size="sm" onClick={() => { setEditing(e); setShowForm(true); }}><Pencil className="w-4 h-4" /></Button>
                      {isAdmin && <Button variant="ghost" size="sm" className="text-destructive hover:text-destructive" onClick={() => setConfirmDelete(e)}><Trash2 className="w-4 h-4" /></Button>}
                    </div>
                  </td>
                </tr>
              ))}
              {pExpenses.length === 0 && <tr><td colSpan="7" className="px-5 py-8 text-center text-muted-foreground">No expenses for this property</td></tr>}
            </tbody>
          </table>
        </div>
      </div>

      <Dialog open={showForm} onOpenChange={v => { setShowForm(v); if(!v) setEditing(null); }}>
        <DialogContent className="max-w-lg">
          <DialogHeader><DialogTitle>{editing ? 'Edit Expense' : 'Add Expense'}</DialogTitle></DialogHeader>
          <ExpenseForm expense={editing} property={property} tenants={pTenants} onSubmit={handleSubmit} onCancel={() => { setShowForm(false); setEditing(null); }} />
        </DialogContent>
      </Dialog>

      <ConfirmDialog
        open={!!confirmDelete}
        title="Delete Expense"
        description={`Delete "${confirmDelete?.description}"?`}
        onConfirm={() => handleDelete(confirmDelete)}
        onCancel={() => setConfirmDelete(null)}
      />
    </div>
  );
}

import React, { useState } from 'react';
import { base44 } from '@/api/base44Client';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import StatusBadge from '@/components/ui/StatusBadge';
import { Plus, ClipboardList, Pencil, Trash2, Eye, Download } from 'lucide-react';
import { format, parseISO } from 'date-fns';
import InspectionForm from '@/components/property/InspectionForm';
import { jsPDF } from 'jspdf';

export default function PropertyInspection({ property, pTenants = [] }) {
  const queryClient = useQueryClient();
  const [showForm, setShowForm] = useState(false);
  const [editReport, setEditReport] = useState(null);
  const [viewReport, setViewReport] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(null);

  const { data: reports = [] } = useQuery({
    queryKey: ['inspection_reports', property.id],
    queryFn: () => base44.entities.InspectionReport.filter({ property_id: property.id }, '-inspection_date'),
    initialData: [],
  });

  const handleSave = async (data) => {
    if (editReport) {
      await base44.entities.InspectionReport.update(editReport.id, data);
    } else {
      await base44.entities.InspectionReport.create({ ...data, property_id: property.id });
    }
    queryClient.invalidateQueries({ queryKey: ['inspection_reports', property.id] });
    setShowForm(false);
    setEditReport(null);
  };

  const handleDelete = async () => {
    await base44.entities.InspectionReport.delete(confirmDelete.id);
    queryClient.invalidateQueries({ queryKey: ['inspection_reports', property.id] });
    setConfirmDelete(null);
  };

  const typeLabels = { check_in: 'Check-in', check_out: 'Check-out', routine: 'Routine' };
  const typeColors = { check_in: 'green', check_out: 'red', routine: 'blue' };
  const statusColors = { draft: 'yellow', completed: 'green' };

  const downloadPDF = (report) => {
    const sections = (() => { try { return JSON.parse(report.sections || '[]'); } catch { return []; } })();
    const doc = new jsPDF();
    const pageW = doc.internal.pageSize.getWidth();
    const pageH = doc.internal.pageSize.getHeight();
    const margin = 14;
    const colWidths = [80, 35, pageW - margin * 2 - 80 - 35];
    const rowH = 7;

    const checkNewPage = (y, needed = rowH) => {
      if (y + needed > pageH - 14) { doc.addPage(); return 28; }
      return y;
    };

    const drawRow = (y, cols, colWidths, isHeader = false, stripe = false) => {
      if (isHeader) { doc.setFillColor(26, 45, 69); doc.rect(margin, y - 5, pageW - margin * 2, rowH, 'F'); }
      else if (stripe) { doc.setFillColor(245, 247, 250); doc.rect(margin, y - 5, pageW - margin * 2, rowH, 'F'); }
      doc.setTextColor(isHeader ? 255 : 0, isHeader ? 255 : 0, isHeader ? 255 : 0);
      doc.setFont('helvetica', isHeader ? 'bold' : 'normal');
      doc.setFontSize(8);
      let x = margin;
      cols.forEach((text, i) => {
        const maxW = colWidths[i] - 2;
        const lines = doc.splitTextToSize(String(text || '—'), maxW);
        doc.text(lines[0], x + 1, y);
        x += colWidths[i];
      });
      return y + rowH;
    };

    // Header banner
    doc.setFillColor(26, 45, 69);
    doc.rect(0, 0, pageW, 22, 'F');
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(14);
    doc.setFont('helvetica', 'bold');
    doc.text('Property Inspection Report', margin, 10);
    doc.setFontSize(8);
    doc.setFont('helvetica', 'normal');
    doc.text('CONDITION & INVENTORY ASSESSMENT', margin, 17);

    // Meta block
    doc.setTextColor(0, 0, 0);
    let y = 30;
    const metaRows = [
      ['Address', property.address || '—'],
      ['Date', report.inspection_date ? format(parseISO(report.inspection_date), 'dd MMM yyyy') : '—'],
      ['Tenant', report.tenant_name || '—'],
      ['Type', typeLabels[report.inspection_type] || '—'],
      ['Inspector', report.inspector_name || '—'],
    ];
    const metaColW = [45, pageW - margin * 2 - 45];
    metaRows.forEach(([label, val], i) => {
      const stripe = i % 2 === 0;
      if (stripe) { doc.setFillColor(245, 247, 250); doc.rect(margin, y - 5, pageW - margin * 2, rowH, 'F'); }
      doc.setFont('helvetica', 'bold'); doc.setFontSize(8); doc.setTextColor(0, 0, 0);
      doc.text(label, margin + 1, y);
      doc.setFont('helvetica', 'normal');
      doc.text(String(val), margin + metaColW[0] + 1, y);
      y += rowH;
    });
    y += 4;

    // Sections
    sections.forEach(section => {
      if (!section.items?.length) return;
      y = checkNewPage(y, rowH * 2);

      // Section title row
      const sectionTitle = section.roomType ? `${section.title} (${section.roomType})` : section.title;
      doc.setFillColor(26, 45, 69);
      doc.rect(margin, y - 5, pageW - margin * 2, rowH, 'F');
      doc.setTextColor(255, 255, 255);
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(9);
      doc.text(sectionTitle, margin + 1, y);
      y += rowH;

      // Column headers
      y = checkNewPage(y);
      y = drawRow(y, ['Item', 'State', 'Comments'], colWidths, true);

      // Items
      section.items.forEach((item, idx) => {
        y = checkNewPage(y);
        y = drawRow(y, [item.name, item.value, item.comment], colWidths, false, idx % 2 === 0);
      });
      y += 4;
    });

    // Summaries
    if (report.summary_tenant || report.summary_agent) {
      y = checkNewPage(y, rowH * 3);
      doc.setFillColor(26, 45, 69);
      doc.rect(margin, y - 5, pageW - margin * 2, rowH, 'F');
      doc.setTextColor(255, 255, 255);
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(8);
      doc.text('Maintenance Summary', margin + 1, y);
      y += rowH;

      const halfW = (pageW - margin * 2) / 2;
      const summaryRows = [
        ['Maintenance by Tenant', report.summary_tenant || 'None'],
        ['Maintenance by Agent/Landlord', report.summary_agent || 'None'],
      ];
      summaryRows.forEach(([label, val], i) => {
        y = checkNewPage(y, rowH * 2);
        if (i % 2 === 0) { doc.setFillColor(245, 247, 250); doc.rect(margin, y - 5, pageW - margin * 2, rowH * 2, 'F'); }
        doc.setTextColor(0, 0, 0);
        doc.setFont('helvetica', 'bold'); doc.setFontSize(8);
        doc.text(label, margin + 1, y);
        doc.setFont('helvetica', 'normal');
        const lines = doc.splitTextToSize(val, pageW - margin * 2 - 2);
        doc.text(lines[0], margin + 1, y + rowH - 2);
        y += rowH * 2;
      });
    }

    const filename = `Inspection_${property.address?.replace(/[^a-z0-9]/gi, '_')}_${report.inspection_date || 'report'}.pdf`;
    doc.save(filename);
  };

  return (
    <div>
      <div className="flex items-center justify-between mb-4">
        <div>
          <h3 className="font-semibold text-foreground">Inspection Reports</h3>
          <p className="text-sm text-muted-foreground">{reports.length} report{reports.length !== 1 ? 's' : ''}</p>
        </div>
        <Button onClick={() => { setEditReport(null); setShowForm(true); }}>
          <Plus className="w-4 h-4 mr-2" />New Inspection
        </Button>
      </div>

      {reports.length === 0 ? (
        <div className="bg-card border border-border rounded-xl flex flex-col items-center justify-center py-16 gap-3">
          <ClipboardList className="w-10 h-10 text-muted-foreground opacity-30" />
          <p className="text-muted-foreground text-sm">No inspection reports yet</p>
          <Button variant="outline" size="sm" onClick={() => setShowForm(true)}>
            <Plus className="w-4 h-4 mr-1" />Create First Report
          </Button>
        </div>
      ) : (
        <div className="bg-card rounded-xl border border-border overflow-hidden">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-muted/50">
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Date</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Type</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Tenant</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Inspector</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Status</th>
                <th className="px-5 py-3"></th>
              </tr>
            </thead>
            <tbody>
              {reports.map(r => (
                <tr key={r.id} className="border-t border-border hover:bg-muted/30 transition-colors">
                  <td className="px-5 py-3 font-medium">{r.inspection_date ? format(parseISO(r.inspection_date), 'dd MMM yyyy') : '—'}</td>
                  <td className="px-5 py-3"><StatusBadge color={typeColors[r.inspection_type]}>{typeLabels[r.inspection_type]}</StatusBadge></td>
                  <td className="px-5 py-3 text-muted-foreground">{r.tenant_name || '—'}</td>
                  <td className="px-5 py-3 text-muted-foreground">{r.inspector_name || '—'}</td>
                  <td className="px-5 py-3"><StatusBadge color={statusColors[r.status]}>{r.status}</StatusBadge></td>
                  <td className="px-5 py-3">
                    <div className="flex gap-1">
                      <Button variant="ghost" size="sm" onClick={() => setViewReport(r)} title="View"><Eye className="w-4 h-4" /></Button>
                      <Button variant="ghost" size="sm" onClick={() => downloadPDF(r)} title="Download PDF"><Download className="w-4 h-4" /></Button>
                      <Button variant="ghost" size="sm" onClick={() => { setEditReport(r); setShowForm(true); }} title="Edit"><Pencil className="w-4 h-4" /></Button>
                      <Button variant="ghost" size="sm" className="text-destructive/70 hover:text-destructive" onClick={() => setConfirmDelete(r)} title="Delete"><Trash2 className="w-4 h-4" /></Button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* Create / Edit form dialog */}
      <Dialog open={showForm} onOpenChange={v => { if (!v) { setShowForm(false); setEditReport(null); } }}>
        <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{editReport ? 'Edit Inspection Report' : 'New Inspection Report'}</DialogTitle>
          </DialogHeader>
          <InspectionForm
            property={property}
            tenants={pTenants}
            initialData={editReport}
            onSubmit={handleSave}
            onCancel={() => { setShowForm(false); setEditReport(null); }}
          />
        </DialogContent>
      </Dialog>

      {/* View report dialog */}
      <Dialog open={!!viewReport} onOpenChange={v => { if (!v) setViewReport(null); }}>
        <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <div className="flex items-center justify-between pr-6">
              <DialogTitle>Inspection Report — {viewReport?.inspection_date ? format(parseISO(viewReport.inspection_date), 'dd MMM yyyy') : ''}</DialogTitle>
              {viewReport && (
                <Button variant="outline" size="sm" onClick={() => downloadPDF(viewReport)}>
                  <Download className="w-4 h-4 mr-1" />Download PDF
                </Button>
              )}
            </div>
          </DialogHeader>
          {viewReport && <InspectionReportView report={viewReport} />}
        </DialogContent>
      </Dialog>

      {/* Delete confirm */}
      {confirmDelete && (
        <Dialog open={!!confirmDelete} onOpenChange={() => setConfirmDelete(null)}>
          <DialogContent className="max-w-sm">
            <DialogHeader><DialogTitle>Delete Inspection Report?</DialogTitle></DialogHeader>
            <p className="text-sm text-muted-foreground">This will permanently delete the inspection report from {confirmDelete.inspection_date ? format(parseISO(confirmDelete.inspection_date), 'dd MMM yyyy') : ''}.</p>
            <div className="flex gap-2 justify-end mt-2">
              <Button variant="outline" onClick={() => setConfirmDelete(null)}>Cancel</Button>
              <Button variant="destructive" onClick={handleDelete}>Delete</Button>
            </div>
          </DialogContent>
        </Dialog>
      )}
    </div>
  );
}

function InspectionReportView({ report }) {
  const sections = (() => { try { return JSON.parse(report.sections || '[]'); } catch { return []; } })();
  const typeLabels = { check_in: 'Check-in', check_out: 'Check-out', routine: 'Routine' };

  return (
    <div className="space-y-6 text-sm">
      <div className="grid grid-cols-2 gap-4 bg-muted/40 rounded-lg p-4">
        <div><span className="text-muted-foreground">Type:</span> <span className="font-medium">{typeLabels[report.inspection_type]}</span></div>
        <div><span className="text-muted-foreground">Date:</span> <span className="font-medium">{report.inspection_date ? format(parseISO(report.inspection_date), 'dd MMM yyyy') : '—'}</span></div>
        <div><span className="text-muted-foreground">Tenant:</span> <span className="font-medium">{report.tenant_name || '—'}</span></div>
        <div><span className="text-muted-foreground">Inspector:</span> <span className="font-medium">{report.inspector_name || '—'}</span></div>
      </div>

      {sections.map((section, si) => (
        <div key={si} className="border border-border rounded-lg overflow-hidden">
          <div className="bg-primary text-primary-foreground px-4 py-2 font-semibold text-sm">{section.title}</div>
          <table className="w-full text-sm">
            <thead><tr className="bg-muted/50"><th className="text-left px-4 py-2 text-muted-foreground">Item</th><th className="text-left px-4 py-2 text-muted-foreground">State</th><th className="text-left px-4 py-2 text-muted-foreground">Comments</th></tr></thead>
            <tbody>
              {section.items?.map((item, ii) => (
                <tr key={ii} className="border-t border-border">
                  <td className="px-4 py-2">{item.name}</td>
                  <td className="px-4 py-2 font-medium">{item.value || '—'}</td>
                  <td className="px-4 py-2 text-muted-foreground">{item.comment || '—'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ))}

      {(report.summary_tenant || report.summary_agent) && (
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <div className="border border-border rounded-lg p-4">
            <p className="font-semibold mb-1">Maintenance by Tenant</p>
            <p className="text-muted-foreground text-sm">{report.summary_tenant || 'None'}</p>
          </div>
          <div className="border border-border rounded-lg p-4">
            <p className="font-semibold mb-1">Maintenance by Agent/Landlord</p>
            <p className="text-muted-foreground text-sm">{report.summary_agent || 'None'}</p>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useMemo, useState } from 'react';
import { useTenants, useProperties, useLandlords, useRentPayments } from '@/hooks/useAllData';
import { buildTenantInvoices } from '@/lib/invoices';
import { downloadTenantInvoicePDF } from '@/lib/pdfExport';
import { Dialog, DialogContent } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Eye, Download, FileText } from 'lucide-react';
import { formatCurrency } from '@/lib/computations';
import { format, parseISO } from 'date-fns';

export default function PropertyInvoicesTab({ property }) {
  const { data: tenants } = useTenants();
  const { data: properties } = useProperties();
  const { data: landlords } = useLandlords();
  const { data: rentPayments } = useRentPayments();
  const [selectedInvoice, setSelectedInvoice] = useState(null);

  const invoices = useMemo(() => {
    return buildTenantInvoices({ tenants, properties, landlords, rentPayments })
      .filter(inv => inv.property_id === property.id)
      .sort((a, b) => b.period_month.localeCompare(a.period_month));
  }, [tenants, properties, landlords, rentPayments, property.id]);

  const statusStyle = (s) => s === 'Paid' ? 'bg-emerald-50 text-emerald-700 border-emerald-200' : s === 'Partial' ? 'bg-amber-50 text-amber-700 border-amber-200' : s === 'Upcoming' ? 'bg-blue-50 text-blue-700 border-blue-200' : 'bg-red-50 text-red-700 border-red-200';

  return (
    <div>
      <div className="bg-card rounded-xl border border-border overflow-hidden">
        <table className="w-full text-sm">
          <thead>
            <tr className="bg-muted/50">
              <th className="text-left px-5 py-3 font-medium text-muted-foreground">Tenant</th>
              <th className="text-left px-5 py-3 font-medium text-muted-foreground">Period</th>
              <th className="text-right px-5 py-3 font-medium text-muted-foreground">Rent Due</th>
              <th className="text-right px-5 py-3 font-medium text-muted-foreground">Paid</th>
              <th className="text-right px-5 py-3 font-medium text-muted-foreground">Balance</th>
              <th className="text-left px-5 py-3 font-medium text-muted-foreground">Status</th>
              <th className="px-5 py-3"></th>
            </tr>
          </thead>
          <tbody>
            {invoices.map(inv => (
              <tr key={inv.key} className="border-t border-border hover:bg-muted/30 transition-colors">
                <td className="px-5 py-3 font-medium">{inv.tenant_name}</td>
                <td className="px-5 py-3 text-xs text-muted-foreground">{inv.cycle_label || inv.period_month}</td>
                <td className="px-5 py-3 text-right">{formatCurrency(inv.rent_amount)}</td>
                <td className="px-5 py-3 text-right text-emerald-600">{inv.total_paid > 0 ? formatCurrency(inv.total_paid) : '-'}</td>
                <td className="px-5 py-3 text-right font-medium">{inv.balance_due > 0 ? <span className="text-red-600">{formatCurrency(inv.balance_due)}</span> : <span className="text-emerald-600">£0.00</span>}</td>
                <td className="px-5 py-3"><span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium border ${statusStyle(inv.status)}`}>{inv.status}</span></td>
                <td className="px-5 py-3">
                  <div className="flex gap-1">
                    <Button variant="ghost" size="sm" onClick={() => setSelectedInvoice(inv)}><Eye className="w-4 h-4" /></Button>
                    <Button variant="ghost" size="sm" onClick={() => downloadTenantInvoicePDF(inv)}><Download className="w-4 h-4" /></Button>
                  </div>
                </td>
              </tr>
            ))}
            {invoices.length === 0 && <tr><td colSpan="7" className="px-5 py-8 text-center text-muted-foreground">No invoices yet</td></tr>}
          </tbody>
        </table>
      </div>

      <Dialog open={!!selectedInvoice} onOpenChange={v => { if (!v) setSelectedInvoice(null); }}>
        {selectedInvoice && (
          <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
            <div className="space-y-4 py-2">
              <div className="flex items-center gap-3">
                <FileText className="w-5 h-5 text-primary" />
                <h2 className="text-lg font-semibold">{selectedInvoice.invoice_number}</h2>
                <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium border ${statusStyle(selectedInvoice.status)}`}>{selectedInvoice.status}</span>
              </div>
              <div className="grid grid-cols-2 gap-4 text-sm">
                <div><p className="text-muted-foreground">Tenant</p><p className="font-medium">{selectedInvoice.tenant_name}</p></div>
                <div><p className="text-muted-foreground">Period</p><p className="font-medium">{selectedInvoice.cycle_label || selectedInvoice.period_month}</p></div>
                <div><p className="text-muted-foreground">Rent Due</p><p className="font-medium">{formatCurrency(selectedInvoice.rent_amount)}</p></div>
                <div><p className="text-muted-foreground">Amount Paid</p><p className="font-medium text-emerald-600">{formatCurrency(selectedInvoice.total_paid)}</p></div>
              </div>
              {selectedInvoice.payments?.length > 0 && (
                <div>
                  <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-2">Payments</p>
                  <div className="rounded-lg border border-border overflow-hidden">
                    <table className="w-full text-sm">
                      <thead className="bg-muted/50">
                        <tr>
                          <th className="text-left px-4 py-2 font-medium text-muted-foreground">Date</th>
                          <th className="text-left px-4 py-2 font-medium text-muted-foreground">Method</th>
                          <th className="text-right px-4 py-2 font-medium text-muted-foreground">Amount</th>
                        </tr>
                      </thead>
                      <tbody>
                        {selectedInvoice.payments.map(p => (
                          <tr key={p.id} className="border-t border-border">
                            <td className="px-4 py-2 text-muted-foreground">{p.payment_date ? format(parseISO(p.payment_date),'dd MMM yyyy') : '-'}</td>
                            <td className="px-4 py-2">{p.method?.replace(/_/g,' ') || '-'}</td>
                            <td className="px-4 py-2 text-right text-emerald-600 font-medium">{formatCurrency(p.amount)}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
