export default function PropertyLandlordInvoices({
  property, landlord, landlords = [], pPayments, pLedger, pPayouts,
  pExpenses, pExtras, pMaintenance, pTenants = [], pCommissionAgreements = [],
}) {
  const [selected, setSelected] = useState(null);
  const [emailStmt, setEmailStmt] = useState(null);
  const { data: pRentHistory = [] } = useRentHistoryAll();

  const buildEmailBody = (m) => {
    const periodLabel = m.coverage_label ? m.coverage_label : (m.rent_frequency === 'quarterly' && m.cycle_label ? m.cycle_label : fmtPeriod(m.period_month));
    const props = (m.properties_breakdown || []).map(p => `  ${p.address?.split(',')[0]}: ${formatCurrency(p.net)}`).join('\n');
    return `Dear ${m.landlord_name},

Please find below your landlord statement for ${periodLabel}.

Statement No: ${m.statement_number}
Period: ${periodLabel}
Agreed Rent: ${formatCurrency(m.expected_rent || 0)}${m.commission_total > 0 ? '\nCommission: - ' + formatCurrency(m.commission_total) : ''}${m.expenses_total > 0 ? '\nExpenses: - ' + formatCurrency(m.expenses_total) : ''}${m.extras_total > 0 ? '\nDeductions: - ' + formatCurrency(m.extras_total) : ''}${m.maintenance_total > 0 ? '\nMaintenance: - ' + formatCurrency(m.maintenance_total) : ''}

Net Payable: ${formatCurrency(m.invoice_net_payable ?? m.net_payable ?? 0)}
Already Paid: ${formatCurrency(m.paid_this_period)}
Balance Due: ${formatCurrency(m.balance_due)}

Property Breakdown:
${props || '  N/A'}

If you have any questions, please do not hesitate to contact us.

Kind regards,
${biz.name}
${biz.email}`;
  };

  const monthlyStatements = useMemo(() => buildPropertyMonthlyStatements({
    property, landlord, landlords,
    pPayments, pLedger, pPayouts, pExpenses, pExtras, pMaintenance, pTenants, pCommissionAgreements,
    pRentHistory: pRentHistory.filter(r => r.property_id === property?.id),
  }), [pPayments, pLedger, pExpenses, pMaintenance, pExtras, pPayouts, pCommissionAgreements, property, landlord, landlords, pTenants, pRentHistory]);

  const totalNet = monthlyStatements.reduce((s, m) => s + m.invoice_net_payable, 0);
  const totalPaid = monthlyStatements.reduce((s, m) => s + m.paid_this_period, 0);
  const totalBalance = monthlyStatements.reduce((s, m) => s + m.balance_due, 0);

  return (
    <div>
      <div className="flex items-center justify-between mb-4">
        <div>
          <h2 className="text-sm font-semibold">Landlord Invoices</h2>
          <p className="text-xs text-muted-foreground">
            {monthlyStatements[0]?.rent_frequency === 'quarterly'
              ? 'Quarterly net payable — 3× monthly rent, billed per quarter cycle'
              : 'Monthly net payable — fixed at the agreed amount regardless of tenant payment'}
          </p>
        </div>
      </div>

      <div className="grid grid-cols-3 gap-4 mb-6">
        <StatCard label="Total Net Payable" value={formatCurrency(totalNet)} icon={Wallet} />
        <StatCard label="Total Paid" value={formatCurrency(totalPaid)} icon={Banknote} color="success" />
        <StatCard label="Outstanding" value={formatCurrency(totalBalance)} icon={PieChart} color={totalBalance > 0 ? 'warning' : 'success'} />
      </div>

      <div className="bg-white rounded-xl border border-border overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-muted/50">
                <th className="text-left px-4 py-3 font-medium text-muted-foreground">Invoice #</th>
                <th className="text-left px-4 py-3 font-medium text-muted-foreground">Period</th>
                <th className="text-right px-4 py-3 font-medium text-muted-foreground">Gross Payable</th>
                <th className="text-right px-4 py-3 font-medium text-muted-foreground">Net Payable</th>
                <th className="text-right px-4 py-3 font-medium text-muted-foreground">Paid (Bank)</th>
                <th className="text-left px-4 py-3 font-medium text-muted-foreground">Bank Date</th>
                <th className="text-right px-4 py-3 font-medium text-muted-foreground">Balance Due</th>
                <th className="text-left px-4 py-3 font-medium text-muted-foreground">Status</th>
                <th className="px-4 py-3"></th>
              </tr>
            </thead>
            <tbody>
              {monthlyStatements.map(m => (
                <tr key={m.key} className="border-t border-border hover:bg-muted/30 transition-colors">
                  <td className="px-4 py-3 font-mono text-xs text-muted-foreground">{m.statement_number}</td>
                  <td className="px-4 py-3 font-medium">
                    {m.coverage_label
                      ? <span title="Pro-rated for mid-cycle move-out">{m.coverage_label}</span>
                      : m.rent_frequency === 'quarterly' && m.cycle_label
                        ? <span>{m.cycle_label}</span>
                        : fmtPeriod(m.period_month)}
                    {m.is_co_owned && <span className="block text-xs font-normal text-primary">{m.landlord_name} · {m.share_pct}%</span>}
                  </td>
                  <td className="px-4 py-3 text-right text-muted-foreground">{formatCurrency((m.expected_rent || 0) - (m.commission_total || 0))}</td>
                  <td className="px-4 py-3 text-right font-medium">{formatCurrency(m.invoice_net_payable)}</td>
                  <td className="px-4 py-3 text-right text-emerald-600">{m.paid_this_period > 0 ? formatCurrency(m.paid_this_period) : '-'}</td>
                  <td className="px-4 py-3 text-xs text-muted-foreground">
                    {m.bank_payout_entries?.length > 0
                      ? m.bank_payout_entries.map(p => {
                        try { return format(parseISO(p.bank_date || p.payment_date), 'dd MMM yyyy'); } catch { return '-'; }
                      }).join(', ')
                      : '-'}
                  </td>
                  <td className="px-4 py-3 text-right font-medium">
                    {m.balance_due > 0
                      ? <span className="text-red-600">{formatCurrency(m.balance_due)}</span>
                      : <span className="text-emerald-600">£0.00</span>}
                  </td>
                  <td className="px-4 py-3">
                    <StatusBadge color={STATUS_COLOR[m.status]}>{m.status}</StatusBadge>
                  </td>
                  <td className="px-4 py-3">
                    <div className="flex gap-1">
                      <Button variant="ghost" size="sm" onClick={() => setSelected(m)}>
                        <Eye className="w-4 h-4" />
                      </Button>
                      <Button variant="ghost" size="sm" onClick={() => downloadLandlordStatementPDF(m)}>
                        <Download className="w-4 h-4" />
                      </Button>
                      <Button variant="ghost" size="sm" disabled={!m.landlord_email} title={m.landlord_email ? 'Send email' : 'No email on record'} onClick={() => setEmailStmt(m)}>
                        <Mail className="w-4 h-4" />
                      </Button>
                    </div>
                  </td>
                </tr>
              ))}
              {monthlyStatements.length === 0 && (
                <tr>
                  <td colSpan="9" className="px-4 py-10 text-center text-muted-foreground">
                    No landlord invoices yet
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      <Dialog open={!!selected} onOpenChange={v => { if (!v) setSelected(null); }}>
        <InvoiceDetailModal stmt={selected} onClose={() => setSelected(null)} />
      </Dialog>

      {emailStmt && (
        <EmailComposer
          open={!!emailStmt}
          onClose={() => setEmailStmt(null)}
          to={emailStmt.landlord_email}
          toName={emailStmt.landlord_name}
          subject={`Landlord Statement – ${emailStmt.statement_number} – ${emailStmt.rent_frequency === 'quarterly' && emailStmt.cycle_label ? emailStmt.cycle_label : fmtPeriod(emailStmt.period_month)}`}
          body={buildEmailBody(emailStmt)}
          type="landlord_statement"
          referenceId={emailStmt.key}
          attachmentBlobFn={() => getLandlordStatementPDFBlob(emailStmt)}
          attachmentName={`${emailStmt.statement_number}-Statement.pdf`}
        />
      )}
    </div>
  );
}

