];
const YEARS = Array.from({ length: 15 }, (_, i) => String(new Date().getFullYear() - 5 + i));

function PeriodPicker({ value, onChange }) {
  const initParts = (value || format(new Date(), 'yyyy-MM')).split('-');
  const [month, setMonth] = React.useState(initParts[1] || format(new Date(), 'MM'));
  const [year,  setYear]  = React.useState(initParts[0] || String(new Date().getFullYear()));
  const handleMonth = (m) => { setMonth(m); onChange(`${year}-${m}`); };
  const handleYear  = (y) => { setYear(y);  onChange(`${y}-${month}`); };
  return (
    <div className="flex gap-2">
      <Select value={month} onValueChange={handleMonth}>
        <SelectTrigger className="flex-1"><SelectValue placeholder="Month" /></SelectTrigger>
        <SelectContent>
          {MONTHS.map(m => <SelectItem key={m.value} value={m.value}>{m.label}</SelectItem>)}
        </SelectContent>
      </Select>
      <Select value={year} onValueChange={handleYear}>
        <SelectTrigger className="w-28"><SelectValue placeholder="Year" /></SelectTrigger>
        <SelectContent>
          {YEARS.map(y => <SelectItem key={y} value={y}>{y}</SelectItem>)}
        </SelectContent>
      </Select>
    </div>
  );
}

