  const [submitting, setSubmitting] = useState(false);
  const [splitBankName, setSplitBankName] = useState('');
  const [data, setData] = useState({
    amount: pendingAmount || '',
    payment_date: format(new Date(), 'yyyy-MM-dd'),
    period_month: format(new Date(), 'yyyy-MM'),
    method: 'bank_transfer', reference: '', notes: '',
  });

  const cashNum = Number(cashAmount) || 0;
  const bankNum = Number(bankAmount) || 0;
  const cashInvolved = (paymentMode === 'single' && data.method === 'cash') || (paymentMode === 'split' && cashNum > 0);
  const totalAmount = paymentMode === 'split' ? cashNum + bankNum : Number(data.amount) || 0;
  const cashExceedsTotal = paymentMode === 'split' && cashNum > (pendingAmount || 9999999);

  const handleCashChange = (val) => {
    setCashAmount(val);
    const cash = Number(val) || 0;
    setBankAmount(Math.max(0, (pendingAmount || 0) - cash).toFixed(2));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (submitting) return;
    setSubmitting(true);

    try {
      if (paymentMode === 'split') {
        await onSubmit({
          ...data, amount: cashNum + bankNum,
          method: 'split', payment_mode: 'split',
          cash_amount: cashNum, bank_amount: bankNum,
          bank_date: bankDate, cash_date: cashDate || null, cash_pending: !cashDate,
          property_id: property.id, landlord_id: targetLandlordId,
          split_bank_name: splitBankName || '',
        });
      } else {
        await onSubmit({ ...data, amount: Number(data.amount), payment_mode: 'single', cash_amount: 0, bank_amount: 0, property_id: property.id, landlord_id: targetLandlordId, paid_from_bank_name: paidFromBankName || '' });
      }
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      {pendingAmount > 0 && (
        <div className="rounded-lg bg-blue-50 border border-blue-200 px-4 py-3 text-sm">
          <span className="text-blue-700 font-medium">Pending Balance: </span>
          <span className="font-bold text-blue-900">£{Number(pendingAmount).toFixed(2)}</span>
        </div>
      )}

      {allowSplit && (
        <div className="space-y-2">
          <Label>Payment Mode</Label>
          <div className="flex gap-2">
            <button type="button" onClick={() => setPaymentMode('single')} className={`flex-1 py-2 rounded-lg border text-sm font-medium transition-colors ${paymentMode === 'single' ? 'bg-primary text-primary-foreground border-primary' : 'border-border hover:bg-muted'}`}>Single</button>
            <button type="button" onClick={() => setPaymentMode('split')} className={`flex-1 py-2 rounded-lg border text-sm font-medium transition-colors ${paymentMode === 'split' ? 'bg-amber-500 text-white border-amber-500' : 'border-border hover:bg-muted'}`}>Split (Cash + Bank)</button>
          </div>
        </div>
      )}

      {paymentMode === 'split' && (
        <div className="rounded-lg border border-amber-200 bg-amber-50 p-4 space-y-3">
          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1">
              <Label className="text-xs">Bank Amount (£) — auto-calc</Label>
              <Input type="number" value={bankAmount} readOnly className="bg-muted opacity-60" />
            </div>
            <div className="space-y-1">
              <Label className="text-xs">Bank Transfer Date *</Label>
              <Input type="date" value={bankDate} onChange={e => setBankDate(e.target.value)} required />
            </div>
            <div className="space-y-1">
              <Label className="text-xs">Cash Amount (£)</Label>
              <Input type="number" min="0" step="0.01" value={cashAmount} onChange={e => handleCashChange(e.target.value)} className={cashExceedsTotal ? 'border-red-500' : ''} />
              {cashExceedsTotal && <p className="text-xs text-red-600">Cannot exceed pending balance</p>}
            </div>
            <div className="space-y-1">
              <Label className="text-xs">Cash Date (optional)</Label>
              <Input type="date" value={cashDate} onChange={e => setCashDate(e.target.value)} />
            </div>
            <div className="col-span-2 space-y-1">
              <Label className="text-xs">Paid From Bank Account (bank portion)</Label>
              <Select value={splitBankName} onValueChange={setSplitBankName}>
                <SelectTrigger><SelectValue placeholder="Select bank" /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="HSBC">HSBC</SelectItem>
                  <SelectItem value="Santander">Santander</SelectItem>
                  <SelectItem value="Lloyds">Lloyds</SelectItem>
                  <SelectItem value="Barclays">Barclays</SelectItem>
                  <SelectItem value="NatWest">NatWest</SelectItem>
                  <SelectItem value="Halifax">Halifax</SelectItem>
                  <SelectItem value="Metro Bank">Metro Bank</SelectItem>
                  <SelectItem value="Monzo">Monzo</SelectItem>
                  <SelectItem value="Starling">Starling</SelectItem>
                  <SelectItem value="Other">Other</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
          <div className="text-sm font-semibold bg-white px-3 py-2 rounded border border-amber-200">Total: £{totalAmount.toFixed(2)}</div>
        </div>
      )}

      <div className="grid grid-cols-2 gap-4">
        <div className="space-y-1">
          <Label>Amount (£) *</Label>
          <Input type="number" min="0" step="0.01" value={data.amount} onChange={e => setData({ ...data, amount: e.target.value })} required disabled={paymentMode === 'split'} />
        </div>
        <div className="space-y-1">
          <Label>Date *</Label>
          <Input type="date" value={data.payment_date} onChange={e => setData({ ...data, payment_date: e.target.value })} required />
        </div>
        <div className="space-y-1">
          <Label>Period Month *</Label>
          <PeriodPicker value={data.period_month} onChange={v => setData({ ...data, period_month: v })} />
        </div>
        {paymentMode === 'single' && (
          <div className="space-y-1">
            <Label>Method</Label>
            <Select value={data.method} onValueChange={v => setData(prev => ({ ...prev, method: v, paid_from_bank_name: v === 'cash' ? '' : prev.paid_from_bank_name }))}>
              <SelectTrigger><SelectValue /></SelectTrigger>
              <SelectContent>{['bank_transfer', 'cheque', 'cash', 'other'].map(m => <SelectItem key={m} value={m}>{m.replace(/_/g, ' ')}</SelectItem>)}</SelectContent>
            </Select>
          </div>
        )}
        {paymentMode === 'single' && data.method !== 'cash' && (
          <div className="space-y-1">
            <Label>Paid From Bank</Label>

          </div>
        )}
        {paymentMode === 'single' && data.method !== 'cash' && (
          <div className="space-y-1">
            <Label>Paid From Account</Label>
            <Select value={paidFromBankName} onValueChange={setPaidFromBankName}>
              <SelectTrigger><SelectValue placeholder="Select bank" /></SelectTrigger>
              <SelectContent>
                <SelectItem value="HSBC">HSBC</SelectItem>
                <SelectItem value="Santander">Santander</SelectItem>
                <SelectItem value="Lloyds">Lloyds</SelectItem>
                <SelectItem value="Barclays">Barclays</SelectItem>
                <SelectItem value="NatWest">NatWest</SelectItem>
                <SelectItem value="Halifax">Halifax</SelectItem>
                <SelectItem value="Metro Bank">Metro Bank</SelectItem>
                <SelectItem value="Monzo">Monzo</SelectItem>
                <SelectItem value="Starling">Starling</SelectItem>
                <SelectItem value="Other">Other</SelectItem>
              </SelectContent>
            </Select>
          </div>
        )}
        <div className="space-y-1">
          <Label>{cashInvolved ? 'Cash paid to (name) *' : 'Reference'}</Label>
          <Input value={data.reference} onChange={e => setData({ ...data, reference: e.target.value })}
            placeholder={cashInvolved ? 'Who was the cash handed to?' : ''} required={cashInvolved} />
        </div>
      </div>
      <div className="space-y-1">
        <Label>Notes</Label>
        <Textarea value={data.notes} onChange={e => setData({ ...data, notes: e.target.value })} rows={2} />
      </div>
      <div className="flex gap-2 justify-end">
        <Button type="button" variant="outline" onClick={onCancel}>Cancel</Button>
        <Button type="submit" disabled={cashExceedsTotal || submitting || (cashInvolved && !String(data.reference || '').trim())}>{submitting ? 'Saving...' : paymentMode === 'split' ? 'Record Split Payment' : 'Record Payment'}</Button>
      </div>
    </form>
  );
}

export default function PropertyLandlordPayments({ property, landlord, landlords, properties, pPayments, pLedger, pPayouts, pExpenses, pExtras, pMaintenance, pTenants, pCommissionAgreements }) {
  const { user, isAdmin, isManager } = useRole();
  const canEdit = isAdmin || isManager;
  const queryClient = useQueryClient();
  const [showForm, setShowForm] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(null);

  const cycleSummary = useMemo(() => {
    if (!property?.payment_day || !landlord) return null;
    return buildPropertyCycleSummary({
      property, landlord,
      rentPayments: pPayments,
      commissionLedger: pLedger,
      expenses: pExpenses || [],
      landlordPayouts: pPayouts,
      paymentExtras: pExtras || [],
      tenants: pTenants || [],
      commissionAgreements: pCommissionAgreements || [],
    });
  }, [property, landlord, pPayments, pLedger, pExpenses, pPayouts, pExtras, pTenants, pCommissionAgreements]);

  // Authoritative per-month figures — SAME source as the Landlord Invoices tab,
  // so commission (from the agreement) is deducted consistently across both tabs.
  const stmts = useMemo(() => buildPropertyMonthlyStatements({
    property, landlord, landlords,
    pPayments, pLedger, pPayouts, pExpenses, pExtras, pMaintenance, pTenants, pCommissionAgreements,
  }), [property, landlord, landlords, pPayments, pLedger, pPayouts, pExpenses, pExtras, pMaintenance, pTenants, pCommissionAgreements]);

  // Split the cycle across co-owners (single-landlord → one row, unchanged).
  const cycleRows = useMemo(() => {
    if (!cycleSummary) return [];
    const shares = getLandlordShares(property);
    const single = shares.length <= 1 && (shares.length === 0 || shares[0].landlord_id === property?.landlord_id);
    // Commission for the cycle's month, from the agreement (consistent with the Invoices tab).
    const cyclePeriod = cycleSummary.cycleStart.substring(0, 7);
    const cycleCommission = stmts.filter(m => m.period_month === cyclePeriod).reduce((s, m) => s + (m.commission_total || 0), 0);
    const cyclePayable = round2(cycleSummary.rentCollected - cycleCommission - cycleSummary.expensesDeducted - (cycleSummary.extraDeductions || 0));
    if (single) {
      const paid = cycleSummary.alreadyPaid;
      const status = paid >= cyclePayable && cyclePayable > 0 ? 'Paid' : paid > 0 ? 'Partial' : (cycleSummary.isOverdue && cyclePayable > 0 ? 'Overdue' : 'Pending');
      return [{
        landlord_name: null, share_pct: null,
        rentCollected: cycleSummary.rentCollected,
        expensesDeducted: round2(cycleSummary.expensesDeducted + cycleCommission),
        payable: cyclePayable,
        alreadyPaid: paid,
        balance: round2(cyclePayable - paid),
        status,
      }];
    }
    // Separate deductions targeted at ONE owner from shared (split) ones.
    const cycleExtras = (pExtras || []).filter(e =>
      e.property_id === property.id &&
      (e.period_month === cyclePeriod || (!e.period_month && e.date >= cycleSummary.cycleStart && e.date <= cycleSummary.cycleEnd))
    );
    const targetedByLandlord = {};
    let sharedExtras = 0;
    cycleExtras.forEach(e => {
      if (e.deduct_from_landlord_id) {
        targetedByLandlord[e.deduct_from_landlord_id] = (targetedByLandlord[e.deduct_from_landlord_id] || 0) + (e.amount || 0);
      } else {
        sharedExtras += (e.amount || 0);
      }
    });
    const totalTargeted = Object.values(targetedByLandlord).reduce((s, v) => s + v, 0);

    // Pool that gets split by share = everything EXCEPT the targeted deductions.
    // (cycleSummary.extraDeductions already subtracted ALL extras, so add the
    // targeted ones back before splitting, then remove each from its owner.)
    const poolPayable = round2(cyclePayable + totalTargeted);
    const parts = splitByShares(poolPayable, shares);
    return shares.map((sh, i) => {
      const frac = parts[i].fraction;
      const ll = landlords.find(l => l.id === sh.landlord_id);
      const paid = pPayouts
        .filter(p => p.landlord_id === sh.landlord_id && p.payment_date >= cycleSummary.cycleStart && p.payment_date <= cycleSummary.cycleEnd)
        .reduce((s, p) => s + (p.payment_mode === 'split' ? (p.bank_amount || 0) + (p.cash_amount || 0) : (p.amount || 0)), 0);
      const targeted = round2(targetedByLandlord[sh.landlord_id] || 0);
      const payable = round2(parts[i].amount - targeted);
      const balance = round2(payable - paid);
      const status = paid >= payable && payable > 0 ? 'Paid' : paid > 0 ? 'Partial' : (cycleSummary.isOverdue && payable > 0 ? 'Overdue' : 'Pending');
      return {
        landlord_name: ll?.name || 'Unknown', share_pct: sh.share_pct,
        rentCollected: round2(cycleSummary.rentCollected * frac),
        expensesDeducted: round2((cycleSummary.expensesDeducted + cycleCommission) * frac + targeted),
        soleDeduction: targeted,
        payable, alreadyPaid: paid, balance, status,
      };
    });
  }, [cycleSummary, property, landlords, pPayouts, pExtras, stmts]);

  const handlePayCash = async (payout) => {
    if (!isAdmin) return;
    const cashDate = format(new Date(), 'yyyy-MM-dd');
    await base44.entities.CashEntry.create({
      date: cashDate,
      type: 'Expense',
      category: 'Landlord Payment - Cash',
      description: `Split Payment (Cash) - ${landlord?.name}`,
      amount: payout.cash_amount,
      property_id: property.id,
      notes: `Payout #${payout.id.substring(0, 8)} (Property: ${property.address})`,
      added_by: user.email,
    });
    await base44.entities.LandlordPayout.update(payout.id, { ...payout, cash_pending: false, cash_date: cashDate });
    await logAction({ user, action: 'update', entityType: 'LandlordPayout', entityId: payout.id, summary: `Cash paid to ${landlord?.name} — £${payout.cash_amount}` });
    queryClient.invalidateQueries({ queryKey: ['landlord_payouts'] });
    queryClient.invalidateQueries({ queryKey: ['cash_entries'] });
  };

  // Totals derived from the SAME statements as the Invoices tab → always consistent.
  // Commission comes from the agreement (not the ledger), so it's always deducted.
  const totalCommission = stmts.reduce((s, m) => s + (m.commission_total || 0), 0);
  const totalExpenses = stmts.reduce((s, m) => s + (m.expenses_total || 0), 0);
  const totalExtras = stmts.reduce((s, m) => s + (m.extras_total || 0), 0);
  const totalMaint = stmts.reduce((s, m) => s + (m.maintenance_total || 0), 0);
  const netPayable = stmts.reduce((s, m) => s + (m.invoice_net_payable || 0), 0);
  const totalPaid = stmts.reduce((s, m) => s + (m.paid_this_period || 0), 0);
  const outstanding = stmts.reduce((s, m) => s + (m.balance_due || 0), 0);

  // Co-ownership: pay each owner their own share separately.
  const coOwned = isMultiLandlord(property);
  const ownerShares = getLandlordShares(property);
  const [payLandlordId, setPayLandlordId] = useState(property.landlord_id);
  // Each owner's outstanding = sum of their own statement balances (exact, per-owner).
  const outstandingByLandlord = (lid) => round2(stmts.filter(m => m.landlord_id === lid).reduce((s, m) => s + (m.balance_due || 0), 0));
  const selectedLandlord = landlords.find(l => l.id === payLandlordId) || landlord;
  const pendingForSelected = coOwned ? Math.max(0, outstandingByLandlord(payLandlordId)) : Math.max(0, outstanding);
  const openPayDialog = (lid) => { setPayLandlordId(lid || property.landlord_id); setShowForm(true); };

  const handleSubmit = async (data) => {
    if (!isAdmin) return;
    const paidLandlord = landlords.find(l => l.id === data.landlord_id) || landlord;
    const created = await base44.entities.LandlordPayout.create(data);
    if (data.payment_mode === 'split') {
      if (data.bank_amount > 0) {
        await base44.entities.LedgerAdjustment.create({
          date: data.bank_date || data.payment_date,
          type: 'Expense',
          description: `Landlord payment (bank) — ${paidLandlord?.name}${data.split_bank_name ? ' · ' + data.split_bank_name : ''}${data.reference ? ` · cash to ${data.reference}` : ''}`,
          amount: data.bank_amount,
          landlord_id: data.landlord_id,
          property_id: data.property_id,
          bank_name: data.split_bank_name || '',
          reason: `Bank portion of split payout #${created.id.substring(0, 8)}`,
          edited_by: user.email,
        });
      }
      if (data.cash_amount > 0 && data.cash_date) {
        await base44.entities.CashEntry.create({
          date: data.cash_date,
          type: 'Expense',
          category: 'Landlord Payment - Cash',
          description: `Split Payment (Cash) - ${paidLandlord?.name}${data.reference ? ` · paid to ${data.reference}` : ''}`,
          amount: data.cash_amount,
          property_id: property.id,
          notes: `Payout #${created.id.substring(0, 8)} (Property: ${property.address})`,
          added_by: user.email,
        });
      }
    }
    await logAction({ user, action: 'create', entityType: 'LandlordPayout', entityId: created.id, summary: `Recorded payout of £${data.amount} to ${paidLandlord?.name} for ${property.address}`, newValue: data });
    queryClient.invalidateQueries({ queryKey: ['landlord_payouts'] });
    queryClient.invalidateQueries({ queryKey: ['ledger_adjustments'] });
    queryClient.invalidateQueries({ queryKey: ['cash_entries'] });
    setShowForm(false);
  };

  const handleDelete = async (payout) => {
    if (!isAdmin) return;
    const payoutRef = payout.id.substring(0, 8);
    // Delete linked CashEntry (cash portion of split)
    if (payout.payment_mode === 'split' && payout.cash_amount > 0) {
      const cashEntries = await base44.entities.CashEntry.filter({ type: 'Expense' });
      const toDelete = cashEntries.filter(c => c.notes?.includes(payoutRef));
      for (const entry of toDelete) await base44.entities.CashEntry.delete(entry.id);
    }
    // Delete linked LedgerAdjustment (bank portion of split)
    if (payout.payment_mode === 'split' && payout.bank_amount > 0) {
      const ledgerEntries = await base44.entities.LedgerAdjustment.filter({ type: 'Expense' });
      const toDelete = ledgerEntries.filter(l => l.reason?.includes(payoutRef));
      for (const entry of toDelete) await base44.entities.LedgerAdjustment.delete(entry.id);
    }
    await base44.entities.LandlordPayout.delete(payout.id);
    await logAction({ user, action: 'delete', entityType: 'LandlordPayout', entityId: payout.id, summary: `Deleted payout of £${payout.amount}${payout.period_month ? ` (period: ${payout.period_month})` : ''}`, oldValue: payout });
    queryClient.invalidateQueries({ queryKey: ['landlord_payouts'] });
    queryClient.invalidateQueries({ queryKey: ['ledger_adjustments'] });
    queryClient.invalidateQueries({ queryKey: ['cash_entries'] });
    queryClient.invalidateQueries({ queryKey: ['commission_ledger'] });
    queryClient.invalidateQueries({ queryKey: ['rent_payments'] });
    queryClient.invalidateQueries({ queryKey: ['payment_extras'] });
    setConfirmDelete(null);
  };

  return (
    <div className="space-y-8">
      {/* Link to full Landlord Payment Schedule */}
      <div>
        <Button asChild>
          <Link to="/LandlordPaymentSchedule">
            <Calendar className="w-4 h-4 mr-1.5" />
            View Landlord Payment Schedule
            <ExternalLink className="w-3.5 h-3.5 ml-1.5" />
          </Link>
        </Button>
      </div>

      {/* Extras / Deductions */}
      <ExtrasSection
        extras={pExtras || []}
        landlords={landlords}
        properties={properties}
        property={property}
        user={user}
        isAdmin={isAdmin}
        filterPropertyId={property.id}
        filterLandlordId={property.landlord_id}
      />

      <div>
        <div className="flex items-center justify-between mb-4">
          <div>
            <h2 className="text-sm font-semibold">Landlord Payments</h2>
            <p className="text-xs text-muted-foreground">{coOwned ? 'Pay each owner their own share separately' : `Payments made to ${landlord?.name}`}</p>
          </div>
          {isAdmin ? (
            coOwned ? (
              <div className="flex flex-wrap gap-2 justify-end">
                {ownerShares.map(s => {
                  const ll = landlords.find(l => l.id === s.landlord_id);
                  const due = Math.max(0, outstandingByLandlord(s.landlord_id));
                  return (
                    <Button key={s.landlord_id} size="sm" variant={due > 0 ? 'default' : 'outline'} onClick={() => openPayDialog(s.landlord_id)}>
                      <Plus className="w-4 h-4 mr-1.5" />Pay {ll?.name?.split(' ')[0] || 'owner'} ({formatCurrency(due)})
                    </Button>
                  );
                })}
              </div>
            ) : (
              <Button size="sm" onClick={() => openPayDialog(property.landlord_id)}>
                <Plus className="w-4 h-4 mr-1.5" />Pay Landlord
              </Button>
            )
          ) : (
            <span className="text-xs text-muted-foreground flex items-center gap-1"><Lock className="w-3 h-3" />Admin only</span>
          )}
        </div>

        <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
          <StatCard label="Net Payable" value={formatCurrency(netPayable)} icon={Wallet} />
          <StatCard label="Paid" value={formatCurrency(totalPaid)} icon={Wallet} color="success" />
          <StatCard label="Outstanding" value={formatCurrency(outstanding)} icon={Wallet} color={outstanding > 0 ? 'warning' : 'success'} />
          <StatCard label="Total Deductions" value={formatCurrency(totalCommission + totalExpenses + totalExtras + totalMaint)} icon={Wallet} color="primary" />
        </div>

        <div className="bg-card rounded-xl border border-border overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="bg-muted/50">
                  <th className="text-left px-5 py-3 font-medium text-muted-foreground">Date</th>
                  <th className="text-left px-5 py-3 font-medium text-muted-foreground">Amount</th>
                  <th className="text-left px-5 py-3 font-medium text-muted-foreground">Period</th>
                  <th className="text-left px-5 py-3 font-medium text-muted-foreground">Method</th>
                  <th className="text-left px-5 py-3 font-medium text-muted-foreground">Paid From</th>
                  <th className="text-left px-5 py-3 font-medium text-muted-foreground">Reference</th>
                  {isAdmin && <th className="px-5 py-3" />}
                </tr>
              </thead>
              <tbody>
                {pPayouts.map(p => (
                  <tr key={p.id} className="border-t border-border hover:bg-muted/30 transition-colors">
                    <td className="px-5 py-3 text-muted-foreground">{p.payment_date ? format(parseISO(p.payment_date), 'dd MMM yyyy') : '—'}</td>
                    <td className="px-5 py-3 font-semibold text-emerald-700">
                      {formatCurrency(p.amount)}
                      {coOwned && <div className="text-xs font-normal text-primary mt-0.5">→ {landlords.find(l => l.id === p.landlord_id)?.name || 'Unknown'}</div>}
                      {p.payment_mode === 'split' && (
                        <div className="text-xs text-muted-foreground mt-0.5">
                          <div>🏦 £{(p.bank_amount || 0).toFixed(2)} bank</div>
                          <div className={p.cash_pending ? 'text-amber-600' : ''}>💵 £{(p.cash_amount || 0).toFixed(2)} cash {p.cash_pending ? '— PENDING' : ''}</div>
                        </div>
                      )}
                    </td>
                    <td className="px-5 py-3">{p.period_month || '—'}</td>
                    <td className="px-5 py-3"><StatusBadge color={p.payment_mode === 'split' ? 'yellow' : p.method === 'cash' ? 'yellow' : 'blue'}>{p.payment_mode === 'split' ? 'Split' : p.method?.replace(/_/g, ' ')}</StatusBadge></td>
                    <td className="px-5 py-3 text-xs text-muted-foreground">
                      {p.payment_mode === 'split'
                        ? (p.split_bank_name ? `🏦 ${p.split_bank_name}` : '—')
                        : p.method === 'cash' ? '💵 Cash'
                        : (p.paid_from_bank_name || '—')}
                    </td>
                    <td className="px-5 py-3 text-muted-foreground">{p.reference || '—'}</td>
                    {isAdmin && (
                      <td className="px-5 py-3">
                        <div className="flex gap-1 flex-wrap">
                          {p.payment_mode === 'split' && p.cash_pending && (
                            <Button size="sm" className="bg-amber-500 hover:bg-amber-600 text-white text-xs h-7 px-2" onClick={() => handlePayCash(p)}>
                              💵 Pay Cash Now
                            </Button>
                          )}
                          {(p.payment_mode === 'split' ? (p.bank_amount || 0) > 0 : p.method !== 'cash') && (
                                           <Button variant="ghost" size="sm" className="text-xs h-7 px-2" onClick={() => p.payment_mode === 'split' ? downloadSplitPayoutPDF(p, landlords, properties, 'bank') : downloadSingleBankStatementPDF(p, landlords, properties)}>
                                             🏦 Bank Statement
                                           </Button>
                                         )}
                                         {p.method === 'cash' && (p.payment_mode === 'single' || !p.payment_mode) && (
                                           <Button variant="ghost" size="sm" className="text-xs h-7 px-2" onClick={() => downloadCashReceiptPDF(p, landlords, properties)}>
                                             💵 Cash Receipt
                                           </Button>
                                         )}
                                         {p.payment_mode === 'split' && (p.cash_amount || 0) > 0 && (
                                           <Button variant="ghost" size="sm" className="text-xs h-7 px-2 text-muted-foreground" onClick={() => downloadSplitPayoutPDF(p, landlords, properties, 'cash')}>
                                             💵 Cash Receipt
                                           </Button>
                                         )}
                          <Button variant="ghost" size="sm" className="text-destructive hover:text-destructive" onClick={() => setConfirmDelete(p)}>
                            <Trash2 className="w-4 h-4" />
                          </Button>
                        </div>
                      </td>
                    )}
                  </tr>
                ))}
                {pPayouts.length === 0 && <tr><td colSpan="6" className="px-5 py-10 text-center text-muted-foreground">No payments to landlord yet</td></tr>}
              </tbody>
            </table>
          </div>
        </div>
      </div>{/* end payments section */}

      <Dialog open={showForm} onOpenChange={setShowForm}>
        <DialogContent className="max-w-lg">
          <DialogHeader><DialogTitle>Pay Landlord — {selectedLandlord?.name}{coOwned && ownerShares.find(s => s.landlord_id === payLandlordId) ? ` (${ownerShares.find(s => s.landlord_id === payLandlordId).share_pct}%)` : ''}</DialogTitle></DialogHeader>
          <PayoutForm key={payLandlordId} property={property} landlord={selectedLandlord} payLandlordId={payLandlordId} pendingAmount={pendingForSelected} onSubmit={handleSubmit} onCancel={() => setShowForm(false)} />
        </DialogContent>
      </Dialog>

      <ConfirmDialog
        open={!!confirmDelete}
        title="Delete Payment"
        description={`Delete payout of ${formatCurrency(confirmDelete?.amount)}?`}
        onConfirm={() => handleDelete(confirmDelete)}
        onCancel={() => setConfirmDelete(null)}
      />
    </div>
  );
}

import React, { useState } from 'react';
import { base44 } from '@/api/base44Client';
import { useQueryClient } from '@tanstack/react-query';
import { useCRMEntries, useCommissionAgreements, useLandlordPayouts, useCommissionLedger } from '@/hooks/useAllData';
import { useRole } from '@/hooks/useRole';
import { logAction } from '@/lib/audit';
import StatusBadge from '@/components/ui/StatusBadge';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Plus, CheckCircle, Pencil, Trash2, Phone, Mail, User } from 'lucide-react';
import { formatCurrency, calculateLandlordBalance } from '@/lib/computations';
import { format, parseISO } from 'date-fns';
import { Link } from 'react-router-dom';

function CRMForm({ entry, landlordId, onSubmit, onCancel }) {
  const [data, setData] = useState(entry || { landlord_id: landlordId, type: 'note', subject: '', content: '', due_date: '', completed: false });
  return (
    <form onSubmit={e => { e.preventDefault(); onSubmit(data); }} className="space-y-4">
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div className="space-y-2 sm:col-span-2"><Label>Type</Label>
          <Select value={data.type} onValueChange={v => setData({ ...data, type: v })}>
            <SelectTrigger><SelectValue /></SelectTrigger>
            <SelectContent>{['note','call','email','message','meeting','task'].map(t => <SelectItem key={t} value={t}>{t.charAt(0).toUpperCase()+t.slice(1)}</SelectItem>)}</SelectContent>
          </Select>
        </div>
        <div className="space-y-2 sm:col-span-2"><Label>Subject *</Label><Input value={data.subject} onChange={e => setData({...data,subject:e.target.value})} required /></div>
      </div>
      <div className="space-y-2"><Label>Content</Label><Textarea value={data.content||''} onChange={e => setData({...data,content:e.target.value})} rows={3} /></div>
      {data.type === 'task' && <div className="space-y-2"><Label>Due Date</Label><Input type="date" value={data.due_date||''} onChange={e => setData({...data,due_date:e.target.value})} /></div>}
      <div className="flex gap-3 justify-end pt-2">
        <Button type="button" variant="outline" onClick={onCancel}>Cancel</Button>
        <Button type="submit">{entry ? 'Update' : 'Add Entry'}</Button>
      </div>
    </form>
  );
}

export default function PropertyLandlordTab({ property, landlord }) {
  const { user } = useRole();
  const queryClient = useQueryClient();
  const { data: allCRM } = useCRMEntries();
  const { data: allAgreements } = useCommissionAgreements();
  const { data: allPayouts } = useLandlordPayouts();
  const { data: ledger } = useCommissionLedger();
  const [showCRMForm, setShowCRMForm] = useState(false);
  const [editingCRM, setEditingCRM] = useState(null);

  if (!landlord) return <div className="p-8 text-center text-muted-foreground">No landlord linked to this property.</div>;

  const lid = landlord.id;
  const crm = allCRM.filter(e => e.landlord_id === lid);
  const agreements = allAgreements.filter(a => a.landlord_id === lid);
  const payouts = allPayouts.filter(p => p.landlord_id === lid);
  const lLedger = ledger.filter(e => e.landlord_id === lid);
  const balance = calculateLandlordBalance(lLedger, payouts);
  const typeColors = { note:'gray',call:'blue',email:'blue',message:'blue',meeting:'yellow',task:'green' };

  const handleCRMSubmit = async (data) => {
    if (editingCRM) {
      await base44.entities.CRMEntry.update(editingCRM.id, data);
    } else {
      await base44.entities.CRMEntry.create(data);
    }
    queryClient.invalidateQueries({ queryKey: ['crm_entries'] });
    setShowCRMForm(false); setEditingCRM(null);
  };

  const toggleComplete = async (entry) => {
    await base44.entities.CRMEntry.update(entry.id, { completed: !entry.completed });
    queryClient.invalidateQueries({ queryKey: ['crm_entries'] });
  };

  return (
    <div className="space-y-8">
      {/* Landlord Info */}
      <div className="bg-card border border-border rounded-xl p-5">
        <div className="flex items-start justify-between mb-4">
          <h3 className="text-sm font-semibold">Landlord Details</h3>
          <Link to={`/LandlordDetail?id=${lid}`}><Button variant="outline" size="sm">Full Profile</Button></Link>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 text-sm">
          <div className="flex items-center gap-2"><User className="w-4 h-4 text-muted-foreground" /><span className="font-medium">{landlord.name}</span></div>
          {landlord.email && <div className="flex items-center gap-2"><Mail className="w-4 h-4 text-muted-foreground" /><span>{landlord.email}</span></div>}
          {landlord.phone && <div className="flex items-center gap-2"><Phone className="w-4 h-4 text-muted-foreground" /><span>{landlord.phone}</span></div>}
        </div>
        <div className="mt-4 pt-4 border-t border-border grid grid-cols-1 sm:grid-cols-2 gap-3 text-sm">
          <div><p className="text-muted-foreground">Balance Owed</p><p className={`font-semibold text-lg ${balance > 0 ? 'text-amber-600' : 'text-emerald-600'}`}>{formatCurrency(balance)}</p></div>
          <div><p className="text-muted-foreground">Commission Agreements</p><p className="font-medium">{agreements.length} active</p></div>
        </div>
      </div>

      {/* Commission Agreements */}
      <div>
        <div className="flex items-center justify-between mb-3">
          <h3 className="text-sm font-semibold">Commission Agreements</h3>
          <Link to={`/Commission?landlord_id=${lid}`}><Button variant="outline" size="sm">Manage Agreements</Button></Link>
        </div>
        <div className="space-y-2">
          {agreements.map(a => (
            <div key={a.id} className="p-3 border border-border rounded-lg flex items-center justify-between bg-card">
              <div>
                <p className="text-sm font-medium">{a.type?.replace(/_/g,' ')} — {a.type === 'percentage' ? `${a.value}%` : formatCurrency(a.value)}</p>
                <p className="text-xs text-muted-foreground">{a.property_id ? 'This property' : 'All properties'}</p>
              </div>
              {a.type === 'one_time' && <StatusBadge color={a.one_time_applied ? 'gray' : 'green'}>{a.one_time_applied ? 'Applied' : 'Pending'}</StatusBadge>}
            </div>
          ))}
          {agreements.length === 0 && <p className="text-sm text-muted-foreground">No commission agreements</p>}
        </div>
      </div>

      {/* Recent Payouts */}
      <div>
        <div className="flex items-center justify-between mb-3">
          <h3 className="text-sm font-semibold">Recent Payouts</h3>
          <Link to={`/LandlordPayments?landlord_id=${lid}`}><Button size="sm">Make Payment</Button></Link>
        </div>
        <div className="bg-card rounded-xl border border-border overflow-hidden">
          <table className="w-full text-sm">
            <thead><tr className="bg-muted/50">
              <th className="text-left px-4 py-3 font-medium text-muted-foreground">Date</th>
              <th className="text-left px-4 py-3 font-medium text-muted-foreground">Amount</th>
              <th className="text-left px-4 py-3 font-medium text-muted-foreground">Notes</th>
            </tr></thead>
            <tbody>
              {payouts.slice(0,5).map(p => (
                <tr key={p.id} className="border-t border-border">
                  <td className="px-4 py-3 text-muted-foreground">{p.payment_date ? format(parseISO(p.payment_date), 'dd MMM yyyy') : '-'}</td>
                  <td className="px-4 py-3 font-medium text-emerald-600">{formatCurrency(p.amount)}</td>
                  <td className="px-4 py-3 text-muted-foreground">{p.notes || '-'}</td>
                </tr>
              ))}
              {payouts.length === 0 && <tr><td colSpan="3" className="px-4 py-6 text-center text-muted-foreground">No payouts yet</td></tr>}
            </tbody>
          </table>
        </div>
      </div>

      {/* CRM Log */}
      <div>
        <div className="flex items-center justify-between mb-3">
          <h3 className="text-sm font-semibold">Communication Log</h3>
          <Button size="sm" onClick={() => { setEditingCRM(null); setShowCRMForm(true); }}><Plus className="w-4 h-4 mr-1" />Add Entry</Button>
        </div>
        <div className="space-y-2">
          {crm.slice(0,10).map(e => (
            <div key={e.id} className="p-3 border border-border rounded-lg bg-card">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <StatusBadge color={typeColors[e.type]}>{e.type}</StatusBadge>
                  <span className="text-xs text-muted-foreground">{e.created_date ? format(new Date(e.created_date),'dd MMM yyyy') : ''}</span>
                </div>
                <div className="flex gap-1">
                  {e.type === 'task' && <Button variant="ghost" size="sm" onClick={() => toggleComplete(e)}><CheckCircle className={`w-4 h-4 ${e.completed ? 'text-emerald-500' : 'text-muted-foreground'}`} /></Button>}
                  <Button variant="ghost" size="sm" onClick={() => { setEditingCRM(e); setShowCRMForm(true); }}><Pencil className="w-4 h-4" /></Button>
                </div>
              </div>
              <p className="text-sm font-medium mt-1">{e.subject}</p>
              {e.content && <p className="text-xs text-muted-foreground mt-0.5">{e.content}</p>}
            </div>
          ))}
          {crm.length === 0 && <p className="text-sm text-muted-foreground">No communication entries</p>}
        </div>
      </div>

      <Dialog open={showCRMForm} onOpenChange={v => { setShowCRMForm(v); if (!v) setEditingCRM(null); }}>
        <DialogContent className="max-w-lg">
          <DialogHeader><DialogTitle>{editingCRM ? 'Edit CRM Entry' : 'Add CRM Entry'}</DialogTitle></DialogHeader>
          <CRMForm entry={editingCRM} landlordId={lid} onSubmit={handleCRMSubmit} onCancel={() => { setShowCRMForm(false); setEditingCRM(null); }} />
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React, { useMemo, useState } from 'react';
import { base44 } from '@/api/base44Client';
import { useQueryClient } from '@tanstack/react-query';
import { useRole } from '@/hooks/useRole';
import { buildLedger } from '@/lib/ledger';
import { formatCurrency } from '@/lib/computations';
import StatCard from '@/components/ui/StatCard';
import StatusBadge from '@/components/ui/StatusBadge';
import ConfirmDialog from '@/components/ui/ConfirmDialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { TrendingUp, TrendingDown, CreditCard, Banknote, Plus, Pencil, Trash2, Lock } from 'lucide-react';
import { format, parseISO } from 'date-fns';

const CASH_METHODS = new Set(['cash']);
const SOURCE_LABELS = { RentPayment: 'Rent', Commission: 'Commission', LandlordPayout: 'Payout', Expense: 'Expense', Adjustment: 'Manual' };

function CashEntryForm({ entry, propertyId, onSubmit, onCancel }) {
  const [data, setData] = useState({
    date: entry?.date || format(new Date(), 'yyyy-MM-dd'),
    description: entry?.description || '',
    amount: entry?.amount || '',
    type: entry?.type || 'Income',
    category: entry?.category || 'Cash',
    notes: entry?.notes || '',
  });

  const handleSubmit = async (e) => {
    e.preventDefault();
    await onSubmit({ ...data, amount: Number(data.amount), property_id: propertyId });
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <div className="grid grid-cols-2 gap-3">
        <div className="space-y-1"><Label>Date *</Label><Input type="date" value={data.date} onChange={e => setData(d => ({ ...d, date: e.target.value }))} required /></div>
        <div className="space-y-1">
          <Label>Type *</Label>
          <Select value={data.type} onValueChange={v => setData(d => ({ ...d, type: v }))}>
            <SelectTrigger><SelectValue /></SelectTrigger>
            <SelectContent><SelectItem value="Income">Income</SelectItem><SelectItem value="Expense">Expense</SelectItem></SelectContent>
          </Select>
        </div>
        <div className="col-span-2 space-y-1"><Label>Description *</Label><Input value={data.description} onChange={e => setData(d => ({ ...d, description: e.target.value }))} required /></div>
        <div className="space-y-1"><Label>Amount (£) *</Label><Input type="number" min="0" step="0.01" value={data.amount} onChange={e => setData(d => ({ ...d, amount: e.target.value }))} required /></div>
        <div className="space-y-1"><Label>Category</Label><Input value={data.category} onChange={e => setData(d => ({ ...d, category: e.target.value }))} /></div>
        <div className="col-span-2 space-y-1"><Label>Notes</Label><Textarea value={data.notes} onChange={e => setData(d => ({ ...d, notes: e.target.value }))} rows={2} /></div>
      </div>
      <div className="flex gap-2 justify-end">
        <Button type="button" variant="outline" onClick={onCancel}>Cancel</Button>
        <Button type="submit">{entry ? 'Update' : 'Add Entry'}</Button>
      </div>
    </form>
  );
}

export default function PropertyLedger({ property, pTenants, allTenants, landlords, properties, pPayments, allRentPayments, commissionLedger, landlordPayouts, pExpenses, adjustments, cashEntries, propertyId }) {
  const { user, isAdmin } = useRole();
  const queryClient = useQueryClient();
  const [tab, setTab] = useState('bank');
  const [showCashForm, setShowCashForm] = useState(false);
  const [editingCash, setEditingCash] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(null);
  const [lockedMsg, setLockedMsg] = useState(null);

  const allEntries = useMemo(() => buildLedger({
    rentPayments: allRentPayments, commissionLedger, landlordPayouts, expenses: pExpenses, properties, tenants: allTenants, landlords, adjustments,
  }), [allRentPayments, commissionLedger, landlordPayouts, pExpenses, properties, allTenants, landlords, adjustments]);

  // Filter to this property and exclude commission entries
  const propBankEntries = useMemo(() => {
    const entries = allEntries.filter(e =>
      e.property_id === propertyId &&
      e.ref_type !== 'Commission' &&
      !CASH_METHODS.has(e.payment_method)
    );
    let bal = 0;
    return entries.map(e => { if (e.type === 'Income') bal += e.amount; else bal -= e.amount; return { ...e, running_balance: bal }; });
  }, [allEntries, propertyId]);

  const propCashEntries = useMemo(() => {
    const cashRent = allEntries.filter(e => e.property_id === propertyId && (e.ref_type === 'RentPayment' || e.ref_type === 'LandlordPayout') && CASH_METHODS.has(e.payment_method));
    const manualCash = (cashEntries || []).filter(c => c.property_id === propertyId).map(c => ({
      id: `cash-${c.id}`, ref_id: c.id, ref_type: 'CashEntry', date: c.date, type: c.type,
      category: c.category || 'Cash', description: c.description, amount: c.amount, notes: c.notes, property_id: propertyId,
    }));
    const combined = [...cashRent, ...manualCash].sort((a, b) => new Date(a.date || 0) - new Date(b.date || 0));
    let bal = 0;
    return combined.map(e => { if (e.type === 'Income') bal += e.amount; else bal -= e.amount; return { ...e, running_balance: bal }; });
  }, [allEntries, cashEntries, propertyId]);

  const displayed = tab === 'bank' ? propBankEntries : propCashEntries;
  const income = displayed.filter(e => e.type === 'Income').reduce((s, e) => s + e.amount, 0);
  const expense = displayed.filter(e => e.type === 'Expense').reduce((s, e) => s + e.amount, 0);

  const handleCashEntryAction = (entry, action) => {
    if (entry.ref_type !== 'CashEntry') { setLockedMsg('System-generated entry. Edit source record.'); return; }
    if (action === 'edit') { const ce = cashEntries.find(c => c.id === entry.ref_id); setEditingCash(ce); setShowCashForm(true); }
    else setConfirmDelete({ ...entry, _deleteType: 'cash' });
  };

  const handleCashSubmit = async (data) => {
    const payload = { ...data, added_by: user?.email };
    if (editingCash) { await base44.entities.CashEntry.update(editingCash.id, payload); }
    else { await base44.entities.CashEntry.create(payload); }
    queryClient.invalidateQueries({ queryKey: ['cash_entries'] });
    setShowCashForm(false); setEditingCash(null);
  };

  const handleConfirmDelete = async () => {
    if (confirmDelete._deleteType === 'cash') {
      await base44.entities.CashEntry.delete(confirmDelete.ref_id);
      queryClient.invalidateQueries({ queryKey: ['cash_entries'] });
    }
    setConfirmDelete(null);
  };

  const typeColors = { Income: 'green', Expense: 'red' };

  return (
    <div>
      <div className="flex items-center justify-between mb-4">
        <div><h2 className="text-sm font-semibold">Property Ledger</h2><p className="text-xs text-muted-foreground">Cash & Bank — property specific</p></div>
        {tab === 'cash' && (
          <Button size="sm" onClick={() => { setEditingCash(null); setShowCashForm(true); }}>
            <Plus className="w-4 h-4 mr-1.5" />Add Cash Entry
          </Button>
        )}
      </div>

      <div className="flex gap-2 mb-4">
        <button onClick={() => setTab('bank')} className={`flex items-center gap-2 px-5 py-2.5 rounded-lg text-sm font-semibold border transition-colors ${tab === 'bank' ? 'bg-primary text-primary-foreground border-primary' : 'bg-card border-border hover:bg-muted'}`}>
          <CreditCard className="w-4 h-4" /> Bank Ledger
        </button>
        <button onClick={() => setTab('cash')} className={`flex items-center gap-2 px-5 py-2.5 rounded-lg text-sm font-semibold border transition-colors ${tab === 'cash' ? 'bg-primary text-primary-foreground border-primary' : 'bg-card border-border hover:bg-muted'}`}>
          <Banknote className="w-4 h-4" /> Cash Ledger
        </button>
      </div>

      <div className="grid grid-cols-3 gap-4 mb-6">
        <StatCard label={tab === 'bank' ? 'Bank Income' : 'Cash In'} value={formatCurrency(income)} icon={TrendingUp} color="success" />
        <StatCard label={tab === 'bank' ? 'Bank Expense' : 'Cash Out'} value={formatCurrency(expense)} icon={TrendingDown} color="destructive" />
        <StatCard label="Net Balance" value={formatCurrency(income - expense)} icon={tab === 'bank' ? CreditCard : Banknote} color={income - expense >= 0 ? 'success' : 'destructive'} />
      </div>

      <div className="bg-card rounded-xl border border-border overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-muted/50">
                <th className="text-left px-4 py-3 font-medium text-muted-foreground">Date</th>
                <th className="text-left px-4 py-3 font-medium text-muted-foreground">Type</th>
                <th className="text-left px-4 py-3 font-medium text-muted-foreground">Description</th>
                <th className="text-right px-4 py-3 font-medium text-muted-foreground">Income</th>
                <th className="text-right px-4 py-3 font-medium text-muted-foreground">Expense</th>
                <th className="text-right px-4 py-3 font-medium text-muted-foreground">Balance</th>
                {tab === 'cash' && isAdmin && <th className="px-4 py-3" />}
              </tr>
            </thead>
            <tbody>
              {displayed.map(e => (
                <tr key={e.id} className="border-t border-border hover:bg-muted/30 transition-colors">
                  <td className="px-4 py-3 text-muted-foreground whitespace-nowrap">{e.date ? format(parseISO(e.date), 'dd MMM yyyy') : '—'}</td>
                  <td className="px-4 py-3"><StatusBadge color={typeColors[e.type]}>{e.type}</StatusBadge></td>
                  <td className="px-4 py-3 max-w-[200px]"><span className="truncate block">{e.description}</span></td>
                  <td className="px-4 py-3 text-right text-emerald-600 font-medium">{e.type === 'Income' ? formatCurrency(e.amount) : ''}</td>
                  <td className="px-4 py-3 text-right text-red-600 font-medium">{e.type === 'Expense' ? formatCurrency(e.amount) : ''}</td>
                  <td className={`px-4 py-3 text-right font-bold ${e.running_balance >= 0 ? 'text-emerald-600' : 'text-red-600'}`}>{formatCurrency(e.running_balance)}</td>
                  {tab === 'cash' && isAdmin && (
                    <td className="px-4 py-3">
                      <div className="flex gap-1">
                        <Button variant="ghost" size="sm" onClick={() => handleCashEntryAction(e, 'edit')} title={e.ref_type === 'CashEntry' ? 'Edit' : 'Locked'}>
                          {e.ref_type === 'CashEntry' ? <Pencil className="w-3.5 h-3.5" /> : <Lock className="w-3.5 h-3.5 opacity-30" />}
                        </Button>
                        <Button variant="ghost" size="sm" className="text-destructive/70" onClick={() => handleCashEntryAction(e, 'delete')} title={e.ref_type === 'CashEntry' ? 'Delete' : 'Locked'}>
                          {e.ref_type === 'CashEntry' ? <Trash2 className="w-3.5 h-3.5" /> : <Lock className="w-3.5 h-3.5 opacity-30" />}
                        </Button>
                      </div>
                    </td>
                  )}
                </tr>
              ))}
              {displayed.length === 0 && <tr><td colSpan="7" className="px-4 py-10 text-center text-muted-foreground">No entries yet</td></tr>}
              {displayed.length > 0 && (
                <tr className="border-t-2 border-border bg-muted/50 font-bold">
                  <td colSpan="3" className="px-4 py-3 text-sm">TOTALS ({displayed.length} entries)</td>
                  <td className="px-4 py-3 text-right text-emerald-600">{formatCurrency(income)}</td>
                  <td className="px-4 py-3 text-right text-red-600">{formatCurrency(expense)}</td>
                  <td className={`px-4 py-3 text-right ${income - expense >= 0 ? 'text-emerald-600' : 'text-red-600'}`}>{formatCurrency(income - expense)}</td>
                  {tab === 'cash' && isAdmin && <td />}
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      <Dialog open={showCashForm} onOpenChange={v => { if (!v) { setShowCashForm(false); setEditingCash(null); } }}>
        <DialogContent className="max-w-md">
          <DialogHeader><DialogTitle>{editingCash ? 'Edit Cash Entry' : 'Add Cash Entry'}</DialogTitle></DialogHeader>
          <CashEntryForm entry={editingCash} propertyId={propertyId} onSubmit={handleCashSubmit} onCancel={() => { setShowCashForm(false); setEditingCash(null); }} />
        </DialogContent>
      </Dialog>

      <Dialog open={!!lockedMsg} onOpenChange={() => setLockedMsg(null)}>
        <DialogContent className="max-w-sm">
          <DialogHeader><DialogTitle>Entry Locked</DialogTitle></DialogHeader>
          <div className="flex items-start gap-3 py-2"><Lock className="w-5 h-5 text-muted-foreground mt-0.5 shrink-0" /><p className="text-sm text-muted-foreground">{lockedMsg}</p></div>
          <div className="flex justify-end"><Button onClick={() => setLockedMsg(null)}>OK</Button></div>
        </DialogContent>
      </Dialog>

      <ConfirmDialog open={!!confirmDelete} title="Delete Entry" description={`Delete "${confirmDelete?.description}"?`} onConfirm={handleConfirmDelete} onCancel={() => setConfirmDelete(null)} />
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { base44 } from '@/api/base44Client';
import { useMaintenanceRequests } from '@/hooks/useMaintenanceRequests';
import { useProperties, useTenants, useLandlords } from '@/hooks/useAllData';
import { useRole } from '@/hooks/useRole';
import { logAction } from '@/lib/audit';
import { notifyMaintenanceRaised } from '@/lib/whatsappAlerts';
import { formatCurrency } from '@/lib/computations';
import PageHeader from '@/components/ui/PageHeader';
import MaintenanceCard from '@/components/maintenance/MaintenanceCard';
import MaintenanceForm from '@/components/maintenance/MaintenanceForm';
import ConfirmDialog from '@/components/ui/ConfirmDialog';
import { StatusBadge, PriorityBadge } from '@/components/maintenance/MaintenanceStatusBadge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import StatCard from '@/components/ui/StatCard';
import { Plus, Search, Wrench, Clock, CheckCircle, AlertTriangle, PoundSterling, Building2, Users, Trash2 } from 'lucide-react';

export default function Maintenance() {
  const { user, isAdmin } = useRole();
  const queryClient = useQueryClient();
  const { data: requests } = useMaintenanceRequests();
  const { data: properties } = useProperties();
  const { data: tenants } = useTenants();
  const { data: landlords } = useLandlords();

  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [priorityFilter, setPriorityFilter] = useState('all');
  const [categoryFilter, setCategoryFilter] = useState('all');
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(null);

  const filtered = useMemo(() => {
    return requests.filter(r => {
      const prop = properties.find(p => p.id === r.property_id);
      const tenant = tenants.find(t => t.id === r.tenant_id);
      const searchMatch = !search ||
        r.title?.toLowerCase().includes(search.toLowerCase()) ||
        prop?.address?.toLowerCase().includes(search.toLowerCase()) ||
        tenant?.name?.toLowerCase().includes(search.toLowerCase()) ||
        r.contractor_name?.toLowerCase().includes(search.toLowerCase());
      const statusMatch = statusFilter === 'all' || r.status === statusFilter;
      const priorityMatch = priorityFilter === 'all' || r.priority === priorityFilter;
      const categoryMatch = categoryFilter === 'all' || r.category === categoryFilter;
      return searchMatch && statusMatch && priorityMatch && categoryMatch;
    });
  }, [requests, properties, tenants, search, statusFilter, priorityFilter, categoryFilter]);

  const syncLinkedRecords = async (reqData, existingReq = null) => {
    const cost = reqData.actual_cost || reqData.estimated_cost || 0;
    const prevCharged = existingReq?.charge_to_landlord;
    const nowCharged = reqData.charge_to_landlord;
    const prevExtraId = existingReq?.linked_extra_id;
    const dateRef = reqData.resolved_date || reqData.scheduled_date || new Date().toISOString().slice(0, 10);

    // Clean up any legacy linked_expense_id if present (no longer used)
    if (existingReq?.linked_expense_id) {
      try { await base44.entities.Expense.delete(existingReq.linked_expense_id); } catch {}
    }

    let newExtraId = prevExtraId || null;

    if (prevCharged && !nowCharged) {
      // Switching OFF — delete PaymentExtra deduction
      if (prevExtraId) { await base44.entities.PaymentExtra.delete(prevExtraId); newExtraId = null; }
    } else if (nowCharged && cost > 0) {
      // Only create/update a PaymentExtra (deduction on landlord statement)
      // Do NOT create an Expense — that would double-count on statements
      const extraPayload = {
        landlord_id: reqData.landlord_id,
        property_id: reqData.property_id,
        description: `Maintenance: ${reqData.title}`,
        amount: cost,
        date: dateRef,
        period_month: reqData.charge_period || dateRef.substring(0, 7),
        category: 'maintenance',
        notes: 'Auto-created from maintenance request',
      };
      if (prevExtraId && prevCharged) {
        try {
          await base44.entities.PaymentExtra.update(prevExtraId, extraPayload);
        } catch {
          // Record no longer exists — create a fresh one
          const extra = await base44.entities.PaymentExtra.create(extraPayload);
          newExtraId = extra.id;
        }
      } else {
        const extra = await base44.entities.PaymentExtra.create(extraPayload);
        newExtraId = extra.id;
      }
    }

    queryClient.invalidateQueries({ queryKey: ['expenses'] });
    queryClient.invalidateQueries({ queryKey: ['payment_extras'] });
    return { newExpenseId: null, newExtraId };
  };

  const handleSubmit = async (data) => {
    const { newExtraId } = await syncLinkedRecords(data, editing);
    const saveData = { ...data, linked_expense_id: null, linked_extra_id: newExtraId || null };

    if (editing) {
      await base44.entities.MaintenanceRequest.update(editing.id, saveData);
      await logAction({ user, action: 'update', entityType: 'MaintenanceRequest', entityId: editing.id, summary: `Updated maintenance request: ${data.title}`, oldValue: editing, newValue: saveData });
    } else {
      const created = await base44.entities.MaintenanceRequest.create(saveData);
      await logAction({ user, action: 'create', entityType: 'MaintenanceRequest', entityId: created.id, summary: `Created maintenance request: ${data.title}`, newValue: saveData });
      notifyMaintenanceRaised({
        request: saveData,
        property: properties.find(p => p.id === saveData.property_id),
        tenant: tenants.find(t => t.id === saveData.tenant_id),
        raisedBy: user?.full_name || user?.email,
      });
    }
    queryClient.invalidateQueries({ queryKey: ['maintenance_requests'] });
    setShowForm(false);
    setEditing(null);
  };

  const handleDelete = async (req) => {
    if (req.charge_to_landlord) {
      if (req.linked_expense_id) {
        try {
          await base44.entities.Expense.delete(req.linked_expense_id);
        } catch (err) {
          // Silently ignore if expense doesn't exist
        }
      }
      if (req.linked_extra_id) {
        try {
          await base44.entities.PaymentExtra.delete(req.linked_extra_id);
        } catch (err) {
          // Silently ignore if payment extra doesn't exist
        }
      }
      queryClient.invalidateQueries({ queryKey: ['expenses'] });
      queryClient.invalidateQueries({ queryKey: ['payment_extras'] });
    }
    await base44.entities.MaintenanceRequest.delete(req.id);
    await logAction({ user, action: 'delete', entityType: 'MaintenanceRequest', entityId: req.id, summary: `Deleted maintenance request: ${req.title}`, oldValue: req });
    queryClient.invalidateQueries({ queryKey: ['maintenance_requests'] });
    setConfirmDelete(null);
  };

  const handleEdit = (req) => {
    setEditing(req);
    setShowForm(true);
  };

  const handleClose = () => {
    setShowForm(false);
    setEditing(null);
  };

  const pending = requests.filter(r => r.status === 'pending').length;
  const inProgress = requests.filter(r => r.status === 'in_progress').length;
  const resolved = requests.filter(r => r.status === 'resolved').length;
  const emergencies = requests.filter(r => r.priority === 'emergency' && r.status !== 'resolved' && r.status !== 'cancelled').length;

  const totalCost = requests.reduce((s, r) => s + (r.actual_cost || r.estimated_cost || 0), 0);
  const chargedToLandlord = requests.filter(r => r.charge_to_landlord).reduce((s, r) => s + (r.actual_cost || r.estimated_cost || 0), 0);
  const agencyCost = requests.filter(r => !r.charge_to_landlord && r.cost_bearer !== 'tenant').reduce((s, r) => s + (r.actual_cost || r.estimated_cost || 0), 0);

  return (
    <div>
      <PageHeader
        title="Maintenance"
        description="Track and manage property maintenance requests"
        actions={
          <Button onClick={() => { setEditing(null); setShowForm(true); }}>
            <Plus className="w-4 h-4 mr-2" />New Request
          </Button>
        }
      />

      {/* Stats */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-4">
        <StatCard label="Pending" value={pending} icon={Clock} color="warning" />
        <StatCard label="In Progress" value={inProgress} icon={Wrench} color="primary" />
        <StatCard label="Resolved" value={resolved} icon={CheckCircle} color="success" />
        <StatCard label="Emergencies" value={emergencies} icon={AlertTriangle} color="destructive" />
      </div>
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-6">
        <StatCard label="Total Maintenance Cost" value={formatCurrency(totalCost)} icon={PoundSterling} />
        <StatCard label="Charged to Landlords" value={formatCurrency(chargedToLandlord)} icon={Building2} color="warning" trend="Deducted from payouts" />
        <StatCard label="Agency-Covered Cost" value={formatCurrency(agencyCost)} icon={Users} color="primary" trend="Not on landlord statement" />
      </div>

      {/* Filters */}
      <div className="flex flex-wrap gap-3 mb-5">
        <div className="relative flex-1 min-w-[200px]">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input className="pl-9" placeholder="Search requests..." value={search} onChange={e => setSearch(e.target.value)} />
        </div>
        <Select value={statusFilter} onValueChange={setStatusFilter}>
          <SelectTrigger className="w-36"><SelectValue placeholder="Status" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Statuses</SelectItem>
            <SelectItem value="pending">Pending</SelectItem>
            <SelectItem value="in_progress">In Progress</SelectItem>
            <SelectItem value="resolved">Resolved</SelectItem>
            <SelectItem value="cancelled">Cancelled</SelectItem>
          </SelectContent>
        </Select>
        <Select value={priorityFilter} onValueChange={setPriorityFilter}>
          <SelectTrigger className="w-36"><SelectValue placeholder="Priority" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Priorities</SelectItem>
            <SelectItem value="emergency">Emergency</SelectItem>
            <SelectItem value="high">High</SelectItem>
            <SelectItem value="medium">Medium</SelectItem>
            <SelectItem value="low">Low</SelectItem>
          </SelectContent>
        </Select>
        <Select value={categoryFilter} onValueChange={setCategoryFilter}>
          <SelectTrigger className="w-40"><SelectValue placeholder="Category" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Categories</SelectItem>
            {['plumbing','electrical','heating','structural','appliances','pest_control','cleaning','other'].map(c => (
              <SelectItem key={c} value={c}>{c.replace('_', ' ')}</SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      {/* Cards Grid */}
      {filtered.length === 0 ? (
        <div className="text-center py-16 text-muted-foreground">
          <Wrench className="w-10 h-10 mx-auto mb-3 opacity-30" />
          <p className="text-sm">No maintenance requests found</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
          {filtered.map(req => (
            <div key={req.id} className="relative">
              <MaintenanceCard
                request={req}
                property={properties.find(p => p.id === req.property_id)}
                tenant={tenants.find(t => t.id === req.tenant_id)}
                onEdit={handleEdit}
              />
              {isAdmin && (
                <button
                  onClick={() => setConfirmDelete(req)}
                  className="absolute top-3 right-3 p-1.5 rounded-md text-muted-foreground hover:text-destructive hover:bg-destructive/10 transition-colors"
                  title="Delete request"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              )}
            </div>
          ))}
          </div>
          )}

          {/* Dialog */}
      <Dialog open={showForm} onOpenChange={handleClose}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{editing ? 'Manage Request' : 'New Maintenance Request'}</DialogTitle>
          </DialogHeader>
          <MaintenanceForm
            request={editing}
            properties={properties}
            tenants={tenants}
            landlords={landlords}
            onSubmit={handleSubmit}
            onCancel={handleClose}
            isAdminForm={true}
          />
        </DialogContent>
      </Dialog>

      <ConfirmDialog
        open={!!confirmDelete}
        title="Delete Maintenance Request"
        description={`Delete "${confirmDelete?.title}"? This is permanent.`}
        onConfirm={() => handleDelete(confirmDelete)}
        onCancel={() => setConfirmDelete(null)}
      />
    </div>

  );
}

