  };

  return (
    <div>
      <div className="flex items-center justify-between mb-4">
        <p className="text-sm text-muted-foreground">{pRequests.filter(r=>r.status!=='resolved'&&r.status!=='cancelled').length} open request(s)</p>
        <Button onClick={() => { setEditing(null); setShowForm(true); }}><Plus className="w-4 h-4 mr-2" />New Request</Button>
