    </div>
  );
}

import React, { useMemo } from 'react';
import { formatCurrency, calculateArrears, getPropertyCertStatus } from '@/lib/computations';
import { buildPropertyMonthlyStatements } from '@/lib/propertyStatements';
import { usePropertyDocuments, useRentHistoryAll } from '@/hooks/useAllData';
import StatCard from '@/components/ui/StatCard';
import PropertyTasksPanel from '@/components/property/PropertyTasksPanel';
import StatusBadge from '@/components/ui/StatusBadge';
import { Banknote, UserCheck, AlertTriangle, Wrench, ShieldCheck, Wallet } from 'lucide-react';
import { format, parseISO } from 'date-fns';

const CERTS = [
  { catKey: 'gas',        label: 'Gas' },
  { catKey: 'electrical', label: 'Electrical' },
  { catKey: 'epc',        label: 'EPC' },
  { catKey: 'license',    label: 'License' },
];

export default function PropertyOverview({ property, landlord, landlords = [], pTenants, pPayments, pLedger, pPayouts, pMaintenance, pExpenses, pExtras, pCommissionAgreements = [], pRentHistory = [] }) {
  const { data: allDocuments } = usePropertyDocuments();
  const { data: rentHistory = [] } = useRentHistoryAll();

  // Financial summary uses the SAME authoritative monthly-statement builder as
  // the Landlord Invoices / Payments tabs, so the figures always agree:
  //   Net Payable = expected rent − commission (from agreement, per period)
  //                 − landlord-approved expenses − extras − maintenance
  // Only agency-expenses are NOT deducted (agency bears them), and commission
  // is computed from the agreement for every period — not the sparse ledger.
  const statements = useMemo(() => buildPropertyMonthlyStatements({
    property, landlord, landlords,
    pPayments, pLedger, pPayouts, pExpenses, pExtras, pMaintenance, pTenants,
    pCommissionAgreements, pRentHistory: pRentHistory.length ? pRentHistory : rentHistory,
  }), [property, landlord, landlords, pPayments, pLedger, pPayouts, pExpenses, pExtras, pMaintenance, pTenants, pCommissionAgreements, pRentHistory, rentHistory]);

  const totals = useMemo(() => statements.reduce((acc, s) => {
    acc.collected += s.rent_collected || 0;
    acc.netPayable += s.invoice_net_payable || 0;
    acc.paid += s.paid_this_period || 0;
    return acc;
  }, { collected: 0, netPayable: 0, paid: 0 }), [statements]);

  const totalRent = totals.collected;
  const totalPayable = totals.netPayable;
  const totalPaid = totals.paid;
  const outstanding = totalPayable - totalPaid;

  const activeTenants = pTenants.filter(t => t.status === 'active');
  const tenantsInArrears = pTenants.filter(t => {
    if (t.status === 'ended') return false;
    return calculateArrears(t, pPayments.filter(p => p.tenant_id === t.id), rentHistory.filter(r => r.tenant_id === t.id)) > 0;
  });

  const openMaintenance = pMaintenance.filter(r => r.status === 'pending' || r.status === 'in_progress');

  // Cert status for this property — derived from documents
  const certStatus = getPropertyCertStatus(property.id, allDocuments);

  return (
    <div className="space-y-6">
      {/* Financial Stats */}
      <div>
        <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-3">Financial Summary</p>
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
          <StatCard label="Monthly Rent" value={formatCurrency(property.monthly_rent)} icon={Banknote} />
          <StatCard label="Total Collected" value={formatCurrency(totalRent)} icon={Banknote} color="success" />
          <StatCard label="Net Payable" value={formatCurrency(totalPayable)} icon={Wallet} color="primary" />
          <StatCard label="Outstanding" value={formatCurrency(outstanding)} icon={Wallet} color={outstanding > 0 ? 'warning' : 'success'} />
        </div>
      </div>

      {/* People Stats */}
      <div>
        <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-3">Occupancy</p>
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
          <StatCard label="Active Tenants" value={activeTenants.length} icon={UserCheck} color="success" />
          <StatCard label="Tenants in Arrears" value={tenantsInArrears.length} icon={AlertTriangle} color={tenantsInArrears.length > 0 ? 'destructive' : 'success'} />
          <StatCard label="Open Maintenance" value={openMaintenance.length} icon={Wrench} color={openMaintenance.length > 0 ? 'warning' : 'success'} />
          <StatCard label="Paid to Landlord" value={formatCurrency(totalPaid)} icon={Wallet} color="success" />
        </div>
      </div>

      {/* Landlord Info */}
      {landlord && (
        <div className="bg-card border border-border rounded-xl p-5">
          <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-3">Landlord</p>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
            <div><p className="text-muted-foreground text-xs">Name</p><p className="font-semibold">{landlord.name}</p></div>
            <div><p className="text-muted-foreground text-xs">Email</p><p className="font-medium">{landlord.email || '—'}</p></div>
            <div><p className="text-muted-foreground text-xs">Phone</p><p className="font-medium">{landlord.phone || '—'}</p></div>
            <div><p className="text-muted-foreground text-xs">Commission</p><p className="font-medium">{landlord.commission_rate || property.commission_rate || 10}%</p></div>
          </div>
        </div>
      )}

      {/* Certificates — derived from documents */}
      <div>
        <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-3">Certificates & Compliance</p>
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
          {CERTS.map(c => {
            const s = certStatus[c.catKey];
            const expiry = s.expiry;
            const stat = s.status; // expired | expiring | valid | missing

            const cardBorder =
              stat === 'expired'  ? 'border-rose-200 bg-rose-50/50' :
              stat === 'expiring' ? 'border-amber-200 bg-amber-50/50' :
              'border-border bg-card';

            const iconColor =
              stat === 'expired'  ? 'text-rose-500' :
              stat === 'expiring' ? 'text-amber-500' :
              stat === 'valid'    ? 'text-emerald-500' :
              'text-muted-foreground';

            const badgeColor =
              stat === 'expired'  ? 'red' :
              stat === 'expiring' ? 'yellow' :
              stat === 'valid'    ? 'green' :
              'gray';

            const badgeLabel =
              stat === 'expired'  ? 'Expired' :
              stat === 'expiring' ? 'Expiring' :
              stat === 'valid'    ? 'Valid' :
              'Missing';

            return (
              <div key={c.catKey} className={`p-4 rounded-xl border ${cardBorder}`}>
                <div className="flex items-center gap-2 mb-1">
                  <ShieldCheck className={`w-4 h-4 ${iconColor}`} />
                  <p className="text-sm font-medium">{c.label}</p>
                </div>
                <p className="text-xs text-muted-foreground mb-1">
                  {expiry ? format(parseISO(expiry), 'dd MMM yyyy') : 'Not set'}
                </p>
                <StatusBadge color={badgeColor}>{badgeLabel}</StatusBadge>
              </div>
