      </div>

      {/* Active Tenants Quick View */}
      {activeTenants.length > 0 && (
        <div className="bg-card border border-border rounded-xl overflow-hidden">
          <div className="px-5 py-4 border-b border-border">
            <p className="text-sm font-semibold">Active Tenants</p>
          </div>
          <table className="w-full text-sm">
            <thead><tr className="bg-muted/50">
              <th className="text-left px-5 py-2.5 font-medium text-muted-foreground text-xs">Name</th>
              <th className="text-left px-5 py-2.5 font-medium text-muted-foreground text-xs">Rent</th>
              <th className="text-left px-5 py-2.5 font-medium text-muted-foreground text-xs">Arrears</th>
            </tr></thead>
            <tbody>
              {activeTenants.map(t => {
                const arr = calculateArrears(t, pPayments.filter(p => p.tenant_id === t.id), rentHistory.filter(r => r.tenant_id === t.id));
                return (
                  <tr key={t.id} className="border-t border-border">
                    <td className="px-5 py-2.5 font-medium">{t.name}</td>
                    <td className="px-5 py-2.5">{formatCurrency(t.monthly_rent)}</td>
                    <td className="px-5 py-2.5">{arr > 0 ? <span className="text-rose-600 font-semibold">{formatCurrency(arr)}</span> : <StatusBadge color="green">Clear</StatusBadge>}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      <div className="mt-6">
        <PropertyTasksPanel property={property} />
      </div>
    </div>
  );
}

