function formatPeriodLabel(yyyyMM) {
  try { return format(parseISO(`${yyyyMM}-01`), 'MMMM yyyy'); } catch { return yyyyMM; }
}

const MONTHS = [
  { value: '01', label: 'January' },  { value: '02', label: 'February' },
  { value: '03', label: 'March' },    { value: '04', label: 'April' },
  { value: '05', label: 'May' },      { value: '06', label: 'June' },
  { value: '07', label: 'July' },     { value: '08', label: 'August' },
  { value: '09', label: 'September' },{ value: '10', label: 'October' },
  { value: '11', label: 'November' }, { value: '12', label: 'December' },
];
const YEARS = Array.from({ length: 15 }, (_, i) => String(new Date().getFullYear() - 5 + i));

function PeriodPicker({ value, onChange }) {
  const initParts = (value || format(new Date(), 'yyyy-MM')).split('-');
  const [month, setMonth] = React.useState(initParts[1] || format(new Date(), 'MM'));
  const [year,  setYear]  = React.useState(initParts[0] || String(new Date().getFullYear()));
  const handleMonth = (m) => { setMonth(m); onChange(`${year}-${m}`); };
  const handleYear  = (y) => { setYear(y);  onChange(`${y}-${month}`); };
  return (
    <div className="flex gap-2">
      <Select value={month} onValueChange={handleMonth}>
        <SelectTrigger className="flex-1"><SelectValue placeholder="Month" /></SelectTrigger>
        <SelectContent>
          {MONTHS.map(m => <SelectItem key={m.value} value={m.value}>{m.label}</SelectItem>)}
        </SelectContent>
      </Select>
      <Select value={year} onValueChange={handleYear}>
        <SelectTrigger className="w-28"><SelectValue placeholder="Year" /></SelectTrigger>
        <SelectContent>
          {YEARS.map(y => <SelectItem key={y} value={y}>{y}</SelectItem>)}
        </SelectContent>
      </Select>
    </div>
  );
}

function RentForm({ property, pTenants, onSubmit, onCancel, initialMethod }) {
  const [submitting, setSubmitting] = useState(false);
  const [data, setData] = useState({
    tenant_id: '',
    amount: '',
    payment_date: format(new Date(), 'yyyy-MM-dd'),
    period_month: format(new Date(), 'yyyy-MM'),
    method: initialMethod || 'bank_transfer',
    reference: '',
    notes: initialMethod === 'deposit' ? 'Rent settled from deposit' : '',
  });

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (submitting) return;
    setSubmitting(true);
    try { await onSubmit({ ...data, property_id: property.id, landlord_id: property.landlord_id, amount: Number(data.amount) }); } finally { setSubmitting(false); }
  };

  // For a deposit payment the tenancy has usually already ended, so include
  // ended tenants (marked as such). Normal rent payments stay active-only.
  const isDeposit = initialMethod === 'deposit';
  const activeTenants = isDeposit ? pTenants : pTenants.filter(t => t.status !== 'ended');
  const selectedTenant = pTenants.find(t => t.id === data.tenant_id);

  const handleTenantChange = (v) => {
    const t = pTenants.find(t => t.id === v);
    setData(d => ({ ...d, tenant_id: v, amount: t?.monthly_rent || d.amount }));
  };

  const isOverpayment = selectedTenant && Number(data.amount) > (selectedTenant.monthly_rent || 0);
  const isPartial = selectedTenant && Number(data.amount) > 0 && Number(data.amount) < (selectedTenant.monthly_rent || 0);

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      {/* Info banner */}
      <div className="rounded-lg bg-blue-50 border border-blue-200 px-4 py-3 text-xs text-blue-700 flex gap-2">
        <Info className="w-4 h-4 shrink-0 mt-0.5" />
        <span><strong>Payment Date</strong> = when money was received. <strong>Rent Period</strong> = which month this payment covers. These can be different.</span>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div className="space-y-1">
          <Label>Tenant *</Label>
          <Select value={data.tenant_id} onValueChange={handleTenantChange}>
            <SelectTrigger><SelectValue placeholder="Select tenant" /></SelectTrigger>
            <SelectContent>{activeTenants.map(t => <SelectItem key={t.id} value={t.id}>{t.name} — {formatCurrency(t.monthly_rent)}{t.status === 'ended' ? ' (ended)' : ''}</SelectItem>)}</SelectContent>
          </Select>
        </div>

        <div className="space-y-1">
          <Label>Amount (£) *</Label>
          <Input type="number" min="0" step="0.01" value={data.amount} onChange={e => setData({ ...data, amount: e.target.value })} required />
          {isPartial && <p className="text-xs text-amber-600">⚠ Partial payment — remaining stays as arrears</p>}
          {isOverpayment && <p className="text-xs text-blue-600">ℹ Overpayment — excess carried to next period automatically</p>}
        </div>

        <div className="space-y-1">
          <Label>Payment Date * <span className="font-normal text-muted-foreground">(when received)</span></Label>
          <Input type="date" value={data.payment_date} onChange={e => setData({ ...data, payment_date: e.target.value })} required />
        </div>

        <div className="space-y-1">
          <Label>Apply to Rent Period * <span className="font-normal text-muted-foreground">(which month)</span></Label>
          <PeriodPicker value={data.period_month} onChange={v => setData({ ...data, period_month: v })} />
        </div>

        <div className="space-y-1">
          <Label>Method</Label>
          <Select value={data.method} onValueChange={v => setData({ ...data, method: v, received_in_bank_id: v === 'cash' ? '' : data.received_in_bank_id })}>
            <SelectTrigger><SelectValue /></SelectTrigger>
            <SelectContent>
              {['bank_transfer', 'cash', 'cheque', 'standing_order', 'deposit', 'other'].map(m => (
                <SelectItem key={m} value={m}>{m.replace(/_/g, ' ')}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {data.method !== 'cash' && (
          <div className="space-y-1">
            <Label>Received In Account</Label>
            <Select value={data.received_in_bank_name || ''} onValueChange={v => setData({ ...data, received_in_bank_name: v })}>
              <SelectTrigger><SelectValue placeholder="Select account" /></SelectTrigger>
              <SelectContent>
                <SelectItem value="HSBC">HSBC</SelectItem>
                <SelectItem value="Santander">Santander</SelectItem>
                <SelectItem value="Lloyds">Lloyds</SelectItem>
                <SelectItem value="Barclays">Barclays</SelectItem>
                <SelectItem value="NatWest">NatWest</SelectItem>
                <SelectItem value="Halifax">Halifax</SelectItem>
                <SelectItem value="Metro Bank">Metro Bank</SelectItem>
                <SelectItem value="Monzo">Monzo</SelectItem>
                <SelectItem value="Starling">Starling</SelectItem>
                <SelectItem value="Other">Other</SelectItem>
              </SelectContent>
            </Select>
          </div>
        )}

        <div className="space-y-1">
          <Label>{data.method === 'cash' ? 'Cash received from (name) *' : 'Reference'}</Label>
          <Input value={data.reference} onChange={e => setData({ ...data, reference: e.target.value })}
            placeholder={data.method === 'cash' ? 'Who handed over the cash?' : ''} required={data.method === 'cash'} />
        </div>
      </div>

      <div className="space-y-1">
        <Label>Notes</Label>
        <Textarea value={data.notes} onChange={e => setData({ ...data, notes: e.target.value })} rows={2} />
      </div>

      <div className="flex gap-2 justify-end">
        <Button type="button" variant="outline" onClick={onCancel}>Cancel</Button>
        <Button type="submit" disabled={!data.tenant_id || !data.amount || submitting || (data.method === 'cash' && !String(data.reference || '').trim())}>{submitting ? 'Saving...' : 'Record Payment'}</Button>
      </div>
    </form>
  );
}

export default function PropertyRentPayments({ property, pTenants, pPayments, pLedger, pCommissionAgreements }) {
  const { user, isAdmin } = useRole();
  const queryClient = useQueryClient();
  const [showForm, setShowForm] = useState(false);
  const [formMethod, setFormMethod] = useState('bank_transfer');
  const [confirmDelete, setConfirmDelete] = useState(null);
  const [depositTenant, setDepositTenant] = useState(null);
  const [showTenantPicker, setShowTenantPicker] = useState(false);

  const activeTenants = pTenants.filter(t => t.status !== 'ended');

  const handleDepositClick = () => {
    if (activeTenants.length === 1) {
      setDepositTenant(activeTenants[0]);
    } else {
      setShowTenantPicker(true);
    }
  };

  const totalRent = pPayments.reduce((s, p) => s + (p.amount || 0), 0);
  const cashRent = pPayments.filter(p => p.method === 'cash').reduce((s, p) => s + (p.amount || 0), 0);
  const bankRent = pPayments.filter(p => p.method !== 'cash').reduce((s, p) => s + (p.amount || 0), 0);

  const handleSubmit = async (data) => {
    const created = await base44.entities.RentPayment.create(data);

    const agreement = (pCommissionAgreements || []).find(a => a.property_id === property.id)
      || (pCommissionAgreements || []).find(a => !a.property_id);

    if (agreement) {
      const existingEntry = (pLedger || []).find(
        e => e.property_id === property.id && e.period_month === data.period_month
      );
      if (!existingEntry) {
        let commissionAmount = 0;
        let commissionRate = agreement.value;
        if (agreement.type === 'percentage') {
          commissionAmount = (data.amount * agreement.value) / 100;
        } else if (agreement.type === 'fixed_monthly') {
          commissionAmount = agreement.value;
        } else if (agreement.type === 'one_time' && !agreement.one_time_applied) {
          commissionAmount = agreement.value;
          await base44.entities.CommissionAgreement.update(agreement.id, { one_time_applied: true });
        }
        if (commissionAmount > 0) {
          await base44.entities.CommissionLedger.create({
            property_id: property.id,
            landlord_id: property.landlord_id,
            rent_payment_id: created.id,
            period_month: data.period_month,
            rent_amount: data.amount,
            commission_rate: commissionRate,
            commission_type: agreement.type,
            commission_amount: commissionAmount,
            landlord_share: data.amount - commissionAmount,
            date: data.payment_date,
          });
        }
      }
    }

    await logAction({ user, action: 'create', entityType: 'RentPayment', entityId: created.id, summary: `Recorded rent payment £${data.amount} for ${property.address} (period: ${data.period_month})`, newValue: data });
    queryClient.invalidateQueries({ queryKey: ['rent_payments'] });
    queryClient.invalidateQueries({ queryKey: ['commission_ledger'] });
    queryClient.invalidateQueries({ queryKey: ['commission_agreements'] });
    setShowForm(false);
  };

  const handleDelete = async (payment) => {
    const periodPayments = (pPayments || []).filter(
      p => p.property_id === payment.property_id && p.period_month === payment.period_month
    );
    const isLastForPeriod = periodPayments.length === 1;
    if (isLastForPeriod) {
      const periodCommission = (pLedger || []).find(
        e => e.property_id === payment.property_id && e.period_month === payment.period_month
      );
      if (periodCommission) await base44.entities.CommissionLedger.delete(periodCommission.id);
    }
    await base44.entities.RentPayment.delete(payment.id);
    await logAction({ user, action: 'delete', entityType: 'RentPayment', entityId: payment.id, summary: `Deleted rent payment of £${payment.amount}${isLastForPeriod ? ' — commission reversed' : ''}`, oldValue: payment });
    queryClient.invalidateQueries({ queryKey: ['rent_payments'] });
    queryClient.invalidateQueries({ queryKey: ['commission_ledger'] });
    setConfirmDelete(null);
  };

  // Group payments by period for display
  const sortedPayments = [...pPayments].sort((a, b) => {
    const pa = a.period_month || '';
    const pb = b.period_month || '';
    return pb.localeCompare(pa);
  });

  return (
    <div>
      <div className="flex items-center justify-between mb-4">
        <div>
          <h2 className="text-sm font-semibold">Rent & Payments</h2>
          <p className="text-xs text-muted-foreground">{pPayments.length} payments recorded</p>
        </div>
        <div className="flex gap-2">
          <Button size="sm" variant="outline" onClick={handleDepositClick}>
            <ShieldCheck className="w-4 h-4 mr-1.5" />Deposit
          </Button>
          <Button size="sm" variant="outline" onClick={() => { setFormMethod('deposit'); setShowForm(true); }} title="Record a month's rent paid from the held deposit">
            <Wallet className="w-4 h-4 mr-1.5" />Pay from Deposit
          </Button>
          <Button size="sm" onClick={() => { setFormMethod('bank_transfer'); setShowForm(true); }}>
            <Plus className="w-4 h-4 mr-1.5" />Record Rent
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-3 gap-4 mb-6">
        <StatCard label="Total Collected" value={formatCurrency(totalRent)} icon={Banknote} color="success" />
        <StatCard label="Bank Payments" value={formatCurrency(bankRent)} icon={Banknote} color="primary" />
        <StatCard label="Cash Payments" value={formatCurrency(cashRent)} icon={Banknote} color="warning" />
      </div>

      <div className="bg-card rounded-xl border border-border overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-muted/50">
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Tenant</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Amount</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Rent Period</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Payment Date</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Method</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Account</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Reference</th>
                {isAdmin && <th className="px-5 py-3" />}
              </tr>
            </thead>
            <tbody>
              {sortedPayments.map(p => {
                const tenant = pTenants.find(t => t.id === p.tenant_id);
                return (
                  <tr key={p.id} className="border-t border-border hover:bg-muted/30 transition-colors">
                    <td className="px-5 py-3 font-medium">{tenant?.name || 'Unknown'}</td>
                    <td className="px-5 py-3 font-semibold text-emerald-700">{formatCurrency(p.amount)}</td>
                    <td className="px-5 py-3">
                      <span className="font-medium">{p.period_month ? formatPeriodLabel(p.period_month) : '—'}</span>
                    </td>
                    <td className="px-5 py-3 text-muted-foreground">{p.payment_date ? format(parseISO(p.payment_date), 'dd MMM yyyy') : '—'}</td>
                    <td className="px-5 py-3"><StatusBadge color={p.method === 'cash' ? 'yellow' : 'blue'}>{p.method?.replace(/_/g, ' ')}</StatusBadge></td>
                    <td className="px-5 py-3 text-xs text-muted-foreground">{p.method === 'cash' ? '💵 Cash' : p.received_in_bank_name || '—'}</td>
                    <td className="px-5 py-3 text-muted-foreground">{p.reference || '—'}</td>
                    {isAdmin && (
                      <td className="px-5 py-3">
                        <Button variant="ghost" size="sm" className="text-destructive hover:text-destructive" onClick={() => setConfirmDelete(p)}>
                          <Trash2 className="w-4 h-4" />
                        </Button>
                      </td>
                    )}
                  </tr>
                );
              })}
              {pPayments.length === 0 && <tr><td colSpan="7" className="px-5 py-10 text-center text-muted-foreground">No rent payments yet</td></tr>}
            </tbody>
          </table>
        </div>
      </div>

      <Dialog open={showForm} onOpenChange={setShowForm}>
        <DialogContent className="max-w-lg">
          <DialogHeader><DialogTitle>Record Rent Payment</DialogTitle></DialogHeader>
          <RentForm key={formMethod} property={property} pTenants={pTenants} onSubmit={handleSubmit} onCancel={() => setShowForm(false)} initialMethod={formMethod} />
        </DialogContent>
      </Dialog>

      {/* Deposit Modal */}
      {depositTenant && <DepositModal open={!!depositTenant} onClose={() => setDepositTenant(null)} tenant={depositTenant} />}

      {/* Tenant picker when multiple active tenants */}
      <Dialog open={showTenantPicker} onOpenChange={setShowTenantPicker}>
        <DialogContent className="max-w-sm">
          <DialogHeader><DialogTitle>Select Tenant</DialogTitle></DialogHeader>
          <div className="space-y-2">
            {activeTenants.map(t => (
              <button key={t.id} onClick={() => { setShowTenantPicker(false); setDepositTenant(t); }}
                className="w-full text-left px-4 py-3 rounded-lg border border-border hover:bg-muted/50 transition-colors text-sm font-medium">
                {t.name}
              </button>
            ))}
          </div>
        </DialogContent>
      </Dialog>

      <ConfirmDialog
        open={!!confirmDelete}
        title="Delete Payment"
        description={`Delete rent payment of ${formatCurrency(confirmDelete?.amount)} for ${confirmDelete?.period_month ? formatPeriodLabel(confirmDelete.period_month) : ''}?`}
        onConfirm={() => handleDelete(confirmDelete)}
        onCancel={() => setConfirmDelete(null)}
      />
    </div>
  );
}

import React, { useState } from 'react';
import { base44 } from '@/api/base44Client';
import { useTenants, useRentPayments, useCommissionAgreements, useCommissionLedger } from '@/hooks/useAllData';
import { useQueryClient } from '@tanstack/react-query';
import { useRole } from '@/hooks/useRole';
import { logAction } from '@/lib/audit';
import RentPaymentForm from '@/components/forms/RentPaymentForm';
import ConfirmDialog from '@/components/ui/ConfirmDialog';
import StatusBadge from '@/components/ui/StatusBadge';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Plus, Trash2 } from 'lucide-react';
import { formatCurrency, calculateCommission } from '@/lib/computations';
import { format, parseISO } from 'date-fns';

export default function PropertyRentTab({ property }) {
  const { user, isAdmin } = useRole();
  const { data: tenants } = useTenants();
  const { data: rentPayments } = useRentPayments();
  const { data: agreements } = useCommissionAgreements();
  const { data: ledger } = useCommissionLedger();
  const queryClient = useQueryClient();
  const [showForm, setShowForm] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(null);

  const pTenants = tenants.filter(t => t.property_id === property.id);
  const pPayments = rentPayments.filter(p => p.property_id === property.id);
  const totalCollected = pPayments.reduce((s, p) => s + (p.amount || 0), 0);

  const handleSubmit = async (data) => {
    const paymentData = { ...data, property_id: property.id, landlord_id: property.landlord_id };
    const payment = await base44.entities.RentPayment.create(paymentData);

    const freshLedger = await base44.entities.CommissionLedger.filter({ property_id: property.id, period_month: data.period_month });
    if (freshLedger.length === 0) {
      const propAgreement = agreements.find(a => a.property_id === property.id);
      const landlordAgreement = agreements.find(a => a.landlord_id === property.landlord_id && !a.property_id);
      const agreement = propAgreement || landlordAgreement;
      const tenant = tenants.find(t => t.id === data.tenant_id);
      const fullMonthlyRent = tenant?.monthly_rent || data.amount;

      if (agreement) {
        const { commission, landlordShare } = calculateCommission(fullMonthlyRent, agreement);
        await base44.entities.CommissionLedger.create({
          rent_payment_id: payment.id, landlord_id: property.landlord_id, property_id: property.id,
          period_month: data.period_month, rent_amount: fullMonthlyRent, commission_amount: commission,
          landlord_share: landlordShare, commission_type: agreement.type, commission_rate: agreement.value, date: data.payment_date,
        });
        if (agreement.type === 'one_time' && !agreement.one_time_applied) {
          await base44.entities.CommissionAgreement.update(agreement.id, { one_time_applied: true });
          queryClient.invalidateQueries({ queryKey: ['commission_agreements'] });
        }
      } else {
        await base44.entities.CommissionLedger.create({
          rent_payment_id: payment.id, landlord_id: property.landlord_id, property_id: property.id,
          period_month: data.period_month, rent_amount: fullMonthlyRent, commission_amount: 0,
          landlord_share: fullMonthlyRent, commission_type: 'percentage', commission_rate: 0, date: data.payment_date,
        });
      }
    }

    await logAction({ user, action: 'create', entityType: 'RentPayment', entityId: payment.id, summary: `Recorded rent £${data.amount} for ${data.period_month}`, newValue: data });
    queryClient.invalidateQueries({ queryKey: ['rent_payments'] });
    queryClient.invalidateQueries({ queryKey: ['commission_ledger'] });
    setShowForm(false);
  };

  const handleDelete = async (rp) => {
    if (!isAdmin) return;
    const periodCommission = ledger.find(e => e.property_id === rp.property_id && e.period_month === rp.period_month);
    if (periodCommission) await base44.entities.CommissionLedger.delete(periodCommission.id);
    await base44.entities.RentPayment.delete(rp.id);
    await logAction({ user, action: 'delete', entityType: 'RentPayment', entityId: rp.id, summary: `Deleted rent payment ${formatCurrency(rp.amount)}`, oldValue: rp });
    queryClient.invalidateQueries({ queryKey: ['rent_payments'] });
    queryClient.invalidateQueries({ queryKey: ['commission_ledger'] });
    setConfirmDelete(null);
  };

  return (
    <div>
      <div className="flex items-center justify-between mb-4">
        <p className="text-sm text-muted-foreground">Total collected: <span className="font-semibold text-foreground">{formatCurrency(totalCollected)}</span></p>
        <Button onClick={() => setShowForm(true)}><Plus className="w-4 h-4 mr-2" />Record Payment</Button>
      </div>

      <div className="bg-card rounded-xl border border-border overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-muted/50">
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Tenant</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Amount</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Date</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Period</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Method</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Commission</th>
                {isAdmin && <th className="px-5 py-3"></th>}
              </tr>
            </thead>
            <tbody>
              {pPayments.map(rp => {
                const entry = ledger.find(e => e.rent_payment_id === rp.id);
                return (
                  <tr key={rp.id} className="border-t border-border hover:bg-muted/30 transition-colors">
                    <td className="px-5 py-3 font-medium">{tenants.find(t=>t.id===rp.tenant_id)?.name||'Unknown'}</td>
                    <td className="px-5 py-3 font-medium">{formatCurrency(rp.amount)}</td>
                    <td className="px-5 py-3 text-muted-foreground">{rp.payment_date ? format(parseISO(rp.payment_date),'dd MMM yyyy') : '-'}</td>
                    <td className="px-5 py-3">{rp.period_month}</td>
                    <td className="px-5 py-3"><StatusBadge color="blue">{rp.method?.replace(/_/g,' ')}</StatusBadge></td>
                    <td className="px-5 py-3">{entry ? <span className="text-primary font-medium">{formatCurrency(entry.commission_amount)}</span> : <span className="text-muted-foreground">—</span>}</td>
                    {isAdmin && <td className="px-5 py-3"><Button variant="ghost" size="sm" className="text-destructive hover:text-destructive" onClick={() => setConfirmDelete(rp)}><Trash2 className="w-4 h-4" /></Button></td>}
                  </tr>
                );
              })}
              {pPayments.length === 0 && <tr><td colSpan={isAdmin?7:6} className="px-5 py-8 text-center text-muted-foreground">No rent payments recorded</td></tr>}
            </tbody>
          </table>
        </div>
      </div>

      <Dialog open={showForm} onOpenChange={setShowForm}>
        <DialogContent className="max-w-lg">
          <DialogHeader><DialogTitle>Record Rent Payment</DialogTitle></DialogHeader>
          <RentPaymentForm
            tenants={pTenants}
            properties={[property]}
            onSubmit={handleSubmit}
            onCancel={() => setShowForm(false)}
          />
        </DialogContent>
      </Dialog>

      <ConfirmDialog
        open={!!confirmDelete}
        title="Delete Rent Payment"
        description={`Delete this payment of ${formatCurrency(confirmDelete?.amount)}? Commission entry will also be reversed.`}
        onConfirm={() => handleDelete(confirmDelete)}
        onCancel={() => setConfirmDelete(null)}
      />
    </div>
  );
}

import React, { useState } from 'react';
import { base44 } from '@/api/base44Client';
import { useQueryClient } from '@tanstack/react-query';
import { useTasks, useTeamMembers } from '@/hooks/useTasks';
import { useRole } from '@/hooks/useRole';
import { logAction } from '@/lib/audit';
import { Link } from 'react-router-dom';
import StatusBadge from '@/components/ui/StatusBadge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { ListChecks, Plus, ChevronRight } from 'lucide-react';
import { format, parseISO } from 'date-fns';
import { TASK_TYPE_KEYS, stepsForType, typeLabel, statusColor, firstStatus, isDoneStatus } from '@/lib/taskConfig';

// Compact tasks panel shown on a property's Overview tab. Lists this property's
// tasks, lets you add one quickly, and advance a task's status inline (each
// change is recorded to the activity log with who did it).
export default function PropertyTasksPanel({ property }) {
  const { user } = useRole();
  const queryClient = useQueryClient();
  const { data: allTasks } = useTasks();
  const { data: team } = useTeamMembers();
  const [adding, setAdding] = useState(false);
  const [title, setTitle] = useState('');
  const [type, setType] = useState('general');
  const [assignee, setAssignee] = useState('');
  const [showDone, setShowDone] = useState(false);

  const members = (team || []).filter(m => m.active !== false);
  const byName = user?.full_name || user?.name || (members[0]?.name || '');

  const tasks = (allTasks || [])
    .filter(t => t.property_id === property.id)
    .filter(t => showDone || !isDoneStatus(t.type, t.status))
    .sort((a, b) => (a.due_date || '9999').localeCompare(b.due_date || '9999'));

  const refresh = () => queryClient.invalidateQueries({ queryKey: ['tasks'] });

  const add = async () => {
    if (!title.trim()) return;
    const created = await base44.entities.Task.create({
      title: title.trim(), type, status: firstStatus(type),
      assigned_to: assignee, priority: 'normal', property_id: property.id,
      landlord_id: property.landlord_id || '', activity_log: [],
    });
    await logAction({ user, action: 'create', entityType: 'Task', entityId: created?.id, summary: `Created task "${title.trim()}" on ${property.address}` });
    setTitle(''); setAssignee(''); setType('general'); setAdding(false);
    refresh();
  };

  const advance = async (t) => {
    const steps = stepsForType(t.type);
    const idx = steps.indexOf(t.status);
    const next = steps[Math.min(idx + 1, steps.length - 1)];
    if (next === t.status) return;
    const entry = { at: new Date().toISOString(), by: byName || 'Unknown', from_status: t.status, to_status: next, note: '' };
    const payload = { status: next, activity_log: [...(t.activity_log || []), entry] };
    if (isDoneStatus(t.type, next)) payload.completed_at = new Date().toISOString();
    await base44.entities.Task.update(t.id, payload);
    await logAction({ user, action: 'update', entityType: 'Task', entityId: t.id, summary: `Task "${t.title}": ${t.status} → ${next}` });
    refresh();
  };

  return (
    <div className="bg-card border border-border rounded-xl p-5">
      <div className="flex items-center justify-between mb-3">
        <h3 className="text-sm font-semibold flex items-center gap-2"><ListChecks className="w-4 h-4 text-rose-500" />Tasks</h3>
        <div className="flex items-center gap-2">
          <button onClick={() => setShowDone(v => !v)} className="text-[11px] text-muted-foreground hover:text-foreground">{showDone ? 'Hide done' : 'Show done'}</button>
          <Button size="sm" variant="outline" onClick={() => setAdding(v => !v)}><Plus className="w-3.5 h-3.5 mr-1" />Add</Button>
        </div>
      </div>

      {adding && (
        <div className="mb-3 space-y-2 border border-border rounded-lg p-3 bg-muted/30">
          <Input placeholder="Task title…" value={title} onChange={e => setTitle(e.target.value)} autoFocus />
          <div className="grid grid-cols-2 gap-2">
            <Select value={type} onValueChange={setType}>
              <SelectTrigger className="h-8 text-xs"><SelectValue /></SelectTrigger>
              <SelectContent>{TASK_TYPE_KEYS.map(k => <SelectItem key={k} value={k}>{typeLabel(k)}</SelectItem>)}</SelectContent>
            </Select>
            <Select value={assignee || '__none__'} onValueChange={v => setAssignee(v === '__none__' ? '' : v)}>
              <SelectTrigger className="h-8 text-xs"><SelectValue placeholder="Assign…" /></SelectTrigger>
              <SelectContent>
                <SelectItem value="__none__">Unassigned</SelectItem>
                {members.map(m => <SelectItem key={m.id} value={m.name}>{m.name}</SelectItem>)}
              </SelectContent>
            </Select>
          </div>
          <div className="flex justify-end gap-2">
            <Button size="sm" variant="ghost" onClick={() => setAdding(false)}>Cancel</Button>
            <Button size="sm" onClick={add} disabled={!title.trim()}>Add task</Button>
          </div>
        </div>
      )}

      {tasks.length === 0 ? (
        <p className="text-xs text-muted-foreground py-2">No tasks for this property.</p>
      ) : (
        <div className="space-y-2">
          {tasks.map(t => {
            const done = isDoneStatus(t.type, t.status);
            return (
              <div key={t.id} className="flex items-center justify-between gap-2 border border-border rounded-lg px-3 py-2">
                <div className="min-w-0">
                  <p className="text-sm font-medium truncate">{t.title}</p>
                  <div className="flex items-center gap-1.5 mt-0.5">
                    <StatusBadge color="blue">{typeLabel(t.type)}</StatusBadge>
                    <StatusBadge color={statusColor(t.type, t.status)}>{t.status || firstStatus(t.type)}</StatusBadge>
                    {t.assigned_to && <span className="text-[11px] text-muted-foreground">{t.assigned_to}</span>}
                    {t.due_date && <span className="text-[11px] text-muted-foreground">· due {format(parseISO(t.due_date), 'd MMM')}</span>}
                  </div>
                </div>
                {!done && (
                  <Button size="sm" variant="outline" onClick={() => advance(t)} title="Advance to next step" className="shrink-0">
                    Next <ChevronRight className="w-3.5 h-3.5 ml-0.5" />
                  </Button>
                )}
              </div>
            );
          })}
        </div>
      )}

      <div className="mt-3 text-right">
        <Link to="/Tasks" className="text-[11px] text-primary hover:underline">Open full task board →</Link>
      </div>
    </div>
  );
}

import React, { useMemo, useState } from 'react';
import { buildTenantInvoices } from '@/lib/invoices';
import { useTenantCarriedBalances } from '@/hooks/useTenantCarriedBalances';
import { useTenantInvoiceCharges } from '@/hooks/useTenantInvoiceCharges';
import { useRentHistoryAll } from '@/hooks/useAllData';
import AddTenantChargeDialog from '@/components/property/AddTenantChargeDialog';
import { base44 } from '@/api/base44Client';
import { useQueryClient } from '@tanstack/react-query';
import { downloadTenantInvoicePDF, getTenantInvoicePDFBlob } from '@/lib/pdfExport';
import { formatCurrency } from '@/lib/computations';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent } from '@/components/ui/dialog';
import { Eye, Download, FileText, Mail, Plus, Trash2 } from 'lucide-react';
import { format, parseISO } from 'date-fns';
import EmailComposer from '@/components/email/EmailComposer';
import { businessConfig as biz } from '@/lib/businessConfig';

export default function PropertyTenantInvoices({ property, landlords, properties, pTenants, allTenants, pPayments, allRentPayments, propertyId }) {
  const [selectedInvoice, setSelectedInvoice] = useState(null);
  const [emailInvoice, setEmailInvoice] = useState(null);
  const [chargeFor, setChargeFor] = useState(null);
  const { data: carriedBalances } = useTenantCarriedBalances();
  const { data: manualCharges } = useTenantInvoiceCharges();
  const { data: rentHistoryAll = [] } = useRentHistoryAll();
  const qc = useQueryClient();
  const deleteCharge = async (id) => {
    if (!window.confirm('Remove this charge from the invoice?')) return;
    await base44.entities.TenantInvoiceCharge.delete(id);
    qc.invalidateQueries({ queryKey: ['tenant_invoice_charges'] });
  };

  const invoices = useMemo(() => {
    return buildTenantInvoices({ tenants: allTenants, properties, landlords, rentPayments: allRentPayments, carriedBalances, manualCharges, rentHistoryAll })
      .filter(inv => inv.property_id === propertyId)
      .sort((a, b) => b.period_month.localeCompare(a.period_month));
  }, [allTenants, properties, landlords, allRentPayments, carriedBalances, manualCharges, rentHistoryAll, propertyId]);

  const buildEmailBody = (inv) => `Dear ${inv.tenant_name},

Please find below your rent invoice for ${inv.cycle_label || inv.period_month}.

Property: ${inv.property_address}
Period: ${inv.cycle_label || inv.period_month}
Rent Due: ${formatCurrency(inv.rent_amount)}${inv.discount > 0 ? '\nDiscount: -' + formatCurrency(inv.discount) + (inv.discount_reason ? ' (' + inv.discount_reason + ')' : '') : ''}${inv.arrears > 0 ? '\nArrears: ' + formatCurrency(inv.arrears) : ''}
Total Due: ${formatCurrency(inv.total_due)}
Balance Due: ${formatCurrency(inv.balance_due)}

Please ensure your payment is made on time. If you have already paid, please disregard this message.

If you have any questions, please do not hesitate to contact us.

Kind regards,
${biz.name}
${biz.email}`;

  const statusStyle = (status) => {
    if (status === 'Paid') return 'bg-emerald-50 text-emerald-700 border-emerald-200';
    if (status === 'Partial') return 'bg-amber-50 text-amber-700 border-amber-200';
    if (status === 'Upcoming') return 'bg-blue-50 text-blue-700 border-blue-200';
    return 'bg-red-50 text-red-700 border-red-200';
  };

  return (
    <div>
      <div className="flex items-center justify-between mb-4">
        <div>
          <h2 className="text-sm font-semibold">Tenant Invoices</h2>
          <p className="text-xs text-muted-foreground">Auto-generated from lease cycles</p>
        </div>
      </div>

      <div className="bg-card rounded-xl border border-border overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-muted/50">
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Invoice #</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Tenant</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Period</th>
                <th className="text-right px-5 py-3 font-medium text-muted-foreground">Rent Due</th>
                <th className="text-right px-5 py-3 font-medium text-muted-foreground">Paid</th>
                <th className="text-right px-5 py-3 font-medium text-muted-foreground">Balance</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Status</th>
                <th className="px-5 py-3" />
              </tr>
            </thead>
            <tbody>
              {invoices.map(inv => (
                <React.Fragment key={inv.key}>
                <tr className="border-t border-border hover:bg-muted/30 transition-colors">
                  <td className="px-5 py-3 text-xs text-muted-foreground font-mono">{inv.invoice_number}</td>
                  <td className="px-5 py-3 font-medium">{inv.tenant_name}</td>
                  <td className="px-5 py-3 text-xs text-muted-foreground">{inv.cycle_label || inv.period_month}</td>
                  <td className="px-5 py-3 text-right">{formatCurrency(inv.rent_amount)}</td>
                  <td className="px-5 py-3 text-right text-emerald-600">{inv.total_paid > 0 ? formatCurrency(inv.total_paid) : '—'}</td>
                  <td className="px-5 py-3 text-right font-semibold">
                    {inv.balance_due > 0
                      ? <span className="text-red-600">{formatCurrency(inv.balance_due)}</span>
                      : inv.overpaid > 0
                        ? <span className="text-emerald-600" title="Overpaid — refund due to tenant">- {formatCurrency(inv.overpaid)}</span>
                        : <span className="text-emerald-600">£0.00</span>}
                  </td>
                  <td className="px-5 py-3">
                    <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium border ${statusStyle(inv.status)}`}>{inv.status}</span>
                  </td>
                  <td className="px-5 py-3">
                    <div className="flex gap-1">
                      {!inv.is_upcoming && (<Button variant="ghost" size="sm" title="Add a charge to this invoice" onClick={() => setChargeFor(inv)}><Plus className="w-4 h-4" /></Button>)}
                      <Button variant="ghost" size="sm" onClick={() => setSelectedInvoice(inv)}><Eye className="w-4 h-4" /></Button>
                      <Button variant="ghost" size="sm" onClick={() => downloadTenantInvoicePDF(inv)}><Download className="w-4 h-4" /></Button>
                      <Button variant="ghost" size="sm" disabled={!inv.tenant_email} title={inv.tenant_email ? 'Send email' : 'No email on record'} onClick={() => setEmailInvoice(inv)}><Mail className="w-4 h-4" /></Button>
                    </div>
                  </td>
                </tr>
                {(inv.manual_charges || []).map(c => (
                  <tr key={c.id} className="bg-amber-50/40 text-xs">
                    <td className="px-5 py-1.5 text-muted-foreground">↳ charge</td>
                    <td className="px-5 py-1.5 text-muted-foreground" colSpan="2">{c.description}{c.category ? <span className="ml-1.5 capitalize text-[10px] px-1.5 py-0.5 rounded-full bg-amber-100 text-amber-700">{c.category.replace('_',' ')}</span> : null}</td>
                    <td className="px-5 py-1.5 text-right font-medium text-amber-700">+ {formatCurrency(c.amount)}</td>
                    <td colSpan="3" />
                    <td className="px-5 py-1.5"><button onClick={() => deleteCharge(c.id)} title="Remove charge" className="text-muted-foreground hover:text-red-600"><Trash2 className="w-3.5 h-3.5" /></button></td>
                  </tr>
                ))}
                </React.Fragment>
              ))}
              {invoices.length === 0 && <tr><td colSpan="8" className="px-5 py-10 text-center text-muted-foreground">No invoices yet</td></tr>}
            </tbody>
          </table>
        </div>
      </div>

      <Dialog open={!!selectedInvoice} onOpenChange={v => { if (!v) setSelectedInvoice(null); }}>
        {selectedInvoice && (
          <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
            <div className="space-y-4 py-2">
              <div className="flex items-center gap-3">
                <FileText className="w-5 h-5 text-primary" />
                <h2 className="text-lg font-semibold">{selectedInvoice.invoice_number}</h2>
                <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium border ${statusStyle(selectedInvoice.status)}`}>{selectedInvoice.status}</span>
              </div>
              <div className="grid grid-cols-2 gap-4 text-sm">
                <div><p className="text-muted-foreground">Tenant</p><p className="font-medium">{selectedInvoice.tenant_name}</p></div>
                <div><p className="text-muted-foreground">Period</p><p className="font-medium">{selectedInvoice.cycle_label || selectedInvoice.period_month}</p></div>
                <div><p className="text-muted-foreground">Rent Due</p><p className="font-medium">{formatCurrency(selectedInvoice.rent_amount)}</p></div>
                <div><p className="text-muted-foreground">Paid</p><p className="font-medium text-emerald-600">{formatCurrency(selectedInvoice.total_paid)}</p></div>
              </div>
              {selectedInvoice.discount > 0 && (
                <div className="flex justify-between items-start rounded-lg bg-emerald-50 border border-emerald-200 px-4 py-2">
                  <div>
                    <p className="text-sm font-medium text-emerald-800">Discount applied</p>
                    {selectedInvoice.discount_reason && <p className="text-xs text-emerald-700 italic">{selectedInvoice.discount_reason}</p>}
                  </div>
                  <span className="text-sm font-semibold text-emerald-700">- {formatCurrency(selectedInvoice.discount)}</span>
                </div>
              )}
              {selectedInvoice.payments?.length > 0 && (
                <div>
                  <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-2">Payments</p>
                  <div className="rounded-lg border border-border overflow-hidden">
                    <table className="w-full text-sm">
                      <thead className="bg-muted/50">
                        <tr>
                          <th className="text-left px-4 py-2 font-medium text-muted-foreground">Date</th>
                          <th className="text-left px-4 py-2 font-medium text-muted-foreground">Method</th>
                          <th className="text-right px-4 py-2 font-medium text-muted-foreground">Amount</th>
                        </tr>
                      </thead>
                      <tbody>
                        {selectedInvoice.payments.map(p => (
                          <tr key={p.id} className="border-t border-border">
                            <td className="px-4 py-2 text-muted-foreground">{p.payment_date ? format(parseISO(p.payment_date), 'dd MMM yyyy') : '—'}</td>
                            <td className="px-4 py-2">{p.method?.replace(/_/g, ' ') || '—'}</td>
                            <td className="px-4 py-2 text-right text-emerald-600 font-medium">{formatCurrency(p.amount)}</td>
                          </tr>
