              )}
              <div className="flex justify-between border-t pt-3">
                <span className="font-semibold">{selectedInvoice.overpaid > 0 ? 'Credit (refund due)' : 'Balance Due'}</span>
                <span className={`font-bold text-lg ${selectedInvoice.overpaid > 0 ? 'text-emerald-600' : selectedInvoice.balance_due > 0 ? 'text-red-600' : 'text-emerald-600'}`}>
                  {selectedInvoice.overpaid > 0 ? `- ${formatCurrency(selectedInvoice.overpaid)}` : formatCurrency(selectedInvoice.balance_due)}
