              </div>
              <div className="flex gap-2 justify-end">
                <Button variant="outline" onClick={() => setSelectedInvoice(null)}>Close</Button>
                <Button onClick={() => downloadTenantInvoicePDF(selectedInvoice)}><Download className="w-4 h-4 mr-2" />Download PDF</Button>
              </div>
            </div>
          </DialogContent>
        )}
      </Dialog>

      {emailInvoice && (
        <EmailComposer
          open={!!emailInvoice}
          onClose={() => setEmailInvoice(null)}
          to={emailInvoice.tenant_email}
          toName={emailInvoice.tenant_name}
          subject={`Rent Invoice – ${emailInvoice.property_address?.split(',')[0]} – ${emailInvoice.cycle_label || emailInvoice.period_month}`}
          body={buildEmailBody(emailInvoice)}
          type="tenant_invoice"
          referenceId={emailInvoice.key}
          attachmentBlobFn={() => getTenantInvoicePDFBlob(emailInvoice)}
          attachmentName={`${emailInvoice.invoice_number}-Invoice.pdf`}
        />
      )}
      {chargeFor && (
        <AddTenantChargeDialog
          open={!!chargeFor}
          onClose={() => setChargeFor(null)}
          tenantId={chargeFor.tenant_id}
          propertyId={chargeFor.property_id || propertyId}
