          monthLabel={chargeFor.cycle_label || chargeFor.period_month}
        />
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { base44 } from '@/api/base44Client';
import { useQueryClient } from '@tanstack/react-query';
import { useRole } from '@/hooks/useRole';
import { logAction } from '@/lib/audit';
import { formatCurrency, calculateArrears } from '@/lib/computations';
import { useRentHistoryAll } from '@/hooks/useAllData';
import StatusBadge from '@/components/ui/StatusBadge';
import TenantForm from '@/components/forms/TenantForm';
import { withDerivedStatus } from '@/lib/tenantStatus';
import ConfirmDialog from '@/components/ui/ConfirmDialog';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Plus, Eye, Pencil, Trash2, FileDown, Mail, Phone, TrendingUp } from 'lucide-react';
import RentIncreaseDialog from '@/components/tenants/RentIncreaseDialog';
import { Link } from 'react-router-dom';

export default function PropertyTenants({ property, properties, landlord, pTenants, pPayments }) {
  const { user, isAdmin } = useRole();
  const { data: rentHistoryAll = [] } = useRentHistoryAll();
  const queryClient = useQueryClient();
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(null);
  const [generatingFor, setGeneratingFor] = useState(null);
  const [rentIncreaseFor, setRentIncreaseFor] = useState(null);

  const handleDownloadAgreement = async (tenant) => {
    if (generatingFor) return;
    setGeneratingFor(tenant.id);
    try {
      const response = await base44.functions.invoke('generateTenancyAgreement', {
        tenant_name: tenant.name,
        tenant_email: tenant.email || '',
        tenant_phone: tenant.phone || '',
        property_address: property?.address || '',
        landlord_name: landlord?.name || '',
        monthly_rent: tenant.monthly_rent,
        deposit: tenant.deposit || 0,
        lease_start: tenant.lease_start || '',
        payment_day: property?.payment_day || 1,
        unit_description: tenant.unit_description || '',
      });

      const binary = atob(response.data.base64);
      const bytes = new Uint8Array(binary.length);
      for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
      const blob = new Blob([bytes], {
        type: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `Tenancy_Agreement_${(tenant.name || 'Tenant').replace(/[^a-zA-Z0-9 ]/g, '').trim().replace(/ /g, '_')}.docx`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    } catch (err) {
      console.error('Failed to generate agreement:', err);
      alert('Failed to generate agreement. Please try again.');
    } finally {
      setGeneratingFor(null);
    }
  };

  const handleSubmit = async (data) => {
    // Always link to this property, and sync status from lease_end
    const payload = withDerivedStatus({ ...data, property_id: property.id });
    if (editing) {
      await base44.entities.Tenant.update(editing.id, payload);
      await logAction({ user, action: 'update', entityType: 'Tenant', entityId: editing.id, summary: `Updated tenant ${data.name}`, oldValue: editing, newValue: payload });
    } else {
      const created = await base44.entities.Tenant.create(payload);
      await logAction({ user, action: 'create', entityType: 'Tenant', entityId: created.id, summary: `Created tenant ${data.name}`, newValue: payload });
    }
    queryClient.invalidateQueries({ queryKey: ['tenants'] });
    setShowForm(false);
    setEditing(null);
  };

  const handleDelete = async (tenant) => {
    await base44.entities.Tenant.delete(tenant.id);
    await logAction({ user, action: 'delete', entityType: 'Tenant', entityId: tenant.id, summary: `Deleted tenant ${tenant.name}`, oldValue: tenant });
    queryClient.invalidateQueries({ queryKey: ['tenants'] });
    setConfirmDelete(null);
  };

  const statusColors = { active: 'green', notice: 'yellow', ended: 'gray' };

  return (
    <div>
      <div className="flex items-center justify-between mb-4">
        <div>
          <h2 className="text-sm font-semibold">Tenants</h2>
          <p className="text-xs text-muted-foreground">{pTenants.filter(t => t.status === 'active').length} active</p>
        </div>
        <Button size="sm" onClick={() => { setEditing(null); setShowForm(true); }}>
          <Plus className="w-4 h-4 mr-1.5" />Add Tenant
        </Button>
      </div>

      <div className="bg-card rounded-xl border border-border overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-muted/50">
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Name</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Email</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Phone</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Rent</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Lease Start</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Arrears</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Status</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Actions</th>
              </tr>
            </thead>
            <tbody>
              {pTenants.map(t => {
                // For ended tenants with no lease_end set, cap at end of last month
                // so the current in-progress month isn't counted as arrears
                const lastMonth = new Date();
                lastMonth.setDate(0); // last day of previous month
                const tForArrears = (t.status === 'ended' && !t.lease_end)
                  ? { ...t, lease_end: lastMonth.toISOString().slice(0, 10) }
                  : t;
                const arr = calculateArrears(tForArrears, pPayments.filter(p => p.tenant_id === t.id), rentHistoryAll.filter(r => r.tenant_id === t.id));
                return (
                  <tr key={t.id} className="border-t border-border hover:bg-muted/30 transition-colors">
                    <td className="px-5 py-3 font-medium">{t.name}</td>
                    <td className="px-5 py-3 text-muted-foreground">
                      {t.email ? (
                        <a href={`mailto:${t.email}`} className="inline-flex items-center gap-1 hover:text-primary">
                          <Mail className="w-3.5 h-3.5" />
                          {t.email}
                        </a>
                      ) : '—'}
                    </td>
                    <td className="px-5 py-3 text-muted-foreground">
                      {t.phone ? (
                        <a href={`tel:${t.phone}`} className="inline-flex items-center gap-1 hover:text-primary">
                          <Phone className="w-3.5 h-3.5" />
                          {t.phone}
                        </a>
                      ) : '—'}
                    </td>
                    <td className="px-5 py-3">{formatCurrency(t.monthly_rent)}</td>
                    <td className="px-5 py-3 text-muted-foreground">{t.lease_start || '—'}</td>
                    <td className="px-5 py-3">
                      {arr > 0 ? <span className="text-red-600 font-semibold">{formatCurrency(arr)}</span> : <StatusBadge color="green">Clear</StatusBadge>}
                    </td>
                    <td className="px-5 py-3"><StatusBadge color={statusColors[t.status]}>{t.status}</StatusBadge></td>
                    <td className="px-5 py-3">
                      <div className="flex gap-1">
                        <Link to={`/TenantDetail?id=${t.id}`}><Button variant="ghost" size="sm"><Eye className="w-4 h-4" /></Button></Link>
                        <Button variant="ghost" size="sm" onClick={() => { setEditing(t); setShowForm(true); }}><Pencil className="w-4 h-4" /></Button>
                        <Button variant="ghost" size="sm" title="Download Agreement" disabled={!!generatingFor} onClick={() => handleDownloadAgreement(t)}>
                          <FileDown className="w-4 h-4" />
                        </Button>
                        <Button variant="ghost" size="sm" title="Rent increase" onClick={() => setRentIncreaseFor(t)}>
                          <TrendingUp className="w-4 h-4" />
                        </Button>
                        {isAdmin && <Button variant="ghost" size="sm" className="text-destructive hover:text-destructive" onClick={() => setConfirmDelete(t)}><Trash2 className="w-4 h-4" /></Button>}
                      </div>
                    </td>
                  </tr>
                );
              })}
              {pTenants.length === 0 && <tr><td colSpan="8" className="px-5 py-10 text-center text-muted-foreground">No tenants for this property yet</td></tr>}
            </tbody>
          </table>
        </div>
      </div>

      <Dialog open={showForm} onOpenChange={setShowForm}>
        <DialogContent className="max-w-2xl">
          <DialogHeader><DialogTitle>{editing ? 'Edit Tenant' : 'Add Tenant to Property'}</DialogTitle></DialogHeader>
          <TenantForm
            tenant={editing ? editing : { property_id: property.id }}
            properties={properties}
            allTenants={pTenants}
            onSubmit={handleSubmit}
            onCancel={() => { setShowForm(false); setEditing(null); }}
          />
        </DialogContent>
      </Dialog>

      <ConfirmDialog
        open={!!confirmDelete}
        title="Remove Tenant"
        description={`Mark "${confirmDelete?.name}" as ended?`}
        onConfirm={() => handleDelete(confirmDelete)}
        onCancel={() => setConfirmDelete(null)}
      />

      <RentIncreaseDialog
        tenant={rentIncreaseFor}
        propertyId={property.id}
        user={user}
        onClose={() => setRentIncreaseFor(null)}
        onSaved={async () => {
          setRentIncreaseFor(null);
          await queryClient.invalidateQueries({ queryKey: ['tenants'] });
          await queryClient.invalidateQueries({ queryKey: ['rent_history_all'] });
          await queryClient.invalidateQueries({ queryKey: ['rent_payments'] });
        }}
      />

    </div>
  );
}

import React, { useState } from 'react';
import { base44 } from '@/api/base44Client';
import { useTenants, useRentPayments, useRentHistoryAll } from '@/hooks/useAllData';
import { useQueryClient } from '@tanstack/react-query';
import { useRole } from '@/hooks/useRole';
import { logAction } from '@/lib/audit';
import StatusBadge from '@/components/ui/StatusBadge';
import TenantForm from '@/components/forms/TenantForm';
import ConfirmDialog from '@/components/ui/ConfirmDialog';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Plus, Eye, Pencil, Trash2 } from 'lucide-react';
import { Link } from 'react-router-dom';
import { formatCurrency, calculateArrears } from '@/lib/computations';
import { format, parseISO } from 'date-fns';

export default function PropertyTenantsTab({ property }) {
  const { user, isAdmin } = useRole();
  const { data: tenants } = useTenants();
  const { data: rentPayments } = useRentPayments();
  const { data: rentHistory = [] } = useRentHistoryAll();
  const queryClient = useQueryClient();
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(null);

  const pTenants = tenants.filter(t => t.property_id === property.id);
  const statusColors = { active: 'green', notice: 'yellow', ended: 'gray' };

  const handleSubmit = async (data) => {
    const tenantData = { ...data, property_id: property.id };
    if (editing) {
      await base44.entities.Tenant.update(editing.id, tenantData);
      await logAction({ user, action: 'update', entityType: 'Tenant', entityId: editing.id, summary: `Updated tenant ${data.name}`, oldValue: editing, newValue: tenantData });
    } else {
      const created = await base44.entities.Tenant.create(tenantData);
      await logAction({ user, action: 'create', entityType: 'Tenant', entityId: created.id, summary: `Created tenant ${data.name}`, newValue: tenantData });
    }
    queryClient.invalidateQueries({ queryKey: ['tenants'] });
    setShowForm(false); setEditing(null);
  };

  const handleDelete = async (tenant) => {
    await base44.entities.Tenant.delete(tenant.id);
    await logAction({ user, action: 'delete', entityType: 'Tenant', entityId: tenant.id, summary: `Deleted tenant ${tenant.name}`, oldValue: tenant });
    queryClient.invalidateQueries({ queryKey: ['tenants'] });
    setConfirmDelete(null);
  };

  return (
    <div>
      <div className="flex items-center justify-between mb-4">
        <p className="text-sm text-muted-foreground">{pTenants.filter(t=>t.status==='active').length} active tenant(s)</p>
        <Button onClick={() => { setEditing(null); setShowForm(true); }}><Plus className="w-4 h-4 mr-2" />Add Tenant</Button>
      </div>

      <div className="bg-card rounded-xl border border-border overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-muted/50">
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Name</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Contact</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Lease</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Rent</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Arrears</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Status</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Actions</th>
              </tr>
            </thead>
            <tbody>
              {pTenants.map(t => {
                const tPayments = rentPayments.filter(p => p.tenant_id === t.id);
                const arrears = calculateArrears(t, tPayments, rentHistory.filter(r => r.tenant_id === t.id));
                return (
                  <tr key={t.id} className="border-t border-border hover:bg-muted/30 transition-colors">
                    <td className="px-5 py-3 font-medium">{t.name}</td>
                    <td className="px-5 py-3 text-muted-foreground text-xs">
                      {t.email && <p>{t.email}</p>}
                      {t.phone && <p>{t.phone}</p>}
                    </td>
                    <td className="px-5 py-3 text-xs text-muted-foreground">
                      <p>{t.lease_start ? format(parseISO(t.lease_start), 'dd MMM yy') : '-'}</p>
                      <p>{t.lease_end ? format(parseISO(t.lease_end), 'dd MMM yy') : 'Ongoing'}</p>
                    </td>
                    <td className="px-5 py-3">{formatCurrency(t.monthly_rent)}</td>
                    <td className="px-5 py-3">{arrears > 0 ? <span className="text-red-600 font-medium">{formatCurrency(arrears)}</span> : <StatusBadge color="green">Clear</StatusBadge>}</td>
                    <td className="px-5 py-3"><StatusBadge color={statusColors[t.status]}>{t.status}</StatusBadge></td>
                    <td className="px-5 py-3">
                      <div className="flex items-center gap-1">
                        <Link to={`/TenantDetail?id=${t.id}`}><Button variant="ghost" size="sm"><Eye className="w-4 h-4" /></Button></Link>
                        <Button variant="ghost" size="sm" onClick={() => { setEditing(t); setShowForm(true); }}><Pencil className="w-4 h-4" /></Button>
                        {isAdmin && <Button variant="ghost" size="sm" className="text-destructive hover:text-destructive" onClick={() => setConfirmDelete(t)}><Trash2 className="w-4 h-4" /></Button>}
                      </div>
                    </td>
                  </tr>
