import { CheckCircle2, Loader2 } from 'lucide-react';

export default function InquiryForm({ propertyId, propertyTitle, defaultType = 'info' }) {
  const [form, setForm] = useState({
    name: '', email: '', phone: '', message: '',
    inquiry_type: defaultType, preferred_date: '',
  });
  const [submitting, setSubmitting] = useState(false);
  const [done, setDone] = useState(false);
  const [error, setError] = useState('');

  const update = (k, v) => setForm(prev => ({ ...prev, [k]: v }));

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.name || !form.email || !form.message) {
      setError('Please fill in name, email, and message.');
      return;
    }
    setSubmitting(true);
    setError('');
    try {
    const payload = {
      name: form.name,
      email: form.email,
      phone: form.phone || undefined,
      message: form.message,
      inquiry_type: form.inquiry_type,
      preferred_date: form.preferred_date || undefined,
      property_id: propertyId || undefined,
    };
    await base44.functions.invoke('submitInquiry', payload);
    setDone(true);
    } catch (err) {
      setError('Failed to send message. Please try again.');
    } finally {
      setSubmitting(false);
    }
  };

  if (done) {
    return (
      <div className="text-center py-6">
        <div className="w-12 h-12 rounded-full bg-emerald-50 text-emerald-600 flex items-center justify-center mx-auto mb-3">
          <CheckCircle2 className="w-6 h-6" />
        </div>
        <h3 className="font-semibold mb-1">Message sent!</h3>
        <p className="text-sm text-muted-foreground">Thanks {form.name.split(' ')[0]} — we'll be in touch shortly.</p>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-3">
      {propertyTitle && (
        <div className="text-xs text-muted-foreground bg-muted/60 rounded px-3 py-2 mb-1">
          Enquiry about: <span className="font-medium text-foreground">{propertyTitle}</span>
        </div>
      )}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
        <div>
          <Label className="text-xs">Name *</Label>
          <Input value={form.name} onChange={e => update('name', e.target.value)} required />
        </div>
        <div>
          <Label className="text-xs">Email *</Label>
          <Input type="email" value={form.email} onChange={e => update('email', e.target.value)} required />
        </div>
      </div>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
        <div>
          <Label className="text-xs">Phone</Label>
          <Input value={form.phone} onChange={e => update('phone', e.target.value)} />
        </div>
        <div>
          <Label className="text-xs">Enquiry type</Label>
          <Select value={form.inquiry_type} onValueChange={v => update('inquiry_type', v)}>
            <SelectTrigger><SelectValue /></SelectTrigger>
            <SelectContent>
              <SelectItem value="info">More information</SelectItem>
              <SelectItem value="viewing">Book a viewing</SelectItem>
              <SelectItem value="offer">Make an offer</SelectItem>
              <SelectItem value="general">General enquiry</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>
      {form.inquiry_type === 'viewing' && (
        <div>
          <Label className="text-xs">Preferred viewing date</Label>
          <Input type="date" value={form.preferred_date} onChange={e => update('preferred_date', e.target.value)} />
        </div>
      )}
      <div>
        <Label className="text-xs">Message *</Label>
        <Textarea rows={4} value={form.message} onChange={e => update('message', e.target.value)} required placeholder="Tell us a bit about what you're looking for..." />
      </div>
      {error && <p className="text-xs text-destructive">{error}</p>}
      <Button type="submit" className="w-full" disabled={submitting}>
        {submitting ? <><Loader2 className="w-4 h-4 mr-2 animate-spin" />Sending...</> : 'Send message'}
      </Button>
    </form>
  );
}

