import React, { useState, useRef, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";

const SIGNATURE_FONTS = [
  { name: "Cursive", style: "italic 32px 'Brush Script MT', cursive" },
  { name: "Serif", style: "italic 28px Georgia, serif" },
  { name: "Elegant", style: "italic 30px 'Palatino Linotype', serif" },
];

export default function SignatureModal({ open, onClose, onSave, type = "signature" }) {
  const canvasRef = useRef(null);
  const [tab, setTab] = useState("draw");
  const [typedName, setTypedName] = useState("");
  const [selectedFont, setSelectedFont] = useState(0);
  const [isDrawing, setIsDrawing] = useState(false);
  const [hasDrawn, setHasDrawn] = useState(false);

  useEffect(() => {
    if (open && canvasRef.current) {
      const canvas = canvasRef.current;
      const ctx = canvas.getContext("2d");
      canvas.width = canvas.offsetWidth * 2;
      canvas.height = canvas.offsetHeight * 2;
      ctx.scale(2, 2);
      ctx.lineWidth = 2;
      ctx.lineCap = "round";
      ctx.strokeStyle = "#1e293b";
      setHasDrawn(false);
    }
  }, [open, tab]);

  const getPos = (e) => {
    const rect = canvasRef.current.getBoundingClientRect();
    const touch = e.touches ? e.touches[0] : e;
    return { x: touch.clientX - rect.left, y: touch.clientY - rect.top };
  };

  const startDraw = (e) => {
    e.preventDefault();
    setIsDrawing(true);
    setHasDrawn(true);
    const ctx = canvasRef.current.getContext("2d");
    const pos = getPos(e);
    ctx.beginPath();
    ctx.moveTo(pos.x, pos.y);
  };

  const draw = (e) => {
    if (!isDrawing) return;
    e.preventDefault();
    const ctx = canvasRef.current.getContext("2d");
    const pos = getPos(e);
    ctx.lineTo(pos.x, pos.y);
    ctx.stroke();
  };

  const stopDraw = () => setIsDrawing(false);

  const clearCanvas = () => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    setHasDrawn(false);
  };

  const handleSave = () => {
    if (tab === "draw" && canvasRef.current) {
      onSave(canvasRef.current.toDataURL("image/png"));
    } else if (tab === "type" && typedName) {
      const canvas = document.createElement("canvas");
      canvas.width = 400;
      canvas.height = 100;
      const ctx = canvas.getContext("2d");
      ctx.font = SIGNATURE_FONTS[selectedFont].style;
      ctx.fillStyle = "#1e293b";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(typedName, 200, 50);
      onSave(canvas.toDataURL("image/png"));
    }
    onClose();
  };

  const canSave = (tab === "draw" && hasDrawn) || (tab === "type" && typedName.trim());

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>
            {type === "initials" ? "Add Your Initials" : "Add Your Signature"}
          </DialogTitle>
        </DialogHeader>

        <Tabs value={tab} onValueChange={setTab}>
          <TabsList className="grid w-full grid-cols-2">
            <TabsTrigger value="draw">Draw</TabsTrigger>
            <TabsTrigger value="type">Type</TabsTrigger>
          </TabsList>

          <TabsContent value="draw" className="mt-4">
            <div className="relative">
              <canvas
                ref={canvasRef}
                className="w-full h-32 border border-border rounded-lg cursor-crosshair bg-white touch-none"
                onMouseDown={startDraw}
                onMouseMove={draw}
                onMouseUp={stopDraw}
                onMouseLeave={stopDraw}
                onTouchStart={startDraw}
                onTouchMove={draw}
                onTouchEnd={stopDraw}
              />
              <button
                onClick={clearCanvas}
                className="absolute top-2 right-2 text-xs text-muted-foreground hover:text-foreground"
              >
                Clear
              </button>
            </div>
          </TabsContent>

          <TabsContent value="type" className="mt-4 space-y-3">
            <Input
              value={typedName}
              onChange={(e) => setTypedName(e.target.value)}
              placeholder={type === "initials" ? "Your initials" : "Your full name"}
            />
            <div className="space-y-2">
              {SIGNATURE_FONTS.map((font, i) => (
                <button
                  key={i}
                  onClick={() => setSelectedFont(i)}
                  className={`w-full p-3 text-left rounded-lg border transition-colors ${
                    selectedFont === i ? "border-primary bg-primary/5" : "border-border"
                  }`}
                >
                  <span style={{ font: font.style.replace(/\d+px/, "24px") }}>
                    {typedName || (type === "initials" ? "AB" : "Your Name")}
                  </span>
                </button>
              ))}
            </div>
          </TabsContent>
        </Tabs>

        <div className="flex justify-end gap-2 mt-4">
          <Button variant="outline" onClick={onClose}>Cancel</Button>
          <Button onClick={handleSave} disabled={!canSave}>
            Adopt & Sign
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import React from "react";
import { PenTool, Type, Calendar, Hash, CheckSquare, User } from "lucide-react";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";

const FIELD_ICONS = {
  signature: PenTool,
  initials: Type,
  name: User,
  date: Calendar,
  text: Hash,
  checkbox: CheckSquare,
};

export default function SigningField({ field, isActive, onFocus, value, onChange, onSignatureClick }) {
  const Icon = FIELD_ICONS[field.type] || Hash;
  const isFilled = !!value;

  const renderContent = () => {
    if (field.type === "signature" || field.type === "initials") {
      if (value) {
        return (
          <img
            src={value}
            alt={field.type}
            className="w-full h-full object-contain cursor-pointer"
            onClick={() => onSignatureClick(field)}
          />
        );
      }
      return (
        <button
          onClick={() => onSignatureClick(field)}
          className="w-full h-full flex items-center justify-center gap-1 text-xs font-medium text-primary hover:bg-primary/10 transition-colors"
        >
          <Icon className="w-3 h-3" />
          {field.type === "signature" ? "Sign here" : "Initial here"}
        </button>
      );
    }

    if (field.type === "checkbox") {
      return (
        <div className="w-full h-full flex items-center justify-center">
          <Checkbox
            checked={value === "true"}
            onCheckedChange={(checked) => onChange(checked ? "true" : "")}
          />
        </div>
      );
    }

    if (field.type === "date") {
      return (
        <div className="w-full h-full flex items-center px-1">
          <span className="text-xs">{value || ""}</span>
        </div>
      );
    }

    if (field.type === "name") {
      return (
        <div className="w-full h-full flex items-center px-1">
          <span className="text-xs">{value || ""}</span>
        </div>
      );
    }

    return (
      <Input
        value={value || ""}
        onChange={(e) => onChange(e.target.value)}
        className="w-full h-full border-0 text-xs p-1 bg-transparent focus-visible:ring-0"
        placeholder={field.placeholder || "Enter text"}
        onClick={(e) => e.stopPropagation()}
      />
    );
  };

  return (
    <div
      className={`absolute border-2 rounded cursor-pointer transition-all ${
        isActive ? "border-primary shadow-md ring-2 ring-primary/20" : isFilled ? "border-emerald-400 bg-emerald-50/50" : "border-primary/50 bg-blue-50/80"
      }`}
      style={{
        left: `${field.x * 100}%`,
        top: `${field.y * 100}%`,
        width: `${field.width * 100}%`,
        height: `${field.height * 100}%`,
      }}
      onClick={() => onFocus(field)}
    >
      {renderContent()}
    </div>
  );
}

