export default function DepositModal({ open, onClose, tenant }) {
  const queryClient = useQueryClient();
  const [showForm, setShowForm] = useState(false);
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState({
    amount: '',
    payment_date: format(new Date(), 'yyyy-MM-dd'),
    method: 'bank_transfer',
    notes: '',
    paid_by: '',
  });

  const { data: payments = [], refetch } = useQuery({
    queryKey: ['deposit_payments', tenant?.id],
    queryFn: () => base44.entities.DepositPayment.filter({ tenant_id: tenant.id }),
    enabled: !!tenant?.id && open,
  });

  const totalPaid = payments.reduce((s, p) => s + Number(p.amount || 0), 0);
  const depositDue = Number(tenant?.deposit || 0);
  const remaining = depositDue - totalPaid;

  const handleAdd = async (e) => {
    e.preventDefault();
    if (saving) return;
    setSaving(true);
    try {
      const cashName = form.paid_by.trim();
      const notes = [cashName && `Cash from ${cashName}`, form.notes].filter(Boolean).join(' — ');
      await base44.entities.DepositPayment.create({
        tenant_id: tenant.id,
        property_id: tenant.property_id,
        amount: Number(form.amount),
        payment_date: form.payment_date,
        method: form.method,
        notes,
      });
      await refetch();
      queryClient.invalidateQueries({ queryKey: ['deposit_payments'] });
      setForm({ amount: '', payment_date: format(new Date(), 'yyyy-MM-dd'), method: 'bank_transfer', notes: '', paid_by: '' });
      setShowForm(false);
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Delete this deposit payment?')) return;
    await base44.entities.DepositPayment.delete(id);
    await refetch();
    queryClient.invalidateQueries({ queryKey: ['deposit_payments'] });
  };

  return (
    <Dialog open={open} onOpenChange={v => { if (!v) { onClose(); setShowForm(false); } }}>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle>Deposit — {tenant?.name}</DialogTitle>
        </DialogHeader>

        {/* Summary */}
        <div className="grid grid-cols-3 gap-3 mb-2">
          <div className="bg-muted/50 rounded-lg px-3 py-2 text-center">
            <p className="text-xs text-muted-foreground">Deposit Due</p>
            <p className="font-semibold text-sm">{formatCurrency(depositDue)}</p>
          </div>
          <div className="bg-emerald-50 rounded-lg px-3 py-2 text-center">
            <p className="text-xs text-muted-foreground">Total Received</p>
            <p className="font-semibold text-sm text-emerald-700">{formatCurrency(totalPaid)}</p>
          </div>
          <div className={`rounded-lg px-3 py-2 text-center ${remaining > 0 ? 'bg-red-50' : 'bg-emerald-50'}`}>
            <p className="text-xs text-muted-foreground">Outstanding</p>
            <p className={`font-semibold text-sm ${remaining > 0 ? 'text-red-600' : 'text-emerald-700'}`}>
              {remaining > 0 ? formatCurrency(remaining) : <span className="flex items-center justify-center gap-1"><CheckCircle className="w-3.5 h-3.5" /> Paid</span>}
            </p>
          </div>
        </div>

        {/* Payment list */}
        {payments.length > 0 && (
          <div className="border border-border rounded-lg overflow-hidden mb-3">
            <table className="w-full text-sm">
              <thead>
                <tr className="bg-muted/50">
                  <th className="text-left px-3 py-2 font-medium text-muted-foreground">Date</th>
                  <th className="text-right px-3 py-2 font-medium text-muted-foreground">Amount</th>
                  <th className="text-left px-3 py-2 font-medium text-muted-foreground">Method</th>
                  <th className="text-left px-3 py-2 font-medium text-muted-foreground">Notes</th>
                  <th className="px-3 py-2"></th>
                </tr>
              </thead>
              <tbody>
                {payments.map(p => (
                  <tr key={p.id} className="border-t border-border">
                    <td className="px-3 py-2 text-muted-foreground whitespace-nowrap">
                      {p.payment_date ? format(parseISO(p.payment_date), 'dd MMM yyyy') : '-'}
                    </td>
                    <td className="px-3 py-2 text-right font-semibold text-emerald-700">{formatCurrency(p.amount)}</td>
                    <td className="px-3 py-2 text-xs capitalize">{p.method?.replace(/_/g, ' ')}</td>
                    <td className="px-3 py-2 text-xs text-muted-foreground">{p.notes || '—'}</td>
                    <td className="px-3 py-2">
                      <button onClick={() => handleDelete(p.id)}
                        className="text-red-400 hover:text-red-600">
                        <Trash2 className="w-3.5 h-3.5" />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {payments.length === 0 && !showForm && (
          <p className="text-sm text-muted-foreground text-center py-4">No deposit payments recorded yet.</p>
        )}

        {/* Add form */}
        {showForm ? (
          <form onSubmit={handleAdd} className="space-y-3 border border-border rounded-lg p-3">
            <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">New Payment</p>
            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1">
                <Label>Amount (£)</Label>
                <Input type="number" min="0.01" step="0.01" value={form.amount}
                  onChange={e => setForm(f => ({ ...f, amount: e.target.value }))} required />
              </div>
              <div className="space-y-1">
                <Label>Date</Label>
                <Input type="date" value={form.payment_date}
                  onChange={e => setForm(f => ({ ...f, payment_date: e.target.value }))} required />
              </div>
              <div className="space-y-1">
                <Label>Method</Label>
                <Select value={form.method} onValueChange={v => setForm(f => ({ ...f, method: v }))}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    {['bank_transfer','cash','card','standing_order','other'].map(m =>
                      <SelectItem key={m} value={m}>{m.replace(/_/g, ' ')}</SelectItem>)}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-1">
                <Label>Notes</Label>
                <Input value={form.notes} onChange={e => setForm(f => ({ ...f, notes: e.target.value }))} placeholder="Optional…" />
              </div>
              {form.method === 'cash' && (
                <div className="space-y-1 col-span-2">
                  <Label>Cash received from (name) *</Label>
                  <Input value={form.paid_by} onChange={e => setForm(f => ({ ...f, paid_by: e.target.value }))}
                    placeholder="Who handed over the cash?" required />
                </div>
              )}
            </div>
            <div className="flex gap-2 justify-end">
              <Button type="button" variant="outline" size="sm" onClick={() => setShowForm(false)}>Cancel</Button>
              <Button type="submit" size="sm" disabled={saving || (form.method === 'cash' && !form.paid_by.trim())}>{saving ? 'Saving...' : 'Save'}</Button>
            </div>
          </form>
        ) : (
          <Button size="sm" variant="outline" onClick={() => setShowForm(true)} className="w-full">
            <Plus className="w-4 h-4 mr-1" /> Record Deposit Payment
          </Button>
        )}
      </DialogContent>
    </Dialog>
  );
}

import React, { useState } from 'react';
import { format, parseISO, isAfter } from 'date-fns';
import { base44 } from '@/api/base44Client';
import { formatCurrency } from '@/lib/computations';
import StatusBadge from '@/components/ui/StatusBadge';
import ConfirmDialog from '@/components/ui/ConfirmDialog';
import { Button } from '@/components/ui/button';
import { Trash2 } from 'lucide-react';
import { useRole } from '@/hooks/useRole';
import { logAction } from '@/lib/audit';

export default function RentHistoryTable({ records, tenant, onChanged }) {
  const { user, isAdmin } = useRole();
  const [confirmDel, setConfirmDel] = useState(null);
  const [busy, setBusy] = useState(false);

  if (!records || records.length === 0) {
    return <p className="text-sm text-muted-foreground">No rent history recorded yet.</p>;
  }

  const today = new Date();
  const sorted = [...records].sort((a, b) => b.start_date.localeCompare(a.start_date));

  const getStatus = (r) => {
    const start = parseISO(r.start_date);
    if (r.end_date) return { label: 'Past', color: 'gray' };
    if (isAfter(start, today)) return { label: 'Scheduled', color: 'yellow' };
    return { label: 'Active', color: 'green' };
  };

  // Deleting a rent-change record undoes it. If it's the current (open) period,
  // reopen the previous period and restore the tenant's headline rent to it, so
  // the increase is cleanly reversed.
  const handleDelete = async (r) => {
    setBusy(true);
    try {
      const isOpen = !r.end_date;
      await base44.entities.RentHistory.delete(r.id);

      if (isOpen && tenant) {
        const prev = (records || [])
          .filter(x => x.id !== r.id && x.start_date < r.start_date)
          .sort((a, b) => b.start_date.localeCompare(a.start_date))[0];
        if (prev) {
          await base44.entities.RentHistory.update(prev.id, { end_date: '' });
          await base44.entities.Tenant.update(tenant.id, { monthly_rent: prev.rent_amount });
        }
      }
      await logAction({ user, action: 'delete', entityType: 'RentHistory', entityId: r.id, summary: `Deleted rent record ${formatCurrency(r.rent_amount)} from ${r.start_date} for ${tenant?.name || 'tenant'}`, oldValue: r });
      await onChanged?.();
    } finally {
      setBusy(false);
      setConfirmDel(null);
    }
  };

  return (
    <>
      <div className="bg-card rounded-xl border border-border overflow-hidden">
        <table className="w-full text-sm">
          <thead>
            <tr className="bg-muted/50">
              <th className="text-left px-4 py-3 font-medium text-muted-foreground">Amount</th>
              <th className="text-left px-4 py-3 font-medium text-muted-foreground">From</th>
              <th className="text-left px-4 py-3 font-medium text-muted-foreground">To</th>
              <th className="text-left px-4 py-3 font-medium text-muted-foreground">Status</th>
              <th className="text-left px-4 py-3 font-medium text-muted-foreground">Notes</th>
              <th className="text-right px-4 py-3 font-medium text-muted-foreground">Actions</th>
            </tr>
          </thead>
          <tbody>
            {sorted.map(r => {
              const status = getStatus(r);
              return (
                <tr key={r.id} className="border-t border-border hover:bg-muted/20 transition-colors">
                  <td className="px-4 py-3 font-semibold">{formatCurrency(r.rent_amount)}/mo</td>
                  <td className="px-4 py-3 text-muted-foreground">{format(parseISO(r.start_date), 'dd MMM yyyy')}</td>
                  <td className="px-4 py-3 text-muted-foreground">{r.end_date ? format(parseISO(r.end_date), 'dd MMM yyyy') : '—'}</td>
                  <td className="px-4 py-3"><StatusBadge color={status.color}>{status.label}</StatusBadge></td>
                  <td className="px-4 py-3 text-muted-foreground text-xs">{r.notes || '—'}</td>
                  <td className="px-4 py-3 text-right">
                    <Button variant="ghost" size="sm" className="text-destructive hover:text-destructive" disabled={busy} onClick={() => setConfirmDel(r)} title="Delete this rent record">
                      <Trash2 className="w-4 h-4" />
                    </Button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <ConfirmDialog
        open={!!confirmDel}
        title="Delete rent record?"
        description={confirmDel
          ? (!confirmDel.end_date
              ? `This removes the ${formatCurrency(confirmDel.rent_amount)}/mo rent from ${format(parseISO(confirmDel.start_date), 'MMM yyyy')} and restores the previous rent as current. Invoices will recalculate.`
              : `This removes the ${formatCurrency(confirmDel.rent_amount)}/mo record starting ${format(parseISO(confirmDel.start_date), 'MMM yyyy')}. Invoices for those months will recalculate.`)
          : ''}
        confirmText="Delete"
        onConfirm={() => handleDelete(confirmDel)}
        onCancel={() => setConfirmDel(null)}
      />
    </>
  );
}

import React, { useState } from 'react';
import { base44 } from '@/api/base44Client';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { format, subDays, parseISO } from 'date-fns';
import { TrendingUp, Plus, Pencil, Trash2, X, Check } from 'lucide-react';
import { formatCurrency } from '@/lib/computations';
import StatusBadge from '@/components/ui/StatusBadge';

const emptyForm = () => ({
  rent_amount: '',
  start_date: format(new Date(), 'yyyy-MM-dd'),
  end_date: '',
  notes: '',
});

export default function RentIncreaseModal({ open, onClose, tenant, currentRent, rentHistory = [], onSuccess }) {
  const [mode, setMode] = useState('list'); // 'list' | 'add' | 'edit'
  const [editRecord, setEditRecord] = useState(null);
  const [form, setForm] = useState(emptyForm());
  const [saving, setSaving] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(null);

  const update = (k, v) => setForm(f => ({ ...f, [k]: v }));

  const sorted = [...rentHistory].sort((a, b) => b.start_date.localeCompare(a.start_date));

  const openAdd = () => {
    setForm(emptyForm());
    setEditRecord(null);
    setMode('add');
  };

  const openEdit = (r) => {
    setForm({
      rent_amount: r.rent_amount,
      start_date: r.start_date,
      end_date: r.end_date || '',
      notes: r.notes || '',
    });
    setEditRecord(r);
    setMode('edit');
  };

  const handleClose = () => {
    setMode('list');
    setEditRecord(null);
    setConfirmDelete(null);
    onClose();
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (saving) return;
    setSaving(true);

    const newAmount = Number(form.rent_amount);
    const newStart = form.start_date;

    if (mode === 'add') {
      // Close any currently active (no end_date) record
      const active = sorted.filter(r => !r.end_date);
      if (active.length > 0) {
        const endDate = format(subDays(parseISO(newStart), 1), 'yyyy-MM-dd');
        await Promise.all(active.map(r => base44.entities.RentHistory.update(r.id, { end_date: endDate })));
      }
      await base44.entities.RentHistory.create({
        tenant_id: tenant.id,
        property_id: tenant.property_id,
        rent_amount: newAmount,
        start_date: newStart,
        end_date: form.end_date || null,
        notes: form.notes || null,
      });
      // Update tenant's monthly_rent to the new active amount
      await base44.entities.Tenant.update(tenant.id, { monthly_rent: newAmount });
    } else if (mode === 'edit') {
      await base44.entities.RentHistory.update(editRecord.id, {
        rent_amount: newAmount,
        start_date: newStart,
        end_date: form.end_date || null,
        notes: form.notes || null,
      });
      // If this is the active record (no end_date), sync tenant monthly_rent
      if (!form.end_date) {
        await base44.entities.Tenant.update(tenant.id, { monthly_rent: newAmount });
      }
    }

    setSaving(false);
    setMode('list');
    setEditRecord(null);
    onSuccess?.();
  };

  const handleDelete = async (record) => {
    setSaving(true);
    await base44.entities.RentHistory.delete(record.id);

    // Find the previous record (the one whose end_date was set to day-before this record's start_date)
    const remaining = sorted.filter(r => r.id !== record.id);
    if (remaining.length > 0) {
      // The previous record is the most recent one before this record's start_date
      const prev = remaining.find(r => r.start_date < record.start_date);
      if (prev) {
        // Re-open the previous record by clearing its end_date
        await base44.entities.RentHistory.update(prev.id, { end_date: null });
        // Sync tenant monthly_rent back to the restored record
        await base44.entities.Tenant.update(tenant.id, { monthly_rent: prev.rent_amount });
      }
    }

    setSaving(false);
    setConfirmDelete(null);
    onSuccess?.();
  };

  const getStatus = (r) => {
    const today = new Date().toISOString().slice(0, 10);
    if (r.end_date) return { label: 'Past', color: 'gray' };
    if (r.start_date > today) return { label: 'Scheduled', color: 'yellow' };
    return { label: 'Active', color: 'green' };
  };

  return (
    <Dialog open={open} onOpenChange={v => { if (!v) handleClose(); }}>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <TrendingUp className="w-5 h-5 text-primary" />
            Rent History — {tenant?.name}
          </DialogTitle>
        </DialogHeader>

        {/* LIST MODE */}
        {mode === 'list' && (
          <div className="space-y-4">
            <div className="bg-muted/40 border border-border rounded-lg px-4 py-3 text-sm">
              <p className="text-muted-foreground">Current rent: <span className="font-semibold text-foreground">{formatCurrency(currentRent)}/mo</span></p>
            </div>

            {sorted.length === 0 ? (
              <p className="text-sm text-muted-foreground text-center py-4">No rent history yet.</p>
            ) : (
              <div className="space-y-2 max-h-72 overflow-y-auto">
                {sorted.map(r => {
                  const st = getStatus(r);
                  return (
                    <div key={r.id} className="flex items-center justify-between gap-3 bg-card border border-border rounded-lg px-4 py-3">
                      <div className="min-w-0">
                        <p className="font-semibold text-sm">{formatCurrency(r.rent_amount)}/mo</p>
                        <p className="text-xs text-muted-foreground mt-0.5">
                          {format(parseISO(r.start_date), 'dd MMM yyyy')} →{' '}
                          {r.end_date ? format(parseISO(r.end_date), 'dd MMM yyyy') : 'present'}
                        </p>
                        {r.notes && <p className="text-xs text-muted-foreground italic mt-0.5">{r.notes}</p>}
                      </div>
                      <div className="flex items-center gap-2 shrink-0">
                        <StatusBadge color={st.color}>{st.label}</StatusBadge>
                        <Button variant="ghost" size="icon" className="h-7 w-7" onClick={() => openEdit(r)}>
                          <Pencil className="w-3.5 h-3.5" />
                        </Button>
                        <Button variant="ghost" size="icon" className="h-7 w-7 text-destructive hover:text-destructive" onClick={() => setConfirmDelete(r)}>
                          <Trash2 className="w-3.5 h-3.5" />
                        </Button>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}

            {/* Delete confirm */}
            {confirmDelete && (
              <div className="bg-destructive/10 border border-destructive/30 rounded-lg px-4 py-3 text-sm space-y-2">
                <p className="font-medium text-destructive">Delete this rent record ({formatCurrency(confirmDelete.rent_amount)}/mo)?</p>
                <div className="flex gap-2">
                  <Button size="sm" variant="destructive" disabled={saving} onClick={() => handleDelete(confirmDelete)}>
                    <Trash2 className="w-3.5 h-3.5 mr-1" />{saving ? 'Deleting...' : 'Confirm Delete'}
                  </Button>
                  <Button size="sm" variant="outline" onClick={() => setConfirmDelete(null)}>Cancel</Button>
                </div>
              </div>
            )}

            <div className="flex justify-between pt-1">
              <Button variant="outline" onClick={handleClose}>Close</Button>
              <Button onClick={openAdd}><Plus className="w-4 h-4 mr-1" />Add New Rate</Button>
            </div>
          </div>
        )}

        {/* ADD / EDIT MODE */}
        {(mode === 'add' || mode === 'edit') && (
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="bg-muted/40 border border-border rounded-lg px-4 py-3 text-sm">
              <p className="text-muted-foreground">
                {mode === 'edit' ? 'Editing existing rent record' : 'Adding a new rent rate — any currently active record will be automatically closed.'}
              </p>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1 col-span-2 sm:col-span-1">
                <Label>Rent Amount (£) *</Label>
                <Input
                  type="number" min="0" step="0.01"
                  placeholder="e.g. 1200"
                  value={form.rent_amount}
                  onChange={e => update('rent_amount', e.target.value)}
                  required
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1">
                <Label>Start Date *</Label>
                <Input type="date" value={form.start_date} onChange={e => update('start_date', e.target.value)} required />
              </div>
              <div className="space-y-1">
                <Label>End Date <span className="text-muted-foreground text-xs">(leave blank if active)</span></Label>
                <Input type="date" value={form.end_date} onChange={e => update('end_date', e.target.value)} />
              </div>
            </div>

            <div className="space-y-1">
              <Label>Notes (optional)</Label>
              <Input placeholder="Reason for change..." value={form.notes} onChange={e => update('notes', e.target.value)} />
            </div>

            {mode === 'add' && (
              <p className="text-xs text-muted-foreground">Previous active record will automatically close the day before the start date.</p>
            )}

            <div className="flex justify-between pt-1">
              <Button type="button" variant="outline" onClick={() => setMode('list')}>
                <X className="w-4 h-4 mr-1" />Back
              </Button>
              <Button type="submit" disabled={saving}>
                <Check className="w-4 h-4 mr-1" />{saving ? 'Saving...' : mode === 'add' ? 'Add Rate' : 'Save Changes'}
              </Button>
            </div>
          </form>
        )}
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useEffect } from 'react';
import { base44 } from '@/api/base44Client';
import { logAction } from '@/lib/audit';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { formatCurrency } from '@/lib/computations';
import { format } from 'date-fns';

/**
 * Rent increase dialog. Records a rent change that applies FROM the chosen month
 * ONWARD only — earlier months keep the old rent. Uses the RentHistory entity,
 * which the invoice/arrears calculations already read via getRentForPeriod.
 *
 * The user picks a MONTH; the new rent takes effect on the 1st of that month, so
 * it never partially affects an earlier month.
 */
export default function RentIncreaseDialog({ tenant, propertyId, user, onClose, onSaved }) {
  const [newRent, setNewRent] = useState('');
  const [effectiveDate, setEffectiveDate] = useState(''); // 'yyyy-MM-dd' — exact start day
  const [notes, setNotes] = useState('');
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    if (tenant) {
      setNewRent('');
      // Default to the first of next month, but the user can pick any exact day.
      const d = new Date(); d.setDate(1); d.setMonth(d.getMonth() + 1);
      setEffectiveDate(format(d, 'yyyy-MM-dd'));
      setNotes(''); setError('');
    }
  }, [tenant]);

  if (!tenant) return null;
  const current = Number(tenant.monthly_rent || 0);
  const next = Number(newRent) || 0;
  const diff = next - current;
  const pct = current > 0 ? ((diff / current) * 100) : 0;
  const pid = propertyId || tenant.property_id;

  const save = async () => {
    setError('');
    if (!next || next <= 0) { setError('Enter the new monthly rent.'); return; }
    if (!effectiveDate) { setError('Choose the date the new rent starts.'); return; }
    setSaving(true);
    try {
      // The new rent starts on the EXACT date chosen; the old rent ends the day
      // before, so nothing before that date is affected.
      const dayBefore = new Date(effectiveDate);
      dayBefore.setDate(dayBefore.getDate() - 1);
      const prevEnd = format(dayBefore, 'yyyy-MM-dd');

      const existing = await base44.entities.RentHistory.filter({ tenant_id: tenant.id });

      // Guard: don't allow a change dated on/before an existing newer change.
      const laterOrSame = (existing || []).some(r => r.start_date >= effectiveDate);
      if (laterOrSame) {
        setError('There is already a rent record on or after that date. Pick a later date or delete the existing one.');
        setSaving(false);
        return;
      }

      // Ensure earlier months are covered by an explicit record so this new rent
      // is NEVER applied backwards. If there's no record that starts on/before
      // the day this change begins, seed the tenant's CURRENT rent as the prior
      // period, running from the lease start up to the day before the change.
      const coversEarlier = (existing || []).some(r => r.start_date <= prevEnd);
      if (!coversEarlier) {
        await base44.entities.RentHistory.create({
          tenant_id: tenant.id, property_id: pid,
          rent_amount: current, start_date: tenant.lease_start || prevEnd, end_date: prevEnd,
          notes: 'Rent before increase (auto-recorded)',
        });
      }

      // Close any still-open prior period the day before the new rent starts.
      const openPeriods = (existing || []).filter(r => !r.end_date);
      for (const p of openPeriods) {
        if (p.start_date <= prevEnd) {
          await base44.entities.RentHistory.update(p.id, { end_date: prevEnd });
        }
      }
      await base44.entities.RentHistory.create({
        tenant_id: tenant.id, property_id: pid,
        rent_amount: next, start_date: effectiveDate, end_date: '',
        notes: notes || `Rent ${diff >= 0 ? 'increase' : 'change'} from ${current} to ${next}`,
      });
      await base44.entities.Tenant.update(tenant.id, { monthly_rent: next });
      await logAction({ user, action: 'update', entityType: 'Tenant', entityId: tenant.id, summary: `Rent ${diff >= 0 ? 'increase' : 'change'} for ${tenant.name}: ${current} → ${next} from ${effectiveDate}`, oldValue: { monthly_rent: current }, newValue: { monthly_rent: next } });
      await onSaved?.();
    } catch (e) {
      setError(e?.message || 'Could not save the rent change.');
    } finally {
      setSaving(false);
    }
  };

  const dateLabel = effectiveDate ? format(new Date(effectiveDate), 'd MMM yyyy') : '';

  return (
    <Dialog open={!!tenant} onOpenChange={(o) => { if (!o) onClose(); }}>
      <DialogContent className="max-w-md">
        <DialogHeader><DialogTitle>Rent increase — {tenant.name}</DialogTitle></DialogHeader>
        <div className="space-y-4 pt-1">
          <div className="flex items-center justify-between text-sm bg-muted/40 rounded-lg px-3 py-2">
            <span className="text-muted-foreground">Current rent</span>
            <span className="font-semibold">{formatCurrency(current)}/mo</span>
          </div>
          <div className="space-y-1.5">
            <Label className="text-xs">New monthly rent (£)</Label>
            <Input type="number" min="0" step="0.01" value={newRent} onChange={(e) => setNewRent(e.target.value)} placeholder="e.g. 2100" autoFocus />
          </div>
          {next > 0 && (
            <div className={`text-xs ${diff >= 0 ? 'text-emerald-700' : 'text-red-600'}`}>
              {diff >= 0 ? 'Increase' : 'Decrease'} of {formatCurrency(Math.abs(diff))}/mo ({pct >= 0 ? '+' : ''}{pct.toFixed(1)}%)
            </div>
          )}
          <div className="space-y-1.5">
            <Label className="text-xs">Starts from date</Label>
            <Input type="date" value={effectiveDate} onChange={(e) => setEffectiveDate(e.target.value)} />
            <p className="text-[11px] text-muted-foreground">
              {dateLabel ? `New rent applies from ${dateLabel} onward. Anything before keeps ${formatCurrency(current)}.` : 'New rent applies from this date onward only.'}
            </p>
          </div>
          <div className="space-y-1.5">
            <Label className="text-xs">Notes (optional)</Label>
            <Input value={notes} onChange={(e) => setNotes(e.target.value)} placeholder="e.g. Annual review" />
          </div>
          {error && <p className="text-xs text-red-600">{error}</p>}
          <div className="flex gap-2 justify-end pt-1">
            <Button variant="outline" onClick={onClose} disabled={saving}>Cancel</Button>
            <Button onClick={save} disabled={saving}>{saving ? 'Saving…' : 'Apply rent change'}</Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

