export default function Pagination({ page, totalPages, total, pageSize, onPage }) {
  if (totalPages <= 1) return null;
  const from = (page - 1) * pageSize + 1;
  const to = Math.min(page * pageSize, total);
  return (
    <div className="flex items-center justify-between mt-4 text-sm text-muted-foreground">
      <span>Showing {from}–{to} of {total}</span>
      <div className="flex items-center gap-1">
        <Button variant="outline" size="sm" disabled={page === 1} onClick={() => onPage(page - 1)}>
          <ChevronLeft className="w-4 h-4" />
        </Button>
        {Array.from({ length: totalPages }, (_, i) => i + 1).map(p => (
          <Button
            key={p}
            variant={p === page ? 'default' : 'outline'}
            size="sm"
            className="w-8 h-8 p-0"
            onClick={() => onPage(p)}
          >
            {p}
          </Button>
        ))}
        <Button variant="outline" size="sm" disabled={page === totalPages} onClick={() => onPage(page + 1)}>
          <ChevronRight className="w-4 h-4" />
        </Button>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { ChevronUp, ChevronDown } from 'lucide-react';

/**
 * Floating control to quickly jump to the top or bottom of a long page.
 * Shows only when the page is actually scrollable. Buttons disable when you're
 * already at the relevant end.
 */
export default function ScrollNav() {
  const [show, setShow] = useState(false);
  const [atTop, setAtTop] = useState(true);
  const [atBottom, setAtBottom] = useState(false);

  useEffect(() => {
    const update = () => {
      const doc = document.documentElement;
      const scrollable = doc.scrollHeight - window.innerHeight > 200;
      setShow(scrollable);
      const y = window.scrollY;
      setAtTop(y < 40);
      setAtBottom(y + window.innerHeight >= doc.scrollHeight - 40);
    };
    update();
    window.addEventListener('scroll', update, { passive: true });
    window.addEventListener('resize', update);
    const t = setInterval(update, 800); // catch late-loading content
    return () => {
      window.removeEventListener('scroll', update);
      window.removeEventListener('resize', update);
      clearInterval(t);
    };
  }, []);

  if (!show) return null;

  const toTop = () => window.scrollTo({ top: 0, behavior: 'smooth' });
  const toBottom = () => window.scrollTo({ top: document.documentElement.scrollHeight, behavior: 'smooth' });

  return (
    <div className="fixed bottom-6 right-6 z-40 flex flex-col gap-1.5 print:hidden">
      <button
        onClick={toTop}
        disabled={atTop}
        title="Jump to top"
        aria-label="Jump to top"
        className="w-11 h-11 rounded-full bg-primary text-white shadow-lg flex items-center justify-center hover:bg-primary/90 disabled:opacity-30 disabled:cursor-not-allowed transition-all"
      >
        <ChevronUp className="w-5 h-5" />
      </button>
      <button
        onClick={toBottom}
        disabled={atBottom}
        title="Jump to bottom"
        aria-label="Jump to bottom"
        className="w-11 h-11 rounded-full bg-primary text-white shadow-lg flex items-center justify-center hover:bg-primary/90 disabled:opacity-30 disabled:cursor-not-allowed transition-all"
      >
        <ChevronDown className="w-5 h-5" />
      </button>
    </div>
  );
}

