export const monthLabelFor = (monthKey) => format(parseISO(`${monthKey}-01`), 'MMMM yyyy');

const NAVY = '1F2C80';
const RED = 'C8302A';

// snake_case / camelCase -> "Title Case"
const prettyKey = (k) =>
  k.replace(/_/g, ' ')
   .replace(/([a-z])([A-Z])/g, '$1 $2')
   .replace(/\b\w/g, (c) => c.toUpperCase())
   .replace(/\bId\b/, 'ID');

const isMoney = (k) => /amount|rent|price|deposit|cost|value|balance|payable|paid|fee|sale/i.test(k);
const isDate  = (k) => /date|lease_start|lease_end|_from|_to|effective|start|end/i.test(k);

function fmtDate(v) {
  if (!v) return '';
  const s = String(v);
  const m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return `${m[3]}/${m[2]}/${m[1]}`;        // DD/MM/YYYY
  const ym = s.match(/^(\d{4})-(\d{2})$/);
  if (ym) return `${ym[2]}/${ym[1]}`;             // MM/YYYY
  return s;
}

/**
 * Build the organised backup ZIP from a data map { EntityKey: records[] }.
 * Returns { blob, totalRecords }.
 */
export async function buildBackupZip(data, { monthKey, dateStamp }) {
  const monthLabel = monthLabelFor(monthKey);

  // Lookup maps to resolve IDs -> human names
  const landlordName = {};
  (data.Landlord || []).forEach((l) => { landlordName[l.id] = l.name || l.email || l.id; });
  const propertyAddr = {};
  (data.Property || []).forEach((p) => { propertyAddr[p.id] = p.address || p.public_title || p.id; });
  const tenantName = {};
  (data.Tenant || []).forEach((t) => { tenantName[t.id] = t.name || t.id; });

  const resolveId = (key, val) => {
    if (key === 'landlord_id') return landlordName[val] || val;
    if (key === 'property_id') return propertyAddr[val] || val;
    if (key === 'tenant_id')   return tenantName[val] || val;
    return val;
  };

  // Build a friendly worksheet for an entity's records
  const buildSheet = (records) => {
    const rows = records.map((rec) => {
      const out = {};
      Object.keys(rec).forEach((k) => {
        if (k === 'id' || k.startsWith('_') || k === 'created_date' || k === 'updated_date') {
          return;
        }
        let v = rec[k];
        if (v && typeof v === 'object') v = JSON.stringify(v);
        if (k.endsWith('_id')) {
          out[prettyKey(k.replace(/_id$/, ''))] = resolveId(k, v);
        } else if (isDate(k)) {
          out[prettyKey(k)] = fmtDate(v);
        } else {
          out[prettyKey(k)] = v ?? '';
        }
      });
      out['Record ID'] = rec.id;
      return out;
    });

    const ws = XLSX.utils.json_to_sheet(rows);

    // Column widths + £ number format on money columns
    if (rows.length > 0) {
      const headers = Object.keys(rows[0]);
      ws['!cols'] = headers.map((h) => ({ wch: Math.min(Math.max(h.length + 4, 12), 40) }));
      ws['!autofilter'] = { ref: ws['!ref'] };
      const range = XLSX.utils.decode_range(ws['!ref']);
      headers.forEach((h, ci) => {
        if (!isMoney(h)) return;
        for (let r = 1; r <= range.e.r; r++) {
          const addr = XLSX.utils.encode_cell({ r, c: ci });
          const cell = ws[addr];
          if (cell && typeof cell.v === 'number') cell.z = '"\u00A3"#,##0.00';
        }
      });
    }
    return ws;
  };

  // Assemble the ZIP in a folder hierarchy
  const zip = new JSZip();
  const root = zip.folder(`ASA Estates Backups/${monthKey} (${monthLabel})`);
  const rawFolder = root.folder('_raw_json');
  const master = XLSX.utils.book_new();

  let totalRecords = 0;
  for (const e of BACKUP_ENTITIES) {
    const records = data[e.key] || [];
    totalRecords += records.length;

    // raw json (always, even if empty)
    rawFolder.file(`${e.key}.json`, JSON.stringify(records, null, 2));

    if (records.length === 0) continue;

    const ws = buildSheet(records);

    // individual workbook in the entity folder
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, e.label.slice(0, 31));
    const buf = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
    root.folder(e.folder).file(`${e.label}_${dateStamp}.xlsx`, buf);

    // also a CSV
    root.folder(e.folder).file(`${e.label}_${dateStamp}.csv`, XLSX.utils.sheet_to_csv(ws));

    // add as a tab in the master workbook
    XLSX.utils.book_append_sheet(master, ws, e.label.slice(0, 31));
  }

  // Master workbook
  const masterBuf = XLSX.write(master, { bookType: 'xlsx', type: 'array' });
  root.file(`ASA_Estates_All_Data_${dateStamp}.xlsx`, masterBuf);

  // Branded summary (HTML — opens in browser, Ctrl+P -> Save as PDF)
  const propCount = (data.Property || []).length;
  const tenCount = (data.Tenant || []).length;
  const activeTen = (data.Tenant || []).filter((t) => t.status === 'active').length;
  const landlordCount = (data.Landlord || []).length;
  const rentUnderMgmt = (data.Property || []).reduce((s, p) => s + (Number(p.monthly_rent) || 0), 0);

  const rows = BACKUP_ENTITIES
    .map((e) => `<tr><td>${e.label}</td><td style="text-align:right">${(data[e.key] || []).length}</td></tr>`)
    .join('');

  const summaryHtml = `<!doctype html><html><head><meta charset="utf-8">
<title>ASA Estates Backup — ${monthLabel}</title>
<style>
  body{font-family:Arial,Helvetica,sans-serif;color:#1a1a1a;max-width:760px;margin:40px auto;padding:0 24px}
  .bar{height:6px;background:#${NAVY};border-radius:3px}
  h1{font-size:30px;margin:18px 0 4px;color:#${NAVY}}
  .sub{color:#777;margin-bottom:28px}
  .cards{display:flex;gap:14px;flex-wrap:wrap;margin-bottom:28px}
  .card{flex:1;min-width:150px;border:1px solid #eee;border-radius:12px;padding:16px 18px}
  .card .n{font-size:28px;font-weight:800;color:#${RED}}
  .card .l{font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:#888;margin-top:4px}
  table{width:100%;border-collapse:collapse;margin-top:8px}
  th,td{padding:10px 12px;border-bottom:1px solid #eee;font-size:14px}
  th{text-align:left;background:#fafafa;color:#${NAVY};text-transform:uppercase;font-size:11px;letter-spacing:.06em}
  .foot{margin-top:28px;color:#999;font-size:12px}
</style></head><body>
  <div class="bar"></div>
  <h1>ASA Estates &mdash; Data Backup</h1>
  <div class="sub">${monthLabel} &nbsp;&middot;&nbsp; generated ${format(new Date(), 'dd MMM yyyy, HH:mm')}</div>
  <div class="cards">
    <div class="card"><div class="n">${propCount}</div><div class="l">Properties</div></div>
    <div class="card"><div class="n">${activeTen}/${tenCount}</div><div class="l">Active Tenants</div></div>
    <div class="card"><div class="n">${landlordCount}</div><div class="l">Landlords</div></div>
    <div class="card"><div class="n">\u00A3${rentUnderMgmt.toLocaleString()}</div><div class="l">Rent / month</div></div>
  </div>
  <table>
    <thead><tr><th>Data set</th><th style="text-align:right">Records</th></tr></thead>
    <tbody>${rows}<tr><td><strong>Total</strong></td><td style="text-align:right"><strong>${totalRecords}</strong></td></tr></tbody>
  </table>
  <div class="foot">
    To save as PDF: open this file and press Ctrl+P (Cmd+P on Mac) &rarr; "Save as PDF".<br/>
    Readable spreadsheets are in each folder. Full raw data for restore is in <code>_raw_json/</code>.<br/>
    &copy; ${new Date().getFullYear()} ASA Estates Ltd &middot; 320 Romford Road, London E7 8BD
  </div>
</body></html>`;
  root.file('00_SUMMARY.html', summaryHtml);

  const blob = await zip.generateAsync({ type: 'blob' });
  return { blob, totalRecords };
}

