import { differenceInMonths, parseISO, addMonths, isAfter, isBefore, startOfMonth, format } from 'date-fns';

/**
 * Calculate commission for a rent payment based on the agreement
 */
export function calculateCommission(rentAmount, agreement) {
  if (!agreement) return { commission: 0, landlordShare: rentAmount };

  switch (agreement.type) {
    case 'percentage':
      const commission = (rentAmount * agreement.value) / 100;
      return { commission, landlordShare: rentAmount - commission };
    case 'fixed_monthly':
      return { commission: agreement.value, landlordShare: rentAmount - agreement.value };
    case 'one_time':
      if (agreement.one_time_applied) {
        return { commission: 0, landlordShare: rentAmount };
      }
      return { commission: agreement.value, landlordShare: rentAmount - agreement.value };
    default:
      return { commission: 0, landlordShare: rentAmount };
  }
}

/**
 * Generate expected rent periods (YYYY-MM) from lease start to now (or lease end)
 */
export function generateRentPeriods(tenant, upToDate = new Date()) {
  if (!tenant?.lease_start) return [];
  const leaseStart = parseISO(tenant.lease_start);
  if (isNaN(leaseStart.getTime())) return [];
  const rentDay = leaseStart.getDate();
  const leaseEnd = tenant.lease_end ? parseISO(tenant.lease_end) : null;
  const validLeaseEnd = leaseEnd && !isNaN(leaseEnd.getTime()) ? leaseEnd : null;
  const end = validLeaseEnd && isBefore(validLeaseEnd, upToDate) ? validLeaseEnd : upToDate;
  const periods = [];
  let current = startOfMonth(leaseStart);
  const firstKey = format(leaseStart, 'yyyy-MM');
  while (!isAfter(current, startOfMonth(end))) {
    // A period is only owed if the tenancy was still active on/after that month's
    // rent due day. Tenant pays IN ADVANCE on the rent day: e.g. rent day 10, a
    // lease ending 9 Aug means the Aug period (due 10 Aug) was never reached, so
    // no Aug invoice. The very first period always counts (rent due at move-in).
    const daysInMonth = new Date(current.getFullYear(), current.getMonth() + 1, 0).getDate();
    const dueDate = new Date(current.getFullYear(), current.getMonth(), Math.min(rentDay, daysInMonth));
    const isFirst = format(current, 'yyyy-MM') === firstKey;
    if (isFirst || !validLeaseEnd || !isBefore(validLeaseEnd, dueDate)) {
      periods.push(format(current, 'yyyy-MM'));
    }
    current = addMonths(current, 1);
  }
  return periods;
}

/**
 * Pro-rata factor for the FINAL rent period of an ended tenancy, when the
 * tenant pays in advance and leaves part-way through a paid period.
 *
 * Rule (as configured):
 *   • Count whole days occupied INCLUDING the end date.
 *   • Divide by the number of days in that actual calendar month.
 *   • factor = daysStayed / daysInMonth  (capped at 1).
 *
 * Returns 1 for any period that is NOT the tenant's final part-period (i.e.
 * full months are charged in full). Returns a fraction only for the last
 * period when lease_end falls between that period's rent day and the next.
 *
 * @param {string} period  'YYYY-MM' of the invoice's cycle-start month
 * @param {object} tenant  needs lease_start, lease_end
 * @returns {number} 0..1
 */
export function finalPeriodProration(period, tenant) {
  if (!tenant?.lease_start || !tenant?.lease_end) return 1;
  const leaseStart = parseISO(tenant.lease_start);
  const leaseEnd = parseISO(tenant.lease_end);
  if (isNaN(leaseStart.getTime()) || isNaN(leaseEnd.getTime())) return 1;

  const rentDay = leaseStart.getDate();
  const [py, pm] = period.split('-').map(Number);
  const daysInMonth = new Date(py, pm, 0).getDate();
  const periodStart = new Date(py, pm - 1, Math.min(rentDay, daysInMonth));
  // Next cycle start = same day next month
  const nextDim = new Date(py, pm + 1, 0).getDate();
  const nextStart = new Date(py, pm, Math.min(rentDay, nextDim));

  // Only prorate the period that actually contains the end date:
  //   periodStart <= leaseEnd < nextStart
  if (leaseEnd < periodStart || leaseEnd >= nextStart) return 1;

  // Whole days occupied, inclusive of the end date.
  const msPerDay = 86400000;
  const daysStayed = Math.floor((leaseEnd.getTime() - periodStart.getTime()) / msPerDay) + 1;
  const factor = daysStayed / daysInMonth;
  return Math.max(0, Math.min(1, factor));
}

/**
 * Get the rent amount effective for a given period (YYYY-MM) using versioned RentHistory.
 * Falls back to tenant.monthly_rent if no history records exist.
 */
export function getRentForPeriod(period, tenant, rentHistory) {
  if (!rentHistory || rentHistory.length === 0) return tenant.monthly_rent;
  // Compare against the day the cycle actually starts (the tenant's rent day
  // from lease_start), not the 1st — a 27th-cycle "April" invoice covers
  // 27 Apr → 26 May, so a record starting 27 Apr must count for it.
  let dayPart = '01';
  if (tenant.lease_start && /^\d{4}-\d{2}-\d{2}$/.test(tenant.lease_start)) {
    dayPart = tenant.lease_start.slice(8, 10);
  }
  const periodStart = `${period}-${dayPart}`;
  const active = rentHistory
    .filter(r => r.start_date <= periodStart && (!r.end_date || r.end_date >= periodStart))
    .sort((a, b) => b.start_date.localeCompare(a.start_date));
  if (active.length > 0) return active[0].rent_amount;
  // Period is BEFORE the earliest record — do NOT apply a later increase
  // backwards. Fall back to the tenant's base rent for those earlier months.
  return tenant.monthly_rent;
}

/**
 * Calculate per-period arrears breakdown for a tenant.
 * Overpayments carry forward to the next period.
 * Uses versioned rentHistory for date-accurate rent amounts.
 * Returns array of { period, rent, paid, arrears, status, creditForward }
 */
/**
 * Total refund due to a tenant when they move out.
 * = rent overpaid (sum of any invoice where they paid more than the pro-rated
 *   amount owed) + their deposit.
 * Only meaningful for ended tenancies; returns a breakdown so the UI can show it.
 *
 * @param {object} tenant
 * @param {Array}  invoices  the tenant's invoices from buildTenantInvoices (with .overpaid)
 * @returns {{ rentOverpaid:number, deposit:number, total:number }}
 */
export function calculateRefundDue(tenant, invoices = []) {
  const rentOverpaid = (invoices || [])
    .filter(inv => inv.tenant_id === tenant.id)
    .reduce((sum, inv) => sum + Math.max(0, Number(inv.overpaid || 0)), 0);
  const deposit = Math.max(0, Number(tenant.deposit || 0));
  const rentOverpaidR = Math.round(rentOverpaid * 100) / 100;
  const total = Math.round((rentOverpaidR + deposit) * 100) / 100;
  return { rentOverpaid: rentOverpaidR, deposit, total };
}

export function calculatePeriodArrears(tenant, payments, rentHistory, upToMonth = null) {
  if (!tenant?.lease_start || !tenant?.monthly_rent) return [];
  let periods = generateRentPeriods(tenant);
  // Optionally cap at a month ('yyyy-MM'), so arrears can be shown "as of" a
  // past month rather than always up to today.
  if (upToMonth) periods = periods.filter(p => p <= upToMonth);
  const paymentsByPeriod = {};
  (payments || []).forEach(p => {
    const pm = p.period_month || p.period_month_date;
    if (!pm) return;
    // Normalise to YYYY-MM
    const key = pm.length > 7 ? pm.substring(0, 7) : pm;
    // When capping to a month, ignore payments recorded for later periods.
    if (upToMonth && key > upToMonth) return;
    paymentsByPeriod[key] = (paymentsByPeriod[key] || 0) + (p.amount || 0);
  });

  let credit = 0; // overpayment carried from previous period
  return periods.map(period => {
    // Pro-rata the final period of an ended tenancy (advance payer leaving mid-month),
    // so arrears match the pro-rated invoice rather than a full month.
    const factor = finalPeriodProration(period, tenant);
    const rent = Math.round(getRentForPeriod(period, tenant, rentHistory) * factor * 100) / 100;
    const rawPaid = (paymentsByPeriod[period] || 0) + credit;
    const effective = Math.min(rawPaid, rent);
    credit = Math.max(0, rawPaid - rent);
    const arrears = Math.max(0, rent - effective);
    const status = arrears === 0 ? 'paid' : effective > 0 ? 'partial' : 'unpaid';
    return { period, rent, paid: effective, arrears, status, creditForward: credit, prorated: factor < 1 };
  });
}

/**
 * Calculate total arrears for a tenant (sum of per-period arrears)
 */
export function calculateArrears(tenant, payments, rentHistory, upToMonth = null) {
  const breakdown = calculatePeriodArrears(tenant, payments, rentHistory, upToMonth);
  return breakdown.reduce((sum, p) => sum + p.arrears, 0);
}

/**
 * Check if a date is expired
 */
export function isExpired(dateStr) {
  if (!dateStr) return false;
  return isBefore(parseISO(dateStr), new Date());
}

/**
 * Check if a date is expiring within N days
 */
export function isExpiringSoon(dateStr, days = 30) {
  if (!dateStr) return false;
  const date = parseISO(dateStr);
  const now = new Date();
  const futureDate = new Date(now.getTime() + days * 24 * 60 * 60 * 1000);
  return isAfter(date, now) && isBefore(date, futureDate);
}

/**
 * Get landlord balance: total landlord share from commission ledger minus total payouts
 */
export function calculateLandlordBalance(commissionLedgerEntries, payouts) {
  const totalOwed = (commissionLedgerEntries || []).reduce((sum, e) => sum + (e.landlord_share || 0), 0);
  const totalPaid = (payouts || []).reduce((sum, p) => sum + (p.amount || 0), 0);
  return totalOwed - totalPaid;
}

/**
 * Format currency
 */
export function formatCurrency(amount) {
  return new Intl.NumberFormat('en-GB', { style: 'currency', currency: 'GBP' }).format(amount || 0);
}

