/**
 * Get the latest non-archived document of a category for a property.
 * Sorted by expiry_date (newest first), falling back to issue_date.
 * Returns the document object or null.
 */
export function getLatestPropertyDoc(propertyId, category, documents) {
  if (!documents || documents.length === 0) return null;
  const filtered = documents
    .filter(d =>
      d.property_id === propertyId &&
      d.category === category &&
      !d.is_archived
    )
    .sort((a, b) => {
      const aKey = a.expiry_date || a.issue_date || '';
      const bKey = b.expiry_date || b.issue_date || '';
      return bKey.localeCompare(aKey);
    });
  return filtered[0] || null;
}

/**
 * Current expiry date for a category on a property.
 * Returns the expiry_date string from the latest doc, or null if no doc / no expiry.
 */
export function getCurrentExpiry(propertyId, category, documents) {
  const latest = getLatestPropertyDoc(propertyId, category, documents);
  return latest?.expiry_date || null;
}

/**
 * Build a per-property certificate status snapshot.
 * Returns: { gas, electrical, epc, license } where each is { expiry, status, doc }.
 * status: 'expired' | 'expiring' | 'valid' | 'missing'
 *   - expired:  expiry date is in the past
 *   - expiring: expiry date is within 30 days
 *   - valid:    expiry date is more than 30 days away
 *   - missing:  no document on file
 */
export function getPropertyCertStatus(propertyId, documents) {
  const cats = {
    gas: 'gas_cert',
    electrical: 'electrical_cert',
    epc: 'epc_cert',
    license: 'license',
  };
  const out = {};
  for (const [key, category] of Object.entries(cats)) {
    const doc = getLatestPropertyDoc(propertyId, category, documents);
    const expiry = doc?.expiry_date || null;
    let status = 'missing';
    if (expiry) {
      if (isExpired(expiry)) status = 'expired';
      else if (isExpiringSoon(expiry)) status = 'expiring';
      else status = 'valid';
    }
    out[key] = { expiry, status, doc };
  }
  return out;
}

/**
 * Count how many documents exist for a property in a given category (non-archived).
 * Useful for "3 documents on file" labels.
 */
export function countPropertyDocs(propertyId, category, documents) {
  if (!documents) return 0;
  return documents.filter(d =>
    d.property_id === propertyId &&
    d.category === category &&
    !d.is_archived
  ).length;
}

import * as XLSX from 'xlsx';
import { format } from 'date-fns';
import { formatCurrency, getPropertyCertStatus } from '@/lib/computations';
import { buildLedger } from '@/lib/ledger';

function col(headers, rows, totals) {
  const ws = XLSX.utils.aoa_to_sheet([headers, ...rows]);
  if (totals) {
    XLSX.utils.sheet_add_aoa(ws, [totals], { origin: -1 });
  }
  return ws;
}

function fmtDate(d) {
  if (!d) return '';
  try { return format(new Date(d), 'dd/MM/yyyy'); } catch { return d; }
}

function download(wb, filename) {
  XLSX.writeFile(wb, `${filename}_${format(new Date(), 'yyyy-MM-dd')}.xlsx`);
}

export function exportTenants({ tenants, properties, landlords, rentPayments }) {
  const wb = XLSX.utils.book_new();

  const rows = tenants.map(t => {
    const prop = properties.find(p => p.id === t.property_id);
    const landlord = landlords.find(l => l.id === prop?.landlord_id);
    const paid = rentPayments.filter(rp => rp.tenant_id === t.id).reduce((s, rp) => s + (rp.amount || 0), 0);
    return [t.name, t.email || '', t.phone || '', prop?.address || '', landlord?.name || '',
      fmtDate(t.lease_start), fmtDate(t.lease_end), t.monthly_rent, t.deposit || 0, t.status, paid];
  });
  const totals = ['TOTALS', '', '', '', '', '', '',
    tenants.reduce((s, t) => s + (t.monthly_rent || 0), 0),
    tenants.reduce((s, t) => s + (t.deposit || 0), 0), '', 0];

  XLSX.utils.book_append_sheet(wb, col(
    ['Name', 'Email', 'Phone', 'Property', 'Landlord', 'Lease Start', 'Lease End', 'Monthly Rent (£)', 'Deposit (£)', 'Status', 'Total Paid (£)'],
    rows, totals
  ), 'Tenants');

  download(wb, 'Tenants_Export');
}

export function exportProperties({ properties, landlords, tenants, propertyDocuments = [] }) {
  const wb = XLSX.utils.book_new();

  const rows = properties.map(p => {
    const landlord = landlords.find(l => l.id === p.landlord_id);
    const activeTenants = tenants.filter(t => t.property_id === p.id && t.status === 'active').length;
    const cs = getPropertyCertStatus(p.id, propertyDocuments);
    return [p.address, landlord?.name || '', p.type, p.monthly_rent, p.status, activeTenants,
      fmtDate(cs.gas.expiry), fmtDate(cs.electrical.expiry), fmtDate(cs.epc.expiry), fmtDate(cs.license.expiry)];
  });

  XLSX.utils.book_append_sheet(wb, col(
    ['Address', 'Landlord', 'Type', 'Monthly Rent (£)', 'Status', 'Active Tenants',
      'Gas Cert Expiry', 'Electrical Cert Expiry', 'EPC Expiry', 'License Expiry'],
    rows
  ), 'Properties');

  download(wb, 'Properties_Export');
}

