  const wb = XLSX.utils.book_new();

  // Summary sheet
  const totalRent = rentPayments.reduce((s, p) => s + (p.amount || 0), 0);
  const totalCommission = commissionLedger.reduce((s, e) => s + (e.commission_amount || 0), 0);
  const totalLandlordShare = commissionLedger.reduce((s, e) => s + (e.landlord_share || 0), 0);
  const totalPayouts = landlordPayouts.reduce((s, p) => s + (p.amount || 0), 0);
  const totalExpenses = expenses.filter(e => e.paid_by === 'agency').reduce((s, e) => s + (e.amount || 0), 0);
  const netProfit = totalCommission - totalExpenses;
  const outstanding = totalLandlordShare - totalPayouts;

  const summaryWs = XLSX.utils.aoa_to_sheet([
    ['Property Management Financial Summary'],
    ['Generated:', format(new Date(), 'dd/MM/yyyy HH:mm')],
    [],
    ['Metric', 'Amount (£)'],
    ['Total Rent Collected', totalRent],
    ['Total Commission Earned', totalCommission],
    ['Total Landlord Share', totalLandlordShare],
    ['Total Paid to Landlords', totalPayouts],
    ['Outstanding Landlord Balance', outstanding],
    ['Agency Expenses', totalExpenses],
    ['Net Agency Profit', netProfit],
  ]);
  XLSX.utils.book_append_sheet(wb, summaryWs, 'Summary');

  // Rent Payments sheet
  const rentRows = rentPayments.map(rp => {
    const tenant = tenants.find(t => t.id === rp.tenant_id);
    const property = properties.find(p => p.id === rp.property_id);
    const ledger = commissionLedger.find(e => e.rent_payment_id === rp.id);
    return [fmtDate(rp.payment_date), tenant?.name || '', property?.address || '', rp.period_month || '',
      rp.amount, ledger?.commission_amount || 0, ledger?.landlord_share || 0, rp.method?.replace(/_/g, ' ') || ''];
  });
  XLSX.utils.book_append_sheet(wb, col(
    ['Date', 'Tenant', 'Property', 'Period', 'Amount (£)', 'Commission (£)', 'Landlord Share (£)', 'Method'],
    rentRows, ['TOTALS', '', '', '', totalRent, totalCommission, totalLandlordShare, '']
  ), 'Rent Payments');

  // Commission sheet
  const commRows = commissionLedger.map(e => {
    const landlord = landlords.find(l => l.id === e.landlord_id);
    const property = properties.find(p => p.id === e.property_id);
    return [fmtDate(e.date), landlord?.name || '', property?.address || '', e.commission_type || '',
      e.commission_rate || 0, e.rent_amount || 0, e.commission_amount || 0, e.landlord_share || 0];
  });
  XLSX.utils.book_append_sheet(wb, col(
    ['Date', 'Landlord', 'Property', 'Type', 'Rate', 'Rent (£)', 'Commission (£)', 'Landlord Share (£)'],
    commRows, ['TOTALS', '', '', '', '', 0, totalCommission, totalLandlordShare]
  ), 'Commission');

  // Expenses sheet
  const expRows = expenses.map(e => {
    const prop = properties.find(p => p.id === e.property_id);
    const landlord = landlords.find(l => l.id === e.landlord_id);
    return [fmtDate(e.date), prop?.address || '', landlord?.name || '', e.category?.replace(/_/g, ' ') || '',
      e.description, e.amount, e.paid_by];
  });
  XLSX.utils.book_append_sheet(wb, col(
    ['Date', 'Property', 'Landlord', 'Category', 'Description', 'Amount (£)', 'Paid By'],
    expRows, ['TOTALS', '', '', '', '', expenses.reduce((s, e) => s + (e.amount || 0), 0), '']
  ), 'Expenses');

  // Ledger sheet
  const ledgerEntries = buildLedger({ rentPayments, commissionLedger, landlordPayouts, expenses, properties, tenants, landlords });
  const ledgerRows = ledgerEntries.map(e => [
    fmtDate(e.date), e.type, e.category, e.description, e.property_address, e.tenant_name, e.landlord_name,
    e.type === 'Income' ? e.amount : 0, e.type === 'Expense' ? e.amount : 0, e.running_balance
  ]);
  XLSX.utils.book_append_sheet(wb, col(
    ['Date', 'Type', 'Category', 'Description', 'Property', 'Tenant', 'Landlord', 'Income (£)', 'Expense (£)', 'Running Balance (£)'],
    ledgerRows
  ), 'Ledger');

  download(wb, 'FullReport');
}

