}

/**
 * Invoice & Statement generation — fully computed from existing entities.
 */
import { format, parseISO, addMonths, subMonths, subDays, differenceInMonths, startOfMonth, getDate, isBefore, isValid } from 'date-fns';
import { getLandlordShares, getLandlordSharesForPeriod, splitByShares } from '@/lib/landlordShares';
import { getFrequency, cycleStartMonth, forPeriod, cycleMonths } from '@/lib/rentFrequency';
import { finalPeriodProration } from '@/lib/computations';

const round2 = (n) => Math.round(((n || 0) + Number.EPSILON) * 100) / 100;

function getRentForPeriod(period, tenant, rentHistoryByTenant) {
  const history = rentHistoryByTenant?.[tenant.id];
  if (!history || history.length === 0) return tenant.monthly_rent || 0;
  // Match against the day the cycle actually starts (the tenant's rent day),
  // not the 1st of the month. A tenant whose rent runs 27th–26th has their
  // "April" invoice cover 27 Apr → 26 May, so a rent record starting 27 Apr
  // must count for that invoice.
  let dayPart = '01';
  if (tenant.lease_start && /^\d{4}-\d{2}-\d{2}$/.test(tenant.lease_start)) {
    dayPart = tenant.lease_start.slice(8, 10);
  }
  const periodStart = `${period}-${dayPart}`;
  // A rent record applies to a cycle if it started on or before the cycle start
  // (and hasn't ended before it). Pick the latest such record.
  const active = history
    .filter(r => r.start_date <= periodStart && (!r.end_date || r.end_date >= periodStart))
    .sort((a, b) => b.start_date.localeCompare(a.start_date));
  if (active.length > 0) return active[0].rent_amount;
  // Month is before the earliest record — never apply a later increase backwards.
  return tenant.monthly_rent_original ?? tenant.base_monthly_rent ?? tenant.monthly_rent ?? 0;
}

function safeParseISO(str) { if (!str) return null; const d = parseISO(str); return isValid(d) ? d : null; }

function getLeasePeriod(paymentDateStr, leaseStartDay) {
  if (!paymentDateStr || !leaseStartDay) return paymentDateStr?.substring(0, 7);
  const d = parseISO(paymentDateStr);
  if (getDate(d) < leaseStartDay) return format(subMonths(d, 1), 'yyyy-MM');
  return format(d, 'yyyy-MM');
}

/**
 * Returns { rent, source } — expected monthly rent for a property in a month.
 *
 * Handover-safe: when two tenants overlap the same month in the SAME unit
 * (old tenant leaving + new tenant arriving), it uses the newest one's rent —
 * it does NOT sum them. Distinct units (HMO) still sum, so multi-room rent is correct.
 */
export function getPropertyRentForPeriod({ property, tenants = [], rentHistoryAll = [], rentPayments = [], periodMonth }) {
  if (!property || !periodMonth) return { rent: 0, source: 'none' };
  const rentHistoryByTenant = {};
  rentHistoryAll.forEach(r => {
    if (!rentHistoryByTenant[r.tenant_id]) rentHistoryByTenant[r.tenant_id] = [];
    rentHistoryByTenant[r.tenant_id].push(r);
  });
  const [yr, mo] = periodMonth.split('-').map(Number);
  const periodStart = `${periodMonth}-01`;
  const periodEnd = format(new Date(yr, mo, 0), 'yyyy-MM-dd');

  // End-of-tenancy proration: if tenancies overlap this month but NONE continues
  // past month-end (the final month of the last tenancy), the landlord is only
  // owed the pro-rated portion — scale whichever rent source wins below.
  const coversMonth = (t) => {
    if (!t.lease_start) return false;
    const startMonth = t.lease_start.substring(0, 7);
    if (startMonth > periodMonth) return false;
    if (periodMonth === startMonth) return true;
    if (!t.lease_end) return true;
    if (t.lease_end.substring(0, 7) < periodMonth) return false;
    const dim0 = new Date(yr, mo, 0).getDate();
    const day = Math.min(Number(t.lease_start.substring(8, 10)) || 1, dim0);
    return t.lease_end >= `${periodMonth}-${String(day).padStart(2, '0')}`;
  };
  const overlapping = tenants.filter(t => t.property_id === property.id && coversMonth(t));
  let endFactor = 1;
  if (overlapping.length > 0 && overlapping.every(t => t.lease_end && t.lease_end < periodEnd)) {
    endFactor = Math.max(...overlapping.map(t => finalPeriodProration(periodMonth, t)));
  }
  const scaled = (rent, source) => ({ rent: Math.round(rent * endFactor * 100) / 100, source, prorated: endFactor < 1 });

  // 1. PROPERTY's own monthly_rent (primary)
  if ((property.monthly_rent || 0) > 0) return scaled(property.monthly_rent, 'property');

  // 2. Tenants overlapping the month — dedupe by unit (newest per unit), then sum across units
  const tenantsInMonth = tenants.filter(t =>
    t.property_id === property.id &&
    (!t.lease_start || t.lease_start <= periodEnd) &&
    (!t.lease_end   || t.lease_end   >= periodStart)
  );
  if (tenantsInMonth.length > 0) {
    // Prefer tenants still in place at month-end. In a handover month this drops the
    // departing tenant (whose lease_end falls before month-end), leaving the incoming one.
    const activeAtEnd = tenantsInMonth.filter(t => !t.lease_end || t.lease_end >= periodEnd);
    const pool = activeAtEnd.length > 0 ? activeAtEnd : tenantsInMonth;

    // Then dedupe by unit (newest per unit) and sum across distinct units (HMO-safe).
    const byUnit = {};
    pool.forEach(t => {
      const unit = (t.unit_description || '').trim().toLowerCase() || '__main__';
      const cur = byUnit[unit];
      if (!cur || (t.lease_start || '') > (cur.lease_start || '')) byUnit[unit] = t;
    });
    const rent = Object.values(byUnit).reduce((s, t) => s + (getRentForPeriod(periodMonth, t, rentHistoryByTenant) || 0), 0);
    if (rent > 0) return scaled(rent, 'tenant-in-month');
  }

  // 3. Any tenant on the property at all (newest first)
  const allTenants = tenants
    .filter(t => t.property_id === property.id)
    .sort((a, b) => (b.lease_start || '').localeCompare(a.lease_start || ''));
  for (const t of allTenants) {
    const r = (t.monthly_rent || 0) > 0 ? t.monthly_rent : getRentForPeriod(periodMonth, t, rentHistoryByTenant);
    if (r > 0) return { rent: r, source: 'tenant-any' };
  }

  // 4. Learn from most recent rent payment on the property
  const propPayments = rentPayments
    .filter(rp => rp.property_id === property.id && rp.amount > 0)
    .sort((a, b) => (b.payment_date || '').localeCompare(a.payment_date || ''));
  if (propPayments[0]?.amount > 0) return { rent: propPayments[0].amount, source: 'rent-payment-history' };

  return { rent: 0, source: 'none' };
}

export function buildTenantInvoices({ tenants, properties, landlords, rentPayments, carriedBalances = [], rentHistoryAll = [], manualCharges = [] }) {
  // Guard against a data hook returning null/undefined (a `= []` default only
  // catches undefined, not null) — otherwise .forEach below throws.
  tenants = tenants || [];
  properties = properties || [];
  landlords = landlords || [];
  rentPayments = rentPayments || [];
  manualCharges = manualCharges || [];
  // Manual one-off charges grouped by tenant+month, added onto that invoice.
  const chargesByKey = {};
  manualCharges.forEach(c => {
    if (!c.tenant_id || !c.period_month || !c.amount) return;
    const k = `${c.tenant_id}__${c.period_month}`;
    (chargesByKey[k] = chargesByKey[k] || []).push(c);
  });
  carriedBalances = carriedBalances || [];
  rentHistoryAll = rentHistoryAll || [];

  const rentHistoryByTenant = {};
  rentHistoryAll.forEach(r => { if (!rentHistoryByTenant[r.tenant_id]) rentHistoryByTenant[r.tenant_id] = []; rentHistoryByTenant[r.tenant_id].push(r); });
  const invoiceMap = {};
  const carriedByTenant = {};
  carriedBalances.forEach(cb => { if (cb.is_cleared || !cb.tenant_id || !cb.amount) return; carriedByTenant[cb.tenant_id] = (carriedByTenant[cb.tenant_id] || 0) + Number(cb.amount); });
  const tenantLeaseDay = {};
  tenants.forEach(t => { const d = safeParseISO(t.lease_start); if (d) tenantLeaseDay[t.id] = getDate(d); });
  const getCycleLabel = (cs, frequency) => `${format(cs, 'd MMM yyyy')} → ${format(subDays(addMonths(cs, cycleMonths(frequency)), 1), 'd MMM yyyy')}`;

  rentPayments.forEach(rp => {
    const tenant = tenants.find(t => t.id === rp.tenant_id);
    const frequency = getFrequency(tenant);
    const leaseStartMonth = tenant?.lease_start ? tenant.lease_start.substring(0, 7) : null;
    let period = rp.period_month || getLeasePeriod(rp.payment_date, tenantLeaseDay[rp.tenant_id]);
    // Snap quarterly payments to their quarter-start month so they land on the right invoice.
    if (frequency === 'quarterly' && leaseStartMonth) period = cycleStartMonth(leaseStartMonth, period, 'quarterly');
    const key = `${rp.tenant_id}__${period}`;
    const property = properties.find(p => p.id === rp.property_id);
    const landlord = landlords.find(l => l.id === rp.landlord_id);
    if (!invoiceMap[key]) {
      const [py, pm] = period.split('-').map(Number);
      const parsedLease = safeParseISO(tenant?.lease_start);
      const leaseDay = parsedLease ? getDate(parsedLease) : 1;
      const cycleStartDate = new Date(py, pm - 1, leaseDay);
      if (!isValid(cycleStartDate)) { invoiceMap[key] && invoiceMap[key].payments.push(rp); return; }
      invoiceMap[key] = { key, tenant_id: rp.tenant_id, tenant_name: tenant?.name || 'Unknown', tenant_email: tenant?.email || '', unit_description: tenant?.unit_description || '', property_id: rp.property_id, property_address: property?.address || '', landlord_name: landlord?.name || '', period_month: period, cycle_label: getCycleLabel(cycleStartDate, frequency), rent_amount: tenant ? forPeriod(getRentForPeriod(period, tenant, rentHistoryByTenant), frequency) : rp.amount, arrears: 0, payments: [], due_date: format(cycleStartDate, 'yyyy-MM-dd'), invoice_date: rp.payment_date, is_upcoming: false, rent_frequency: frequency };
    }
    invoiceMap[key].payments.push(rp);
  });

  const now = new Date();
  // Generate historic invoices for tenants that are active OR ended. For ended
  // tenants we still owe the invoices for every cycle up to (and including) the
  // one containing lease_end — otherwise unpaid final cycles silently vanish
  // the moment a tenancy is marked Ended.
  tenants.filter(t => (t.status === 'active' || t.status === 'ended') && t.lease_start).forEach(tenant => {
    const leaseStart = safeParseISO(tenant.lease_start); if (!leaseStart) return;
    const frequency = getFrequency(tenant);
    const step = cycleMonths(frequency);
    const property = properties.find(p => p.id === tenant.property_id);
    const landlord = landlords.find(l => l.id === property?.landlord_id);
    const leaseEnd = safeParseISO(tenant.lease_end);
    // For ended tenants, stop at lease_end rather than "now".
    const boundary = (tenant.status === 'ended' && leaseEnd && isBefore(leaseEnd, now)) ? leaseEnd : now;
    const monthCount = Math.min(differenceInMonths(boundary, leaseStart) + 1, 48);
    for (let i = 0; i < monthCount; i += step) {
      const cycleStartDate = addMonths(leaseStart, i); if (!isValid(cycleStartDate)) continue;
      // Never generate a cycle that starts after the tenancy end date.
      if (leaseEnd && cycleStartDate > leaseEnd) break;
      const period = format(cycleStartDate, 'yyyy-MM'); const key = `${tenant.id}__${period}`;
      if (!invoiceMap[key]) invoiceMap[key] = { key, tenant_id: tenant.id, tenant_name: tenant.name || 'Unknown', tenant_email: tenant.email || '', unit_description: tenant.unit_description || '', property_id: tenant.property_id, property_address: property?.address || '', landlord_name: landlord?.name || '', period_month: period, cycle_label: getCycleLabel(cycleStartDate, frequency), rent_amount: forPeriod(getRentForPeriod(period, tenant, rentHistoryByTenant), frequency), arrears: 0, payments: [], due_date: format(cycleStartDate, 'yyyy-MM-dd'), invoice_date: format(cycleStartDate, 'yyyy-MM-dd'), is_upcoming: false, rent_frequency: frequency };
    }
  });

  tenants.filter(t => t.status === 'active' && t.lease_start).forEach(tenant => {
    const leaseEnd = safeParseISO(tenant.lease_end); if (leaseEnd && isBefore(leaseEnd, now)) return;
    const leaseStart = safeParseISO(tenant.lease_start); if (!leaseStart) return;
    const frequency = getFrequency(tenant);
    const step = cycleMonths(frequency);
    // Next cycle start = leaseStart + (floor(diff/step)+1)*step — identical to the old
    // formula for monthly (step=1), and the next quarter start for quarterly.
    const nextCycleStart = addMonths(leaseStart, (Math.floor(differenceInMonths(now, leaseStart) / step) + 1) * step);
    if (!isValid(nextCycleStart)) return;
    if (frequency === 'quarterly' && leaseEnd && nextCycleStart > leaseEnd) return;
    if (now < subDays(nextCycleStart, 5)) return;
    const nextPeriod = format(nextCycleStart, 'yyyy-MM'); const upcomingKey = `${tenant.id}__${nextPeriod}`;
    if (invoiceMap[upcomingKey]) return;
    const property = properties.find(p => p.id === tenant.property_id);
    const landlord = landlords.find(l => l.id === property?.landlord_id);
    invoiceMap[upcomingKey] = { key: upcomingKey, tenant_id: tenant.id, tenant_name: tenant.name || 'Unknown', tenant_email: tenant.email || '', unit_description: tenant.unit_description || '', property_id: tenant.property_id, property_address: property?.address || '', landlord_name: landlord?.name || '', period_month: nextPeriod, cycle_label: getCycleLabel(nextCycleStart, frequency), rent_amount: forPeriod(getRentForPeriod(nextPeriod, tenant, rentHistoryByTenant), frequency), arrears: 0, payments: [], due_date: format(nextCycleStart, 'yyyy-MM-dd'), invoice_date: format(now, 'yyyy-MM-dd'), is_upcoming: true, rent_frequency: frequency };
  });

  const earliestByTenant = {};
  Object.values(invoiceMap).forEach(inv => { const cur = earliestByTenant[inv.tenant_id]; if (!cur || inv.period_month < cur.period_month) earliestByTenant[inv.tenant_id] = inv; });
  Object.entries(carriedByTenant).forEach(([tid, amt]) => { const target = earliestByTenant[tid]; if (target && amt > 0) target.carried_balance = amt; });

  // tenant lookup for per-month discounts (stored on tenant.monthly_notes)
  const tenantById = {};
  tenants.forEach(t => { tenantById[t.id] = t; });
  const monthDiscount = (tenantId, period) => {
    const t = tenantById[tenantId];
    const notes = t && Array.isArray(t.monthly_notes) ? t.monthly_notes : [];
    const e = notes.find(n => n.month === period);
    return Math.max(0, Number(e?.discount || 0));
  };
  const monthDiscountReason = (tenantId, period) => {
    const t = tenantById[tenantId];
    const notes = t && Array.isArray(t.monthly_notes) ? t.monthly_notes : [];
    const e = notes.find(n => n.month === period);
    return e?.discount_reason || '';
  };

  const invoicesByTenant = {};
  Object.values(invoiceMap).forEach(inv => { if (!invoicesByTenant[inv.tenant_id]) invoicesByTenant[inv.tenant_id] = []; invoicesByTenant[inv.tenant_id].push(inv); });
  Object.values(invoicesByTenant).forEach(tInvs => {
    tInvs.sort((a, b) => a.period_month.localeCompare(b.period_month));
    // carry starts at 0; the first invoice already has carried_balance set from carriedByTenant above
    let carry = 0;
    tInvs.forEach((inv, idx) => {
      if (idx > 0) inv.carried_balance = carry;
      // else: inv.carried_balance was already set (or 0) from the earliestByTenant assignment above
      const cb = inv.carried_balance || 0;
      // Subtract any discount for the month so a discounted invoice doesn't
      // carry its discounted portion forward as phantom arrears.
      const disc = inv.is_upcoming ? 0 : monthDiscount(inv.tenant_id, inv.period_month);
      const chg = inv.is_upcoming ? 0 : (chargesByKey[`${inv.tenant_id}__${inv.period_month}`] || []).reduce((s2, c) => s2 + Number(c.amount || 0), 0);
      const td = Math.max(0, (inv.rent_amount || 0) - disc) + (inv.arrears || 0) + cb + chg;
      const tp = inv.payments.reduce((s, p) => s + (p.amount || 0), 0);
      carry = Math.max(0, td - tp);
    });
  });


  // ── Final-period handling for ended tenancies (advance payers) ──
  // 1) Drop any monthly period whose rent day falls AFTER lease_end — the tenant
  //    left before that period was ever due (e.g. rent day 10, ends 9 Aug → no Aug).
  // 2) Pro-rata the period that actually contains lease_end, based on whole days
  //    occupied (inclusive) ÷ days in that month.
  Object.keys(invoiceMap).forEach(key => {
    const inv = invoiceMap[key];
    if (inv.is_upcoming) return;
    const t = tenantById[inv.tenant_id] || tenants.find(x => x.id === inv.tenant_id);
    if (!t || !t.lease_end) return;
    const freq = inv.rent_frequency || getFrequency(t);
    if (freq !== 'monthly') return; // proration handled for monthly cycles only
    const leaseEnd = safeParseISO(t.lease_end);
    const leaseStart = safeParseISO(t.lease_start);
    if (!leaseEnd || !leaseStart) return;

    const [py, pm] = inv.period_month.split('-').map(Number);
    const rentDay = getDate(leaseStart);
    const dim = new Date(py, pm, 0).getDate();
    const periodStart = new Date(py, pm - 1, Math.min(rentDay, dim));

    // If this period starts after lease_end AND it isn't already paid, it should
    // not exist. Keep it only if a payment was recorded against it.
    if (periodStart > leaseEnd) {
      const hasPayment = (inv.payments || []).length > 0;
      if (!hasPayment) { delete invoiceMap[key]; return; }
    }

    const factor = finalPeriodProration(inv.period_month, t);
    if (factor < 1) {
      inv.rent_amount = Math.round((inv.rent_amount || 0) * factor * 100) / 100;
      inv.prorated = true;
      inv.proration_factor = factor;
      inv.cycle_label = `${format(periodStart, 'd MMM yyyy')} → ${format(leaseEnd, 'd MMM yyyy')} (part month)`;
    }
  });

  // Recompute carry-forward after proration so balances stay correct.
  {
    const byTenant2 = {};
    Object.values(invoiceMap).forEach(inv => { (byTenant2[inv.tenant_id] = byTenant2[inv.tenant_id] || []).push(inv); });
    Object.values(byTenant2).forEach(tInvs => {
      tInvs.sort((a, b) => a.period_month.localeCompare(b.period_month));
      let carry = 0;
      tInvs.forEach((inv, idx) => {
        if (idx > 0) inv.carried_balance = carry;
        const cb = inv.carried_balance || 0;
        const disc = inv.is_upcoming ? 0 : monthDiscount(inv.tenant_id, inv.period_month);
        const chg = inv.is_upcoming ? 0 : (chargesByKey[`${inv.tenant_id}__${inv.period_month}`] || []).reduce((s2, c) => s2 + Number(c.amount || 0), 0);
        const td = Math.max(0, (inv.rent_amount || 0) - disc) + (inv.arrears || 0) + cb + chg;
        const tp = inv.payments.reduce((s, p) => s + (p.amount || 0), 0);
        carry = Math.max(0, td - tp);
      });
    });
  }

  return Object.values(invoiceMap)
    .sort((a, b) => a.period_month !== b.period_month ? a.period_month.localeCompare(b.period_month) : a.tenant_name.localeCompare(b.tenant_name))
    .map((inv, idx) => {
      const total_paid = inv.payments.reduce((s, p) => s + (p.amount || 0), 0);
      const carried_balance = inv.carried_balance || 0;
      const discount = inv.is_upcoming ? 0 : monthDiscount(inv.tenant_id, inv.period_month);
      const discount_reason = discount > 0 ? monthDiscountReason(inv.tenant_id, inv.period_month) : '';
      const rent_after_discount = Math.max(0, (inv.rent_amount || 0) - discount);
      const manual_charges = inv.is_upcoming ? [] : (chargesByKey[`${inv.tenant_id}__${inv.period_month}`] || []);
      const manual_charges_total = manual_charges.reduce((s2, c) => s2 + Number(c.amount || 0), 0);
      const total_due = rent_after_discount + (inv.arrears || 0) + carried_balance + manual_charges_total;
      let status = 'Unpaid';
      if (inv.is_upcoming) status = 'Upcoming';
      else if (total_paid >= total_due && total_due > 0) status = 'Paid';
      else if (total_paid > 0) status = 'Partial';
      // Overpayment on this invoice (e.g. paid a full month in advance but the
      // tenancy ended mid-month so the pro-rated amount owed is lower).
      const overpaid = inv.is_upcoming ? 0 : Math.max(0, Math.round((total_paid - total_due) * 100) / 100);
      if (overpaid > 0) status = 'Credit';
      return { ...inv, invoice_number: `INV-${String(idx + 1).padStart(4, '0')}`, total_paid, total_due, discount, discount_reason, carried_balance, overpaid, manual_charges, manual_charges_total, balance_due: inv.is_upcoming ? total_due : Math.max(0, total_due - total_paid), status };
    });
}

/**
 * Landlord statements — Due = Rent − Commission − Expenses − Maintenance − Extras.
 * Rent from getPropertyRentForPeriod (handover-safe). FIXED regardless of tenant payment.
 */
export function buildLandlordStatements({
  landlords, properties, tenants, rentPayments, commissionLedger,
  expenses, landlordPayouts, paymentExtras = [], maintenanceRequests = [],
  commissionAgreements = [], rentHistoryAll = [],
}) {
  landlords = landlords || []; properties = properties || []; tenants = tenants || [];
  rentPayments = rentPayments || []; commissionLedger = commissionLedger || [];
  expenses = expenses || []; landlordPayouts = landlordPayouts || [];
  paymentExtras = paymentExtras || []; maintenanceRequests = maintenanceRequests || [];
  commissionAgreements = commissionAgreements || []; rentHistoryAll = rentHistoryAll || [];

  const stmtMap = {};
  const today = new Date();

  const commissionForPeriod = (landlordId, propertyId, period, expectedRent) => {
    const inWindow = (a) => (!a.effective_from || a.effective_from <= period) && (!a.effective_to || a.effective_to >= period);
    const agreement = commissionAgreements.find(a => a.landlord_id === landlordId && a.property_id === propertyId && inWindow(a)) || commissionAgreements.find(a => a.landlord_id === landlordId && !a.property_id && inWindow(a));
    if (!agreement) return 0;
    if (!(expectedRent > 0)) return 0; // no rent (e.g. vacant) → no commission
    if (agreement.type === 'percentage') return (expectedRent * agreement.value) / 100;
    if (agreement.type === 'fixed_monthly') return agreement.value;
    if (agreement.type === 'one_time' && !agreement.one_time_applied) return agreement.value;
    return 0;
  };

  // Was any tenancy live during a given month at a property?
  const tenancyInMonth = (propTenants, period) => propTenants.some(t => {
    if (!t.lease_start) return false;
    const startMonth = t.lease_start.substring(0, 7);
    if (startMonth > period) return false;
    if (period === startMonth) return true; // first month always counts
    if (!t.lease_end) return true;
    if (t.lease_end.substring(0, 7) < period) return false;
    // Rent-day aware: the month only counts if the tenancy reached its due day
    // (lease-start day, clamped) in that month — otherwise the final cycle
    // belongs to the previous month and this month generates nothing.
    const [yr, mo] = period.split('-').map(Number);
    const dim = new Date(yr, mo, 0).getDate();
    const day = Math.min(Number(t.lease_start.substring(8, 10)) || 1, dim);
    return t.lease_end >= `${period}-${String(day).padStart(2, '0')}`;
  });

  properties.forEach(prop => {
    if (!prop.payment_day) return;
    const landlord = landlords.find(l => l.id === prop.landlord_id);
    if (!landlord || landlord.status === 'inactive' || landlord.is_agent) return;
    const propTenants = tenants.filter(t => t.property_id === prop.id);
    let earliestStr = null;
    propTenants.forEach(t => { if (t.lease_start && (!earliestStr || t.lease_start < earliestStr)) earliestStr = t.lease_start; });
    // No tenant has ever lived here → no landlord statements at all.
    if (!earliestStr) return;
    const earliestDate = parseISO(earliestStr); if (!isValid(earliestDate)) return;
    const monthsBack = Math.max(0, Math.min(differenceInMonths(today, earliestDate), 24));
    for (let i = 0; i <= monthsBack; i++) {
      const monthDate = addMonths(startOfMonth(earliestDate), i);
      const period = format(monthDate, 'yyyy-MM');
      // Skip vacant months — once every tenancy has ended, stop generating.
      if (!tenancyInMonth(propTenants, period)) continue;
      const key = `${landlord.id}__${prop.id}__${period}`;
      if (!stmtMap[key]) stmtMap[key] = { key, landlord_id: landlord.id, landlord_name: landlord.name || 'Unknown', landlord_email: landlord.email || '', property_id: prop.id, property_address: prop.address || 'Unknown', period_month: period, rent_payments: [], commission_entries: [], expense_entries: [], payout_entries: [], extras: [], maintenance_charges: [] };
    }
  });

  rentPayments.forEach(rp => {
    const period = rp.period_month; if (!period) return;
    const key = `${rp.landlord_id}__${rp.property_id}__${period}`;
    if (!stmtMap[key]) {
      const landlord = landlords.find(l => l.id === rp.landlord_id);
      const property = properties.find(p => p.id === rp.property_id);
      stmtMap[key] = { key, landlord_id: rp.landlord_id, landlord_name: landlord?.name || 'Unknown', landlord_email: landlord?.email || '', property_id: rp.property_id, property_address: property?.address || 'Unknown', period_month: period, rent_payments: [], commission_entries: [], expense_entries: [], payout_entries: [], extras: [], maintenance_charges: [] };
    }
    stmtMap[key].rent_payments.push({ ...rp, tenant_name: tenants.find(t => t.id === rp.tenant_id)?.name || rp.tenant_name || 'Unknown' });
  });

  commissionLedger.forEach(entry => {
    const rp = rentPayments.find(r => r.id === entry.rent_payment_id); if (!rp) return;
    const key = `${entry.landlord_id}__${rp.property_id}__${rp.period_month}`;
    if (stmtMap[key]) stmtMap[key].commission_entries.push(entry);
  });

  expenses.filter(e => e.paid_by === 'landlord' && e.approved === true).forEach(exp => {
    if (!exp.property_id) return;
    const month = exp.date ? exp.date.substring(0, 7) : null; if (!month) return;
    const key = `${exp.landlord_id}__${exp.property_id}__${month}`;
    if (stmtMap[key]) stmtMap[key].expense_entries.push(exp);
  });

  paymentExtras.forEach(ex => {
    const month = ex.period_month; if (!month || !ex.property_id) return;
    const key = `${ex.landlord_id}__${ex.property_id}__${month}`;
    if (!stmtMap[key]) {
      const landlord = landlords.find(l => l.id === ex.landlord_id);
      const property = properties.find(p => p.id === ex.property_id);
      stmtMap[key] = { key, landlord_id: ex.landlord_id, landlord_name: landlord?.name || 'Unknown', landlord_email: landlord?.email || '', property_id: ex.property_id, property_address: property?.address || 'Unknown', period_month: month, rent_payments: [], commission_entries: [], expense_entries: [], payout_entries: [], extras: [], maintenance_charges: [] };
    }
    stmtMap[key].extras.push(ex);
  });

  maintenanceRequests.filter(m => m.charge_to_landlord && m.landlord_id && m.property_id && !m.linked_extra_id).forEach(m => {
    const cost = m.actual_cost || m.estimated_cost || 0; if (!cost) return;
    let targetPeriod = m.charge_period || null;
    if (!targetPeriod) { const dr = m.resolved_date || m.scheduled_date; if (!dr) return; targetPeriod = dr.substring(0, 7); }
    const key = `${m.landlord_id}__${m.property_id}__${targetPeriod}`;
    if (!stmtMap[key]) {
      const landlord = landlords.find(l => l.id === m.landlord_id);
      const property = properties.find(p => p.id === m.property_id);
      stmtMap[key] = { key, landlord_id: m.landlord_id, landlord_name: landlord?.name || 'Unknown', landlord_email: landlord?.email || '', property_id: m.property_id, property_address: property?.address || 'Unknown', period_month: targetPeriod, rent_payments: [], commission_entries: [], expense_entries: [], payout_entries: [], extras: [], maintenance_charges: [] };
    }
    stmtMap[key].maintenance_charges.push({ id: m.id, title: m.title, description: m.description, category: m.category, amount: cost, charge_period: targetPeriod });
  });

  landlordPayouts.forEach(p => {
    if (!p.property_id) return;
    const targetMonth = p.period_month || (p.payment_date ? p.payment_date.substring(0, 7) : null);
    if (!targetMonth) return;
    const key = `${p.landlord_id}__${p.property_id}__${targetMonth}`;
    if (stmtMap[key]) { stmtMap[key].payout_entries.push(p); return; }
    const fallbackKey = Object.keys(stmtMap).find(k => k.startsWith(`${p.landlord_id}__${p.property_id}__`));
    if (fallbackKey) stmtMap[fallbackKey].payout_entries.push(p);
  });

  const sortedBase = Object.values(stmtMap).sort((a, b) => {
    if (a.period_month !== b.period_month) return a.period_month.localeCompare(b.period_month);
    if (a.landlord_name !== b.landlord_name) return a.landlord_name.localeCompare(b.landlord_name);
    return a.property_address.localeCompare(b.property_address);
  });

  // payout-classification helpers (kept identical to legacy behaviour)
  const bankEntriesOf  = (payouts) => payouts.filter(p => p.payment_mode === 'split' ? (p.bank_amount || 0) > 0 : p.method !== 'cash');
  const cashSeparateOf = (payouts) => payouts.reduce((s, p) => p.payment_mode === 'split' && !p.cash_pending ? s + (p.cash_amount || 0) : s, 0);
  const paidOf         = (payouts) => payouts.reduce((s, p) => p.payment_mode === 'split' ? s + (p.bank_amount || 0) : s + (p.amount || 0), 0);
  const payoutPeriod   = (p) => p.period_month || (p.payment_date ? p.payment_date.substring(0, 7) : null);

  const expanded = [];

  sortedBase.forEach(stmt => {
    const property = properties.find(p => p.id === stmt.property_id);

    // ── Property-level figures (computed ONCE; commission charged once here) ──
    const rentResult = getPropertyRentForPeriod({
      property, tenants, rentHistoryAll, rentPayments, periodMonth: stmt.period_month,
    });
    const expected_rent = rentResult.rent;
    const rent_source = rentResult.source;

    // Coverage label: the dates this month's rent covers, shown for EVERY month
    // a tenant occupies (e.g. "17 Jun 2026 → 16 Jul 2026"). If the tenancy ends
    // mid-cycle, the end date is lease_end and "(part month)" is appended.
    let coverage_label = null;
    {
      const [cyr, cmo] = stmt.period_month.split('-').map(Number);
      const cEnd = format(new Date(cyr, cmo, 0), 'yyyy-MM-dd');
      const cStart = `${stmt.period_month}-01`;
      const covering = (tenants || [])
        .filter(t => {
          if (t.property_id !== stmt.property_id || !t.lease_start) return false;
          if (t.lease_start.substring(0, 7) > stmt.period_month) return false;
          if (t.lease_end && t.lease_end < cStart) return false;
          return true;
        })
        .sort((a, b) => (b.lease_start || '').localeCompare(a.lease_start || ''));
      const t = covering[0];
      if (t && t.lease_start) {
        const sd = safeParseISO(t.lease_start);
        if (sd) {
          const rentDay = getDate(sd);
          const dim = new Date(cyr, cmo, 0).getDate();
          const cycleStart = new Date(cyr, cmo - 1, Math.min(rentDay, dim));
          const nextDim = new Date(cyr, cmo + 1, 0).getDate();
          const nextStart = new Date(cyr, cmo, Math.min(rentDay, nextDim));
          const normalEnd = new Date(nextStart.getTime() - 86400000);
          const le = t.lease_end ? safeParseISO(t.lease_end) : null;
          const endsInCycle = le && le >= cycleStart && le < normalEnd;
          const end = endsInCycle ? le : normalEnd;
          const label = `${format(cycleStart, 'd MMM yyyy')} → ${format(end, 'd MMM yyyy')}`;
          coverage_label = endsInCycle ? `${label} (part month)` : label;
        }
      }
    }

    const rent_collected = stmt.rent_payments.reduce((s, r) => s + (r.amount || 0), 0);
    const commission_total = commissionForPeriod(stmt.landlord_id, stmt.property_id, stmt.period_month, expected_rent);
    const expenses_total    = stmt.expense_entries.reduce((s, e) => s + (e.amount || 0), 0);
    const extras_total      = stmt.extras.reduce((s, e) => s + (e.amount || 0), 0);
    const maintenance_total = stmt.maintenance_charges.reduce((s, m) => s + (m.amount || 0), 0);

    const net_payable = expected_rent - commission_total - expenses_total - maintenance_total - extras_total;
    const tenant_overpayment = Math.max(0, rent_collected - expected_rent);
    const tenant_shortfall   = Math.max(0, expected_rent - rent_collected);

    // Ownership split in effect for THIS month, so past months keep their split.
    const shares = getLandlordSharesForPeriod(property, stmt.period_month);
    const isLegacySingle = shares.length <= 1 && (shares.length === 0 || shares[0].landlord_id === stmt.landlord_id);

    if (isLegacySingle) {
      // ═══ UNCHANGED legacy single-landlord path (byte-identical to before) ═══
      const bank_payout_entries = bankEntriesOf(stmt.payout_entries);
      const cash_paid_separately = cashSeparateOf(stmt.payout_entries);
      const paid_this_period = paidOf(stmt.payout_entries);
      const invoice_net_payable = Math.max(0, net_payable - cash_paid_separately);
      expanded.push({
        ...stmt,
        agreed_rent: expected_rent, expected_rent, rent_collected, rent_source,
        tenant_overpayment, tenant_shortfall,
        commission_total, expenses_total, extras_total, maintenance_total,
        net_payable, invoice_net_payable, cash_paid_separately, paid_this_period, bank_payout_entries,
        coverage_label,
        balance_due: Math.max(0, invoice_net_payable - paid_this_period),
        properties_breakdown: [{ property_id: stmt.property_id, address: stmt.property_address, agreed_rent: expected_rent, commission: commission_total, expenses: expenses_total, extras: extras_total, maintenance: maintenance_total, net: invoice_net_payable }],
        status: invoice_net_payable <= 0 ? 'Paid' : paid_this_period >= invoice_net_payable ? 'Paid' : paid_this_period > 0 ? 'Partial' : 'Unpaid',
      });
      return;
    }

    // ═══ MULTI-LANDLORD: one statement per co-owner, scaled by share ═══
    // Net is split exactly (parts sum to the property net — no penny lost).
    const netParts = splitByShares(net_payable, shares);
    const co_owners = shares.map(x => ({
      landlord_id: x.landlord_id,
      name: landlords.find(l => l.id === x.landlord_id)?.name || 'Unknown',
      share_pct: x.share_pct,
    }));

    shares.forEach((sh, si) => {
      const frac = netParts[si].fraction;
      const ll = landlords.find(l => l.id === sh.landlord_id);

      // This co-landlord's OWN payouts for this property+period (payouts are per-landlord).
      const myPayouts = landlordPayouts.filter(p =>
        p.landlord_id === sh.landlord_id &&
        p.property_id === stmt.property_id &&
        payoutPeriod(p) === stmt.period_month
      );

      const scaledExpenses    = stmt.expense_entries.map(e => ({ ...e, amount: round2((e.amount || 0) * frac) }));
      const scaledExtras      = stmt.extras.map(e => ({ ...e, amount: round2((e.amount || 0) * frac) }));
      const scaledMaintenance = stmt.maintenance_charges.map(m => ({ ...m, amount: round2((m.amount || 0) * frac) }));
      const scaledRentPays    = stmt.rent_payments.map(r => ({ ...r, amount: round2((r.amount || 0) * frac) }));

      const rent_share        = round2(expected_rent * frac);
      const commission_share  = round2(commission_total * frac);
      const expenses_share    = round2(expenses_total * frac);
      const extras_share       = round2(extras_total * frac);
      const maintenance_share = round2(maintenance_total * frac);
      const net_share         = netParts[si].amount;            // exact
      const rent_collected_sh = round2(rent_collected * frac);

      const bank_payout_entries = bankEntriesOf(myPayouts);
      const cash_paid_separately = cashSeparateOf(myPayouts);
      const paid_this_period = paidOf(myPayouts);
      const invoice_net_payable = Math.max(0, net_share - cash_paid_separately);

      expanded.push({
        ...stmt,
        key: `${sh.landlord_id}__${stmt.property_id}__${stmt.period_month}`,
        landlord_id: sh.landlord_id,
        landlord_name: ll?.name || 'Unknown',
        landlord_email: ll?.email || '',
        is_co_owned: true,
        share_pct: sh.share_pct,
        co_owners,
        rent_payments: scaledRentPays,
        expense_entries: scaledExpenses,
        extras: scaledExtras,
        maintenance_charges: scaledMaintenance,
        payout_entries: myPayouts,
        agreed_rent: rent_share, expected_rent: rent_share, rent_collected: rent_collected_sh, rent_source,
        tenant_overpayment: round2(tenant_overpayment * frac), tenant_shortfall: round2(tenant_shortfall * frac),
        commission_total: commission_share, expenses_total: expenses_share, extras_total: extras_share, maintenance_total: maintenance_share,
        net_payable: net_share, invoice_net_payable, cash_paid_separately, paid_this_period, bank_payout_entries,
        coverage_label,
        balance_due: Math.max(0, invoice_net_payable - paid_this_period),
        properties_breakdown: [{ property_id: stmt.property_id, address: stmt.property_address, agreed_rent: rent_share, commission: commission_share, expenses: expenses_share, extras: extras_share, maintenance: maintenance_share, net: invoice_net_payable }],
        status: invoice_net_payable <= 0 ? 'Paid' : paid_this_period >= invoice_net_payable ? 'Paid' : paid_this_period > 0 ? 'Partial' : 'Unpaid',
      });
    });
  });

  return expanded
    .sort((a, b) => {
      if (a.period_month !== b.period_month) return a.period_month.localeCompare(b.period_month);
      if (a.landlord_name !== b.landlord_name) return a.landlord_name.localeCompare(b.landlord_name);
      return a.property_address.localeCompare(b.property_address);
    })
    .map((s, idx) => ({ ...s, statement_number: `LST-${String(idx + 1).padStart(4, '0')}` }));
}

/**
 * Multi-landlord ownership helpers.
 *
 * A property can be owned by more than one landlord, each holding a share %.
 * Money (rent − commission − expenses − maintenance − extras) is computed ONCE
 * at the property level, then split between co-landlords by their share, with
 * separate statements / payouts per landlord.
 *
 * BACKWARD-COMPAT: a property with no `landlord_shares` is treated as a single
 * landlord (its `landlord_id`) holding 100%. All legacy single-landlord
 * behaviour is preserved exactly — see isSingleLandlord().
 */

/**
 * Normalised list of { landlord_id, share_pct } for a property.
 * Always returns at least one entry when the property has any landlord.
 * Filters out blank ids and non-positive shares.
 */
export function getLandlordShares(property) {
  if (!property) return [];
  const raw = Array.isArray(property.landlord_shares) ? property.landlord_shares : [];
  const cleaned = raw
    .filter(s => s && s.landlord_id && Number(s.share_pct) > 0)
    .map(s => ({ landlord_id: s.landlord_id, share_pct: Number(s.share_pct) }));

  if (cleaned.length > 0) return cleaned;

  // Fallback: single legacy landlord at 100%
  if (property.landlord_id) return [{ landlord_id: property.landlord_id, share_pct: 100 }];
  return [];
}

/**
 * Date-aware ownership split. Returns the shares that were in effect for a given
 * month ('yyyy-MM'), so past statements keep their historical split even after
 * ownership changes.
 *
 * property.ownership_history is an optional array of past splits, each:
 *   { effective_to: 'yyyy-MM', shares: [{ landlord_id, share_pct }, ...] }
 * meaning "this split applied for all months <= effective_to". The property's
 * live landlord_shares is the CURRENT split (applies after the latest
 * effective_to). If there's no history, behaviour is identical to
 * getLandlordShares (current split for every month).
 */
export function getLandlordSharesForPeriod(property, periodMonth) {
  if (!property) return [];
  const history = Array.isArray(property.ownership_history) ? property.ownership_history : [];
  if (history.length && periodMonth) {
    // Earliest-first; a period belongs to the first record whose window covers it.
    const sorted = [...history]
      .filter(h => h && h.effective_to && Array.isArray(h.shares) && h.shares.length)
      .sort((a, b) => a.effective_to.localeCompare(b.effective_to));
    for (const h of sorted) {
      if (periodMonth <= h.effective_to) {
        const cleaned = h.shares
          .filter(s => s && s.landlord_id && Number(s.share_pct) > 0)
          .map(s => ({ landlord_id: s.landlord_id, share_pct: Number(s.share_pct) }));
        if (cleaned.length) return cleaned;
      }
    }
  }
  // No historical window matched → current split.
  return getLandlordShares(property);
}

/**
 * True when the property is owned by exactly one landlord and that landlord is
 * the legacy primary. In this case every downstream computation must behave
 * identically to the pre-multi-landlord code.
 */
export function isSingleLandlord(property) {
  const shares = getLandlordShares(property);
  return shares.length <= 1 &&
    (shares.length === 0 || shares[0].landlord_id === property.landlord_id);
}

export function isMultiLandlord(property) {
  return getLandlordShares(property).length > 1;
}

/** The primary landlord id = largest share (ties → first). Falls back to property.landlord_id. */
export function primaryLandlordId(property) {
  const shares = getLandlordShares(property);
  if (shares.length === 0) return property?.landlord_id || null;
  return [...shares].sort((a, b) => b.share_pct - a.share_pct)[0].landlord_id;
}

/** Total of declared shares (used for validation + proportional fallback). */
export function totalShare(shares) {
  return (shares || []).reduce((s, x) => s + (Number(x.share_pct) || 0), 0);
}

/**
 * Split a monetary amount across shares so the parts sum EXACTLY to
 * round(amount, 2). Allocation is proportional to share_pct (works even if the
 * shares don't sum to 100 — they're treated as weights). Any rounding remainder
 * is given to the largest share, so no penny is ever lost or invented.
 *
 * Returns [{ landlord_id, share_pct, fraction, amount }] in the SAME ORDER as
 * the input shares.
 */
export function splitByShares(amount, shares) {
  const list = (shares || []).filter(s => s && s.landlord_id);
  if (list.length === 0) return [];

  const round2 = (n) => Math.round((n + Number.EPSILON) * 100) / 100;
  const target = round2(amount || 0);
  const weightTotal = list.reduce((s, x) => s + (Number(x.share_pct) || 0), 0);

  // Degenerate: no positive weights → everything to the first landlord.
  if (weightTotal <= 0) {
    return list.map((s, i) => ({
      landlord_id: s.landlord_id,
      share_pct: Number(s.share_pct) || 0,
      fraction: i === 0 ? 1 : 0,
      amount: i === 0 ? target : 0,
    }));
  }

  const parts = list.map(s => {
    const fraction = (Number(s.share_pct) || 0) / weightTotal;
    return { landlord_id: s.landlord_id, share_pct: Number(s.share_pct) || 0, fraction, amount: round2(target * fraction) };
  });

  // Reconcile rounding drift onto the largest-weight share.
  const allocated = round2(parts.reduce((s, p) => s + p.amount, 0));
  const drift = round2(target - allocated);
  if (drift !== 0) {
    let biggest = 0;
    for (let i = 1; i < parts.length; i++) if (parts[i].share_pct > parts[biggest].share_pct) biggest = i;
    parts[biggest].amount = round2(parts[biggest].amount + drift);
  }
  return parts;
}

/** Build a display label like "Ali (60%) · Sara (40%)". */
export function sharesLabel(property, landlords = []) {
  return getLandlordShares(property)
    .map(s => {
      const l = landlords.find(x => x.id === s.landlord_id);
      return `${l?.name || 'Unknown'} (${s.share_pct}%)`;
    })
    .join(' · ');
}

/**
 * Auto-generates a ledger from existing data + manual adjustments.
 * Sources: RentPayments + CommissionLedger + LandlordPayouts + Expenses + LedgerAdjustments
 */
import { format, parseISO } from 'date-fns';

export function buildLedger({ rentPayments, commissionLedger, landlordPayouts, expenses, properties, tenants, landlords, adjustments = [] }) {
  const entries = [];

  // --- RENT PAYMENTS ---
  rentPayments.forEach(rp => {
    const tenant = tenants.find(t => t.id === rp.tenant_id);
    const property = properties.find(p => p.id === rp.property_id);
    const landlord = landlords.find(l => l.id === rp.landlord_id);
    const ledgerEntry = commissionLedger.find(e => e.rent_payment_id === rp.id);
    const cashFrom = rp.method === 'cash' && rp.reference ? ` · cash from ${rp.reference}` : '';

    entries.push({
      id: `rent-${rp.id}`,
      ref_id: rp.id,
      ref_type: 'RentPayment',
      date: rp.payment_date,
      type: 'Income',
      category: 'Rent',
      description: `(${rp.period_month})${property?.address?.split(',')[0] ||''}${cashFrom}`,
      property_id: rp.property_id,
      property_address: property?.address || '',
      tenant_id: rp.tenant_id,
      tenant_name: tenant?.name || '',
      landlord_id: rp.landlord_id,
      landlord_name: landlord?.name || '',
      amount: rp.amount,
      payment_method: rp.method || 'bank_transfer',
      received_in_bank_name: rp.received_in_bank_name || '',
    });


  });

  // --- COMMISSION DEDUCTIONS ---
  commissionLedger.forEach(entry => {
    if (!entry.commission_amount || entry.commission_amount <= 0) return;
    const rentPayment = rentPayments.find(r => r.id === entry.rent_payment_id);
    const property = properties.find(p => p.id === entry.property_id);
    const landlord = landlords.find(l => l.id === entry.landlord_id);
    entries.push({
      id: `commission-${entry.id}`,
      ref_id: entry.id,
      ref_type: 'Commission',
      date: entry.date || rentPayment?.payment_date,
      type: 'Expense',
      category: 'Commission',
      description: `Agency commission — ${property?.address?.split(',')[0] || ''} (${entry.period_month}) · ${entry.commission_type === 'percentage' ? `${entry.commission_rate}%` : `£${entry.commission_rate} fixed`}`,
      property_id: entry.property_id || '',
      property_address: property?.address || '',
      landlord_id: entry.landlord_id || '',
      landlord_name: landlord?.name || '',
      amount: entry.commission_amount,
      commission_rate: entry.commission_rate,
      commission_type: entry.commission_type,
      period_month: entry.period_month,
    });
  });

  // --- LANDLORD PAYOUTS ---
  landlordPayouts.forEach(payout => {
    const landlord = landlords.find(l => l.id === payout.landlord_id);
    const property = properties.find(p => p.id === payout.property_id);
    const isSplit = payout.payment_mode === 'split';

    // Split: record bank portion only (cash goes to cash ledger separately)
    const amount = isSplit ? (payout.bank_amount || 0) : (payout.amount || 0);
    if (amount <= 0) return;

    const bankName = isSplit ? (payout.split_bank_name || '') : (payout.paid_from_bank_name || '');
    const isCashPayout = payout.method === 'cash' || isSplit;
    const refLabel = payout.reference ? ` (${isCashPayout ? 'cash to ' : ''}${payout.reference})` : '';

    entries.push({
      id: `payout-${payout.id}`,
      ref_id: payout.id,
      ref_type: 'LandlordPayout',
      date: isSplit ? (payout.bank_date || payout.payment_date) : payout.payment_date,
      type: 'Expense',
      category: 'Landlord Payment',
      description: `${landlord?.name || 'Unknown'} — ${property?.address?.split(',')[0] || ''}${refLabel}`,
      property_id: payout.property_id || '',
      property_address: property?.address || '',
      landlord_id: payout.landlord_id,
      landlord_name: landlord?.name || '',
      amount,
      payment_method: isSplit ? 'split (bank)' : (payout.method || 'bank_transfer'),
      received_in_bank_name: bankName,
    });
  });

  // --- EXPENSES ---
  //expenses.forEach(exp => {
  expenses.filter(exp => exp.paid_by !== 'landlord' || exp.approved === true).forEach(exp => {
    const property = properties.find(p => p.id === exp.property_id);
    const landlord = landlords.find(l => l.id === exp.landlord_id);
    const tenant = tenants.find(t => t.id === exp.tenant_id);
    entries.push({
      id: `expense-${exp.id}`,
      ref_id: exp.id,
      ref_type: 'Expense',
      date: exp.date,
      type: 'Expense',
      category: 'Expense',
      description: `${exp.description} [${exp.category}]  —  paid by ${exp.paid_by}`,
      property_id: exp.property_id,
      property_address: property?.address || '',
      tenant_id: exp.tenant_id || '',
      tenant_name: tenant?.name || '',
      landlord_id: exp.landlord_id || '',
      landlord_name: landlord?.name || '',
      amount: exp.amount,
      paid_by: exp.paid_by,
    });
  });

  // --- MANUAL ADJUSTMENTS ---
  adjustments.forEach(adj => {
    const property = properties.find(p => p.id === adj.property_id);
    const landlord = landlords.find(l => l.id === adj.landlord_id);
    entries.push({
      id: `adj-${adj.id}`,
      ref_id: adj.id,
      ref_type: 'Adjustment',
      date: adj.date,
      type: adj.type,
      category: 'Adjustment',
      description: adj.description,
      property_id: adj.property_id || '',
      property_address: property?.address || '',
      landlord_id: adj.landlord_id || '',
      landlord_name: landlord?.name || '',
      amount: adj.amount,
      reason: adj.reason,
      is_manual: true,
    });
  });

  // Sort by date ascending, then add running balance
  entries.sort((a, b) => {
    const da = a.date ? new Date(a.date) : new Date(0);
    const db = b.date ? new Date(b.date) : new Date(0);
    return da - db;
  });

  let runningBalance = 0;
  entries.forEach(e => {
    if (e.type === 'Income') runningBalance += e.amount;
    else runningBalance -= e.amount;
    e.running_balance = runningBalance;
  });

  return entries;
}

export function groupByDate(entries) {
  const groups = {};
  entries.forEach(e => {
    const key = e.date || 'Unknown';
    if (!groups[key]) groups[key] = [];
    groups[key].push(e);
  });
  return Object.entries(groups)
    .sort(([a], [b]) => new Date(b) - new Date(a))
    .map(([date, items]) => ({ date, items }));
}

export function buildProfitLoss({ commissionLedger, expenses }) {
  const income = commissionLedger.reduce((s, e) => s + (e.commission_amount || 0), 0);
  const agencyExpenses = expenses.filter(e => e.paid_by === 'agency').reduce((s, e) => s + (e.amount || 0), 0);
  return { income, expenses: agencyExpenses, netProfit: income - agencyExpenses };
}

export function buildCashFlow({ rentPayments, landlordPayouts, expenses }) {
  const totalInflow = rentPayments.reduce((s, p) => s + (p.amount || 0), 0);
  const totalOutflow = landlordPayouts.reduce((s, p) => s + (p.amount || 0), 0) +
    expenses.filter(e => e.paid_by === 'agency').reduce((s, e) => s + (e.amount || 0), 0);
  return { totalInflow, totalOutflow, net: totalInflow - totalOutflow };
}

/**
 * Payment Schedule utilities — cycle calculation for landlord paydays
 */
import { addMonths, subMonths, format, isBefore, subDays, differenceInDays } from 'date-fns';
/**
 * Given a landlord's payment_day and a reference date (default: today),
 * return the current active cycle: { start, end, payDate, prevPayDate }
 * Cycle: (payDay+1 of prev month) → (payDay of this month)
 */
/**
 * Clamp paymentDay to the last valid day of the given month.
 * E.g. paymentDay=31 in Feb 2026 → 28; in Apr 2026 → 30; in Jan 2026 → 31.
 */
function clampDayToMonth(paymentDay, year, month) {
  const lastDayOfMonth = new Date(year, month + 1, 0).getDate();
  return Math.min(Math.max(paymentDay || 25, 1), lastDayOfMonth);
}
export function getCurrentCycle(paymentDay, referenceDate = new Date()) {

  const ref = new Date(referenceDate);

  // This month's pay date
  const thisMonthDay = clampDayToMonth(paymentDay, ref.getFullYear(), ref.getMonth());
let payDate = new Date(ref.getFullYear(), ref.getMonth(), thisMonthDay);

  // If today is after or on payDate, cycle is: (day+1 this month) → (day next month)
  // If today is before payDate, cycle is: (day+1 last month) → (day this month)
  let cycleEnd, cycleStart;
  if (ref >= payDate) {
    // We're past this month's payday — current cycle ends next month
    const nextRef = addMonths(payDate, 1);
const nextDay = clampDayToMonth(paymentDay, nextRef.getFullYear(), nextRef.getMonth());
cycleEnd = new Date(nextRef.getFullYear(), nextRef.getMonth(), nextDay);
cycleStart = new Date(payDate.getFullYear(), payDate.getMonth(), payDate.getDate() + 1);
  } else {
    // We're before this month's payday — current cycle ends this month

    cycleEnd = payDate;
const prevRef = subMonths(payDate, 1);
const prevDay = clampDayToMonth(paymentDay, prevRef.getFullYear(), prevRef.getMonth());
const prevPay = new Date(prevRef.getFullYear(), prevRef.getMonth(), prevDay);
cycleStart = new Date(prevPay.getFullYear(), prevPay.getMonth(), prevPay.getDate() + 1);
  }

  const statementDate = subDays(cycleEnd, 5);
  const daysUntilPay = differenceInDays(cycleEnd, ref);
  const isOverdue = isBefore(cycleEnd, ref);
  const statementDue = ref >= statementDate;

  return {
    cycleStart: format(cycleStart, 'yyyy-MM-dd'),
    cycleEnd: format(cycleEnd, 'yyyy-MM-dd'),
    payDate: format(cycleEnd, 'yyyy-MM-dd'),
    statementDate: format(statementDate, 'yyyy-MM-dd'),
    daysUntilPay,
    isOverdue,
    statementDue,
    label: `${format(cycleStart, 'd MMM')} → ${format(cycleEnd, 'd MMM yyyy')}`,
  };
}

/**
 * Get last N cycles for a landlord (for history)
 */
export function getPastCycles(paymentDay, count = 6) {

  const today = new Date();
  const cycles = [];
  for (let i = 0; i < count; i++) {
    const monthRef = subMonths(new Date(today.getFullYear(), today.getMonth(), 1), i);
const payDay = clampDayToMonth(paymentDay, monthRef.getFullYear(), monthRef.getMonth());
const payDate = new Date(monthRef.getFullYear(), monthRef.getMonth(), payDay);
const prevRef = subMonths(payDate, 1);
const prevDay = clampDayToMonth(paymentDay, prevRef.getFullYear(), prevRef.getMonth());
const prevPay = new Date(prevRef.getFullYear(), prevRef.getMonth(), prevDay);
const cycleStart = new Date(prevPay.getFullYear(), prevPay.getMonth(), prevPay.getDate() + 1);
    cycles.push({
      cycleStart: format(cycleStart, 'yyyy-MM-dd'),
      cycleEnd: format(payDate, 'yyyy-MM-dd'),
      payDate: format(payDate, 'yyyy-MM-dd'),
      label: `${format(cycleStart, 'd MMM')} → ${format(payDate, 'd MMM yyyy')}`,
    });
  }
  return cycles;
}

/**
 * Sum rent payments within a cycle for a specific property
 */
export function sumCycleRent(rentPayments, landlordId, cycleStart, cycleEnd, propertyId = null) {
  return rentPayments
    .filter(rp =>
      rp.landlord_id === landlordId &&
      (!propertyId || rp.property_id === propertyId) &&
      rp.payment_date >= cycleStart && rp.payment_date <= cycleEnd
    )
    .reduce((s, rp) => s + (rp.amount || 0), 0);
}

/**
 * Sum expenses within a cycle for a property (landlord-paid, approved only)
 */
export function sumCycleExpenses(expenses, landlordId, cycleStart, cycleEnd, propertyId = null) {
  return expenses
    .filter(e =>
      e.landlord_id === landlordId &&
      (!propertyId || e.property_id === propertyId) &&
      e.paid_by === 'landlord' && e.approved === true &&
      e.date >= cycleStart && e.date <= cycleEnd
    )
    .reduce((s, e) => s + (e.amount || 0), 0);
}

/**
 * Sum commission within a cycle for a property
 */
export function sumCycleCommission(commissionLedger, rentPayments, landlordId, cycleStart, cycleEnd, propertyId = null) {
  const cycleRentIds = new Set(
    rentPayments
      .filter(rp =>
        rp.landlord_id === landlordId &&
        (!propertyId || rp.property_id === propertyId) &&
        rp.payment_date >= cycleStart && rp.payment_date <= cycleEnd
      )
      .map(rp => rp.id)
  );
  return commissionLedger
    .filter(e => cycleRentIds.has(e.rent_payment_id))
    .reduce((s, e) => s + (e.commission_amount || 0), 0);
}

/**
 * Sum payouts already made within a cycle for a property
 */
export function sumCyclePayouts(landlordPayouts, landlordId, cycleStart, cycleEnd, propertyId = null) {
  return landlordPayouts
    .filter(p =>
      p.landlord_id === landlordId &&
      (!propertyId || p.property_id === propertyId) &&
      p.payment_date >= cycleStart && p.payment_date <= cycleEnd
    )
    .reduce((s, p) => s + (p.amount || 0), 0);
}

/**
 * Build cycle summary per property (each property has its own payment_day)
 */
export function buildPropertyCycleSummary({ property, landlord, rentPayments, commissionLedger, expenses, landlordPayouts, paymentExtras = [] }) {
  if (!property.payment_day) return null;
  const cycle = getCurrentCycle(property.payment_day);
  const rentCollected = sumCycleRent(rentPayments, landlord.id, cycle.cycleStart, cycle.cycleEnd, property.id);
  const expensesDeducted = sumCycleExpenses(expenses, landlord.id, cycle.cycleStart, cycle.cycleEnd, property.id);
  const commissionDeducted = sumCycleCommission(commissionLedger, rentPayments, landlord.id, cycle.cycleStart, cycle.cycleEnd, property.id);
  // Use period_month for PaymentExtras (date field is for record only — period_month drives assignment)
  const cyclePeriod = cycle.cycleStart.substring(0, 7);
  const extraDeductions = paymentExtras
    .filter(e => e.landlord_id === landlord.id && e.property_id === property.id && (e.period_month === cyclePeriod || (!e.period_month && e.date >= cycle.cycleStart && e.date <= cycle.cycleEnd)))
    .reduce((s, e) => s + (e.amount || 0), 0);
  const payable = rentCollected - commissionDeducted - expensesDeducted - extraDeductions;
  const alreadyPaid = sumCyclePayouts(landlordPayouts, landlord.id, cycle.cycleStart, cycle.cycleEnd, property.id);
  const balance = payable - alreadyPaid;

  let status = 'Pending';
  if (alreadyPaid >= payable && payable > 0) status = 'Paid';
  else if (alreadyPaid > 0) status = 'Partial';
  else if (cycle.isOverdue && payable > 0) status = 'Overdue';

  return { ...cycle, property, landlord, rentCollected, expensesDeducted, commissionDeducted, extraDeductions, payable, alreadyPaid, balance, status };
}

/**
 * Backward-compat wrapper — builds per-property summaries for a landlord
 */
export function buildCycleSummary({ landlord, rentPayments, commissionLedger, expenses, landlordPayouts, paymentExtras = [], properties = [] }) {
  const landlordProps = properties.filter(p => p.landlord_id === landlord.id && p.payment_day);
  if (landlordProps.length === 0) return null;
  // Return summary for the earliest upcoming pay date
  const summaries = landlordProps
    .map(prop => buildPropertyCycleSummary({ property: prop, landlord, rentPayments, commissionLedger, expenses, landlordPayouts, paymentExtras }))
    .filter(Boolean)
    .sort((a, b) => a.payDate.localeCompare(b.payDate));
  return summaries[0] || null;
}

/**
 * Landlord payout bank accounts.
 *
 * A landlord can have several bank accounts. Each property they own is paid into
 * one of them (chosen per property). Backward-compat: if a landlord only has the
 * old flat fields (account_number etc.), we treat that as a single "Main account".
 */

export function genAccountId() {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) return `acc_${crypto.randomUUID().slice(0, 8)}`;
  return `acc_${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
}

/** Normalised list of the landlord's bank accounts (seeds one from legacy flat fields). */
export function getLandlordAccounts(landlord) {
  if (!landlord) return [];
  const list = Array.isArray(landlord.bank_accounts) ? landlord.bank_accounts.filter(Boolean) : [];
  if (list.length > 0) return list;
  // Legacy fallback: synthesise a single account from the old flat fields.
  if (landlord.account_number || landlord.sort_code || landlord.bank_name || landlord.account_name) {
    return [{
      id: 'default',
      label: 'Main account',
      account_name: landlord.account_name || '',
      bank_name: landlord.bank_name || '',
      sort_code: landlord.sort_code || '',
      account_number: landlord.account_number || '',
      payment_reference: landlord.payment_reference || '',
      is_default: true,
    }];
  }
  return [];
}

export function defaultAccount(landlord) {
  const accts = getLandlordAccounts(landlord);
  return accts.find(a => a.is_default) || accts[0] || null;
}

/** The account a given property pays into for a given landlord. */
export function resolvePayoutAccount(property, landlord) {
  const accts = getLandlordAccounts(landlord);
  const mapping = Array.isArray(property?.payout_accounts) ? property.payout_accounts : [];
  const entry = mapping.find(m => m && m.landlord_id === (landlord?.id));
  if (entry && entry.account_id) {
    const found = accts.find(a => a.id === entry.account_id);
    if (found) return found;
  }
  // Legacy fallback: an inline per-property override (older model).
  const overrides = Array.isArray(property?.payout_bank_accounts) ? property.payout_bank_accounts : [];
  const o = overrides.find(a => a && a.landlord_id === (landlord?.id)) || overrides.find(a => a && !a.landlord_id);
  if (o && (o.account_number || o.sort_code || o.bank_name || o.account_name)) {
    return {
      id: 'override', label: 'Property account',
      account_name: o.account_name || '', bank_name: o.bank_name || '',
      sort_code: o.sort_code || '', account_number: o.account_number || '',
      payment_reference: o.reference || o.payment_reference || '',
    };
  }
  return defaultAccount(landlord);
}

/** Short one-line label for an account, e.g. "Barclays · 20-00-00 12345678". */
export function accountLine(acc) {
  if (!acc) return '';
  return [acc.bank_name, [acc.sort_code, acc.account_number].filter(Boolean).join(' ')]
    .filter(Boolean).join(' · ');
}

/** Upsert the (landlord → account) choice for a property. Returns the new payout_accounts array. */
export function setPropertyPayoutAccount(property, landlordId, accountId) {
  const mapping = Array.isArray(property?.payout_accounts) ? [...property.payout_accounts] : [];
  const idx = mapping.findIndex(m => m && m.landlord_id === landlordId);
  if (accountId) {
    if (idx >= 0) mapping[idx] = { landlord_id: landlordId, account_id: accountId };
    else mapping.push({ landlord_id: landlordId, account_id: accountId });
  } else if (idx >= 0) {
    mapping.splice(idx, 1);
  }
  return mapping;
}

/**
 * PDF generation for Tenant Invoices and Landlord Statements using jsPDF.
 */
import jsPDF from 'jspdf';
import { format, parseISO } from 'date-fns';

import { businessConfig } from '@/lib/businessConfig';
const BRAND = { name: businessConfig.name, tagline: businessConfig.tagline, primary: businessConfig.brandColor };
const LOGO_URL = businessConfig.logoUrl;

async function loadImageAsDataUrl(url) {
  return new Promise((resolve) => {
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = () => {
      const canvas = document.createElement('canvas');
      canvas.width = img.width;
      canvas.height = img.height;
      canvas.getContext('2d').drawImage(img, 0, 0);
      resolve(canvas.toDataURL('image/png'));
    };
    img.onerror = () => resolve(null);
    img.src = url;
  });
}

function fmtCurrency(amount) {
  return new Intl.NumberFormat('en-GB', { style: 'currency', currency: 'GBP' }).format(amount || 0);
}

function drawHeader(doc, title, number, date, logoDataUrl) {
  // Brand block — white background with dark border
  doc.setFillColor(255, 255, 255);
  doc.rect(0, 0, 210, 28, 'F');
  doc.setDrawColor(200, 200, 200);
  doc.setLineWidth(0.5);
  doc.line(0, 28, 210, 28);

  // Logo or text fallback
  if (logoDataUrl) {
    doc.addImage(logoDataUrl, 'PNG', 14, 2, 40, 24);
  } else {
    doc.setFontSize(18);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(50, 50, 50);
    doc.text(BRAND.name, 14, 12);
    doc.setFontSize(8);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(100, 100, 100);
    doc.text(BRAND.tagline, 14, 18);
  }

  // Company details next to the logo (matches the manual invoice header)
  doc.setFontSize(8);
  doc.setTextColor(60, 60, 60);
  doc.setFont('helvetica', 'bold');
  doc.text('ASA Estates Ltd.', 58, 8);
  doc.setFont('helvetica', 'normal');
  doc.text('320 Romford Road, London, E7 8BD', 58, 13);
  doc.text('Ph: 02084724466 | Fax: 02084724466', 58, 17);
  doc.text('Email: info@asaestates.com', 58, 21);

  // Title + number
  doc.setFontSize(22);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(...BRAND.primary);
  doc.text(title, 14, 42);
  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(80, 80, 80);
  doc.text(`${number}`, 14, 50);
  doc.text(`Date: ${date}`, 130, 42);

  // Divider
  doc.setDrawColor(...BRAND.primary);
  doc.setLineWidth(0.5);
  doc.line(14, 55, 196, 55);
}

function drawInfoBlock(doc, leftLabel, leftData, rightLabel, rightData, y) {
  doc.setFontSize(9);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(...BRAND.primary);
  doc.text(leftLabel, 14, y);
  doc.text(rightLabel || '', 110, y);

  doc.setFont('helvetica', 'normal');
  doc.setTextColor(60, 60, 60);
  let ly = y + 6;
  leftData.forEach(line => {
    doc.splitTextToSize(String(line ?? ''), 94).forEach(w => { doc.text(w, 14, ly); ly += 5; });
  });
  let ry = y + 6;
  if (rightData) {
    rightData.forEach(line => {
      doc.splitTextToSize(String(line ?? ''), 86).forEach(w => { doc.text(w, 110, ry); ry += 5; });
    });
  }
  return Math.max(ly, ry);
}

function drawTable(doc, headers, rows, y) {
  const colWidths = headers.map(h => h.width);
  const colX = [];
  let cx = 14;
  colWidths.forEach(w => { colX.push(cx); cx += w; });
  const rowH = 8;

  // Header
  doc.setFillColor(245, 247, 255);
  doc.rect(14, y, 182, rowH, 'F');
  doc.setFontSize(8.5);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(...BRAND.primary);
  headers.forEach((h, i) => {
    const x = h.align === 'right' ? colX[i] + colWidths[i] - 2 : colX[i] + 2;
    doc.text(h.label, x, y + 5.5, { align: h.align === 'right' ? 'right' : 'left' });
  });

  doc.setFont('helvetica', 'normal');
  doc.setTextColor(50, 50, 50);
  let ry = y + rowH;

  rows.forEach((row, ri) => {
    // wrap each cell to its column width so long text doesn't overflow into neighbouring columns
    doc.setFontSize(8.5);
    doc.setFont('helvetica', 'normal');
    const wrapped = row.map((cell, ci) => doc.splitTextToSize(String(cell ?? ''), colWidths[ci] - 4));
    const lineCount = Math.max(...wrapped.map(w => w.length), 1);
    const rowHh = Math.max(rowH, lineCount * 4 + 4);
    if (ri % 2 === 0) {
      doc.setFillColor(252, 252, 255);
      doc.rect(14, ry, 182, rowHh, 'F');
    }
    doc.setTextColor(50, 50, 50);
    row.forEach((cell, ci) => {
      const h = headers[ci];
      const x = h.align === 'right' ? colX[ci] + colWidths[ci] - 2 : colX[ci] + 2;
      doc.text(wrapped[ci], x, ry + 5.5, { align: h.align === 'right' ? 'right' : 'left' });
    });
    ry += rowHh;
  });

  // bottom line
  doc.setDrawColor(200, 210, 240);
  doc.setLineWidth(0.3);
  doc.line(14, ry, 196, ry);
  return ry + 4;
}

function drawTotalsBox(doc, lines, y) {
  const boxW = 90;
  const boxX = 196 - boxW;
  let by = y + 4;
  lines.forEach(({ label, value, bold, highlight }) => {
    if (bold || highlight) {
      doc.setFont('helvetica', 'bold');
      if (highlight) {
        doc.setFillColor(...BRAND.primary);
        doc.rect(boxX - 2, by - 4, boxW + 4, 8, 'F');
        doc.setTextColor(255, 255, 255);
      } else {
        doc.setTextColor(30, 30, 30);
      }
    } else {
      doc.setFont('helvetica', 'normal');
      doc.setTextColor(60, 60, 60);
    }
    doc.setFontSize(9);
    doc.text(label, boxX + 2, by);
    doc.text(value, 194, by, { align: 'right' });
    by += 8;
    doc.setTextColor(60, 60, 60);
  });
  return by + 4;
}

function drawStatusBadge(doc, status, y) {
  const colors = { Paid: [16, 185, 129], Partial: [245, 158, 11], Unpaid: [239, 68, 68] };
  const [r, g, b] = colors[status] || [100, 100, 100];
  doc.setFillColor(r, g, b);
  doc.roundedRect(14, y, 28, 8, 2, 2, 'F');
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(9);
  doc.setTextColor(255, 255, 255);
  doc.text(status.toUpperCase(), 28, y + 5.5, { align: 'center' });
}

function drawFooter(doc) {
  const pageH = doc.internal.pageSize.height;
  doc.setFillColor(255, 255, 255);
  doc.rect(0, pageH - 14, 210, 14, 'F');
  doc.setFontSize(7.5);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(130, 130, 160);
  doc.text(`${BRAND.name} · Generated ${format(new Date(), 'dd MMM yyyy HH:mm')}`, 14, pageH - 5);
  doc.text('This is a system-generated document', 196, pageH - 5, { align: 'right' });
}

export async function getTenantInvoicePDFBlob(invoice) {
  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
  const logoDataUrl = await loadImageAsDataUrl(LOGO_URL);
  const invoiceDate = invoice.invoice_date ? format(parseISO(invoice.invoice_date), 'dd MMM yyyy') : format(new Date(), 'dd MMM yyyy');
  const dueDate = invoice.due_date ? format(parseISO(invoice.due_date), 'dd MMM yyyy') : '-';
  drawHeader(doc, 'RENT INVOICE', invoice.invoice_number, invoiceDate, logoDataUrl);
  let y = 62;
  drawStatusBadge(doc, invoice.status, y);
  y += 14;
  const billedToLines = [
    invoice.tenant_name,
    ...(invoice.unit_description ? [invoice.unit_description] : []),
    invoice.tenant_email || '',
    invoice.property_address,
  ].filter(Boolean);
  y = drawInfoBlock(doc, 'BILLED TO', billedToLines, 'INVOICE DETAILS', [`Invoice No: ${invoice.invoice_number}`, `Period: ${invoice.period_month}`, `Due Date: ${dueDate}`], y);
  y += 6;
  const lineRows = [['Monthly Rent', invoice.period_month, fmtCurrency(invoice.rent_amount)]];
  if (invoice.discount > 0) lineRows.push([invoice.discount_reason ? `Discount — ${invoice.discount_reason}` : 'Discount', invoice.period_month, `- ${fmtCurrency(invoice.discount)}`]);
  if (invoice.arrears > 0) lineRows.push(['Outstanding Arrears (prior months)', 'Carried forward', fmtCurrency(invoice.arrears)]);
  if (invoice.carried_balance > 0) lineRows.push(['Opening Balance (carried forward)', 'Pre-existing', fmtCurrency(invoice.carried_balance)]);
  (invoice.manual_charges || []).forEach(c => lineRows.push([c.description || 'Charge', invoice.period_month, fmtCurrency(c.amount)]));
  y = drawTable(doc, [{ label: 'Description', width: 90, align: 'left' }, { label: 'Period', width: 40, align: 'left' }, { label: 'Amount', width: 52, align: 'right' }], lineRows, y);
  y += 4;
  const totals = [{ label: 'Rent', value: fmtCurrency(invoice.rent_amount) }];
  if (invoice.discount > 0) totals.push({ label: invoice.discount_reason ? `Discount (${invoice.discount_reason})` : 'Discount', value: `- ${fmtCurrency(invoice.discount)}` });
  if (invoice.arrears > 0) totals.push({ label: 'Arrears', value: fmtCurrency(invoice.arrears) });
  if (invoice.carried_balance > 0) totals.push({ label: 'Opening Balance', value: fmtCurrency(invoice.carried_balance) });
  if (invoice.manual_charges_total > 0) totals.push({ label: 'Additional Charges', value: fmtCurrency(invoice.manual_charges_total) });
  if (invoice.total_paid > 0) totals.push({ label: 'Amount Paid', value: `- ${fmtCurrency(invoice.total_paid)}` });
  if (invoice.overpaid > 0) {
    totals.push({ label: 'Credit (refund due)', value: `- ${fmtCurrency(invoice.overpaid)}`, bold: true, highlight: true });
  } else {
    totals.push({ label: 'Balance Due', value: fmtCurrency(invoice.balance_due), bold: true, highlight: true });
  }
  y = drawTotalsBox(doc, totals, y);
  if (invoice.payments?.length > 0) {
    y += 4;
    doc.setFontSize(9); doc.setFont('helvetica', 'bold'); doc.setTextColor(...BRAND.primary);
    doc.text('PAYMENTS RECEIVED', 14, y); y += 4;
    y = drawTable(doc, [{ label: 'Date', width: 50, align: 'left' }, { label: 'Method', width: 60, align: 'left' }, { label: 'Amount', width: 72, align: 'right' }], invoice.payments.map(p => [p.payment_date ? format(parseISO(p.payment_date), 'dd MMM yyyy') : '-', p.method?.replace(/_/g, ' ') || '-', fmtCurrency(p.amount)]), y);
  }
  drawFooter(doc);
  return doc.output('blob');
}

export async function downloadTenantInvoicePDF(invoice) {
  const blob = await getTenantInvoicePDFBlob(invoice);
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `${invoice.invoice_number}-${invoice.tenant_name.replace(/\s+/g, '_')}.pdf`;
  a.click();
  URL.revokeObjectURL(url);
}

export async function getLandlordStatementPDFBlob(stmt) {
  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
  const logoDataUrl = await loadImageAsDataUrl(LOGO_URL);
  const stmtDate = format(new Date(), 'dd MMM yyyy');
  drawHeader(doc, 'LANDLORD STATEMENT', stmt.statement_number, stmtDate, logoDataUrl);
  let y = 62;
  drawStatusBadge(doc, stmt.status, y);
  y += 14;
  const payoutDates = (stmt.payout_entries || []).filter(p => p.payment_date).map(p => format(parseISO(p.payment_date), 'dd MMM yyyy')).join(', ');
  // jsPDF's built-in helvetica font can't render the → arrow (shows as '!'),
  // so swap it for a plain ' to ' in the PDF only — the on-screen table keeps →.
  const periodDisplay = (stmt.coverage_label ? stmt.coverage_label : (stmt.rent_frequency === 'quarterly' && stmt.cycle_label ? stmt.cycle_label : stmt.period_month)).replace(/→/g, ' to ');
  y = drawInfoBlock(doc, 'LANDLORD', [stmt.landlord_name, stmt.landlord_email || ''], 'STATEMENT DETAILS', [`Statement No: ${stmt.statement_number}`, `Period: ${periodDisplay}`, ...(payoutDates ? [`Date Paid: ${payoutDates}`] : [])], y);
  y += 8;
  doc.setFontSize(9); doc.setFont('helvetica', 'bold'); doc.setTextColor(...BRAND.primary);
  doc.text('PROPERTY BREAKDOWN', 14, y); y += 4;
  y = drawTable(doc, [{ label: 'Property', width: 130, align: 'left' }, { label: 'Payable', width: 52, align: 'right' }], (stmt.properties_breakdown || []).map(p => [p.address.split(',')[0], fmtCurrency(p.net)]), y);
  y += 4;
  if (stmt.extras?.length > 0) {
    y += 4;
    doc.setFontSize(9); doc.setFont('helvetica', 'bold'); doc.setTextColor(...BRAND.primary);
    doc.text('DEDUCTIONS / EXTRAS', 14, y); y += 4;
    y = drawTable(doc, [{ label: 'Description', width: 90, align: 'left' }, { label: 'Category', width: 50, align: 'left' }, { label: 'Amount', width: 42, align: 'right' }], stmt.extras.map(e => [e.description, e.category || '-', fmtCurrency(e.amount)]), y);
    y += 4;
  }
  // Use invoice_net_payable (bank-only for split payments) so the PDF matches what was actually invoiced
  const invoiceNet = stmt.invoice_net_payable ?? stmt.net_payable;
  const beforeDeductions = (invoiceNet || 0) + (stmt.extras_total || 0) + (stmt.maintenance_total || 0);
  const totalLines = [{ label: 'Net Payable (before deductions)', value: fmtCurrency(beforeDeductions) }];
  if (stmt.extras_total > 0 || stmt.maintenance_total > 0) {
    totalLines.push({ label: 'Deductions', value: `- ${fmtCurrency((stmt.extras_total || 0) + (stmt.maintenance_total || 0))}` });
    totalLines.push({ label: 'Net Payable', value: fmtCurrency(invoiceNet) });
  }
  const paidLabel = stmt.cash_paid_separately > 0 ? 'Paid (Bank Transfer)' : 'Already Paid';
  totalLines.push({ label: paidLabel, value: `- ${fmtCurrency(stmt.paid_this_period)}` });
  totalLines.push({ label: 'Balance Due', value: fmtCurrency(stmt.balance_due), bold: true, highlight: true });
  drawTotalsBox(doc, totalLines, y);
  drawFooter(doc);
  return doc.output('blob');
}

