/**
 * Download a clean bank-only landlord statement for a single bank transfer payout.
 */
export async function downloadSingleBankStatementPDF(payout, landlords, properties) {
  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
  const logoDataUrl = await loadImageAsDataUrl(LOGO_URL);

  const landlord = landlords.find(l => l.id === payout.landlord_id);
  const property = properties.find(p => p.id === payout.property_id);
  const bankAmount = payout.payment_mode === 'split' ? (payout.bank_amount || 0) : (payout.amount || 0);
  const payDate = (payout.bank_date || payout.payment_date)
    ? format(parseISO(payout.bank_date || payout.payment_date), 'dd MMM yyyy')
    : format(new Date(), 'dd MMM yyyy');
  const docNumber = `BNK-${payout.id?.substring(0, 8).toUpperCase()}`;
  const periodLabel = payout.period_month || '—';

  drawHeader(doc, 'LANDLORD BANK STATEMENT', docNumber, payDate, logoDataUrl);

  let y = 62;

  // Bank badge
  doc.setFillColor(...BRAND.primary);
  doc.roundedRect(14, y, 50, 8, 2, 2, 'F');
