/**
 * Annual rent statement for a single property, shown to the landlord.
 * BANK TRANSFERS ONLY — cash receipts are deliberately excluded.
 * payments: [{ dateLabel, monthLabel, tenant, reference, amount }]
 */
export async function downloadYearlyRentStatementPDF({ landlord, property, year, payments, deductions = [] }) {
  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
  const logoDataUrl = await loadImageAsDataUrl(LOGO_URL);
  drawHeader(doc, 'ANNUAL RENT STATEMENT', `April ${year} to March ${Number(year) + 1}`, format(new Date(), 'dd/MM/yyyy'), logoDataUrl);

  let y = drawInfoBlock(
    doc,
    'LANDLORD',
    [landlord?.name || '-', landlord?.address || '', landlord?.email || ''].filter(Boolean),
    'PROPERTY',
    [property?.address || '-'],
    64,
  );
  y += 6;

  const headers = [
    { label: 'Date paid', width: 28 },
    { label: 'Month', width: 24 },
    { label: 'Paid from', width: 48 },
    { label: 'Reference', width: 26 },
    { label: 'Deduction', width: 26, align: 'right' },
    { label: 'Amount', width: 30, align: 'right' },
  ];

  const perPage = 22;
  const total = payments.reduce((s, p) => s + (Number(p.amount) || 0), 0);
  const totalDeduction = payments.reduce((s, p) => s + (Number(p.deduction) || 0), 0);

  if (payments.length === 0) {
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(120, 120, 120);
    doc.setFontSize(10);
    doc.text('No bank payments to the landlord recorded for this property in this year.', 14, y + 6);
    y += 14;
  } else {
    for (let i = 0; i < payments.length; i += perPage) {
      if (i > 0) { doc.addPage(); y = 20; }
      const chunk = payments.slice(i, i + perPage).map(p => [
        p.dateLabel, p.monthLabel, p.detail || '-', p.reference || '-',
        (Number(p.deduction) || 0) > 0 ? `- ${fmtCurrency(p.deduction)}` : '-',
        p.paid === false ? '-' : fmtCurrency(p.amount),
      ]);
      y = drawTable(doc, headers, chunk, y);
    }
  }

  const totalsLines = [{ label: 'Months paid', value: String(payments.filter(p => p.paid !== false).length) }];
  if (totalDeduction > 0) totalsLines.push({ label: 'Total deductions', value: `- ${fmtCurrency(totalDeduction)}` });
  totalsLines.push({ label: 'Total paid to landlord', value: fmtCurrency(total), highlight: true });
  y = drawTotalsBox(doc, totalsLines, y + 2);

  // Itemised deductions breakdown
  if (deductions && deductions.length > 0) {
    if (y > 245) { doc.addPage(); y = 20; }
    y += 4;
    doc.setFontSize(11);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(...BRAND.primary);
    doc.text('Deductions', 14, y);
    y += 4;
    const dHeaders = [
      { label: 'Month', width: 30 },
      { label: 'Description', width: 122 },
      { label: 'Amount', width: 30, align: 'right' },
    ];
    const dTotal = deductions.reduce((s, d) => s + (Number(d.amount) || 0), 0);
    for (let i = 0; i < deductions.length; i += 22) {
      if (i > 0) { doc.addPage(); y = 20; }
      const chunk = deductions.slice(i, i + 22).map(d => [d.monthLabel, d.description, `- ${fmtCurrency(d.amount)}`]);
      y = drawTable(doc, dHeaders, chunk, y);
    }
    drawTotalsBox(doc, [{ label: 'Total deductions', value: `- ${fmtCurrency(dTotal)}`, bold: true }], y + 1);
  }

  drawFooter(doc);
  const safe = (property?.address || 'property').replace(/[^a-z0-9]+/gi, '_').slice(0, 30);
  doc.save(`Annual-Rent-Statement-${year}-${safe}.pdf`);
}

/**
 * Single source of truth for a property's monthly landlord figures.
 * Used by BOTH the Landlord Invoices tab and the Landlord Payments tab so they
 * always agree. Commission is taken from the commission AGREEMENT (applied to
 * expected rent), not the commission ledger — and split by co-ownership share.
 */
import { format, parseISO, addMonths, subDays, startOfMonth, differenceInMonths, isValid, getDate } from 'date-fns';
import { getLandlordShares, getLandlordSharesForPeriod, splitByShares } from '@/lib/landlordShares';
import { getPropertyPayoutFrequency, cycleStartMonth, cycleMonths, forPeriod } from '@/lib/rentFrequency';
import { finalPeriodProration } from '@/lib/computations';

const round2 = (n) => Math.round(((n || 0) + Number.EPSILON) * 100) / 100;

export function buildPropertyMonthlyStatements({
  property, landlord, landlords = [],
  pPayments = [], pLedger = [], pPayouts = [], pExpenses = [], pExtras = [],
  pMaintenance = [], pTenants = [], pCommissionAgreements = [], pRentHistory = [],
}) {
  const { frequency, leaseStartMonth } = getPropertyPayoutFrequency(property, pTenants);
  const cycle = cycleMonths(frequency);

  // Rent history grouped by tenant, so each month bills the rent that was
  // actually in effect then (a mid-tenancy rent increase must not apply to
  // earlier months).
  const historyByTenant = {};
  (pRentHistory || []).forEach(r => {
    (historyByTenant[r.tenant_id] = historyByTenant[r.tenant_id] || []).push(r);
  });
  const rentForTenantPeriod = (t, period) => {
    const hist = historyByTenant[t.id];
    if (!hist || hist.length === 0) return t.monthly_rent || 0;
    let dayPart = '01';
    if (t.lease_start && /^\d{4}-\d{2}-\d{2}$/.test(t.lease_start)) dayPart = t.lease_start.slice(8, 10);
    const periodStart = `${period}-${dayPart}`;
    const active = hist
      .filter(r => r.start_date <= periodStart && (!r.end_date || r.end_date >= periodStart))
      .sort((a, b) => b.start_date.localeCompare(a.start_date));
    if (active.length > 0) return active[0].rent_amount;
    return t.monthly_rent || 0;
  };

  const commissionForPeriod = (period, expectedRent) => {
    const inWindow = (a) =>
      (!a.effective_from || a.effective_from <= period) &&
      (!a.effective_to   || a.effective_to   >= period);
    const agreement =
      pCommissionAgreements.find(a => a.landlord_id === landlord?.id && a.property_id === property?.id && inWindow(a)) ||
      pCommissionAgreements.find(a => a.landlord_id === landlord?.id && !a.property_id && inWindow(a));
    if (!agreement) return 0;
    // No rent expected for this month (e.g. property vacant) → no commission.
    // Commission is a fee on rent; charging it on a rentless month produces a
    // spurious negative landlord invoice.
    if (!(expectedRent > 0)) return 0;
    if (agreement.type === 'percentage')    return (expectedRent * agreement.value) / 100;
    if (agreement.type === 'fixed_monthly') return agreement.value * cycle;
    if (agreement.type === 'one_time' && !agreement.one_time_applied) return agreement.value;
    return 0;
  };

  // Does this tenancy generate a rent cycle in the given calendar month?
  // Rent-day aware: a month only counts if the tenancy was still active on that
  // month's due day (the tenant's lease-start day, clamped for short months).
  // e.g. cycles 17th→16th ending 16 Jul: July's due day (17 Jul) was never
  // reached, so July generates nothing — the final cycle belongs to June.
  const tenantCoversMonth = (t, period) => {
    if (!t.lease_start) return false;
    const startMonth = t.lease_start.substring(0, 7);
    if (startMonth > period) return false;
    if (period === startMonth) return true; // first month always counts
    if (!t.lease_end) return true;
    if (t.lease_end.substring(0, 7) < period) return false;
    const [yr, mo] = period.split('-').map(Number);
    const dim = new Date(yr, mo, 0).getDate();
    const day = Math.min(Number(t.lease_start.substring(8, 10)) || 1, dim);
    const dueDate = `${period}-${String(day).padStart(2, '0')}`;
    return t.lease_end >= dueDate;
  };

  const expectedRentForPeriod = (period) => {
    const [yr, mo] = period.split('-').map(Number);
    const periodStart = `${period}-01`;
    const periodEnd = format(new Date(yr, mo, 0), 'yyyy-MM-dd');
    const overlap = pTenants.filter(t => tenantCoversMonth(t, period));
    if (overlap.length > 0) {
      const activeAtEnd = overlap.filter(t => !t.lease_end || t.lease_end >= periodEnd);
      const pool = activeAtEnd.length > 0 ? activeAtEnd : overlap;
      const byUnit = {};
      pool.forEach(t => {
        // Dedup by unit ONLY when a unit description exists (so a re-let room
        // isn't counted twice). HMO rooms with no unit_description are distinct
        // tenancies and must each be keyed separately (by id), otherwise they
        // collapse into one and the property's rent is massively understated.
        const desc = (t.unit_description || '').trim().toLowerCase();
        const unit = desc || `__id_${t.id}`;
        const cur = byUnit[unit];
        if (!cur || (t.lease_start || '') > (cur.lease_start || '')) byUnit[unit] = t;
      });
      // Pro-rate each tenant's rent for their FINAL part-month, so the landlord's
      // expected rent (and the commission derived from it) matches the reduced
      // amount actually owed when the tenant leaves mid-cycle.
      const rent = Object.values(byUnit).reduce((s, t) => {
        const factor = finalPeriodProration(period, t);
        return s + rentForTenantPeriod(t, period) * factor;
      }, 0);
      if (rent > 0) return round2(rent);
    }
    // No tenancy overlaps this month → nothing is owed. (Previously this fell
    // back to the property's headline rent, inventing a full month's rent —
    // and commission on it — for a vacant property.)
    return 0;
  };

  const byMonth = {};
  const today = new Date();
  const ensureMonth = (month) => {
    if (!byMonth[month]) {
      byMonth[month] = { period_month: month, rent_payments: [], commission_entries: [], expense_entries: [], payout_entries: [], extras: [], maintenance_charges: [] };
    }
  };

  if (property?.payment_day) {
    let earliestStr = null;
    pTenants.forEach(t => { if (t.lease_start && (!earliestStr || t.lease_start < earliestStr)) earliestStr = t.lease_start; });
    // No tenant has ever lived here → no landlord invoices at all.
    const earliestDate = earliestStr ? parseISO(earliestStr) : null;
    if (earliestDate && isValid(earliestDate)) {
      const monthsBack = Math.max(0, Math.min(differenceInMonths(today, earliestDate), 24));
      // Only create a month if at least one tenancy overlaps it — once every
      // tenancy has ended, no further landlord invoices are generated.
      const hasTenantInMonth = (month) => pTenants.some(t => tenantCoversMonth(t, month));
      for (let i = 0; i <= monthsBack; i++) {
        const month = format(addMonths(startOfMonth(earliestDate), i), 'yyyy-MM');
        if (!hasTenantInMonth(month)) continue;
        ensureMonth(month);
      }
    }
  }

  pPayments.forEach(p => {
    ensureMonth(p.period_month);
    const tenant = pTenants.find(t => t.id === p.tenant_id);
    byMonth[p.period_month].rent_payments.push({ ...p, tenant_name: tenant?.name || p.tenant_name || '' });
  });
  pLedger.forEach(e => { if (byMonth[e.period_month]) byMonth[e.period_month].commission_entries.push(e); });
  pExpenses.filter(e => e.paid_by === 'landlord' && e.approved === true).forEach(e => {
    const month = (e.date || '').substring(0, 7); if (!month) return;
    ensureMonth(month); byMonth[month].expense_entries.push(e);
  });
  pMaintenance.filter(m => m.charge_to_landlord && !m.linked_extra_id).forEach(m => {
    const cost = m.actual_cost || m.estimated_cost || 0; if (!cost) return;
    const month = m.charge_period || m.period_month || (m.resolved_date || m.scheduled_date || '').substring(0, 7); if (!month) return;
    ensureMonth(month);
    byMonth[month].maintenance_charges.push({ id: m.id, title: m.title, description: m.description, category: m.category, amount: cost, charge_period: month });
  });
  pExtras.forEach(ex => { const month = ex.period_month; if (!month) return; ensureMonth(month); byMonth[month].extras.push(ex); });
  pPayouts.forEach(p => { const month = p.period_month || (p.payment_date || '').substring(0, 7); if (!month) return; ensureMonth(month); byMonth[month].payout_entries.push(p); });

  // For quarterly properties, group months into quarters (anchored to lease start).
  // Each quarter produces ONE statement with 3× the monthly rent and aggregated costs.
  let baseMonths;
  if (frequency === 'quarterly' && leaseStartMonth) {
    const byQuarter = {};
    Object.values(byMonth).forEach(m => {
      const qStart = cycleStartMonth(leaseStartMonth, m.period_month, 'quarterly');
      if (!byQuarter[qStart]) {
        byQuarter[qStart] = { period_month: qStart, rent_payments: [], commission_entries: [], expense_entries: [], payout_entries: [], extras: [], maintenance_charges: [] };
      }
      byQuarter[qStart].rent_payments.push(...m.rent_payments);
      byQuarter[qStart].commission_entries.push(...m.commission_entries);
      byQuarter[qStart].expense_entries.push(...m.expense_entries);
      byQuarter[qStart].payout_entries.push(...m.payout_entries);
      byQuarter[qStart].extras.push(...m.extras);
      byQuarter[qStart].maintenance_charges.push(...m.maintenance_charges);
    });
    baseMonths = Object.values(byQuarter).sort((a, b) => b.period_month.localeCompare(a.period_month));
  } else {
    baseMonths = Object.values(byMonth).sort((a, b) => b.period_month.localeCompare(a.period_month));
  }
  const shares = getLandlordShares(property);
  const isLegacySingle = shares.length <= 1 && (shares.length === 0 || shares[0].landlord_id === property?.landlord_id);

  const bankEntriesOf  = (payouts) => payouts.filter(p => p.payment_mode === 'split' ? (p.bank_amount || 0) > 0 : p.method !== 'cash');
  const cashSeparateOf = (payouts) => payouts.reduce((s, p) => p.payment_mode === 'split' && !p.cash_pending ? s + (p.cash_amount || 0) : s, 0);
  const paidOf         = (payouts) => payouts.reduce((s, p) => p.payment_mode === 'split' ? s + (p.bank_amount || 0) : s + (p.amount || 0), 0);

  const out = [];
  const cycleLabel = (periodMonth) => {
    if (frequency !== 'quarterly') return null;
    try {
      const start = parseISO(`${periodMonth}-01`);
      const end = subDays(addMonths(start, cycle), 1);
      return `${format(start, 'd MMM yyyy')} → ${format(end, 'd MMM yyyy')}`;
    } catch { return null; }
  };

  // Coverage label: the actual dates the rent for this month covers, shown for
  // EVERY month a tenant occupies (e.g. "17 Jun 2026 → 16 Jul 2026"). If the
  // tenant leaves mid-cycle the end date is their lease_end and "(part month)"
  // is appended. Returns null only when no tenant covers the month.
  const coverageLabel = (periodMonth) => {
    try {
      const [yr, mo] = periodMonth.split('-').map(Number);
      const periodEnd = format(new Date(yr, mo, 0), 'yyyy-MM-dd');
      const periodStart = `${periodMonth}-01`;
      const overlap = pTenants.filter(t => tenantCoversMonth(t, periodMonth));
      if (!overlap.length) return null;
      // Pick the tenant whose cycle defines this month (latest lease_start).
      const t = overlap.sort((a, b) => (b.lease_start || '').localeCompare(a.lease_start || ''))[0];
      const sd = parseISO(t.lease_start);
      if (!isValid(sd)) return null;
      const rentDay = getDate(sd);
      const dim = new Date(yr, mo, 0).getDate();
      const cycleStart = new Date(yr, mo - 1, Math.min(rentDay, dim));
      // Cycle end = day before the rent day `cycle` months later (1 month for
      // monthly, 3 months for quarterly), so a quarterly property shows a
      // 3-month span (e.g. 30 Apr -> 29 Jul) instead of a single month.
      const nextDim = new Date(yr, mo - 1 + cycle, 0).getDate();
      const nextStart = new Date(yr, mo - 1 + cycle, Math.min(rentDay, nextDim));
      const normalEnd = new Date(nextStart.getTime() - 86400000);
      // If the tenancy ends within this cycle, use lease_end and flag part month.
      const le = t.lease_end ? parseISO(t.lease_end) : null;
      const endsInCycle = le && isValid(le) && le >= cycleStart && le < normalEnd;
      const end = endsInCycle ? le : normalEnd;
      const label = `${format(cycleStart, 'd MMM yyyy')} → ${format(end, 'd MMM yyyy')}`;
      return endsInCycle ? `${label} (part month)` : label;
    } catch { return null; }
  };

  // Sum the actual expected rent for each calendar month in a cycle, rather than
  // taking the cycle-start month's rent × cycle length. For an HMO where rooms
  // are let on different dates, each month of a quarter can have a different rent
  // total, so multiplying one month ×3 badly under- or over-states the quarter.
  const expectedRentForCycle = (startPeriod) => {
    const [yr, mo] = startPeriod.split('-').map(Number);
    let total = 0;
    for (let i = 0; i < cycle; i++) {
      const d = new Date(yr, mo - 1 + i, 1);
      const mPeriod = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
      total += expectedRentForPeriod(mPeriod);
    }
    return round2(total);
  };

  baseMonths.forEach((m) => {
    const expected_rent = expectedRentForCycle(m.period_month);
    const rent_collected = m.rent_payments.reduce((s, r) => s + (r.amount || 0), 0);
    const commission_total = commissionForPeriod(m.period_month, expected_rent);
    const expenses_total = m.expense_entries.reduce((s, e) => s + (e.amount || 0), 0);
    const extras_total = m.extras.reduce((s, e) => s + (e.amount || 0), 0);
    const maintenance_total = m.maintenance_charges.reduce((s, mc) => s + (mc.amount || 0), 0);
    const net_payable = expected_rent - commission_total - expenses_total - maintenance_total - extras_total;
    const tenant_overpayment = Math.max(0, rent_collected - expected_rent);
    const tenant_shortfall   = Math.max(0, expected_rent - rent_collected);

    // Decide single-vs-split per MONTH using the ownership in effect then, so a
    // month that was co-owned still splits even if the property is now single
    // (and vice-versa).
    const periodShares = getLandlordSharesForPeriod(property, m.period_month);
    const periodIsLegacySingle = periodShares.length <= 1 &&
      (periodShares.length === 0 || periodShares[0].landlord_id === property?.landlord_id);

    if (periodIsLegacySingle) {
      const bank_payout_entries = bankEntriesOf(m.payout_entries);
      const cash_paid_separately = cashSeparateOf(m.payout_entries);
      const paid_this_period = paidOf(m.payout_entries);
      // Show the TRUE net payable (rent − commission − deductions). Do NOT clamp
      // to zero — when deductions exceed rent the negative figure is meaningful
      // (the landlord has been over-deducted). balance_due still clamps at 0.
      const invoice_net_payable = net_payable - cash_paid_separately;
      const balance_due = Math.max(0, invoice_net_payable - paid_this_period);
      const status = balance_due <= 0 ? 'Paid' : paid_this_period > 0 ? 'Partial' : 'Unpaid';
      out.push({
        ...m,
        key: `${property?.id}__${m.period_month}`,
        statement_number: `INV-${m.period_month.replace('-', '')}`,
        landlord_id: landlord?.id,
        landlord_name: landlord?.name || '',
        landlord_email: landlord?.email || '',
        property_address: property?.address || '',
        rent_frequency: frequency,
        cycle_label: cycleLabel(m.period_month),
        coverage_label: coverageLabel(m.period_month),
        expected_rent, agreed_rent: expected_rent, rent_collected,
        tenant_overpayment, tenant_shortfall,
        commission_total, expenses_total, extras_total, maintenance_total,
        net_payable, invoice_net_payable, cash_paid_separately, paid_this_period, bank_payout_entries,
        balance_due, status,
        properties_breakdown: [{ property_id: property?.id, address: property?.address || '', agreed_rent: expected_rent, commission: commission_total, expenses: expenses_total, extras: extras_total, maintenance: maintenance_total, net: invoice_net_payable }],
      });
      return;
    }

    // Ownership split IN EFFECT for this month (past months keep their historical
    // split even after an ownership change).
    const shares = periodShares;
    const netParts = splitByShares(net_payable, shares);
    const co_owners = shares.map(x => ({ landlord_id: x.landlord_id, name: landlords.find(l => l.id === x.landlord_id)?.name || 'Unknown', share_pct: x.share_pct }));
    shares.forEach((sh, si) => {
      const frac = netParts[si].fraction;
      const ll = landlords.find(l => l.id === sh.landlord_id);
      const myPayouts = m.payout_entries.filter(p => p.landlord_id === sh.landlord_id);

      const bank_payout_entries = bankEntriesOf(myPayouts);
      const cash_paid_separately = cashSeparateOf(myPayouts);
      const paid_this_period = paidOf(myPayouts);
      const net_share = netParts[si].amount;
      const invoice_net_payable = net_share - cash_paid_separately;
      const balance_due = Math.max(0, invoice_net_payable - paid_this_period);
      const status = balance_due <= 0 ? 'Paid' : paid_this_period > 0 ? 'Partial' : 'Unpaid';

      out.push({
        ...m,
        key: `${property?.id}__${m.period_month}__${sh.landlord_id}`,
        statement_number: `INV-${m.period_month.replace('-', '')}-${si + 1}`,
        is_co_owned: true,
        share_pct: sh.share_pct,
        co_owners,
        landlord_id: sh.landlord_id,
        landlord_name: ll?.name || 'Unknown',
        landlord_email: ll?.email || '',
        property_address: property?.address || '',
        rent_frequency: frequency,
        cycle_label: cycleLabel(m.period_month),
        coverage_label: coverageLabel(m.period_month),
        rent_payments: m.rent_payments.map(r => ({ ...r, amount: round2((r.amount || 0) * frac) })),
        expense_entries: m.expense_entries.map(e => ({ ...e, amount: round2((e.amount || 0) * frac) })),
        extras: m.extras.map(e => ({ ...e, amount: round2((e.amount || 0) * frac) })),
        maintenance_charges: m.maintenance_charges.map(mc => ({ ...mc, amount: round2((mc.amount || 0) * frac) })),
        payout_entries: myPayouts,
        expected_rent: round2(expected_rent * frac), agreed_rent: round2(expected_rent * frac), rent_collected: round2(rent_collected * frac),
        tenant_overpayment: round2(tenant_overpayment * frac), tenant_shortfall: round2(tenant_shortfall * frac),
        commission_total: round2(commission_total * frac), expenses_total: round2(expenses_total * frac), extras_total: round2(extras_total * frac), maintenance_total: round2(maintenance_total * frac),
        net_payable: net_share, invoice_net_payable, cash_paid_separately, paid_this_period, bank_payout_entries,
        balance_due, status,
        properties_breakdown: [{ property_id: property?.id, address: property?.address || '', agreed_rent: round2(expected_rent * frac), commission: round2(commission_total * frac), expenses: round2(expenses_total * frac), extras: round2(extras_total * frac), maintenance: round2(maintenance_total * frac), net: invoice_net_payable }],
      });
    });
  });
  return out;
}

