/**
 * Shared rent-frequency helpers.
 *
 * A quarterly tenancy is billed every 3 months, anchored to its lease_start.
 * Billing months are leaseStartMonth + 0, 3, 6, 9 … months. Each quarterly
 * invoice covers 3 months and the amount due is 3 × the per-month figure.
 *
 * These helpers are the single source of truth so invoices, the Tenant Rent
 * Dates page and the Landlord Payment Schedule all stay consistent.
 */
import { addMonths, format } from 'date-fns';

const ACTIVE_STATUSES = ['active', 'notice'];

/** Returns 'monthly' or 'quarterly' for a tenant (defaults to monthly). */
export function getFrequency(tenant) {
  return tenant && tenant.rent_frequency === 'quarterly' ? 'quarterly' : 'monthly';
}

/** Number of months a single billing cycle covers. */
export function cycleMonths(frequency) {
  return frequency === 'quarterly' ? 3 : 1;
}

/** Multiply a per-month amount by the cycle length (×3 for quarterly, ×1 for monthly). */
export function forPeriod(monthlyAmount, frequency) {
  return (Number(monthlyAmount) || 0) * cycleMonths(frequency);
}

// month difference (b - a) between two 'yyyy-MM' strings
function monthDiff(aMonth, bMonth) {
  const [ay, am] = aMonth.split('-').map(Number);
  const [by, bm] = bMonth.split('-').map(Number);
  return (by - ay) * 12 + (bm - am);
}

/** Add n months to a 'yyyy-MM' string, returning a 'yyyy-MM' string. */
export function addMonthsStr(monthStr, n) {
  const [y, m] = monthStr.split('-').map(Number);
  return format(addMonths(new Date(y, m - 1, 1), n), 'yyyy-MM');
}

/**
 * Is `month` a billing month for a tenancy anchored to `leaseStartMonth`?
 * Monthly = every month from start; quarterly = every 3rd month from start.
 */
export function isDueMonth(leaseStartMonth, month, frequency) {
  if (!leaseStartMonth || !month) return false;
  const diff = monthDiff(leaseStartMonth, month);
  if (diff < 0) return false;
  return frequency === 'quarterly' ? diff % 3 === 0 : true;
}

/**
 * Snap a month to the start of the billing cycle that owns it.
 * Monthly → the month itself; quarterly → the quarter-start month
 * (leaseStartMonth + floor(diff/3)*3).
 */
export function cycleStartMonth(leaseStartMonth, month, frequency) {
  if (frequency !== 'quarterly' || !leaseStartMonth || !month) return month;
  const diff = monthDiff(leaseStartMonth, month);
  if (diff < 0) return leaseStartMonth;
  return addMonthsStr(leaseStartMonth, Math.floor(diff / 3) * 3);
}

/**
 * Determine a property's rent frequency from its active tenants.
 * Returns { frequency, leaseStartMonth } — quarterly if any active tenant
 * is quarterly (anchored to the earliest such tenant's lease start).
 */
export function getPropertyFrequency(property, tenants) {
  if (!property || !tenants) return { frequency: 'monthly', leaseStartMonth: null };
  const qTenants = tenants
    .filter(t => t.property_id === property.id && ACTIVE_STATUSES.includes(t.status) && t.rent_frequency === 'quarterly' && t.lease_start)
    .sort((a, b) => a.lease_start.localeCompare(b.lease_start));
  if (qTenants.length > 0) {
    return { frequency: 'quarterly', leaseStartMonth: qTenants[0].lease_start.substring(0, 7) };
  }
  return { frequency: 'monthly', leaseStartMonth: null };
}

/**
 * Determine the LANDLORD PAYOUT frequency for a property.
 * Uses the property-level `landlord_payout_frequency` override if set.
 * Falls back to the tenant-derived frequency (getPropertyFrequency).
 *
 * For HMO properties: tenants may pay monthly while the landlord is paid quarterly.
 * The leaseStartMonth for quarterly payout anchoring uses the earliest active tenant.
 */
export function getPropertyPayoutFrequency(property, tenants) {
  if (!property) return { frequency: 'monthly', leaseStartMonth: null };
  const override = property.landlord_payout_frequency;
  if (override === 'quarterly') {
    // Anchor to earliest active (or any) tenant's lease start
    const allTenants = (tenants || [])
      .filter(t => t.property_id === property.id && t.lease_start)
      .sort((a, b) => a.lease_start.localeCompare(b.lease_start));
    const anchor = allTenants[0];
    return { frequency: 'quarterly', leaseStartMonth: anchor ? anchor.lease_start.substring(0, 7) : null };
  }
  if (override === 'monthly') {
    return { frequency: 'monthly', leaseStartMonth: null };
  }
  // No override — derive from tenants (existing behaviour)
  return getPropertyFrequency(property, tenants);
}

