// Central definition of task types and their workflow steps, so the Tasks page
// and the per-property panel stay in sync.

export const TASK_TYPES = {
  general:         { label: 'General',          steps: ['To Do', 'In Progress', 'Done'] },
  rent_increase:   { label: 'Rent Increase',    steps: ['To Serve', 'Served', 'Acknowledged', 'Effective'] },
  gas_safety:      { label: 'Gas Safety',       steps: ['Due', 'Booked', 'Completed', 'Uploaded'] },
  certificate:     { label: 'Certificate',      steps: ['Due', 'Booked', 'Completed', 'Uploaded'] },
  deposit_return:  { label: 'Deposit Return',   steps: ['Requested', 'Calculated', 'Sent', 'Confirmed'] },
  eviction_notice: { label: 'Eviction Notice',  steps: ['Drafted', 'Served', 'Expired', 'Resolved'] },
  inspection:      { label: 'Inspection',       steps: ['Scheduled', 'Done', 'Report Filed'] },
  maintenance:     { label: 'Maintenance',      steps: ['Reported', 'Assigned', 'In Progress', 'Fixed'] },
};

export const TASK_TYPE_KEYS = Object.keys(TASK_TYPES);

export function stepsForType(type) {
  return (TASK_TYPES[type] || TASK_TYPES.general).steps;
}

export function typeLabel(type) {
  return (TASK_TYPES[type] || TASK_TYPES.general).label;
}

// The last step of each type is treated as "done".
export function isDoneStatus(type, status) {
  const steps = stepsForType(type);
  return status === steps[steps.length - 1];
}

export function firstStatus(type) {
  return stepsForType(type)[0];
}

// Colour hint for a status by its position in the workflow (start → end).
export function statusColor(type, status) {
  const steps = stepsForType(type);
  const idx = steps.indexOf(status);
  if (idx < 0) return 'gray';
  if (idx === steps.length - 1) return 'green';   // done
  if (idx === 0) return 'red';                     // not started
  return 'yellow';                                  // in progress
}

// A colour + label for task priority.
export const PRIORITY = {
  low:    { label: 'Low',    color: 'gray' },
  normal: { label: 'Normal', color: 'blue' },
  high:   { label: 'High',   color: 'red' },
};

// ─────────────────────────────────────────────────────────────────────
// Keeps a tenant's status in sync with their lease_end date, so you don't
// have to flip the Status dropdown by hand.
//
//   • lease_end set AND in the past  → status becomes 'ended'
//   • lease_end cleared OR in future  → an 'ended' tenant flips back to 'active'
//
// We deliberately keep the `status` field as the single source of truth
// (the whole app reads status === 'active' / 'ended'), and just derive its
// value from the date. 'notice' is left untouched — it's a manual state.
// ─────────────────────────────────────────────────────────────────────

function endOfDay(d) { const x = new Date(d); x.setHours(23, 59, 59, 999); return x; }

/**
 * Return the status a tenant SHOULD have given their lease_end date.
 * Pass the current status so manual 'notice' is preserved.
 */
export function deriveTenantStatus(leaseEnd, currentStatus) {
  const now = new Date();
  const end = leaseEnd ? new Date(leaseEnd) : null;
  const validEnd = end && !isNaN(end.getTime()) ? end : null;

  // Past lease end → ended (inclusive of the end day itself).
  if (validEnd && endOfDay(validEnd) < now) return 'ended';

  // No end date, or a future end date:
  //  - if they were auto-ended, bring them back to active
  //  - otherwise keep whatever they are (active / notice)
  if (currentStatus === 'ended') return 'active';
  return currentStatus || 'active';
}

/**
 * Apply the derived status onto a tenant payload before save.
 * Returns a new object; does not mutate the input.
 */
export function withDerivedStatus(payload) {
  return { ...payload, status: deriveTenantStatus(payload.lease_end, payload.status) };
}

