// Vacancy analysis shared by the dashboard card and the Vacancies page, so both
// agree on what "empty" and "becoming empty" mean.
//
// A property is:
//   - VACANT NOW    : no tenancy whose lease covers today.
//   - BECOMING EMPTY: has a tenancy whose lease_end is within `days` of today
//                     (and no other tenancy continues past that date).

import { differenceInCalendarDays, parseISO, isValid } from 'date-fns';

const day = (d) => { try { const x = parseISO(d); return isValid(x) ? x : null; } catch { return null; } };

// Does any tenancy cover a given date (yyyy-MM-dd)?
function coveredOn(tenants, propertyId, dateStr) {
  return tenants.some(t =>
    t.property_id === propertyId &&
    t.lease_start && t.lease_start <= dateStr &&
    (!t.lease_end || t.lease_end >= dateStr)
  );
}

export function analyseVacancies(properties = [], tenants = [], { days = 30 } = {}) {
  const today = new Date(); today.setHours(0, 0, 0, 0);
  const todayStr = today.toISOString().slice(0, 10);
  const horizonStr = new Date(today.getTime() + days * 86400000).toISOString().slice(0, 10);

  const vacantNow = [];
  const becomingEmpty = [];

  properties.forEach(p => {
    const pTenants = tenants.filter(t => t.property_id === p.id);
    const activeNow = pTenants.filter(t => t.lease_start && t.lease_start <= todayStr && (!t.lease_end || t.lease_end >= todayStr));

    if (activeNow.length === 0) {
      // No one in it today → vacant. Find when it last emptied (latest lease_end).
      const ended = pTenants.filter(t => t.lease_end).sort((a, b) => (b.lease_end || '').localeCompare(a.lease_end || ''));
      vacantNow.push({
        property: p,
        since: ended[0]?.lease_end || null,
        lastTenant: ended[0]?.name || null,
        everLet: pTenants.length > 0,
      });
      return;
    }

    // Occupied today — is a tenancy ending within the horizon, with nothing
    // continuing past it?
    const endingSoon = activeNow
      .filter(t => t.lease_end && t.lease_end >= todayStr && t.lease_end <= horizonStr)
      .sort((a, b) => (a.lease_end || '').localeCompare(b.lease_end || ''));

    if (endingSoon.length > 0) {
      const t = endingSoon[0];
      // Skip if another tenancy already covers the day after this one ends
      // (i.e. a replacement is lined up — not actually becoming empty).
      const dayAfter = new Date(day(t.lease_end).getTime() + 86400000).toISOString().slice(0, 10);
      if (coveredOn(pTenants, p.id, dayAfter)) return;
      becomingEmpty.push({
        property: p,
        tenant: t,
        endDate: t.lease_end,
        daysLeft: differenceInCalendarDays(day(t.lease_end), today),
      });
    }
  });

  vacantNow.sort((a, b) => (b.since || '').localeCompare(a.since || ''));
  becomingEmpty.sort((a, b) => a.daysLeft - b.daysLeft);
  return { vacantNow, becomingEmpty };
}

import { base44 } from '@/api/base44Client';

// ─────────────────────────────────────────────────────────────────────
// WhatsApp alerts to the manager/admin.
// Fire-and-forget: never throws, so a failed WhatsApp send can never
// block or break the actual record creation.
// Backend: base44/functions/sendWhatsAppAlert (see that file for the
// one-time WHATSAPP_RECIPIENTS setup).
// ─────────────────────────────────────────────────────────────────────

const PRIORITY_TAGS = {
  urgent: '🔴 URGENT',
  high: '🟠 High',
  medium: '🟡 Medium',
  low: '🟢 Low',
};

export async function sendWhatsAppAlert(message) {
  try {
    const res = await base44.functions.invoke('sendWhatsAppAlert', { message });
    return res?.data || { ok: false };
  } catch (err) {
    console.warn('[whatsapp] alert failed:', err?.message || err);
    return { ok: false, error: err?.message };
  }
}

// Sends a message to the fixed maintenance contractor (WHATSAPP_CONTRACTOR secret).
export async function sendToContractor(message) {
  try {
    const res = await base44.functions.invoke('sendWhatsAppAlert', { message, target: 'contractor' });
    return res?.data || { ok: false };
  } catch (err) {
    console.warn('[whatsapp] contractor message failed:', err?.message || err);
    return { ok: false, error: err?.message };
  }
}

export function buildContractorMessage({ request, property, tenant }) {
  const lines = ['🔧 *Maintenance job for you*', ''];
  lines.push(`*Job:* ${request?.title || 'Untitled'}`);
  if (request?.description) {
    const d = String(request.description).trim();
    lines.push(`*Details:* ${d.length > 1500 ? d.slice(0, 1497) + '…' : d}`);
  }
  if (request?.category) lines.push(`*Category:* ${request.category}`);
  if (request?.priority) lines.push(`*Priority:* ${request.priority}`);
  if (property?.address) lines.push('', `*Address:* ${property.address}`);
  if (tenant?.name) {
    lines.push(`*Tenant:* ${tenant.name}${tenant.phone ? ` — ${tenant.phone}` : ''}`);
  }
  if (request?.access_notes) lines.push(`*Access:* ${request.access_notes}`);
  if (request?.notes) lines.push('', `*Notes:* ${request.notes}`);
  lines.push('', 'Please confirm when you can attend. — ASA Estates');
  return lines.join('\n');
}

export function notifyMaintenanceRaised({ request, property, tenant, raisedBy }) {
  const lines = [
    '🔧 *New maintenance job raised*',
    '',
    `*Job:* ${request?.title || 'Untitled'}`,
  ];
  if (request?.description) {
    const desc = String(request.description).trim();
    lines.push(`*Description:* ${desc.length > 1500 ? desc.slice(0, 1497) + '…' : desc}`);
  }
  if (property?.address) lines.push(`*Property:* ${property.address}`);
  if (tenant?.name) {
    lines.push(`*Tenant:* ${tenant.name}${tenant.phone ? ` (${tenant.phone})` : ''}`);
  }
  if (request?.priority) lines.push(`*Priority:* ${PRIORITY_TAGS[request.priority] || request.priority}`);
  if (request?.category) lines.push(`*Category:* ${request.category}`);
  if (raisedBy) lines.push(`*Raised by:* ${raisedBy}`);
  lines.push('', '— ASA Estates');

  // Intentionally not awaited by callers — fire and forget
  return sendWhatsAppAlert(lines.join('\n'));
}

