  update_tenant: { icon: Pencil, label: 'Update tenant', color: 'text-emerald-600' },
  record_rent_payment: { icon: Banknote, label: 'Record rent payment', color: 'text-emerald-700' },
  create_maintenance: { icon: Wrench, label: 'New maintenance request', color: 'text-amber-600' },
  schedule_inspection: { icon: ClipboardCheck, label: 'Schedule inspection', color: 'text-blue-700' },
};

const EXAMPLES = [
  'Add landlord John Smith, 07700 900111, then a 2-bed flat at 14 Katherine Road E7 8PA for £1,650/month under John Smith',
  'Mark 14 Katherine Road as let agreed',
  'Record £1,650 rent received from Sarah Ahmed today by bank transfer',
  'Log a maintenance request for 14 Katherine Road: leaking kitchen tap, high priority',
  'Schedule an inspection at 14 Katherine Road on 5 July 2026 at 11:00',
];

const RESPONSE_SCHEMA = {
  type: 'object',
  properties: {
    actions: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          action: {
            type: 'string',
            enum: ['create_landlord', 'create_property', 'create_tenant', 'update_landlord', 'update_property', 'update_tenant', 'record_rent_payment', 'create_maintenance', 'schedule_inspection'],
          },
          ref: { type: 'string', description: 'temp id to link new records, e.g. L1, P1' },
          landlord_ref: { type: 'string', description: 'property: ref or existing landlord name' },
          property_ref: { type: 'string', description: 'tenant/maintenance/inspection: ref or existing property address' },
          target: { type: 'string', description: 'for updates/payments: name or address of the existing record to act on' },
          name: { type: 'string' }, email: { type: 'string' }, phone: { type: 'string' }, address: { type: 'string' },
          property_type: { type: 'string', description: 'house, flat, studio, commercial, hmo' },
          bedrooms: { type: 'number' }, bathrooms: { type: 'number' },
          monthly_rent: { type: 'number' }, deposit_amount: { type: 'number' },
          council_tax_band: { type: 'string' }, status: { type: 'string' },
          payment_day: { type: 'number' }, listing_type: { type: 'string', description: 'rent or sale' },
          let_agreed: { type: 'boolean' },
          lease_start: { type: 'string', description: 'YYYY-MM-DD' }, lease_end: { type: 'string', description: 'YYYY-MM-DD' },
          unit_description: { type: 'string' },
          amount: { type: 'number' }, payment_date: { type: 'string', description: 'YYYY-MM-DD' },
          period_month: { type: 'string', description: 'YYYY-MM' }, method: { type: 'string', description: 'bank or cash' },
          paid_by: { type: 'string', description: 'for cash payments: name of the person who handed over the cash (required)' },
          title: { type: 'string' }, description: { type: 'string' }, priority: { type: 'string', description: 'low, medium or high' }, category: { type: 'string' },
          appointment_date: { type: 'string', description: 'YYYY-MM-DD' }, appointment_time: { type: 'string', description: 'HH:MM' }, inspector_name: { type: 'string' },
        },
        required: ['action'],
      },
    },
    note: { type: 'string' },
  },
};

const ORDER = { create_landlord: 0, create_property: 1, create_tenant: 2, update_landlord: 3, update_property: 3, update_tenant: 3, record_rent_payment: 4, create_maintenance: 4, schedule_inspection: 4 };

export default function AIAssistant() {
  const queryClient = useQueryClient();
  const { data: landlords = [] } = useLandlords();
  const { data: properties = [] } = useProperties();
  const { data: tenants = [] } = useTenants();

  const [text, setText] = useState('');
  const [interpreting, setInterpreting] = useState(false);
  const [creating, setCreating] = useState(false);
  const [actions, setActions] = useState(null);
  const [note, setNote] = useState('');
  const [error, setError] = useState('');
  const [results, setResults] = useState(null);

  const interpret = async () => {
    if (!text.trim() || interpreting) return;
    setError(''); setActions(null); setResults(null); setNote('');
    setInterpreting(true);
    try {
      const prompt = `You are an agent for a UK property management app (ASA Estates). Convert the instruction into a list of structured actions.

Actions and key fields:
- create_landlord: name (req), email, phone, address. Give it a ref (L1).
- create_property: address (req), monthly_rent (req), landlord_ref (link), property_type, bedrooms, bathrooms, deposit_amount, council_tax_band, listing_type. Give it a ref (P1).
- create_tenant: name (req), property_ref (link), monthly_rent, lease_start (YYYY-MM-DD), lease_end, email, phone, deposit_amount.
- update_property: target (address of existing property), then any of: let_agreed, monthly_rent, status, listing_type, council_tax_band, deposit_amount, bedrooms, bathrooms, payment_day.
- update_landlord: target (existing landlord name), then email/phone/address/status.
- update_tenant: target (existing tenant name), then monthly_rent/lease_end/status.
- record_rent_payment: target (tenant name), amount, payment_date (YYYY-MM-DD), period_month (YYYY-MM), method (bank or cash). For cash, paid_by (name of who handed over the cash) is REQUIRED — never record a cash payment without it.
- create_maintenance: property_ref (address), title, description, priority (low/medium/high), category.
- schedule_inspection: property_ref (address), appointment_date (YYYY-MM-DD), appointment_time (HH:MM), inspector_name.

Rules: only include fields the user gave or that are clearly implied; never invent emails, phones or prices; dates as YYYY-MM-DD; "let agreed" means update_property with let_agreed=true; today's date is ${format(new Date(), 'yyyy-MM-dd')}. If something required is missing, still output the action and note it.

Existing landlords: ${landlords.slice(0, 50).map(l => l.name).filter(Boolean).join('; ') || 'none'}
Existing properties: ${properties.slice(0, 60).map(p => p.address).filter(Boolean).join('; ') || 'none'}
Existing tenants: ${tenants.slice(0, 60).map(t => t.name).filter(Boolean).join('; ') || 'none'}

Instruction:
"""${text.trim()}"""`;

      const res = await base44.integrations.Core.InvokeLLM({ prompt, response_json_schema: RESPONSE_SCHEMA });
      const parsed = typeof res === 'string' ? JSON.parse(res) : res;
      const list = Array.isArray(parsed?.actions) ? parsed.actions : [];
      if (!list.length) { setError('I couldn’t work out any actions from that. Try being more specific.'); return; }
      list.sort((a, b) => (ORDER[a.action] ?? 9) - (ORDER[b.action] ?? 9));
      setActions(list);
      setNote(parsed?.note || '');
    } catch (e) {
      setError(e?.message || 'Could not interpret that. Make sure the AI integration is enabled.');
    } finally {
      setInterpreting(false);
    }
  };

  const byName = (arr, q, key = 'name') => {
    if (!q) return null;
    const s = String(q).toLowerCase();
    return arr.find(x => x[key] && (x[key].toLowerCase() === s || x[key].toLowerCase().includes(s))) || null;
  };
  const resolveLandlordId = (ref, refMap) => refMap[ref] || byName(landlords, ref)?.id || '';
  const resolvePropertyId = (ref, refMap) => refMap[ref] || byName(properties, ref, 'address')?.id || '';

  const runActions = async () => {
    if (!actions || creating) return;
    setCreating(true); setError(''); setResults(null);
    const refMap = {}; const propRent = {}; const done = [];
    const today = format(new Date(), 'yyyy-MM-dd');
    const norm = (m) => (String(m || '').toLowerCase().includes('cash') ? 'cash' : 'bank_transfer');
    try {
      for (const a of actions) {
        switch (a.action) {
          case 'create_landlord': {
            const rec = await base44.entities.Landlord.create({ name: a.name || 'Unnamed landlord', email: a.email || '', phone: a.phone || '', address: a.address || '', status: 'active' });
            if (a.ref) refMap[a.ref] = rec.id;
            done.push({ action: a.action, label: rec.name }); break;
          }
          case 'create_property': {
            const landlord_id = resolveLandlordId(a.landlord_ref, refMap);
            if (!landlord_id) throw new Error(`No landlord found for property "${a.address}".`);
            const p = { landlord_id, address: a.address || '', type: a.property_type || 'flat', bedrooms: a.bedrooms ?? 1, bathrooms: a.bathrooms ?? 1, monthly_rent: a.monthly_rent ?? 0, deposit_amount: a.deposit_amount ?? 0, council_tax_band: a.council_tax_band || '', status: a.status || 'vacant', listing_type: a.listing_type || 'rent' };
            if (a.payment_day) p.payment_day = a.payment_day;
            const rec = await base44.entities.Property.create(p);
            if (a.ref) { refMap[a.ref] = rec.id; propRent[a.ref] = p.monthly_rent; }
            done.push({ action: a.action, label: rec.address }); break;
          }
          case 'create_tenant': {
            const property_id = resolvePropertyId(a.property_ref, refMap);
            if (!property_id) throw new Error(`No property found for tenant "${a.name}".`);
            const rent = a.monthly_rent ?? propRent[a.property_ref] ?? properties.find(p => p.id === property_id)?.monthly_rent ?? 0;
            const rec = await base44.entities.Tenant.create({ property_id, name: a.name || 'Unnamed tenant', email: a.email || '', phone: a.phone || '', monthly_rent: rent, deposit: a.deposit_amount ?? 0, lease_start: a.lease_start || today, lease_end: a.lease_end || '', unit_description: a.unit_description || '', status: a.status || 'active' });
            done.push({ action: a.action, label: rec.name }); break;
          }
          case 'update_property': {
            const prop = byName(properties, a.target || a.address, 'address');
            if (!prop) throw new Error(`Couldn't find property "${a.target || a.address}" to update.`);
            const u = {};
            ['monthly_rent', 'status', 'listing_type', 'council_tax_band', 'deposit_amount', 'bedrooms', 'bathrooms', 'payment_day'].forEach(k => { if (a[k] !== undefined) u[k] = a[k]; });
            if (a.let_agreed !== undefined) u.let_agreed = a.let_agreed;
            await base44.entities.Property.update(prop.id, u);
            done.push({ action: a.action, label: prop.address }); break;
          }
          case 'update_landlord': {
            const ll = byName(landlords, a.target || a.name);
            if (!ll) throw new Error(`Couldn't find landlord "${a.target || a.name}" to update.`);
            const u = {}; ['email', 'phone', 'address', 'status'].forEach(k => { if (a[k] !== undefined) u[k] = a[k]; });
            await base44.entities.Landlord.update(ll.id, u);
            done.push({ action: a.action, label: ll.name }); break;
          }
          case 'update_tenant': {
            const t = byName(tenants, a.target || a.name);
            if (!t) throw new Error(`Couldn't find tenant "${a.target || a.name}" to update.`);
            const u = {}; ['monthly_rent', 'lease_end', 'status', 'phone', 'email'].forEach(k => { if (a[k] !== undefined) u[k] = a[k]; });
            await base44.entities.Tenant.update(t.id, u);
            done.push({ action: a.action, label: t.name }); break;
          }
          case 'record_rent_payment': {
            const t = byName(tenants, a.target || a.name);
            if (!t) throw new Error(`Couldn't find tenant "${a.target || a.name}" to record a payment.`);
            const method = norm(a.method);
            const payer = String(a.paid_by || '').trim();
            if (method === 'cash' && !payer) {
              throw new Error(`Cash payment for "${t.name}" was NOT recorded — the name of the person who handed over the cash is required. Try again and include who paid the cash.`);
            }
            const prop = properties.find(p => p.id === t.property_id);
            await base44.entities.RentPayment.create({
              tenant_id: t.id, property_id: t.property_id, landlord_id: prop?.landlord_id || '',
              amount: a.amount ?? t.monthly_rent ?? 0,
              payment_date: a.payment_date || today,
              period_month: a.period_month || (a.payment_date || today).slice(0, 7),
              method,
              reference: method === 'cash' ? payer : '',
            });
            done.push({ action: a.action, label: `${t.name} · £${a.amount ?? t.monthly_rent ?? 0}` }); break;
          }
          case 'create_maintenance': {
            const property_id = resolvePropertyId(a.property_ref || a.target, refMap);
            if (!property_id) throw new Error(`No property found for the maintenance request.`);
            const tenant = tenants.find(t => t.property_id === property_id);
            const rec = await base44.entities.MaintenanceRequest.create({ property_id, tenant_id: tenant?.id || '', title: a.title || (a.description ? a.description.slice(0, 60) : 'Maintenance'), description: a.description || '', category: a.category || 'general', priority: a.priority || 'medium', status: 'open' });
            notifyMaintenanceRaised({ request: rec, property: properties.find(p => p.id === property_id), tenant, raisedBy: 'AI Assistant' });
            done.push({ action: a.action, label: rec.title }); break;
          }
          case 'schedule_inspection': {
            const property_id = resolvePropertyId(a.property_ref || a.target, refMap);
            if (!property_id) throw new Error(`No property found for the inspection.`);
            const tenant = tenants.find(t => t.property_id === property_id);
            const prop = properties.find(p => p.id === property_id);
            await base44.entities.Inspection.create({ property_id, tenant_id: tenant?.id || '', tenant_name: tenant?.name || '', status: 'scheduled', appointment_date: a.appointment_date || today, appointment_time: a.appointment_time || '10:00', inspector_name: a.inspector_name || '' });
            done.push({ action: a.action, label: prop?.address || 'Property' }); break;
          }
          default: break;
        }
      }
      ['landlords', 'properties', 'tenants', 'rent_payments', 'maintenance_requests', 'inspections'].forEach(k => queryClient.invalidateQueries({ queryKey: [k] }));
      setResults({ ok: true, done }); setActions(null);
    } catch (e) {
      setResults({ ok: false, done, error: e?.message || 'Something went wrong.' });
    } finally {
      setCreating(false);
    }
  };

  const fieldRows = (a) => {
    const skip = new Set(['action', 'ref']);
    return Object.entries(a).filter(([k, v]) => !skip.has(k) && v !== undefined && v !== '' && v !== null);
  };

  return (
    <div>
      <PageHeader title="AI Assistant" description="Describe what you need in plain English — add or update landlords, properties and tenants, record payments, log maintenance or schedule inspections. You review everything before it’s saved." />

      <div className="max-w-3xl space-y-4">
        <div className="bg-card border border-border rounded-xl p-4">
          <textarea value={text} onChange={(e) => setText(e.target.value)} rows={4}
            placeholder="e.g. Mark 14 Katherine Road as let agreed, and record £1,650 rent received from Sarah Ahmed today by bank transfer."
            className="w-full text-sm border border-input rounded-lg px-3 py-2.5 focus:outline-none focus:ring-2 focus:ring-primary resize-none" />
          <div className="flex items-center justify-between mt-3">
            <div className="text-xs text-muted-foreground">Nothing is saved until you confirm. The assistant never deletes records.</div>
            <Button onClick={interpret} disabled={interpreting || !text.trim()}>
              {interpreting ? <Loader2 className="w-4 h-4 mr-1 animate-spin" /> : <Wand2 className="w-4 h-4 mr-1" />}
              {interpreting ? 'Thinking…' : 'Interpret'}
            </Button>
          </div>
        </div>

        {!actions && !results && (
          <div className="text-xs text-muted-foreground space-y-1.5">
            <p className="font-medium text-foreground">Try:</p>
            {EXAMPLES.map((ex, i) => <button key={i} onClick={() => setText(ex)} className="block text-left hover:text-primary hover:underline">“{ex}”</button>)}
          </div>
        )}

        {error && <div className="flex items-start gap-2 rounded-lg border border-destructive/30 bg-destructive/10 px-3 py-2.5 text-sm text-destructive"><AlertCircle className="w-4 h-4 mt-0.5 shrink-0" /> {error}</div>}

        {actions && (
          <div className="space-y-3">
            <div className="flex items-center gap-2 text-sm font-semibold"><Sparkles className="w-4 h-4 text-primary" /> Proposed actions ({actions.length})</div>
            {note && <p className="text-xs text-amber-700 bg-amber-50 rounded-lg px-3 py-2">{note}</p>}
            {actions.map((a, i) => {
              const meta = META[a.action] || {}; const Icon = meta.icon || Sparkles;
              return (
                <div key={i} className="bg-card border border-border rounded-xl p-4">
                  <div className="flex items-center gap-2 mb-2"><Icon className={`w-4 h-4 ${meta.color || ''}`} /><span className="text-sm font-semibold">{meta.label || a.action}</span></div>
                  <div className="grid grid-cols-2 gap-x-6 gap-y-1 text-sm">
                    {fieldRows(a).map(([k, v]) => (
                      <div key={k} className="flex gap-2"><span className="text-muted-foreground capitalize w-28 shrink-0">{k.replace(/_/g, ' ')}</span><span className="font-medium break-words">{String(v)}</span></div>
                    ))}
                  </div>
                </div>
              );
            })}
            <div className="flex gap-2">
              <Button onClick={runActions} disabled={creating} className="bg-emerald-600 hover:bg-emerald-700">
                {creating ? <Loader2 className="w-4 h-4 mr-1 animate-spin" /> : <Check className="w-4 h-4 mr-1" />}
                {creating ? 'Working…' : `Confirm ${actions.length} action${actions.length > 1 ? 's' : ''}`}
              </Button>
              <Button variant="outline" onClick={() => setActions(null)} disabled={creating}>Cancel</Button>
            </div>
          </div>
        )}

        {results && (
          <div className={`rounded-xl border p-4 ${results.ok ? 'border-emerald-200 bg-emerald-50' : 'border-destructive/30 bg-destructive/10'}`}>
            <div className="flex items-center gap-2 text-sm font-semibold mb-2">
              {results.ok ? <Check className="w-4 h-4 text-emerald-600" /> : <AlertCircle className="w-4 h-4 text-destructive" />}
              {results.ok ? 'Done' : 'Stopped with an error'}
            </div>
            {results.done.length > 0 && (
              <ul className="text-sm space-y-1 mb-2">
                {results.done.map((d, i) => { const meta = META[d.action] || {}; const Icon = meta.icon || Check; return <li key={i} className="flex items-center gap-2"><Icon className={`w-3.5 h-3.5 ${meta.color || ''}`} /> {meta.label}: <span className="font-medium">{d.label}</span></li>; })}
              </ul>
            )}
            {!results.ok && <p className="text-sm text-destructive">{results.error}</p>}
            <Button variant="outline" size="sm" className="mt-2" onClick={() => { setResults(null); setText(''); }}>Start again</Button>
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState, useRef } from 'react';
import { base44 } from '@/api/base44Client';
import { businessConfig } from '@/lib/businessConfig';
import { useTenants, useLandlords, useProperties } from '@/hooks/useAllData';
import PageHeader from '@/components/ui/PageHeader';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { useToast } from '@/components/ui/use-toast';
import { saveAs } from 'file-saver';
import JSZip from 'jszip';
import { FileText, Upload, Loader2, Download, Sparkles, RefreshCw, Image as ImageIcon, Phone, MapPin, Plus, X, Printer, FileUp, Wand2 } from 'lucide-react';

const LS_KEY = 'asa_letterhead_template_url';

const escapeHtml = (s = '') =>
  String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const toDataUrl = (url) =>
  new Promise((resolve) => {
    fetch(url)
      .then((r) => r.blob())
      .then((blob) => {
        const reader = new FileReader();
        reader.onloadend = () => resolve(reader.result);
        reader.onerror = () => resolve(null);
        reader.readAsDataURL(blob);
      })
      .catch(() => resolve(null));
  });

const paragraphsHtml = (text) =>
  String(text || '')
    .split(/\n{2,}/)
    .map((p) => `<p>${escapeHtml(p).replace(/\n/g, '<br/>')}</p>`)
    .join('');

export default function AILetterWriter() {
  const { toast } = useToast();
  const fileInputRef = useRef(null);
  const templateInputRef = useRef(null);

  const { data: tenants = [] } = useTenants();
  const { data: landlords = [] } = useLandlords();
  const { data: properties = [] } = useProperties();

  // Letterhead (image) — the agency header printed at the top of the letter.
  const [letterheadUrl, setLetterheadUrl] = useState(
    () => localStorage.getItem(LS_KEY) || businessConfig.logoUrl
  );
  const [uploading, setUploading] = useState(false);

  // Mode: 'compose' = free-form AI writing; 'template' = merge inputs into an uploaded doc.
  const [mode, setMode] = useState('compose');

  // Template mode state
  const [templateFileUrl, setTemplateFileUrl] = useState('');
  const [templateFileName, setTemplateFileName] = useState('');
  const [extracting, setExtracting] = useState(false);
  const [templateText, setTemplateText] = useState('');
  const [inputs, setInputs] = useState([{ label: '', value: '' }]);

  // Shared letter fields
  const [recipientType, setRecipientType] = useState('tenant');
  const [selectedId, setSelectedId] = useState('');
  const [recipientName, setRecipientName] = useState('');
  const [recipientAddress, setRecipientAddress] = useState('');
  const [subject, setSubject] = useState('');
  const [date, setDate] = useState(new Date().toLocaleDateString('en-GB'));
  const [tone, setTone] = useState('Formal');
  const [instructions, setInstructions] = useState('');
  const [signOffName, setSignOffName] = useState(businessConfig.name);

  const [generating, setGenerating] = useState(false);
  const [letter, setLetter] = useState(null); // compose: {greeting,body,signOff} | template: {body}

  const handleUpload = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    try {
      const { file_url } = await base44.integrations.Core.UploadFile({ file });
      setLetterheadUrl(file_url);
      localStorage.setItem(LS_KEY, file_url);
      toast({ title: 'Letterhead template uploaded' });
    } catch (err) {
      toast({ title: 'Upload failed', description: String(err?.message || err), variant: 'destructive' });
    } finally {
      setUploading(false);
    }
  };

  const detectPlaceholders = (text) => {
    const re = /\{\{([^{}]+)\}\}|<<([^<>]+)>>|\[([A-Za-z_][\w ./-]{1,40}?)\]/g;
    const found = [];
    let m;
    while ((m = re.exec(text))) {
      const p = (m[1] || m[2] || m[3] || '').trim();
      if (p) found.push(p);
    }
    return [...new Set(found)];
  };

  const handleTemplateUpload = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const ext = file.name.toLowerCase().split('.').pop();
    if (ext === 'doc') {
      toast({ title: 'Legacy .doc not supported', description: 'Please save the file as .docx or .pdf and upload again.', variant: 'destructive' });
      return;
    }
    setExtracting(true);
    try {
      let text = '';
      let phs = [];
      if (ext === 'docx') {
        const zip = await JSZip.loadAsync(file);
        const xml = await zip.file('word/document.xml').async('string');
        text = xml
          .replace(/<w:p[^>]*>/g, '\n')
          .replace(/<[^>]+>/g, '')
          .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'")
          .replace(/\n{3,}/g, '\n\n').replace(/^\n+/, '').trim();
        phs = detectPlaceholders(text);
        setTemplateFileName(file.name);
      } else {
        const { file_url } = await base44.integrations.Core.UploadFile({ file });
        setTemplateFileUrl(file_url);
        setTemplateFileName(file.name);
        const res = await base44.integrations.Core.ExtractDataFromUploadedFile({
          file_url,
          json_schema: {
            type: 'object',
            properties: {
              template_text: { type: 'string', description: 'The full text of the letter template, preserving placeholders such as {{name}}, [name], or <<field>> exactly as written.' },
              placeholders: { type: 'array', items: { type: 'string' }, description: 'List of every placeholder/blank field found in the template.' },
            },
            required: ['template_text'],
          },
        });
        text = res?.output?.template_text || '';
        phs = Array.isArray(res?.output?.placeholders) ? res.output.placeholders : detectPlaceholders(text);
      }
      setTemplateText(text);
      if (phs.length) {
        setInputs(phs.map((p) => ({ label: p, value: '' })));
      }
      toast({ title: 'Template loaded', description: phs.length ? `${phs.length} placeholders detected` : 'Edit the template text below' });
    } catch (err) {
      toast({ title: 'Template extraction failed', description: String(err?.message || err), variant: 'destructive' });
    } finally {
      setExtracting(false);
    }
  };

  const updateInput = (i, field, value) =>
    setInputs((prev) => prev.map((x, idx) => (idx === i ? { ...x, [field]: value } : x)));
  const addInput = () => setInputs((prev) => [...prev, { label: '', value: '' }]);
  const removeInput = (i) => setInputs((prev) => prev.filter((_, idx) => idx !== i));

  const onTypeChange = (v) => {
    setRecipientType(v);
