Template:
"""
${templateText}
"""

Values:
${valuesText || '(no specific values provided — fill generically where possible)'}

Recipient: ${recipientName || ''}${recipientAddress ? ', ' + recipientAddress : ''}
Date: ${date}
${subject ? 'Subject: ' + subject : ''}

Return JSON with:
- body: the complete final letter text, including greeting and sign-off as part of the body, with paragraphs separated by a blank line.`;
        res = await base44.integrations.Core.InvokeLLM({
          prompt,
          response_json_schema: {
            type: 'object',
            properties: { body: { type: 'string' } },
