}

import React, { useMemo, useState } from 'react';
import { useLandlords, useProperties, useLandlordPayouts, usePaymentExtras, useTenants } from '@/hooks/useAllData';
import { downloadYearlyRentStatementPDF } from '@/lib/pdfExport';
import { formatCurrency } from '@/lib/computations';
import { getLandlordShares } from '@/lib/landlordShares';
import PageHeader from '@/components/ui/PageHeader';
import LandlordBanner from '@/components/ui/LandlordBanner';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Download, FileText, Landmark } from 'lucide-react';
import { format, parseISO } from 'date-fns';

// The statement year runs April to March: '2026' = April 2026 to March 2027
const monthOf = (p) => p.period_month || (p.bank_date || p.payment_date || '').slice(0, 7) || '';
const inYear = (month, year) => !!month && month >= `${year}-04` && month <= `${Number(year) + 1}-03`;
const yearLabel = (year) => `April ${year} to March ${Number(year) + 1}`;
// returns the bank amount of a payout — same rule as the landlord statement builder:
// split payouts count only their bank share; anything not paid in cash counts as a bank payment
const bankAmount = (p) => {
  if (p.payment_mode === 'split') return Number(p.bank_amount) || 0;
  const m = String(p.method || '').toLowerCase();
  if (m === 'cash') return 0;
  return Number(p.amount) || 0;
};

export default function AnnualRentStatement() {
  const { data: landlords = [] } = useLandlords();
  const { data: properties = [] } = useProperties();
  const { data: payouts = [] } = useLandlordPayouts();
  const { data: paymentExtras = [] } = usePaymentExtras();
  const { data: tenants = [] } = useTenants();

  const thisYear = new Date().getFullYear();
  const [landlordId, setLandlordId] = useState('');
  const [propertyId, setPropertyId] = useState('');
  const [year, setYear] = useState(String(thisYear));
  const [generating, setGenerating] = useState(false);

  const landlord = landlords.find(l => l.id === landlordId) || null;
  const property = properties.find(p => p.id === propertyId) || null;

  // properties belonging to the selected landlord (primary or co-owned)
  const landlordProperties = useMemo(() => {
    if (!landlordId) return [];
    return properties.filter(p =>
      p.landlord_id === landlordId || getLandlordShares(p).some(s => s.landlord_id === landlordId)
    ).sort((a, b) => (a.address || '').localeCompare(b.address || ''));
  }, [properties, landlordId]);

  const years = useMemo(() => {
    const set = new Set([String(thisYear), String(thisYear - 1)]);
    payouts.forEach(p => {
      const m = monthOf(p); if (!m) return;
      const y = Number(m.slice(5, 7)) >= 4 ? m.slice(0, 4) : String(Number(m.slice(0, 4)) - 1);
      set.add(y);
    });
    return [...set].sort((a, b) => b.localeCompare(a));
  }, [payouts]);

  // this landlord's share of the property (1 unless co-owned)
  const shareFraction = useMemo(() => {
    if (!property || !landlordId) return 1;
    const shares = getLandlordShares(property);
    if (shares.length <= 1) return 1;
    const mine = shares.find(s => s.landlord_id === landlordId);
    return mine ? (Number(mine.share_pct) || 0) / 100 : 1;
  }, [property, landlordId]);

  // deduction per month for this property/year (this landlord's share), excludes commission
  const monthDeduction = useMemo(() => {
    const map = {};
    paymentExtras
      .filter(e => e.property_id === propertyId && inYear(e.period_month, String(year)) && e.settlement_method !== 'cash_settled')
      .forEach(e => { map[e.period_month] = (map[e.period_month] || 0) + (Number(e.amount) || 0) * shareFraction; });
    return map;
  }, [paymentExtras, propertyId, year, shareFraction]);

  // was the property let (any tenant lease overlapping) during the selected April to March year?
  const wasLet = useMemo(() => {
    if (!propertyId) return false;
    const start = `${year}-04-01`;
    const end = `${Number(year) + 1}-03-31`;
    return tenants.some(t => t.property_id === propertyId && t.lease_start && t.lease_start <= end && (!t.lease_end || t.lease_end >= start));
  }, [tenants, propertyId, year]);

  // Per-month: was the property let (any tenant lease overlapping that month)?
  const monthWasLet = useMemo(() => {
    const map = {};
    for (let i = 0; i < 12; i++) {
      const d = new Date(Number(year), 3 + i, 1); // Apr(3) → Mar
      const ym = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
      const mStart = `${ym}-01`;
      const mEnd = format(new Date(d.getFullYear(), d.getMonth() + 1, 0), 'yyyy-MM-dd');
      map[ym] = tenants.some(t => t.property_id === propertyId && t.lease_start && t.lease_start <= mEnd && (!t.lease_end || t.lease_end >= mStart));
    }
    return map;
  }, [tenants, propertyId, year]);

  // bank payouts to the landlord for the chosen property + year (deduction shown once per month)
  const rows = useMemo(() => {
    if (!propertyId) return [];
    const seenMonth = new Set();
    // Payout rows keyed by month.
    const payoutByMonth = {};
    payouts
      .filter(p => p.property_id === propertyId && (!landlordId || p.landlord_id === landlordId) && bankAmount(p) > 0 && inYear(monthOf(p), String(year)))
      .sort((a, b) => new Date(a.bank_date || a.payment_date || 0) - new Date(b.bank_date || b.payment_date || 0))
      .forEach(p => {
        const d = p.bank_date || p.payment_date;
        const m = p.period_month || '';
        let deduction = 0;
        if (m && !seenMonth.has(m)) { deduction = monthDeduction[m] || 0; seenMonth.add(m); }
        // If two payouts land in the same month, keep the first and add amounts.
        if (payoutByMonth[m]) {
          payoutByMonth[m].amount += bankAmount(p);
        } else {
          payoutByMonth[m] = {
            month: m,
            dateLabel: d ? format(parseISO(d), 'dd/MM/yyyy') : '—',
            monthLabel: m ? format(parseISO(m + '-01'), 'MMM yyyy') : '—',
            detail: p.paid_from_bank_name || p.split_bank_name || 'Bank transfer',
            reference: p.reference || '',
            deduction,
            amount: bankAmount(p),
            paid: true,
          };
        }
      });

    // Build the full Apr→Mar grid, filling gaps with a status row.
    const out = [];
    for (let i = 0; i < 12; i++) {
      const dt = new Date(Number(year), 3 + i, 1);
      const ym = `${dt.getFullYear()}-${String(dt.getMonth() + 1).padStart(2, '0')}`;
      if (payoutByMonth[ym]) {
        out.push(payoutByMonth[ym]);
      } else {
        const let_ = monthWasLet[ym];
        // Don't show future months (no expectation of payment yet).
        const isFuture = ym > format(new Date(), 'yyyy-MM');
        if (isFuture) continue;
        // A month with no payout can still have a deduction (e.g. a refurb charged
        // while vacant). Show it so it isn't hidden.
        const monthDed = monthDeduction[ym] || 0;
        out.push({
          month: ym,
          dateLabel: '—',
          monthLabel: format(new Date(ym + '-01'), 'MMM yyyy'),
          detail: let_ ? 'No payment made' : 'Property was empty',
          reference: '',
          deduction: monthDed,
          amount: 0,
          paid: false,
          vacant: !let_,
        });
      }
    }
    return out;
  }, [payouts, propertyId, landlordId, year, monthDeduction, monthWasLet]);

  const total = rows.reduce((s, r) => s + r.amount, 0);
  const totalDeduction = rows.reduce((s, r) => s + (r.deduction || 0), 0);

  // itemised deductions (with descriptions) for the property/year
  const deductions = useMemo(() => {
    if (!propertyId) return [];
    return paymentExtras
      .filter(e => e.property_id === propertyId && inYear(e.period_month, String(year)))
      .sort((a, b) => (a.period_month || '').localeCompare(b.period_month || '') || new Date(a.date || 0) - new Date(b.date || 0))
      .map(e => ({
        monthLabel: e.period_month ? format(parseISO(e.period_month + '-01'), 'MMM yyyy') : (e.date ? format(parseISO(e.date), 'MMM yyyy') : '—'),
        description: (e.description || e.category || e.notes || 'Deduction') + (e.settlement_method === 'cash_settled' ? ' (settled in cash)' : ''),
        amount: e.settlement_method === 'cash_settled' ? 0 : (Number(e.amount) || 0) * shareFraction,
      }));
  }, [paymentExtras, propertyId, year, shareFraction]);

  const download = async () => {
    if (!property) return;
    setGenerating(true);
    try {
      await downloadYearlyRentStatementPDF({ landlord, property, year, payments: rows, deductions });
    } finally {
      setGenerating(false);
    }
  };

  return (
    <div>
      <PageHeader
        title="Annual Rent Statement"
        description="A year's rent paid to the landlord for a property (April to March) — bank payments only. Cash payouts are excluded."
      />

      <LandlordBanner subtitle="Annual rent paid to a landlord for a property." />

      <div className="max-w-4xl space-y-5">
        {/* Selectors */}
        <div className="bg-card border border-border rounded-xl p-4 grid grid-cols-1 sm:grid-cols-3 gap-4">
          <div className="space-y-1.5">
            <Label>Landlord</Label>
            <Select value={landlordId} onValueChange={(v) => { setLandlordId(v); setPropertyId(''); }}>
              <SelectTrigger><SelectValue placeholder="Select landlord" /></SelectTrigger>
              <SelectContent>
                {landlords.slice().sort((a, b) => (a.name || '').localeCompare(b.name || '')).map(l => (
                  <SelectItem key={l.id} value={l.id}>{l.name}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div className="space-y-1.5">
            <Label>Property</Label>
            <Select value={propertyId} onValueChange={setPropertyId} disabled={!landlordId}>
              <SelectTrigger><SelectValue placeholder={landlordId ? 'Select property' : 'Choose a landlord first'} /></SelectTrigger>
              <SelectContent>
                {landlordProperties.map(p => <SelectItem key={p.id} value={p.id}>{p.address}</SelectItem>)}
              </SelectContent>
            </Select>
          </div>
          <div className="space-y-1.5">
            <Label>Year</Label>
            <Select value={year} onValueChange={setYear}>
              <SelectTrigger><SelectValue /></SelectTrigger>
              <SelectContent>
                {years.map(y => <SelectItem key={y} value={y}>{yearLabel(y)}</SelectItem>)}
              </SelectContent>
            </Select>
          </div>
        </div>

        {/* Preview */}
        {propertyId && (
          <div className="bg-card border border-border rounded-xl overflow-hidden">
            <div className="flex items-center justify-between gap-3 p-4 border-b border-border">
              <div>
                <p className="font-semibold">{property?.address}</p>
                <p className="text-xs text-muted-foreground flex items-center gap-1"><Landmark className="w-3 h-3" /> Bank payments only · {yearLabel(year)}</p>
              </div>
              <Button onClick={download} disabled={generating || rows.length === 0}>
                <Download className="w-4 h-4 mr-1" /> {generating ? 'Preparing…' : 'Download PDF'}
              </Button>
            </div>

            {rows.length === 0 ? (
              <div className="p-8 text-center text-sm text-muted-foreground">
                <FileText className="w-8 h-8 mx-auto mb-2 opacity-40" />
                {wasLet
                  ? <>No bank payments to the landlord for this property in {yearLabel(year)}.</>
                  : 'Property was not let in this period.'}
              </div>
            ) : (
              <table className="w-full text-sm">
                <thead>
                  <tr className="text-left text-xs uppercase tracking-wide text-muted-foreground border-b border-border">
                    <th className="px-4 py-2 font-medium">Date paid</th>
                    <th className="px-4 py-2 font-medium">Month</th>
                    <th className="px-4 py-2 font-medium">Paid from</th>
                    <th className="px-4 py-2 font-medium">Reference</th>
                    <th className="px-4 py-2 font-medium text-right">Deduction</th>
                    <th className="px-4 py-2 font-medium text-right">Amount</th>
                  </tr>
                </thead>
                <tbody>
                  {rows.map((r, i) => (
                    <tr key={i} className={`border-b border-border/60 ${!r.paid ? 'bg-muted/30 text-muted-foreground italic' : ''}`}>
                      <td className="px-4 py-2">{r.dateLabel}</td>
                      <td className="px-4 py-2">{r.monthLabel}</td>
                      <td className="px-4 py-2">{r.detail}</td>
                      <td className="px-4 py-2 text-muted-foreground">{r.reference || '—'}</td>
                      <td className="px-4 py-2 text-right tabular-nums text-amber-700">{r.deduction > 0 ? `- ${formatCurrency(r.deduction)}` : '—'}</td>
                      <td className="px-4 py-2 text-right font-medium tabular-nums">{r.paid ? formatCurrency(r.amount) : '—'}</td>
                    </tr>
                  ))}
                  <tr className="bg-muted/40 font-semibold">
                    <td className="px-4 py-2.5" colSpan={4}>Totals (bank)</td>
                    <td className="px-4 py-2.5 text-right tabular-nums text-amber-700">{totalDeduction > 0 ? `- ${formatCurrency(totalDeduction)}` : '—'}</td>
                    <td className="px-4 py-2.5 text-right tabular-nums">{formatCurrency(total)}</td>
                  </tr>
                </tbody>
              </table>
            )}
          </div>
        )}

        {/* Deductions breakdown */}
        {propertyId && deductions.length > 0 && (
          <div className="bg-card border border-border rounded-xl overflow-hidden">
            <div className="p-4 border-b border-border">
              <p className="font-semibold">Deductions</p>
              <p className="text-xs text-muted-foreground">What was deducted and why ({yearLabel(year)}).</p>
            </div>
            <table className="w-full text-sm">
              <thead>
                <tr className="text-left text-xs uppercase tracking-wide text-muted-foreground border-b border-border">
                  <th className="px-4 py-2 font-medium">Month</th>
                  <th className="px-4 py-2 font-medium">Description</th>
                  <th className="px-4 py-2 font-medium text-right">Amount</th>
                </tr>
              </thead>
              <tbody>
                {deductions.map((d, i) => (
                  <tr key={i} className="border-b border-border/60">
                    <td className="px-4 py-2">{d.monthLabel}</td>
                    <td className="px-4 py-2">{d.description}</td>
                    <td className="px-4 py-2 text-right tabular-nums text-amber-700">- {formatCurrency(d.amount)}</td>
                  </tr>
                ))}
                <tr className="bg-muted/40 font-semibold">
                  <td className="px-4 py-2.5" colSpan={2}>Total deductions</td>
                  <td className="px-4 py-2.5 text-right tabular-nums text-amber-700">- {formatCurrency(totalDeduction)}</td>
                </tr>
              </tbody>
            </table>
          </div>
        )}

        {!propertyId && (
          <p className="text-sm text-muted-foreground">Choose a landlord and one of their properties to see the year's bank payments and download a statement.</p>
        )}
      </div>
    </div>
  );
}

import React from 'react';
import { useTenants, useProperties, useLandlords, useRentPayments, useRentHistoryAll } from '@/hooks/useAllData';
import PageHeader from '@/components/ui/PageHeader';
import StatusBadge from '@/components/ui/StatusBadge';
import { formatCurrency, calculateArrears, calculatePeriodArrears } from '@/lib/computations';
import { Link } from 'react-router-dom';
import { Button } from '@/components/ui/button';
import { Eye } from 'lucide-react';
import { format, parseISO } from 'date-fns';

function formatPeriodLabel(yyyyMM) {
  try { return format(parseISO(`${yyyyMM}-01`), 'MMMM yyyy'); } catch { return yyyyMM; }
}

export default function Arrears() {
  const { data: tenants = [] } = useTenants();
  const { data: properties = [] } = useProperties();
  const { data: landlords = [] } = useLandlords();
  const { data: rentPayments = [] } = useRentPayments();
  const { data: rentHistoryAll = [] } = useRentHistoryAll();

  const arrearsData = tenants
    .filter(t => t.status !== 'ended')
    .map(t => {
      const tPayments = rentPayments.filter(p => p.tenant_id === t.id);
      const tHistory = rentHistoryAll.filter(r => r.tenant_id === t.id);
      const arrears = calculateArrears(t, tPayments, tHistory);
      const property = properties.find(p => p.id === t.property_id);
      const landlord = landlords.find(l => l.id === property?.landlord_id);
      const totalPaid = tPayments.reduce((s, p) => s + (p.amount || 0), 0);
      const periodBreakdown = calculatePeriodArrears(t, tPayments, tHistory);
      const lastUnpaid = [...periodBreakdown].reverse().find(p => p.arrears > 0);
      return { tenant: t, property, landlord, arrears, totalPaid, lastUnpaid };
    })
    .filter(d => d.arrears > 0)
    .sort((a, b) => b.arrears - a.arrears);

  const totalArrears = arrearsData.reduce((s, d) => s + d.arrears, 0);

  return (
    <div>
      <PageHeader
        title="Arrears"
        description={`${arrearsData.length} tenants with outstanding arrears — Total: ${formatCurrency(totalArrears)}`}
      />

      <div className="bg-card rounded-xl border border-border overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-muted/50">
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Tenant</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Property</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Landlord</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Monthly Rent</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Total Paid</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Oldest Unpaid Period</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Total Arrears</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Actions</th>
              </tr>
            </thead>
            <tbody>
              {arrearsData.map(d => (
                <tr key={d.tenant.id} className="border-t border-border hover:bg-muted/30 transition-colors">
                  <td className="px-5 py-3 font-medium">{d.tenant.name}</td>
                  <td className="px-5 py-3 text-muted-foreground">{d.property?.address || '-'}</td>
                  <td className="px-5 py-3 text-muted-foreground">{d.landlord?.name || '-'}</td>
                  <td className="px-5 py-3">{formatCurrency(d.tenant.monthly_rent)}</td>
                  <td className="px-5 py-3">{formatCurrency(d.totalPaid)}</td>
                  <td className="px-5 py-3 text-amber-600 font-medium">{d.lastUnpaid ? formatPeriodLabel(d.lastUnpaid.period) : '—'}</td>
                  <td className="px-5 py-3">
                    <span className="text-red-600 font-bold">{formatCurrency(d.arrears)}</span>
                  </td>
                  <td className="px-5 py-3">
                    <Link to={`/TenantDetail?id=${d.tenant.id}`}>
                      <Button variant="ghost" size="sm"><Eye className="w-4 h-4" /></Button>
                    </Link>
                  </td>
                </tr>
              ))}
              {arrearsData.length === 0 && (
                <tr><td colSpan="7" className="px-5 py-8 text-center text-muted-foreground">No arrears — all tenants are up to date!</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

