export default function CRM() {
  const { user, isAdmin } = useRole();
  const { data: entries } = useCRMEntries();
  const { data: landlords } = useLandlords();
  const queryClient = useQueryClient();
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState(null);
  const [search, setSearch] = useState('');
  const [filterType, setFilterType] = useState('all');
  const [confirmDelete, setConfirmDelete] = useState(null);

  const handleSubmit = async (data) => {
    if (editing) {
      await base44.entities.CRMEntry.update(editing.id, data);
      await logAction({ user, action: 'update', entityType: 'CRMEntry', entityId: editing.id, summary: `Updated CRM entry: ${data.subject}`, oldValue: editing, newValue: data });
    } else {
      const created = await base44.entities.CRMEntry.create(data);
      await logAction({ user, action: 'create', entityType: 'CRMEntry', entityId: created.id, summary: `Created CRM entry: ${data.subject}`, newValue: data });
    }
    queryClient.invalidateQueries({ queryKey: ['crm_entries'] });
    setEditing(null);
    setShowForm(false);
  };

  const handleDelete = async (entry) => {
    await base44.entities.CRMEntry.delete(entry.id);
    await logAction({ user, action: 'delete', entityType: 'CRMEntry', entityId: entry.id, summary: `Deleted CRM entry: ${entry.subject}`, oldValue: entry });
    queryClient.invalidateQueries({ queryKey: ['crm_entries'] });
    setConfirmDelete(null);
  };

  const toggleComplete = async (entry) => {
    await base44.entities.CRMEntry.update(entry.id, { completed: !entry.completed });
    queryClient.invalidateQueries({ queryKey: ['crm_entries'] });
  };

  const getLandlordName = (id) => landlords.find(l => l.id === id)?.name || 'Unknown';
  const typeColors = { note: 'gray', call: 'blue', email: 'blue', message: 'blue', meeting: 'yellow', task: 'green' };

  const filtered = entries.filter(e => {
    const matchSearch = e.subject?.toLowerCase().includes(search.toLowerCase()) || getLandlordName(e.landlord_id).toLowerCase().includes(search.toLowerCase());
    const matchType = filterType === 'all' || e.type === filterType;
    return matchSearch && matchType;
  });

  return (
    <div>
      <PageHeader
