import React from 'react';
import { useProperties, useLandlords, usePropertyDocuments } from '@/hooks/useAllData';
import PageHeader from '@/components/ui/PageHeader';
import StatusBadge from '@/components/ui/StatusBadge';
import { getPropertyCertStatus } from '@/lib/computations';
import { format, parseISO } from 'date-fns';
import { Link } from 'react-router-dom';
import { Button } from '@/components/ui/button';
import { Eye, FileText, Upload } from 'lucide-react';

const CERT_TYPES = [
  { catKey: 'gas',        category: 'gas_cert',        label: 'Gas Certificate' },
  { catKey: 'electrical', category: 'electrical_cert', label: 'Electrical Certificate' },
  { catKey: 'epc',        category: 'epc_cert',        label: 'EPC Certificate' },
  { catKey: 'license',    category: 'license',         label: 'License' },
];

export default function Certificates() {
  const { data: properties } = useProperties();
  const { data: landlords } = useLandlords();
  const { data: propertyDocuments } = usePropertyDocuments();

  const getLandlordName = (id) => landlords.find(l => l.id === id)?.name || 'Unknown';

  // Build the flat row list across every property × every cert category
  const allCerts = [];
  properties.forEach(p => {
    const status = getPropertyCertStatus(p.id, propertyDocuments);
    CERT_TYPES.forEach(ct => {
      const s = status[ct.catKey];
      const docCount = propertyDocuments.filter(
        d => d.property_id === p.id && d.category === ct.category && !d.is_archived
      ).length;
      allCerts.push({
        property: p,
        type: ct.label,
        category: ct.category,
        expiry: s.expiry,
        status: s.status, // 'expired' | 'expiring' | 'valid' | 'missing'
        docCount,
      });
    });
  });

  // Sort: expired first, then expiring, then missing, then valid
  const order = { expired: 0, expiring: 1, missing: 2, valid: 3 };
  allCerts.sort((a, b) => order[a.status] - order[b.status]);

  const statusColor = { expired: 'red', expiring: 'yellow', valid: 'green', missing: 'gray' };

  const expiredCount = allCerts.filter(c => c.status === 'expired').length;
  const expiringCount = allCerts.filter(c => c.status === 'expiring').length;

  return (
    <div>
      <PageHeader
        title="Certificates & Licenses"
        description={`${expiredCount} expired, ${expiringCount} expiring soon`}
      />

      <div className="bg-card rounded-xl border border-border overflow-hidden elev-1">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-muted/50">
                <th className="text-left px-5 py-3 font-semibold text-muted-foreground text-[11px] uppercase tracking-wider">Property</th>
                <th className="text-left px-5 py-3 font-semibold text-muted-foreground text-[11px] uppercase tracking-wider">Landlord</th>
                <th className="text-left px-5 py-3 font-semibold text-muted-foreground text-[11px] uppercase tracking-wider">Certificate</th>
                <th className="text-left px-5 py-3 font-semibold text-muted-foreground text-[11px] uppercase tracking-wider">Expiry Date</th>
                <th className="text-left px-5 py-3 font-semibold text-muted-foreground text-[11px] uppercase tracking-wider">Status</th>
                <th className="text-left px-5 py-3 font-semibold text-muted-foreground text-[11px] uppercase tracking-wider">History</th>
                <th className="text-right px-5 py-3 font-semibold text-muted-foreground text-[11px] uppercase tracking-wider">Actions</th>
              </tr>
            </thead>
            <tbody>
              {allCerts.map((c, i) => (
                <tr
                  key={i}
                  className={`border-t border-border hover:bg-muted/30 transition-colors ${
                    c.status === 'expired' ? 'bg-rose-50/40' :
                    c.status === 'expiring' ? 'bg-amber-50/40' : ''
                  }`}
                >
                  <td className="px-5 py-3 font-medium">{c.property.address}</td>
                  <td className="px-5 py-3 text-muted-foreground">{getLandlordName(c.property.landlord_id)}</td>
                  <td className="px-5 py-3">{c.type}</td>
                  <td className="px-5 py-3 text-muted-foreground tabular-nums">
                    {c.expiry ? format(parseISO(c.expiry), 'dd MMM yyyy') : 'Not set'}
                  </td>
                  <td className="px-5 py-3">
                    <StatusBadge color={statusColor[c.status]}>{c.status}</StatusBadge>
                  </td>
                  <td className="px-5 py-3 text-muted-foreground">
                    {c.docCount > 0 ? (
                      <span className="inline-flex items-center gap-1 text-xs">
                        <FileText className="w-3 h-3" />
                        {c.docCount} on file
                      </span>
                    ) : (
                      <span className="text-xs">—</span>
                    )}
                  </td>
                  <td className="px-5 py-3 text-right">
                    <div className="inline-flex items-center gap-1">
                      {c.status === 'missing' ? (
                        <Link to={`/PropertyDetail?id=${c.property.id}&tab=documents`}>
                          <Button variant="outline" size="sm" className="h-8">
                            <Upload className="w-3.5 h-3.5 mr-1" />Upload
                          </Button>
                        </Link>
                      ) : (
                        <Link to={`/PropertyDetail?id=${c.property.id}&tab=documents`}>
                          <Button variant="ghost" size="sm" className="h-8" title="Manage documents">
                            <FileText className="w-4 h-4" />
                          </Button>
                        </Link>
                      )}
                      <Link to={`/PropertyDetail?id=${c.property.id}`}>
                        <Button variant="ghost" size="sm" className="h-8" title="View property">
                          <Eye className="w-4 h-4" />
                        </Button>
                      </Link>
                    </div>
                  </td>
                </tr>
              ))}
              {allCerts.length === 0 && (
                <tr>
                  <td colSpan="7" className="px-5 py-12 text-center text-muted-foreground">
                    No properties yet. Add a property to start tracking certificates.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { base44 } from '@/api/base44Client';
