function AgreementForm({ landlords, properties, onSubmit, onCancel, initialData }) {
  const [data, setData] = useState(initialData || { landlord_id: '', property_id: '', type: 'percentage', value: 10, notes: '', effective_from: '', effective_to: '' });
  const [submitting, setSubmitting] = useState(false);

  const handlePropertyChange = (v) => {
    const propertyId = v === 'none' ? '' : v;
    const property = properties.find(p => p.id === propertyId);
    setData(prev => ({
      ...prev,
      property_id: propertyId,
      landlord_id: property?.landlord_id || prev.landlord_id,
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (submitting) return;
    setSubmitting(true);
    try { await onSubmit(data); } finally { setSubmitting(false); }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label>Property (optional override)</Label>
          <Select value={data.property_id || 'none'} onValueChange={handlePropertyChange}>
            <SelectTrigger><SelectValue placeholder="All properties" /></SelectTrigger>
            <SelectContent>
              <SelectItem value="none">All properties (default)</SelectItem>
              {properties.map(p => <SelectItem key={p.id} value={p.id}>{p.address}</SelectItem>)}
            </SelectContent>
          </Select>
        </div>
        <div className="space-y-2">
          <Label>Landlord *</Label>
          <LandlordCombobox landlords={landlords} value={data.landlord_id} onChange={v => setData({ ...data, landlord_id: v })} placeholder="Select landlord" />
        </div>
        <div className="space-y-2">
          <Label>Type *</Label>
          <Select value={data.type} onValueChange={v => setData({ ...data, type: v })}>
            <SelectTrigger><SelectValue /></SelectTrigger>
            <SelectContent>
              <SelectItem value="percentage">Percentage</SelectItem>
              <SelectItem value="fixed_monthly">Fixed Monthly</SelectItem>
              <SelectItem value="one_time">One-time Fee</SelectItem>
            </SelectContent>
          </Select>
        </div>
        <div className="space-y-2">
          <Label>{data.type === 'percentage' ? 'Percentage (%)' : 'Amount (£)'}</Label>
          <Input type="number" min="0" step="0.01" value={data.value} onChange={e => setData({ ...data, value: Number(e.target.value) })} />
        </div>
        <div className="space-y-2">
          <Label>Effective From <span className="text-muted-foreground text-xs">(YYYY-MM)</span></Label>
          <Input type="month" value={data.effective_from} onChange={e => setData({ ...data, effective_from: e.target.value })} placeholder="e.g. 2026-01" />
        </div>
        <div className="space-y-2">
          <Label>Effective To <span className="text-muted-foreground text-xs">(YYYY-MM, leave blank = still active)</span></Label>
          <Input type="month" value={data.effective_to || ''} onChange={e => setData({ ...data, effective_to: e.target.value })} placeholder="e.g. 2026-04" />
        </div>
      </div>
      <div className="flex gap-3 justify-end pt-2">
        {onCancel && <Button type="button" variant="outline" onClick={onCancel} disabled={submitting}>Cancel</Button>}
        <Button type="submit" disabled={submitting}>{submitting ? 'Saving...' : initialData ? 'Save Changes' : 'Add Agreement'}</Button>
      </div>
    </form>
  );
}

export default function Commission() {
  const { user, isAdmin } = useRole();
  const { data: agreements = [] } = useCommissionAgreements();
  const { data: ledgerRaw = [] } = useCommissionLedger();
  const { data: landlords = [] } = useLandlords();
  const { data: properties = [] } = useProperties();
  const { data: rentPayments = [] } = useRentPayments();

  // Only show commission entries where actual rent payments exist for that property+period
  const ledger = ledgerRaw.filter(e =>
    rentPayments.some(p => p.property_id === e.property_id && p.period_month === e.period_month)
  );
  const queryClient = useQueryClient();
  const [showForm, setShowForm] = useState(false);
  const [editAgreement, setEditAgreement] = useState(null);
  const [tab, setTab] = useState('ledger');
  const [confirmDelete, setConfirmDelete] = useState(null);

  const totalCommission = ledger.reduce((s, e) => s + (e.commission_amount || 0), 0);
  const totalLandlordShare = ledger.reduce((s, e) => s + (e.landlord_share || 0), 0);

const handleAddAgreement = async (data) => {
  if (!isAdmin) { alert('Only admins can manage commission agreements.'); return; }
  const created = await base44.entities.CommissionAgreement.create(data);

  // Recalculate ledger entries within the effective date range only
  const affectedLedger = ledgerRaw.filter(e => {
    if (e.landlord_id !== data.landlord_id) return false;
    if (data.property_id && e.property_id !== data.property_id) return false;
    if (data.effective_from && e.period_month && e.period_month < data.effective_from) return false;
    if (data.effective_to && e.period_month && e.period_month > data.effective_to) return false;
    return true;
  });

  for (const entry of affectedLedger) {
    const rentAmount = entry.rent_amount || rentPayments.find(r => r.id === entry.rent_payment_id)?.amount || 0;
    let newCommission = 0;
    if (data.type === 'percentage') newCommission = (rentAmount * data.value) / 100;
    else if (data.type === 'fixed_monthly') newCommission = data.value;
    else if (data.type === 'one_time') newCommission = data.value;

    await base44.entities.CommissionLedger.update(entry.id, {
      ...entry,
      commission_amount: newCommission,
      landlord_share: rentAmount - newCommission,
      commission_rate: data.value,
      commission_type: data.type,
    });
  }

  await logAction({ user, action: 'create', entityType: 'CommissionAgreement', entityId: created.id, summary: `Created commission agreement for landlord ${getLandlordName(data.landlord_id)} — ${affectedLedger.length} ledger entries updated`, newValue: data });
  queryClient.invalidateQueries({ queryKey: ['commission_agreements'] });
  queryClient.invalidateQueries({ queryKey: ['commission_ledger'] });
  setShowForm(false);
};

const handleEditAgreement = async (data) => {
  if (!isAdmin) { alert('Only admins can manage commission agreements.'); return; }
  await base44.entities.CommissionAgreement.update(editAgreement.id, data);

  // Recalculate ledger entries within the effective date range only
  const affectedLedger = ledgerRaw.filter(e => {
    if (e.landlord_id !== data.landlord_id) return false;
    if (data.property_id && e.property_id !== data.property_id) return false;
    if (data.effective_from && e.period_month && e.period_month < data.effective_from) return false;
    if (data.effective_to && e.period_month && e.period_month > data.effective_to) return false;
    return true;
  });
  for (const entry of affectedLedger) {
    const rentAmount = entry.rent_amount || rentPayments.find(r => r.id === entry.rent_payment_id)?.amount || 0;
    let newCommission = 0;
    if (data.type === 'percentage') newCommission = (rentAmount * data.value) / 100;
    else if (data.type === 'fixed_monthly') newCommission = data.value;
    else if (data.type === 'one_time') newCommission = data.value;
    await base44.entities.CommissionLedger.update(entry.id, {
      ...entry,
      commission_amount: newCommission,
      landlord_share: rentAmount - newCommission,
      commission_rate: data.value,
      commission_type: data.type,
    });
  }

  await logAction({ user, action: 'update', entityType: 'CommissionAgreement', entityId: editAgreement.id, summary: `Updated commission agreement for ${getLandlordName(data.landlord_id)}`, newValue: data });
  queryClient.invalidateQueries({ queryKey: ['commission_agreements'] });
  queryClient.invalidateQueries({ queryKey: ['commission_ledger'] });
  setEditAgreement(null);
};

const handleDeleteAgreement = async (agreement) => {
  if (!isAdmin) { alert('Only admins can delete commission agreements.'); setConfirmDelete(null); return; }

  const affectedLedger = ledgerRaw.filter(e => {
    if (e.landlord_id !== agreement.landlord_id) return false;
    if (agreement.property_id) return e.property_id === agreement.property_id;
    return true;
  });

  const remainingAgreements = agreements.filter(a => a.id !== agreement.id);
  await base44.entities.CommissionAgreement.delete(agreement.id);

  for (const entry of affectedLedger) {
    const newAgreement =
      remainingAgreements.find(a => a.property_id === entry.property_id) ||
      remainingAgreements.find(a => a.landlord_id === entry.landlord_id && !a.property_id);

    const rentAmount = entry.rent_amount || rentPayments.find(r => r.id === entry.rent_payment_id)?.amount || 0;
    let newCommission = 0, newRate = 0, newType = 'percentage';

    if (newAgreement) {
      newType = newAgreement.type;
      newRate = newAgreement.value;
      if (newAgreement.type === 'percentage') newCommission = (rentAmount * newAgreement.value) / 100;
      else if (newAgreement.type === 'fixed_monthly') newCommission = newAgreement.value;
      else if (newAgreement.type === 'one_time' && !newAgreement.one_time_applied) newCommission = newAgreement.value;
    }

    await base44.entities.CommissionLedger.update(entry.id, {
      ...entry,
      commission_amount: newCommission,
      landlord_share: rentAmount - newCommission,
      commission_rate: newRate,
      commission_type: newType,
    });
  }

  await logAction({ user, action: 'delete', entityType: 'CommissionAgreement', entityId: agreement.id, summary: `Deleted commission agreement for ${getLandlordName(agreement.landlord_id)} — ${affectedLedger.length} ledger entries recalculated`, oldValue: agreement });
  queryClient.invalidateQueries({ queryKey: ['commission_agreements'] });
  queryClient.invalidateQueries({ queryKey: ['commission_ledger'] });
  setConfirmDelete(null);
};

  const getLandlordName = (id) => landlords.find(l => l.id === id)?.name || 'Unknown';
  const getPropertyAddress = (id) => properties.find(p => p.id === id)?.address || 'All properties';

  return (
    <div>
      <PageHeader
        title="Commission"
        description="Commission agreements and ledger"
        actions={isAdmin ? <Button onClick={() => setShowForm(true)}><Plus className="w-4 h-4 mr-2" />Add Agreement</Button> : <span className="text-xs text-muted-foreground flex items-center gap-1"><Lock className="w-3 h-3" />Admin only</span>}
      />

      <LandlordBanner subtitle="Commission agreements and landlord share." />

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-8">
        <StatCard label="Total Commission Earned" value={formatCurrency(totalCommission)} icon={PieChart} color="primary" />
        <StatCard label="Total Landlord Share" value={formatCurrency(totalLandlordShare)} color="success" />
        <StatCard label="Active Agreements" value={agreements.length} />
      </div>

      {/* Tab Toggle */}
      <div className="flex gap-2 mb-4 flex-wrap">
        <Button variant={tab === 'ledger' ? 'default' : 'outline'} size="sm" onClick={() => setTab('ledger')}>Commission Ledger</Button>
        <Button variant={tab === 'agreements' ? 'default' : 'outline'} size="sm" onClick={() => setTab('agreements')}>Agreements</Button>
        <Button variant={tab === 'invoices' ? 'default' : 'outline'} size="sm" onClick={() => setTab('invoices')}>Manual Invoices</Button>
      </div>

      {tab === 'ledger' && (
        <div className="bg-card rounded-xl border border-border overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="bg-muted/50">
                  <th className="text-left px-5 py-3 font-medium text-muted-foreground">Date</th>
                  <th className="text-left px-5 py-3 font-medium text-muted-foreground">Landlord</th>
                  <th className="text-left px-5 py-3 font-medium text-muted-foreground">Property</th>
                  <th className="text-left px-5 py-3 font-medium text-muted-foreground">Rent</th>
                  <th className="text-left px-5 py-3 font-medium text-muted-foreground">Commission</th>
                  <th className="text-left px-5 py-3 font-medium text-muted-foreground">Landlord Share</th>
                  <th className="text-left px-5 py-3 font-medium text-muted-foreground">Type</th>
                </tr>
              </thead>
              <tbody>
                {ledger.map(e => (
                  <tr key={e.id} className="border-t border-border hover:bg-muted/30 transition-colors">
                    <td className="px-5 py-3 text-muted-foreground">{e.date ? format(parseISO(e.date), 'dd MMM yyyy') : '-'}</td>
                    <td className="px-5 py-3 font-medium">{getLandlordName(e.landlord_id)}</td>
                    <td className="px-5 py-3 text-muted-foreground">{getPropertyAddress(e.property_id)}</td>
                    <td className="px-5 py-3">{formatCurrency(e.rent_amount)}</td>
                    <td className="px-5 py-3 font-medium text-primary">{formatCurrency(e.commission_amount)}</td>
                    <td className="px-5 py-3">{formatCurrency(e.landlord_share)}</td>
                    <td className="px-5 py-3"><StatusBadge color="blue">{e.commission_type?.replace(/_/g, ' ')}</StatusBadge></td>
                  </tr>
                ))}
                {ledger.length === 0 && (
                  <tr><td colSpan="7" className="px-5 py-8 text-center text-muted-foreground">No commission entries yet</td></tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {tab === 'agreements' && (
        <div className="bg-card rounded-xl border border-border overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="bg-muted/50">
                  <th className="text-left px-5 py-3 font-medium text-muted-foreground">Landlord</th>
                  <th className="text-left px-5 py-3 font-medium text-muted-foreground">Property</th>
                  <th className="text-left px-5 py-3 font-medium text-muted-foreground">Type</th>
                  <th className="text-left px-5 py-3 font-medium text-muted-foreground">Value</th>
                  <th className="text-left px-5 py-3 font-medium text-muted-foreground">Effective From</th>
                  <th className="text-left px-5 py-3 font-medium text-muted-foreground">Effective To</th>
                  <th className="text-left px-5 py-3 font-medium text-muted-foreground">Status</th>
                  <th className="text-left px-5 py-3 font-medium text-muted-foreground">Actions</th>
                </tr>
              </thead>
              <tbody>
                {agreements.map(a => (
                  <tr key={a.id} className="border-t border-border hover:bg-muted/30 transition-colors">
                    <td className="px-5 py-3 font-medium">{getLandlordName(a.landlord_id)}</td>
                    <td className="px-5 py-3 text-muted-foreground">{getPropertyAddress(a.property_id)}</td>
                    <td className="px-5 py-3"><StatusBadge color="blue">{a.type?.replace(/_/g, ' ')}</StatusBadge></td>
                    <td className="px-5 py-3 font-medium">
                      {a.type === 'percentage' ? `${a.value}%` : formatCurrency(a.value)}
                    </td>
                    <td className="px-5 py-3 text-muted-foreground">{a.effective_from || '—'}</td>
                    <td className="px-5 py-3 text-muted-foreground">{a.effective_to || <span className="text-emerald-600 font-medium">Active</span>}</td>
                    <td className="px-5 py-3">
                      {a.type === 'one_time' && a.one_time_applied ? (
                        <StatusBadge color="gray">Applied</StatusBadge>
                      ) : a.effective_to ? (
                        <StatusBadge color="gray">Ended {a.effective_to}</StatusBadge>
                      ) : (
                        <StatusBadge color="green">Active</StatusBadge>
                      )}
                    </td>
                    <td className="px-5 py-3">
                      {isAdmin ? (
                        <div className="flex gap-1">
                          <Button variant="ghost" size="sm" onClick={() => setEditAgreement(a)}>
                            <Pencil className="w-4 h-4" />
                          </Button>
                          <Button variant="ghost" size="sm" className="text-destructive hover:text-destructive" onClick={() => setConfirmDelete(a)}>
                            <Trash2 className="w-4 h-4" />
                          </Button>
                        </div>
                      ) : (
                        <Lock className="w-4 h-4 text-muted-foreground" />
                      )}
                    </td>
                  </tr>
                ))}
                {agreements.length === 0 && (
                  <tr><td colSpan="6" className="px-5 py-8 text-center text-muted-foreground">No agreements set up</td></tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {tab === 'invoices' && (
        <ManualInvoicesTab landlords={landlords} properties={properties} />
      )}

      <Dialog open={showForm} onOpenChange={setShowForm}>
        <DialogContent className="max-w-lg">
          <DialogHeader><DialogTitle>Add Commission Agreement</DialogTitle></DialogHeader>
          <AgreementForm landlords={landlords} properties={properties} onSubmit={handleAddAgreement} onCancel={() => setShowForm(false)} />
        </DialogContent>
      </Dialog>

      <Dialog open={!!editAgreement} onOpenChange={v => { if (!v) setEditAgreement(null); }}>
        <DialogContent className="max-w-lg">
          <DialogHeader><DialogTitle>Edit Commission Agreement</DialogTitle></DialogHeader>
          {editAgreement && (
            <AgreementForm
              landlords={landlords}
              properties={properties}
              onSubmit={handleEditAgreement}
              onCancel={() => setEditAgreement(null)}
              initialData={{ landlord_id: editAgreement.landlord_id, property_id: editAgreement.property_id || '', type: editAgreement.type, value: editAgreement.value, notes: editAgreement.notes || '', effective_from: editAgreement.effective_from || '', effective_to: editAgreement.effective_to || '' }}
            />
          )}
        </DialogContent>
      </Dialog>

      <ConfirmDialog
        open={!!confirmDelete}
        title="Delete Commission Agreement"
        description={`Delete commission agreement for "${getLandlordName(confirmDelete?.landlord_id)}"? All linked commission ledger entries will be recalculated using any remaining agreement, or set to £0 if none exists.`}
        onConfirm={() => handleDeleteAgreement(confirmDelete)}
        onCancel={() => setConfirmDelete(null)}
      />
    </div>
  );
}

import React, { useState } from 'react';
import { useLandlords, useProperties, useTenants, useRentPayments, useCommissionLedger, useLandlordPayouts, usePaymentExtras, usePropertyDocuments, useRentHistoryAll } from '@/hooks/useAllData';
import { useExpenses } from '@/hooks/useExpenses';

import { useMaintenanceRequests } from '@/hooks/useMaintenanceRequests';
import { calculateArrears, formatCurrency, getPropertyCertStatus } from '@/lib/computations';
import { buildTenantInvoices, buildLandlordStatements } from '@/lib/invoices';
import { analyseVacancies } from '@/lib/vacancies';
import { useCommissionAgreements } from '@/hooks/useAllData';
import StatCard from '@/components/ui/StatCard';
import StatusBadge from '@/components/ui/StatusBadge';
import RentDuePanel from '@/components/notifications/RentDuePanel';
import { Link, useNavigate } from 'react-router-dom';
import { Button } from '@/components/ui/button';
import { Banknote, PieChart, Wallet, AlertTriangle, ShieldCheck, Users, Building2, UserCheck, Wrench, FileText, ChevronDown, ChevronUp, ChevronLeft, ChevronRight, Receipt, Home, ArrowRight, DoorOpen } from 'lucide-react';
import { format, parseISO } from 'date-fns';

// Cert categories used by Dashboard alerts
const CERT_TYPES = [
  { catKey: 'gas',        label: 'Gas' },
  { catKey: 'electrical', label: 'Electrical' },
  { catKey: 'epc',        label: 'EPC' },
  { catKey: 'license',    label: 'License' },
];

export default function Dashboard() {
  const navigate = useNavigate();
  const { data: landlords = [] } = useLandlords();
  const { data: properties = [] } = useProperties();
  const { data: tenants = [] } = useTenants();
  const { data: rentPayments = [] } = useRentPayments();
  const { data: commissionLedger = [] } = useCommissionLedger();
  const { data: payouts = [] } = useLandlordPayouts();
  const { data: maintenanceRequests = [] } = useMaintenanceRequests();
  const { data: expenses = [] } = useExpenses();
  const { data: propertyDocuments = [] } = usePropertyDocuments();
  const { data: rentHistory = [] } = useRentHistoryAll();
  const { data: commissionAgreements = [] } = useCommissionAgreements();
  const [alertsExpanded, setAlertsExpanded] = useState(false);
  // Dashboard month filter — defaults to the current month; arrows page back/forward.
  const [selectedMonth, setSelectedMonth] = useState(() => format(new Date(), 'yyyy-MM'));
  const currentMonth = format(new Date(), 'yyyy-MM');
  const isCurrentMonth = selectedMonth === currentMonth;
  const shiftMonth = (delta) => {
    const [y, m] = selectedMonth.split('-').map(Number);
    const d = new Date(y, m - 1 + delta, 1);
    setSelectedMonth(format(d, 'yyyy-MM'));
  };
  const monthLabel = format(new Date(`${selectedMonth}-01`), 'MMMM yyyy');
  const inMonth = (dateStr) => (dateStr || '').slice(0, 7) === selectedMonth;

  const totalRent = rentPayments.reduce((s, p) => s + (p.amount || 0), 0);
  const totalCommission = commissionLedger.reduce((s, e) => s + (e.commission_amount || 0), 0);

  // Proper invoice-based figures (rent-history aware, arrears carried forward).
  const tenantInvoices = React.useMemo(() => buildTenantInvoices({
    tenants, properties, landlords, rentPayments, rentHistoryAll: rentHistory,
  }), [tenants, properties, landlords, rentPayments, rentHistory]);

  // Total invoiced = sum of each real (non-upcoming) invoice's rent + charges,
  // i.e. what tenants were actually billed — distinct from what was collected.
  const totalInvoiced = React.useMemo(() => tenantInvoices
    .filter(inv => !inv.is_upcoming)
    .reduce((s, inv) => s + (Number(inv.rent_amount || 0) + Number(inv.manual_charges_total || 0)), 0), [tenantInvoices]);

  // Landlord statements drive what is owed / paid to landlords.
  const landlordStatements = React.useMemo(() => buildLandlordStatements({
    landlords, properties, tenants, rentPayments, commissionLedger,
    expenses, landlordPayouts: payouts, paymentExtras: [], maintenanceRequests,
    commissionAgreements, rentHistoryAll: rentHistory,
  }), [landlords, properties, tenants, rentPayments, commissionLedger, expenses, payouts, maintenanceRequests, commissionAgreements, rentHistory]);

  const totalPaidOut = payouts.reduce((s, p) => s + (p.payment_mode === 'split' ? (p.bank_amount || 0) + (p.cash_amount || 0) : (p.amount || 0)), 0);
  const outstandingBalance = landlordStatements.reduce((s, m) => s + Math.max(0, Number(m.balance_due || 0)), 0);
  const totalLandlordShare = 0; // (legacy var kept for any downstream references)

  // ── Month-scoped figures (respond to the month filter) ──
  const monthRentCollected = rentPayments
    .filter(p => inMonth(p.period_month || p.payment_date))
    .reduce((s, p) => s + (p.amount || 0), 0);
  const monthInvoiced = tenantInvoices
    .filter(inv => !inv.is_upcoming && inv.period_month === selectedMonth)
    .reduce((s, inv) => s + (Number(inv.rent_amount || 0) + Number(inv.manual_charges_total || 0)), 0);
  const monthCommission = landlordStatements
    .filter(m => m.period_month === selectedMonth)
    .reduce((s, m) => s + Number(m.commission_total || 0), 0);
  const monthOutstandingToLandlords = landlordStatements
    .filter(m => m.period_month === selectedMonth)
    .reduce((s, m) => s + Math.max(0, Number(m.balance_due || 0)), 0);
  const monthPaidToLandlords = payouts
    .filter(p => inMonth(p.payment_date))
    .reduce((s, p) => s + (p.payment_mode === 'split' ? (p.bank_amount || 0) + (p.cash_amount || 0) : (p.amount || 0)), 0);

  // Vacancy analysis (empty now + becoming empty within 30 days).
  const { vacantNow, becomingEmpty } = React.useMemo(() => analyseVacancies(properties, tenants, { days: 30 }), [properties, tenants]);

  // Arrears "as of" the selected month (cap at that month for past months; for
  // the current month, no cap = up to today).
  const arrearsCutoff = isCurrentMonth ? null : selectedMonth;
  const tenantsInArrears = tenants.filter(t => {
    if (t.status === 'ended') return false;
    const tPayments = rentPayments.filter(p => p.tenant_id === t.id);
    const tHistory = rentHistory.filter(r => r.tenant_id === t.id);
    return calculateArrears(t, tPayments, tHistory, arrearsCutoff) > 0;
  });

  // Build expired / expiring lists from PropertyDocument-derived statuses
  const expiredCerts = [];
  const soonExpiring = [];
  properties.forEach(p => {
    const status = getPropertyCertStatus(p.id, propertyDocuments);
    CERT_TYPES.forEach(({ catKey, label }) => {
      if (status[catKey].status === 'expired')  expiredCerts.push({ property: p, type: label });
      if (status[catKey].status === 'expiring') soonExpiring.push({ property: p, type: label });
    });
  });

  const alerts = [
    ...tenantsInArrears.map(t => ({
      type: 'red',
      msg: `${t.name} is in arrears (${formatCurrency(calculateArrears(t, rentPayments.filter(p => p.tenant_id === t.id), rentHistory.filter(r => r.tenant_id === t.id), arrearsCutoff))})`,
      link: `/PropertyDetail?id=${t.property_id}&tab=arrears`
    })),
    ...expiredCerts.map(c => ({ type: 'red', msg: `${c.type} cert expired — ${c.property.address.split(',')[0]}`, link: `/PropertyDetail?id=${c.property.id}&tab=certificates` })),
    ...soonExpiring.map(c => ({ type: 'yellow', msg: `${c.type} cert expiring soon — ${c.property.address.split(',')[0]}`, link: `/PropertyDetail?id=${c.property.id}&tab=certificates` })),
    ...becomingEmpty.map(v => ({ type: 'yellow', msg: `${v.property.address.split(',')[0]} becoming empty in ${v.daysLeft} day${v.daysLeft === 1 ? '' : 's'} (${format(parseISO(v.endDate), 'd MMM')})`, link: '/Vacancies' })),
    ...(outstandingBalance > 500 ? [{ type: 'yellow', msg: `Outstanding landlord balance: ${formatCurrency(outstandingBalance)}`, link: '/LandlordStatements' }] : []),
  ];

  const visibleAlerts = alertsExpanded ? alerts : alerts.slice(0, 4);

  const recentPayments = [...rentPayments]
    .sort((a, b) => (b.payment_date || '').localeCompare(a.payment_date || ''))
    .slice(0, 8);

  return (
    <div>
      {/* Header */}
      <div className="mb-8 flex items-start justify-between gap-4 flex-wrap">
        <div>
          <h1 className="text-xl sm:text-2xl font-semibold text-foreground tracking-tight">Dashboard</h1>
          <p className="text-sm text-muted-foreground mt-1">{format(new Date(), 'EEEE, d MMMM yyyy')} · ASA Estates Ltd</p>
        </div>
        {/* Month filter */}
        <div className="flex items-center gap-1 bg-card border border-border rounded-lg px-1.5 py-1">
          <button onClick={() => shiftMonth(-1)} className="p-1.5 rounded-md hover:bg-muted text-muted-foreground" title="Previous month">
            <ChevronLeft className="w-4 h-4" />
          </button>
          <span className="text-sm font-semibold px-2 min-w-[120px] text-center tabular-nums">{monthLabel}</span>
          <button onClick={() => shiftMonth(1)} disabled={isCurrentMonth}
            className="p-1.5 rounded-md hover:bg-muted text-muted-foreground disabled:opacity-30 disabled:hover:bg-transparent" title="Next month">
            <ChevronRight className="w-4 h-4" />
          </button>
          {!isCurrentMonth && (
            <button onClick={() => setSelectedMonth(currentMonth)} className="text-xs text-primary px-2 hover:underline">Today</button>
          )}
        </div>
      </div>

      {/* Portfolio KPIs */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mb-6">
        <Link to="/Properties">
          <div className="bg-card border border-border rounded-xl p-5 hover:shadow-md transition-shadow cursor-pointer group">
            <div className="flex items-start justify-between">
              <div>
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Properties</p>
                <p className="text-2xl font-semibold mt-1 tabular-nums">{properties.length}</p>
                <p className="text-xs text-muted-foreground mt-1">{properties.filter(p => p.status === 'occupied').length} occupied · {properties.filter(p => p.status === 'vacant').length} vacant</p>
              </div>
              <div className="p-2.5 rounded-lg bg-primary/10 text-primary"><Building2 className="w-5 h-5" /></div>
            </div>
            <div className="flex items-center gap-1 mt-3 text-xs text-primary font-medium group-hover:underline">View all <ArrowRight className="w-3 h-3" /></div>
          </div>
        </Link>
        <Link to="/Tenants">
          <div className="bg-card border border-border rounded-xl p-5 hover:shadow-md transition-shadow cursor-pointer group">
            <div className="flex items-start justify-between">
              <div>
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Tenants</p>
                <p className="text-2xl font-semibold mt-1 tabular-nums">{tenants.filter(t => t.status === 'active').length}</p>
                <p className="text-xs text-muted-foreground mt-1">{tenantsInArrears.length > 0 ? <span className="text-rose-600 font-semibold">{tenantsInArrears.length} in arrears</span> : 'All clear'}</p>
              </div>
              <div className="p-2.5 rounded-lg bg-sky-50 text-sky-600"><UserCheck className="w-5 h-5" /></div>
            </div>
            <div className="flex items-center gap-1 mt-3 text-xs text-primary font-medium group-hover:underline">View all <ArrowRight className="w-3 h-3" /></div>
          </div>
        </Link>
        <Link to="/Landlords">
          <div className="bg-card border border-border rounded-xl p-5 hover:shadow-md transition-shadow cursor-pointer group">
            <div className="flex items-start justify-between">
              <div>
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Landlords</p>
                <p className="text-2xl font-semibold mt-1 tabular-nums">{landlords.length}</p>
                <p className="text-xs text-muted-foreground mt-1">{landlords.filter(l => l.status === 'active').length} active</p>
              </div>
              <div className="p-2.5 rounded-lg bg-violet-50 text-violet-600"><Users className="w-5 h-5" /></div>
            </div>
            <div className="flex items-center gap-1 mt-3 text-xs text-primary font-medium group-hover:underline">View all <ArrowRight className="w-3 h-3" /></div>
          </div>
        </Link>
        <Link to="/Maintenance">
          <div className="bg-card border border-border rounded-xl p-5 hover:shadow-md transition-shadow cursor-pointer group">
            <div className="flex items-start justify-between">
              <div>
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Maintenance</p>
                <p className="text-2xl font-semibold mt-1 tabular-nums">{maintenanceRequests.filter(r => r.status === 'pending' || r.status === 'in_progress').length}</p>
                <p className="text-xs text-muted-foreground mt-1">
                  {maintenanceRequests.filter(r => r.priority === 'emergency' && r.status !== 'resolved' && r.status !== 'cancelled').length > 0
                    ? <span className="text-rose-600 font-semibold">{maintenanceRequests.filter(r => r.priority === 'emergency' && r.status !== 'resolved' && r.status !== 'cancelled').length} emergency</span>
                    : 'Open jobs'}
                </p>
              </div>
              <div className="p-2.5 rounded-lg bg-orange-50 text-orange-600"><Wrench className="w-5 h-5" /></div>
            </div>
            <div className="flex items-center gap-1 mt-3 text-xs text-primary font-medium group-hover:underline">View all <ArrowRight className="w-3 h-3" /></div>
          </div>
        </Link>
      </div>

      {/* Financials Row */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mb-8">
        <Link to="/Rent">
          <StatCard label="Rent Collected" value={formatCurrency(monthRentCollected)} icon={Banknote} color="success" trend={monthLabel} />
        </Link>
        <Link to="/Commission">
          <StatCard label="Commission Earned" value={formatCurrency(monthCommission)} icon={PieChart} color="primary" trend={monthLabel} />
        </Link>
        <Link to="/LandlordStatements">
          <StatCard label="Outstanding to Landlords" value={formatCurrency(Math.max(0, monthOutstandingToLandlords))} icon={Wallet} color="warning" trend={monthLabel} />
        </Link>
        <Link to="/LandlordStatements">
          <StatCard label="Paid to Landlords" value={formatCurrency(monthPaidToLandlords)} icon={Wallet} color="success" trend={monthLabel} />
        </Link>
      </div>

      {/* Alerts */}
      {alerts.length > 0 && (
        <div className="mb-8">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-sm font-semibold text-foreground">🚨 Alerts <span className="ml-1 text-xs bg-rose-100 text-rose-700 rounded-full px-2 py-0.5">{alerts.length}</span></h2>
            {alerts.length > 4 && (
              <button onClick={() => setAlertsExpanded(v => !v)} className="text-xs text-primary flex items-center gap-1 hover:underline">
                {alertsExpanded ? <><ChevronUp className="w-3 h-3" />Show less</> : <><ChevronDown className="w-3 h-3" />Show all</>}
              </button>
            )}
          </div>
          <div className="space-y-2">
            {visibleAlerts.map((a, i) => (
              <Link
                key={i}
                to={a.link}
                className={`flex items-center gap-3 px-4 py-2.5 rounded-lg text-sm font-medium transition-colors ${
                  a.type === 'red' ? 'bg-rose-50 text-rose-700 hover:bg-rose-100 border border-rose-200' :
                  'bg-amber-50 text-amber-700 hover:bg-amber-100 border border-amber-200'
                }`}
              >
                <AlertTriangle className="w-4 h-4 shrink-0" />
                <span className="flex-1">{a.msg}</span>
                <ArrowRight className="w-3.5 h-3.5 opacity-50" />
              </Link>
            ))}
          </div>
        </div>
      )}

      {/* Compliance Row */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mb-8">
        <Link to="/Certificates">
          <StatCard label="Expired Certificates" value={expiredCerts.length} icon={ShieldCheck} color={expiredCerts.length > 0 ? 'destructive' : 'success'} trend="Action required" />
        </Link>
        <Link to="/Certificates">
          <StatCard label="Expiring Soon" value={soonExpiring.length} icon={ShieldCheck} color={soonExpiring.length > 0 ? 'warning' : 'success'} trend="Within 30 days" />
        </Link>
        <Link to="/Vacancies">
          <StatCard label="Becoming Vacant" value={becomingEmpty.length} icon={DoorOpen} color={becomingEmpty.length > 0 ? 'warning' : 'success'} trend="Next 30 days" />
        </Link>
        <Link to="/Arrears">
          <StatCard label="Tenants in Arrears" value={tenantsInArrears.length} icon={AlertTriangle} color={tenantsInArrears.length > 0 ? 'destructive' : 'success'} trend={isCurrentMonth ? 'Outstanding rent' : `As of ${monthLabel}`} />
        </Link>
        <Link to="/TenantInvoices">
          <StatCard label="Tenant Invoices" value={formatCurrency(monthInvoiced)} icon={FileText} color="primary" trend={`Invoiced · ${monthLabel}`} />
        </Link>
      </div>

      {/* Rent Due Soon */}
      <div className="mb-8">
        <RentDuePanel tenants={tenants} properties={properties} />
      </div>

      {/* Recent Rent Payments */}
      <div className="bg-card rounded-xl border border-border overflow-hidden">
        <div className="px-5 py-4 border-b border-border flex items-center justify-between">
          <h2 className="text-sm font-semibold text-foreground">Recent Rent Payments</h2>
          <Link to="/Rent" className="text-xs text-primary hover:underline flex items-center gap-1">View all <ArrowRight className="w-3 h-3" /></Link>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-muted/50">
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Tenant</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Property</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Amount</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Date</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Period</th>
              </tr>
            </thead>
            <tbody>
              {recentPayments.map(rp => {
                const tenant = tenants.find(t => t.id === rp.tenant_id);
                const property = properties.find(p => p.id === rp.property_id);
                return (
                  <tr key={rp.id} className="border-t border-border hover:bg-muted/30 transition-colors">
                    <td className="px-5 py-3 font-medium">{tenant?.name || 'Unknown'}</td>
                    <td className="px-5 py-3 text-xs text-muted-foreground">{property?.address?.split(',')[0] || '-'}</td>
                    <td className="px-5 py-3 text-emerald-600 font-semibold tabular-nums">{formatCurrency(rp.amount)}</td>
                    <td className="px-5 py-3 text-muted-foreground">{rp.payment_date ? format(parseISO(rp.payment_date), 'dd MMM yyyy') : '-'}</td>
                    <td className="px-5 py-3">{rp.period_month}</td>
                  </tr>
                );
              })}
              {rentPayments.length === 0 && (
                <tr><td colSpan="5" className="px-5 py-8 text-center text-muted-foreground">No rent payments recorded yet</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { saveAs } from 'file-saver';
import { base44 } from '@/api/base44Client';
import { BACKUP_ENTITIES as ENTITIES, buildBackupZip, monthLabelFor } from '@/lib/backupZip';
import PageHeader from '@/components/ui/PageHeader';
import MonthlyDriveDownloads from '@/components/backup/MonthlyDriveDownloads';
import { Button } from '@/components/ui/button';
import { Download, CheckCircle, AlertCircle, Loader2, FolderArchive, Cloud } from 'lucide-react';
import { format } from 'date-fns';

export default function DataBackup() {
  const [running, setRunning] = useState(false);
  const [log, setLog] = useState([]);     // [{label, count, status}]
  const [done, setDone] = useState(null);  // {month, total}
  const [error, setError] = useState(null);

  const pushLog = (entry) => setLog((l) => [...l, entry]);

  const runBackup = async () => {
    setRunning(true); setLog([]); setDone(null); setError(null);
    const monthKey = format(new Date(), 'yyyy-MM');
    const dateStamp = format(new Date(), 'yyyy-MM-dd');

    try {
      // 1. Fetch every entity
      const data = {};
      for (const e of ENTITIES) {
        try {
          const records = await base44.entities[e.key].list();
          data[e.key] = Array.isArray(records) ? records : [];
          pushLog({ label: e.label, count: data[e.key].length, status: 'ok' });
        } catch (err) {
          data[e.key] = [];
          pushLog({ label: e.label, count: 0, status: 'skip' });
        }
      }

      // 2. Build the organised ZIP (shared with the previous-months downloader)
      const { blob, totalRecords } = await buildBackupZip(data, { monthKey, dateStamp });
      saveAs(blob, `ASA-Estates-Backup-${monthKey}.zip`);

      setDone({ month: monthLabelFor(monthKey), total: totalRecords });
    } catch (err) {
      setError(err.message || String(err));
    } finally {
      setRunning(false);
    }
  };

  return (
    <div>
      <PageHeader
        title="Data Backup"
        description="Export all your data into an organised, readable backup you can save to Google Drive."
      />

      <div className="max-w-2xl">
        <div className="bg-card border border-border rounded-xl p-6">
          <div className="flex items-start gap-4">
            <div className="w-12 h-12 rounded-xl bg-primary/10 flex items-center justify-center flex-shrink-0">
              <FolderArchive className="w-6 h-6 text-primary" />
            </div>
            <div className="flex-1">
              <h2 className="font-semibold text-lg">Monthly backup</h2>
              <p className="text-sm text-muted-foreground mt-1 leading-relaxed">
                Creates a ZIP with every data set as a formatted Excel file (plus CSV),
                a master workbook with all data, a branded summary, and a raw-JSON copy for restore.
                Organised into dated folders. Download it, then drag the ZIP into your Google Drive
                &ldquo;ASA Estates Backups&rdquo; folder.
              </p>

              <Button onClick={runBackup} disabled={running} className="mt-5">
                {running ? <><Loader2 className="w-4 h-4 mr-2 animate-spin" /> Backing up&hellip;</>
                         : <><Download className="w-4 h-4 mr-2" /> Back up now</>}
              </Button>
            </div>
          </div>

          {/* Progress log */}
          {log.length > 0 && (
            <div className="mt-6 border-t border-border pt-4 space-y-1.5 max-h-72 overflow-y-auto">
              {log.map((l, i) => (
                <div key={i} className="flex items-center justify-between text-sm">
                  <span className="text-muted-foreground">{l.label}</span>
                  <span className={l.status === 'ok' ? 'text-foreground font-medium' : 'text-muted-foreground/50'}>
                    {l.status === 'ok' ? `${l.count} records` : 'skipped'}
                  </span>
                </div>
              ))}
            </div>
          )}

          {done && (
            <div className="mt-5 flex items-start gap-2 bg-emerald-50 border border-emerald-200 rounded-lg p-3 text-sm text-emerald-800">
              <CheckCircle className="w-4 h-4 mt-0.5 flex-shrink-0" />
              <div>
                Backup for <strong>{done.month}</strong> downloaded &mdash; {done.total} records.
                Now drag <strong>ASA-Estates-Backup-{format(new Date(), 'yyyy-MM')}.zip</strong> into your Google Drive backups folder.
              </div>
            </div>
          )}

          {error && (
            <div className="mt-5 flex items-start gap-2 bg-red-50 border border-red-200 rounded-lg p-3 text-sm text-red-800">
              <AlertCircle className="w-4 h-4 mt-0.5 flex-shrink-0" />
              <div>Backup failed: {error}</div>
            </div>
          )}
        </div>

        <div className="mt-4 bg-secondary/40 border border-border rounded-xl p-6">
          <div className="flex items-start gap-4">
            <div className="w-12 h-12 rounded-xl bg-primary/10 flex items-center justify-center flex-shrink-0">
              <Cloud className="w-6 h-6 text-primary" />
            </div>
            <div className="flex-1">
              <h2 className="font-semibold text-lg">Automatic Google Drive backup</h2>
              <p className="text-sm text-muted-foreground mt-1 leading-relaxed">
                Runs automatically on the 1st of every month at 9am. Each month gets its own folder in your Drive
                &ldquo;ASA Estates Backups&rdquo; folder (e.g. <code>2026-09</code>) containing a full JSON backup plus
                8 Excel workbooks &mdash; Properties &amp; Tenants, Payments &amp; Payouts, Commission &amp; Invoices,
                Ledger &amp; Banking, Maintenance &amp; Inspections, CRM &amp; Communications, Documents &amp; Signatures,
                and Admin &amp; Audit &mdash; each with one tab per data set, so payments and records are easy to track.
              </p>
            </div>
          </div>
        </div>

        <MonthlyDriveDownloads />

        <div className="mt-4 text-xs text-muted-foreground leading-relaxed">
          <strong>Inside the ZIP:</strong> <code>ASA Estates Backups / {format(new Date(), 'yyyy-MM')} (this month) / </code>
          &rarr; <code>00_SUMMARY.html</code>, one folder per data set with Excel + CSV,
          a master workbook, and <code>_raw_json/</code> for a complete restore.
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { useParams, useNavigate, Link } from "react-router-dom";
import { base44 } from "@/api/base44Client";
import { useToast } from "@/components/ui/use-toast";
import {
  ArrowLeft, Send, XCircle, Download, FileText, Clock,
  User, Mail, Eye, CheckCircle, AlertCircle
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import StatusBadge from "@/components/documents/StatusBadge";
import DocumentPreview from "@/components/documents/DocumentPreview";
import moment from "moment";

export default function DocumentDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { toast } = useToast();
  const [doc, setDoc] = useState(null);
  const [signers, setSigners] = useState([]);
  const [fields, setFields] = useState([]);
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadData();
  }, [id]);

  const loadData = async () => {
    setLoading(true);
    const [d, s, f, e] = await Promise.all([
      base44.entities.Document.get(id),
      base44.entities.Signer.filter({ document_id: id }),
      base44.entities.SignatureField.filter({ document_id: id }),
      base44.entities.AuditEvent.filter({ document_id: id }, "-created_date"),
    ]);
    setDoc(d);
    setSigners(s);
    setFields(f);
    setEvents(e);
    setLoading(false);
  };

  const handleVoid = async () => {
    await base44.entities.Document.update(id, { status: "voided" });
    await base44.entities.AuditEvent.create({ document_id: id, event_type: "voided" });
    toast({ title: "Document voided" });
    loadData();
  };

  const handleResend = async (signer) => {
    await base44.functions.invoke("sendSignerInvites", {
      documentId: id,
      title: doc.title,
      message: "This is a reminder to sign this document.",
      appUrl: window.location.origin,
      signers: [{ name: signer.name, email: signer.email, access_token: signer.access_token }],
    });
    toast({ title: "Reminder sent", description: `Resent to ${signer.email}` });
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-20">
        <div className="w-8 h-8 border-4 border-primary/20 border-t-primary rounded-full animate-spin" />
      </div>
    );
  }

  if (!doc) {
    return (
      <div className="text-center py-20">
        <p className="text-muted-foreground">Document not found</p>
        <Link to="/ESignatures" className="text-primary text-sm mt-2 inline-block">Back to E-Signatures</Link>
      </div>
    );
  }

  const signedCount = signers.filter((s) => s.status === "signed").length;
  const progress = signers.length > 0 ? (signedCount / signers.length) * 100 : 0;

  const eventIcons = {
    created: FileText,
    sent: Send,
    opened: Eye,
    viewed: Eye,
    signed: CheckCircle,
    declined: AlertCircle,
    completed: CheckCircle,
    voided: XCircle,
    consent_given: CheckCircle,
    field_completed: CheckCircle,
  };

  return (
    <div>
      <div className="flex items-center gap-3 mb-6">
        <Button variant="ghost" size="icon" onClick={() => navigate("/ESignatures")}>
          <ArrowLeft className="w-5 h-5" />
        </Button>
        <div className="flex-1">
          <div className="flex items-center gap-3">
            <h1 className="text-xl font-bold text-foreground">{doc.title}</h1>
            <StatusBadge status={doc.status} />
          </div>
          <p className="text-sm text-muted-foreground mt-0.5">
            Created {moment(doc.created_date).format("MMM D, YYYY [at] h:mm A")}
          </p>
        </div>
        <div className="flex gap-2">
          {doc.signed_file_url && (
            <a href={doc.signed_file_url} target="_blank" rel="noopener" download>
              <Button variant="outline" size="sm" className="gap-2">
                <Download className="w-4 h-4" /> Download
              </Button>
            </a>
          )}
          {["sent", "viewed", "partially_signed"].includes(doc.status) && (
            <Button variant="outline" size="sm" className="gap-2 text-destructive" onClick={handleVoid}>
              <XCircle className="w-4 h-4" /> Void
            </Button>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Main content */}
        <div className="lg:col-span-2 space-y-6">
          {/* Progress */}
          <div className="bg-white rounded-xl border border-border p-5">
            <div className="flex items-center justify-between mb-3">
              <h2 className="font-semibold">Signing Progress</h2>
              <span className="text-sm text-muted-foreground">{signedCount} of {signers.length} signed</span>
            </div>
            <Progress value={progress} className="h-2" />
          </div>

          {/* Document Preview */}
          <DocumentPreview doc={doc} />

          {/* Signers */}
          <div className="bg-white rounded-xl border border-border p-5">
            <h2 className="font-semibold mb-4">Signers</h2>
            <div className="space-y-3">
              {signers.map((signer) => (
                <div key={signer.id} className="flex items-center justify-between p-3 rounded-lg bg-muted/50">
                  <div className="flex items-center gap-3">
                    <div
                      className="w-8 h-8 rounded-full flex items-center justify-center text-white text-sm font-medium"
                      style={{ backgroundColor: signer.color || "#3b82f6" }}
                    >
                      {signer.name?.[0]?.toUpperCase()}
                    </div>
                    <div>
                      <p className="text-sm font-medium">{signer.name}</p>
                      <p className="text-xs text-muted-foreground">{signer.email}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <StatusBadge status={signer.status} type="signer" />
                    {signer.status === "pending" && ["sent", "viewed", "partially_signed"].includes(doc.status) && (
                      <Button variant="ghost" size="sm" onClick={() => handleResend(signer)} className="gap-1 text-xs">
                        <Send className="w-3 h-3" /> Resend
                      </Button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Sidebar - Audit Trail */}
        <div className="space-y-6">
          <div className="bg-white rounded-xl border border-border p-5">
            <h2 className="font-semibold mb-4">Activity</h2>
            <div className="space-y-3">
              {events.length === 0 ? (
                <p className="text-sm text-muted-foreground">No activity yet</p>
              ) : (
                events.map((event) => {
                  const Icon = eventIcons[event.event_type] || Clock;
                  return (
                    <div key={event.id} className="flex items-start gap-3">
                      <div className="w-7 h-7 rounded-full bg-muted flex items-center justify-center shrink-0 mt-0.5">
                        <Icon className="w-3.5 h-3.5 text-muted-foreground" />
                      </div>
                      <div className="min-w-0">
                        <p className="text-sm capitalize">{event.event_type.replace(/_/g, " ")}</p>
                        <p className="text-xs text-muted-foreground">
                          {moment(event.created_date).format("MMM D, h:mm A")}
                        </p>
                      </div>
                    </div>
                  );
                })
              )}
            </div>
          </div>

          {doc.message && (
            <div className="bg-white rounded-xl border border-border p-5">
              <h2 className="font-semibold mb-2">Message</h2>
              <p className="text-sm text-muted-foreground">{doc.message}</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { base44 } from "@/api/base44Client";
import { Link } from "react-router-dom";
import { Plus, Search, FileText, Send, CheckCircle, Clock } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { useToast } from "@/components/ui/use-toast";
import DocumentCard from "@/components/documents/DocumentCard";
import EmptyState from "@/components/documents/EmptyState";

const FILTERS = [
  { key: "all", label: "All", icon: FileText },
  { key: "draft", label: "Drafts", icon: Clock },
  { key: "active", label: "Out for Signature", icon: Send },
  { key: "completed", label: "Completed", icon: CheckCircle },
];

export default function ESignatures() {
  const [documents, setDocuments] = useState([]);
  const [signers, setSigners] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [filter, setFilter] = useState("all");
  const { toast } = useToast();

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    const [docs, signs] = await Promise.all([
      base44.entities.Document.list("-created_date", 100),
      base44.entities.Signer.list("-created_date", 500),
    ]);
    setDocuments(docs);
    setSigners(signs);
    setLoading(false);
  };

  const handleVoid = async (id) => {
    await base44.entities.Document.update(id, { status: "voided" });
    toast({ title: "Document voided" });
    loadData();
  };

  const handleDelete = async (id) => {
    await base44.entities.Document.delete(id);
    toast({ title: "Document deleted" });
    loadData();
  };

  const filteredDocs = documents.filter((doc) => {
    const matchesSearch = !search || doc.title?.toLowerCase().includes(search.toLowerCase());
    let matchesFilter = true;
    if (filter === "draft") matchesFilter = doc.status === "draft";
    else if (filter === "active") matchesFilter = ["sent", "viewed", "partially_signed"].includes(doc.status);
    else if (filter === "completed") matchesFilter = doc.status === "completed";
    return matchesSearch && matchesFilter;
  });

  const stats = {
    total: documents.length,
    draft: documents.filter((d) => d.status === "draft").length,
    active: documents.filter((d) => ["sent", "viewed", "partially_signed"].includes(d.status)).length,
    completed: documents.filter((d) => d.status === "completed").length,
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-20">
        <div className="w-8 h-8 border-4 border-primary/20 border-t-primary rounded-full animate-spin" />
      </div>
    );
  }

  return (
    <div>
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-8">
        <div>
          <h1 className="text-2xl font-bold text-foreground tracking-tight">E-Signatures</h1>
          <p className="text-sm text-muted-foreground mt-1">
            {stats.total} document{stats.total !== 1 ? "s" : ""} · {stats.active} awaiting signature
          </p>
        </div>
        <Link to="/documents/new">
          <Button className="gap-2">
            <Plus className="w-4 h-4" />
            New Document
          </Button>
        </Link>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-6">
        {[
          { label: "Total", value: stats.total, color: "text-foreground" },
          { label: "Drafts", value: stats.draft, color: "text-gray-600" },
          { label: "Awaiting", value: stats.active, color: "text-amber-600" },
          { label: "Completed", value: stats.completed, color: "text-emerald-600" },
        ].map((stat) => (
          <div key={stat.label} className="bg-white rounded-xl border border-border p-4">
            <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">{stat.label}</p>
            <p className={`text-2xl font-bold mt-1 ${stat.color}`}>{stat.value}</p>
          </div>
        ))}
      </div>

      {/* Filters + Search */}
      <div className="flex flex-col sm:flex-row gap-3 mb-6">
        <div className="flex gap-1 bg-muted p-1 rounded-lg">
          {FILTERS.map((f) => (
            <button
              key={f.key}
              onClick={() => setFilter(f.key)}
              className={`px-3 py-1.5 rounded-md text-sm font-medium transition-colors ${
                filter === f.key
                  ? "bg-white text-foreground shadow-sm"
                  : "text-muted-foreground hover:text-foreground"
              }`}
            >
              {f.label}
            </button>
          ))}
        </div>
        <div className="relative flex-1 max-w-sm">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            placeholder="Search documents..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-9"
          />
        </div>
      </div>

      {/* Documents List */}
      {filteredDocs.length === 0 ? (
        <EmptyState filtered={search || filter !== "all"} />
      ) : (
        <div className="space-y-3">
          {filteredDocs.map((doc) => (
            <DocumentCard
              key={doc.id}
              document={doc}
              signers={signers.filter((s) => s.document_id === doc.id)}
              onVoid={handleVoid}
              onDelete={handleDelete}
            />
          ))}
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { useEmailLogs } from '@/hooks/useEmailLogs';
import PageHeader from '@/components/ui/PageHeader';
import StatusBadge from '@/components/ui/StatusBadge';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Mail, Search } from 'lucide-react';
import { format, parseISO } from 'date-fns';

const TYPE_LABELS = {
  tenant_invoice: 'Tenant Invoice',
  landlord_statement: 'Landlord Statement',
  rent_reminder: 'Rent Reminder',
  other: 'Other',
};

export default function EmailLog() {
  const { data: logs } = useEmailLogs();
  const [search, setSearch] = useState('');
  const [filterType, setFilterType] = useState('all');

  const filtered = logs.filter(log => {
    if (filterType !== 'all' && log.type !== filterType) return false;
    if (search) {
      const q = search.toLowerCase();
      return (log.recipient_email || '').toLowerCase().includes(q) ||
        (log.recipient_name || '').toLowerCase().includes(q) ||
        (log.subject || '').toLowerCase().includes(q);
    }
    return true;
  });

  return (
    <div>
      <PageHeader
        title="Email Log"
        description="History of all emails opened via the system"
        actions={
          <div className="flex items-center gap-2 text-sm text-muted-foreground">
            <Mail className="w-4 h-4" />
            {logs.length} total emails
          </div>
        }
      />

      <div className="flex gap-3 mb-5">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input className="pl-9 h-9" placeholder="Search recipient, subject..." value={search} onChange={e => setSearch(e.target.value)} />
        </div>
        <Select value={filterType} onValueChange={setFilterType}>
          <SelectTrigger className="w-44 h-9"><SelectValue placeholder="All Types" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Types</SelectItem>
            <SelectItem value="tenant_invoice">Tenant Invoice</SelectItem>
            <SelectItem value="landlord_statement">Landlord Statement</SelectItem>
            <SelectItem value="rent_reminder">Rent Reminder</SelectItem>
            <SelectItem value="other">Other</SelectItem>
          </SelectContent>
        </Select>
      </div>

      <div className="bg-card rounded-xl border border-border overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-muted/50">
                <th className="text-left px-4 py-3 font-medium text-muted-foreground">Date</th>
                <th className="text-left px-4 py-3 font-medium text-muted-foreground">Recipient</th>
                <th className="text-left px-4 py-3 font-medium text-muted-foreground">Subject</th>
                <th className="text-left px-4 py-3 font-medium text-muted-foreground">Type</th>
                <th className="text-left px-4 py-3 font-medium text-muted-foreground">Status</th>
                <th className="text-left px-4 py-3 font-medium text-muted-foreground">Sent By</th>
              </tr>
            </thead>
            <tbody>
              {filtered.map(log => (
                <tr key={log.id} className="border-t border-border hover:bg-muted/30 transition-colors">
                  <td className="px-4 py-3 text-muted-foreground text-xs">
                    {log.created_date ? format(parseISO(log.created_date), 'dd MMM yyyy HH:mm') : '-'}
                  </td>
                  <td className="px-4 py-3">
                    <p className="font-medium">{log.recipient_name || log.recipient_email}</p>
                    <p className="text-xs text-muted-foreground">{log.recipient_email}</p>
                  </td>
                  <td className="px-4 py-3 max-w-xs truncate">{log.subject}</td>
                  <td className="px-4 py-3">
                    <StatusBadge color="blue">{TYPE_LABELS[log.type] || log.type}</StatusBadge>
                  </td>
                  <td className="px-4 py-3">
                    <StatusBadge color={log.status === 'opened' ? 'green' : 'red'}>
                      {log.status === 'opened' ? 'Opened' : 'Failed'}
                    </StatusBadge>
                  </td>
                  <td className="px-4 py-3 text-xs text-muted-foreground">{log.sent_by || '-'}</td>
                </tr>
              ))}
              {filtered.length === 0 && (
                <tr><td colSpan="6" className="px-4 py-10 text-center text-muted-foreground">No emails logged yet</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { base44 } from '@/api/base44Client';
import { useExpenses } from '@/hooks/useExpenses';
import { useProperties, useLandlords, useTenants } from '@/hooks/useAllData';
import { useQueryClient } from '@tanstack/react-query';
import { useRole } from '@/hooks/useRole';
import { logAction } from '@/lib/audit';
import { exportExpenses } from '@/lib/exportExcel';
import PageHeader from '@/components/ui/PageHeader';
import StatusBadge from '@/components/ui/StatusBadge';
import ConfirmDialog from '@/components/ui/ConfirmDialog';
import StatCard from '@/components/ui/StatCard';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Plus, Search, Trash2, Pencil, Download, Receipt } from 'lucide-react';
import { formatCurrency } from '@/lib/computations';
import { format, parseISO } from 'date-fns';

const CATEGORIES = ['maintenance', 'repairs', 'insurance', 'utilities', 'management_fee', 'legal', 'cleaning', 'other'];

function ExpenseForm({ expense, properties, tenants, onSubmit, onCancel }) {
  const [submitting, setSubmitting] = useState(false);
  const [data, setData] = useState(expense || {
    property_id: '', landlord_id: '', tenant_id: '', date: format(new Date(), 'yyyy-MM-dd'),
    category: 'maintenance', description: '', amount: '', paid_by: 'agency', reference: '', notes: ''
  });

  const handlePropertyChange = (propId) => {
    const prop = properties.find(p => p.id === propId);
    setData({ ...data, property_id: propId, landlord_id: prop?.landlord_id || '' });
  };

  return (
    <form onSubmit={async e => { e.preventDefault(); if (submitting) return; setSubmitting(true); try { await onSubmit({ ...data, amount: Number(data.amount) }); } finally { setSubmitting(false); } }} className="space-y-4">
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label>Property *</Label>
          <Select value={data.property_id} onValueChange={handlePropertyChange}>
            <SelectTrigger><SelectValue placeholder="Select property" /></SelectTrigger>
            <SelectContent>{properties.map(p => <SelectItem key={p.id} value={p.id}>{p.address}</SelectItem>)}</SelectContent>
          </Select>
        </div>
        <div className="space-y-2">
          <Label>Category *</Label>
          <Select value={data.category} onValueChange={v => setData({ ...data, category: v })}>
            <SelectTrigger><SelectValue /></SelectTrigger>
            <SelectContent>{CATEGORIES.map(c => <SelectItem key={c} value={c}>{c.replace(/_/g, ' ')}</SelectItem>)}</SelectContent>
          </Select>
        </div>
        <div className="space-y-2">
          <Label>Date *</Label>
          <Input type="date" value={data.date} onChange={e => setData({ ...data, date: e.target.value })} required />
        </div>
        <div className="space-y-2">
          <Label>Amount (£) *</Label>
          <Input type="number" min="0" step="0.01" value={data.amount} onChange={e => setData({ ...data, amount: e.target.value })} required />
        </div>
        <div className="space-y-2 sm:col-span-2">
          <Label>Description *</Label>
          <Input value={data.description} onChange={e => setData({ ...data, description: e.target.value })} required />
        </div>
        <div className="space-y-2">
          <Label>Paid By</Label>
          <Select value={data.paid_by} onValueChange={v => setData({ ...data, paid_by: v })}>
            <SelectTrigger><SelectValue /></SelectTrigger>
            <SelectContent>
              <SelectItem value="agency">Agency</SelectItem>
              <SelectItem value="landlord">Landlord</SelectItem>
            </SelectContent>
          </Select>
        </div>
        <div className="space-y-2">
          <Label>Tenant (optional)</Label>
          <Select value={data.tenant_id || ''} onValueChange={v => setData({ ...data, tenant_id: v })}>
            <SelectTrigger><SelectValue placeholder="None" /></SelectTrigger>
            <SelectContent>
              <SelectItem value={null}>None</SelectItem>
              {tenants.filter(t => !data.property_id || t.property_id === data.property_id).map(t => (
                <SelectItem key={t.id} value={t.id}>{t.name}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
        <div className="space-y-2">
          <Label>Reference</Label>
          <Input value={data.reference || ''} onChange={e => setData({ ...data, reference: e.target.value })} />
        </div>
      </div>
      <div className="space-y-2">
        <Label>Notes</Label>
        <Textarea value={data.notes || ''} onChange={e => setData({ ...data, notes: e.target.value })} rows={2} />
      </div>
      <div className="flex gap-3 justify-end pt-2">
        {onCancel && <Button type="button" variant="outline" onClick={onCancel}>Cancel</Button>}
        <Button type="submit" disabled={submitting}>{submitting ? 'Saving...' : expense ? 'Update Expense' : 'Add Expense'}</Button>
      </div>
    </form>
  );
}

export default function Expenses() {
  const { user, isAdmin } = useRole();
  const { data: expenses } = useExpenses();
  const { data: properties } = useProperties();
  const { data: landlords } = useLandlords();
  const { data: tenants } = useTenants();
  const queryClient = useQueryClient();
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState(null);
  const [search, setSearch] = useState('');
  const [confirmDelete, setConfirmDelete] = useState(null);

  const getProperty = (id) => properties.find(p => p.id === id);
  const getLandlord = (id) => landlords.find(l => l.id === id);

  const handleApprove = async (expense) => {
    await base44.entities.Expense.update(expense.id, { ...expense, approved: true });
    await logAction({ user, action: 'update', entityType: 'Expense', entityId: expense.id, summary: `Approved landlord expense: ${expense.description} £${expense.amount}`, oldValue: expense, newValue: { ...expense, approved: true } });
    queryClient.invalidateQueries({ queryKey: ['expenses'] });
  };

  const handleSubmit = async (data) => {
    const saveData = { ...data, approved: data.paid_by === 'landlord' ? false : true };
    if (editing) {
      const approvedStatus = editing.approved && data.paid_by === 'landlord' ? true : saveData.approved;
      await base44.entities.Expense.update(editing.id, { ...saveData, approved: approvedStatus });
      await logAction({ user, action: 'update', entityType: 'Expense', entityId: editing.id, summary: `Updated expense: ${data.description} £${data.amount}`, oldValue: editing, newValue: saveData });
    } else {
      const created = await base44.entities.Expense.create(saveData);
      await logAction({ user, action: 'create', entityType: 'Expense', entityId: created.id, summary: `Added expense: ${data.description} £${data.amount}`, newValue: saveData });
    }
    queryClient.invalidateQueries({ queryKey: ['expenses'] });
    setShowForm(false);
    setEditing(null);
  };

  const handleDelete = async (expense) => {
    await base44.entities.Expense.delete(expense.id);
    await logAction({ user, action: 'delete', entityType: 'Expense', entityId: expense.id, summary: `Deleted expense: ${expense.description}`, oldValue: expense });
    queryClient.invalidateQueries({ queryKey: ['expenses'] });
    setConfirmDelete(null);
  };

  const filtered = expenses.filter(e =>
    e.description?.toLowerCase().includes(search.toLowerCase()) ||
    getProperty(e.property_id)?.address?.toLowerCase().includes(search.toLowerCase())
  );

  const totalAgency = expenses.filter(e => e.paid_by === 'agency').reduce((s, e) => s + (e.amount || 0), 0);
  const totalLandlord = expenses.filter(e => e.paid_by === 'landlord').reduce((s, e) => s + (e.amount || 0), 0);

  const catColors = { maintenance: 'red', repairs: 'red', insurance: 'blue', utilities: 'yellow', management_fee: 'blue', legal: 'yellow', cleaning: 'green', other: 'gray' };

  return (
    <div>
      <PageHeader
        title="Expenses"
        description="Track all property-related expenses"
        actions={
          <div className="flex gap-2">
            <Button variant="outline" size="sm" onClick={() => exportExpenses({ expenses, properties, landlords })}>
              <Download className="w-4 h-4 mr-2" />Export Excel
            </Button>
            <Button onClick={() => { setEditing(null); setShowForm(true); }}>
              <Plus className="w-4 h-4 mr-2" />Add Expense
            </Button>
          </div>
        }
      />

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-6">
        <StatCard label="Total Expenses" value={formatCurrency(totalAgency + totalLandlord)} icon={Receipt} />
        <StatCard label="Agency Expenses" value={formatCurrency(totalAgency)} icon={Receipt} color="destructive" />
        <StatCard label="Landlord Expenses" value={formatCurrency(totalLandlord)} icon={Receipt} color="warning" />
      </div>

      <div className="mb-4 max-w-sm">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input placeholder="Search expenses..." value={search} onChange={e => setSearch(e.target.value)} className="pl-9" />
        </div>
      </div>

      <div className="bg-card rounded-xl border border-border overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-muted/50">
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Date</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Property</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Category</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Description</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Amount</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Paid By</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Status</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Actions</th>
              </tr>
            </thead>
            <tbody>
              {filtered.map(e => (
                <tr key={e.id} className="border-t border-border hover:bg-muted/30 transition-colors">
                  <td className="px-5 py-3 text-muted-foreground">{e.date ? format(parseISO(e.date), 'dd MMM yyyy') : '-'}</td>
                  <td className="px-5 py-3 text-muted-foreground">{getProperty(e.property_id)?.address?.split(',')[0] || '-'}</td>
                  <td className="px-5 py-3"><StatusBadge color={catColors[e.category] || 'gray'}>{e.category?.replace(/_/g, ' ')}</StatusBadge></td>
                  <td className="px-5 py-3">{e.description}</td>
                  <td className="px-5 py-3 font-medium text-red-600">{formatCurrency(e.amount)}</td>
                  <td className="px-5 py-3"><StatusBadge color={e.paid_by === 'agency' ? 'blue' : 'yellow'}>{e.paid_by}</StatusBadge></td>
                  <td className="px-5 py-3">
                    {e.paid_by === 'landlord'
                      ? e.approved
                        ? <StatusBadge color="green">Approved</StatusBadge>
                        : <StatusBadge color="yellow">Pending Approval</StatusBadge>
                      : <StatusBadge color="blue">N/A</StatusBadge>}
                  </td>
                  <td className="px-5 py-3">
                    <div className="flex items-center gap-1">
                      {isAdmin && e.paid_by === 'landlord' && !e.approved && (
                        <Button size="sm" className="bg-emerald-600 hover:bg-emerald-700 text-white text-xs px-2 h-7" onClick={() => handleApprove(e)}>
                          ✓ Approve
                        </Button>
                      )}
                      <Button variant="ghost" size="sm" onClick={() => { setEditing(e); setShowForm(true); }}><Pencil className="w-4 h-4" /></Button>
                      {isAdmin && <Button variant="ghost" size="sm" className="text-destructive hover:text-destructive" onClick={() => setConfirmDelete(e)}><Trash2 className="w-4 h-4" /></Button>}
                    </div>
                  </td>
                </tr>
              ))}
              {filtered.length === 0 && (
                <tr><td colSpan="8" className="px-5 py-8 text-center text-muted-foreground">No expenses found</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      <Dialog open={showForm} onOpenChange={v => { setShowForm(v); if (!v) setEditing(null); }}>
        <DialogContent className="max-w-lg">
          <DialogHeader><DialogTitle>{editing ? 'Edit Expense' : 'Add Expense'}</DialogTitle></DialogHeader>
          <ExpenseForm expense={editing} properties={properties} tenants={tenants} onSubmit={handleSubmit} onCancel={() => { setShowForm(false); setEditing(null); }} />
        </DialogContent>
      </Dialog>

      <ConfirmDialog
        open={!!confirmDelete}
        title="Delete Expense"
        description={`Delete "${confirmDelete?.description}"? This is permanent.`}
        onConfirm={() => handleDelete(confirmDelete)}
        onCancel={() => setConfirmDelete(null)}
      />
    </div>
  );
}

import React, { useState } from "react";
import { Link } from "react-router-dom";
import { base44 } from "@/api/base44Client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Mail, ArrowLeft, Loader2 } from "lucide-react";
import AuthLayout from "@/components/AuthLayout";

export default function ForgotPassword() {
  const [email, setEmail] = useState("");
  const [loading, setLoading] = useState(false);
  const [sent, setSent] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      await base44.auth.resetPasswordRequest(email);
    } catch {
      // Always show success regardless
    } finally {
      setLoading(false);
      setSent(true);
    }
  };

  return (
    <AuthLayout
      icon={Mail}
      title="Reset password"
      subtitle="We'll send you a link to reset it"
      footer={
        <Link to="/login" className="text-primary font-medium hover:underline">
          <ArrowLeft className="w-3 h-3 inline mr-1" />Back to log in
        </Link>
      }
    >
      {sent ? (
        <p className="text-sm text-foreground text-center">
          If an account exists with that email, you'll receive a password reset link shortly.
        </p>
      ) : (
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="email">Email address</Label>
            <div className="relative">
              <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" aria-hidden="true" />
              <Input
                id="email"
                type="email"
                autoComplete="email"
                autoFocus
                placeholder="you@example.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="pl-10 h-12"
                required
              />
            </div>
          </div>
          <Button type="submit" className="w-full h-12 font-medium" disabled={loading}>
            {loading ? (
              <>
                <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                Sending...
              </>
            ) : (
              "Send reset link"
            )}
          </Button>
        </form>
      )}
    </AuthLayout>
  );
}

import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { base44 } from '@/api/base44Client';
import PageHeader from '@/components/ui/PageHeader';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Badge } from '@/components/ui/badge';
import { Plus, Search, Pencil, Trash2, Key } from 'lucide-react';
import { useToast } from '@/components/ui/use-toast';

const STATUS_COLORS = {
  in_office: 'bg-green-100 text-green-800',
  with_tenant: 'bg-blue-100 text-blue-800',
  with_landlord: 'bg-purple-100 text-purple-800',
  missing: 'bg-red-100 text-red-800',
};

const STATUS_LABELS = {
  in_office: 'In Office',
  with_tenant: 'With Tenant',
  with_landlord: 'With Landlord',
  missing: 'Missing',
};

const EMPTY_FORM = { key_number: '', address: '', notes: '', status: 'in_office' };

export default function HouseKeys() {
  const { toast } = useToast();
  const qc = useQueryClient();
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState(EMPTY_FORM);

  const { data: keys = [], isLoading } = useQuery({
    queryKey: ['housekeys'],
    queryFn: () => base44.entities.HouseKey.list('key_number', 500),
  });

  const saveMutation = useMutation({
    mutationFn: (data) => editing
      ? base44.entities.HouseKey.update(editing.id, data)
      : base44.entities.HouseKey.create(data),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['housekeys'] });
      setDialogOpen(false);
      toast({ title: editing ? 'Key updated' : 'Key added', duration: 3000 });
    },
  });

  const deleteMutation = useMutation({
    mutationFn: (id) => base44.entities.HouseKey.delete(id),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['housekeys'] });
      toast({ title: 'Key deleted', duration: 3000 });
    },
    onError: (err) => {
      toast({ title: 'Delete failed', description: err?.message || 'Could not delete key', variant: 'destructive', duration: 4000 });
    },
  });

  const openAdd = () => { setEditing(null); setForm(EMPTY_FORM); setDialogOpen(true); };
  const openEdit = (k) => { setEditing(k); setForm({ key_number: k.key_number ?? '', address: k.address, notes: k.notes ?? '', status: k.status ?? 'in_office' }); setDialogOpen(true); };

  const handleSave = () => {
    const payload = { ...form, key_number: form.key_number !== '' ? Number(form.key_number) : undefined };
    saveMutation.mutate(payload);
  };

  const filtered = keys.filter(k => {
    const matchSearch = !search || k.address?.toLowerCase().includes(search.toLowerCase()) || String(k.key_number).includes(search);
    const matchStatus = statusFilter === 'all' || k.status === statusFilter;
    return matchSearch && matchStatus;
  });

  const counts = keys.reduce((acc, k) => { acc[k.status ?? 'in_office'] = (acc[k.status ?? 'in_office'] || 0) + 1; return acc; }, {});

  return (
    <div className="space-y-6">
      <PageHeader
        title="House Keys"
        description={`${keys.length} keys registered`}
        actions={<Button onClick={openAdd} size="sm"><Plus className="w-4 h-4" /> Add Key</Button>}
      />

      {/* Summary badges */}
      <div className="flex flex-wrap gap-2">
        {Object.entries(STATUS_LABELS).map(([s, label]) => (
          <span key={s} className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-medium ${STATUS_COLORS[s]}`}>
            <Key className="w-3 h-3" /> {label}: {counts[s] ?? 0}
          </span>
        ))}
      </div>

      {/* Filters */}
      <div className="flex flex-col sm:flex-row gap-2">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input placeholder="Search by address or number…" value={search} onChange={e => setSearch(e.target.value)} className="pl-9" />
        </div>
        <Select value={statusFilter} onValueChange={setStatusFilter}>
          <SelectTrigger className="w-full sm:w-44">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Statuses</SelectItem>
            {Object.entries(STATUS_LABELS).map(([s, l]) => <SelectItem key={s} value={s}>{l}</SelectItem>)}
          </SelectContent>
        </Select>
      </div>

      {/* Table */}
      {isLoading ? (
        <div className="text-center py-12 text-muted-foreground">Loading…</div>
      ) : (
        <div className="border border-border rounded-lg overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-muted/50">
                <tr>
                  <th className="text-left px-4 py-3 font-medium text-muted-foreground w-12">#</th>
                  <th className="text-left px-4 py-3 font-medium text-muted-foreground">Address</th>
                  <th className="text-left px-4 py-3 font-medium text-muted-foreground hidden sm:table-cell">Notes</th>
                  <th className="text-left px-4 py-3 font-medium text-muted-foreground">Status</th>
                  <th className="w-20 px-4 py-3"></th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border">
                {filtered.length === 0 && (
                  <tr><td colSpan={5} className="text-center py-10 text-muted-foreground">No keys found.</td></tr>
                )}
                {filtered.map(k => (
                  <tr key={k.id} className="hover:bg-muted/30 transition-colors">
                    <td className="px-4 py-3 text-muted-foreground tabular-nums">{k.key_number ?? '—'}</td>
                    <td className="px-4 py-3 font-medium">{k.address}</td>
                    <td className="px-4 py-3 text-muted-foreground hidden sm:table-cell">{k.notes || '—'}</td>
                    <td className="px-4 py-3">
                      <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${STATUS_COLORS[k.status ?? 'in_office']}`}>
                        {STATUS_LABELS[k.status ?? 'in_office']}
                      </span>
                    </td>
                    <td className="px-4 py-3">
                      <div className="flex items-center gap-1">
                        <button onClick={() => openEdit(k)} className="p-1.5 rounded hover:bg-muted text-muted-foreground hover:text-foreground transition-colors">
                          <Pencil className="w-3.5 h-3.5" />
                        </button>
                        <button onClick={() => deleteMutation.mutate(k.id)} className="p-1.5 rounded hover:bg-destructive/10 text-muted-foreground hover:text-destructive transition-colors">
                          <Trash2 className="w-3.5 h-3.5" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Add/Edit Dialog */}
      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>{editing ? 'Edit Key' : 'Add Key'}</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 pt-2">
            <div>
              <label className="text-sm font-medium mb-1 block">Key Number</label>
              <Input type="number" placeholder="e.g. 42" value={form.key_number} onChange={e => setForm(f => ({ ...f, key_number: e.target.value }))} />
            </div>
            <div>
              <label className="text-sm font-medium mb-1 block">Address *</label>
              <Input placeholder="Full property address" value={form.address} onChange={e => setForm(f => ({ ...f, address: e.target.value }))} />
            </div>
            <div>
              <label className="text-sm font-medium mb-1 block">Notes</label>
              <Input placeholder="e.g. keys with tenant, back door key" value={form.notes} onChange={e => setForm(f => ({ ...f, notes: e.target.value }))} />
            </div>
            <div>
              <label className="text-sm font-medium mb-1 block">Status</label>
              <Select value={form.status} onValueChange={v => setForm(f => ({ ...f, status: v }))}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  {Object.entries(STATUS_LABELS).map(([s, l]) => <SelectItem key={s} value={s}>{l}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div className="flex justify-end gap-2 pt-2">
              <Button variant="outline" onClick={() => setDialogOpen(false)}>Cancel</Button>
              <Button onClick={handleSave} disabled={!form.address || saveMutation.isPending}>
                {saveMutation.isPending ? 'Saving…' : 'Save'}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React, { useMemo, useState } from 'react';
import { base44 } from '@/api/base44Client';
import { useQueryClient } from '@tanstack/react-query';
import { useInquiries } from '@/hooks/useInquiries';
import { useProperties } from '@/hooks/useAllData';
import { useRole } from '@/hooks/useRole';
import { logAction } from '@/lib/audit';
import PageHeader from '@/components/ui/PageHeader';
import StatCard from '@/components/ui/StatCard';
import StatusBadge from '@/components/ui/StatusBadge';
import ConfirmDialog from '@/components/ui/ConfirmDialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Mail, Phone, Search, Trash2, Eye, Inbox, MessageSquare } from 'lucide-react';
import { format, parseISO } from 'date-fns';

const STATUS_COLOR = { new: 'blue', contacted: 'yellow', closed: 'green' };

export default function Inquiries() {
  const { user, isAdmin } = useRole();
  const { data: inquiries } = useInquiries();
  const { data: properties } = useProperties();
  const queryClient = useQueryClient();

  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [selected, setSelected] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(null);

  const propertyAddr = (id) => properties.find(p => p.id === id)?.address?.split(',')[0] || '—';

  const filtered = useMemo(() => inquiries.filter(i => {
    if (filterStatus !== 'all' && i.status !== filterStatus) return false;
    if (search) {
      const q = search.toLowerCase();
      return (i.name || '').toLowerCase().includes(q)
        || (i.email || '').toLowerCase().includes(q)
        || (i.message || '').toLowerCase().includes(q);
    }
    return true;
  }), [inquiries, filterStatus, search]);

  const totals = {
    new: inquiries.filter(i => i.status === 'new').length,
    contacted: inquiries.filter(i => i.status === 'contacted').length,
    closed: inquiries.filter(i => i.status === 'closed').length,
  };

  const updateStatus = async (inq, status) => {
    await base44.entities.Inquiry.update(inq.id, { status });
    await logAction({ user, action: 'update', entityType: 'Inquiry', entityId: inq.id, summary: `Marked enquiry from ${inq.name} as ${status}`, oldValue: inq, newValue: { ...inq, status } });
    queryClient.invalidateQueries({ queryKey: ['inquiries'] });
    if (selected) setSelected({ ...selected, status });
  };

  const saveNotes = async (inq, notes) => {
    await base44.entities.Inquiry.update(inq.id, { notes });
    queryClient.invalidateQueries({ queryKey: ['inquiries'] });
  };

  const handleDelete = async (inq) => {
    await base44.entities.Inquiry.delete(inq.id);
    await logAction({ user, action: 'delete', entityType: 'Inquiry', entityId: inq.id, summary: `Deleted enquiry from ${inq.name}`, oldValue: inq });
    queryClient.invalidateQueries({ queryKey: ['inquiries'] });
    setConfirmDelete(null);
    setSelected(null);
  };

  return (
    <div>
      <PageHeader title="Website Enquiries" description="Messages submitted from the public website" />

      <div className="grid grid-cols-3 gap-4 mb-6">
        <StatCard label="New" value={totals.new} icon={Inbox} color="primary" />
        <StatCard label="Contacted" value={totals.contacted} icon={MessageSquare} color="warning" />
        <StatCard label="Closed" value={totals.closed} icon={Mail} color="success" />
      </div>

      <div className="flex flex-wrap gap-3 mb-5">
        <div className="relative flex-1 min-w-[200px]">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input className="pl-9 h-9" placeholder="Search name, email, message..." value={search} onChange={e => setSearch(e.target.value)} />
        </div>
        <Select value={filterStatus} onValueChange={setFilterStatus}>
          <SelectTrigger className="w-40 h-9"><SelectValue /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All status</SelectItem>
            <SelectItem value="new">New</SelectItem>
            <SelectItem value="contacted">Contacted</SelectItem>
            <SelectItem value="closed">Closed</SelectItem>
          </SelectContent>
        </Select>
      </div>

      <div className="bg-card rounded-xl border border-border overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-muted/50">
                <th className="text-left px-4 py-3 font-medium text-muted-foreground">Date</th>
                <th className="text-left px-4 py-3 font-medium text-muted-foreground">Name</th>
                <th className="text-left px-4 py-3 font-medium text-muted-foreground">Type</th>
                <th className="text-left px-4 py-3 font-medium text-muted-foreground">Property</th>
                <th className="text-left px-4 py-3 font-medium text-muted-foreground">Contact</th>
                <th className="text-left px-4 py-3 font-medium text-muted-foreground">Status</th>
                <th className="px-4 py-3"></th>
              </tr>
            </thead>
            <tbody>
              {filtered.map(inq => (
                <tr key={inq.id} className="border-t border-border hover:bg-muted/30">
                  <td className="px-4 py-3 text-xs text-muted-foreground">
                    {inq.created_date ? format(typeof inq.created_date === 'string' ? parseISO(inq.created_date) : inq.created_date, 'dd MMM yyyy') : '-'}
                  </td>
                  <td className="px-4 py-3 font-medium">{inq.name}</td>
                  <td className="px-4 py-3 text-xs text-muted-foreground capitalize">{inq.inquiry_type}</td>
                  <td className="px-4 py-3 text-xs text-muted-foreground">{inq.property_id ? propertyAddr(inq.property_id) : 'General'}</td>
                  <td className="px-4 py-3 text-xs">
                    <div className="flex flex-col gap-0.5">
                      {inq.email && <a href={`mailto:${inq.email}`} className="hover:text-primary truncate">{inq.email}</a>}
                      {inq.phone && <span className="text-muted-foreground">{inq.phone}</span>}
                    </div>
                  </td>
                  <td className="px-4 py-3"><StatusBadge color={STATUS_COLOR[inq.status]}>{inq.status}</StatusBadge></td>
                  <td className="px-4 py-3">
                    <div className="flex gap-1 justify-end">
                      <Button variant="ghost" size="sm" onClick={() => setSelected(inq)}><Eye className="w-4 h-4" /></Button>
                      {isAdmin && <Button variant="ghost" size="sm" className="text-destructive hover:text-destructive" onClick={() => setConfirmDelete(inq)}><Trash2 className="w-4 h-4" /></Button>}
                    </div>
                  </td>
                </tr>
              ))}
              {filtered.length === 0 && (
                <tr><td colSpan="7" className="px-4 py-10 text-center text-muted-foreground">No enquiries yet</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      <Dialog open={!!selected} onOpenChange={v => { if (!v) setSelected(null); }}>
        {selected && (
          <DialogContent className="max-w-2xl">
            <DialogHeader>
              <DialogTitle className="flex items-center gap-3">
                Enquiry from {selected.name}
                <StatusBadge color={STATUS_COLOR[selected.status]}>{selected.status}</StatusBadge>
              </DialogTitle>
            </DialogHeader>
            <div className="space-y-4 text-sm">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label className="text-xs text-muted-foreground">Email</Label>
                  <a href={`mailto:${selected.email}`} className="block font-medium hover:text-primary"><Mail className="w-3.5 h-3.5 inline mr-1" />{selected.email}</a>
                </div>
                <div>
                  <Label className="text-xs text-muted-foreground">Phone</Label>
                  <div className="font-medium">{selected.phone ? <><Phone className="w-3.5 h-3.5 inline mr-1" />{selected.phone}</> : '—'}</div>
                </div>
                <div>
                  <Label className="text-xs text-muted-foreground">Type</Label>
                  <div className="font-medium capitalize">{selected.inquiry_type}</div>
                </div>
                <div>
                  <Label className="text-xs text-muted-foreground">Property</Label>
                  <div className="font-medium">{selected.property_id ? propertyAddr(selected.property_id) : 'General enquiry'}</div>
                </div>
                {selected.preferred_date && (
                  <div>
                    <Label className="text-xs text-muted-foreground">Preferred date</Label>
                    <div className="font-medium">{format(parseISO(selected.preferred_date), 'dd MMM yyyy')}</div>
                  </div>
                )}
              </div>
              <div>
                <Label className="text-xs text-muted-foreground">Message</Label>
                <div className="bg-muted/40 rounded-lg p-3 mt-1 whitespace-pre-line">{selected.message}</div>
              </div>
              <div>
                <Label className="text-xs text-muted-foreground">Internal notes</Label>
                <Textarea
                  rows={3}
                  defaultValue={selected.notes || ''}
                  onBlur={e => saveNotes(selected, e.target.value)}
                  placeholder="Add notes (auto-saved on blur)"
                />
              </div>
              <div className="flex flex-wrap gap-2 justify-end pt-2 border-t border-border">
                <Button variant="outline" size="sm" onClick={() => updateStatus(selected, 'new')}>Mark New</Button>
                <Button variant="outline" size="sm" onClick={() => updateStatus(selected, 'contacted')}>Mark Contacted</Button>
                <Button variant="outline" size="sm" onClick={() => updateStatus(selected, 'closed')}>Mark Closed</Button>
                <Button onClick={() => setSelected(null)}>Close</Button>
              </div>
            </div>
          </DialogContent>
        )}
      </Dialog>

      <ConfirmDialog
        open={!!confirmDelete}
        title="Delete Enquiry"
        description={`Permanently delete the enquiry from ${confirmDelete?.name}?`}
        onConfirm={() => handleDelete(confirmDelete)}
        onCancel={() => setConfirmDelete(null)}
      />
    </div>
  );
}

import React, { useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import { useQueryClient } from '@tanstack/react-query';
import { base44 } from '@/api/base44Client';
import { useProperties, useTenants, useInspections } from '@/hooks/useAllData';
import PageHeader from '@/components/ui/PageHeader';
import { Button } from '@/components/ui/button';
import { format, parseISO } from 'date-fns';
import {
  MapPin, CalendarClock, CheckCircle2, Plus, Trash2, ClipboardCheck,
  AlertTriangle, ArrowRight, Search, RefreshCw, Phone,
} from 'lucide-react';

/* Outward postcode, e.g. "12 Edgar Rd, London E7 8BD" -> "E7". Groups nearby properties. */
function outwardCode(address) {
  if (!address) return 'Other';
  const m = String(address).toUpperCase().match(/([A-Z]{1,2}\d[A-Z\d]?)\s*\d[A-Z]{2}\b/);
  return m ? m[1] : 'Other';
}

const SEV = {
  low: { label: 'Low', cls: 'bg-slate-100 text-slate-600' },
  medium: { label: 'Medium', cls: 'bg-amber-100 text-amber-700' },
  high: { label: 'High', cls: 'bg-red-100 text-red-700' },
};

function Modal({ title, subtitle, onClose, children }) {
  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 p-4" onClick={onClose}>
      <div className="bg-card border border-border rounded-xl shadow-xl w-full max-w-md max-h-[90vh] overflow-y-auto" onClick={(e) => e.stopPropagation()}>
        <div className="p-5">
          <p className="text-base font-semibold">{title}</p>
          {subtitle && <p className="text-xs text-muted-foreground mt-0.5">{subtitle}</p>}
          <div className="mt-4">{children}</div>
        </div>
      </div>
    </div>
  );
}

export default function Inspections() {
  const queryClient = useQueryClient();
  const { data: properties = [] } = useProperties();
  const { data: tenants = [] } = useTenants();
  const { data: inspections = [] } = useInspections();
  const [search, setSearch] = useState('');
  const [busy, setBusy] = useState(false);

  // appointment modal state
  const [apptFor, setApptFor] = useState(null); // { property, tenant, inspection }
  const [apptDate, setApptDate] = useState('');
  const [apptTime, setApptTime] = useState('10:00');
  const [apptInspector, setApptInspector] = useState('');

  // done modal state
  const [doneFor, setDoneFor] = useState(null);
  const [doneDate, setDoneDate] = useState('');
  const [doneCond, setDoneCond] = useState('good');
  const [doneNotes, setDoneNotes] = useState('');
  const [doneIssues, setDoneIssues] = useState([]);

  const refresh = () => {
    queryClient.invalidateQueries({ queryKey: ['inspections'] });
    queryClient.invalidateQueries({ queryKey: ['properties'] });
    queryClient.invalidateQueries({ queryKey: ['tenants'] });
  };

  const tenantFor = (propertyId) =>
    tenants.find((t) => t.property_id === propertyId && t.status !== 'past' && t.status !== 'former') ||
    tenants.find((t) => t.property_id === propertyId) || null;

  const latestInspection = (propertyId) =>
    inspections
      .filter((i) => i.property_id === propertyId)
      .sort((a, b) => new Date(b.created_date || 0) - new Date(a.created_date || 0))[0] || null;

  // Build grouped rows by postcode
  const groups = useMemo(() => {
    const q = search.trim().toLowerCase();
    const rows = properties
      .map((p) => {
        const tenant = tenantFor(p.id);
        const insp = latestInspection(p.id);
        return { property: p, tenant, inspection: insp, code: outwardCode(p.address) };
      })
      .filter((r) => !q ||
        r.property.address?.toLowerCase().includes(q) ||
        r.tenant?.name?.toLowerCase().includes(q) ||
        r.code.toLowerCase().includes(q));

    const map = {};
    rows.forEach((r) => { (map[r.code] = map[r.code] || []).push(r); });
    return Object.keys(map).sort().map((code) => ({
      code,
      rows: map[code].sort((a, b) => (a.property.address || '').localeCompare(b.property.address || '')),
    }));
  }, [properties, tenants, inspections, search]);

  const totals = useMemo(() => {
    let scheduled = 0, completed = 0, openIssues = 0;
    inspections.forEach((i) => {
      if (i.status === 'scheduled') scheduled++;
      if (i.status === 'completed') completed++;
      (Array.isArray(i.issues) ? i.issues : []).forEach((x) => { if (x.status !== 'resolved') openIssues++; });
    });
    return { scheduled, completed, openIssues };
  }, [inspections]);

  /* ----- appointment ----- */
  const openAppt = (row) => {
    setApptFor(row);
    setApptDate(row.inspection?.appointment_date || format(new Date(), 'yyyy-MM-dd'));
    setApptTime(row.inspection?.appointment_time || '10:00');
    setApptInspector(row.inspection?.inspector_name || '');
  };
  const saveAppt = async () => {
    if (!apptDate) { alert('Please choose a date.'); return; }
    setBusy(true);
    try {
      const { property, tenant, inspection } = apptFor;
      const payload = {
        property_id: property.id,
        tenant_id: tenant?.id || '',
        tenant_name: tenant?.name || '',
        status: 'scheduled',
        appointment_date: apptDate,
        appointment_time: apptTime,
        inspector_name: apptInspector,
      };
      if (inspection && inspection.status === 'scheduled') {
        await base44.entities.Inspection.update(inspection.id, payload);
      } else {
        await base44.entities.Inspection.create(payload);
      }
      setApptFor(null);
      refresh();
    } catch (e) { alert(`Could not save: ${e.message || e}`); }
    finally { setBusy(false); }
  };

  /* ----- mark done ----- */
  const openDone = (row) => {
    setDoneFor(row);
    setDoneDate(row.inspection?.completed_date || format(new Date(), 'yyyy-MM-dd'));
    setDoneCond(row.inspection?.overall_condition || 'good');
    setDoneNotes(row.inspection?.notes || '');
    setDoneIssues(Array.isArray(row.inspection?.issues) ? row.inspection.issues : []);
  };
  const addIssue = () => setDoneIssues((p) => [...p, { description: '', severity: 'low', status: 'open' }]);
  const updIssue = (i, k, v) => setDoneIssues((p) => p.map((x, idx) => idx === i ? { ...x, [k]: v } : x));
  const rmIssue = (i) => setDoneIssues((p) => p.filter((_, idx) => idx !== i));
  const saveDone = async () => {
    if (!doneDate) { alert('Please set the inspection date.'); return; }
    setBusy(true);
    try {
      const { property, tenant, inspection } = doneFor;
      const cleanIssues = doneIssues.filter((x) => x.description && x.description.trim());
      const payload = {
        property_id: property.id,
        tenant_id: tenant?.id || '',
        tenant_name: tenant?.name || '',
        status: 'completed',
        completed_date: doneDate,
        overall_condition: doneCond,
        notes: doneNotes,
        issues: cleanIssues,
      };
      if (inspection) await base44.entities.Inspection.update(inspection.id, payload);
      else await base44.entities.Inspection.create(payload);
      setDoneFor(null);
      refresh();
    } catch (e) { alert(`Could not save: ${e.message || e}`); }
    finally { setBusy(false); }
  };

  const StatusPill = ({ insp }) => {
    if (!insp) return <span className="px-2.5 py-1 rounded-md bg-slate-100 text-slate-500 text-xs font-semibold">Not scheduled</span>;
    if (insp.status === 'completed') {
      const open = (insp.issues || []).filter((x) => x.status !== 'resolved').length;
      return (
        <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-md bg-emerald-100 text-emerald-700 text-xs font-semibold">
          <CheckCircle2 className="w-3.5 h-3.5" /> Done{open > 0 ? ` · ${open} issue${open > 1 ? 's' : ''}` : ''}
        </span>
      );
    }
    return (
      <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-md bg-blue-100 text-blue-700 text-xs font-semibold">
        <CalendarClock className="w-3.5 h-3.5" /> {insp.appointment_date ? format(parseISO(insp.appointment_date), 'dd MMM') : 'Scheduled'}{insp.appointment_time ? ` · ${insp.appointment_time}` : ''}
      </span>
    );
  };

  return (
    <div>
      <PageHeader
        title="Inspections"
        description="Schedule and record property inspections. Properties are grouped by postcode so you can plan nearby visits together."
        actions={<Button variant="outline" size="sm" onClick={refresh}><RefreshCw className="w-4 h-4 mr-1" /> Refresh</Button>}
      />

      {/* summary */}
      <div className="grid grid-cols-3 gap-3 mb-6 max-w-xl">
        {[['Scheduled', totals.scheduled, 'text-blue-700'], ['Completed', totals.completed, 'text-emerald-700'], ['Open issues', totals.openIssues, 'text-red-700']].map(([l, v, c]) => (
          <div key={l} className="bg-card border border-border rounded-xl p-4">
            <div className={`text-2xl font-bold ${c}`}>{v}</div>
            <div className="text-xs text-muted-foreground mt-0.5">{l}</div>
          </div>
        ))}
      </div>

      {/* search */}
      <div className="relative mb-6 max-w-xl">
        <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
        <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search address, tenant or postcode…"
          className="w-full pl-9 pr-3 py-2.5 text-sm border border-input rounded-lg bg-background focus:outline-none focus:ring-2 focus:ring-primary" />
      </div>

      {groups.length === 0 && <p className="text-sm text-muted-foreground">No properties found.</p>}

      <div className="space-y-8">
        {groups.map((g) => (
          <div key={g.code}>
            <div className="flex items-center gap-2 mb-3">
              <MapPin className="w-4 h-4 text-primary" />
              <h2 className="text-sm font-bold uppercase tracking-wide text-foreground">{g.code}</h2>
              <span className="text-xs text-muted-foreground">· {g.rows.length} propert{g.rows.length > 1 ? 'ies' : 'y'}</span>
              <span className="flex-1 h-px bg-border ml-2" />
            </div>

            <div className="bg-card border border-border rounded-xl overflow-hidden">
              <table className="w-full text-sm">
                <tbody>
                  {g.rows.map((r, i) => (
                    <tr key={r.property.id} className={i > 0 ? 'border-t border-border' : ''}>
                      <td className="px-4 py-3">
                        <div className="font-medium">{r.property.address}</div>
                        <div className="text-xs text-muted-foreground flex flex-wrap items-center gap-x-2">
                          <span>{r.tenant ? r.tenant.name : 'No active tenant'}</span>
                          {r.tenant?.phone && (
                            <a href={`tel:${r.tenant.phone}`} onClick={(e) => e.stopPropagation()}
                              className="inline-flex items-center gap-1 text-primary hover:underline">
                              <Phone className="w-3 h-3" /> {r.tenant.phone}
                            </a>
                          )}
                        </div>
                      </td>
                      <td className="px-4 py-3"><StatusPill insp={r.inspection} /></td>
                      <td className="px-4 py-3 text-right whitespace-nowrap">
                        <div className="inline-flex items-center gap-2">
                          <Button size="sm" variant="outline" onClick={() => openAppt(r)}>
                            <CalendarClock className="w-3.5 h-3.5 mr-1" /> {r.inspection?.status === 'scheduled' ? 'Reschedule' : 'Make appointment'}
                          </Button>
                          <Button size="sm" onClick={() => openDone(r)} className="bg-emerald-600 hover:bg-emerald-700">
                            <ClipboardCheck className="w-3.5 h-3.5 mr-1" /> {r.inspection?.status === 'completed' ? 'Edit report' : 'Mark done'}
                          </Button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        ))}
      </div>

      {/* appointment modal */}
      {apptFor && (
        <Modal title="Make appointment" subtitle={`${apptFor.property.address}${apptFor.tenant ? ` · ${apptFor.tenant.name}` : ''}${apptFor.tenant?.phone ? ` · ${apptFor.tenant.phone}` : ''}`} onClose={() => setApptFor(null)}>
          <label className="block text-xs font-medium text-muted-foreground mb-1">Date</label>
          <input type="date" value={apptDate} onChange={(e) => setApptDate(e.target.value)} className="w-full text-sm border border-input rounded-md px-3 py-2 mb-3" />
          <label className="block text-xs font-medium text-muted-foreground mb-1">Time</label>
          <input type="time" value={apptTime} onChange={(e) => setApptTime(e.target.value)} className="w-full text-sm border border-input rounded-md px-3 py-2 mb-3" />
          <label className="block text-xs font-medium text-muted-foreground mb-1">Inspector (optional)</label>
          <input type="text" value={apptInspector} onChange={(e) => setApptInspector(e.target.value)} placeholder="Who's attending" className="w-full text-sm border border-input rounded-md px-3 py-2 mb-4" />
          <div className="flex gap-2">
            <button onClick={saveAppt} disabled={busy} className="flex-1 px-3 py-2 rounded-md bg-primary text-primary-foreground text-sm font-semibold disabled:opacity-50">{busy ? 'Saving…' : 'Save appointment'}</button>
            <button onClick={() => setApptFor(null)} className="flex-1 px-3 py-2 rounded-md bg-muted text-muted-foreground text-sm">Cancel</button>
          </div>
        </Modal>
      )}

      {/* done modal */}
      {doneFor && (
        <Modal title="Inspection report" subtitle={`${doneFor.property.address}${doneFor.tenant ? ` · ${doneFor.tenant.name}` : ''}${doneFor.tenant?.phone ? ` · ${doneFor.tenant.phone}` : ''}`} onClose={() => setDoneFor(null)}>
          <div className="grid grid-cols-2 gap-3 mb-3">
            <div>
              <label className="block text-xs font-medium text-muted-foreground mb-1">Date inspected</label>
              <input type="date" value={doneDate} onChange={(e) => setDoneDate(e.target.value)} className="w-full text-sm border border-input rounded-md px-3 py-2" />
            </div>
            <div>
              <label className="block text-xs font-medium text-muted-foreground mb-1">Overall condition</label>
