                <select value={iss.severity} onChange={(e) => updIssue(i, 'severity', e.target.value)} className="text-xs border border-input rounded-md px-2 py-1.5 bg-background">
                  <option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option>
                </select>
