// Small guard so one section can't blank the whole page.
class SectionBoundary extends React.Component {
  constructor(p) { super(p); this.state = { err: null }; }
  static getDerivedStateFromError(err) { return { err }; }
  render() {
    if (this.state.err) {
      return <p className="text-sm text-destructive">Couldn't load this section: {String(this.state.err?.message || this.state.err)}</p>;
