// A co-owned row stores its per-month data under a landlord-qualified key so each
// owner's amount / paid status / bank / notes are independent. Single-landlord
// rows use the plain month (unchanged → existing data is preserved exactly).
const SEP = '::';
// Popover shown when clicking a property address on the schedule: lists each
// tenant living there in the selected month and whether their rent was received.
function TenantRentStatus({ property, month, tenants, rentPayments, children }) {
  const [yr, mo] = month.split('-').map(Number);
  const mStart = `${month}-01`;
  const mEnd = format(new Date(yr, mo, 0), 'yyyy-MM-dd');

  // Tenants active in this month at this property.
  const propTenants = (tenants || []).filter(t =>
    t.property_id === property.id && t.lease_start && t.lease_start <= mEnd &&
    (!t.lease_end || t.lease_end >= mStart)
  );

  const rows = propTenants.map(t => {
    const freq = getPropertyFrequency(property, tenants)?.frequency || 'monthly';
    const due = forPeriod(Number(t.monthly_rent || property.monthly_rent || 0), freq);
    const paid = (rentPayments || [])
      .filter(p => {
        if (p.tenant_id !== t.id) return false;
        const period = p.period_month || (p.payment_date ? p.payment_date.substring(0, 7) : null);
        return period === month;
      })
      .reduce((s, p) => s + Number(p.amount || 0), 0);
    let status = 'unpaid';
    if (paid <= 0) status = 'unpaid';
    else if (paid >= due) status = 'paid';
    else status = 'partial';
    return { id: t.id, name: t.name, due, paid, status };
  });

  return (
    <Popover>
      <PopoverTrigger asChild>
        <button type="button" className="text-left hover:underline decoration-dotted underline-offset-2 cursor-pointer">
          {children}
        </button>
      </PopoverTrigger>
      <PopoverContent className="w-72 p-0" align="start">
        <div className="px-3 py-2 border-b border-border bg-muted/40">
          <p className="text-xs font-semibold">Rent received — {format(parseISO(mStart), 'MMM yyyy')}</p>
          <p className="text-[11px] text-muted-foreground truncate">{property.address}</p>
        </div>
        <div className="max-h-64 overflow-y-auto divide-y divide-border">
          {rows.length === 0 && <p className="px-3 py-3 text-xs text-muted-foreground">No active tenant this month.</p>}
          {rows.map(r => (
            <div key={r.id} className="px-3 py-2 flex items-center justify-between gap-2">
              <div className="min-w-0">
                <p className="text-xs font-medium truncate">{r.name}</p>
                <p className="text-[11px] text-muted-foreground">{formatCurrency(r.paid)} of {formatCurrency(r.due)}</p>
              </div>
              {r.status === 'paid' && <span className="inline-flex items-center gap-1 text-[11px] font-semibold text-emerald-600"><CheckCircle className="w-3.5 h-3.5" />Paid</span>}
              {r.status === 'partial' && <span className="inline-flex items-center gap-1 text-[11px] font-semibold text-amber-600"><AlertCircle className="w-3.5 h-3.5" />Partial</span>}
              {r.status === 'unpaid' && <span className="inline-flex items-center gap-1 text-[11px] font-semibold text-red-600"><XCircle className="w-3.5 h-3.5" />Not paid</span>}
            </div>
          ))}
        </div>
      </PopoverContent>
    </Popover>
  );
}

function monthKeyFor(month, landlordId, coOwned) {
  return coOwned && landlordId ? `${month}${SEP}${landlordId}` : month;
}

// Tag retained for backward cleanup of any cash entries created by an earlier build.
function cashTag(propertyId, month, landlordId) {
  return `__from_schedule_cash__${SEP}${month}${SEP}${landlordId}`;
}

// Sync a LandlordPayout record when marking paid from the schedule page.
// Tagged with notes='__from_schedule__' so we can find & update it next time.
// The ledger derives cash vs bank from LandlordPayout.method, so setting
// method:'cash' is all that's needed to record it against cash (no extra entry).
async function syncLandlordPayout(property, month, amount, bankName, paidDateStr, landlordId, method, paidBy) {
  let paymentDate = `${month}-01`;
  if (paidDateStr && /^\d{2}\/\d{2}\/\d{4}$/.test(paidDateStr)) {
    const [dd, mm, yyyy] = paidDateStr.split('/');
    paymentDate = `${yyyy}-${mm}-${dd}`;
  }
  const targetLandlord = landlordId || property.landlord_id;
  const isCash = method === 'cash';

  const all = await base44.entities.LandlordPayout.filter({
    property_id: property.id,
    period_month: month,
    notes: '__from_schedule__',
  });
  const existing = (all || []).filter((p) => p.landlord_id === targetLandlord);

  const payload = {
    landlord_id: targetLandlord,
    property_id: property.id,
    amount: amount || 0,
    payment_date: paymentDate,
    period_month: month,
    method: isCash ? 'cash' : 'bank transfer',
    paid_from_bank_name: isCash ? '' : (bankName || ''),
    reference: isCash ? (paidBy || '') : '',
    notes: '__from_schedule__',
  };

  if (existing.length > 0) {
    await base44.entities.LandlordPayout.update(existing[0].id, payload);
  } else {
    await base44.entities.LandlordPayout.create(payload);
  }

  // Clean up any stray CashEntry an earlier version may have created (avoids double count).
  const tag = cashTag(property.id, month, targetLandlord);
  const stray = await base44.entities.CashEntry.filter({ property_id: property.id, notes: tag });
  await Promise.all((stray || []).map((c) => base44.entities.CashEntry.delete(c.id)));
}

async function deleteSchedulePayout(propertyId, month, landlordId) {
  const existing = await base44.entities.LandlordPayout.filter({
    property_id: propertyId,
    period_month: month,
    notes: '__from_schedule__',
  });
  await Promise.all((existing || [])
    .filter((p) => !landlordId || p.landlord_id === landlordId)
    .map((p) => base44.entities.LandlordPayout.delete(p.id)));
  if (landlordId) {
    const tag = cashTag(propertyId, month, landlordId);
    const cash = await base44.entities.CashEntry.filter({ property_id: propertyId, notes: tag });
    await Promise.all((cash || []).map((c) => base44.entities.CashEntry.delete(c.id)));
  }
}

function ordinal(n) {
  if (n >= 11 && n <= 13) return `${n}th`;
  const last = n % 10;
  if (last === 1) return `${n}st`;
  if (last === 2) return `${n}nd`;
  if (last === 3) return `${n}rd`;
  return `${n}th`;
}

// Resolve the amount that applies for a given month from effective-dated history.
// Returns the amount of the latest entry whose `from` is <= the month.
function resolveAmount(history, month) {
  if (!Array.isArray(history) || history.length === 0) return null;
  const applicable = history
    .filter((h) => h && h.from && h.from <= month)
    .sort((a, b) => b.from.localeCompare(a.from));
  return applicable.length > 0 ? applicable[0].amount : null;
}

// ─── Effective-dated amount cell ─────────────────────────────────────────────
// Editing on a given month applies from THAT month forward. Earlier months keep
// whatever they had (their own earlier history entry).
function AmountCell({ property, month, onSaved, locked, landlordId, coOwned, defaultAmount, frequency }) {
  const cycleMul = cycleMonths(frequency); // 3 for quarterly, 1 for monthly
  // Co-owned → per-landlord history in landlord_amount_history_shared; else the plain field.
  const readHistory = () => {
    if (coOwned) {
      return (Array.isArray(property.landlord_amount_history_shared) ? property.landlord_amount_history_shared : [])
        .filter((h) => h && h.landlord_id === landlordId)
        .map((h) => ({ from: h.from, amount: h.amount }));
    }
    return Array.isArray(property.landlord_amount_history) ? property.landlord_amount_history : [];
  };
  const history = readHistory();
  // History stores the PER-MONTH amount; for quarterly the display is 3× that.
  const resolved = resolveAmount(history, month);
  const effective = resolved != null ? forPeriod(resolved, frequency) : (defaultAmount != null ? defaultAmount : null);
  const [value, setValue] = useState(effective == null ? '' : String(effective));
  const [saving, setSaving] = useState(false);
  const [justSaved, setJustSaved] = useState(false);

  useEffect(() => {
    const h = readHistory();
    const r = resolveAmount(h, month);
    const eff = r != null ? forPeriod(r, frequency) : (defaultAmount != null ? defaultAmount : null);
    setValue(eff == null ? '' : String(eff));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [property.landlord_amount_history, property.landlord_amount_history_shared, month, landlordId, defaultAmount, frequency]);

  const dirty = value !== (effective == null ? '' : String(effective));

  const handleSave = async () => {
    if (!dirty || !month) return;
    if (value === '') return;
    const amount = parseFloat(value);
    if (Number.isNaN(amount) || amount < 0) { setValue(effective == null ? '' : String(effective)); return; }
    // Store the per-month amount (divide by the cycle length for quarterly).
    const storeAmount = Math.round((amount / cycleMul) * 100) / 100;
    const monthLabel = format(parseISO(`${month}-01`), 'MMMM yyyy');
    const periodWord = frequency === 'quarterly' ? 'quarter' : 'month';
    if (!window.confirm(
      `Set the amount to pay to £${amount.toFixed(2)} per ${periodWord} from ${monthLabel} onward?\n\n` +
      `Earlier months keep their current amount. Later months follow this new amount until you change it again.`
    )) {
      setValue(effective == null ? '' : String(effective));
      return;
    }
    setSaving(true);
    try {
      if (coOwned) {
        const all = Array.isArray(property.landlord_amount_history_shared) ? property.landlord_amount_history_shared : [];
        const next = [
          ...all.filter((h) => !(h && h.landlord_id === landlordId && h.from === month)),
          { landlord_id: landlordId, from: month, amount: storeAmount },
        ].sort((a, b) => (a.from || '').localeCompare(b.from || ''));
        await base44.entities.Property.update(property.id, { landlord_amount_history_shared: next });
      } else {
        const next = [
          ...history.filter((h) => h && h.from !== month),
          { from: month, amount: storeAmount },
        ].sort((a, b) => a.from.localeCompare(b.from));
        await base44.entities.Property.update(property.id, { landlord_amount_history: next });
      }
      setJustSaved(true);
      setTimeout(() => setJustSaved(false), 1200);
      onSaved && onSaved();
    } catch (e) {
      alert(`Could not save: ${e.message || e}`);
      setValue(effective == null ? '' : String(effective));
    } finally { setSaving(false); }
  };

  const handleKey = (e) => {
    if (e.key === 'Enter') { e.preventDefault(); handleSave(); e.target.blur(); }
    else if (e.key === 'Escape') setValue(effective == null ? '' : String(effective));
  };

  return (
    <div className="flex items-center justify-end gap-2">
      <div className="relative">
        <span className="absolute left-2 top-1/2 -translate-y-1/2 text-xs text-muted-foreground">£</span>
        <input
          type="number" step="0.01" value={value}
          onChange={(e) => setValue(e.target.value)}
          onBlur={handleSave} onKeyDown={handleKey}
          placeholder="0.00" disabled={saving || locked}
          className={`w-28 pl-5 pr-2 py-1.5 text-sm text-right font-semibold border rounded-md focus:outline-none focus:ring-2 focus:ring-primary disabled:opacity-50 ${locked ? 'bg-muted border-muted cursor-not-allowed' : 'border-input'}`}
        />
      </div>
      {justSaved && <CheckCircle className="w-4 h-4 text-emerald-600" />}
    </div>
  );
}

// Resolve the most recent note field value for a given month (carry-forward logic)
function resolveNoteField(monthlyNotes, month, field) {
  const arr = Array.isArray(monthlyNotes) ? monthlyNotes : [];
  // exact match first
  const exact = arr.find((e) => e && e.month === month);
  if (exact && exact[field]) return exact[field];
  // Qualified (co-owned) keys must NOT carry-forward — it would leak across owners.
  if (String(month).includes(SEP)) return '';
  // From August 2026 onward, bank values are NOT carried forward from previous months.
  if (field === 'bank' && month >= BANK_DROPDOWN_FROM) return '';
  // fall back to latest entry whose month is before the current month
  const past = arr
    .filter((e) => e && e.month < month && e[field])
    .sort((a, b) => b.month.localeCompare(a.month));
  return past.length > 0 ? past[0][field] : '';
}

// Month from which the bank dropdown is shown (free-text input kept for earlier months)
const BANK_DROPDOWN_FROM = '2026-08';

// Generic editable cell for bank name — saves to Property.monthly_notes
// Uses a dropdown select (populated from Bank records) from August 2026 onward;
// earlier months keep the free-text input to preserve existing entries.
function BankCell({ property, month, monthKey, onSaved, banks = [], fallbackBank = '' }) {
  const key = monthKey || month;
  const stored = resolveNoteField(property.monthly_notes, key, 'bank');
  // The actual bank a payment was made from (via a payout) is authoritative — it
  // overrides any stale value typed on the schedule (e.g. "metro" when the money
  // actually left Santander).
  const effective = fallbackBank || stored;
  const [value, setValue] = useState(effective);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    const s = resolveNoteField(property.monthly_notes, key, 'bank');
    setValue(fallbackBank || s);
  }, [property.monthly_notes, key, fallbackBank]);

  // If a payout bank exists and differs from what's stored, persist it once so
  // the schedule's own field matches the real payment bank going forward.
  useEffect(() => {
    if (fallbackBank && fallbackBank !== stored) {
      (async () => {
        try {
          const next = Array.isArray(property.monthly_notes) ? [...property.monthly_notes] : [];
          const idx = next.findIndex((e) => e && e.month === key);
          if (idx >= 0) next[idx] = { ...next[idx], bank: fallbackBank };
          else next.push({ month: key, bank: fallbackBank });
          await base44.entities.Property.update(property.id, { monthly_notes: next });
          onSaved && onSaved();
        } catch { /* non-fatal; display already shows payout bank */ }
      })();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fallbackBank, stored, key]);

  const dirty = value !== effective;

  const handleSave = async (newVal) => {
    const saveVal = newVal !== undefined ? newVal : value;
    if (saveVal === effective || !key) return;
    setSaving(true);
    try {
      const next = Array.isArray(property.monthly_notes) ? [...property.monthly_notes] : [];
      const idx = next.findIndex((e) => e && e.month === key);
      if (idx >= 0) next[idx] = { ...next[idx], bank: saveVal };
      else next.push({ month: key, bank: saveVal });
      await base44.entities.Property.update(property.id, { monthly_notes: next });
      onSaved && onSaved();
    } catch (e) {
      alert(`Could not save: ${e.message || e}`);
      setValue(effective);
    } finally { setSaving(false); }
  };

  const handleKey = (e) => {
    if (e.key === 'Enter') { e.preventDefault(); handleSave(); e.target.blur(); }
    else if (e.key === 'Escape') setValue(effective);
  };

  // Free-text input for months before August 2026
  if (month < BANK_DROPDOWN_FROM) {
    return (
      <input
        type="text"
        value={value}
        onChange={(e) => setValue(e.target.value)}
        onBlur={handleSave}
        onKeyDown={handleKey}
        placeholder="Bank name…"
        disabled={saving}
        className="w-32 px-2 py-1.5 text-sm border border-input rounded-md focus:outline-none focus:ring-2 focus:ring-primary disabled:opacity-50"
      />
    );
  }

  // Dropdown select for August 2026 onward
  const handleChange = (newVal) => {
    setValue(newVal);
    handleSave(newVal);
  };

  return (
    <div className="flex flex-col gap-0.5">
      <select
        value={value}
        onChange={(e) => handleChange(e.target.value)}
        disabled={saving}
        className="w-36 px-2 py-1.5 text-sm border border-input rounded-md bg-background focus:outline-none focus:ring-2 focus:ring-primary disabled:opacity-50"
      >
        <option value="">— Select bank —</option>
        {banks.map((b) => <option key={b.id} value={b.name}>{b.name}</option>)}
        {/* Preserve a stored value that doesn't match any Bank record */}
        {value && !banks.some((b) => b.name === value) && (
          <option value={value}>{value}</option>
        )}
      </select>
      {!value && !fallbackBank && (
        <span className="text-[10px] text-transparent pl-1">·</span>
      )}
    </div>
  );
}

