// MarkPaidButton — opens a date picker popup, saves date permanently.
// The Property.landlord_paid_months schema is an array of STRINGS, so each entry
// is encoded as 'YYYY-MM|dd/MM/yyyy' (month, pipe, frozen paid date).
// Legacy plain 'YYYY-MM' strings (no date) are read gracefully.
// Parse a stored 'dd/MM/yyyy' string into a local Date (noon, to avoid any TZ edge).
// Returns null for missing/legacy/invalid values.
function parsePaidDate(str) {
  if (!str || typeof str !== 'string') return null;
  const m = str.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (!m) return null;
  const [, dd, mm, yyyy] = m;
  return new Date(Number(yyyy), Number(mm) - 1, Number(dd), 12, 0, 0);
}

// Freeze a Date into a 'dd/MM/yyyy' string from its LOCAL parts.
// Built from getDate/getMonth/getFullYear so it can never shift across a TZ boundary.
function freezeDate(date) {
  const dd = String(date.getDate()).padStart(2, '0');
  const mm = String(date.getMonth() + 1).padStart(2, '0');
  const yyyy = date.getFullYear();
  return `${dd}/${mm}/${yyyy}`;
}

// Normalise any stored entry into { month, paid_date }.
// Handles: new 'YYYY-MM|dd/MM/yyyy' strings, legacy 'YYYY-MM' strings,
// and any stray legacy object { month, paid_date }.
function parsePaidEntry(e) {
  if (typeof e === 'string') {
    const [m, d, n] = e.split('|');
    return { month: m, paid_date: d || null, paid_by: n || null };
  }
  if (e && typeof e === 'object') return { month: e.month || null, paid_date: e.paid_date || null };
  return { month: null, paid_date: null };
}

// Encode month + frozen date back into the schema's string form.
function encodePaidEntry(month, dateStr, name) {
  return dateStr ? `${month}|${dateStr}${name ? '|' + name : ''}` : month;
}

function MarkPaidButton({ row, month, onSaved, autoPaid }) {
  const [saving, setSaving] = useState(false);
  const [showPicker, setShowPicker] = useState(false);
  const [payMethod, setPayMethod] = useState(row.paidMethod || 'bank'); // 'bank' | 'cash'
  const [cashName, setCashName] = useState('');
  const popoverRef = useRef(null);
  useEffect(() => { setPayMethod(row.paidMethod || 'bank'); }, [row.paidMethod]);

  const coOwned = !!row.coOwned;
  const landlordId = row.landlordId || row.property.landlord_id;
  const key = monthKeyFor(month, landlordId, coOwned);   // paid-tracking key (qualified for co-owned)

  const rawPaidMonths = Array.isArray(row.property.landlord_paid_months) ? row.property.landlord_paid_months : [];
  const paidEntry = rawPaidMonths.find((e) => parsePaidEntry(e).month === key);
  const isPaid = !!paidEntry;
  const paidDate = isPaid ? parsePaidEntry(paidEntry).paid_date : null;

  const [selectedDate, setSelectedDate] = useState(() => parsePaidDate(paidDate) || new Date());
  const [pickedDate, setPickedDate] = useState(() => format(parsePaidDate(paidDate) || new Date(), 'yyyy-MM-dd'));
  useEffect(() => {
    setSelectedDate(parsePaidDate(paidDate) || new Date());
  }, [paidDate]);

  const openPicker = () => {
    setPickedDate(format(parsePaidDate(paidDate) || new Date(), 'yyyy-MM-dd'));
    setCashName(paidEntry ? (parsePaidEntry(paidEntry).paid_by || '') : '');
    setShowPicker(true);
  };

  useEffect(() => {
    if (!showPicker) return;
    const handler = (e) => {
      if (popoverRef.current && !popoverRef.current.contains(e.target)) {
        setShowPicker(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [showPicker]);

  const markPaid = async (date) => {
    if (!month) return;
    // Require all the info before marking paid.
    const bankName = resolveNoteField(row.property.monthly_notes, key, 'bank');
    const paidHistory = Array.isArray(row.property.landlord_paid_history) ? row.property.landlord_paid_history : [];
    const paidEntry2 = paidHistory.find((h) => h && h.month === key);
    const enteredAmount = paidEntry2 ? Number(paidEntry2.amount) : null;
    if (enteredAmount == null || Number.isNaN(enteredAmount) || enteredAmount <= 0) {
      setShowPicker(false);
      alert('Please enter the Paid (£) amount for this row before marking as paid.');
      return;
    }
    if (payMethod === 'bank' && !String(bankName || '').trim()) {
      setShowPicker(false);
      alert('Please enter the Bank for this row before marking as paid (or choose Cash).');
      return;
    }
    if (payMethod === 'cash' && !cashName.trim()) {
      setShowPicker(false);
      alert('Please enter who the cash was paid to.');
      return;
    }
    setSaving(true);
    setShowPicker(false);
    try {
      const dateStr = freezeDate(date);
      const next = [
        ...rawPaidMonths.filter((e) => parsePaidEntry(e).month !== key),
        encodePaidEntry(key, dateStr, payMethod === 'cash' ? cashName.trim() : null),
      ];
      await base44.entities.Property.update(row.property.id, { landlord_paid_months: next });
      // Sync LandlordPayout (real month for period; tagged to THIS landlord)
      await syncLandlordPayout(row.property, month, enteredAmount, bankName, dateStr, landlordId, payMethod, payMethod === 'cash' ? cashName.trim() : '');
      onSaved && onSaved();
    } catch (e) { alert(`Could not save: ${e.message || e}`); }
    finally { setSaving(false); }
  };

  const unmarkPaid = async () => {
    if (!month) return;
    if (!window.confirm('Mark this landlord as NOT paid for this month? This clears the paid date.')) return;
    setSaving(true);
    try {
      const next = rawPaidMonths.filter((e) => parsePaidEntry(e).month !== key);
      await base44.entities.Property.update(row.property.id, { landlord_paid_months: next });
      await deleteSchedulePayout(row.property.id, month, landlordId);
      onSaved && onSaved();
    } catch (e) { alert(`Could not save: ${e.message || e}`); }
    finally { setSaving(false); }
  };

  // Centered modal (matches the Tenant Rent Dates "Record rent received" dialog)
  const pickerPopup = showPicker && (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 p-4" onClick={() => setShowPicker(false)}>
      <div className="bg-card border border-border rounded-xl shadow-xl p-5 w-full max-w-xs" onClick={(e) => e.stopPropagation()}>
        <p className="text-sm font-semibold mb-1">{isPaid ? 'Change payment' : 'Record payment'}</p>
        <p className="text-xs text-muted-foreground mb-3">{row.landlord?.name}{row.property?.address ? ` · ${row.property.address}` : ''}</p>
        <label className="block text-xs font-medium text-muted-foreground mb-1">Method</label>
        <div className="flex gap-1 p-0.5 bg-muted rounded-lg mb-3">
          <button onClick={() => setPayMethod('bank')}
            className={`flex-1 text-sm font-semibold py-2 rounded-md transition-colors ${payMethod === 'bank' ? 'bg-white shadow text-foreground' : 'text-muted-foreground'}`}>
            Bank transfer
          </button>
          <button onClick={() => setPayMethod('cash')}
            className={`flex-1 text-sm font-semibold py-2 rounded-md transition-colors ${payMethod === 'cash' ? 'bg-white shadow text-emerald-700' : 'text-muted-foreground'}`}>
            Cash
          </button>
        </div>
        {payMethod === 'cash' && <p className="text-[11px] text-emerald-700 bg-emerald-50 rounded px-2 py-1.5 mb-3">Records a matching entry in the cash ledger.</p>}
        {payMethod === 'cash' && (
          <div className="mb-3">
            <label className="block text-xs font-medium text-muted-foreground mb-1">Cash paid to (name) *</label>
            <input type="text" value={cashName} onChange={(e) => setCashName(e.target.value)}
              placeholder="Who was the cash handed to?" autoFocus
              className="w-full text-sm border border-input rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-primary" />
          </div>
        )}
        <label className="block text-xs font-medium text-muted-foreground mb-1">Payment date</label>
        <input
          type="date"
          value={pickedDate}
          onChange={(e) => setPickedDate(e.target.value)}
          className="w-full text-sm border border-input rounded-md px-3 py-2 mb-4 focus:outline-none focus:ring-2 focus:ring-primary"
        />
        <div className="flex gap-2">
          <button onClick={() => pickedDate && markPaid(new Date(pickedDate + 'T00:00:00'))} disabled={saving || !pickedDate || (payMethod === 'cash' && !cashName.trim())}
            className="flex-1 px-3 py-2 rounded-md bg-emerald-600 text-white text-sm font-semibold hover:bg-emerald-700 disabled:opacity-50">
            {saving ? 'Saving…' : 'Save'}
          </button>
          <button onClick={() => setShowPicker(false)}
            className="flex-1 px-3 py-2 rounded-md bg-muted text-muted-foreground text-sm hover:bg-muted/80">
            Cancel
          </button>
        </div>
      </div>
    </div>
  );

  if (isPaid || autoPaid) {
    const auto = !isPaid && autoPaid;
    return (
      <div className="relative inline-flex items-center gap-1.5 flex-wrap" ref={popoverRef}>
        <button onClick={auto ? undefined : unmarkPaid} disabled={saving || auto}
          className={`inline-flex items-center gap-1 px-2.5 py-1.5 rounded-md text-xs font-semibold disabled:opacity-100 ${auto ? 'bg-emerald-50 text-emerald-700 cursor-default' : 'bg-emerald-100 text-emerald-700 hover:bg-emerald-200'}`}
          title={auto ? 'Paid via a recorded payout (e.g. from the property\'s Pay Landlord screen)' : 'Click to unmark as paid'}>
          <CheckCircle className="w-3.5 h-3.5" /> Paid
        </button>
        {auto ? (
          <span className="flex flex-col leading-tight">
            <span className="text-[10px] text-muted-foreground">via payment</span>
            {row.paidDate && <span className="text-[10px] text-muted-foreground">{row.paidDate}</span>}
          </span>
        ) : (
          <span className="flex flex-col leading-tight items-start gap-0.5">
            <span className={`text-[10px] px-1.5 py-0.5 rounded font-medium ${row.paidMethod === 'cash' ? 'bg-amber-100 text-amber-700' : 'bg-blue-100 text-blue-700'}`}>
              {row.paidMethod === 'cash' ? 'Cash' : 'Bank'}
            </span>
            {row.paidMethod === 'cash' && paidEntry && parsePaidEntry(paidEntry).paid_by && (
              <span className="text-[10px] text-muted-foreground whitespace-nowrap">{parsePaidEntry(paidEntry).paid_by}</span>
            )}
            {paidDate && (
              <button onClick={openPicker} disabled={saving}
                className="text-[10px] text-muted-foreground underline decoration-dotted underline-offset-2 hover:text-foreground disabled:opacity-50 whitespace-nowrap"
                title="Click to change the payment date">
                {paidDate}
              </button>
            )}
          </span>
        )}
        {pickerPopup}
      </div>
    );
  }

  return (
    <div className="relative inline-block" ref={popoverRef}>
      <Button size="sm" onClick={openPicker} disabled={saving} className="bg-emerald-600 hover:bg-emerald-700">
        {saving ? '...' : 'Mark Paid'}
      </Button>
      {pickerPopup}
    </div>
  );
}

// Manual paid-amount cell — type how much was paid this month. Stored per exact month (or month+landlord for co-owned).
function PaidAmountCell({ property, month, monthKey, onSaved, fallbackPaid = 0 }) {
  const key = monthKey || month;
  const history = Array.isArray(property.landlord_paid_history) ? property.landlord_paid_history : [];
  const entry = history.find((h) => h && h.month === key);
  const stored = entry && entry.amount != null ? String(entry.amount) : '';
  const [value, setValue] = useState(stored);
  const [saving, setSaving] = useState(false);
  const [justSaved, setJustSaved] = useState(false);

  useEffect(() => {
    const h = Array.isArray(property.landlord_paid_history) ? property.landlord_paid_history : [];
    const e = h.find((x) => x && x.month === key);
    setValue(e && e.amount != null ? String(e.amount) : '');
  }, [property.landlord_paid_history, key]);

  const dirty = value !== stored;

  const handleSave = async () => {
    if (!dirty || !key) return;
    const amount = value === '' ? null : parseFloat(value);
    if (amount != null && (Number.isNaN(amount) || amount < 0)) { setValue(stored); return; }
    setSaving(true);
    try {
      const next = amount == null
        ? history.filter((h) => h && h.month !== key)
        : [...history.filter((h) => h && h.month !== key), { month: key, amount }];
      await base44.entities.Property.update(property.id, { landlord_paid_history: next });
      setJustSaved(true);
      setTimeout(() => setJustSaved(false), 1200);
      onSaved && onSaved();
    } catch (e) {
      alert(`Could not save: ${e.message || e}`);
      setValue(stored);
    } finally { setSaving(false); }
  };

  const handleKey = (e) => {
    if (e.key === 'Enter') { e.preventDefault(); handleSave(); e.target.blur(); }
    else if (e.key === 'Escape') setValue(stored);
  };

  return (
    <div className="flex items-center justify-end gap-2">
      <div className="relative">
        <span className="absolute left-2 top-1/2 -translate-y-1/2 text-xs text-muted-foreground">£</span>
        <input
          type="number" step="0.01" value={value}
          onChange={(e) => setValue(e.target.value)}
          onBlur={handleSave} onKeyDown={handleKey}
          placeholder={fallbackPaid > 0 ? String(fallbackPaid) : '0.00'} disabled={saving}
          className="w-24 pl-5 pr-2 py-1.5 text-sm text-right text-emerald-700 font-semibold border border-input rounded-md focus:outline-none focus:ring-2 focus:ring-primary disabled:opacity-50"
        />
      </div>
      {justSaved && <CheckCircle className="w-4 h-4 text-emerald-600" />}
      {!value && fallbackPaid > 0 && (
        <span className="text-[10px] text-emerald-700 whitespace-nowrap" title="Amount recorded via a payout (e.g. from the property's Pay Landlord screen)">
          {formatCurrency(fallbackPaid)} paid
        </span>
      )}
    </div>
  );
}

// Extra payment lines for a property/month — PURELY VISUAL notes (no effect on totals/status).
// Stored in property.monthly_notes[month].extra_lines: [{ bank, notes, value, manually_paid, paid_date }].
// Lets you record more than one payment to a landlord in a month (installments).
function LandlordExtraPaymentLines({ property, month, onSaved, banks = [] }) {
  const getLines = () => {
    const a = Array.isArray(property.monthly_notes) ? property.monthly_notes : [];
    const e = a.find((x) => x && x.month === month) || {};
    return Array.isArray(e.extra_lines) ? e.extra_lines : [];
  };
  const serverLines = getLines();
  const [lines, setLines] = useState(serverLines);
  const [saving, setSaving] = useState(false);
  const [pickerLine, setPickerLine] = useState(null);
  const [pickedDate, setPickedDate] = useState(format(new Date(), 'yyyy-MM-dd'));
  const [cashName, setCashName] = useState('');

  // Re-sync on month/property change or when the NUMBER of lines changes (add/remove).
  useEffect(() => { setLines(getLines()); }, [month, property.id, serverLines.length]);

  const persist = async (nextLines) => {
    setSaving(true);
    try {
      const next = Array.isArray(property.monthly_notes) ? [...property.monthly_notes] : [];
      const idx = next.findIndex((e) => e && e.month === month);
      if (idx >= 0) next[idx] = { ...next[idx], extra_lines: nextLines };
      else next.push({ month, extra_lines: nextLines });
      await base44.entities.Property.update(property.id, { monthly_notes: next });
      onSaved && onSaved();
    } catch (e) { alert(`Could not save: ${e.message || e}`); setLines(getLines()); }
    finally { setSaving(false); }
  };

  const updateLine = (i, field, val) =>
    setLines((prev) => prev.map((l, idx) => (idx === i ? { ...l, [field]: val } : l)));
  const saveLines = () => persist(lines);
  const removeLine = (i) => {
    if (!window.confirm('Remove this extra payment line? This cannot be undone.')) return;
    const nl = lines.filter((_, idx) => idx !== i); setLines(nl); persist(nl);
  };

  const openPicker = (i) => { setPickedDate(format(new Date(), 'yyyy-MM-dd')); setCashName(lines[i]?.paid_by || ''); setPickerLine(i); };
  const markPaid = async (i) => {
    const line = lines[i] || {};
    const amt = parseFloat(line.value);
    if (!amt || Number.isNaN(amt) || amt <= 0) {
      setPickerLine(null);
      alert('Please enter the amount for this payment line before marking as paid.');
      return;
    }
    if ((line.method || 'bank') === 'bank' && !String(line.bank || '').trim()) {
      setPickerLine(null);
      alert('Please enter the Bank for this payment line before marking as paid (or choose Cash).');
      return;
    }
    if (line.method === 'cash' && !cashName.trim()) {
      alert('Please enter who the cash was paid to.');
      return;
    }
    const newDate = format(new Date(pickedDate + 'T00:00:00'), 'dd/MM/yyyy');
    const nl = lines.map((l, idx) => (idx === i ? { ...l, manually_paid: true, paid_date: newDate, ...(l.method === 'cash' ? { paid_by: cashName.trim() } : {}) } : l));
    setLines(nl); setPickerLine(null);
    await persist(nl);
    {
      const amount = amt;
      const tag = `__from_schedule_extra_${i}__`;
      const existing = await base44.entities.LandlordPayout.filter({ property_id: property.id, period_month: month, notes: tag });
      let paymentDate = `${month}-01`;
      if (/^\d{2}\/\d{2}\/\d{4}$/.test(newDate)) { const [dd, mm, yyyy] = newDate.split('/'); paymentDate = `${yyyy}-${mm}-${dd}`; }
      const payload = { landlord_id: property.landlord_id, property_id: property.id, amount, payment_date: paymentDate, period_month: month, method: line.method === 'cash' ? 'cash' : 'bank transfer', paid_from_bank_name: line.method === 'cash' ? '' : (line.bank || ''), reference: line.method === 'cash' ? cashName.trim() : '', notes: tag };
      if (existing && existing.length > 0) await base44.entities.LandlordPayout.update(existing[0].id, payload);
      else await base44.entities.LandlordPayout.create(payload);
      onSaved && onSaved();
    }
  };
  const unmarkPaid = async (i) => {
    if (!window.confirm('Mark this payment line as NOT paid? This clears its paid date.')) return;
    const nl = lines.map((l, idx) => (idx === i ? { ...l, manually_paid: false, paid_date: null } : l));
    setLines(nl);
    await persist(nl);
    const tag = `__from_schedule_extra_${i}__`;
    const existing = await base44.entities.LandlordPayout.filter({ property_id: property.id, period_month: month, notes: tag });
    await Promise.all((existing || []).map((p) => base44.entities.LandlordPayout.delete(p.id)));
    onSaved && onSaved();
  };

  const onKey = (e) => { if (e.key === 'Enter') { e.preventDefault(); e.target.blur(); } };

  if (lines.length === 0) return null;

  return lines.map((line, i) => (
    <tr key={`extra-${property.id}-${month}-${i}`} className="border-t border-dashed border-border bg-muted/20">
      <td className="px-4 py-3"></td>
      <td className="px-4 py-3 pl-8 text-xs text-muted-foreground whitespace-nowrap">↳ extra payment</td>
      <td className="px-4 py-3"></td>
      <td className="px-4 py-3"></td>
      <td className="px-4 py-3"></td>
      <td className="px-4 py-3"></td>
      <td className="px-4 py-3">
        {month < BANK_DROPDOWN_FROM ? (
          <input type="text" value={line.bank || ''} onChange={(e) => updateLine(i, 'bank', e.target.value)}
            onBlur={saveLines} onKeyDown={onKey} placeholder="Bank…" disabled={saving}
            className="w-32 px-2 py-1.5 text-sm border border-input rounded-md focus:outline-none focus:ring-2 focus:ring-primary disabled:opacity-50" />
        ) : (
          <select value={line.bank || ''} onChange={(e) => { updateLine(i, 'bank', e.target.value); persist(lines.map((l, idx) => idx === i ? { ...l, bank: e.target.value } : l)); }}
            disabled={saving}
            className="w-36 px-2 py-1.5 text-sm border border-input rounded-md bg-background focus:outline-none focus:ring-2 focus:ring-primary disabled:opacity-50">
            <option value="">— Select bank —</option>
            {banks.map((b) => <option key={b.id} value={b.name}>{b.name}</option>)}
            {line.bank && !banks.some((b) => b.name === line.bank) && (
              <option value={line.bank}>{line.bank}</option>
            )}
          </select>
        )}
      </td>
      <td className="px-4 py-3">
        <input type="text" value={line.notes || ''} onChange={(e) => updateLine(i, 'notes', e.target.value)}
          onBlur={saveLines} onKeyDown={onKey} placeholder="Notes…" disabled={saving}
          className="w-36 px-2 py-1.5 text-sm text-red-600 border border-input rounded-md focus:outline-none focus:ring-2 focus:ring-primary disabled:opacity-50" />
      </td>
      <td className="px-4 py-3 text-right">
        <input type="text" value={line.value || ''} onChange={(e) => updateLine(i, 'value', e.target.value)}
          onBlur={saveLines} onKeyDown={onKey} placeholder="Paid…" disabled={saving}
          className="w-24 px-2 py-1.5 text-sm text-right text-emerald-700 font-semibold border border-input rounded-md focus:outline-none focus:ring-2 focus:ring-primary disabled:opacity-50" />
      </td>
      <td className="px-4 py-3 text-center">
        {line.manually_paid ? (
          <div className="inline-flex flex-col items-center gap-0.5">
            <button onClick={() => unmarkPaid(i)} disabled={saving}
              className="inline-flex items-center gap-1 px-3 py-1.5 rounded-md bg-emerald-100 text-emerald-700 text-xs font-semibold hover:bg-emerald-200 disabled:opacity-50"
              title="Click to mark as not paid">
              <CheckCircle className="w-3.5 h-3.5" /> Paid
            </button>
            <span className={`text-[10px] px-1.5 py-0.5 rounded font-medium ${line.method === 'cash' ? 'bg-amber-100 text-amber-700' : 'bg-blue-100 text-blue-700'}`}>
              {line.method === 'cash' ? 'Cash' : 'Bank'}
            </span>
            {line.method === 'cash' && line.paid_by && <span className="text-[10px] text-muted-foreground whitespace-nowrap">{line.paid_by}</span>}
            {line.paid_date && <span className="text-xs text-muted-foreground whitespace-nowrap">{line.paid_date}</span>}
          </div>
        ) : pickerLine === i ? (
          <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 p-4" onClick={() => setPickerLine(null)}>
            <div className="bg-card border border-border rounded-xl shadow-xl p-5 w-full max-w-xs" onClick={(e) => e.stopPropagation()}>
              <p className="text-sm font-semibold mb-3">Record extra payment</p>
              <label className="block text-xs font-medium text-muted-foreground mb-1">Method</label>
              <div className="flex gap-1 p-0.5 bg-muted rounded-lg mb-3">
                <button onClick={() => { updateLine(i, 'method', 'bank'); persist(lines.map((l, idx) => idx === i ? { ...l, method: 'bank' } : l)); }}
                  className={`flex-1 text-sm font-semibold py-2 rounded-md transition-colors ${(line.method || 'bank') === 'bank' ? 'bg-white shadow text-foreground' : 'text-muted-foreground'}`}>Bank transfer</button>
                <button onClick={() => { updateLine(i, 'method', 'cash'); persist(lines.map((l, idx) => idx === i ? { ...l, method: 'cash' } : l)); }}
                  className={`flex-1 text-sm font-semibold py-2 rounded-md transition-colors ${line.method === 'cash' ? 'bg-white shadow text-emerald-700' : 'text-muted-foreground'}`}>Cash</button>
              </div>
              {line.method === 'cash' && <p className="text-[11px] text-emerald-700 bg-emerald-50 rounded px-2 py-1.5 mb-3">Records a matching entry in the cash ledger.</p>}
              {line.method === 'cash' && (
                <div className="mb-3">
                  <label className="block text-xs font-medium text-muted-foreground mb-1">Cash paid to (name) *</label>
                  <input type="text" value={cashName} onChange={(e) => setCashName(e.target.value)}
                    placeholder="Who was the cash handed to?" autoFocus
                    className="w-full text-sm border border-input rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-primary" />
                </div>
              )}
              <label className="block text-xs font-medium text-muted-foreground mb-1">Payment date</label>
              <input type="date" value={pickedDate} onChange={(e) => setPickedDate(e.target.value)}
                className="w-full text-sm border border-input rounded-md px-3 py-2 mb-4 focus:outline-none focus:ring-2 focus:ring-primary" />
              <div className="flex gap-2">
                <button onClick={() => markPaid(i)} disabled={saving || (line.method === 'cash' && !cashName.trim())}
                  className="flex-1 px-3 py-2 rounded-md bg-emerald-600 text-white text-sm font-semibold hover:bg-emerald-700 disabled:opacity-50">
                  {saving ? 'Saving…' : 'Save'}
                </button>
                <button onClick={() => setPickerLine(null)}
                  className="flex-1 px-3 py-2 rounded-md bg-muted text-muted-foreground text-sm hover:bg-muted/80">Cancel</button>
              </div>
            </div>
          </div>
        ) : (
          <Button size="sm" onClick={() => openPicker(i)} disabled={saving} className="bg-emerald-600 hover:bg-emerald-700">
            Mark Paid
          </Button>
        )}
      </td>
      <td className="px-4 py-3 text-right">
        <button onClick={() => removeLine(i)} disabled={saving} title="Remove this payment line"
          className="inline-flex items-center justify-center w-7 h-7 rounded-md bg-red-100 text-red-600 hover:bg-red-200 disabled:opacity-50">
          <X className="w-3.5 h-3.5" />
        </button>
      </td>
    </tr>
  ));
}

export default function LandlordPaymentSchedule() {
  const queryClient = useQueryClient();
  const { data: landlords = [], refetch: rA } = useLandlords();
  const { data: properties = [], refetch: rB } = useProperties();
  const { data: tenants = [] } = useTenants();
  const { data: landlordPayouts = [], refetch: rF } = useLandlordPayouts();
  const { data: paymentExtras = [], refetch: rH } = usePaymentExtras();
  const { data: banks = [] } = useBanks();
  const { data: rentPayments = [] } = useRentPayments();
  const [activeTab, setActiveTab] = useState(null);
  const [refreshing, setRefreshing] = useState(false);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('all'); // all | Paid | Partial | Not Paid
  const [amountLocked, setAmountLocked] = useState(true);

  useEffect(() => {
    ['properties', 'landlords', 'landlord_payouts', 'payment_extras'].forEach((q) => queryClient.invalidateQueries({ queryKey: [q] }));
  }, [queryClient]);

  const handleRefresh = async () => {
    setRefreshing(true);
    await Promise.all([rA(), rB(), rF(), rH()]);
    setRefreshing(false);
  };

  const { baseRows, excluded } = useMemo(() => {
    const included = [];
    const out = [];
    properties.forEach((p) => {
      const landlord = landlords.find((l) => l.id === p.landlord_id);
      if (!landlord) { out.push({ property: p, landlord: null, reason: 'Landlord not found', fix: 'property' }); return; }
      if (landlord.status === 'inactive') { out.push({ property: p, landlord, reason: `Landlord "${landlord.name}" is inactive`, fix: 'landlord' }); return; }
      if (landlord.is_agent) { out.push({ property: p, landlord, reason: `"${landlord.name}" marked as agent`, fix: 'landlord' }); return; }
      if (!p.payment_day) { out.push({ property: p, landlord, reason: 'No payment day set', fix: 'property' }); return; }

      const freq = getPropertyFrequency(p, tenants);
      if (isMultiLandlord(p)) {
        // One row per co-owner. The property is included as a whole (checks above
        // use the primary landlord); each owner gets an independent row.
        const shares = getLandlordShares(p);
        const totalPct = shares.reduce((s, x) => s + (x.share_pct || 0), 0) || 100;
        shares.forEach((sh) => {
          const co = landlords.find((l) => l.id === sh.landlord_id) || landlord;
          included.push({ property: p, landlord: co, landlordId: sh.landlord_id, coOwned: true, sharePct: sh.share_pct, shareFraction: (sh.share_pct || 0) / totalPct, freq });
        });
      } else {
        included.push({ property: p, landlord, landlordId: p.landlord_id, coOwned: false, sharePct: 100, shareFraction: 1, freq });
      }
    });
    included.sort((a, b) => a.property.payment_day - b.property.payment_day);
    return { baseRows: included, excluded: out };
  }, [landlords, properties, tenants]);

  const months = useMemo(() => {
    const set = new Set([format(new Date(), 'yyyy-MM')]);
    landlordPayouts.forEach((p) => {
      const m = p.period_month || (p.payment_date ? p.payment_date.substring(0, 7) : null);
      if (m) set.add(m);
    });
    // also surface any months that appear in amount history so you can see/edit them
    properties.forEach((p) => {
      (Array.isArray(p.landlord_amount_history) ? p.landlord_amount_history : []).forEach((h) => { if (h?.from) set.add(h.from); });
    });
    // Surface the billing months for quarterly properties so their tabs always exist.
    const cur = format(new Date(), 'yyyy-MM');
    properties.forEach((p) => {
      const { frequency, leaseStartMonth } = getPropertyFrequency(p, tenants);
      if (frequency !== 'quarterly' || !leaseStartMonth) return;
      const start = addMonthsStr(cur, -24) > leaseStartMonth ? addMonthsStr(cur, -24) : leaseStartMonth;
      let m = start;
      while (m <= addMonthsStr(cur, 3)) {
        if (isDueMonth(leaseStartMonth, m, 'quarterly')) set.add(m);
        m = addMonthsStr(m, 1);
      }
    });
    return [...set].sort();
  }, [landlordPayouts, properties, tenants]);

  useEffect(() => {
    if (months.length === 0) return;
    const cur = format(new Date(), 'yyyy-MM');
    setActiveTab(months.includes(cur) ? cur : months[months.length - 1]);
  }, [months.join(',')]);

  const rows = useMemo(() => {
    if (!activeTab) return [];
    return baseRows
      .filter((r) => r.freq.frequency !== 'quarterly' || isDueMonth(r.freq.leaseStartMonth, activeTab, 'quarterly'))
      // Hide properties with no active tenancy during this month — if no tenant's
      // lease covers the selected period, there's nothing to pay the landlord for.
      .filter((r) => tenants.some((t) => {
        if (t.property_id !== r.property.id || !t.lease_start) return false;
        const startMonth = t.lease_start.substring(0, 7);
        if (startMonth > activeTab) return false;
        if (t.lease_end && t.lease_end.substring(0, 7) < activeTab) return false;
        return true;
      }))
      .filter((r) => !search.trim() ||
        r.landlord.name?.toLowerCase().includes(search.toLowerCase()) ||
        r.property.address?.toLowerCase().includes(search.toLowerCase()))
      .map((r) => {
        const myPayouts = landlordPayouts.filter((p) => {
          const m = p.period_month || (p.payment_date ? p.payment_date.substring(0, 7) : null);
          // The main row excludes the "+ extra payment" line payouts — those are
          // shown as their own rows and must not change the main payment's total/method.
          const isExtra = String(p.notes || '').startsWith('__from_schedule_extra_');
          return !isExtra && p.property_id === r.property.id && m === activeTab &&
            (!r.coOwned || p.landlord_id === r.landlordId);
        });
        const paid = myPayouts.reduce((sum, p) => sum + Number(p.amount || 0), 0);
        // Total paid INCLUDING the extra-payment lines — used for the Paid/Partial status
        // (so an extra payment that tops up the balance correctly shows as Paid).
        const paidTotal = landlordPayouts
          .filter((p) => {
            const m = p.period_month || (p.payment_date ? p.payment_date.substring(0, 7) : null);
            return p.property_id === r.property.id && m === activeTab && (!r.coOwned || p.landlord_id === r.landlordId);
          })
          .reduce((sum, p) => sum + Number(p.amount || 0), 0);
        // Method shown should be the scheduled payment's method (the one this page
        // recorded). If there isn't one, use the largest payout's method — so a small
        // ad-hoc cash payout doesn't relabel a larger bank payment as "Cash".
        const schedulePayout = myPayouts.find((p) => String(p.notes || '') === '__from_schedule__');
        let methodSource = schedulePayout;
        if (!methodSource && myPayouts.length > 0) {
          methodSource = [...myPayouts].sort((a, b) => Number(b.amount || 0) - Number(a.amount || 0))[0];
        }
        const paidMethod = methodSource && methodSource.method === 'cash' ? 'cash' : 'bank';
        // The actual bank the payout came from (for display on the schedule when
        // the payment was recorded elsewhere, e.g. the property's Pay Landlord screen).
        const paidBankName = methodSource
          ? (methodSource.payment_mode === 'split' ? (methodSource.split_bank_name || '') : (methodSource.paid_from_bank_name || ''))
          : '';
        // Actual amount paid via the payout(s) and the date of the payment, so the
        // schedule can show them in the Paid column / next to the Paid badge even
        // when the payment was recorded from the property's Pay Landlord screen.
        const paidAmount = paidTotal;
        const paidDateVal = methodSource
          ? (methodSource.payment_date ? format(parseISO(methodSource.payment_date), 'd MMM yyyy') : '')
          : '';

        const frequency = r.freq.frequency;
        const propAmount = resolveAmount(Array.isArray(r.property.landlord_amount_history) ? r.property.landlord_amount_history : [], activeTab);
        const baseDefault = frequency === 'quarterly' ? forPeriod(Number(r.property.monthly_rent) || 0, 'quarterly') : 0;
        // History stores a per-month amount; multiply by the cycle for quarterly display.
        const propAmountFinal = propAmount != null ? forPeriod(propAmount, frequency) : baseDefault;
        // Co-owned default amount = the owner's share of the property amount (editable per owner).
        const defaultAmount = r.coOwned ? Math.round(propAmountFinal * r.shareFraction * 100) / 100 : propAmountFinal;
        const sharedResolved = r.coOwned
          ? resolveAmount(
              (Array.isArray(r.property.landlord_amount_history_shared) ? r.property.landlord_amount_history_shared : [])
                .filter((h) => h && h.landlord_id === r.landlordId)
                .map((h) => ({ from: h.from, amount: h.amount })),
              activeTab
            )
          : null;
        const sharedAmount = sharedResolved != null ? forPeriod(sharedResolved, frequency) : null;
        const amount = r.coOwned ? (sharedAmount != null ? sharedAmount : defaultAmount) : propAmountFinal;
        // Cell fallback: per-quarter (3×) default for quarterly, the co-owned share for
        // co-owned, or null for monthly single (keeps the empty-when-no-history behaviour).
        const cellDefault = r.coOwned || frequency === 'quarterly' ? defaultAmount : null;

        // Deductions for this property/month. Targeted deductions (charged to one
        // owner) go only to that owner; untargeted ones split by ownership share.
        const propExtras = paymentExtras.filter((e) => e.property_id === r.property.id && e.period_month === activeTab);
        const sharedDeduction = propExtras
          .filter((e) => !e.deduct_from_landlord_id)
          .reduce((sum, e) => sum + Number(e.amount || 0), 0);
        const targetedDeduction = propExtras
          .filter((e) => e.deduct_from_landlord_id === r.landlordId)
          .reduce((sum, e) => sum + Number(e.amount || 0), 0);
        const deduction = r.coOwned
          ? Math.round((sharedDeduction * r.shareFraction + targetedDeduction) * 100) / 100
          : (sharedDeduction + targetedDeduction);

        // Payment status for filtering: net due = amount to pay minus deductions.
        const netDue = Math.max(0, Math.round(((Number(amount) || 0) - (Number(deduction) || 0)) * 100) / 100);
        const paidSoFar = Number(paidTotal) || 0;
        let payStatus = 'Not Paid';
        if (netDue <= 0 || paidSoFar >= netDue) payStatus = 'Paid';
        else if (paidSoFar > 0) payStatus = 'Partial';

        return { ...r, paid, paidTotal, paidMethod, paidBankName, paidAmount, paidDate: paidDateVal, amount, deduction, netDue, payStatus, defaultAmount, cellDefault, frequency };
      });
  }, [baseRows, landlordPayouts, paymentExtras, activeTab, search, tenants]);

  const paidCount = rows.filter((r) => r.payStatus === 'Paid').length;
  const partialCount = rows.filter((r) => r.payStatus === 'Partial').length;
  const notPaidCount = rows.length - paidCount - partialCount;
  const outstandingTotal = rows.reduce((s, r) => s + Math.max(0, (Number(r.netDue) || 0) - (Number(r.paidTotal) || 0)), 0);
  const filteredRows = useMemo(
    () => (statusFilter === 'all' ? rows : rows.filter((r) => r.payStatus === statusFilter)),
    [rows, statusFilter]
  );

  const handleSaved = async () => {
    await Promise.all([rB(), rF()]);
    queryClient.invalidateQueries({ queryKey: ['properties'] });
    queryClient.invalidateQueries({ queryKey: ['landlord_payouts'] });
  };

  // Append a blank extra payment line to a property's month (visual note only).
  const addExtraPaymentLine = async (property, month) => {
    if (!month) return;
    const arr = Array.isArray(property.monthly_notes) ? [...property.monthly_notes] : [];
    const idx = arr.findIndex((e) => e && e.month === month);
    const blank = { bank: '', notes: '', value: '' };
    if (idx >= 0) {
      const existing = Array.isArray(arr[idx].extra_lines) ? arr[idx].extra_lines : [];
      arr[idx] = { ...arr[idx], extra_lines: [...existing, blank] };
    } else {
      arr.push({ month, extra_lines: [blank] });
    }
    try {
      await base44.entities.Property.update(property.id, { monthly_notes: arr });
      await handleSaved();
    } catch (e) { alert(`Could not save: ${e.message || e}`); }
  };

  return (
    <div>
      <ScrollNav />
      <PageHeader
        title="Landlord Payment Dates"
        description="Type the amount you pay each landlord. Changing it applies from the selected month forward — earlier months keep their previous amount."
        actions={
          <Button size="sm" variant="outline" onClick={handleRefresh} disabled={refreshing}>
            <RefreshCw className={`w-3 h-3 mr-1 ${refreshing ? 'animate-spin' : ''}`} />
            {refreshing ? 'Refreshing...' : 'Refresh'}
          </Button>
        }
      />

      {/* Landlord-page accent banner */}
      <LandlordBanner subtitle="Money you pay out to landlords — not tenant rent received." />

      <div className="bg-card rounded-xl border border-border mb-6 px-4 py-3 flex items-center gap-2">
        <Search className="w-4 h-4 text-muted-foreground" />
        <input type="text" placeholder="Search by landlord name or property address…" value={search} onChange={(e) => setSearch(e.target.value)} className="flex-1 bg-transparent outline-none text-sm" />
        {search && <button onClick={() => setSearch('')} className="text-xs text-muted-foreground hover:text-foreground">Clear</button>}
      </div>

      <div className="flex flex-wrap items-center gap-1.5 mb-6 -mt-3">
        <span className="text-xs font-medium text-muted-foreground mr-1">Status:</span>
        {[['all', `All (${rows.length})`], ['Paid', `Paid (${paidCount})`], ['Partial', `Partial (${partialCount})`], ['Not Paid', `Not paid (${notPaidCount})`]].map(([k, label]) => (
          <button key={k} onClick={() => setStatusFilter(k)}
            className={`px-2.5 py-1 rounded-full text-xs font-semibold transition-colors ${statusFilter === k
              ? (k === 'Paid' ? 'bg-emerald-600 text-white' : k === 'Partial' ? 'bg-amber-500 text-white' : k === 'Not Paid' ? 'bg-red-600 text-white' : 'bg-primary text-white')
              : 'bg-muted text-muted-foreground hover:text-foreground'}`}>
            {label}
          </button>
        ))}
      </div>

      <div className="bg-card rounded-xl border border-border mb-6 overflow-hidden">
        <div className="overflow-x-auto">
          <div className="flex border-b border-border min-w-max">
            {months.map((m) => {
              const isActive = m === activeTab;
              return (
                <button key={m} onClick={() => setActiveTab(m)}
                  className={`px-4 py-3 text-sm font-medium border-b-2 transition-colors whitespace-nowrap ${
                    isActive ? 'border-amber-500 text-amber-700 bg-amber-50' : 'border-transparent text-muted-foreground hover:text-foreground hover:bg-muted/30'
                  }`}>
                  {format(parseISO(`${m}-01`), 'MMM yyyy')}
                </button>
              );
            })}
          </div>
        </div>
      </div>

      <div className="bg-card rounded-xl border border-border overflow-hidden mb-6">
        <div className="px-5 py-4 border-b border-border flex items-center justify-between gap-2 flex-wrap bg-amber-50/40">
          <div className="flex items-center gap-2">
            <Calendar className="w-4 h-4 text-amber-600" />
            <h2 className="text-sm font-semibold">{activeTab ? format(parseISO(`${activeTab}-01`), 'MMMM yyyy') : ''}</h2>
          </div>
          <p className="text-xs text-muted-foreground">
            {paidCount} paid · {partialCount} partial · {notPaidCount} not paid · Outstanding: {formatCurrency(outstandingTotal)}
          </p>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-muted/50">
                <th className="text-left  px-4 py-3 font-medium text-muted-foreground w-20">Date</th>
                <th className="text-left  px-4 py-3 font-medium text-muted-foreground">Property</th>
                <th className="text-left  px-4 py-3 font-medium text-muted-foreground">Landlord</th>
                <th className="text-center px-4 py-3 font-medium text-muted-foreground">Payment</th>
                <th className="text-right px-4 py-3 font-medium text-muted-foreground">
                  <div className="flex items-center justify-end gap-2">
                    <span>Amount to Pay</span>
                    <button
                      onClick={() => setAmountLocked(!amountLocked)}
                      title={amountLocked ? 'Unlock to edit' : 'Lock column'}
                      className={`inline-flex items-center gap-1 px-2 py-1 rounded text-xs font-medium transition-colors ${amountLocked ? 'bg-red-100 text-red-600 hover:bg-red-200' : 'bg-emerald-100 text-emerald-700 hover:bg-emerald-200'}`}
                    >
                      {amountLocked ? <><Lock className="w-3 h-3" /> Locked</> : <><Unlock className="w-3 h-3" /> Unlocked</>}
                    </button>
                  </div>
                </th>
                <th className="text-right px-4 py-3 font-medium text-muted-foreground">Deduction</th>
                <th className="text-left px-4 py-3 font-medium text-muted-foreground">Bank</th>
                <th className="text-left px-4 py-3 font-medium text-muted-foreground">Notes</th>
                <th className="text-right px-4 py-3 font-medium text-muted-foreground">Paid (£)</th>
                <th className="text-center px-4 py-3 font-medium text-muted-foreground">Status</th>
                <th className="px-4 py-3"></th>
              </tr>
            </thead>
            <tbody>
              {filteredRows.length === 0 ? (
                <tr><td colSpan="10" className="px-4 py-8 text-center text-muted-foreground">
                  {search ? `No matches for "${search}"` : (statusFilter !== 'all' ? `No ${statusFilter.toLowerCase()} rows this month` : 'No properties with payment dates set')}
                </td></tr>
              ) : filteredRows.map((r, ri) => {
                const mKey = monthKeyFor(activeTab, r.landlordId, r.coOwned);
                const firstOfProperty = filteredRows.findIndex((x) => x.property.id === r.property.id) === ri;
                return (
                <React.Fragment key={`${r.property.id}__${r.landlordId}`}>
                <tr className="border-t border-border hover:bg-muted/30">
                  <td className="px-4 py-3 font-semibold">{firstOfProperty ? ordinal(r.property.payment_day) : ''}</td>
                  <td className="px-4 py-3">{firstOfProperty ? <TenantRentStatus property={r.property} month={activeTab} tenants={tenants} rentPayments={rentPayments}>{r.property.address}</TenantRentStatus> : ''}</td>
                  <td className="px-4 py-3 text-muted-foreground">
                    <div className="font-medium text-foreground">
                      {r.landlord.name}
                      {r.coOwned && <span className="ml-1 text-xs text-primary">({r.sharePct}%)</span>}
                      {r.frequency === 'quarterly' && <span className="ml-1.5 inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold bg-indigo-100 text-indigo-700">Quarterly</span>}
                    </div>
                    {(() => {
                      const acc = resolvePayoutAccount(r.property, r.landlord);
                      if (!acc || !(acc.account_number || acc.sort_code || acc.bank_name)) {
                        return <div className="mt-0.5 text-[11px] text-amber-600">No bank account set</div>;
                      }
                      return (
                        <div className="mt-0.5 text-[11px] leading-tight text-muted-foreground">
                          {acc.label && <div className="text-primary">{acc.label}</div>}
                          {acc.account_name && <div>{acc.account_name}</div>}
                          <div>
                            {acc.bank_name && <span>{acc.bank_name} · </span>}
                            {acc.sort_code && <span>{acc.sort_code} </span>}
                            {acc.account_number && <span className="font-medium text-foreground">{acc.account_number}</span>}
                          </div>
                          {acc.payment_reference && <div>Ref: {acc.payment_reference}</div>}
                        </div>
                      );
                    })()}
                  </td>
                  <td className="px-4 py-3 text-center">
                    {(() => {
                      const due = Math.max(0, (Number(r.amount) || 0) - (Number(r.deduction) || 0));
                      const paidNow = Number(r.paidTotal ?? r.paid) || 0;
                      if (paidNow <= 0) {
                        return (
                          <span className="inline-flex items-center gap-1 px-3 py-1.5 rounded-md bg-red-100 text-red-600 text-xs font-semibold">
                            Not Paid
                          </span>
                        );
                      }
                      if (due > 0 && paidNow + 0.005 < due) {
                        return (
                          <span className="inline-flex flex-col items-center px-3 py-1 rounded-md bg-amber-100 text-amber-700 text-xs font-semibold">
                            <span>Partial</span>
                            <span className="text-[10px] font-normal">{formatCurrency(paidNow)} of {formatCurrency(due)}</span>
                          </span>
                        );
                      }
                      return (
                        <span className="inline-flex items-center gap-1 px-3 py-1.5 rounded-md bg-emerald-100 text-emerald-700 text-xs font-semibold">
                          <CheckCircle className="w-3.5 h-3.5" /> Paid
                        </span>
                      );
                    })()}
                  </td>
                  <td className="px-4 py-3 text-right">
                    <AmountCell property={r.property} month={activeTab} onSaved={handleSaved} locked={amountLocked} landlordId={r.landlordId} coOwned={r.coOwned} defaultAmount={r.cellDefault} frequency={r.frequency} />
                  </td>
                  <td className="px-4 py-3 text-right font-medium text-red-600">
                    {r.deduction > 0 ? `- ${formatCurrency(r.deduction)}` : '-'}
                  </td>
                  <td className="px-4 py-3">
                    <BankCell property={r.property} month={activeTab} monthKey={mKey} onSaved={handleSaved} banks={banks} fallbackBank={r.paidBankName} />
                  </td>
                  <td className="px-4 py-3">
                    <NotesCell property={r.property} month={activeTab} monthKey={mKey} onSaved={handleSaved} />
                  </td>
                  <td className="px-4 py-3 text-right">
                    <PaidAmountCell property={r.property} month={activeTab} monthKey={mKey} onSaved={handleSaved} fallbackPaid={Number(r.paidAmount) || 0} />
                  </td>
                  <td className="px-4 py-3 text-center">
                    <MarkPaidButton row={r} month={activeTab} onSaved={handleSaved} autoPaid={r.paid > 0} />
                  </td>
                  <td className="px-4 py-3 text-right">
                    <div className="inline-flex items-center gap-1.5">
                      <button
                        onClick={() => addExtraPaymentLine(r.property, activeTab)}
                        title="Add another payment line for this month (note only — does not change totals)"
                        className="inline-flex items-center justify-center w-8 h-8 rounded-md border border-input text-primary hover:bg-primary/5"
                      >
                        <Plus className="w-4 h-4" />
                      </button>
                      <Link to={`/PropertyDetail?id=${r.property.id}&tab=landlord_payments`}>
                        <Button size="sm" variant="outline">Open <ArrowRight className="w-3 h-3 ml-1" /></Button>
                      </Link>
                    </div>
                  </td>
                </tr>
                {firstOfProperty && <LandlordExtraPaymentLines property={r.property} month={activeTab} onSaved={handleSaved} banks={banks} />}
                </React.Fragment>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      {excluded.length > 0 && (
        <div className="bg-amber-50 border border-amber-200 rounded-xl overflow-hidden">
          <div className="px-5 py-4 border-b border-amber-200 flex items-center gap-2">
            <AlertCircle className="w-4 h-4 text-amber-600" />
            <h2 className="text-sm font-semibold text-amber-900">Properties hidden from the list above</h2>
            <span className="ml-auto text-xs text-amber-700">{excluded.length} {excluded.length === 1 ? 'property' : 'properties'}</span>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="bg-amber-100/50">
                  <th className="text-left px-4 py-3 font-medium text-amber-900">Property</th>
                  <th className="text-left px-4 py-3 font-medium text-amber-900">Landlord</th>
                  <th className="text-left px-4 py-3 font-medium text-amber-900">Reason</th>
                  <th className="px-4 py-3"></th>
                </tr>
              </thead>
              <tbody>
                {excluded.map((e) => (
                  <tr key={e.property.id} className="border-t border-amber-200 hover:bg-amber-100/30">
                    <td className="px-4 py-3 font-medium">{e.property.address?.split(',')[0] || '(no address)'}</td>
                    <td className="px-4 py-3 text-amber-800">{e.landlord?.name || '—'}</td>
                    <td className="px-4 py-3 text-xs text-amber-900">{e.reason}</td>
                    <td className="px-4 py-3 text-right">
                      {e.fix === 'landlord' && e.landlord ? (
                        <Link to={`/LandlordDetail?id=${e.landlord.id}`}><Button size="sm" variant="outline">Open landlord <ArrowRight className="w-3 h-3 ml-1" /></Button></Link>
                      ) : (
                        <Link to={`/PropertyDetail?id=${e.property.id}`}><Button size="sm" variant="outline">Open property <ArrowRight className="w-3 h-3 ml-1" /></Button></Link>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}

