export default function LandlordStatements() {
  const { data: rentPayments = [] } = useRentPayments();
  const { data: landlords = [] } = useLandlords();
  const { data: properties = [] } = useProperties();
  const { data: tenants = [] } = useTenants();
  const { data: commissionLedger = [] } = useCommissionLedger();
  const { data: landlordPayouts = [] } = useLandlordPayouts();
  const { data: expenses = [] } = useExpenses();
  const { data: paymentExtras = [] } = usePaymentExtras();
  const { data: maintenanceRequests = [] } = useMaintenanceRequests();
  const { data: commissionAgreements = [] } = useCommissionAgreements();

  const [filterLandlord, setFilterLandlord] = useState('all');
  const urlParams = new URLSearchParams(window.location.search);
  const [filterStatus, setFilterStatus] = useState(urlParams.get('status') || 'all');
  const [filterPeriod, setFilterPeriod] = useState('');
  const [selected, setSelected] = useState(null);
  const [emailStmt, setEmailStmt] = useState(null);

  const allStatements = useMemo(() => buildLandlordStatements({
    landlords, properties, tenants, rentPayments, commissionLedger, expenses,
    landlordPayouts, paymentExtras, maintenanceRequests, commissionAgreements,
  }), [landlords, properties, tenants, rentPayments, commissionLedger, expenses,
       landlordPayouts, paymentExtras, maintenanceRequests, commissionAgreements]);

  const filtered = useMemo(() => allStatements
    .filter(s => {
      if (filterLandlord !== 'all' && s.landlord_id !== filterLandlord) return false;
      if (filterStatus !== 'all' && s.status !== filterStatus) return false;
      if (filterPeriod && !s.period_month.includes(filterPeriod)) return false;
      return true;
    })
    .sort((a, b) => a.period_month.localeCompare(b.period_month) || a.landlord_name.localeCompare(b.landlord_name))
  , [allStatements, filterLandlord, filterStatus, filterPeriod]);

  const totalOwed = filtered.reduce((s, st) => s + (st.invoice_net_payable ?? st.net_payable), 0);
  const totalPaid = filtered.reduce((s, st) => s + st.paid_this_period, 0);
  const totalPending = filtered.reduce((s, st) => s + st.balance_due, 0);

  const buildEmailBody = (s) => `Dear ${s.landlord_name},

Please find below your landlord statement for ${s.period_month}.

Agreed Rent: ${formatCurrency(s.expected_rent || s.agreed_rent || 0)}
Net Payable to You: ${formatCurrency(s.net_payable)}
Already Paid: ${formatCurrency(s.paid_this_period)}
Balance Due: ${formatCurrency(s.balance_due)}

This statement reflects the agreed amount due to you, regardless of tenant payment status. Tenant shortfalls or overpayments are handled separately and do not affect what we owe you.

If you have any questions, please contact us.

Kind regards,
ASA Estates Ltd
info@asaestates.com`;

  const exportExcel = () => {
    const rows = filtered.map(s => ({
      'Statement #': s.statement_number, 'Landlord': s.landlord_name, 'Period': s.period_month,
      'Agreed Rent': s.expected_rent || s.agreed_rent || 0,
      'Net Payable': s.net_payable,
      'Paid': s.paid_this_period, 'Balance Due': s.balance_due, 'Status': s.status,
    }));
    const ws = XLSX.utils.json_to_sheet(rows);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Landlord Statements');
    XLSX.writeFile(wb, `Landlord_Statements_${new Date().toISOString().slice(0,10)}.xlsx`);
  };

  return (
