import React, { useState } from 'react';
import { base44 } from '@/api/base44Client';
import { useLandlords, useProperties } from '@/hooks/useAllData';
import { useQueryClient } from '@tanstack/react-query';
import { useRole } from '@/hooks/useRole';
import { logAction } from '@/lib/audit';
import PageHeader from '@/components/ui/PageHeader';
import LandlordBanner from '@/components/ui/LandlordBanner';
import StatusBadge from '@/components/ui/StatusBadge';
import LandlordForm from '@/components/forms/LandlordForm';
import ConfirmDialog from '@/components/ui/ConfirmDialog';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Plus, Search, Eye, Pencil, Trash2, Upload } from 'lucide-react';
import Pagination from '@/components/ui/Pagination';
import LandlordImportModal from '@/components/import/LandlordImportModal';
import { Input } from '@/components/ui/input';
import { Link } from 'react-router-dom';

export default function Landlords() {
  const { user, isAdmin } = useRole();
  const { data: landlords = [] } = useLandlords();
  const { data: properties = [] } = useProperties();
  const queryClient = useQueryClient();
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState(null);
  const [search, setSearch] = useState('');
  const [confirmDelete, setConfirmDelete] = useState(null);
  const [showImport, setShowImport] = useState(false);
  const [page, setPage] = useState(1);
  const PAGE_SIZE = 20;

  const handleSubmit = async (data) => {
    if (editing) {
      await base44.entities.Landlord.update(editing.id, data);
      await logAction({ user, action: 'update', entityType: 'Landlord', entityId: editing.id, summary: `Updated landlord ${data.name}`, oldValue: editing, newValue: data });
    } else {
      const created = await base44.entities.Landlord.create(data);
      await logAction({ user, action: 'create', entityType: 'Landlord', entityId: created.id, summary: `Created landlord ${data.name}`, newValue: data });
    }
    queryClient.invalidateQueries({ queryKey: ['landlords'] });
    setShowForm(false);
    setEditing(null);
  };

  const handleDelete = async (landlord) => {
    const linked = properties.filter(p => p.landlord_id === landlord.id);
    if (linked.length > 0) {
      alert(`Cannot delete: landlord has ${linked.length} linked propert${linked.length > 1 ? 'ies' : 'y'}. Reassign or delete them first.`);
      setConfirmDelete(null);
      return;
    }
    await base44.entities.Landlord.delete(landlord.id);
    await logAction({ user, action: 'delete', entityType: 'Landlord', entityId: landlord.id, summary: `Deleted landlord ${landlord.name}`, oldValue: landlord });
    queryClient.invalidateQueries({ queryKey: ['landlords'] });
    setConfirmDelete(null);
  };

  const filtered = landlords.filter(l => {
    if (!search) return true;
    const q = search.toLowerCase();
    return [l.name, l.email, l.phone, l.address, l.notes, l.status]
      .some(v => v?.toString().toLowerCase().includes(q));
  });
  const totalPages = Math.ceil(filtered.length / PAGE_SIZE);
  const paged = filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);

  return (
    <div>
      <PageHeader
        title="Landlords"
        description={`${landlords.length} landlords`}
        actions={
          <div className="flex gap-2">
            <Button variant="outline" onClick={() => setShowImport(true)}>
              <Upload className="w-4 h-4 mr-2" />Bulk Import
            </Button>
            <Button onClick={() => { setEditing(null); setShowForm(true); }}>
              <Plus className="w-4 h-4 mr-2" />Add Landlord
            </Button>
          </div>
        }
      />

      <LandlordBanner subtitle="Your landlords and their details." />

      <div className="mb-4 max-w-sm">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input placeholder="Search by name, email, phone, address, notes, status..." value={search} onChange={e => { setSearch(e.target.value); setPage(1); }} className="pl-9" />
        </div>
      </div>

      <div className="bg-card rounded-xl border border-border overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-muted/50">
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Name</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Email</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Phone</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Properties</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Status</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Actions</th>
              </tr>
            </thead>
            <tbody>
              {paged.map(l => (
                <tr key={l.id} className="border-t border-border hover:bg-muted/30 transition-colors">
                  <td className="px-5 py-3 font-medium">{l.name}</td>
                  <td className="px-5 py-3 text-muted-foreground">{l.email || '-'}</td>
                  <td className="px-5 py-3 text-muted-foreground">{l.phone || '-'}</td>
                  <td className="px-5 py-3">{properties.filter(p => p.landlord_id === l.id).length}</td>
                  <td className="px-5 py-3"><StatusBadge color={l.status === 'active' ? 'green' : 'gray'}>{l.status}</StatusBadge></td>
                  <td className="px-5 py-3">
                    <div className="flex items-center gap-2">
                      <Link to={`/LandlordDetail?id=${l.id}`}>
                        <Button variant="ghost" size="sm"><Eye className="w-4 h-4" /></Button>
                      </Link>
                      <Button variant="ghost" size="sm" onClick={() => { setEditing(l); setShowForm(true); }}><Pencil className="w-4 h-4" /></Button>
                      {isAdmin && <Button variant="ghost" size="sm" className="text-destructive hover:text-destructive" onClick={() => setConfirmDelete(l)}><Trash2 className="w-4 h-4" /></Button>}
                    </div>
                  </td>
                </tr>
              ))}
              {filtered.length === 0 && (
                <tr><td colSpan="6" className="px-5 py-8 text-center text-muted-foreground">No landlords found</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
      <Pagination page={page} totalPages={totalPages} total={filtered.length} pageSize={PAGE_SIZE} onPage={setPage} />

      <Dialog open={showForm} onOpenChange={setShowForm}>
        <DialogContent className="max-w-lg">
          <DialogHeader><DialogTitle>{editing ? 'Edit Landlord' : 'Add Landlord'}</DialogTitle></DialogHeader>
          <LandlordForm landlord={editing} onSubmit={handleSubmit} onCancel={() => setShowForm(false)} />
        </DialogContent>
      </Dialog>

      <ConfirmDialog
        open={!!confirmDelete}
        title="Delete Landlord"
        description={`Soft-delete "${confirmDelete?.name}"? This sets them to inactive. All financial history is preserved.`}
        onConfirm={() => handleDelete(confirmDelete)}
        onCancel={() => setConfirmDelete(null)}
      />

      <LandlordImportModal
        open={showImport}
        onClose={() => setShowImport(false)}
        onImported={() => queryClient.invalidateQueries({ queryKey: ['landlords'] })}
      />
    </div>
  );
}

