const exportLedgerToExcel = (entries, filename) => {
  const rows = entries.map(e => ({
    'Date':        e.date ? format(parseISO(e.date), 'dd MMM yyyy') : '-',
    'Type':        e.type,
    'Category':    e.category,
    'Description': e.description,
    'Bank Account': e.received_in_bank_name || '-',
    'Property':    e.property_address || '-',
    'Landlord':    e.landlord_name || '-',
    'Tenant':      e.tenant_name || '-',
    'Income (£)':  e.type === 'Income'  ? e.amount : '',
    'Expense (£)': e.type === 'Expense' ? e.amount : '',
    'Balance (£)': e.running_balance ?? '',
  }));
  const ws = XLSX.utils.json_to_sheet(rows);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Ledger');
  XLSX.writeFile(wb, filename);
};

