// ── Day-end count row: shows the closing balance for a day and who counted it ──
function DayEndCountRow({ date, closingBalance, colSpan, count, knownNames, onSave }) {
  const [editing, setEditing] = useState(false);
  const [name, setName] = useState(count?.counted_by || '');
  const [saving, setSaving] = useState(false);

  const save = async () => {
    const v = name.trim();
    if (!v || saving) return;
    setSaving(true);
    try { await onSave(date, v, count); setEditing(false); } finally { setSaving(false); }
  };

  return (
    <tr className="border-t border-emerald-200/70 bg-emerald-50/50">
      <td colSpan={colSpan} className="px-4 py-2">
        <div className="flex flex-wrap items-center gap-x-4 gap-y-1.5">
          <span className="text-xs font-semibold text-emerald-800 uppercase tracking-wide">
            Day end — {format(parseISO(date), 'dd MMM yyyy')}
          </span>
          <span className="text-xs text-emerald-900">
            Closing cash: <b>{formatCurrency(closingBalance)}</b>
          </span>
          <span className="ml-auto flex items-center gap-2">
            {editing ? (
              <>
                <input
                  list="day-count-names"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); save(); } }}
                  placeholder="Who counted?"
                  autoFocus
                  className="h-7 w-40 rounded-md border border-emerald-300 bg-white px-2 text-xs outline-none focus:border-emerald-500"
                />
                <button onClick={save} disabled={saving || !name.trim()} title="Save" className="inline-flex items-center justify-center w-7 h-7 rounded-md bg-emerald-600 text-white disabled:opacity-50"><Check className="w-3.5 h-3.5" /></button>
                <button onClick={() => { setEditing(false); setName(count?.counted_by || ''); }} title="Cancel" className="inline-flex items-center justify-center w-7 h-7 rounded-md border border-emerald-300 text-emerald-700"><X className="w-3.5 h-3.5" /></button>
              </>
            ) : count?.counted_by ? (
              <button onClick={() => setEditing(true)} title="Change who counted" className="inline-flex items-center gap-1.5 text-xs font-medium text-emerald-800 bg-emerald-100 border border-emerald-300 rounded-full px-2.5 py-1 hover:bg-emerald-200/70">
                <UserCheck className="w-3.5 h-3.5" /> Counted by <b>{count.counted_by}</b>
              </button>
            ) : (
              <button onClick={() => setEditing(true)} className="inline-flex items-center gap-1.5 text-xs font-medium text-amber-800 bg-amber-100 border border-amber-300 rounded-full px-2.5 py-1 hover:bg-amber-200/70">
                <UserCheck className="w-3.5 h-3.5" /> Not counted — select who counted
              </button>
            )}
          </span>
        </div>
      </td>
    </tr>
  );
}

