              {showMethod && <th className="text-left px-4 py-3 font-medium text-muted-foreground">Source</th>}
              <th className="text-left px-4 py-3 font-medium text-muted-foreground">Type</th>
              <th className="text-left px-4 py-3 font-medium text-muted-foreground">Category</th>
              <th className="text-left px-4 py-3 font-medium text-muted-foreground">Description</th>
              <th className="text-left px-4 py-3 font-medium text-muted-foreground">Bank</th>
              <th className="text-right px-4 py-3 font-medium text-muted-foreground">Income</th>
              <th className="text-right px-4 py-3 font-medium text-muted-foreground">Expense</th>
              <th className="text-right px-4 py-3 font-medium text-muted-foreground">Balance</th>
              {isAdmin && <th className="px-4 py-3"></th>}
            </tr>
          </thead>
          <tbody>
            {filtered.map((e, idx) => {
              const isManual = e.ref_type === 'Adjustment' || e.ref_type === 'CashEntry';
              const isLastOfDay = dayEnd && e.date && (idx === filtered.length - 1 || filtered[idx + 1]?.date !== e.date);
              const colSpan = 8 + (showMethod ? 1 : 0) + (isAdmin ? 1 : 0);
              return (
                <React.Fragment key={e.id}>
                <tr className={`border-t border-border transition-colors ${isManual ? 'bg-amber-50/30 hover:bg-amber-50/60' : 'hover:bg-muted/30'}`}>
                  <td className="px-4 py-3 text-muted-foreground whitespace-nowrap">{e.date ? format(parseISO(e.date), 'dd MMM yyyy') : '-'}</td>
                  {showMethod && (
                    <td className="px-4 py-3">
                      <span className={`text-xs px-2 py-0.5 rounded-full font-medium border ${isManual ? 'bg-amber-50 text-amber-700 border-amber-200' : 'bg-slate-50 text-slate-600 border-slate-200'}`}>
                        {isManual ? '✏ Manual' : `🔒 ${SOURCE_LABELS[e.ref_type] || e.ref_type}`}
                      </span>
                    </td>
                  )}
                  <td className="px-4 py-3"><StatusBadge color={typeColors[e.type]}>{e.type}</StatusBadge></td>
                  <td className="px-4 py-3"><StatusBadge color={catColors[e.category] || 'gray'}>{e.category}</StatusBadge></td>
                  <td className="px-4 py-3 max-w-[220px]">
                    <span className="truncate block" title={e.description}>{e.description}</span>
                    {e.reason && <span className="text-xs text-muted-foreground italic">Note: {e.reason}</span>}
                  </td>
                  <td className="px-4 py-3">
                    {e.received_in_bank_name
                      ? <span className="text-xs font-medium bg-blue-50 text-blue-700 border border-blue-200 px-2 py-0.5 rounded-full whitespace-nowrap">🏦 {e.received_in_bank_name}</span>
                      : <span className="text-muted-foreground">—</span>}
                  </td>
                  <td className="px-4 py-3 text-right text-emerald-600 font-medium">{e.type === 'Income' ? formatCurrency(e.amount) : ''}</td>
                  <td className="px-4 py-3 text-right text-red-600 font-medium">{e.type === 'Expense' ? formatCurrency(e.amount) : ''}</td>
                  <td className={`px-4 py-3 text-right font-bold ${e.running_balance >= 0 ? 'text-emerald-600' : 'text-red-600'}`}>{formatCurrency(e.running_balance)}</td>
                  {isAdmin && (
                    <td className="px-4 py-3">
                      <div className="flex gap-1">
                        <Button variant="ghost" size="sm" onClick={() => handleEntryAction(e, 'edit')} title={isManual ? 'Edit' : 'Locked'}>
                          {isManual ? <Pencil className="w-3.5 h-3.5" /> : <Lock className="w-3.5 h-3.5 opacity-30" />}
                        </Button>
                        <Button variant="ghost" size="sm" className="text-destructive/70 hover:text-destructive" onClick={() => handleEntryAction(e, 'delete')} title={isManual ? 'Delete' : 'Locked'}>
                          {isManual ? <Trash2 className="w-3.5 h-3.5" /> : <Lock className="w-3.5 h-3.5 opacity-30" />}
                        </Button>
                      </div>
                    </td>
                  )}
                </tr>
                {isLastOfDay && (
                  <DayEndCountRow
                    date={e.date}
                    closingBalance={e.running_balance}
                    colSpan={colSpan}
                    count={dayEnd.counts.find(c => c.date === e.date)}
                    knownNames={dayEnd.knownNames}
                    onSave={dayEnd.onSave}
                  />
                )}
                </React.Fragment>
              );
            })}
            {filtered.length === 0 && (
              <tr><td colSpan={isAdmin ? 9 : 8} className="px-4 py-10 text-center text-muted-foreground">No entries found</td></tr>
            )}
            {filtered.length > 0 && (
              <tr className="border-t-2 border-border bg-muted/50 font-bold">
                <td colSpan={showMethod ? (isAdmin ? 6 : 5) : (isAdmin ? 5 : 5)} className="px-4 py-3 text-sm">TOTALS ({filtered.length} entries)</td>
                <td className="px-4 py-3 text-right text-emerald-600">{formatCurrency(totalIncome)}</td>
                <td className="px-4 py-3 text-right text-red-600">{formatCurrency(totalExpense)}</td>
                <td className={`px-4 py-3 text-right ${totalIncome - totalExpense >= 0 ? 'text-emerald-600' : 'text-red-600'}`}>{formatCurrency(totalIncome - totalExpense)}</td>
                {isAdmin && <td />}
              </tr>
            )}
          </tbody>
        </table>
        {dayEnd && (
          <datalist id="day-count-names">
            {dayEnd.knownNames.map(n => <option key={n} value={n} />)}
          </datalist>
        )}
      </div>
    </div>
  );
}

export default function Ledger() {
  const { user, isAdmin } = useRole();
  const queryClient = useQueryClient();
  const { data: rentPayments } = useRentPayments();
  const { data: commissionLedger } = useCommissionLedger();
  const { data: landlordPayouts } = useLandlordPayouts();
  const { data: expenses } = useExpenses();
  const { data: properties } = useProperties();
  const { data: tenants } = useTenants();
  const { data: landlords } = useLandlords();
  const { data: adjustments } = useLedgerAdjustments();
  const { data: cashEntries } = useCashEntries();

  const [tab, setTab] = useState('bank'); // 'bank' | 'cash'
  const [dateFrom, setDateFrom] = useState(() => format(startOfMonth(new Date()), 'yyyy-MM-dd'));
  const [dateTo, setDateTo] = useState('');
  const [showAdjForm, setShowAdjForm] = useState(false);
  const [editingAdj, setEditingAdj] = useState(null);
  const [showCashForm, setShowCashForm] = useState(false);
  const [editingCash, setEditingCash] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(null);
  const [lockedMsg, setLockedMsg] = useState(null);
  const [showCloseModal, setShowCloseModal] = useState(false);

  // All system entries
  // Day-end counts (who counted the cash at the end of each day)
  const { data: dayCounts = [] } = useQuery({
    queryKey: ['ledger_day_counts'],
    queryFn: () => base44.entities.LedgerDayCount.list('-date', 1000),
    placeholderData: [],
  });
  const dayCountNames = useMemo(
    () => [...new Set(dayCounts.map(c => (c.counted_by || '').trim()).filter(Boolean))].sort(),
    [dayCounts]
  );
  const saveDayCount = async (date, counted_by, existing) => {
    if (existing?.id) {
      await base44.entities.LedgerDayCount.update(existing.id, { counted_by });
      await logAction({ user, action: 'update', entityType: 'LedgerDayCount', entityId: existing.id, summary: `Day-end count ${date}: counted by ${counted_by}`, oldValue: existing, newValue: { date, counted_by } });
    } else {
      const created = await base44.entities.LedgerDayCount.create({ date, ledger_type: 'cash', counted_by });
      await logAction({ user, action: 'create', entityType: 'LedgerDayCount', entityId: created.id, summary: `Day-end count ${date}: counted by ${counted_by}`, newValue: { date, counted_by } });
    }
    queryClient.invalidateQueries({ queryKey: ['ledger_day_counts'] });
  };

  const allEntries = useMemo(() => buildLedger({
    rentPayments, commissionLedger, landlordPayouts, expenses, properties, tenants, landlords, adjustments
  }), [rentPayments, commissionLedger, landlordPayouts, expenses, properties, tenants, landlords, adjustments]);

  // Bank ledger: all non-cash, non-commission system entries + manual adjustments
  const bankEntries = useMemo(() => {
    const sysEntries = allEntries.filter(e => {
      if (e.ref_type === 'Commission') return false; // commission is agency-internal, excluded from bank ledger
      if (e.ref_type === 'Adjustment') return true;
      return !CASH_METHODS.has(e.payment_method);
    });
    let bal = 0;
    return sysEntries.map(e => {
      if (e.type === 'Income') bal += e.amount; else bal -= e.amount;
      return { ...e, running_balance: bal };
    });
  }, [allEntries]);

  // Cash ledger: cash rent payments + cash payout entries + CashEntry records
  const cashLedgerEntries = useMemo(() => {
    const cashSystemEntries = allEntries.filter(e =>
      (e.ref_type === 'RentPayment' || e.ref_type === 'LandlordPayout') && CASH_METHODS.has(e.payment_method)
    );
    const manualCash = cashEntries.map(c => ({
      id: `cash-${c.id}`,
      ref_id: c.id,
      ref_type: 'CashEntry',
      date: c.date,
      type: c.type,
      category: c.category || 'Cash',
      description: c.description,
      amount: c.amount,
      notes: c.notes,
      property_id: c.property_id || '',
      landlord_id: c.landlord_id || '',
    }));
    const combined = [...cashSystemEntries, ...manualCash].sort((a, b) => new Date(a.date || 0) - new Date(b.date || 0));
    let bal = 0;
    return combined.map(e => {
      if (e.type === 'Income') bal += e.amount; else bal -= e.amount;
      return { ...e, running_balance: bal };
    });
  }, [allEntries, cashEntries]);

  const applyDateFilter = (entries) => entries.filter(e => {
    if (dateFrom && e.date && e.date < dateFrom) return false;
    if (dateTo && e.date && e.date > dateTo) return false;
    return true;
  });

  const rebalance = (entries) => {
    let bal = 0;
    return entries.map(e => {
      if (e.type === 'Income') bal += e.amount; else bal -= e.amount;
      return { ...e, running_balance: bal };
    });
  };

  const filteredBank = useMemo(() => rebalance(applyDateFilter(bankEntries)), [bankEntries, dateFrom, dateTo]);
  const filteredCash = useMemo(() => rebalance(applyDateFilter(cashLedgerEntries)), [cashLedgerEntries, dateFrom, dateTo]);

  const bankIncome = filteredBank.filter(e => e.type === 'Income').reduce((s, e) => s + e.amount, 0);
  const bankExpense = filteredBank.filter(e => e.type === 'Expense').reduce((s, e) => s + e.amount, 0);
  const cashIncome = filteredCash.filter(e => e.type === 'Income').reduce((s, e) => s + e.amount, 0);
  const cashExpense = filteredCash.filter(e => e.type === 'Expense').reduce((s, e) => s + e.amount, 0);

  const handleBankEntryAction = (entry, action) => {
    if (entry.ref_type !== 'Adjustment') {
      setLockedMsg(`This entry is system-generated from a ${SOURCE_LABELS[entry.ref_type] || entry.ref_type} record. Edit the source record instead.`);
      return;
    }
    if (action === 'edit') { const adj = adjustments.find(a => a.id === entry.ref_id); setEditingAdj(adj); setShowAdjForm(true); }
    else setConfirmDelete({ ...entry, _deleteType: 'adj' });
  };

  const handleCashEntryAction = (entry, action) => {
    if (entry.ref_type !== 'CashEntry') {
      setLockedMsg('This is a system-generated cash rent payment. Edit the rent record instead.');
      return;
    }
    if (action === 'edit') { const ce = cashEntries.find(c => c.id === entry.ref_id); setEditingCash(ce); setShowCashForm(true); }
    else setConfirmDelete({ ...entry, _deleteType: 'cash' });
  };

  const handleAdjSubmit = async (data) => {
    const payload = { ...data, edited_by: user?.email };
    if (editingAdj) {
      await base44.entities.LedgerAdjustment.update(editingAdj.id, payload);
    } else {
      await base44.entities.LedgerAdjustment.create(payload);
    }
    queryClient.invalidateQueries({ queryKey: ['ledger_adjustments'] });
    setShowAdjForm(false); setEditingAdj(null);
  };

  const handleCashSubmit = async (data) => {
    const payload = { ...data, added_by: user?.email };
    if (editingCash) {
      await base44.entities.CashEntry.update(editingCash.id, payload);
    } else {
      await base44.entities.CashEntry.create(payload);
    }
    queryClient.invalidateQueries({ queryKey: ['cash_entries'] });
    setShowCashForm(false); setEditingCash(null);
  };

  const handleConfirmDelete = async () => {
    if (!confirmDelete) return;
    if (confirmDelete._deleteType === 'adj') {
      await base44.entities.LedgerAdjustment.delete(confirmDelete.ref_id);
      queryClient.invalidateQueries({ queryKey: ['ledger_adjustments'] });
    } else if (confirmDelete._deleteType === 'cash') {
      await base44.entities.CashEntry.delete(confirmDelete.ref_id);
      queryClient.invalidateQueries({ queryKey: ['cash_entries'] });
    }
    setConfirmDelete(null);
  };

  return (
    <div>
      <PageHeader
        title="Daily Ledger"
        description="Separate cash and bank ledgers with full transaction history"
        actions={
          <div className="flex gap-2 flex-wrap">
            {tab === 'bank' && (
              <Button variant="outline" onClick={() => exportLedgerToExcel(filteredBank, `Bank_Ledger_${format(new Date(), 'yyyy-MM-dd')}.xlsx`)}>
                <Download className="w-4 h-4 mr-2" />Export Bank Ledger
              </Button>
            )}
            {tab === 'cash' && (
              <Button variant="outline" onClick={() => exportLedgerToExcel(filteredCash, `Cash_Ledger_${format(new Date(), 'yyyy-MM-dd')}.xlsx`)}>
                <Download className="w-4 h-4 mr-2" />Export Cash Ledger
              </Button>
            )}
            {isAdmin && tab === 'bank' && (
              <Button onClick={() => { setEditingAdj(null); setShowAdjForm(true); }}>
                <Plus className="w-4 h-4 mr-2" />Add Adjustment
              </Button>
            )}
            {tab === 'cash' && (
              <Button onClick={() => { setEditingCash(null); setShowCashForm(true); }}>
                <Plus className="w-4 h-4 mr-2" />Add Cash Entry
              </Button>
            )}
            {isAdmin && (
              <Button variant="outline" onClick={() => setShowCloseModal(true)}>
                <Archive className="w-4 h-4 mr-2" />Close Month
              </Button>
            )}
          </div>
        }
      />

      {/* Tab switcher */}
      <div className="flex gap-2 mb-6">
        <button
          onClick={() => setTab('bank')}
          className={`flex items-center gap-2 px-5 py-2.5 rounded-lg text-sm font-semibold transition-colors border ${tab === 'bank' ? 'bg-primary text-primary-foreground border-primary' : 'bg-card text-foreground border-border hover:bg-muted'}`}
        >
          <CreditCard className="w-4 h-4" /> Bank Ledger
        </button>
        <button
          onClick={() => setTab('cash')}
          className={`flex items-center gap-2 px-5 py-2.5 rounded-lg text-sm font-semibold transition-colors border ${tab === 'cash' ? 'bg-primary text-primary-foreground border-primary' : 'bg-card text-foreground border-border hover:bg-muted'}`}
        >
          <Banknote className="w-4 h-4" /> Cash Ledger
        </button>
      </div>

      {/* Summary Cards */}
      {tab === 'bank' && (
        <div className="grid grid-cols-2 lg:grid-cols-3 gap-4 mb-6">
          <StatCard label="Bank Income" value={formatCurrency(bankIncome)} icon={TrendingUp} color="success" />
          <StatCard label="Bank Expense" value={formatCurrency(bankExpense)} icon={TrendingDown} color="destructive" />
          <StatCard label="Bank Net" value={formatCurrency(bankIncome - bankExpense)} icon={DollarSign} color={bankIncome - bankExpense >= 0 ? 'success' : 'destructive'} />
        </div>
      )}
      {tab === 'cash' && (
        <div className="grid grid-cols-2 lg:grid-cols-3 gap-4 mb-6">
          <StatCard label="Cash In" value={formatCurrency(cashIncome)} icon={TrendingUp} color="success" />
          <StatCard label="Cash Out" value={formatCurrency(cashExpense)} icon={TrendingDown} color="destructive" />
          <StatCard label="Cash Balance" value={formatCurrency(cashIncome - cashExpense)} icon={Banknote} color={cashIncome - cashExpense >= 0 ? 'success' : 'destructive'} />
        </div>
      )}

      {/* Date filters */}
      <div className="flex flex-wrap gap-3 mb-5">
        <div className="space-y-1">
          <Label className="text-xs">From</Label>
          <Input type="date" value={dateFrom} onChange={e => setDateFrom(e.target.value)} className="w-36" />
        </div>
        <div className="space-y-1">
          <Label className="text-xs">To</Label>
          <Input type="date" value={dateTo} onChange={e => setDateTo(e.target.value)} className="w-36" />
        </div>
        {(dateFrom || dateTo) && (
          <div className="space-y-1 flex items-end">
            <Button variant="outline" size="sm" onClick={() => { setDateFrom(''); setDateTo(''); }}>Clear</Button>
          </div>
        )}
      </div>

      {tab === 'bank' && (
        <LedgerTable
          filtered={filteredBank}
          isAdmin={isAdmin}
          handleEntryAction={handleBankEntryAction}
          showMethod={true}
        />
      )}
      {tab === 'cash' && (
        <LedgerTable
          filtered={filteredCash}
          isAdmin={isAdmin}
          handleEntryAction={handleCashEntryAction}
          showMethod={false}
          dayEnd={{ counts: dayCounts.filter(c => (c.ledger_type || 'cash') === 'cash'), knownNames: dayCountNames, onSave: saveDayCount }}
        />
      )}

      {/* Bank adjustment dialog */}
      <Dialog open={showAdjForm} onOpenChange={v => { if (!v) { setShowAdjForm(false); setEditingAdj(null); } }}>
        <DialogContent className="max-w-lg">
          <DialogHeader><DialogTitle>{editingAdj ? 'Edit Manual Adjustment' : 'Add Manual Adjustment'}</DialogTitle></DialogHeader>
          <ManualAdjustmentForm adjustment={editingAdj} properties={properties} landlords={landlords} onSubmit={handleAdjSubmit} onCancel={() => { setShowAdjForm(false); setEditingAdj(null); }} />
        </DialogContent>
      </Dialog>

      {/* Cash entry dialog */}
      <Dialog open={showCashForm} onOpenChange={v => { if (!v) { setShowCashForm(false); setEditingCash(null); } }}>
        <DialogContent className="max-w-md">
          <DialogHeader><DialogTitle>{editingCash ? 'Edit Cash Entry' : 'Add Cash Entry'}</DialogTitle></DialogHeader>
          <CashEntryForm entry={editingCash} properties={properties} onSubmit={handleCashSubmit} onCancel={() => { setShowCashForm(false); setEditingCash(null); }} />
        </DialogContent>
      </Dialog>

      {/* Locked message */}
      <Dialog open={!!lockedMsg} onOpenChange={() => setLockedMsg(null)}>
        <DialogContent className="max-w-sm">
          <DialogHeader><DialogTitle>Entry Locked</DialogTitle></DialogHeader>
          <div className="flex items-start gap-3 py-2">
            <Lock className="w-5 h-5 text-muted-foreground mt-0.5 shrink-0" />
            <p className="text-sm text-muted-foreground">{lockedMsg}</p>
          </div>
          <div className="flex justify-end"><Button onClick={() => setLockedMsg(null)}>OK</Button></div>
        </DialogContent>
      </Dialog>

      <ConfirmDialog
        open={!!confirmDelete}
        title="Delete Entry"
        description={`Delete "${confirmDelete?.description}"? This cannot be undone.`}
        onConfirm={handleConfirmDelete}
        onCancel={() => setConfirmDelete(null)}
      />

      <CloseLedgerModal
        open={showCloseModal}
        onClose={() => setShowCloseModal(false)}
        bankEntries={bankEntries}
        cashEntries={cashLedgerEntries}
      />
    </div>
  );
}

import React, { useState } from "react";
import { Link } from "react-router-dom";
import { base44 } from "@/api/base44Client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { LogIn, Mail, Lock, Loader2 } from "lucide-react";
import AuthLayout from "@/components/AuthLayout";
import GoogleIcon from "@/components/GoogleIcon";

export default function Login() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const getRedirectUrl = (user) => {
    const internalRoles = ['admin', 'staff', 'user'];
    return internalRoles.includes(user?.role) ? "/Dashboard" : "/";
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setLoading(true);
    try {
      await base44.auth.loginViaEmailPassword(email, password);
      const user = await base44.auth.me();
      window.location.href = getRedirectUrl(user);
    } catch (err) {
      setError(err.message || "Invalid email or password");
    } finally {
      setLoading(false);
    }
  };

  const handleGoogle = () => {
    base44.auth.loginWithProvider("google", "/Dashboard");
  };

  return (
    <AuthLayout
      icon={LogIn}
      title="Welcome back"
      subtitle="Log in to your account"
      footer={
        <>
          Don't have an account?{" "}
          <Link to="/register" className="text-primary font-medium hover:underline">
            Create one
          </Link>
        </>
      }
    >
      <Button
        variant="outline"
        className="w-full h-12 text-sm font-medium mb-6"
        onClick={handleGoogle}
      >
        <GoogleIcon className="w-5 h-5 mr-2" />
        Continue with Google
      </Button>

      <div className="relative mb-6">
        <div className="absolute inset-0 flex items-center">
          <div className="w-full border-t border-border" />
        </div>
        <div className="relative flex justify-center text-xs uppercase">
          <span className="bg-card px-3 text-muted-foreground">or</span>
        </div>
      </div>

      {error && (
        <div className="mb-4 p-3 rounded-lg bg-destructive/10 text-destructive text-sm">
          {error}
        </div>
      )}

      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="space-y-2">
          <Label htmlFor="email">Email</Label>
          <div className="relative">
            <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" aria-hidden="true" />
            <Input
              id="email"
              type="email"
              autoComplete="email"
              autoFocus
              placeholder="you@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="pl-10 h-12"
              required
            />
          </div>
        </div>
        <div className="space-y-2">
          <div className="flex items-center justify-between">
            <Label htmlFor="password">Password</Label>
            <Link to="/forgot-password" className="text-xs text-primary hover:underline">
              Forgot password?
            </Link>
          </div>
          <div className="relative">
            <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" aria-hidden="true" />
            <Input
              id="password"
              type="password"
              autoComplete="current-password"
              placeholder="••••••••"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="pl-10 h-12"
              required
            />
          </div>
        </div>
        <Button type="submit" className="w-full h-12 font-medium" disabled={loading}>
          {loading ? (
            <>
              <Loader2 className="w-4 h-4 mr-2 animate-spin" />
              Logging in...
            </>
          ) : (
            "Log in"
          )}
        </Button>
      </form>
    </AuthLayout>
  );
}

import React, { useState, useMemo } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { base44 } from '@/api/base44Client';
import { useMaintenanceRequests } from '@/hooks/useMaintenanceRequests';
import { useProperties, useTenants, useLandlords } from '@/hooks/useAllData';
import { useRole } from '@/hooks/useRole';
import { logAction } from '@/lib/audit';
import { notifyMaintenanceRaised } from '@/lib/whatsappAlerts';
import { formatCurrency } from '@/lib/computations';
import PageHeader from '@/components/ui/PageHeader';
import MaintenanceCard from '@/components/maintenance/MaintenanceCard';
import MaintenanceForm from '@/components/maintenance/MaintenanceForm';
import ConfirmDialog from '@/components/ui/ConfirmDialog';
import { StatusBadge, PriorityBadge } from '@/components/maintenance/MaintenanceStatusBadge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import StatCard from '@/components/ui/StatCard';
import { Plus, Search, Wrench, Clock, CheckCircle, AlertTriangle, PoundSterling, Building2, Users, Trash2 } from 'lucide-react';

export default function Maintenance() {
  const { user, isAdmin } = useRole();
  const queryClient = useQueryClient();
  const { data: requests } = useMaintenanceRequests();
  const { data: properties } = useProperties();
  const { data: tenants } = useTenants();
  const { data: landlords } = useLandlords();

  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [priorityFilter, setPriorityFilter] = useState('all');
  const [categoryFilter, setCategoryFilter] = useState('all');
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(null);

  const filtered = useMemo(() => {
    return requests.filter(r => {
      const prop = properties.find(p => p.id === r.property_id);
      const tenant = tenants.find(t => t.id === r.tenant_id);
      const searchMatch = !search ||
        r.title?.toLowerCase().includes(search.toLowerCase()) ||
        prop?.address?.toLowerCase().includes(search.toLowerCase()) ||
        tenant?.name?.toLowerCase().includes(search.toLowerCase()) ||
        r.contractor_name?.toLowerCase().includes(search.toLowerCase());
      const statusMatch = statusFilter === 'all' || r.status === statusFilter;
      const priorityMatch = priorityFilter === 'all' || r.priority === priorityFilter;
      const categoryMatch = categoryFilter === 'all' || r.category === categoryFilter;
      return searchMatch && statusMatch && priorityMatch && categoryMatch;
    });
  }, [requests, properties, tenants, search, statusFilter, priorityFilter, categoryFilter]);

  const syncLinkedRecords = async (reqData, existingReq = null) => {
    const cost = reqData.actual_cost || reqData.estimated_cost || 0;
    const prevCharged = existingReq?.charge_to_landlord;
    const nowCharged = reqData.charge_to_landlord;
    const prevExpenseId = existingReq?.linked_expense_id;
    const prevExtraId = existingReq?.linked_extra_id;
    const dateRef = reqData.resolved_date || reqData.scheduled_date || new Date().toISOString().slice(0, 10);

    let newExpenseId = prevExpenseId || null;
    let newExtraId = prevExtraId || null;

    if (prevCharged && !nowCharged) {
      // Switching OFF — delete old expense and extra
      if (prevExpenseId) { await base44.entities.Expense.delete(prevExpenseId); newExpenseId = null; }
      if (prevExtraId) { await base44.entities.PaymentExtra.delete(prevExtraId); newExtraId = null; }
    } else if (nowCharged && cost > 0) {
      // Create or update Expense
      const expensePayload = {
        property_id: reqData.property_id,
        landlord_id: reqData.landlord_id,
        date: dateRef,
        category: 'maintenance',
        description: reqData.title,
        amount: cost,
        paid_by: 'landlord',
        notes: 'Auto-linked from maintenance request',
      };
      if (prevExpenseId && prevCharged) {
        await base44.entities.Expense.update(prevExpenseId, expensePayload);
      } else {
        const exp = await base44.entities.Expense.create(expensePayload);
        newExpenseId = exp.id;
      }

      // Create or update PaymentExtra (deduction on landlord payments page)
      const extraPayload = {
        landlord_id: reqData.landlord_id,
        property_id: reqData.property_id,
        description: `Maintenance: ${reqData.title}`,
        amount: cost,
        date: dateRef,
        category: 'maintenance',
        notes: 'Auto-created from maintenance request',
      };
      if (prevExtraId && prevCharged) {
        await base44.entities.PaymentExtra.update(prevExtraId, extraPayload);
      } else {
        const extra = await base44.entities.PaymentExtra.create(extraPayload);
        newExtraId = extra.id;
      }
    }

    queryClient.invalidateQueries({ queryKey: ['expenses'] });
    queryClient.invalidateQueries({ queryKey: ['payment_extras'] });
    return { newExpenseId, newExtraId };
  };

  const handleSubmit = async (data) => {
    const { newExpenseId, newExtraId } = await syncLinkedRecords(data, editing);
    const saveData = { ...data, linked_expense_id: newExpenseId || '', linked_extra_id: newExtraId || '' };

    if (editing) {
      await base44.entities.MaintenanceRequest.update(editing.id, saveData);
      await logAction({ user, action: 'update', entityType: 'MaintenanceRequest', entityId: editing.id, summary: `Updated maintenance request: ${data.title}`, oldValue: editing, newValue: saveData });
    } else {
      const created = await base44.entities.MaintenanceRequest.create(saveData);
      await logAction({ user, action: 'create', entityType: 'MaintenanceRequest', entityId: created.id, summary: `Created maintenance request: ${data.title}`, newValue: saveData });
      notifyMaintenanceRaised({
        request: saveData,
        property: properties.find(p => p.id === saveData.property_id),
        tenant: tenants.find(t => t.id === saveData.tenant_id),
        raisedBy: user?.full_name || user?.email,
      });
    }
    queryClient.invalidateQueries({ queryKey: ['maintenance_requests'] });
    setShowForm(false);
    setEditing(null);
  };

  const handleDelete = async (req) => {
    if (req.charge_to_landlord) {
      if (req.linked_expense_id) {
        try {
          await base44.entities.Expense.delete(req.linked_expense_id);
        } catch (err) {
          // Silently ignore if expense doesn't exist
        }
      }
      if (req.linked_extra_id) {
        try {
          await base44.entities.PaymentExtra.delete(req.linked_extra_id);
        } catch (err) {
          // Silently ignore if payment extra doesn't exist
        }
      }
      queryClient.invalidateQueries({ queryKey: ['expenses'] });
      queryClient.invalidateQueries({ queryKey: ['payment_extras'] });
    }
    await base44.entities.MaintenanceRequest.delete(req.id);
    await logAction({ user, action: 'delete', entityType: 'MaintenanceRequest', entityId: req.id, summary: `Deleted maintenance request: ${req.title}`, oldValue: req });
    queryClient.invalidateQueries({ queryKey: ['maintenance_requests'] });
    setConfirmDelete(null);
  };

  const handleEdit = (req) => {
    setEditing(req);
    setShowForm(true);
  };

  const handleClose = () => {
    setShowForm(false);
    setEditing(null);
  };

  const pending = requests.filter(r => r.status === 'pending').length;
  const inProgress = requests.filter(r => r.status === 'in_progress').length;
  const resolved = requests.filter(r => r.status === 'resolved').length;
  const emergencies = requests.filter(r => r.priority === 'emergency' && r.status !== 'resolved' && r.status !== 'cancelled').length;

  const totalCost = requests.reduce((s, r) => s + (r.actual_cost || r.estimated_cost || 0), 0);
  const chargedToLandlord = requests.filter(r => r.charge_to_landlord).reduce((s, r) => s + (r.actual_cost || r.estimated_cost || 0), 0);
  const agencyCost = requests.filter(r => !r.charge_to_landlord && r.cost_bearer !== 'tenant').reduce((s, r) => s + (r.actual_cost || r.estimated_cost || 0), 0);

  return (
    <div>
      <PageHeader
        title="Maintenance"
        description="Track and manage property maintenance requests"
        actions={
          <Button onClick={() => { setEditing(null); setShowForm(true); }}>
            <Plus className="w-4 h-4 mr-2" />New Request
          </Button>
        }
      />

      {/* Stats */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-4">
        <StatCard label="Pending" value={pending} icon={Clock} color="warning" />
        <StatCard label="In Progress" value={inProgress} icon={Wrench} color="primary" />
        <StatCard label="Resolved" value={resolved} icon={CheckCircle} color="success" />
        <StatCard label="Emergencies" value={emergencies} icon={AlertTriangle} color="destructive" />
      </div>
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-6">
        <StatCard label="Total Maintenance Cost" value={formatCurrency(totalCost)} icon={PoundSterling} />
        <StatCard label="Charged to Landlords" value={formatCurrency(chargedToLandlord)} icon={Building2} color="warning" trend="Deducted from payouts" />
        <StatCard label="Agency-Covered Cost" value={formatCurrency(agencyCost)} icon={Users} color="primary" trend="Not on landlord statement" />
      </div>

      {/* Filters */}
      <div className="flex flex-wrap gap-3 mb-5">
        <div className="relative flex-1 min-w-[200px]">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input className="pl-9" placeholder="Search requests..." value={search} onChange={e => setSearch(e.target.value)} />
        </div>
        <Select value={statusFilter} onValueChange={setStatusFilter}>
          <SelectTrigger className="w-36"><SelectValue placeholder="Status" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Statuses</SelectItem>
            <SelectItem value="pending">Pending</SelectItem>
            <SelectItem value="in_progress">In Progress</SelectItem>
            <SelectItem value="resolved">Resolved</SelectItem>
            <SelectItem value="cancelled">Cancelled</SelectItem>
          </SelectContent>
        </Select>
        <Select value={priorityFilter} onValueChange={setPriorityFilter}>
          <SelectTrigger className="w-36"><SelectValue placeholder="Priority" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Priorities</SelectItem>
            <SelectItem value="emergency">Emergency</SelectItem>
            <SelectItem value="high">High</SelectItem>
            <SelectItem value="medium">Medium</SelectItem>
            <SelectItem value="low">Low</SelectItem>
          </SelectContent>
        </Select>
        <Select value={categoryFilter} onValueChange={setCategoryFilter}>
          <SelectTrigger className="w-40"><SelectValue placeholder="Category" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Categories</SelectItem>
            {['plumbing','electrical','heating','structural','appliances','pest_control','cleaning','other'].map(c => (
              <SelectItem key={c} value={c}>{c.replace('_', ' ')}</SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      {/* Cards Grid */}
      {filtered.length === 0 ? (
        <div className="text-center py-16 text-muted-foreground">
          <Wrench className="w-10 h-10 mx-auto mb-3 opacity-30" />
          <p className="text-sm">No maintenance requests found</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
          {filtered.map(req => (
            <div key={req.id} className="relative">
              <MaintenanceCard
                request={req}
                property={properties.find(p => p.id === req.property_id)}
                tenant={tenants.find(t => t.id === req.tenant_id)}
                onEdit={handleEdit}
              />
              {isAdmin && (
                <button
                  onClick={() => setConfirmDelete(req)}
                  className="absolute top-3 right-3 p-1.5 rounded-md text-muted-foreground hover:text-destructive hover:bg-destructive/10 transition-colors"
                  title="Delete request"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              )}
            </div>
          ))}
          </div>
          )}

          {/* Dialog */}
      <Dialog open={showForm} onOpenChange={handleClose}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{editing ? 'Manage Request' : 'New Maintenance Request'}</DialogTitle>
          </DialogHeader>
          <MaintenanceForm
            request={editing}
            properties={properties}
            tenants={tenants}
            landlords={landlords}
            onSubmit={handleSubmit}
            onCancel={handleClose}
            isAdminForm={true}
          />
        </DialogContent>
      </Dialog>

      <ConfirmDialog
        open={!!confirmDelete}
        title="Delete Maintenance Request"
        description={`Delete "${confirmDelete?.title}"? This is permanent.`}
        onConfirm={() => handleDelete(confirmDelete)}
        onCancel={() => setConfirmDelete(null)}
      />
    </div>

  );
}

import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { base44 } from "@/api/base44Client";
import { useToast } from "@/components/ui/use-toast";
import StepIndicator from "@/components/documents/StepIndicator";
import UploadStep from "@/components/documents/UploadStep";
import SignersStep from "@/components/documents/SignersStep";
import FieldsStep from "@/components/documents/FieldsStep";
import ReviewStep from "@/components/documents/ReviewStep";
import { getSignerColor } from "@/lib/signerColors";
import { businessConfig as biz } from "@/lib/businessConfig";

export default function NewDocument() {
  const navigate = useNavigate();
  const { toast } = useToast();
  const [step, setStep] = useState(1);
  const [sending, setSending] = useState(false);

  const [documentData, setDocumentData] = useState({
    title: "",
    original_file_url: null,
    fileName: null,
    pageCount: 3,
  });

  const [signersList, setSignersList] = useState([
    { name: "", email: "", role_label: "", signing_order: 1 },
  ]);

  const [fieldsList, setFieldsList] = useState([]);
  const [message, setMessage] = useState("");

  const saveDocument = async (status) => {
    setSending(true);
    try {
      // Create document
      const doc = await base44.entities.Document.create({
        title: documentData.title,
        original_file_url: documentData.original_file_url,
        status,
        message,
        page_count: documentData.pageCount || 1,
        sent_at: status === "sent" ? new Date().toISOString() : undefined,
      });

      // Create signers
      const createdSigners = [];
      for (let i = 0; i < signersList.length; i++) {
        const s = signersList[i];
        const color = getSignerColor(i);
        const token = crypto.randomUUID();
        const signer = await base44.entities.Signer.create({
          document_id: doc.id,
          name: s.name,
          email: s.email,
          role_label: s.role_label,
          signing_order: s.signing_order || i + 1,
          status: "pending",
          access_token: token,
          color: color.hex,
        });
        createdSigners.push(signer);
      }

      // Create fields
      for (const field of fieldsList) {
        const signer = createdSigners[field._signerIndex];
        if (!signer) continue;
        await base44.entities.SignatureField.create({
          document_id: doc.id,
          signer_id: signer.id,
          type: field.type,
          page: field.page,
          x: field.x,
          y: field.y,
          width: field.width,
          height: field.height,
          required: field.required ?? true,
        });
      }

      // Create audit event
      await base44.entities.AuditEvent.create({
        document_id: doc.id,
        event_type: "created",
      });

      // If sending, trigger email notifications
      if (status === "sent") {
        await base44.entities.AuditEvent.create({
          document_id: doc.id,
          event_type: "sent",
        });

        // Send email to signers via backend function
        const emailResponse = await base44.functions.invoke('sendSignerInvites', {
          documentId: doc.id,
          title: documentData.title,
          message,
          appUrl: window.location.origin,
          fromName: biz.name,
          signers: createdSigners.map((s) => ({
            name: s.name,
            email: s.email,
            access_token: s.access_token,
          })),
        });

        const failed = emailResponse.data?.results?.filter((r) => r.status === 'failed') || [];
        if (failed.length > 0) {
          toast({
            title: "Document sent with warnings",
            description: `${failed.length} email(s) failed to send.`,
            variant: "destructive",
          });
        } else {
          toast({ title: "Document sent!", description: "Signing invitations have been emailed.", duration: 3000 });
        }
      } else {
        toast({ title: "Draft saved" });
      }

      navigate(`/documents/${doc.id}`);
    } catch (err) {
      toast({ title: "Error", description: err.message, variant: "destructive" });
    } finally {
      setSending(false);
    }
  };

  return (
    <div>
      <StepIndicator currentStep={step} />

      {step === 1 && (
        <UploadStep
          documentData={documentData}
          setDocumentData={setDocumentData}
          onNext={() => setStep(2)}
        />
      )}

      {step === 2 && (
        <SignersStep
          signersList={signersList}
          setSignersList={setSignersList}
          onNext={() => setStep(3)}
          onBack={() => setStep(1)}
        />
      )}

      {step === 3 && (
        <FieldsStep
          documentData={documentData}
          signersList={signersList}
          fieldsList={fieldsList}
          setFieldsList={setFieldsList}
          onNext={() => setStep(4)}
          onBack={() => setStep(2)}
        />
      )}

      {step === 4 && (
        <ReviewStep
          documentData={documentData}
          signersList={signersList}
          fieldsList={fieldsList}
          message={message}
          setMessage={setMessage}
          onSend={() => saveDocument("sent")}
          onSaveDraft={() => saveDocument("draft")}
          onBack={() => setStep(3)}
          sending={sending}
        />
      )}
    </div>
  );
}

