// Upsert a RentPayment record for this tenant/month.
// Tagged with notes='__from_notifications__' so we can find & update it next time.
async function syncRentPayment(tenant, month, rentValueStr, bankName, paidDateStr, method, paidBy) {
  const amount = parseFloat(rentValueStr);
  if (!amount || Number.isNaN(amount) || amount <= 0) return;

  let paymentDate = `${month}-01`;
  if (paidDateStr && /^\d{2}\/\d{2}\/\d{4}$/.test(paidDateStr)) {
    const [dd, mm, yyyy] = paidDateStr.split('/');
    paymentDate = `${yyyy}-${mm}-${dd}`;
  }
  const isCash = method === 'cash';

  const existing = await base44.entities.RentPayment.filter({
    tenant_id: tenant.id,
    period_month: month,
    notes: '__from_notifications__',
  });

  const payload = {
    tenant_id: tenant.id,
    property_id: tenant.property_id,
    landlord_id: tenant.landlord_id || '',
    amount,
    payment_date: paymentDate,
    period_month: month,
    method: isCash ? 'cash' : 'bank_transfer',
    received_in_bank_name: isCash ? '' : (bankName || ''),
    reference: isCash ? (paidBy || '') : '',
    notes: '__from_notifications__',
  };

  if (existing && existing.length > 0) {
    await base44.entities.RentPayment.update(existing[0].id, payload);
  } else {
    await base44.entities.RentPayment.create(payload);
  }
}

