}

// Mark Paid toggle — shows a date picker popup before saving.
function MarkTenantPaidButton({ tenant, month, onSaved, autoReceived, paidAmount, paidInfo, prevMonthMissing, prevMonthLabel }) {
  const [saving, setSaving] = useState(false);
  const [showDatePicker, setShowDatePicker] = useState(false);
  const [pickedDate, setPickedDate] = useState(format(new Date(), 'yyyy-MM-dd'));
  const [payMethod, setPayMethod] = useState('bank'); // 'bank' | 'cash'
  const [cashName, setCashName] = useState('');
  const prevWarnedRef = React.useRef(false);
  const arr = Array.isArray(tenant.monthly_notes) ? tenant.monthly_notes : [];
  const entry = arr.find((e) => e.month === month) || {};
  const serverIsPaid = !!entry.manually_paid;
  const [isPaid, setIsPaid] = useState(serverIsPaid);
  const [paidDate, setPaidDate] = useState(entry.paid_date || null);

  // Sync with server state when tenant prop changes
  useEffect(() => {
    const a = Array.isArray(tenant.monthly_notes) ? tenant.monthly_notes : [];
    const e = a.find((x) => x.month === month) || {};
    const bankIsCash = String(e.bank || '').trim().toLowerCase() === 'cash';
    setIsPaid(!!e.manually_paid);
    setPaidDate(e.paid_date || null);
    setPayMethod(e.paid_method || (bankIsCash ? 'cash' : 'bank'));
    setCashName(e.paid_by || '');
  }, [tenant.monthly_notes, month]);

  const confirmMark = async () => {
    if (!month) return;
    const currentEntry = (Array.isArray(tenant.monthly_notes) ? tenant.monthly_notes : []).find((e) => e.month === month) || {};
    if (!currentEntry.value) {
      alert('Please fill in "Rent Received" before marking as received.');
      return;
    }
    if (payMethod === 'bank' && !currentEntry.bank) {
      alert('Please select a Bank, or switch to Cash.');
      return;
    }
    if (payMethod === 'cash' && !cashName.trim()) {
      alert('Please enter who the cash was received from.');
      return;
    }
    // One-time heads-up: recording this month while LAST month has nothing
    // recorded (and the tenant was due then) — catches recording against the
    // wrong month. If they confirm, we proceed and don't ask again this session.
    if (prevMonthMissing && !prevWarnedRef.current) {
      prevWarnedRef.current = true;
      const proceed = window.confirm(
        `Heads up: nothing is recorded for ${tenant.name} in ${prevMonthLabel}.\n\n` +
        `You're about to record rent for the current month. If this payment was actually for ${prevMonthLabel}, ` +
        `switch to that month's tab and record it there instead.\n\nRecord it for the current month anyway?`
      );
      if (!proceed) return;
    }
    const newDate = format(new Date(pickedDate + 'T00:00:00'), 'dd/MM/yyyy');
    const effMethod = (payMethod === 'cash' || String(currentEntry.bank || '').trim().toLowerCase() === 'cash') ? 'cash' : 'bank';
    setIsPaid(true);
    setPaidDate(newDate);
    setSaving(true);
    setShowDatePicker(false);
    try {
      const updatedEntry = { ...entry, month, manually_paid: true, paid_date: newDate, paid_method: effMethod, ...(effMethod === 'cash' ? { paid_by: cashName.trim() } : {}) };
      const next = [...arr.filter((e) => e.month !== month), updatedEntry];
      await base44.entities.Tenant.update(tenant.id, { monthly_notes: next });
      // Only sync RentPayment when marking as received
      if (updatedEntry.value) {
        await syncRentPayment(tenant, month, updatedEntry.value, updatedEntry.bank || '', newDate, effMethod, effMethod === 'cash' ? cashName.trim() : '');
      }
      onSaved && await onSaved();
    } catch (e) {
      setIsPaid(false);
      setPaidDate(null);
      alert(`Could not save: ${e.message || e}`);
    } finally { setSaving(false); }
  };

  const unmark = async () => {
    if (!month) return;
    setIsPaid(false);
    setPaidDate(null);
    setSaving(true);
    try {
      const next = [...arr.filter((e) => e.month !== month), { ...entry, month, manually_paid: false, paid_date: null }];
      await base44.entities.Tenant.update(tenant.id, { monthly_notes: next });
      // Delete the RentPayment record created from notifications
      const existing = await base44.entities.RentPayment.filter({
        tenant_id: tenant.id,
        period_month: month,
        notes: '__from_notifications__',
      });
      await Promise.all((existing || []).map((p) => base44.entities.RentPayment.delete(p.id)));
      onSaved && await onSaved();
    } catch (e) {
      setIsPaid(true);
      setPaidDate(entry.paid_date || null);
      alert(`Could not save: ${e.message || e}`);
    } finally { setSaving(false); }
  };

  if (isPaid || autoReceived || paidAmount > 0) {
    const auto = !isPaid && (autoReceived || paidAmount > 0);
    return (
      <div className="inline-flex flex-col items-center gap-0.5">
        <button onClick={auto ? undefined : unmark} disabled={saving || auto}
          className={`inline-flex items-center gap-1 px-3 py-1.5 rounded-md text-xs font-semibold disabled:opacity-100 ${auto ? 'bg-emerald-50 text-emerald-700 cursor-default' : 'bg-emerald-100 text-emerald-700 hover:bg-emerald-200'}`}
          title={auto ? 'Received via a recorded payment (e.g. from the property\'s Rent or Pay Landlord screen)' : 'Click to mark as not received'}>
          <CheckCircle className="w-3.5 h-3.5" /> Received
        </button>
        {auto ? (
          <span className="flex flex-col items-center leading-tight">
            <span className="text-[10px] text-muted-foreground">via payment</span>
            {paidInfo?.bank && paidInfo.method !== 'cash' && (
              <span className="text-[10px] px-1.5 py-0.5 rounded font-medium bg-blue-100 text-blue-700">🏦 {paidInfo.bank}</span>
            )}
            {paidInfo?.method === 'cash' && (
              <span className="text-[10px] px-1.5 py-0.5 rounded font-medium bg-amber-100 text-amber-700">Cash</span>
            )}
            {paidInfo?.date && <span className="text-[10px] text-muted-foreground">{format(parseISO(paidInfo.date), 'd MMM yyyy')}</span>}
          </span>
        ) : (
          <>
            <span className={`text-[10px] px-1.5 py-0.5 rounded font-medium ${payMethod === 'cash' ? 'bg-amber-100 text-amber-700' : 'bg-blue-100 text-blue-700'}`}>
              {payMethod === 'cash' ? 'Cash' : 'Bank'}
            </span>
            {payMethod === 'cash' && entry.paid_by && <span className="text-[10px] text-muted-foreground whitespace-nowrap">{entry.paid_by}</span>}
            {paidDate && <span className="text-xs text-muted-foreground whitespace-nowrap">{paidDate}</span>}
          </>
        )}
      </div>
    );
  }

  return (
    <div className="relative inline-block">
      {showDatePicker && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 p-4" onClick={() => setShowDatePicker(false)}>
          <div className="bg-card border border-border rounded-xl shadow-xl p-5 w-full max-w-xs" onClick={(e) => e.stopPropagation()}>
            <p className="text-sm font-semibold mb-1">Record rent received</p>
            <p className="text-xs text-muted-foreground mb-3">{tenant.name}{tenant.property_address ? ` · ${tenant.property_address}` : ''}</p>
            <label className="block text-xs font-medium text-muted-foreground mb-1">Method</label>
            <div className="flex gap-1 p-0.5 bg-muted rounded-lg mb-3">
              <button onClick={() => setPayMethod('bank')}
                className={`flex-1 text-sm font-semibold py-2 rounded-md transition-colors ${payMethod === 'bank' ? 'bg-white shadow text-foreground' : 'text-muted-foreground'}`}>
                Bank
              </button>
              <button onClick={() => setPayMethod('cash')}
                className={`flex-1 text-sm font-semibold py-2 rounded-md transition-colors ${payMethod === 'cash' ? 'bg-white shadow text-emerald-700' : 'text-muted-foreground'}`}>
                Cash
              </button>
            </div>
            {payMethod === 'cash' && <p className="text-[11px] text-emerald-700 bg-emerald-50 rounded px-2 py-1.5 mb-3">Recorded as cash in the ledger.</p>}
            {payMethod === 'cash' && (
              <div className="mb-3">
                <label className="block text-xs font-medium text-muted-foreground mb-1">Cash received from (name) *</label>
                <input type="text" value={cashName} onChange={(e) => setCashName(e.target.value)}
                  placeholder="Who handed over the cash?" autoFocus
                  className="w-full text-sm border border-input rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-primary" />
              </div>
            )}
            <label className="block text-xs font-medium text-muted-foreground mb-1">Payment date</label>
            <input
              type="date"
              value={pickedDate}
              onChange={(e) => setPickedDate(e.target.value)}
              className="w-full text-sm border border-input rounded-md px-3 py-2 mb-4 focus:outline-none focus:ring-2 focus:ring-primary"
            />
            <div className="flex gap-2">
              <button onClick={confirmMark} disabled={saving || (payMethod === 'cash' && !cashName.trim())}
                className="flex-1 px-3 py-2 rounded-md bg-emerald-600 text-white text-sm font-semibold hover:bg-emerald-700 disabled:opacity-50">
                {saving ? 'Saving…' : 'Save'}
              </button>
              <button onClick={() => setShowDatePicker(false)}
                className="flex-1 px-3 py-2 rounded-md bg-muted text-muted-foreground text-sm hover:bg-muted/80">
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
      <Button size="sm" onClick={() => { setPickedDate(format(new Date(), 'yyyy-MM-dd')); setShowDatePicker(true); }} disabled={saving} className="bg-emerald-600 hover:bg-emerald-700">
        Mark Received
      </Button>
    </div>
  );
}

// Dedicated bank cell — dropdown select from Bank records.
function BankCell({ tenant, month, onSaved, banks = [] }) {
  const getVal = () => {
    const a = Array.isArray(tenant.monthly_notes) ? tenant.monthly_notes : [];
    return (a.find((e) => e && e.month === month) || {}).bank || '';
  };
  const [value, setValue] = useState(getVal);
  const [committed, setCommitted] = useState(getVal);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    const v = getVal();
    setValue(v);
    setCommitted(v);
  }, [month, tenant.id]);

  const handleChange = async (newVal) => {
    setValue(newVal);
    if (!month) return;
    setSaving(true);
    try {
      const notes = Array.isArray(tenant.monthly_notes) ? [...tenant.monthly_notes] : [];
      const idx = notes.findIndex((e) => e && e.month === month);
      if (idx >= 0) notes[idx] = { ...notes[idx], bank: newVal };
      else notes.push({ month, bank: newVal });
      await base44.entities.Tenant.update(tenant.id, { monthly_notes: notes });
      setCommitted(newVal);
      onSaved && onSaved();
    } catch (e) { alert(`Could not save: ${e.message || e}`); setValue(committed); }
    finally { setSaving(false); }
  };

  return (
    <select value={value} onChange={(e) => handleChange(e.target.value)} disabled={saving}
      className="w-36 px-2 py-1.5 text-sm border border-input rounded-md bg-background focus:outline-none focus:ring-2 focus:ring-primary disabled:opacity-50">
