    </select>
  );
}

// Dedicated value/record-rent cell — saves to monthly_notes AND creates/updates a RentPayment.
function ValueCell({ tenant, month, onSaved }) {
  const getVal = () => {
    const a = Array.isArray(tenant.monthly_notes) ? tenant.monthly_notes : [];
    return (a.find((e) => e && e.month === month) || {}).value || '';
  };
  const [value, setValue] = useState(getVal);
  const [committed, setCommitted] = useState(getVal);
  const [saving, setSaving] = useState(false);

  // Only sync from server when the month changes (not after every refetch)
  useEffect(() => {
    const v = getVal();
    setValue(v);
    setCommitted(v);
  }, [month, tenant.id]);

  const dirty = value !== committed;

  const handleSave = async () => {
    if (!dirty || !month) return;
    setSaving(true);
    const saved = value;
    try {
      const notes = Array.isArray(tenant.monthly_notes) ? [...tenant.monthly_notes] : [];
      const idx = notes.findIndex((e) => e && e.month === month);
      if (idx >= 0) notes[idx] = { ...notes[idx], value: saved };
      else notes.push({ month, value: saved });
      await base44.entities.Tenant.update(tenant.id, { monthly_notes: notes });
      setCommitted(saved);
      onSaved && onSaved();
    } catch (e) { alert(`Could not save: ${e.message || e}`); setValue(committed); }
    finally { setSaving(false); }
  };

  const handleKey = (e) => {
    if (e.key === 'Enter') { e.preventDefault(); handleSave(); e.target.blur(); }
    else if (e.key === 'Escape') setValue(committed);
  };

  return (
    <input type="text" value={value} onChange={(e) => setValue(e.target.value)}
      onBlur={() => handleSave()} onKeyDown={handleKey} placeholder="Rent Received…" disabled={saving}
      className="w-40 px-2 py-1.5 text-sm border border-input rounded-md focus:outline-none focus:ring-2 focus:ring-primary disabled:opacity-50"
