// Extra payment lines for a tenant/month.
// Also creates a separate RentPayment per extra line (tagged __from_notifications_extra_N__).
function ExtraPaymentLines({ tenant, month, onSaved, banks = [] }) {
  const getLines = () => {
    const a = Array.isArray(tenant.monthly_notes) ? tenant.monthly_notes : [];
    const e = a.find((x) => x && x.month === month) || {};
    return Array.isArray(e.extra_lines) ? e.extra_lines : [];
  };
  const serverLines = getLines();
  const [lines, setLines] = useState(serverLines);
  const [saving, setSaving] = useState(false);

  useEffect(() => { setLines(getLines()); }, [month, tenant.id, serverLines.length]);

  const persist = async (nextLines) => {
    setSaving(true);
    try {
      const next = Array.isArray(tenant.monthly_notes) ? [...tenant.monthly_notes] : [];
      const idx = next.findIndex((e) => e && e.month === month);
      if (idx >= 0) next[idx] = { ...next[idx], extra_lines: nextLines };
      else next.push({ month, extra_lines: nextLines });
      await base44.entities.Tenant.update(tenant.id, { monthly_notes: next });
      onSaved && onSaved();
    } catch (e) { alert(`Could not save: ${e.message || e}`); setLines(getLines()); }
    finally { setSaving(false); }
  };

  const updateLine = (i, field, val) =>
    setLines((prev) => prev.map((l, idx) => (idx === i ? { ...l, [field]: val } : l)));
  const saveLines = () => persist(lines);
  const removeLine = (i) => {
    if (!window.confirm('Remove this payment line?')) return;
    const nl = lines.filter((_, idx) => idx !== i); setLines(nl); persist(nl);
  };

  const [pickerLine, setPickerLine] = useState(null);
  const [pickedDate, setPickedDate] = useState(format(new Date(), 'yyyy-MM-dd'));
  const [cashName, setCashName] = useState('');
  const openPicker = (i) => { setPickedDate(format(new Date(), 'yyyy-MM-dd')); setCashName(lines[i]?.paid_by || ''); setPickerLine(i); };
  const markReceived = async (i) => {
    const line0 = lines[i] || {};
    if (line0.method === 'cash' && !cashName.trim()) {
      alert('Please enter who the cash was received from.');
      return;
    }
    const newDate = format(new Date(pickedDate + 'T00:00:00'), 'dd/MM/yyyy');
    const nl = lines.map((l, idx) => (idx === i ? { ...l, manually_paid: true, paid_date: newDate, ...(l.method === 'cash' ? { paid_by: cashName.trim() } : {}) } : l));
    setLines(nl); setPickerLine(null);
    await persist(nl);
    // Sync RentPayment only when marking received
    const line = nl[i];
    if (line.value) {
      const tag = `__from_notifications_extra_${i}__`;
      await syncExtraRentPayment(tenant, month, line.value, line.bank || '', newDate, tag, line.method || 'bank', line.method === 'cash' ? cashName.trim() : '');
    }
  };
  const unmarkReceived = async (i) => {
    const nl = lines.map((l, idx) => (idx === i ? { ...l, manually_paid: false, paid_date: null } : l));
    setLines(nl);
    await persist(nl);
    // Delete the extra RentPayment record for this line
    const tag = `__from_notifications_extra_${i}__`;
    const existing = await base44.entities.RentPayment.filter({
      tenant_id: tenant.id,
      period_month: month,
      notes: tag,
    });
    await Promise.all((existing || []).map((p) => base44.entities.RentPayment.delete(p.id)));
  };

  const onKey = (e) => { if (e.key === 'Enter') { e.preventDefault(); e.target.blur(); } };

  if (lines.length === 0) return null;

  return lines.map((line, i) => (
    <tr key={`extra-${tenant.id}-${month}-${i}`} className="border-t border-dashed border-border bg-muted/20">
      <td className="px-4 py-2"></td>
      <td className="px-4 py-2 pl-8 text-xs text-muted-foreground whitespace-nowrap">↳ extra payment</td>
      <td className="px-4 py-2"></td>
      <td className="px-4 py-2"></td>
      <td className="px-4 py-2"></td>
      <td className="px-4 py-2"></td>
      <td className="px-4 py-2">
        <select value={line.bank || ''} onChange={(e) => { updateLine(i, 'bank', e.target.value); persist(lines.map((l, idx) => idx === i ? { ...l, bank: e.target.value } : l)); }}
          disabled={saving}
          className="w-36 px-2 py-1.5 text-sm border border-input rounded-md bg-background focus:outline-none focus:ring-2 focus:ring-primary disabled:opacity-50">
          <option value="">— Select bank —</option>
          {banks.map((b) => <option key={b.id} value={b.name}>{b.name}</option>)}
        </select>
      </td>
      <td className="px-4 py-2">
        <input type="text" value={line.value || ''} onChange={(e) => updateLine(i, 'value', e.target.value)}
          onBlur={saveLines} onKeyDown={onKey} placeholder="Rent received…" disabled={saving}
          className="w-40 px-2 py-1.5 text-sm border border-input rounded-md focus:outline-none focus:ring-2 focus:ring-primary disabled:opacity-50" />
      </td>
      <td className="px-4 py-2">
        <input type="text" value={line.notes || ''} onChange={(e) => updateLine(i, 'notes', e.target.value)}
          onBlur={saveLines} onKeyDown={onKey} placeholder="Notes…" disabled={saving}
          className="w-40 px-2 py-1.5 text-sm border border-input rounded-md focus:outline-none focus:ring-2 focus:ring-primary disabled:opacity-50" />
      </td>
      <td className="px-4 py-2 text-center">
        {line.manually_paid ? (
          <div className="inline-flex flex-col items-center gap-0.5">
            <button onClick={() => unmarkReceived(i)} disabled={saving}
              className="inline-flex items-center gap-1 px-3 py-1.5 rounded-md bg-emerald-100 text-emerald-700 text-xs font-semibold hover:bg-emerald-200 disabled:opacity-50"
              title="Click to mark as not received">
              <CheckCircle className="w-3.5 h-3.5" /> Received
            </button>
            <span className={`text-[10px] px-1.5 py-0.5 rounded font-medium ${line.method === 'cash' ? 'bg-amber-100 text-amber-700' : 'bg-blue-100 text-blue-700'}`}>
              {line.method === 'cash' ? 'Cash' : 'Bank'}
            </span>
            {line.method === 'cash' && line.paid_by && <span className="text-[10px] text-muted-foreground whitespace-nowrap">{line.paid_by}</span>}
            {line.paid_date && <span className="text-xs text-muted-foreground whitespace-nowrap">{line.paid_date}</span>}
          </div>
        ) : (
          <div className="relative inline-block">
            {pickerLine === i && (
              <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 p-4" onClick={() => setPickerLine(null)}>
                <div className="bg-card border border-border rounded-xl shadow-xl p-5 w-full max-w-xs" onClick={(e) => e.stopPropagation()}>
                  <p className="text-sm font-semibold mb-3">Record extra payment</p>
                  <label className="block text-xs font-medium text-muted-foreground mb-1">Method</label>
                  <div className="flex gap-1 p-0.5 bg-muted rounded-lg mb-3">
                    <button onClick={() => { updateLine(i, 'method', 'bank'); persist(lines.map((l, idx) => idx === i ? { ...l, method: 'bank' } : l)); }}
                      className={`flex-1 text-sm font-semibold py-2 rounded-md transition-colors ${(line.method || 'bank') === 'bank' ? 'bg-white shadow text-foreground' : 'text-muted-foreground'}`}>
                      Bank
                    </button>
                    <button onClick={() => { updateLine(i, 'method', 'cash'); persist(lines.map((l, idx) => idx === i ? { ...l, method: 'cash' } : l)); }}
                      className={`flex-1 text-sm font-semibold py-2 rounded-md transition-colors ${line.method === 'cash' ? 'bg-white shadow text-emerald-700' : 'text-muted-foreground'}`}>
                      Cash
                    </button>
                  </div>
                  {line.method === 'cash' && <p className="text-[11px] text-emerald-700 bg-emerald-50 rounded px-2 py-1.5 mb-3">Recorded as cash in the ledger.</p>}
                  {line.method === 'cash' && (
                    <div className="mb-3">
                      <label className="block text-xs font-medium text-muted-foreground mb-1">Cash received from (name) *</label>
                      <input type="text" value={cashName} onChange={(e) => setCashName(e.target.value)}
                        placeholder="Who handed over the cash?" autoFocus
                        className="w-full text-sm border border-input rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-primary" />
                    </div>
                  )}
                  <label className="block text-xs font-medium text-muted-foreground mb-1">Payment date</label>
                  <input type="date" value={pickedDate} onChange={(e) => setPickedDate(e.target.value)}
                    className="w-full text-sm border border-input rounded-md px-3 py-2 mb-4 focus:outline-none focus:ring-2 focus:ring-primary" />
                  <div className="flex gap-2">
                    <button onClick={() => markReceived(i)} disabled={saving || (line.method === 'cash' && !cashName.trim())}
                      className="flex-1 px-3 py-2 rounded-md bg-emerald-600 text-white text-sm font-semibold hover:bg-emerald-700 disabled:opacity-50">
                      {saving ? 'Saving…' : 'Save'}
                    </button>
                    <button onClick={() => setPickerLine(null)}
                      className="flex-1 px-3 py-2 rounded-md bg-muted text-muted-foreground text-sm hover:bg-muted/80">Cancel</button>
                  </div>
                </div>
              </div>
            )}
            <Button size="sm" onClick={() => openPicker(i)} disabled={saving} className="bg-emerald-600 hover:bg-emerald-700">
              Mark Received
            </Button>
          </div>
        )}
      </td>
      <td className="px-4 py-2 sticky right-0 z-10 bg-card border-l border-border text-center">
        <button onClick={() => removeLine(i)} disabled={saving} title="Remove this payment line"
          className="inline-flex items-center justify-center w-7 h-7 rounded-md bg-red-100 text-red-600 hover:bg-red-200 disabled:opacity-50">
          <X className="w-3.5 h-3.5" />
        </button>
      </td>
    </tr>
  ));
}

function ordinal(n) {
  if (n >= 11 && n <= 13) return `${n}th`;
  const last = n % 10;
  if (last === 1) return `${n}st`;
  if (last === 2) return `${n}nd`;
  if (last === 3) return `${n}rd`;
  return `${n}th`;
}

const ACTIVE_STATUSES = ['active', 'notice'];

function DiscountButton({ tenant, month, onSaved }) {
  const [open, setOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  const entry = (Array.isArray(tenant.monthly_notes) ? tenant.monthly_notes : []).find((e) => e.month === month) || {};
  const [amount, setAmount] = useState(entry.discount ? String(entry.discount) : '');
  const [reason, setReason] = useState(entry.discount_reason || '');

  useEffect(() => {
    const e = (Array.isArray(tenant.monthly_notes) ? tenant.monthly_notes : []).find((x) => x.month === month) || {};
    setAmount(e.discount ? String(e.discount) : '');
    setReason(e.discount_reason || '');
  }, [tenant.monthly_notes, month]);

  const save = async (override) => {
    setSaving(true);
    try {
      const disc = override !== undefined ? override : Math.max(0, Number(amount) || 0);
      const next = Array.isArray(tenant.monthly_notes) ? [...tenant.monthly_notes] : [];
      const idx = next.findIndex((e) => e.month === month);
      if (disc > 0) {
        const patch = { discount: disc, discount_reason: reason || '' };
        if (idx >= 0) next[idx] = { ...next[idx], ...patch };
        else next.push({ month, ...patch });
      } else if (idx >= 0) {
        // Removing the discount: strip the discount fields. If nothing else is
        // stored for the month, drop the whole entry so it's gone everywhere.
        const { discount, discount_reason, ...rest } = next[idx];
        const hasOther = Object.keys(rest).some((k) => k !== 'month' && rest[k] !== '' && rest[k] != null);
        if (hasOther) next[idx] = rest;
        else next.splice(idx, 1);
      }
      await base44.entities.Tenant.update(tenant.id, { monthly_notes: next });
      setAmount(disc > 0 ? String(disc) : '');
      if (disc <= 0) setReason('');
      setOpen(false);
      await onSaved?.();
    } finally {
      setSaving(false);
    }
  };

  const remove = () => save(0);

  const current = Number(entry.discount || 0);

  return (
    <>
      <button
        onClick={() => setOpen(true)}
        title={current > 0 ? `Discount this month: ${formatCurrency(current)}` : 'Give a discount for this month'}
        className={`inline-flex items-center justify-center w-8 h-8 rounded-md border ${current > 0 ? 'border-emerald-300 bg-emerald-50 text-emerald-700' : 'border-input text-primary hover:bg-primary/5'}`}
      >
        <Percent className="w-4 h-4" />
      </button>
      {open && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4" onClick={() => setOpen(false)}>
          <div className="bg-card rounded-xl border border-border w-full max-w-sm p-5" onClick={(e) => e.stopPropagation()}>
            <p className="text-sm font-semibold mb-1">Tenant discount</p>
            <p className="text-xs text-muted-foreground mb-4">{tenant.name} &middot; {month}. Reduces the rent due for this month only.</p>
            <label className="text-xs font-medium">Discount amount (£)</label>
            <input type="number" min="0" step="0.01" value={amount} onChange={(e) => setAmount(e.target.value)} autoFocus
              className="w-full border border-input rounded-md px-3 py-2 text-sm mb-3 mt-1 focus:outline-none focus:ring-2 focus:ring-primary" />
            <label className="text-xs font-medium">Reason (optional)</label>
            <input type="text" value={reason} onChange={(e) => setReason(e.target.value)} placeholder="e.g. goodwill, repairs delay"
              className="w-full border border-input rounded-md px-3 py-2 text-sm mb-4 mt-1 focus:outline-none focus:ring-2 focus:ring-primary" />
            <div className="flex gap-2 justify-end">
              {current > 0 && (
                <button onClick={remove} disabled={saving}
                  className="px-3 py-2 text-sm rounded-md border border-input text-red-600 mr-auto">Remove</button>
              )}
              <button onClick={() => setOpen(false)} className="px-3 py-2 text-sm rounded-md border border-input">Cancel</button>
              <button onClick={() => save()} disabled={saving} className="px-3 py-2 text-sm rounded-md bg-primary text-white disabled:opacity-50">{saving ? 'Saving…' : 'Save discount'}</button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

export default function Notifications() {
  const queryClient = useQueryClient();
  const { data: tenants = [], refetch: rA } = useTenants();
  const { data: properties = [], refetch: rB } = useProperties();
  const { data: landlords = [], refetch: rC } = useLandlords();
  const { data: rentPayments = [], refetch: rD } = useRentPayments();
  const { data: rentHistoryAll = [], refetch: rE } = useRentHistoryAll();
  const { data: carriedBalances = [], refetch: rF } = useTenantCarriedBalances();
  const { data: landlordPayouts = [], refetch: rG } = useLandlordPayouts();
  const { data: banks = [] } = useBanks();

  const [activeTab, setActiveTab] = useState(null);
  const [refreshing, setRefreshing] = useState(false);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('all'); // all | Paid | Partial | Not Paid



  const handleRefresh = async () => {
    setRefreshing(true);
    try {
      await Promise.all([rA(), rB(), rC(), rD(), rE(), rF(), rG()]);
    } finally {
      setRefreshing(false);
    }
  };

  const allInvoices = useMemo(
    () =>
      buildTenantInvoices({
        tenants,
        properties,
        landlords,
        rentPayments,
        carriedBalances,
        rentHistoryAll,
      }),
    [tenants, properties, landlords, rentPayments, carriedBalances, rentHistoryAll]
  );

  const months = useMemo(() => {
    const set = new Set([format(new Date(), 'yyyy-MM')]);

    (rentPayments || []).forEach((payment) => {
      const period =
        payment.period_month ||
        (payment.payment_date ? payment.payment_date.substring(0, 7) : null);
      if (period) set.add(period);
    });

    allInvoices.forEach((invoice) => {
      if (invoice.period_month) set.add(invoice.period_month);
    });

    return [...set].sort();
  }, [rentPayments, allInvoices]);



  useEffect(() => {
    if (months.length === 0 || activeTab) return;
    const currentMonth = format(new Date(), 'yyyy-MM');
    setActiveTab(months.includes(currentMonth) ? currentMonth : months[months.length - 1]);
  }, [months]);

  const { baseRows, excluded } = useMemo(() => {
    const included = [];
    const out = [];

    // Map property -> tenants, so an older tenancy can be bounded by the start of
    // the next tenancy on the same property (handles "old tenant never marked ended").
    const byProperty = {};
    (tenants || []).forEach((t) => {
      if (!t.property_id) return;
      (byProperty[t.property_id] = byProperty[t.property_id] || []).push(t);
    });

    // Multi-unit detection: two tenancies at the same property with OVERLAPPING
    // lease periods = concurrent flats sharing one property record.
    const multiUnitProperty = {};
    Object.entries(byProperty).forEach(([propId, list]) => {
      const withDates = list
        .filter((t) => t.lease_start)
        .map((t) => {
          const sd = parseISO(t.lease_start);
          const eRaw = t.lease_end ? parseISO(t.lease_end) : null;
          const ed = eRaw && isValid(eRaw) ? eRaw : new Date(8640000000000000);
          return isValid(sd) ? { s: sd, e: ed } : null;
        })
        .filter(Boolean);
      let overlap = false;
      for (let i = 0; i < withDates.length && !overlap; i++) {
        for (let j = i + 1; j < withDates.length; j++) {
          const a = withDates[i], b = withDates[j];
          if (a.s < b.e && b.s < a.e) { overlap = true; break; }
        }
      }
      multiUnitProperty[propId] = overlap;
    });

    (tenants || []).forEach((tenant) => {
      const property = properties.find((p) => p.id === tenant.property_id);

      // Ended/archived tenants are NOT dropped outright — they should still show
      // for the months they were active. We bound them by lease_end below.
      const KNOWN_STATUSES = [...ACTIVE_STATUSES, 'ended', 'archived'];
      if (!tenant.status || !KNOWN_STATUSES.includes(tenant.status)) {
        out.push({
          tenant,
          property,
          reason: `Tenant status: "${tenant.status || 'none'}" (not active/notice)`,
          fix: 'tenant',
        });
        return;
      }

      if (!tenant.property_id) {
        out.push({
          tenant,
          property: null,
          reason: 'No property assigned to tenant',
          fix: 'tenant',
        });
        return;
      }

      if (!property) {
        out.push({
          tenant,
          property: null,
          reason: `Property not found (ID: ${tenant.property_id})`,
          fix: 'tenant',
        });
        return;
      }

      if (!tenant.lease_start) {
        out.push({
          tenant,
          property,
          reason: 'No lease start date set',
          fix: 'tenant',
        });
        return;
      }

      const leaseDate = parseISO(tenant.lease_start);
      if (!isValid(leaseDate)) {
        out.push({
          tenant,
          property,
          reason: `Invalid lease start date: ${tenant.lease_start}`,
          fix: 'tenant',
        });
        return;
      }

      const rentDay = getDate(leaseDate);
      const leaseMonth = format(leaseDate, 'yyyy-MM');

      // Upper bound: a tenant appears in months up to AND INCLUDING the month
      // their tenancy ended. The end is the EARLIEST of:
      //  - their lease_end month,
      //  - the start month of a newer tenancy on the same property (supersession),
      //    but ONLY for ended/archived tenants — active/notice tenants are
      //    concurrent (e.g. HMO / multi-unit properties with multiple tenants).
      //  - the month they were marked ended/archived.
      const bounds = [];
      if (tenant.lease_end) {
        const endDate = parseISO(tenant.lease_end);
        if (isValid(endDate)) {
          // Rent-day aware: cycles are keyed by their START month. If the lease
          // ends BEFORE that month's rent day (e.g. rent day 15, ends 14 Jul),
          // the last cycle started the month before — so bound at the previous
          // month, otherwise July would wrongly show a due rent that was never
          // reached. Clamp the rent day for short months (day 31 in Feb etc.).
          const dim = new Date(endDate.getFullYear(), endDate.getMonth() + 1, 0).getDate();
          const dueDayThisMonth = Math.min(rentDay, dim);
          const lastCycleMonth = getDate(endDate) >= dueDayThisMonth
            ? format(endDate, 'yyyy-MM')
            : format(subMonths(endDate, 1), 'yyyy-MM');
          // Never bound before the first month of the tenancy.
          bounds.push(lastCycleMonth < leaseMonth ? leaseMonth : lastCycleMonth);
        }
      }
      if (tenant.status === 'ended' || tenant.status === 'archived') {
        // A strictly-later tenancy supersedes this ended one — but ONLY on
        // genuine single-unit properties. On multi-unit properties (detected by
        // overlapping lease dates), other tenants are different flats living
        // there at the same time, not replacements.
        if (!multiUnitProperty[tenant.property_id]) {
          (byProperty[tenant.property_id] || []).forEach((other) => {
            if (other.id === tenant.id || !other.lease_start) return;
            const od = parseISO(other.lease_start);
            if (!isValid(od)) return;
            const om = format(od, 'yyyy-MM');
            if (om > leaseMonth) bounds.push(om);
          });
        }
        // Only guess from "last edited" when there is NO lease_end at all —
        // a real lease_end must never be overridden by an earlier edit date.
        if (!tenant.lease_end) {
          const ended = tenant.updated_date ? parseISO(tenant.updated_date) : null;
          bounds.push(ended && isValid(ended) ? format(ended, 'yyyy-MM') : format(new Date(), 'yyyy-MM'));
        }
      }
      const leaseEndMonth = bounds.length ? bounds.sort()[0] : null;

      included.push({ tenant, property, rentDay, leaseMonth, leaseEndMonth });
    });

    included.sort((a, b) => a.rentDay - b.rentDay);
    return { baseRows: included, excluded: out };
  }, [tenants, properties]);

  // Count not-received tenants per month (for tab badges)
  // Per-month rent stats: fully paid / partial / left (not received)
  const monthStats = useMemo(() => {
    const stats = {};
    months.forEach((month) => {
      const monthRows = baseRows.filter((row) =>
        row.leaseMonth <= month && (!row.leaseEndMonth || month <= row.leaseEndMonth) &&
        isDueMonth(row.leaseMonth, month, getFrequency(row.tenant))
      );
      let paidC = 0, partialC = 0, leftC = 0;
      monthRows.forEach((row) => {
        const freq = getFrequency(row.tenant);
        const totalPaid = rentPayments
          .filter((pmt) => {
            if (pmt.tenant_id !== row.tenant.id) return false;
            let period = pmt.period_month || (pmt.payment_date ? pmt.payment_date.substring(0, 7) : null);
            if (freq === 'quarterly' && period) period = cycleStartMonth(row.leaseMonth, period, 'quarterly');
            return period === month;
          })
          .reduce((sum, pmt) => sum + Number(pmt.amount || 0), 0);
        const invoiceForMonth = allInvoices.find(
          (inv) => inv.tenant_id === row.tenant.id && inv.period_month === month
        );
        const discountEntry = (Array.isArray(row.tenant.monthly_notes) ? row.tenant.monthly_notes : []).find((e) => e.month === month) || {};
        const noteDiscount = Math.max(0, Number(discountEntry.discount || 0));
        const amountDue = invoiceForMonth
          ? Math.max(0, Number(invoiceForMonth.total_due ?? invoiceForMonth.rent_amount ?? 0))
          : Math.max(0, forPeriod(Number(row.tenant.monthly_rent ?? row.property?.monthly_rent ?? 0), freq) - noteDiscount);
        if (totalPaid <= 0) leftC++;
        else if (totalPaid >= amountDue) paidC++;
        else partialC++;
      });
      stats[month] = { paid: paidC, partial: partialC, left: leftC, total: monthRows.length };
    });
    return stats;
  }, [months, baseRows, rentPayments, allInvoices]);

  const rows = useMemo(() => {
    if (!activeTab) return [];

    return baseRows
      .filter((row) => row.leaseMonth <= activeTab && (!row.leaseEndMonth || activeTab <= row.leaseEndMonth) && isDueMonth(row.leaseMonth, activeTab, getFrequency(row.tenant)))
      .filter(
        (row) =>
          !search.trim() ||
          row.tenant.name?.toLowerCase().includes(search.toLowerCase()) ||
          row.property.address?.toLowerCase().includes(search.toLowerCase())
      )
      .map((row) => {
        const freq = getFrequency(row.tenant);
        const matchedPayments = rentPayments.filter((payment) => {
          if (payment.tenant_id !== row.tenant.id) return false;
          let period =
            payment.period_month ||
            (payment.payment_date ? payment.payment_date.substring(0, 7) : null);
          if (freq === 'quarterly' && period) period = cycleStartMonth(row.leaseMonth, period, 'quarterly');
          return period === activeTab;
        });

        const totalPaid = matchedPayments.reduce(
          (sum, payment) => sum + Number(payment.amount || 0),
          0
        );

        // Most recent matched payment — used to surface the date/method/bank when
        // rent was recorded elsewhere (e.g. the property Rent tab).
        const latestPayment = [...matchedPayments].sort((a, b) =>
          (b.payment_date || '').localeCompare(a.payment_date || '')
        )[0];
        const paidInfo = latestPayment ? {
          date: latestPayment.payment_date || '',
          method: latestPayment.method === 'cash' ? 'cash' : 'bank',
          bank: latestPayment.received_in_bank_name || '',
        } : null;

        // Does the PREVIOUS month have any rent recorded for this tenant? Used to
        // warn if you record the current month while last month is still empty
        // (a common "recorded against the wrong month" mistake). Only considered
        // when the tenant was actually due rent last month (lease covers it).
        const prevMonthStr = (() => {
          const [yy, mm] = activeTab.split('-').map(Number);
          const d = new Date(yy, mm - 2, 1);
          return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
        })();
        const prevDueStart = `${prevMonthStr}-01`;
        const prevDueEnd = `${prevMonthStr}-28`;
        const leaseCoversPrev = row.tenant.lease_start && row.tenant.lease_start.slice(0, 7) <= prevMonthStr
          && (!row.tenant.lease_end || row.tenant.lease_end >= prevDueStart);
        const prevNotes = (Array.isArray(row.tenant.monthly_notes) ? row.tenant.monthly_notes : []).find(e => e.month === prevMonthStr) || {};
        const prevHasNote = !!(prevNotes.manually_paid || prevNotes.value);
        const prevHasPayment = rentPayments.some(p => {
          if (p.tenant_id !== row.tenant.id) return false;
          const per = p.period_month || (p.payment_date ? p.payment_date.slice(0, 7) : null);
          return per === prevMonthStr;
        });
        const prevMonthMissing = leaseCoversPrev && !prevHasNote && !prevHasPayment;

        // Use the built invoice for this month if one exists — including
        // "upcoming" months — because its total_due already carries forward any
        // unpaid balance from earlier months. Ignoring upcoming invoices here
        // made future months show only that month's rent, hiding real arrears.
        const invoiceForMonth = allInvoices.find(
          (invoice) =>
            invoice.tenant_id === row.tenant.id &&
            invoice.period_month === activeTab
        );

        const discountEntry = (Array.isArray(row.tenant.monthly_notes) ? row.tenant.monthly_notes : []).find((e) => e.month === activeTab) || {};
        const noteDiscount = Math.max(0, Number(discountEntry.discount || 0));
        const discountReason = discountEntry.discount_reason || '';

        let amountDue;
        let discount;
        let grossDue;
        if (invoiceForMonth) {
          // total_due already has the discount applied in buildTenantInvoices — do NOT subtract again
          amountDue = Math.max(0, Number(invoiceForMonth.total_due ?? invoiceForMonth.rent_amount ?? 0));
          discount = Math.max(0, Number(invoiceForMonth.discount ?? noteDiscount));
          grossDue = amountDue + discount;
        } else {
          // No built invoice for this (usually future) month. The invoice builder
          // only generates up to ~now, so far-future tabs have none. Still carry
          // forward any unpaid balance from the tenant's most recent invoice, so
          // arrears don't disappear when looking ahead.
          const freq = getFrequency(row.tenant);
          const raw = forPeriod(Number(row.tenant.monthly_rent ?? row.property?.monthly_rent ?? 0), freq);
          // Latest invoice at or before this month for this tenant.
          const priorInvoices = allInvoices
            .filter((inv) => inv.tenant_id === row.tenant.id && inv.period_month < activeTab)
            .sort((a, b) => b.period_month.localeCompare(a.period_month));
          const prior = priorInvoices[0];
          let carried = 0;
          if (prior) {
            // Outstanding on the most recent invoice = its total due minus what
            // was paid against it (balance_due already accounts for this).
            carried = Math.max(0, Number(prior.balance_due ?? 0));
          }
          discount = noteDiscount;
          grossDue = raw + carried;
          amountDue = Math.max(0, grossDue - discount);
        }

        const balanceOwed = Math.max(amountDue - totalPaid, 0);

        // Plain agreed rent for THIS month (rent-history aware, no arrears/carry).
        // Prefer the invoice's own rent_amount; otherwise derive from rent history
        // so a month before an increase still shows the old rent.
        let agreedRentClean;
        if (invoiceForMonth) {
          agreedRentClean = Number(invoiceForMonth.rent_amount ?? 0);
        } else {
          const freqA = getFrequency(row.tenant);
          const histA = (rentHistoryAll || [])
            .filter((r) => r.tenant_id === row.tenant.id)
            .sort((a, b) => b.start_date.localeCompare(a.start_date));
          let dayPart = '01';
          if (row.tenant.lease_start && /^\d{4}-\d{2}-\d{2}$/.test(row.tenant.lease_start)) dayPart = row.tenant.lease_start.slice(8, 10);
          const periodStartA = `${activeTab}-${dayPart}`;
          const activeRec = histA.find((r) => r.start_date <= periodStartA && (!r.end_date || r.end_date >= periodStartA));
          const baseRent = activeRec ? Number(activeRec.rent_amount) : Number(row.tenant.monthly_rent ?? row.property?.monthly_rent ?? 0);
          agreedRentClean = forPeriod(baseRent, freqA);
        }

        let status = 'Not Paid';
        if (grossDue <= 0) {
          status = 'Not Paid';
        } else if (totalPaid >= amountDue) {
          status = 'Paid';
        } else if (totalPaid > 0) {
          status = 'Partial';
        }

        // Most recent actual payment (e.g. recorded from the property Rent tab)
        // drives the auto-received / part-paid state on the button below.

        return {
          ...row,
          totalPaid,
          amountDue,
          grossDue,
          discount,
          discountReason,
          agreedRent: grossDue,
          agreedRentClean,
          balanceOwed,
          paidInfo,
          prevMonthMissing,
          prevMonthLabel: format(new Date(prevMonthStr + '-01'), 'MMMM yyyy'),
          status,
        };
      });
  }, [activeTab, allInvoices, baseRows, rentPayments, search, rentHistoryAll]);

  // ── Per-month helpers for landlords ──
  const getLandlordMonthEntry = (landlord, month) => {
    const arr = Array.isArray(landlord.monthly_notes) ? landlord.monthly_notes : [];
    return arr.find((e) => e.month === month) || {};
  };

  const saveLandlordMonthField = async (landlord, month, field, value) => {
    const arr = Array.isArray(landlord.monthly_notes) ? [...landlord.monthly_notes] : [];
    const idx = arr.findIndex((e) => e.month === month);
    if (idx >= 0) arr[idx] = { ...arr[idx], [field]: value };
    else arr.push({ month, [field]: value });
    await base44.entities.Landlord.update(landlord.id, { monthly_notes: arr });
    await rC();
  };

  // One row per landlord that has at least one active property for the active month
  const landlordRows = useMemo(() => {
    if (!activeTab) return [];
    const activeLandlordIds = new Set(
      properties
        .filter((p) => p.landlord_id && p.status !== 'inactive')
        .map((p) => p.landlord_id)
    );
    return landlords
      .filter((l) => !l.is_agent && activeLandlordIds.has(l.id))
      .sort((a, b) => (a.name || '').localeCompare(b.name || ''));
  }, [activeTab, landlords, properties]);

  // Append a blank extra payment line to a tenant's month (visual note only).
  const addExtraPaymentLine = async (tenant, month) => {
    if (!month) return;
    const arr = Array.isArray(tenant.monthly_notes) ? [...tenant.monthly_notes] : [];
    const idx = arr.findIndex((e) => e && e.month === month);
    const blank = { value: '', bank: '', notes: '' };
    if (idx >= 0) {
      const existing = Array.isArray(arr[idx].extra_lines) ? arr[idx].extra_lines : [];
      arr[idx] = { ...arr[idx], extra_lines: [...existing, blank] };
    } else {
      arr.push({ month, extra_lines: [blank] });
    }
    try {
      await base44.entities.Tenant.update(tenant.id, { monthly_notes: arr });
      await rA();
      queryClient.invalidateQueries({ queryKey: ['tenants'] });
    } catch (e) { alert(`Could not save: ${e.message || e}`); }
  };

  const filteredRows = useMemo(
    () => (statusFilter === 'all' ? rows : rows.filter((row) => row.status === statusFilter)),
    [rows, statusFilter]
  );

  const paidCount = rows.filter((row) => row.status === 'Paid').length;
  const partialCount = rows.filter((row) => row.status === 'Partial').length;
  const totalOwedAcrossTenants = rows.reduce((sum, row) => sum + row.balanceOwed, 0);

  return (
    <div>
      <ScrollNav />
      <PageHeader
        title="Tenant Rent Dates"
        description="Day of the month each tenant pays rent. New tab appears automatically each month."
        actions={
          <Button size="sm" variant="outline" onClick={handleRefresh} disabled={refreshing}>
            <RefreshCw className={`w-3 h-3 mr-1 ${refreshing ? 'animate-spin' : ''}`} />
            {refreshing ? 'Refreshing...' : 'Refresh'}
          </Button>
        }
      />

      <div className="bg-card rounded-xl border border-border mb-6 px-4 py-3 flex items-center gap-2">
        <Search className="w-4 h-4 text-muted-foreground" />
        <input
          type="text"
          placeholder="Search by tenant name or property address…"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="flex-1 bg-transparent outline-none text-sm"
        />
        {search && (
          <button
            type="button"
            onClick={() => setSearch('')}
            className="text-xs text-muted-foreground hover:text-foreground"
          >
            Clear
          </button>
        )}
      </div>

      <div className="flex flex-wrap items-center gap-1.5 mb-6 -mt-3">
        <span className="text-xs font-medium text-muted-foreground mr-1">Status:</span>
        {[['all',`All (${rows.length})`],['Paid',`Paid (${paidCount})`],['Partial',`Partial (${partialCount})`],['Not Paid',`Not paid (${rows.length - paidCount - partialCount})`]].map(([k,label]) => (
          <button key={k} onClick={() => setStatusFilter(k)}
            className={`px-2.5 py-1 rounded-full text-xs font-semibold transition-colors ${statusFilter === k
              ? (k === 'Paid' ? 'bg-emerald-600 text-white' : k === 'Partial' ? 'bg-amber-500 text-white' : k === 'Not Paid' ? 'bg-red-600 text-white' : 'bg-primary text-white')
              : 'bg-muted text-muted-foreground hover:text-foreground'}`}>
            {label}
          </button>
        ))}
      </div>

      <div className="bg-card rounded-xl border border-border mb-6 overflow-hidden">
        <div className="overflow-x-auto">
          <div className="flex border-b border-border min-w-max">
            {months.map((month) => {
              const isActive = month === activeTab;
              return (
                <button
                  key={month}
                  type="button"
                  onClick={() => setActiveTab(month)}
                  className={`px-4 py-3 text-sm font-medium border-b-2 transition-colors whitespace-nowrap ${
                    isActive
                      ? 'border-primary text-primary bg-primary/5'
                      : 'border-transparent text-muted-foreground hover:text-foreground hover:bg-muted/30'
