import React, { useEffect, useState } from "react";
import { appParams } from "@/lib/app-params";
import { Button } from "@/components/ui/button";
import { ShieldCheck, Loader2 } from "lucide-react";
import AuthLayout from "@/components/AuthLayout";

// App-side OAuth consent page for the app's MCP server. The platform redirects
// AI clients here (see base44/mcp/config.json `consent_path`) with an opaque
// `ctx` handle — the authorization request itself lives on the server. This page
// gates on the app-user session, fetches the display info for that handle, shows
// the categories of access being granted, and posts the approve/deny decision.
// Do not change the fetch calls, headers, or the `ctx` handle handling — styling
// and copy are safe to edit.
export default function OAuthConsent() {
  const ctx = new URLSearchParams(window.location.search).get("ctx");
  const [info, setInfo] = useState(null);
  const [checking, setChecking] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [decided, setDecided] = useState("");
  const [error, setError] = useState("");
  const [reconnect, setReconnect] = useState("");

  useEffect(() => {
    (async () => {
      let redirecting = false;
      try {
        if (!ctx) {
          setError("This authorization link is invalid or has expired.");
          return;
        }
        // Resolve the handle first: a dead handle must never render
        // approve/deny, and the response carries the app's configured login
        // route for the signed-out redirect below. Send the session (cookie +
        // bearer token) so the server can list the granted tools for a
        // signed-in user — the same auth the approve/deny call sends; without
        // it the display request is anonymous and shows no tools.
        const infoHeaders = {};
        if (appParams.token) infoHeaders.Authorization = "Bearer " + appParams.token;
        const res = await fetch(
          `/api/apps/${appParams.appId}/mcp/consent-info?handle=${encodeURIComponent(ctx)}`,
          { credentials: "include", headers: infoHeaders },
        );
        if (!res.ok) {
          setError("This authorization link is invalid or has expired.");
          return;
        }
        const data = await res.json();
        // Gate on the server's auth result, NOT base44.auth.isAuthenticated():
        // the SDK check runs the bearer path, so a cookie-only session (platform
        // login/SSO, or a private app with a stale localStorage token) would read
        // as signed-out and redirect — even though /consent-info just
        // authenticated this same request via its cookie fallback. data.authenticated
        // keeps the redirect decision in agreement with what the server returned.
        if (!data.authenticated) {
          // The short handle rides back in returnTo; login_path is
          // owner-configured and validated server-side as a same-origin path.
          // Send from_url too: a custom-auth app coerced to platform auth (e.g.
          // public_without_login under workspace SSO) serves the platform login,
          // which honors from_url rather than returnTo. Rebuild the query from
          // `ctx` alone — never forward window.location.search raw: the platform
          // resume returns from_url verbatim, so crafted extras on the consent
          // link (app_base_url, access_token, …) would ride through the login
          // round-trip and app-params.js would persist them into the freshly
          // authenticated session.
          const returnTo =
            window.location.pathname + "?ctx=" + encodeURIComponent(ctx);
          const encoded = encodeURIComponent(returnTo);
          redirecting = true; // keep the spinner while the browser navigates
          window.location.href =
            (data.login_path || "/login") + "?returnTo=" + encoded + "&from_url=" + encoded;
          return;
        }
        setInfo(data);
      } catch (e) {
        setError("Could not load this authorization request. Please try again.");
      } finally {
        if (!redirecting) setChecking(false);
      }
    })();
  }, [ctx]);

  const respond = async (action) => {
    setSubmitting(true);
    setError("");
    try {
      const headers = { "Content-Type": "application/json" };
      // Cookie-backed sessions carry no token; sending "Bearer null" would
      // shadow the valid cookie, so add the header only when a token exists.
      if (appParams.token) headers.Authorization = "Bearer " + appParams.token;
      const res = await fetch(`/api/apps/${appParams.appId}/mcp/authorize-grant`, {
        method: "POST",
        credentials: "include",
        headers,
        body: JSON.stringify({ ctx, action }),
      });
      if (!res.ok) {
        // 401 = the session expired before the (single-use, still-unconsumed)
        // handle was spent; retrying the same controls re-sends the dead session
        // forever. Send the user back through login preserving `ctx` — the same
        // redirect the initial signed-out path uses — so they can return and
        // approve the still-valid handle.
        if (res.status === 401) {
          const returnTo = window.location.pathname + "?ctx=" + encodeURIComponent(ctx);
          const encoded = encodeURIComponent(returnTo);
          window.location.href =
            ((info && info.login_path) || "/login") + "?returnTo=" + encoded + "&from_url=" + encoded;
          return;
        }
        // These all come AFTER the single-use handle is atomically consumed
        // (409 tool set changed; 403 host/resource/app mismatch; 404 access
        // gone; 400 malformed/handle already used), so retrying can only 404.
        // Show a terminal reconnect state, not an impossible "try again".
        if ([400, 403, 404, 409].includes(res.status)) {
          let detail = "";
          try { detail = (await res.json()).detail; } catch (_) { /* keep default */ }
          setReconnect(detail || "This authorization can no longer be completed. Reconnect from your AI client to try again.");
          setSubmitting(false);
          return;
        }
        throw new Error("Could not complete authorization. Please try again.");
      }
      const data = await res.json();
      window.location.href = data.redirect_url;
      if (!/^https?:/i.test(data.redirect_url)) {
        // Custom-scheme redirect (native AI clients, e.g. cursor://): browsers
        // may block or not visibly navigate, so show a terminal state instead
        // of an eternal spinner.
        setDecided(action);
        setSubmitting(false);
      }
    } catch (e) {
      setError(e.message);
      setSubmitting(false);
    }
  };

  if (checking) {
    return (
      <AuthLayout icon={ShieldCheck} title="Authorize access">
        <div className="flex items-center justify-center py-6 text-muted-foreground">
          <Loader2 className="w-5 h-5 mr-2 animate-spin" aria-hidden="true" />
          Loading…
        </div>
      </AuthLayout>
    );
  }

  const client = (info && info.client_name) || "An AI client";
  const appName = (info && info.app_name) || "this app";

  if (decided) {
    return (
      <AuthLayout
        icon={ShieldCheck}
        title={decided === "approve" ? "Access granted" : "Access denied"}
        subtitle={`You can return to ${client} and close this window.`}
      />
    );
  }

  // Terminal: the authorization request is no longer valid (tool set changed +
  // handle consumed). Retrying can't succeed, so show reconnect guidance with
  // no approve/deny controls.
  if (reconnect) {
    return (
      <AuthLayout icon={ShieldCheck} title="Reconnect required">
        <div className="p-3 rounded-lg bg-destructive/10 text-destructive text-sm">
          {reconnect}
        </div>
      </AuthLayout>
    );
  }

  // No consent details means nothing trustworthy to approve: a failed
  // consent-info load (expired handle, rate limit, transient error) renders
  // the error alone, never the approve/deny controls.
  if (error && !info) {
    return (
      <AuthLayout icon={ShieldCheck} title="Authorize access">
        <div className="p-3 rounded-lg bg-destructive/10 text-destructive text-sm">
          {error}
        </div>
      </AuthLayout>
    );
  }

  const tools = Array.isArray(info.tools) ? info.tools : [];

  return (
    <AuthLayout
      icon={ShieldCheck}
      title="Authorize access"
      subtitle={`${client} wants to access ${appName} on your behalf`}
    >
      {error && (
        <div className="mb-4 p-3 rounded-lg bg-destructive/10 text-destructive text-sm">
          {error}
        </div>
      )}

      <p className="text-sm font-medium text-foreground mb-2">
        {tools.length ? `It will be able to use these tools in ${appName}:` : "No tools requested"}
      </p>
      {tools.length > 0 && (
        <ul className="space-y-2 text-sm mb-6">
          {tools.map((tool) => (
            <li key={tool.name} className="flex flex-col">
              <span className="text-foreground font-medium">
                {tool.title || tool.name}
              </span>
              {tool.description && (
                <span className="text-muted-foreground">{tool.description}</span>
              )}
            </li>
          ))}
        </ul>
      )}

      <div className="flex gap-3">
        <Button
          variant="outline"
          className="flex-1 h-12 font-medium"
          disabled={submitting}
          onClick={() => respond("deny")}
        >
          Deny
        </Button>
        <Button
          className="flex-1 h-12 font-medium"
          disabled={submitting}
          onClick={() => respond("approve")}
        >
          {submitting ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : null}
          Approve
        </Button>
      </div>
    </AuthLayout>
  );
}

import React, { useState } from 'react';
import { base44 } from '@/api/base44Client';
import { useProperties, useLandlords, useTenants, useRentPayments, usePropertyDocuments, useRentHistoryAll } from '@/hooks/useAllData';
import { useQueryClient } from '@tanstack/react-query';
import { useRole } from '@/hooks/useRole';
import { logAction } from '@/lib/audit';
import PageHeader from '@/components/ui/PageHeader';
import StatusBadge from '@/components/ui/StatusBadge';
import PropertyForm from '@/components/forms/PropertyForm';
import ConfirmDialog from '@/components/ui/ConfirmDialog';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Plus, Search, Eye, Pencil, Trash2, Building2, Users, Banknote, ShieldCheck, Upload, AlertTriangle, CheckCircle2, Clock, XCircle } from 'lucide-react';
import { format, parseISO } from 'date-fns';
import Pagination from '@/components/ui/Pagination';
import PropertyImportModal from '@/components/import/PropertyImportModal';
import { Input } from '@/components/ui/input';
import { Link } from 'react-router-dom';
import { formatCurrency, isExpired, isExpiringSoon, calculateArrears, getPropertyCertStatus } from '@/lib/computations';
import { getLandlordShares, sharesLabel, isMultiLandlord } from '@/lib/landlordShares';

export default function Properties() {
  const { user, isAdmin } = useRole();
  const { data: properties = [] } = useProperties();
  const { data: landlords = [] } = useLandlords();
  const { data: tenants = [] } = useTenants();
  const { data: rentPayments = [] } = useRentPayments();
  const { data: propertyDocuments = [] } = usePropertyDocuments();
  const { data: rentHistory = [] } = useRentHistoryAll();
  const queryClient = useQueryClient();
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState(null);
  const [search, setSearch] = useState('');
  const [confirmDelete, setConfirmDelete] = useState(null);
  const [showImport, setShowImport] = useState(false);
  const [page, setPage] = useState(1);
  const PAGE_SIZE = 20;

  const handleSubmit = async (data) => {
    if (editing) {
      const oldLandlord = editing.landlord_id;
      const newLandlord = data.landlord_id;
      await base44.entities.Property.update(editing.id, data);
      await logAction({ user, action: 'update', entityType: 'Property', entityId: editing.id, summary: `Updated property ${data.address}`, oldValue: editing, newValue: data });

      // Keep commission records in sync with the property's landlord.
      // If the landlord changed, repoint this property's commission ledger,
      // agreements and history from the old landlord to the new one.
      if (newLandlord && oldLandlord && newLandlord !== oldLandlord) {
        try {
          const [ledger, agreements, history] = await Promise.all([
            base44.entities.CommissionLedger.filter({ property_id: editing.id }),
            base44.entities.CommissionAgreement.filter({ property_id: editing.id }),
            base44.entities.CommissionHistory.filter({ property_id: editing.id }),
          ]);
          const repoint = (rows, entity) =>
            (rows || [])
              .filter(r => r.landlord_id === oldLandlord)
              .map(r => entity.update(r.id, { landlord_id: newLandlord }));
          await Promise.all([
            ...repoint(ledger, base44.entities.CommissionLedger),
            ...repoint(agreements, base44.entities.CommissionAgreement),
            ...repoint(history, base44.entities.CommissionHistory),
          ]);
          ['commission_ledger', 'commission_agreements', 'commission_history', 'commission_history_all']
            .forEach(k => queryClient.invalidateQueries({ queryKey: [k] }));
          await logAction({ user, action: 'update', entityType: 'CommissionLedger', entityId: editing.id, summary: `Reassigned commission for ${data.address} to the new landlord` });
        } catch (e) {
          console.warn('Commission reassign failed:', e);
        }
      }
    } else {
      const created = await base44.entities.Property.create(data);
      await logAction({ user, action: 'create', entityType: 'Property', entityId: created.id, summary: `Created property ${data.address}`, newValue: data });
    }
    queryClient.invalidateQueries({ queryKey: ['properties'] });
    setShowForm(false);
    setEditing(null);
  };

  const handleDelete = async (property) => {
    const activeTenants = tenants.filter(t => t.property_id === property.id && t.status === 'active');
    if (activeTenants.length > 0) {
      alert('Cannot delete: property has active tenants. End all tenancies first.');
      setConfirmDelete(null);
      return;
    }
    // Delete all related data for this property
    const [allTenants, rentPmts, payouts, commLedger, commAgreements, extras, expenses, maintenance] = await Promise.all([
      base44.entities.Tenant.filter({ property_id: property.id }),
      base44.entities.RentPayment.filter({ property_id: property.id }),
      base44.entities.LandlordPayout.filter({ property_id: property.id }),
      base44.entities.CommissionLedger.filter({ property_id: property.id }),
      base44.entities.CommissionAgreement.filter({ property_id: property.id }),
      base44.entities.PaymentExtra.filter({ property_id: property.id }),
      base44.entities.Expense.filter({ property_id: property.id }),
      base44.entities.MaintenanceRequest.filter({ property_id: property.id }),
    ]);
    await Promise.all([
      ...allTenants.map(r => base44.entities.Tenant.delete(r.id)),
      ...rentPmts.map(r => base44.entities.RentPayment.delete(r.id)),
      ...payouts.map(r => base44.entities.LandlordPayout.delete(r.id)),
      ...commLedger.map(r => base44.entities.CommissionLedger.delete(r.id)),
      ...commAgreements.map(r => base44.entities.CommissionAgreement.delete(r.id)),
      ...extras.map(r => base44.entities.PaymentExtra.delete(r.id)),
      ...expenses.map(r => base44.entities.Expense.delete(r.id)),
      ...maintenance.map(r => base44.entities.MaintenanceRequest.delete(r.id)),
    ]);
    await base44.entities.Property.delete(property.id);
    await logAction({ user, action: 'delete', entityType: 'Property', entityId: property.id, summary: `Deleted property ${property.address} and all related data`, oldValue: property });
    queryClient.invalidateQueries({ queryKey: ['properties'] });
    queryClient.invalidateQueries({ queryKey: ['tenants'] });
    queryClient.invalidateQueries({ queryKey: ['rent_payments'] });
    queryClient.invalidateQueries({ queryKey: ['landlord_payouts'] });
    queryClient.invalidateQueries({ queryKey: ['commission_ledger'] });
    queryClient.invalidateQueries({ queryKey: ['commission_agreements'] });
    queryClient.invalidateQueries({ queryKey: ['payment_extras'] });
    queryClient.invalidateQueries({ queryKey: ['expenses'] });
    queryClient.invalidateQueries({ queryKey: ['maintenance_requests'] });
    setConfirmDelete(null);
  };

  const filtered = properties
    .filter(p => p.address?.toLowerCase().includes(search.toLowerCase()))
    .sort((a, b) => {
      const aLease = tenants.filter(t => t.property_id === a.id).map(t => t.lease_start).filter(Boolean).sort()[0] || '';
      const bLease = tenants.filter(t => t.property_id === b.id).map(t => t.lease_start).filter(Boolean).sort()[0] || '';
      return aLease.localeCompare(bLease);
    });
  const totalPages = Math.ceil(filtered.length / PAGE_SIZE);
  const paged = filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);

  const getLandlordName = (id) => landlords.find(l => l.id === id)?.name || 'Unknown';

  const statusColors = { occupied: 'green', vacant: 'yellow', maintenance: 'red' };

  const getCertStatus = (property) => {
    const certStatus = getPropertyCertStatus(property.id, propertyDocuments);
    const certs = [certStatus.gas.expiry, certStatus.electrical.expiry, certStatus.epc.expiry, certStatus.license.expiry];

    const hasMissing  = certs.some(c => !c);
    const hasExpired  = certs.some(c => c && isExpired(c));
    const hasExpiring = certs.some(c => c && isExpiringSoon(c));

    if (hasExpired && hasMissing)  return { color: 'red',    label: 'Expired & Missing' };
    if (hasExpiring && hasMissing) return { color: 'red',    label: 'Expiring & Missing' };
    if (hasExpired)                return { color: 'red',    label: 'Expired' };
    if (hasMissing)                return { color: 'red',    label: 'Missing' };
    if (hasExpiring)               return { color: 'yellow', label: 'Expiring' };
    return                                { color: 'green',  label: 'Certs OK' };
  };

  return (
    <div>
      <PageHeader
        title="Properties"
        description={`${properties.length} properties managed — click a property to access all management features`}
        actions={
          <div className="flex gap-2">
            <Button variant="outline" onClick={() => setShowImport(true)}>
              <Upload className="w-4 h-4 mr-2" />Bulk Import
            </Button>
            <Button onClick={() => { setEditing(null); setShowForm(true); }}>
              <Plus className="w-4 h-4 mr-2" />Add Property
            </Button>
          </div>
        }
      />

      <div className="mb-4 max-w-sm">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input placeholder="Search properties..." value={search} onChange={e => { setSearch(e.target.value); setPage(1); }} className="pl-9" />
        </div>
      </div>

      {/* Property Cards Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
        {paged.map(p => {
          const landlord = landlords.find(l => l.id === p.landlord_id);
          const pTenants = tenants.filter(t => t.property_id === p.id && t.status === 'active');
          const pRent = rentPayments.filter(rp => rp.property_id === p.id);
          const totalRent = pRent.reduce((s, rp) => s + (rp.amount || 0), 0);
          const totalArrears = pTenants.reduce((s, t) => s + calculateArrears(t, pRent.filter(r => r.tenant_id === t.id), rentHistory.filter(r => r.tenant_id === t.id)), 0);
          const certBad = getCertStatus(p);
          return (
            <div key={p.id} className="bg-card border border-border rounded-xl overflow-hidden hover:shadow-md transition-shadow">
              {/* Card Header */}
              <div className="px-5 py-4 border-b border-border">
                <div className="flex items-start justify-between gap-2">
                  <div className="flex-1 min-w-0">
                    <h3 className="font-semibold text-sm truncate">{p.address}</h3>
                    <p className="text-xs text-muted-foreground mt-0.5">{p.type} · {p.bedrooms || 0} bed · {isMultiLandlord(p) ? sharesLabel(p, landlords) : getLandlordName(p.landlord_id)}</p>
                  </div>
                  <StatusBadge color={{ occupied: 'green', vacant: 'yellow', maintenance: 'red' }[p.status]}>{p.status}</StatusBadge>
                </div>
              </div>

              {/* Card Stats */}
              <div className="px-5 py-3 grid grid-cols-3 gap-3 border-b border-border">
                <div className="text-center">
                  <p className="text-xs text-muted-foreground">Rent</p>
                  <p className="text-sm font-bold">{formatCurrency(p.monthly_rent)}</p>
                </div>
                <div className="text-center">
                  <p className="text-xs text-muted-foreground">Tenants</p>
                  <p className="text-sm font-bold">{pTenants.length}</p>
                </div>
                <div className="text-center">
                  <p className="text-xs text-muted-foreground">Collected</p>
                  <p className="text-sm font-bold text-emerald-700">{formatCurrency(totalRent)}</p>
                </div>
              </div>

              {totalArrears > 0 && (
                <div className="px-5 py-2 bg-red-50 border-t border-red-100">
                  <span className="text-xs font-semibold text-red-600">⚠ Arrears: {formatCurrency(totalArrears)}</span>
                </div>
              )}

              {/* Certificate Status Row */}
              {(() => {
                const cs = getPropertyCertStatus(p.id, propertyDocuments);
                const certItems = [
                  { label: 'Gas', key: 'gas', ...cs.gas },
                  { label: 'EICR', key: 'electrical', ...cs.electrical },
                  { label: 'EPC', key: 'epc', ...cs.epc },
                  { label: 'Licence', key: 'license', ...cs.license },
                ];
                const hasIssue = certItems.some(c => c.status === 'expired' || c.status === 'expiring' || c.status === 'missing');
                if (!hasIssue) {
                  return (
                    <div className="px-5 py-2 border-t border-border flex items-center gap-1.5">
                      <CheckCircle2 className="w-3.5 h-3.5 text-emerald-500" />
                      <span className="text-xs text-emerald-600 font-medium">All certificates valid</span>
                    </div>
                  );
                }
                return (
                  <div className="px-5 py-2.5 border-t border-border grid grid-cols-4 gap-1">
                    {certItems.map(cert => {
                      const colorMap = {
                        expired: 'text-red-600 bg-red-50',
                        expiring: 'text-amber-600 bg-amber-50',
                        missing: 'text-slate-500 bg-slate-100',
                        valid: 'text-emerald-600 bg-emerald-50',
                      };
                      const IconMap = {
                        expired: XCircle,
                        expiring: Clock,
                        missing: AlertTriangle,
                        valid: CheckCircle2,
                      };
                      const Icon = IconMap[cert.status];
                      const cls = colorMap[cert.status];
                      return (
                        <div key={cert.key} className={`rounded-md px-1.5 py-1 flex flex-col items-center gap-0.5 ${cls}`}>
                          <div className="flex items-center gap-0.5">
                            <Icon className="w-3 h-3 flex-shrink-0" />
                            <span className="text-[10px] font-semibold">{cert.label}</span>
                          </div>
                          <span className="text-[9px] leading-tight text-center">
                            {cert.status === 'missing' ? 'Missing' : cert.expiry ? format(parseISO(cert.expiry), 'dd/MM/yy') : '—'}
                          </span>
                        </div>
                      );
                    })}
                  </div>
                );
              })()}

              {/* Actions */}
              <div className="px-5 py-3 border-t border-border flex items-center gap-1.5">
                <Link to={`/PropertyDetail?id=${p.id}`}>
                  <Button size="sm" className="text-xs h-8"><Eye className="w-3.5 h-3.5 mr-1" />Open</Button>
                </Link>
                <Button variant="ghost" size="sm" onClick={() => { setEditing(p); setShowForm(true); }}><Pencil className="w-4 h-4" /></Button>
                {isAdmin && <Button variant="ghost" size="sm" className="text-destructive hover:text-destructive" onClick={() => setConfirmDelete(p)}><Trash2 className="w-4 h-4" /></Button>}
              </div>
            </div>
          );
        })}
        {filtered.length === 0 && (
          <div className="col-span-3 text-center py-16 text-muted-foreground">
            <Building2 className="w-10 h-10 mx-auto mb-3 opacity-30" />
            <p className="text-sm">No properties found</p>
          </div>
        )}
      </div>
      <Pagination page={page} totalPages={totalPages} total={filtered.length} pageSize={PAGE_SIZE} onPage={setPage} />

      <Dialog open={showForm} onOpenChange={setShowForm}>
        <DialogContent className="max-w-2xl">
          <DialogHeader><DialogTitle>{editing ? 'Edit Property' : 'Add Property'}</DialogTitle></DialogHeader>
          <PropertyForm key={editing?.id || 'new'} property={editing} landlords={landlords} onSubmit={handleSubmit} onCancel={() => setShowForm(false)} />
        </DialogContent>
      </Dialog>

      <ConfirmDialog
        open={!!confirmDelete}
        title="Delete Property"
        description={`Delete "${confirmDelete?.address}"? This will be a soft-delete — record is preserved but marked inactive.`}
        onConfirm={() => handleDelete(confirmDelete)}
        onCancel={() => setConfirmDelete(null)}
      />

      <PropertyImportModal
        open={showImport}
        onClose={() => setShowImport(false)}
        onImported={() => queryClient.invalidateQueries({ queryKey: ['properties'] })}
        landlords={landlords}
      />
    </div>
  );
}

import React, { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { base44 } from '@/api/base44Client';
import { useProperties, useLandlords, useTenants, useRentPayments, useCommissionLedger, useLandlordPayouts, usePaymentExtras, useCommissionAgreements, usePropertyDocuments, useRentHistoryAll } from '@/hooks/useAllData';
import { useMaintenanceRequests } from '@/hooks/useMaintenanceRequests';
import { useExpenses } from '@/hooks/useExpenses';
import { useLedgerAdjustments } from '@/hooks/useLedgerAdjustments';
import { useCashEntries } from '@/hooks/useCashEntries';
import { Link } from 'react-router-dom';
import { Button } from '@/components/ui/button';
import { ArrowLeft, Building2 } from 'lucide-react';
import PropertyOverview from '@/components/property/PropertyOverview';
import PropertyTenants from '@/components/property/PropertyTenants';
import PropertyRentPayments from '@/components/property/PropertyRentPayments';
import PropertyTenantInvoices from '@/components/property/PropertyTenantInvoices';
import PropertyLandlordInvoices from '@/components/property/PropertyLandlordInvoices';
import PropertyLandlordPayments from '@/components/property/PropertyLandlordPayments';
import PropertyLedger from '@/components/property/PropertyLedger';
import PropertyMaintenance from '@/components/property/PropertyMaintenance';
import PropertyArrears from '@/components/property/PropertyArrears';
import PropertyCertificates from '@/components/property/PropertyCertificates';
import PropertyDocuments from '@/components/property/PropertyDocuments';
import PropertyCRM from '@/components/property/PropertyCRM';
import PropertyInspection from '@/components/property/PropertyInspection';
import CommissionChanges from '@/components/landlord/CommissionChanges';
import { isMultiLandlord, sharesLabel } from '@/lib/landlordShares';

const TABS = [
  { id: 'overview', label: 'Overview' },
  { id: 'tenants', label: 'Tenants' },
  { id: 'rent', label: 'Rent & Payments' },
  { id: 'tenant_invoices', label: 'Tenant Invoices' },
  { id: 'landlord_invoices', label: 'Landlord Invoices' },
  { id: 'landlord_payments', label: 'Landlord Payments' },
  { id: 'commission', label: 'Commission' },
  { id: 'ledger', label: 'Ledger' },
  { id: 'maintenance', label: 'Maintenance' },
  { id: 'arrears', label: 'Arrears' },
  { id: 'certificates', label: 'Certificates' },
  { id: 'documents', label: 'Documents' },
  { id: 'crm', label: 'Notes & CRM' },
  { id: 'inspection', label: 'Inspections' },
];

export default function PropertyDetail() {
  const urlParams = new URLSearchParams(window.location.search);
  const id = urlParams.get('id');
  const initialTab = urlParams.get('tab') || 'overview';
  const [activeTab, setActiveTab] = useState(initialTab);

  const { data: properties = [] } = useProperties();
  const { data: landlords = [] } = useLandlords();
  const { data: tenants = [] } = useTenants();
  const { data: rentPayments = [] } = useRentPayments();
  const { data: commissionLedger = [] } = useCommissionLedger();
  const { data: landlordPayouts = [] } = useLandlordPayouts();
  const { data: paymentExtras = [] } = usePaymentExtras();
  const { data: maintenanceRequests = [] } = useMaintenanceRequests();
  const { data: expenses = [] } = useExpenses();
  const { data: adjustments = [] } = useLedgerAdjustments();
  const { data: cashEntries = [] } = useCashEntries();
  const { data: commissionAgreements = [] } = useCommissionAgreements();
  const { data: rentHistoryAll = [] } = useRentHistoryAll();
  const { data: commissionHistory = [] } = useQuery({
    queryKey: ['commission_history_all'],
    queryFn: () => base44.entities.CommissionHistory.list('-start_date', 2000),
    initialData: [],
  });
  const { data: propertyDocuments = [] } = usePropertyDocuments();

  const property = properties.find(p => p.id === id);
  if (!property) return (
    <div className="flex flex-col items-center justify-center py-20 gap-4">
      <Building2 className="w-12 h-12 text-muted-foreground opacity-30" />
      <p className="text-muted-foreground">Property not found</p>
      <Link to="/Properties"><Button variant="outline" size="sm"><ArrowLeft className="w-4 h-4 mr-1" />Back to Properties</Button></Link>
    </div>
  );

  const landlord = landlords.find(l => l.id === property.landlord_id);
  const pTenants = tenants.filter(t => t.property_id === id);
  const pPayments = rentPayments.filter(p => p.property_id === id);
  const pLedger = commissionLedger.filter(e => e.property_id === id);
  const pPayouts = landlordPayouts.filter(p => p.property_id === id);
  const pMaintenance = maintenanceRequests.filter(r => r.property_id === id);
  const pExpenses = expenses.filter(e => e.property_id === id);
  const pExtras = paymentExtras.filter(e => e.property_id === id);
  const pDocuments = propertyDocuments.filter(d => d.property_id === id);

  const pCommissionAgreements = commissionAgreements.filter(
    a => a.property_id === id || (!a.property_id && a.landlord_id === property.landlord_id)
  );
  const pRentHistory = rentHistoryAll.filter(r => pTenants.some(t => t.id === r.tenant_id));

  const sharedProps = {
    property, landlord, landlords, properties,
    pTenants, allTenants: tenants,
    pPayments, allRentPayments: rentPayments,
    pLedger, pPayouts, pMaintenance, pExpenses, pExtras,
    pCommissionAgreements, pRentHistory,
    pDocuments, allPropertyDocuments: propertyDocuments,
    commissionLedger, landlordPayouts, adjustments, cashEntries,
    propertyId: id,
  };

  const renderTab = () => {
    switch (activeTab) {
      case 'overview': return <PropertyOverview {...sharedProps} />;
      case 'tenants': return <PropertyTenants {...sharedProps} />;
      case 'rent': return <PropertyRentPayments {...sharedProps} />;
      case 'tenant_invoices': return <PropertyTenantInvoices {...sharedProps} />;
      case 'landlord_invoices': return <PropertyLandlordInvoices {...sharedProps} />;
      case 'landlord_payments': return <PropertyLandlordPayments {...sharedProps} />;
      case 'commission': {
        const histForProp = commissionHistory.filter(
          (h) => h.property_id === id || (!h.property_id && h.landlord_id === property.landlord_id)
        );
        const fromAgreements = pCommissionAgreements.map((a) => ({
          id: a.id,
          property_id: a.property_id || id,
          commission_type: a.type,
          commission_value: a.value,
          start_date: a.effective_from || (a.created_date ? String(a.created_date).slice(0, 10) : ''),
          end_date: a.effective_to || '',
        }));
        const commRecords = histForProp.length ? histForProp : fromAgreements;
        return (
          <div>
            <h3 className="text-sm font-semibold mb-1">Commission</h3>
            <p className="text-xs text-muted-foreground mb-4">Previous and current commission for this property.</p>
            <CommissionChanges records={commRecords} properties={properties} />
          </div>
        );
      }
      case 'ledger': return <PropertyLedger {...sharedProps} />;
      case 'maintenance': return <PropertyMaintenance {...sharedProps} />;
      case 'arrears': return <PropertyArrears {...sharedProps} />;
      case 'certificates': return <PropertyCertificates {...sharedProps} />;
      case 'documents': return <PropertyDocuments {...sharedProps} />;
      case 'crm': return <PropertyCRM {...sharedProps} />;
      case 'inspection': return <PropertyInspection property={property} pTenants={pTenants} />;
      default: return <PropertyOverview {...sharedProps} />;
    }
  };

  return (
    <div>
      {/* Header */}
      <div className="mb-6">
        <div className="flex items-center gap-2 mb-1">
          <Link to="/Properties" className="text-muted-foreground hover:text-foreground text-sm flex items-center gap-1 transition-colors">
            <ArrowLeft className="w-3.5 h-3.5" />Properties
          </Link>
          <span className="text-muted-foreground text-sm">/</span>
          <span className="text-sm font-medium truncate">{property.address}</span>
        </div>
        <div className="flex items-start justify-between gap-4">
          <div className="min-w-0">
            <h1 className="text-xl sm:text-2xl font-semibold text-foreground tracking-tight truncate">{property.address}</h1>
            <p className="text-muted-foreground text-sm mt-0.5">
              {property.type} · {property.bedrooms || 0} bed · Landlord{isMultiLandlord(property) ? 's' : ''}: <span className="font-medium text-foreground">{isMultiLandlord(property) ? sharesLabel(property, landlords) : (landlord?.name || 'Unknown')}</span>
              <span className={`ml-3 inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${
                property.status === 'occupied' ? 'bg-emerald-100 text-emerald-700' :
                property.status === 'vacant' ? 'bg-amber-100 text-amber-700' :
                'bg-rose-100 text-rose-700'
              }`}>{property.status}</span>
            </p>
          </div>
        </div>
      </div>

      {/* Tab Bar */}
      <div className="flex gap-0.5 overflow-x-auto mb-6 bg-muted/50 rounded-xl p-1 border border-border">
        {TABS.map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            className={`px-3.5 py-2 rounded-lg text-xs font-semibold whitespace-nowrap transition-all duration-200 ${
              activeTab === tab.id
                ? 'bg-background text-foreground shadow-sm border border-border'
                : 'text-muted-foreground hover:text-foreground hover:bg-background/50'
            }`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {/* Tab Content */}
      <div>{renderTab()}</div>
    </div>
  );
}

import React, { useMemo, useState } from 'react';
import { base44 } from '@/api/base44Client';
import { useQueryClient } from '@tanstack/react-query';
import { useProspectiveTenants } from '@/hooks/useProspectiveTenants';
import { useRole } from '@/hooks/useRole';
import { logAction } from '@/lib/audit';
import PageHeader from '@/components/ui/PageHeader';
import StatCard from '@/components/ui/StatCard';
import ConfirmDialog from '@/components/ui/ConfirmDialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Users, Search, Trash2, Eye, Plus, Phone, Mail, Pencil, Home, Wallet, Briefcase } from 'lucide-react';
import { format, parseISO } from 'date-fns';

const SOURCES = ['walk_in', 'phone', 'website', 'rightmove', 'zoopla', 'gumtree', 'referral', 'social_media', 'other'];
const EMPLOYMENT = ['employed', 'self_employed', 'student', 'unemployed', 'retired', 'other'];
const fmtLabel = (s) => (s || '').replace(/_/g, ' ');
const money = (n) => (n || n === 0) ? `£${Number(n).toLocaleString()}` : '';

const emptyLead = () => ({
  name: '', phone: '', email: '',
  enquiry_date: format(new Date(), 'yyyy-MM-dd'), source: 'phone',
  budget_min: '', budget_max: '', bedrooms_wanted: '', preferred_area: '', move_in_date: '', property_type: '',
  occupation: '', employer: '', annual_income: '', employment_status: 'employed',
  household_size: '', has_pets: false, smoker: false, current_situation: '', has_guarantor: false, benefits: false,
  notes: '',
});

export default function ProspectiveTenants() {
  const { user, isAdmin } = useRole();
  const { data: leads } = useProspectiveTenants();
  const queryClient = useQueryClient();

  const [search, setSearch] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState(null);
  const [viewing, setViewing] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(null);

  const filtered = useMemo(() => (leads || []).filter(l => {
    if (!search) return true;
    const q = search.toLowerCase();
    return [l.name, l.phone, l.email, l.preferred_area, l.occupation, l.notes]
      .some(v => (v || '').toLowerCase().includes(q));
  }), [leads, search]);

  const totals = useMemo(() => {
    const all = leads || [];
    const thisMonth = all.filter(l => (l.enquiry_date || '').startsWith(format(new Date(), 'yyyy-MM'))).length;
    const withPets = all.filter(l => l.has_pets).length;
    return { total: all.length, thisMonth, withPets };
  }, [leads]);

  const openNew = () => { setEditing(emptyLead()); setShowForm(true); };
  const openEdit = (l) => { setEditing({ ...emptyLead(), ...l }); setShowForm(true); };

  const handleSubmit = async (data) => {
    const payload = {
      ...data,
      budget_min: data.budget_min !== '' ? Number(data.budget_min) : undefined,
      budget_max: data.budget_max !== '' ? Number(data.budget_max) : undefined,
      annual_income: data.annual_income !== '' ? Number(data.annual_income) : undefined,
    };
    if (editing?.id) {
      await base44.entities.ProspectiveTenant.update(editing.id, payload);
      await logAction({ user, action: 'update', entityType: 'ProspectiveTenant', entityId: editing.id, summary: `Updated prospective tenant ${data.name}`, oldValue: editing, newValue: payload });
    } else {
      const created = await base44.entities.ProspectiveTenant.create(payload);
      await logAction({ user, action: 'create', entityType: 'ProspectiveTenant', entityId: created?.id, summary: `Added prospective tenant ${data.name}`, newValue: payload });
    }
    queryClient.invalidateQueries({ queryKey: ['prospective_tenants'] });
    setShowForm(false); setEditing(null);
  };

  const handleDelete = async (l) => {
    await base44.entities.ProspectiveTenant.delete(l.id);
    await logAction({ user, action: 'delete', entityType: 'ProspectiveTenant', entityId: l.id, summary: `Deleted prospective tenant ${l.name}`, oldValue: l });
    queryClient.invalidateQueries({ queryKey: ['prospective_tenants'] });
    setConfirmDelete(null);
  };

  return (
    <div>
      <PageHeader
        title="Prospective Tenants"
        description="Record interested tenants and their details so you can contact them"
        actions={<Button onClick={openNew}><Plus className="w-4 h-4 mr-1.5" />Add Lead</Button>}
