      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-6">
        <StatCard label="Total leads" value={totals.total} icon={Users} color="primary" />
        <StatCard label="Added this month" value={totals.thisMonth} icon={Plus} color="success" />
