      </div>

      <div className="flex items-center gap-2 mb-4 bg-card border border-border rounded-lg px-3 py-2">
        <Search className="w-4 h-4 text-muted-foreground" />
        <input
          value={search}
          onChange={e => setSearch(e.target.value)}
          placeholder="Search name, phone, email, area, occupation…"
          className="flex-1 bg-transparent outline-none text-sm"
        />
        {search && <button onClick={() => setSearch('')} className="text-xs text-muted-foreground hover:text-foreground">Clear</button>}
      </div>

      <div className="bg-card rounded-xl border border-border overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm min-w-[860px]">
            <thead>
              <tr className="bg-muted/50 text-xs text-muted-foreground text-left">
                <th className="px-4 py-3 font-medium">Name</th>
                <th className="px-4 py-3 font-medium">Contact</th>
                <th className="px-4 py-3 font-medium">Looking for</th>
                <th className="px-4 py-3 font-medium">Budget</th>
                <th className="px-4 py-3 font-medium">Move-in</th>
                <th className="px-4 py-3 font-medium">Source</th>
                <th className="px-4 py-3 font-medium text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {filtered.map(l => (
                <tr key={l.id} className="border-t border-border hover:bg-muted/30">
                  <td className="px-4 py-3">
                    <button onClick={() => setViewing(l)} className="font-medium hover:underline text-left">{l.name}</button>
                    {l.enquiry_date && <div className="text-[11px] text-muted-foreground">{format(parseISO(l.enquiry_date), 'd MMM yyyy')}</div>}
                  </td>
                  <td className="px-4 py-3 text-xs">
                    {l.phone && <div className="flex items-center gap-1"><Phone className="w-3 h-3 text-muted-foreground" />{l.phone}</div>}
                    {l.email && <div className="flex items-center gap-1 text-muted-foreground"><Mail className="w-3 h-3" />{l.email}</div>}
                  </td>
                  <td className="px-4 py-3 text-xs">
                    {[l.bedrooms_wanted && `${l.bedrooms_wanted} bed`, l.property_type, l.preferred_area].filter(Boolean).join(' · ') || '—'}
                  </td>
                  <td className="px-4 py-3 text-xs">
                    {l.budget_min || l.budget_max ? `${money(l.budget_min)}${l.budget_min && l.budget_max ? ' – ' : ''}${money(l.budget_max)}` : '—'}
                  </td>
                  <td className="px-4 py-3 text-xs">{l.move_in_date ? format(parseISO(l.move_in_date), 'd MMM yyyy') : '—'}</td>
                  <td className="px-4 py-3 text-xs capitalize">{fmtLabel(l.source)}</td>
                  <td className="px-4 py-3">
                    <div className="flex gap-1 justify-end">
                      <Button variant="ghost" size="sm" onClick={() => setViewing(l)}><Eye className="w-4 h-4" /></Button>
                      <Button variant="ghost" size="sm" onClick={() => openEdit(l)}><Pencil className="w-4 h-4" /></Button>
                      {isAdmin && <Button variant="ghost" size="sm" onClick={() => setConfirmDelete(l)}><Trash2 className="w-4 h-4 text-red-500" /></Button>}
                    </div>
                  </td>
                </tr>
              ))}
              {filtered.length === 0 && (
                <tr><td colSpan="7" className="px-4 py-12 text-center text-muted-foreground text-sm">
                  {search ? 'No leads match your search.' : 'No prospective tenants yet. Click “Add Lead” to record one.'}
                </td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Add / Edit form */}
      <Dialog open={showForm} onOpenChange={(o) => { if (!o) { setShowForm(false); setEditing(null); } }}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader><DialogTitle>{editing?.id ? 'Edit prospective tenant' : 'Add prospective tenant'}</DialogTitle></DialogHeader>
          {editing && <LeadForm data={editing} onChange={setEditing} onSubmit={handleSubmit} onCancel={() => { setShowForm(false); setEditing(null); }} />}
        </DialogContent>
      </Dialog>

      {/* View detail */}
      <Dialog open={!!viewing} onOpenChange={(o) => { if (!o) setViewing(null); }}>
        <DialogContent className="max-w-lg max-h-[90vh] overflow-y-auto">
          {viewing && <LeadDetail lead={viewing} onEdit={() => { setViewing(null); openEdit(viewing); }} />}
        </DialogContent>
      </Dialog>

      <ConfirmDialog
        open={!!confirmDelete}
        title="Delete prospective tenant?"
        description={`This will permanently remove ${confirmDelete?.name || 'this lead'}'s details.`}
        onConfirm={() => handleDelete(confirmDelete)}
        onCancel={() => setConfirmDelete(null)}
      />
    </div>
  );
}

function Section({ icon: Icon, title, children }) {
  return (
    <div className="space-y-3">
      <div className="flex items-center gap-2 text-sm font-semibold text-primary"><Icon className="w-4 h-4" />{title}</div>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">{children}</div>
    </div>
  );
}

function Field({ label, children, full }) {
  return <div className={`space-y-1.5 ${full ? 'sm:col-span-2' : ''}`}><Label className="text-xs">{label}</Label>{children}</div>;
}

function Check({ label, checked, onChange }) {
  return (
    <label className="flex items-center gap-2 cursor-pointer select-none text-sm">
      <input type="checkbox" checked={!!checked} onChange={e => onChange(e.target.checked)} className="w-4 h-4 rounded border-input" />
      {label}
    </label>
  );
}

function LeadForm({ data, onChange, onSubmit, onCancel }) {
  const [submitting, setSubmitting] = useState(false);
  const set = (patch) => onChange({ ...data, ...patch });

  const submit = async (e) => {
    e.preventDefault();
    if (!data.name?.trim()) return;
    setSubmitting(true);
    try { await onSubmit(data); } finally { setSubmitting(false); }
  };

  return (
    <form onSubmit={submit} className="space-y-6 pt-2">
      <Section icon={Users} title="Contact details">
        <Field label="Full name *"><Input value={data.name} onChange={e => set({ name: e.target.value })} placeholder="Name" /></Field>
        <Field label="Phone"><Input value={data.phone} onChange={e => set({ phone: e.target.value })} placeholder="07…" /></Field>
        <Field label="Email"><Input type="email" value={data.email} onChange={e => set({ email: e.target.value })} placeholder="name@email.com" /></Field>
        <Field label="Enquiry date"><Input type="date" value={data.enquiry_date || ''} onChange={e => set({ enquiry_date: e.target.value })} /></Field>
        <Field label="Source">
          <Select value={data.source} onValueChange={v => set({ source: v })}>
            <SelectTrigger><SelectValue /></SelectTrigger>
            <SelectContent>{SOURCES.map(s => <SelectItem key={s} value={s}><span className="capitalize">{fmtLabel(s)}</span></SelectItem>)}</SelectContent>
          </Select>
        </Field>
      </Section>

      <Section icon={Home} title="What they're looking for">
        <Field label="Bedrooms wanted"><Input value={data.bedrooms_wanted} onChange={e => set({ bedrooms_wanted: e.target.value })} placeholder="Studio / 1 / 2 / 3+" /></Field>
        <Field label="Property type"><Input value={data.property_type} onChange={e => set({ property_type: e.target.value })} placeholder="Flat, House, HMO room" /></Field>
        <Field label="Budget min (£/mo)"><Input type="number" value={data.budget_min} onChange={e => set({ budget_min: e.target.value })} placeholder="0" /></Field>
        <Field label="Budget max (£/mo)"><Input type="number" value={data.budget_max} onChange={e => set({ budget_max: e.target.value })} placeholder="0" /></Field>
        <Field label="Preferred area / postcode" full><Input value={data.preferred_area} onChange={e => set({ preferred_area: e.target.value })} placeholder="e.g. E7, Forest Gate" /></Field>
        <Field label="Desired move-in date"><Input type="date" value={data.move_in_date || ''} onChange={e => set({ move_in_date: e.target.value })} /></Field>
      </Section>

      <Section icon={Briefcase} title="Employment & income">
        <Field label="Occupation"><Input value={data.occupation} onChange={e => set({ occupation: e.target.value })} /></Field>
        <Field label="Employer"><Input value={data.employer} onChange={e => set({ employer: e.target.value })} /></Field>
        <Field label="Employment status">
          <Select value={data.employment_status} onValueChange={v => set({ employment_status: v })}>
            <SelectTrigger><SelectValue /></SelectTrigger>
            <SelectContent>{EMPLOYMENT.map(s => <SelectItem key={s} value={s}><span className="capitalize">{fmtLabel(s)}</span></SelectItem>)}</SelectContent>
          </Select>
        </Field>
        <Field label="Annual income (£)"><Input type="number" value={data.annual_income} onChange={e => set({ annual_income: e.target.value })} placeholder="0" /></Field>
      </Section>

      <Section icon={Wallet} title="Household & situation">
        <Field label="Household size / occupants" full><Input value={data.household_size} onChange={e => set({ household_size: e.target.value })} placeholder="e.g. couple + 1 child" /></Field>
        <Field label="Current situation" full><Input value={data.current_situation} onChange={e => set({ current_situation: e.target.value })} placeholder="e.g. renting, living with family" /></Field>
        <div className="sm:col-span-2 grid grid-cols-2 gap-2 pt-1">
          <Check label="Has pets" checked={data.has_pets} onChange={v => set({ has_pets: v })} />
          <Check label="Smoker" checked={data.smoker} onChange={v => set({ smoker: v })} />
          <Check label="Has guarantor" checked={data.has_guarantor} onChange={v => set({ has_guarantor: v })} />
          <Check label="On housing benefit / UC" checked={data.benefits} onChange={v => set({ benefits: v })} />
        </div>
      </Section>

      <div className="space-y-1.5">
        <Label className="text-xs">Notes</Label>
        <Textarea rows={3} value={data.notes} onChange={e => set({ notes: e.target.value })} placeholder="Any follow-up detail…" />
      </div>

      <div className="flex gap-3 justify-end pt-1">
        <Button type="button" variant="outline" onClick={onCancel} disabled={submitting}>Cancel</Button>
        <Button type="submit" disabled={submitting || !data.name?.trim()}>{submitting ? 'Saving…' : (data.id ? 'Save changes' : 'Add lead')}</Button>
