import React, { useState } from "react";
import { Link } from "react-router-dom";
import { base44 } from "@/api/base44Client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { UserPlus, Mail, Lock, Loader2 } from "lucide-react";
import { InputOTP, InputOTPGroup, InputOTPSlot } from "@/components/ui/input-otp";
import AuthLayout from "@/components/AuthLayout";
import GoogleIcon from "@/components/GoogleIcon";
import { toast } from "@/components/ui/use-toast";

export default function Register() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [showOtp, setShowOtp] = useState(false);
  const [otpCode, setOtpCode] = useState("");

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    if (password !== confirmPassword) {
      setError("Passwords do not match");
      return;
    }
    setLoading(true);
    try {
      await base44.auth.register({ email, password });
      setShowOtp(true);
    } catch (err) {
      setError(err.message || "Registration failed");
    } finally {
      setLoading(false);
    }
  };

  const handleVerify = async () => {
    setError("");
    setLoading(true);
    try {
      const result = await base44.auth.verifyOtp({ email, otpCode });
      if (result?.access_token) {
        base44.auth.setToken(result.access_token);
      }
      window.location.href = "/";
    } catch (err) {
      setError(err.message || "Invalid verification code");
    } finally {
      setLoading(false);
    }
  };

  const handleResend = async () => {
    setError("");
    try {
      await base44.auth.resendOtp(email);
      toast({
        title: "Code sent",
        description: "Check your email for the new code.",
      });
    } catch (err) {
      setError(err.message || "Failed to resend code");
    }
  };

  const handleGoogle = () => {
    base44.auth.loginWithProvider("google", "/");
  };

  if (showOtp) {
    return (
      <AuthLayout
        icon={Mail}
        title="Verify your email"
        subtitle={`We sent a code to ${email}`}
      >
        {error && (
          <div className="mb-4 p-3 rounded-lg bg-destructive/10 text-destructive text-sm">
            {error}
          </div>
        )}
        <div className="flex justify-center mb-6">
          <InputOTP
            maxLength={6}
            value={otpCode}
            onChange={setOtpCode}
            autoFocus
            autoComplete="one-time-code"
          >
            <InputOTPGroup>
              <InputOTPSlot index={0} />
              <InputOTPSlot index={1} />
              <InputOTPSlot index={2} />
              <InputOTPSlot index={3} />
              <InputOTPSlot index={4} />
              <InputOTPSlot index={5} />
            </InputOTPGroup>
          </InputOTP>
        </div>
        <Button
          className="w-full h-12 font-medium"
          onClick={handleVerify}
          disabled={loading || otpCode.length < 6}
        >
          {loading ? (
            <>
              <Loader2 className="w-4 h-4 mr-2 animate-spin" />
              Verifying...
            </>
          ) : (
            "Verify"
          )}
        </Button>
        <p className="text-center text-sm text-muted-foreground mt-4">
          Didn't receive the code?{" "}
          <button onClick={handleResend} className="text-primary font-medium hover:underline">
            Resend
          </button>
        </p>
      </AuthLayout>
    );
  }

  return (
    <AuthLayout
      icon={UserPlus}
      title="Create your account"
      subtitle="Sign up to get started"
      footer={
        <>
          Already have an account?{" "}
          <Link to="/login" className="text-primary font-medium hover:underline">
            Log in
          </Link>
        </>
      }
    >
      <Button
        variant="outline"
        className="w-full h-12 text-sm font-medium mb-6"
        onClick={handleGoogle}
      >
        <GoogleIcon className="w-5 h-5 mr-2" />
        Continue with Google
      </Button>

      <div className="relative mb-6">
        <div className="absolute inset-0 flex items-center">
          <div className="w-full border-t border-border" />
        </div>
        <div className="relative flex justify-center text-xs uppercase">
          <span className="bg-card px-3 text-muted-foreground">or</span>
        </div>
      </div>

      {error && (
        <div className="mb-4 p-3 rounded-lg bg-destructive/10 text-destructive text-sm">
          {error}
        </div>
      )}

      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="space-y-2">
          <Label htmlFor="email">Email</Label>
          <div className="relative">
            <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" aria-hidden="true" />
            <Input
              id="email"
              type="email"
              autoComplete="email"
              autoFocus
              placeholder="you@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="pl-10 h-12"
              required
            />
          </div>
        </div>
        <div className="space-y-2">
          <Label htmlFor="password">Password</Label>
          <div className="relative">
            <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" aria-hidden="true" />
            <Input
              id="password"
              type="password"
              autoComplete="new-password"
              placeholder="••••••••"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="pl-10 h-12"
              required
            />
          </div>
        </div>
        <div className="space-y-2">
          <Label htmlFor="confirm">Confirm Password</Label>
          <div className="relative">
            <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" aria-hidden="true" />
            <Input
              id="confirm"
              type="password"
              autoComplete="new-password"
              placeholder="••••••••"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              className="pl-10 h-12"
              required
            />
          </div>
        </div>
        <Button type="submit" className="w-full h-12 font-medium" disabled={loading}>
          {loading ? (
            <>
              <Loader2 className="w-4 h-4 mr-2 animate-spin" />
              Creating account...
            </>
          ) : (
            "Create account"
          )}
        </Button>
      </form>
    </AuthLayout>
  );
}

import React, { useState } from 'react';
import { base44 } from '@/api/base44Client';
import { useRentPayments, useTenants, useProperties, useLandlords, useCommissionAgreements, useCommissionLedger } from '@/hooks/useAllData';
import { useQueryClient } from '@tanstack/react-query';
import { useRole } from '@/hooks/useRole';
import { logAction } from '@/lib/audit';
import PageHeader from '@/components/ui/PageHeader';
import StatusBadge from '@/components/ui/StatusBadge';
import RentPaymentForm from '@/components/forms/RentPaymentForm';
import ConfirmDialog from '@/components/ui/ConfirmDialog';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Plus, Search, Trash2 } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { formatCurrency, calculateCommission } from '@/lib/computations';
import { format, parseISO } from 'date-fns';

export default function Rent() {
  const { user, isAdmin } = useRole();
  const { data: rentPayments } = useRentPayments();
  const { data: tenants } = useTenants();
  const { data: properties } = useProperties();
  const { data: landlords } = useLandlords();
  const { data: agreements } = useCommissionAgreements();
  const { data: ledger } = useCommissionLedger();
  const queryClient = useQueryClient();
  const [showForm, setShowForm] = useState(false);
  const [submittingRent, setSubmittingRent] = useState(false);
  const [search, setSearch] = useState('');
  const [confirmDelete, setConfirmDelete] = useState(null);

  const handleSubmit = async (data) => {
    if (submittingRent) return;
    setSubmittingRent(true);
    try { await handleSubmitInner(data); } finally { setSubmittingRent(false); }
  };

  const handleSubmitInner = async (data) => {
    // Create rent payment
    const payment = await base44.entities.RentPayment.create(data);

    // --- ONE COMMISSION PER PROPERTY+PERIOD ---
    // Check if commission already applied for this property+period
    const freshLedger = await base44.entities.CommissionLedger.filter({
      property_id: data.property_id,
      period_month: data.period_month,
});
const existingEntry = freshLedger.length > 0;

    if (!existingEntry) {
      // Find commission agreement valid for this period_month (respects effective_from / effective_to)
      const periodMonth = data.period_month;
      const matchesPeriod = (a) => {
        if (a.effective_from && periodMonth < a.effective_from) return false;
        if (a.effective_to && periodMonth > a.effective_to) return false;
        return true;
      };
      const propAgreement = agreements.find(a => a.property_id === data.property_id && matchesPeriod(a));
      const landlordAgreement = agreements.find(a => a.landlord_id === data.landlord_id && !a.property_id && matchesPeriod(a));
      const agreement = propAgreement || landlordAgreement;

      // Always base commission on FULL monthly rent (not partial payment amount)
      const tenant = tenants.find(t => t.id === data.tenant_id);
      const fullMonthlyRent = tenant?.monthly_rent || data.amount;

      if (agreement) {
        const { commission, landlordShare } = calculateCommission(fullMonthlyRent, agreement);
        await base44.entities.CommissionLedger.create({
          rent_payment_id: payment.id,
          landlord_id: data.landlord_id,
          property_id: data.property_id,
          period_month: data.period_month,
          rent_amount: fullMonthlyRent,
          commission_amount: commission,
          landlord_share: landlordShare,
          commission_type: agreement.type,
          commission_rate: agreement.value,
          date: data.payment_date,
        });
        if (agreement.type === 'one_time' && !agreement.one_time_applied) {
          await base44.entities.CommissionAgreement.update(agreement.id, { one_time_applied: true });
          queryClient.invalidateQueries({ queryKey: ['commission_agreements'] });
        }
      } else {
        // No agreement: landlord gets full amount, zero commission
        await base44.entities.CommissionLedger.create({
          rent_payment_id: payment.id,
          landlord_id: data.landlord_id,
          property_id: data.property_id,
          period_month: data.period_month,
          rent_amount: fullMonthlyRent,
          commission_amount: 0,
          landlord_share: fullMonthlyRent,
          commission_type: 'percentage',
          commission_rate: 0,
          date: data.payment_date,
        });
      }
    }
    // If existingEntry found: commission already applied for this period — skip entirely

    queryClient.invalidateQueries({ queryKey: ['rent_payments'] });
    queryClient.invalidateQueries({ queryKey: ['commission_ledger'] });
    queryClient.invalidateQueries({ queryKey: ['commission_agreements'] });
    queryClient.invalidateQueries({ queryKey: ['landlord_payouts'] });
    await logAction({ user, action: 'create', entityType: 'RentPayment', entityId: payment.id, summary: `Recorded rent payment of ${formatCurrency(data.amount)} for period ${data.period_month}${existingEntry ? ' (commission already applied this period)' : ''}`, newValue: data });
    setShowForm(false);
  }; // end handleSubmitInner

  const handleDelete = async (rp) => {
    if (!isAdmin) { alert('Only admins can delete rent payments.'); setConfirmDelete(null); return; }

    // How many rent payments exist for this property+period (including the one being deleted)?
    const periodPayments = rentPayments.filter(
      p => p.property_id === rp.property_id && p.period_month === rp.period_month
    );
    const isLastForPeriod = periodPayments.length === 1;

    // Only reverse commission if this is the LAST rent payment for this property+period.
    // If there are multiple installments and one is deleted, commission stays (it's based on full monthly rent).
    if (isLastForPeriod) {
      const periodCommission = ledger.find(
        e => e.property_id === rp.property_id && e.period_month === rp.period_month
      );
      if (periodCommission) {
        await base44.entities.CommissionLedger.delete(periodCommission.id);
      }
    }

    await base44.entities.RentPayment.delete(rp.id);
    await logAction({
      user,
      action: 'delete',
      entityType: 'RentPayment',
      entityId: rp.id,
      summary: `Deleted rent payment of ${formatCurrency(rp.amount)} (${rp.period_month})${isLastForPeriod ? ' — commission reversed' : ' — commission retained (other payments exist for this period)'}`,
      oldValue: rp,
    });
    queryClient.invalidateQueries({ queryKey: ['rent_payments'] });
    queryClient.invalidateQueries({ queryKey: ['commission_ledger'] });
    queryClient.invalidateQueries({ queryKey: ['commission_agreements'] });
    setConfirmDelete(null);
  };

  const getTenantName = (id) => tenants.find(t => t.id === id)?.name || 'Unknown';
  const getPropertyAddress = (id) => properties.find(p => p.id === id)?.address || 'Unknown';

  const filtered = rentPayments.filter(rp => {
    const tName = getTenantName(rp.tenant_id);
    return tName.toLowerCase().includes(search.toLowerCase()) || rp.period_month?.includes(search);
  });

  return (
    <div>
      <PageHeader
        title="Rent Payments"
        description={`${rentPayments.length} payments recorded`}
        actions={<Button onClick={() => setShowForm(true)}><Plus className="w-4 h-4 mr-2" />Record Payment</Button>}
      />

      <div className="mb-4 max-w-sm">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input placeholder="Search by tenant or period..." value={search} onChange={e => setSearch(e.target.value)} className="pl-9" />
        </div>
      </div>

      <div className="bg-card rounded-xl border border-border overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-muted/50">
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Tenant</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Property</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Amount</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Date</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Period</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Method</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Commission</th>
                {isAdmin && <th className="text-left px-5 py-3 font-medium text-muted-foreground">Actions</th>}
              </tr>
            </thead>
            <tbody>
              {filtered.map(rp => {
                const entry = ledger.find(e => e.rent_payment_id === rp.id);
                return (
                  <tr key={rp.id} className="border-t border-border hover:bg-muted/30 transition-colors">
                    <td className="px-5 py-3 font-medium">{getTenantName(rp.tenant_id)}</td>
                    <td className="px-5 py-3 text-muted-foreground">{getPropertyAddress(rp.property_id)}</td>
                    <td className="px-5 py-3 font-medium">{formatCurrency(rp.amount)}</td>
                    <td className="px-5 py-3 text-muted-foreground">{rp.payment_date ? format(parseISO(rp.payment_date), 'dd MMM yyyy') : '-'}</td>
                    <td className="px-5 py-3">{rp.period_month}</td>
                    <td className="px-5 py-3"><StatusBadge color="blue">{rp.method?.replace(/_/g, ' ')}</StatusBadge></td>
                    <td className="px-5 py-3">
                       {(() => {
                         const periodEntry = ledger.find(e => e.rent_payment_id === rp.id);
                          if (!periodEntry) return <span className="text-muted-foreground text-xs">—</span>;
                          return (
                          <div className="flex flex-col">
                          <span className="font-medium">{formatCurrency(periodEntry.commission_amount)}</span>
                          <span className="text-xs text-muted-foreground">✓ applied this period</span>
                          </div>
                          );
                       })()}
                     </td>
                    {isAdmin && <td className="px-5 py-3">
                      <Button variant="ghost" size="sm" className="text-destructive hover:text-destructive" onClick={() => setConfirmDelete(rp)}><Trash2 className="w-4 h-4" /></Button>
                    </td>}
                    </tr>
                    );
                    })}
                    {filtered.length === 0 && (
                    <tr><td colSpan={isAdmin ? 8 : 7} className="px-5 py-8 text-center text-muted-foreground">No payments found</td></tr>
                    )}
                    </tbody>
          </table>
        </div>
      </div>

      <Dialog open={showForm} onOpenChange={setShowForm}>
        <DialogContent className="max-w-lg">
          <DialogHeader><DialogTitle>Record Rent Payment</DialogTitle></DialogHeader>
          <RentPaymentForm tenants={tenants} properties={properties} onSubmit={handleSubmit} onCancel={() => setShowForm(false)} />
        </DialogContent>
      </Dialog>

      <ConfirmDialog
        open={!!confirmDelete}
        title="Delete Rent Payment"
        description={(() => {
          if (!confirmDelete) return '';
          const periodPayments = rentPayments.filter(
            p => p.property_id === confirmDelete.property_id && p.period_month === confirmDelete.period_month
          );
          const isLast = periodPayments.length === 1;
          const lines = [
            `Delete rent payment of ${formatCurrency(confirmDelete.amount)} for ${confirmDelete.period_month}?`,
            isLast
              ? 'The commission ledger entry for this period will also be reversed.'
              : `Note: ${periodPayments.length - 1} other payment(s) exist for this period — commission will be retained.`,
          ];
          return lines.join('\n');
        })()}
        onConfirm={() => handleDelete(confirmDelete)}
        onCancel={() => setConfirmDelete(null)}
      />
    </div>
  );
}

