                { label: 'Landlords', desc: 'All landlords with balance summary', fn: () => exportLandlords({ landlords, commissionLedger, landlordPayouts }) },
                { label: 'Expenses', desc: 'All expenses by property', fn: () => exportExpenses({ expenses, properties, landlords }) },
                { label: 'Landlord Payments', desc: 'All payouts to landlords', fn: () => exportLandlordPayouts({ landlordPayouts, landlords }) },
              ].map(item => (
                <button key={item.label} onClick={item.fn}
                  className={`flex items-center justify-between p-4 rounded-lg border text-left transition-colors hover:bg-muted/50 ${item.highlight ? 'border-primary/40 bg-primary/5' : 'border-border'}`}>
                  <div>
                    <p className={`text-sm font-medium ${item.highlight ? 'text-primary' : ''}`}>{item.label}</p>
                    <p className="text-xs text-muted-foreground mt-0.5">{item.desc}</p>
                  </div>
                  <Download className={`w-5 h-5 shrink-0 ml-3 ${item.highlight ? 'text-primary' : 'text-muted-foreground'}`} />
                </button>
              ))}
            </div>
          </div>

          <div className="bg-card rounded-xl border border-border overflow-hidden">
            <div className="px-5 py-4 border-b border-border"><h2 className="font-semibold">Landlord Statement</h2></div>
            <div className="p-5 flex flex-col sm:flex-row gap-3 items-end">
              <div className="space-y-1 flex-1">
                <Label>Select Landlord</Label>
                <Select value={selectedLandlord} onValueChange={setSelectedLandlord}>
                  <SelectTrigger><SelectValue placeholder="Choose a landlord..." /></SelectTrigger>
                  <SelectContent>{landlords.map(l => <SelectItem key={l.id} value={l.id}>{l.name}</SelectItem>)}</SelectContent>
                </Select>
              </div>
              <Button disabled={!selectedLandlord} onClick={() => {
                const landlord = landlords.find(l => l.id === selectedLandlord);
                if (landlord) exportLandlordStatement({ landlord, rentPayments, commissionLedger, expenses, landlordPayouts, properties, tenants });
              }}>
                <Download className="w-4 h-4 mr-2" />Download Statement
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState } from "react";
import { Link, useSearchParams } from "react-router-dom";
import { base44 } from "@/api/base44Client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Lock, Loader2, AlertTriangle } from "lucide-react";
import AuthLayout from "@/components/AuthLayout";

export default function ResetPassword() {
  const [searchParams] = useSearchParams();
  const resetToken = searchParams.get("token");

  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    if (newPassword !== confirmPassword) {
      setError("Passwords do not match");
      return;
    }
    setLoading(true);
    try {
      await base44.auth.resetPassword({ resetToken, newPassword });
      window.location.href = "/login";
    } catch (err) {
      setError(err.message || "Failed to reset password");
    } finally {
      setLoading(false);
    }
  };

  if (!resetToken) {
    return (
      <AuthLayout
        icon={AlertTriangle}
        title="Invalid reset link"
        subtitle="This password reset link is missing or invalid"
        footer={
          <Link to="/forgot-password" className="text-primary font-medium hover:underline">
            Request a new link
          </Link>
        }
      >
        <p className="text-sm text-foreground text-center">
          The link you used appears to be incomplete. Please request a new password reset email.
        </p>
      </AuthLayout>
    );
  }

  return (
    <AuthLayout
      icon={Lock}
      title="New password"
      subtitle="Enter your new password below"
    >
      {error && (
        <div className="mb-4 p-3 rounded-lg bg-destructive/10 text-destructive text-sm">
          {error}
        </div>
      )}
      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="space-y-2">
          <Label htmlFor="password">New Password</Label>
          <div className="relative">
            <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" aria-hidden="true" />
            <Input
              id="password"
              type="password"
              autoComplete="new-password"
              autoFocus
              placeholder="••••••••"
              value={newPassword}
              onChange={(e) => setNewPassword(e.target.value)}
              className="pl-10 h-12"
              required
            />
          </div>
        </div>
        <div className="space-y-2">
          <Label htmlFor="confirm">Confirm Password</Label>
          <div className="relative">
            <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" aria-hidden="true" />
            <Input
              id="confirm"
              type="password"
              autoComplete="new-password"
              placeholder="••••••••"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              className="pl-10 h-12"
              required
            />
          </div>
        </div>
        <Button type="submit" className="w-full h-12 font-medium" disabled={loading}>
          {loading ? (
            <>
              <Loader2 className="w-4 h-4 mr-2 animate-spin" />
              Resetting...
            </>
          ) : (
            "Reset password"
          )}
        </Button>
      </form>
    </AuthLayout>
  );
}

import React, { useMemo, useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { base44 } from '@/api/base44Client';
import { useLandlords, useTenants, useProperties } from '@/hooks/useAllData';
import PageHeader from '@/components/ui/PageHeader';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Mail, Send, Search, CheckCircle2, Loader2, AlertCircle, UserCircle, Building2, Users } from 'lucide-react';

const RECIPIENT_TYPES = [
  { value: 'tenant', label: 'Tenant', icon: Users },
  { value: 'landlord', label: 'Landlord', icon: UserCircle },
  { value: 'custom', label: 'Other email', icon: Mail },
];

export default function SendEmail() {
  const queryClient = useQueryClient();
  const { data: landlords = [] } = useLandlords();
  const { data: tenants = [] } = useTenants();
  const { data: properties = [] } = useProperties();

  const [type, setType] = useState('tenant');
  const [recipientId, setRecipientId] = useState('');
  const [customEmail, setCustomEmail] = useState('');
  const [customName, setCustomName] = useState('');
  const [search, setSearch] = useState('');
  const [subject, setSubject] = useState('');
  const [body, setBody] = useState('');
  const [sending, setSending] = useState(false);
  const [sent, setSent] = useState(false);
  const [error, setError] = useState(null);

  const propById = useMemo(() => {
    const m = {};
    properties.forEach(p => { m[p.id] = p; });
    return m;
  }, [properties]);

  // Build a unified contact list for the chosen type
  const contacts = useMemo(() => {
    if (type === 'landlord') {
      return landlords
        .filter(l => l.email)
        .map(l => ({ id: l.id, name: l.name, email: l.email, sub: l.address || 'Landlord' }));
    }
    if (type === 'tenant') {
      return tenants
        .filter(t => t.email)
        .map(t => {
          const prop = propById[t.property_id];
          return { id: t.id, name: t.name, email: t.email, sub: prop?.address || 'Tenant' };
        });
    }
    return [];
  }, [type, landlords, tenants, propById]);

  const filteredContacts = useMemo(() => {
    if (!search.trim()) return contacts;
    const q = search.toLowerCase();
    return contacts.filter(c =>
      (c.name || '').toLowerCase().includes(q) ||
      (c.email || '').toLowerCase().includes(q) ||
      (c.sub || '').toLowerCase().includes(q)
    );
  }, [contacts, search]);

  const selected = contacts.find(c => c.id === recipientId) || null;

  const toEmail = type === 'custom' ? customEmail.trim() : (selected?.email || '');
  const toName = type === 'custom' ? customName.trim() : (selected?.name || '');

  const reset = () => {
    setSubject(''); setBody(''); setSent(false); setError(null);
    setRecipientId(''); setCustomEmail(''); setCustomName(''); setSearch('');
  };

  const handleSend = async () => {
    setError(null);
    if (!toEmail) { setError('Please choose a recipient with an email address.'); return; }
    if (!subject.trim()) { setError('Please enter a subject.'); return; }
    setSending(true);
    try {
      const me = await base44.auth.me();
      const htmlBody = body
        .split('\n')
        .map(line => line.trim() === '' ? '<br/>' : `<p style="margin:0 0 8px 0;">${line}</p>`)
        .join('\n');
      const res = await base44.functions.invoke('sendEmail', {
        from_name: 'ASA Estates Ltd',
        to: toEmail,
        subject,
        body: `<div style="font-family:Arial,sans-serif;font-size:14px;line-height:1.6;color:#333;max-width:600px;">${htmlBody}</div>`,
      });
      if (res?.data?.error) throw new Error(res.data.error);
      await base44.entities.EmailLog.create({
        recipient_email: toEmail,
        recipient_name: toName || toEmail,
        subject,
        body_preview: body.substring(0, 300),
        type: 'other',
        reference_id: recipientId || '',
        status: 'opened',
        sent_by: me?.email || '',
      });
      queryClient.invalidateQueries({ queryKey: ['email_logs'] });
      setSending(false);
      setSent(true);
    } catch (e) {
      setSending(false);
      setError(e?.message || 'Failed to send email. Please try again.');
    }
  };

  return (
    <div>
      <PageHeader
        title="Send Email"
        description="Compose and send an email to any tenant or landlord directly from ASA Estates. Every send is logged in the Email Log."
      />

      <div className="max-w-3xl space-y-5">
        {sent ? (
          <div className="bg-card border border-emerald-200 rounded-xl p-8 text-center">
            <CheckCircle2 className="w-12 h-12 mx-auto text-emerald-600 mb-3" />
            <p className="font-semibold text-lg text-emerald-700">Email sent successfully</p>
            <p className="text-sm text-muted-foreground mt-1">
              Your email has been sent to <strong>{toName || toEmail}</strong> and logged.
            </p>
            <div className="flex gap-2 justify-center mt-5">
              <Button variant="outline" onClick={reset}>Send another</Button>
            </div>
          </div>
        ) : (
          <div className="bg-card border border-border rounded-xl p-5 space-y-5">
            {/* Recipient type */}
            <div className="space-y-1.5">
              <Label>Recipient type</Label>
              <Select value={type} onValueChange={(v) => { setType(v); setRecipientId(''); setSearch(''); }}>
                <SelectTrigger className="w-full"><SelectValue /></SelectTrigger>
                <SelectContent>
                  {RECIPIENT_TYPES.map(t => (
                    <SelectItem key={t.value} value={t.value}>
                      <span className="flex items-center gap-2"><t.icon className="w-4 h-4" /> {t.label}</span>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Recipient picker */}
            {type !== 'custom' ? (
              <div className="space-y-1.5">
                <Label>Choose {type}</Label>
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                  <Input
                    className="pl-9"
                    placeholder={`Search ${type}s by name, email or property…`}
                    value={search}
                    onChange={e => setSearch(e.target.value)}
                  />
                </div>
                <div className="border border-border rounded-lg max-h-64 overflow-y-auto divide-y divide-border">
                  {filteredContacts.length === 0 && (
                    <p className="px-3 py-6 text-sm text-muted-foreground text-center">
                      No {type}s with an email address{search ? ' match your search' : ''}.
                    </p>
                  )}
                  {filteredContacts.map(c => (
                    <button
                      key={c.id}
                      onClick={() => { setRecipientId(c.id); }}
                      className={`w-full flex items-center gap-3 px-3 py-2.5 text-left transition-colors ${recipientId === c.id ? 'bg-primary/10' : 'hover:bg-muted/50'}`}
                    >
                      {type === 'tenant'
                        ? <Users className="w-4 h-4 text-emerald-600 shrink-0" />
                        : <UserCircle className="w-4 h-4 text-purple-600 shrink-0" />}
                      <div className="min-w-0 flex-1">
                        <p className="text-sm font-medium truncate">{c.name}</p>
                        <p className="text-xs text-muted-foreground truncate">{c.email}</p>
                      </div>
                      <span className="text-xs text-muted-foreground truncate hidden sm:block max-w-[40%]">{c.sub}</span>
                      {recipientId === c.id && <CheckCircle2 className="w-4 h-4 text-primary shrink-0" />}
                    </button>
                  ))}
                </div>
                {contacts.length > 0 && (
                  <p className="text-xs text-muted-foreground">
                    {contacts.length} {type}{contacts.length !== 1 ? 's' : ''} with an email on record.
                  </p>
                )}
              </div>
            ) : (
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <Label>Recipient name</Label>
                  <Input value={customName} onChange={e => setCustomName(e.target.value)} placeholder="e.g. John Smith" />
                </div>
                <div className="space-y-1.5">
                  <Label>Recipient email *</Label>
                  <Input type="email" value={customEmail} onChange={e => setCustomEmail(e.target.value)} placeholder="name@example.com" />
                </div>
              </div>
            )}

            {/* To summary */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <Label>From</Label>
                <Input value="ASA Estates Ltd" disabled className="bg-muted/50" />
              </div>
              <div className="space-y-1.5">
                <Label>To</Label>
                <Input
                  value={toName && toEmail ? `${toName} <${toEmail}>` : (toEmail || '')}
                  disabled
                  className="bg-muted/50"
                  placeholder="Select a recipient"
                />
              </div>
            </div>

            {/* Subject */}
            <div className="space-y-1.5">
              <Label>Subject *</Label>
              <Input value={subject} onChange={e => setSubject(e.target.value)} placeholder="Enter subject" />
            </div>

            {/* Body */}
            <div className="space-y-1.5">
              <Label>Message *</Label>
              <Textarea
                value={body}
                onChange={e => setBody(e.target.value)}
                rows={12}
                className="text-sm"
                placeholder="Type your message here…"
              />
            </div>

            {error && (
              <div className="flex items-start gap-2 rounded-lg border border-destructive/30 bg-destructive/10 px-3 py-2.5 text-sm text-destructive">
                <AlertCircle className="w-4 h-4 mt-0.5 shrink-0" /> {error}
              </div>
            )}

            <div className="flex items-center justify-between gap-3 pt-1">
              <p className="text-xs text-muted-foreground">Sent from ASA Estates Ltd · logged in Email Log.</p>
              <Button onClick={handleSend} disabled={sending || !toEmail || !subject.trim() || !body.trim()}>
                {sending ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <Send className="w-4 h-4 mr-2" />}
                {sending ? 'Sending…' : 'Send Email'}
              </Button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import { base44 } from "@/api/base44Client";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { useToast } from "@/components/ui/use-toast";
import {
  FileText, ChevronLeft, ChevronRight, Check, Loader2, Shield,
  AlertTriangle, CheckCircle, Download
} from "lucide-react";
import SigningField from "@/components/signing/SigningField";
import SignatureModal from "@/components/signing/SignatureModal";
import PDFPageViewer from "@/components/documents/PDFPageViewer";
import moment from "moment";

export default function SignDocument() {
  const { token } = useParams();
  const { toast } = useToast();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [signerData, setSignerData] = useState(null);
  const [documentData, setDocumentData] = useState(null);
  const [fields, setFields] = useState([]);
  const [fieldValues, setFieldValues] = useState({});
  const [consent, setConsent] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const [signatureModal, setSignatureModal] = useState(null);
  const [adoptedSignature, setAdoptedSignature] = useState(null);
  const [adoptedInitials, setAdoptedInitials] = useState(null);
  const [submitting, setSubmitting] = useState(false);
  const [completed, setCompleted] = useState(false);
  const [declined, setDeclined] = useState(false);
  const [numPages, setNumPages] = useState(1);
  const [finalFileUrl, setFinalFileUrl] = useState(null);

  useEffect(() => {
    loadSigningData();
  }, [token]);

  const loadSigningData = async () => {
    try {
      const res = await base44.functions.invoke("validateSignerToken", {
        token,
        action: "view",
        ip_address: "",
        user_agent: navigator.userAgent,
      });

      setSignerData(res.data.signer);
      setDocumentData(res.data.document);
      setFields(res.data.fields);

      // Pre-fill name and date fields
      const prefilled = {};
      for (const field of res.data.fields) {
        if (field.type === "name") prefilled[field.id] = res.data.signer.name;
        if (field.type === "date") prefilled[field.id] = moment().format("MM/DD/YYYY");
      }
      setFieldValues(prefilled);
    } catch (err) {
      setError(err.response?.data?.error || err.message || "Invalid signing link");
    } finally {
      setLoading(false);
    }
  };

  const handleFieldChange = (fieldId, value) => {
    setFieldValues((prev) => ({ ...prev, [fieldId]: value }));
  };

  const handleSignatureClick = (field) => {
    if (field.type === "signature" && adoptedSignature) {
      handleFieldChange(field.id, adoptedSignature);
      return;
    }
    if (field.type === "initials" && adoptedInitials) {
      handleFieldChange(field.id, adoptedInitials);
      return;
    }
    setSignatureModal(field);
  };

  const handleSignatureSave = (dataUrl) => {
    if (!signatureModal) return;
    handleFieldChange(signatureModal.id, dataUrl);
    if (signatureModal.type === "signature") {
      setAdoptedSignature(dataUrl);
      // Auto-fill other signature fields
      fields.filter((f) => f.type === "signature" && f.id !== signatureModal.id).forEach((f) => {
        handleFieldChange(f.id, dataUrl);
      });
    }
    if (signatureModal.type === "initials") {
      setAdoptedInitials(dataUrl);
      fields.filter((f) => f.type === "initials" && f.id !== signatureModal.id).forEach((f) => {
        handleFieldChange(f.id, dataUrl);
      });
    }
  };

  const handleSubmit = async () => {
    const requiredFields = fields.filter((f) => f.required !== false);
    const missing = requiredFields.filter((f) => !fieldValues[f.id]);
    if (missing.length > 0) {
      toast({
        title: "Incomplete",
        description: `Please complete all ${missing.length} required field(s).`,
        variant: "destructive",
      });
      // Navigate to the first missing field's page
      setCurrentPage(missing[0].page);
      return;
    }

    if (!consent) {
      toast({
        title: "Consent required",
        description: "Please agree to electronic signature consent.",
        variant: "destructive",
      });
      return;
    }

    setSubmitting(true);
    try {
      const res = await base44.functions.invoke("validateSignerToken", {
        token,
        action: "sign",
        fieldValues,
        ip_address: "",
        user_agent: navigator.userAgent,
      });
      if (res.data?.final_file_url) {
        setFinalFileUrl(res.data.final_file_url);
      }
      setCompleted(true);
    } catch (err) {
      toast({
        title: "Error",
        description: err.response?.data?.error || "Failed to submit signature",
        variant: "destructive",
      });
    } finally {
      setSubmitting(false);
    }
  };

  const handleDecline = async () => {
    setSubmitting(true);
    try {
      await base44.functions.invoke("validateSignerToken", {
        token,
        action: "decline",
        ip_address: "",
        user_agent: navigator.userAgent,
      });
      setDeclined(true);
    } catch (err) {
      toast({ title: "Error", description: err.message, variant: "destructive" });
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background">
        <div className="text-center">
          <div className="w-8 h-8 border-4 border-primary/20 border-t-primary rounded-full animate-spin mx-auto" />
          <p className="text-sm text-muted-foreground mt-3">Loading document...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background p-4">
        <div className="text-center max-w-sm">
          <div className="w-14 h-14 rounded-2xl bg-red-100 flex items-center justify-center mx-auto mb-4">
            <AlertTriangle className="w-7 h-7 text-red-600" />
          </div>
          <h2 className="text-lg font-semibold text-foreground mb-2">Unable to Load Document</h2>
          <p className="text-sm text-muted-foreground">{error}</p>
        </div>
      </div>
    );
  }

  if (completed) {
    return (
      <div className="min-h-screen bg-background">
        {/* Top bar */}
        <div className="sticky top-0 z-50 bg-white border-b border-border">
          <div className="max-w-4xl mx-auto px-4 h-14 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="w-8 h-8 rounded-lg bg-emerald-100 flex items-center justify-center">
                <CheckCircle className="w-4 h-4 text-emerald-600" />
              </div>
              <div>
                <p className="text-sm font-semibold">{documentData?.title}</p>
                <p className="text-xs text-muted-foreground">Signing complete</p>
              </div>
            </div>
            {finalFileUrl && (
              <a href={finalFileUrl} target="_blank" rel="noopener" download>
                <Button size="sm" className="gap-2">
                  <Download className="w-4 h-4" /> Certificate
                </Button>
              </a>
            )}
          </div>
        </div>

        <div className="max-w-4xl mx-auto px-4 py-6">
          {/* Success banner */}
          <div className="bg-emerald-50 border border-emerald-200 rounded-xl p-4 mb-6 flex items-start gap-3">
            <CheckCircle className="w-5 h-5 text-emerald-600 shrink-0 mt-0.5" />
            <div>
              <p className="text-sm font-medium text-emerald-900">Signing Complete!</p>
              <p className="text-xs text-emerald-700 mt-1">
                You have successfully signed <strong>{documentData?.title}</strong>.
                {finalFileUrl
                  ? " All parties have signed — your certificate with the full audit trail is ready to download."
                  : " You'll receive a copy when all parties have signed."}
              </p>
            </div>
          </div>

          {/* Page navigation */}
          <div className="flex items-center justify-center gap-3 mb-4">
            <Button
              variant="outline"
              size="icon"
              className="h-8 w-8"
              onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
              disabled={currentPage <= 1}
            >
              <ChevronLeft className="w-4 h-4" />
            </Button>
            <span className="text-sm text-muted-foreground">
              Page {currentPage} of {numPages}
            </span>
            <Button
              variant="outline"
              size="icon"
              className="h-8 w-8"
              onClick={() => setCurrentPage((p) => Math.min(numPages, p + 1))}
              disabled={currentPage >= numPages}
            >
              <ChevronRight className="w-4 h-4" />
            </Button>
          </div>

          {/* Document canvas */}
          <div
            className="relative bg-white border border-border rounded-lg shadow-sm mx-auto overflow-hidden"
            style={{ aspectRatio: "8.5 / 11", maxWidth: 700 }}
          >
            <PDFPageViewer
              url={documentData?.original_file_url}
              pageNumber={currentPage}
              onDocumentLoaded={({ numPages: n }) => setNumPages(n)}
            />
          </div>
        </div>
      </div>
    );
  }

  if (declined) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background p-4">
        <div className="text-center max-w-sm">
          <div className="w-14 h-14 rounded-2xl bg-red-100 flex items-center justify-center mx-auto mb-4">
            <AlertTriangle className="w-7 h-7 text-red-600" />
          </div>
          <h2 className="text-lg font-semibold text-foreground mb-2">Document Declined</h2>
          <p className="text-sm text-muted-foreground">You have declined to sign this document.</p>
        </div>
      </div>
    );
  }

  const pageCount = numPages;
  const pageFields = fields.filter((f) => f.page === currentPage);
  const totalRequired = fields.filter((f) => f.required !== false).length;
  const completedCount = fields.filter((f) => f.required !== false && fieldValues[f.id]).length;

  return (
    <div className="min-h-screen bg-background">
      {/* Top bar */}
      <div className="sticky top-0 z-50 bg-white border-b border-border">
        <div className="max-w-4xl mx-auto px-4 h-14 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-lg bg-primary flex items-center justify-center">
              <FileText className="w-4 h-4 text-white" />
            </div>
            <div>
              <p className="text-sm font-semibold">{documentData?.title}</p>
              <p className="text-xs text-muted-foreground">
                Signing as {signerData?.name}
                {signerData?.role_label && ` (${signerData.role_label})`}
              </p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <span className="text-xs text-muted-foreground hidden sm:inline">
              {completedCount}/{totalRequired} fields
            </span>
            <Button variant="outline" size="sm" onClick={handleDecline} disabled={submitting}>
              Decline
            </Button>
            <Button size="sm" onClick={handleSubmit} disabled={submitting} className="gap-1.5">
              {submitting ? <Loader2 className="w-4 h-4 animate-spin" /> : <Check className="w-4 h-4" />}
              Finish
            </Button>
          </div>
        </div>
      </div>

      <div className="max-w-4xl mx-auto px-4 py-6">
        {/* Consent banner */}
        {!consent && (
          <div className="bg-amber-50 border border-amber-200 rounded-xl p-4 mb-6 flex items-start gap-3">
            <Shield className="w-5 h-5 text-amber-600 shrink-0 mt-0.5" />
            <div className="flex-1">
              <p className="text-sm font-medium text-amber-900">Electronic Signature Consent</p>
              <p className="text-xs text-amber-700 mt-1">
                By checking below, you agree to use electronic records and signatures, and consent that your electronic signature is the legal equivalent of your manual signature on this document.
              </p>
              <div className="flex items-center gap-2 mt-3">
                <Checkbox
                  id="consent"
                  checked={consent}
                  onCheckedChange={setConsent}
                />
                <label htmlFor="consent" className="text-sm font-medium text-amber-900 cursor-pointer">
                  I agree to use electronic records and signatures
                </label>
              </div>
            </div>
          </div>
        )}

        {/* Page navigation */}
        <div className="flex items-center justify-center gap-3 mb-4">
          <Button
            variant="outline"
            size="icon"
            className="h-8 w-8"
            onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
            disabled={currentPage <= 1}
          >
            <ChevronLeft className="w-4 h-4" />
          </Button>
          <span className="text-sm text-muted-foreground">
            Page {currentPage} of {pageCount}
          </span>
          <Button
            variant="outline"
            size="icon"
            className="h-8 w-8"
            onClick={() => setCurrentPage((p) => Math.min(pageCount, p + 1))}
            disabled={currentPage >= pageCount}
          >
            <ChevronRight className="w-4 h-4" />
          </Button>
        </div>

        {/* Document canvas */}
        <div
          className="relative bg-white border border-border rounded-lg shadow-sm mx-auto overflow-hidden"
          style={{ aspectRatio: "8.5 / 11", maxWidth: 700 }}
        >
          {/* PDF page render */}
          <PDFPageViewer
            url={documentData?.original_file_url}
            pageNumber={currentPage}
            onDocumentLoaded={({ numPages: n }) => setNumPages(n)}
          />

          {/* Signing fields */}
          {pageFields.map((field) => (
            <SigningField
              key={field.id}
              field={field}
              isActive={false}
              value={fieldValues[field.id]}
              onChange={(value) => handleFieldChange(field.id, value)}
              onFocus={() => {}}
              onSignatureClick={handleSignatureClick}
            />
          ))}
        </div>
      </div>

      {/* Signature Modal */}
      {signatureModal && (
        <SignatureModal
          open={!!signatureModal}
          onClose={() => setSignatureModal(null)}
          onSave={handleSignatureSave}
          type={signatureModal.type}
        />
      )}
    </div>
  );
}

import React, { useMemo, useState } from 'react';
import { base44 } from '@/api/base44Client';
import { useQueryClient } from '@tanstack/react-query';
import { useTasks, useTeamMembers } from '@/hooks/useTasks';
import { useProperties, useTenants, useLandlords } from '@/hooks/useAllData';
import { useRole } from '@/hooks/useRole';
import { logAction } from '@/lib/audit';
import PageHeader from '@/components/ui/PageHeader';
import StatCard from '@/components/ui/StatCard';
import StatusBadge from '@/components/ui/StatusBadge';
import ConfirmDialog from '@/components/ui/ConfirmDialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { ListChecks, Plus, Search, Trash2, Users, Clock, CheckCircle, AlertTriangle, Settings } from 'lucide-react';
import { format, parseISO, isValid } from 'date-fns';
import {
  TASK_TYPES, TASK_TYPE_KEYS, stepsForType, typeLabel, statusColor,
  firstStatus, isDoneStatus, PRIORITY,
} from '@/lib/taskConfig';

const fmtDate = (s) => { try { return format(parseISO(s), 'd MMM yyyy'); } catch { return s; } };
const fmtDateTime = (s) => { try { return format(parseISO(s), 'd MMM yyyy, HH:mm'); } catch { return s; } };
const addDaysStr = (days) => { const d = new Date(); d.setDate(d.getDate() + days); return format(d, 'yyyy-MM-dd'); };

export default function Tasks() {
  const { user, isAdmin } = useRole();
  const queryClient = useQueryClient();
  const { data: tasks } = useTasks();
  const { data: team } = useTeamMembers();
  const { data: properties = [] } = useProperties();
  const { data: tenants = [] } = useTenants();
  const { data: landlords = [] } = useLandlords();

  const [search, setSearch] = useState('');
  const [statusView, setStatusView] = useState('open'); // open | done | all
  const [assigneeFilter, setAssigneeFilter] = useState('all');
  const [typeFilter, setTypeFilter] = useState('all');
  const [editing, setEditing] = useState(null);
  const [detail, setDetail] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(null);
  const [showTeam, setShowTeam] = useState(false);

  const propName = (id) => properties.find(p => p.id === id)?.address || '';
  const tenantName = (id) => tenants.find(t => t.id === id)?.name || '';
  const landlordName = (id) => landlords.find(l => l.id === id)?.name || '';
  const activeMembers = (team || []).filter(m => m.active !== false);

  const filtered = useMemo(() => (tasks || []).filter(t => {
    const done = isDoneStatus(t.type, t.status);
    if (statusView === 'open' && done) return false;
    if (statusView === 'done' && !done) return false;
    if (assigneeFilter !== 'all' && t.assigned_to !== assigneeFilter) return false;
    if (typeFilter !== 'all' && t.type !== typeFilter) return false;
    if (search) {
      const q = search.toLowerCase();
      const hay = [t.title, t.notes, t.assigned_to, propName(t.property_id), tenantName(t.tenant_id)].join(' ').toLowerCase();
      if (!hay.includes(q)) return false;
    }
    return true;
  }), [tasks, statusView, assigneeFilter, typeFilter, search, properties, tenants]);

  const totals = useMemo(() => {
    const all = tasks || [];
    const open = all.filter(t => !isDoneStatus(t.type, t.status));
    const overdue = open.filter(t => t.due_date && t.due_date < format(new Date(), 'yyyy-MM-dd'));
    return { open: open.length, done: all.length - open.length, overdue: overdue.length };
  }, [tasks]);

  const openNew = () => setEditing({
    title: '', type: 'general', status: firstStatus('general'),
    assigned_to: '', priority: 'normal', due_date: '',
    property_id: '', tenant_id: '', landlord_id: '', notes: '', activity_log: [],
  });

  const saveTask = async (data) => {
    const payload = { ...data };
    if (!payload.status) payload.status = firstStatus(payload.type);
    if (isDoneStatus(payload.type, payload.status) && !payload.completed_at) payload.completed_at = new Date().toISOString();
    if (!isDoneStatus(payload.type, payload.status)) payload.completed_at = '';
    // If the remind date changed (or was set), clear the sent stamp so a fresh
    // reminder email will fire for the new date.
    if (data.id) {
      const existing = (tasks || []).find(t => t.id === data.id);
      if (existing && existing.remind_at !== payload.remind_at) payload.reminder_sent_at = '';
    }
    if (data.id) {
      await base44.entities.Task.update(data.id, payload);
      await logAction({ user, action: 'update', entityType: 'Task', entityId: data.id, summary: `Updated task "${data.title}"`, newValue: payload });
    } else {
      const created = await base44.entities.Task.create(payload);
      await logAction({ user, action: 'create', entityType: 'Task', entityId: created?.id, summary: `Created task "${data.title}"`, newValue: payload });
    }
    queryClient.invalidateQueries({ queryKey: ['tasks'] });
    setEditing(null);
  };

  const handleDelete = async (t) => {
    await base44.entities.Task.delete(t.id);
    await logAction({ user, action: 'delete', entityType: 'Task', entityId: t.id, summary: `Deleted task "${t.title}"`, oldValue: t });
    queryClient.invalidateQueries({ queryKey: ['tasks'] });
    setConfirmDelete(null);
    setDetail(null);
  };

  // Advance/set a task's status, appending to the activity log.
  const changeStatus = async (task, toStatus, by, note) => {
    const entry = { at: new Date().toISOString(), by: by || 'Unknown', from_status: task.status || '', to_status: toStatus, note: note || '' };
    const activity_log = [...(task.activity_log || []), entry];
    const payload = { status: toStatus, activity_log };
    if (isDoneStatus(task.type, toStatus)) payload.completed_at = new Date().toISOString();
    else payload.completed_at = '';
    await base44.entities.Task.update(task.id, payload);
    await logAction({ user, action: 'update', entityType: 'Task', entityId: task.id, summary: `Task "${task.title}": ${task.status} → ${toStatus}${by ? ` by ${by}` : ''}` });
    queryClient.invalidateQueries({ queryKey: ['tasks'] });
    setDetail({ ...task, ...payload });
  };

  return (
    <div>
      <PageHeader
        title="Tasks"
        description="Team task board — who's doing what, tied to your properties"
        actions={
          <div className="flex gap-2">
            <Button variant="outline" onClick={() => setShowTeam(true)}><Users className="w-4 h-4 mr-1.5" />Team</Button>
            <Button onClick={openNew}><Plus className="w-4 h-4 mr-1.5" />New Task</Button>
          </div>
        }
      />

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-6">
        <StatCard label="Open" value={totals.open} icon={Clock} color="primary" />
        <StatCard label="Overdue" value={totals.overdue} icon={AlertTriangle} color={totals.overdue > 0 ? 'destructive' : 'success'} />
        <StatCard label="Completed" value={totals.done} icon={CheckCircle} color="success" />
      </div>

      {/* Filters */}
      <div className="flex flex-wrap items-center gap-2 mb-4">
        <div className="flex items-center gap-2 bg-card border border-border rounded-lg px-3 py-2 flex-1 min-w-[220px]">
          <Search className="w-4 h-4 text-muted-foreground" />
          <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search tasks, property, assignee…" className="flex-1 bg-transparent outline-none text-sm" />
        </div>
        {['open', 'done', 'all'].map(v => (
          <button key={v} onClick={() => setStatusView(v)}
            className={`px-3 py-1.5 rounded-lg text-xs font-semibold capitalize ${statusView === v ? 'bg-primary text-white' : 'bg-muted text-muted-foreground hover:text-foreground'}`}>{v}</button>
        ))}
        <Select value={assigneeFilter} onValueChange={setAssigneeFilter}>
          <SelectTrigger className="w-40 h-9"><SelectValue placeholder="Assignee" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All assignees</SelectItem>
            {activeMembers.map(m => <SelectItem key={m.id} value={m.name}>{m.name}</SelectItem>)}
          </SelectContent>
        </Select>
        <Select value={typeFilter} onValueChange={setTypeFilter}>
          <SelectTrigger className="w-40 h-9"><SelectValue placeholder="Type" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All types</SelectItem>
            {TASK_TYPE_KEYS.map(k => <SelectItem key={k} value={k}>{typeLabel(k)}</SelectItem>)}
          </SelectContent>
        </Select>
      </div>

      {/* Task list */}
      <div className="bg-card rounded-xl border border-border overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm min-w-[820px]">
            <thead>
              <tr className="bg-muted/50 text-xs text-muted-foreground text-left">
                <th className="px-4 py-3 font-medium">Task</th>
                <th className="px-4 py-3 font-medium">Type</th>
                <th className="px-4 py-3 font-medium">Linked to</th>
                <th className="px-4 py-3 font-medium">Assignee</th>
                <th className="px-4 py-3 font-medium">Due</th>
                <th className="px-4 py-3 font-medium">Status</th>
                <th className="px-4 py-3 font-medium text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {filtered.map(t => {
                const overdue = t.due_date && t.due_date < format(new Date(), 'yyyy-MM-dd') && !isDoneStatus(t.type, t.status);
                const link = propName(t.property_id) || tenantName(t.tenant_id) || landlordName(t.landlord_id) || '—';
                return (
                  <tr key={t.id} className="border-t border-border hover:bg-muted/30">
                    <td className="px-4 py-3">
                      <button onClick={() => setDetail(t)} className="font-medium text-left hover:underline">{t.title}</button>
                      {t.priority === 'high' && <span className="ml-2 text-[10px] font-semibold text-red-600">HIGH</span>}
                    </td>
                    <td className="px-4 py-3"><StatusBadge color="blue">{typeLabel(t.type)}</StatusBadge></td>
                    <td className="px-4 py-3 text-xs text-muted-foreground truncate max-w-[180px]">{link}</td>
                    <td className="px-4 py-3 text-xs">{t.assigned_to || <span className="text-muted-foreground">Unassigned</span>}</td>
                    <td className={`px-4 py-3 text-xs ${overdue ? 'text-red-600 font-semibold' : 'text-muted-foreground'}`}>
                      {t.due_date ? fmtDate(t.due_date) : '—'}
                      {t.remind_at && <div className="text-[10px] text-amber-600">🔔 {fmtDate(t.remind_at)}</div>}
                    </td>
                    <td className="px-4 py-3"><StatusBadge color={statusColor(t.type, t.status)}>{t.status || firstStatus(t.type)}</StatusBadge></td>
                    <td className="px-4 py-3">
                      <div className="flex gap-1 justify-end">
                        <Button variant="ghost" size="sm" onClick={() => setDetail(t)}>Open</Button>
                        {isAdmin && <Button variant="ghost" size="sm" onClick={() => setConfirmDelete(t)}><Trash2 className="w-4 h-4 text-red-500" /></Button>}
                      </div>
                    </td>
                  </tr>
                );
              })}
              {filtered.length === 0 && (
                <tr><td colSpan="7" className="px-4 py-12 text-center text-muted-foreground text-sm">
                  {search || assigneeFilter !== 'all' || typeFilter !== 'all' ? 'No tasks match your filters.' : 'No tasks yet. Click “New Task” to add one.'}
                </td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {editing && (
        <TaskForm
          data={editing} onChange={setEditing} onSubmit={saveTask} onCancel={() => setEditing(null)}
          properties={properties} tenants={tenants} landlords={landlords} members={activeMembers}
        />
      )}

      {detail && (
        <TaskDetail
          task={(tasks || []).find(t => t.id === detail.id) || detail}
          onClose={() => setDetail(null)}
          onEdit={() => { setEditing({ ...detail }); setDetail(null); }}
          onChangeStatus={changeStatus}
          members={activeMembers}
          propName={propName} tenantName={tenantName} landlordName={landlordName}
          defaultBy={user?.full_name || user?.name || ''}
        />
      )}

      {showTeam && (
        <TeamManager team={team || []} onClose={() => setShowTeam(false)} user={user}
          onChanged={() => queryClient.invalidateQueries({ queryKey: ['team_members'] })} />
      )}

      <ConfirmDialog
        open={!!confirmDelete}
        title="Delete task?"
        description={`Remove "${confirmDelete?.title}" and its history?`}
        onConfirm={() => handleDelete(confirmDelete)}
        onCancel={() => setConfirmDelete(null)}
      />
    </div>
  );
}

function TaskForm({ data, onChange, onSubmit, onCancel, properties, tenants, landlords, members }) {
  const [submitting, setSubmitting] = useState(false);
  const set = (patch) => onChange({ ...data, ...patch });
  const steps = stepsForType(data.type);

  const submit = async (e) => {
    e.preventDefault();
    if (!data.title?.trim()) return;
    setSubmitting(true);
    try { await onSubmit(data); } finally { setSubmitting(false); }
  };

  // Tenants filtered to the chosen property (if any) for convenience.
  const tenantOptions = data.property_id ? tenants.filter(t => t.property_id === data.property_id) : tenants;

  return (
    <Dialog open onOpenChange={(o) => { if (!o) onCancel(); }}>
      <DialogContent className="max-w-lg max-h-[90vh] overflow-y-auto">
        <DialogHeader><DialogTitle>{data.id ? 'Edit task' : 'New task'}</DialogTitle></DialogHeader>
        <form onSubmit={submit} className="space-y-4 pt-1">
          <div className="space-y-1.5">
            <Label className="text-xs">Title *</Label>
            <Input value={data.title} onChange={e => set({ title: e.target.value })} placeholder="e.g. Serve rent increase letter" autoFocus />
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label className="text-xs">Type</Label>
              <Select value={data.type} onValueChange={v => set({ type: v, status: firstStatus(v) })}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>{TASK_TYPE_KEYS.map(k => <SelectItem key={k} value={k}>{typeLabel(k)}</SelectItem>)}</SelectContent>
              </Select>
            </div>
            <div className="space-y-1.5">
              <Label className="text-xs">Status</Label>
              <Select value={data.status || steps[0]} onValueChange={v => set({ status: v })}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>{steps.map(s => <SelectItem key={s} value={s}>{s}</SelectItem>)}</SelectContent>
              </Select>
            </div>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label className="text-xs">Assigned to</Label>
              <Select value={data.assigned_to || '__none__'} onValueChange={v => set({ assigned_to: v === '__none__' ? '' : v })}>
                <SelectTrigger><SelectValue placeholder="Unassigned" /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="__none__">Unassigned</SelectItem>
                  {members.map(m => <SelectItem key={m.id} value={m.name}>{m.name}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1.5">
              <Label className="text-xs">Priority</Label>
              <Select value={data.priority} onValueChange={v => set({ priority: v })}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>{Object.entries(PRIORITY).map(([k, v]) => <SelectItem key={k} value={k}>{v.label}</SelectItem>)}</SelectContent>
              </Select>
            </div>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label className="text-xs">Due date</Label>
              <Input type="date" value={data.due_date || ''} onChange={e => set({ due_date: e.target.value })} />
            </div>
            <div className="space-y-1.5">
              <Label className="text-xs">Property</Label>
              <Select value={data.property_id || '__none__'} onValueChange={v => set({ property_id: v === '__none__' ? '' : v, tenant_id: '' })}>
                <SelectTrigger><SelectValue placeholder="None" /></SelectTrigger>
                <SelectContent className="max-h-64">
                  <SelectItem value="__none__">None</SelectItem>
                  {properties.map(p => <SelectItem key={p.id} value={p.id}>{p.address}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label className="text-xs">Tenant</Label>
              <Select value={data.tenant_id || '__none__'} onValueChange={v => set({ tenant_id: v === '__none__' ? '' : v })}>
                <SelectTrigger><SelectValue placeholder="None" /></SelectTrigger>
                <SelectContent className="max-h-64">
                  <SelectItem value="__none__">None</SelectItem>
                  {tenantOptions.map(t => <SelectItem key={t.id} value={t.id}>{t.name}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1.5">
              <Label className="text-xs">Landlord</Label>
              <Select value={data.landlord_id || '__none__'} onValueChange={v => set({ landlord_id: v === '__none__' ? '' : v })}>
                <SelectTrigger><SelectValue placeholder="None" /></SelectTrigger>
                <SelectContent className="max-h-64">
                  <SelectItem value="__none__">None</SelectItem>
                  {landlords.map(l => <SelectItem key={l.id} value={l.id}>{l.name}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
          </div>
          <div className="space-y-1.5">
            <Label className="text-xs">Notes</Label>
            <Textarea rows={2} value={data.notes} onChange={e => set({ notes: e.target.value })} />
          </div>
          {/* Reminder / check-again */}
          <div className="space-y-1.5 rounded-lg border border-amber-200 bg-amber-50/50 p-3">
            <Label className="text-xs font-semibold text-amber-900">Remind me to check again</Label>
            <div className="flex flex-wrap gap-1.5">
              {[['+2 weeks', 14], ['+1 month', 30], ['+2 months', 61], ['+3 months', 91]].map(([lbl, days]) => (
                <button key={lbl} type="button" onClick={() => set({ remind_at: addDaysStr(days) })}
                  className="px-2 py-1 rounded text-[11px] font-medium bg-white border border-amber-300 text-amber-800 hover:bg-amber-100">{lbl}</button>
              ))}
              {data.remind_at && (
                <button type="button" onClick={() => set({ remind_at: '', reminder_note: '' })}
                  className="px-2 py-1 rounded text-[11px] font-medium text-red-600 hover:bg-red-50">Clear</button>
              )}
            </div>
            <div className="grid grid-cols-2 gap-2">
              <Input type="date" value={data.remind_at || ''} onChange={e => set({ remind_at: e.target.value })} />
              <Input placeholder="Reminder note (optional)" value={data.reminder_note || ''} onChange={e => set({ reminder_note: e.target.value })} />
            </div>
            {data.remind_at && <p className="text-[11px] text-amber-700">You'll get an email on {fmtDate(data.remind_at)} to check this task.</p>}
          </div>
          <div className="flex gap-2 justify-end pt-1">
            <Button type="button" variant="outline" onClick={onCancel} disabled={submitting}>Cancel</Button>
            <Button type="submit" disabled={submitting || !data.title?.trim()}>{submitting ? 'Saving…' : (data.id ? 'Save' : 'Create task')}</Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

function TaskDetail({ task, onClose, onEdit, onChangeStatus, members, propName, tenantName, landlordName, defaultBy }) {
  const steps = stepsForType(task.type);
  const [by, setBy] = useState(defaultBy || (members[0]?.name || ''));
  const [note, setNote] = useState('');
  const [saving, setSaving] = useState(false);

  const doChange = async (toStatus) => {
    if (toStatus === task.status) return;
    setSaving(true);
    try { await onChangeStatus(task, toStatus, by, note); setNote(''); } finally { setSaving(false); }
  };

  const link = propName(task.property_id) || tenantName(task.tenant_id) || landlordName(task.landlord_id);

  return (
    <Dialog open onOpenChange={(o) => { if (!o) onClose(); }}>
      <DialogContent className="max-w-lg max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center justify-between gap-3 pr-6">
            <span>{task.title}</span>
            <Button size="sm" variant="outline" onClick={onEdit}>Edit</Button>
          </DialogTitle>
        </DialogHeader>

        <div className="flex flex-wrap gap-2 text-xs mb-3">
          <StatusBadge color="blue">{typeLabel(task.type)}</StatusBadge>
          <StatusBadge color={statusColor(task.type, task.status)}>{task.status || steps[0]}</StatusBadge>
          {task.assigned_to && <span className="px-2 py-1 rounded bg-muted">{task.assigned_to}</span>}
          {task.due_date && <span className="px-2 py-1 rounded bg-muted">Due {fmtDate(task.due_date)}</span>}
          {link && <span className="px-2 py-1 rounded bg-muted truncate max-w-[220px]">{link}</span>}
        </div>
        {task.notes && <p className="text-sm text-muted-foreground mb-4">{task.notes}</p>}

        {/* Status stepper */}
        <div className="mb-4">
          <p className="text-xs font-semibold mb-2">Move to status</p>
          <div className="flex flex-wrap gap-1.5">
            {steps.map(s => (
              <button key={s} disabled={saving} onClick={() => doChange(s)}
                className={`px-2.5 py-1.5 rounded-lg text-xs font-medium transition-colors ${s === task.status ? 'bg-primary text-white cursor-default' : 'bg-muted text-muted-foreground hover:bg-muted/70'}`}>
                {s}
              </button>
            ))}
          </div>
          <div className="grid grid-cols-2 gap-2 mt-2">
            <Select value={by || '__none__'} onValueChange={v => setBy(v === '__none__' ? '' : v)}>
              <SelectTrigger className="h-8 text-xs"><SelectValue placeholder="Done by…" /></SelectTrigger>
              <SelectContent>
                <SelectItem value="__none__">Done by…</SelectItem>
                {members.map(m => <SelectItem key={m.id} value={m.name}>{m.name}</SelectItem>)}
              </SelectContent>
            </Select>
            <Input className="h-8 text-xs" placeholder="Note (optional)" value={note} onChange={e => setNote(e.target.value)} />
          </div>
          <p className="text-[11px] text-muted-foreground mt-1">Pick who did it and an optional note, then tap a status above.</p>
        </div>

        {/* Activity timeline */}
        <div>
          <p className="text-xs font-semibold mb-2">Activity</p>
          {(!task.activity_log || task.activity_log.length === 0) ? (
            <p className="text-xs text-muted-foreground">No status changes yet.</p>
          ) : (
            <div className="space-y-2">
              {[...task.activity_log].reverse().map((a, i) => (
                <div key={i} className="flex gap-2 text-xs border-l-2 border-primary/40 pl-3 py-0.5">
                  <div>
                    <span className="font-medium">{a.by || 'Someone'}</span>
                    <span className="text-muted-foreground"> moved {a.from_status ? `${a.from_status} → ` : 'to '}<span className="font-medium text-foreground">{a.to_status}</span></span>
                    {a.note && <div className="text-muted-foreground italic">“{a.note}”</div>}
                    <div className="text-[10px] text-muted-foreground">{fmtDateTime(a.at)}</div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

function TeamManager({ team, onClose, onChanged, user }) {
  const [name, setName] = useState('');
  const [role, setRole] = useState('');
  const [busy, setBusy] = useState(false);

  const add = async () => {
    if (!name.trim()) return;
    setBusy(true);
    try {
      await base44.entities.TeamMember.create({ name: name.trim(), role: role.trim(), active: true });
      setName(''); setRole('');
      await onChanged?.();
    } finally { setBusy(false); }
  };
  const toggle = async (m) => { await base44.entities.TeamMember.update(m.id, { active: m.active === false }); await onChanged?.(); };
  const remove = async (m) => { await base44.entities.TeamMember.delete(m.id); await onChanged?.(); };

  return (
    <Dialog open onOpenChange={(o) => { if (!o) onClose(); }}>
      <DialogContent className="max-w-md">
        <DialogHeader><DialogTitle>Team members</DialogTitle></DialogHeader>
        <div className="space-y-3 pt-1">
          <div className="flex gap-2">
            <Input placeholder="Name" value={name} onChange={e => setName(e.target.value)} />
            <Input placeholder="Role (optional)" value={role} onChange={e => setRole(e.target.value)} className="w-32" />
            <Button onClick={add} disabled={busy || !name.trim()}>Add</Button>
          </div>
          <div className="divide-y divide-border">
            {team.length === 0 && <p className="text-sm text-muted-foreground py-3">No team members yet. Add names above to use them as assignees.</p>}
            {team.map(m => (
              <div key={m.id} className="flex items-center justify-between py-2">
                <div>
                  <span className={`text-sm ${m.active === false ? 'line-through text-muted-foreground' : ''}`}>{m.name}</span>
                  {m.role && <span className="text-xs text-muted-foreground ml-2">{m.role}</span>}
                </div>
                <div className="flex gap-1">
                  <Button variant="ghost" size="sm" onClick={() => toggle(m)}>{m.active === false ? 'Enable' : 'Disable'}</Button>
                  <Button variant="ghost" size="sm" onClick={() => remove(m)}><Trash2 className="w-4 h-4 text-red-500" /></Button>
                </div>
              </div>
            ))}
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState } from 'react';
import { useTenants, useProperties, useLandlords, useRentPayments, useCommissionLedger, useCommissionAgreements, useRentHistoryAll } from '@/hooks/useAllData';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { base44 } from '@/api/base44Client';
import PageHeader from '@/components/ui/PageHeader';
import StatusBadge from '@/components/ui/StatusBadge';
import StatCard from '@/components/ui/StatCard';
import { formatCurrency, calculateArrears, calculateCommission, calculateRefundDue } from '@/lib/computations';
import { buildTenantInvoices } from '@/lib/invoices';
import { Link } from 'react-router-dom';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { ArrowLeft, Banknote, AlertTriangle, Plus, TrendingUp, FileDown, ShieldCheck, Wallet } from 'lucide-react';
import { format, parseISO } from 'date-fns';
import RentIncreaseModal from '@/components/tenant/RentIncreaseModal';
import RentHistoryTable from '@/components/tenant/RentHistoryTable';
import DepositModal from '@/components/tenant/DepositModal';

export default function TenantDetail() {
  const urlParams = new URLSearchParams(window.location.search);
  const id = urlParams.get('id');
  const queryClient = useQueryClient();
  const [showRentModal, setShowRentModal] = useState(false);
  const [showIncreaseModal, setShowIncreaseModal] = useState(false);
  const [showDepositModal, setShowDepositModal] = useState(false);
  const [rentData, setRentData] = useState(null);
  const [saving, setSaving] = useState(false);
  const [generatingDoc, setGeneratingDoc] = useState(false);

  const { data: tenants } = useTenants();
  const { data: properties } = useProperties();
  const { data: landlords } = useLandlords();
  const { data: rentPayments } = useRentPayments();
  const { data: ledger } = useCommissionLedger();
  const { data: agreements } = useCommissionAgreements();
  const { data: rentHistoryAll = [] } = useRentHistoryAll();

  const { data: rentHistory = [], refetch: refetchHistory } = useQuery({
    queryKey: ['rent_history', id],
    queryFn: () => base44.entities.RentHistory.filter({ tenant_id: id }),
    enabled: !!id,
  });

  const tenant = tenants.find(t => t.id === id);
  if (!tenant) return <div className="p-8 text-center text-muted-foreground">Tenant not found</div>;

  const property = properties.find(p => p.id === tenant.property_id);
  const landlord = landlords.find(l => l.id === property?.landlord_id);
  const tPayments = rentPayments.filter(p => p.tenant_id === id);
  const totalPaid = tPayments.reduce((s, p) => s + (p.amount || 0), 0);
  const arrears = calculateArrears(tenant, tPayments, rentHistory);
  const tenantInvoices = buildTenantInvoices({ tenants: tenants || [], properties: properties || [], landlords: landlords || [], rentPayments: rentPayments || [], rentHistoryAll }).filter(inv => inv.tenant_id === id);
  const refund = calculateRefundDue(tenant, tenantInvoices);
  const showRefund = tenant.status === 'ended' && refund.total > 0;

  const paymentIds = new Set(tPayments.map(p => p.id));
  const tLedger = ledger.filter(e => paymentIds.has(e.rent_payment_id));
  const totalCommission = tLedger.reduce((s, e) => s + (e.commission_amount || 0), 0);
  const totalLandlordShare = tLedger.reduce((s, e) => s + (e.landlord_share || 0), 0);

  const openRentModal = () => {
    setRentData({
      amount: tenant.monthly_rent || '',
      payment_date: format(new Date(), 'yyyy-MM-dd'),
      period_month: format(new Date(), 'yyyy-MM'),
      method: 'bank_transfer',
      notes: '',
    });
    setShowRentModal(true);
  };

  // Settle a month's rent FROM the held deposit. Defaults to the tenant's most
  // recent unpaid invoice month and the deposit amount (capped at the rent due),
  // so the last month's rent shows as paid with no cash actually changing hands.
  const openDepositRentModal = () => {
    const unpaid = [...tenantInvoices]
      .filter(inv => !inv.is_upcoming && (inv.balance_due || 0) > 0)
      .sort((a, b) => b.period_month.localeCompare(a.period_month));
    const target = unpaid[0] || null;
    const rentDue = target ? (target.balance_due || target.rent_amount || tenant.monthly_rent) : (tenant.monthly_rent || 0);
    const deposit = Number(tenant.deposit || 0);
    const amount = deposit > 0 ? Math.min(deposit, rentDue) : rentDue;
    setRentData({
      amount: amount || '',
      payment_date: format(new Date(), 'yyyy-MM-dd'),
      period_month: target ? target.period_month : format(new Date(), 'yyyy-MM'),
      method: 'deposit',
      notes: 'Last month rent settled from deposit',
    });
    setShowRentModal(true);
  };

  const handleDownloadAgreement = async () => {
    if (generatingDoc) return;
    setGeneratingDoc(true);
    try {
      const response = await base44.functions.invoke('generateTenancyAgreement', {
        tenant_name: tenant.name,
        tenant_email: tenant.email || '',
        tenant_phone: tenant.phone || '',
        property_address: property?.address || '',
        landlord_name: landlord?.name || '',
        monthly_rent: tenant.monthly_rent,
        deposit: tenant.deposit || 0,
        lease_start: tenant.lease_start || '',
        payment_day: property?.payment_day || 1,
        unit_description: tenant.unit_description || '',
      });

      const binary = atob(response.data.base64);
      const bytes = new Uint8Array(binary.length);
      for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
      const blob = new Blob([bytes], {
        type: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `Tenancy_Agreement_${(tenant.name || 'Tenant').replace(/[^a-zA-Z0-9 ]/g, '').trim().replace(/ /g, '_')}.docx`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    } catch (err) {
      console.error('Failed to generate agreement:', err);
      alert('Failed to generate agreement. Please try again.');
    } finally {
      setGeneratingDoc(false);
    }
  };

  const handleRentSubmit = async (e) => {
    e.preventDefault();
    if (saving) return;
    setSaving(true);
    const payment = {
      ...rentData,
      amount: Number(rentData.amount),
      tenant_id: tenant.id,
      property_id: tenant.property_id,
      landlord_id: property?.landlord_id || '',
    };
    const created = await base44.entities.RentPayment.create(payment);
    // Auto-create commission entry
    const agree = agreements.find(a => a.landlord_id === payment.landlord_id && (!a.property_id || a.property_id === payment.property_id));
    if (agree) {
      const { commission: commissionAmount, landlordShare } = calculateCommission(payment.amount, agree);
      await base44.entities.CommissionLedger.create({
        rent_payment_id: created.id,
        landlord_id: payment.landlord_id,
        property_id: payment.property_id,
        period_month: payment.period_month,
        rent_amount: payment.amount,
        commission_amount: commissionAmount,
        landlord_share: landlordShare,
        commission_type: agree.type,
        commission_rate: agree.value,
        date: payment.payment_date,
      });
    }
    queryClient.invalidateQueries({ queryKey: ['rent_payments'] });
    queryClient.invalidateQueries({ queryKey: ['commission_ledger'] });
    setSaving(false);
    setShowRentModal(false);
  };

  return (
    <div>
      <PageHeader
        title={tenant.name}
        description={`${tenant.email || ''} ${tenant.phone ? `• ${tenant.phone}` : ''}`}
        actions={
          <div className="flex gap-2">
            <Button size="sm" variant="outline" onClick={() => setShowIncreaseModal(true)}>
              <TrendingUp className="w-4 h-4 mr-1" />Increase Rent
            </Button>
            <Button size="sm" variant="outline" onClick={handleDownloadAgreement} disabled={generatingDoc}>
              <FileDown className="w-4 h-4 mr-1" />{generatingDoc ? 'Generating...' : 'Download Agreement'}
            </Button>
            <Button size="sm" variant="outline" onClick={openDepositRentModal} title="Settle a month of rent from the held deposit"><Wallet className="w-4 h-4 mr-1" />Pay from Deposit</Button>
            <Button size="sm" onClick={openRentModal}><Plus className="w-4 h-4 mr-1" />Record Rent</Button>
            <Link to="/Tenants"><Button variant="outline" size="sm"><ArrowLeft className="w-4 h-4 mr-1" />Back</Button></Link>
          </div>
        }
      />

      {showRefund && (
        <div className="mb-6 rounded-xl border border-emerald-200 bg-emerald-50 px-5 py-4">
          <div className="flex items-start justify-between gap-4 flex-wrap">
            <div>
              <p className="text-sm font-semibold text-emerald-800">Refund due to tenant on move-out</p>
              <p className="text-xs text-emerald-700 mt-0.5">
                {refund.rentOverpaid > 0 && <>Rent overpaid: {formatCurrency(refund.rentOverpaid)}</>}
                {refund.rentOverpaid > 0 && refund.deposit > 0 && <> · </>}
                {refund.deposit > 0 && <>Deposit: {formatCurrency(refund.deposit)}</>}
              </p>
            </div>
            <div className="text-right">
              <p className="text-2xl font-bold text-emerald-700 figure">{formatCurrency(refund.total)}</p>
              <p className="text-[11px] uppercase tracking-wider text-emerald-600 font-semibold">Total to return</p>
            </div>
          </div>
        </div>
      )}

      {/* Quick Rent Modal */}
      <Dialog open={showRentModal} onOpenChange={v => { if (!v) setShowRentModal(false); }}>
        <DialogContent className="max-w-md">
          <DialogHeader><DialogTitle>Record Rent Payment — {tenant.name}</DialogTitle></DialogHeader>
          {rentData && (
            <form onSubmit={handleRentSubmit} className="space-y-4">
              <div className="bg-blue-50 border border-blue-200 rounded-lg px-4 py-2.5 text-xs text-blue-800 space-y-0.5">
                <p><span className="font-semibold">Property:</span> {property?.address?.split(',')[0] || '-'}</p>
                <p><span className="font-semibold">Landlord:</span> {landlord?.name || '-'}</p>
                {arrears > 0 && <p className="text-red-600 font-semibold">Outstanding arrears: {formatCurrency(arrears)}</p>}
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1">
                  <Label>Amount (£)</Label>
                  <Input type="number" min="0" step="0.01" value={rentData.amount} onChange={e => setRentData(d => ({...d, amount: e.target.value}))} required />
                </div>
                <div className="space-y-1">
                  <Label>Date</Label>
                  <Input type="date" value={rentData.payment_date} onChange={e => setRentData(d => ({...d, payment_date: e.target.value}))} required />
                </div>
                <div className="space-y-1">
                  <Label>Period</Label>
                  <div className="flex gap-2">
              <Select
                value={rentData.period_month ? rentData.period_month.split('-')[1] : ''}
                onValueChange={v => {
                  const yr = (rentData.period_month || format(new Date(), 'yyyy-MM')).split('-')[0];
                  v => setRentData(d => ({...d, period_month: v}))(`${yr}-${v}`);
                }}
              >
                <SelectTrigger className="w-36"><SelectValue placeholder="Month" /></SelectTrigger>
                <SelectContent>
                  {['01','02','03','04','05','06','07','08','09','10','11','12'].map((m, i) => (
                    <SelectItem key={m} value={m}>
                      {['January','February','March','April','May','June','July','August','September','October','November','December'][i]}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Select
                value={rentData.period_month ? rentData.period_month.split('-')[0] : ''}
                onValueChange={v => {
                  const mo = (rentData.period_month || format(new Date(), 'yyyy-MM')).split('-')[1] || '01';
                  v => setRentData(d => ({...d, period_month: v}))(`${v}-${mo}`);
                }}
              >
                <SelectTrigger className="w-28"><SelectValue placeholder="Year" /></SelectTrigger>
                <SelectContent>
                  {Array.from({ length: 15 }, (_, i) => String(new Date().getFullYear() - 5 + i)).map(y => (
                    <SelectItem key={y} value={y}>{y}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
                </div>
                <div className="space-y-1">
                  <Label>Method</Label>
                  <Select value={rentData.method} onValueChange={v => setRentData(d => ({...d, method: v}))}>
                    <SelectTrigger><SelectValue /></SelectTrigger>
                    <SelectContent>
                      {['bank_transfer','cash','card','standing_order','deposit','other'].map(m => <SelectItem key={m} value={m}>{m.replace(/_/g,' ')}</SelectItem>)}
                    </SelectContent>
                  </Select>
                </div>
              </div>
              <div className="flex gap-2 justify-end">
                <Button type="button" variant="outline" onClick={() => setShowRentModal(false)}>Cancel</Button>
                <Button type="submit" disabled={saving}>{saving ? 'Saving...' : 'Save Payment'}</Button>
              </div>
            </form>
          )}
        </DialogContent>
      </Dialog>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
        <StatCard label="Monthly Rent" value={formatCurrency(tenant.monthly_rent)} icon={Banknote} />
        <StatCard label="Total Paid" value={formatCurrency(totalPaid)} icon={Banknote} color="success" />
        <StatCard label="Arrears" value={formatCurrency(arrears)} icon={AlertTriangle} color={arrears > 0 ? 'destructive' : 'success'} />
        <StatCard label="Commission Generated" value={formatCurrency(totalCommission)} color="primary" />
      </div>

      {/* Linked Details */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-8">
        <div className="bg-card border border-border rounded-xl p-5">
          <h3 className="text-sm font-semibold mb-3">Property</h3>
          {property ? (
            <Link to={`/PropertyDetail?id=${property.id}`} className="text-primary hover:underline font-medium">{property.address}</Link>
          ) : <p className="text-muted-foreground">Not linked</p>}
          <p className="text-xs text-muted-foreground mt-1 capitalize">{property?.type} • {formatCurrency(property?.monthly_rent)}/mo</p>
        </div>
        <div className="bg-card border border-border rounded-xl p-5">
          <h3 className="text-sm font-semibold mb-3">Landlord</h3>
          {landlord ? (
            <Link to={`/LandlordDetail?id=${landlord.id}`} className="text-primary hover:underline font-medium">{landlord.name}</Link>
          ) : <p className="text-muted-foreground">Not linked</p>}
          <p className="text-xs text-muted-foreground mt-1">{landlord?.email || ''}</p>
        </div>
      </div>

      {/* Lease Info */}
      <div className="bg-card border border-border rounded-xl p-5 mb-8">
        <h3 className="text-sm font-semibold mb-3">Lease Details</h3>
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 text-sm">
          <div>
            <p className="text-muted-foreground">Start</p>
            <p className="font-medium">{tenant.lease_start ? format(parseISO(tenant.lease_start), 'dd MMM yyyy') : '-'}</p>
          </div>
          <div>
            <p className="text-muted-foreground">End</p>
            <p className="font-medium">{tenant.lease_end ? format(parseISO(tenant.lease_end), 'dd MMM yyyy') : 'Ongoing'}</p>
          </div>
          <div>
            <p className="text-muted-foreground">Deposit</p>
            <p className="font-medium">{formatCurrency(tenant.deposit)}</p>
          </div>
          <div>
            <p className="text-muted-foreground">Status</p>
            <StatusBadge color={tenant.status === 'active' ? 'green' : tenant.status === 'notice' ? 'yellow' : 'gray'}>{tenant.status}</StatusBadge>
          </div>
        </div>
      </div>

      <DepositModal open={showDepositModal} onClose={() => setShowDepositModal(false)} tenant={tenant} />

      <RentIncreaseModal
        open={showIncreaseModal}
        onClose={() => setShowIncreaseModal(false)}
        tenant={tenant}
        currentRent={tenant.monthly_rent}
        rentHistory={rentHistory}
        onSuccess={() => {
          queryClient.invalidateQueries({ queryKey: ['tenants'] });
          refetchHistory();
        }}
      />

      {/* Rent History */}
      <div className="mb-8">
        <h2 className="text-sm font-semibold text-foreground mb-3">Rent History</h2>
        <RentHistoryTable
          records={rentHistory}
          tenant={tenant}
          onChanged={async () => {
            await refetchHistory();
            await queryClient.invalidateQueries({ queryKey: ['tenants'] });
            await queryClient.invalidateQueries({ queryKey: ['rent_history_all'] });
            await queryClient.invalidateQueries({ queryKey: ['rent_payments'] });
          }}
        />
      </div>

      {/* Payment History */}
      <div className="mb-8">
        <h2 className="text-sm font-semibold text-foreground mb-3">Payment History</h2>
        <div className="bg-card rounded-xl border border-border overflow-hidden">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-muted/50">
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Date</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Amount</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Period</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Method</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Commission</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Landlord Share</th>
              </tr>
            </thead>
            <tbody>
              {tPayments.map(rp => {
                const entry = tLedger.find(e => e.rent_payment_id === rp.id);
                return (
                  <tr key={rp.id} className="border-t border-border hover:bg-muted/30 transition-colors">
                    <td className="px-5 py-3 text-muted-foreground">{rp.payment_date ? format(parseISO(rp.payment_date), 'dd MMM yyyy') : '-'}</td>
                    <td className="px-5 py-3 font-medium">{formatCurrency(rp.amount)}</td>
                    <td className="px-5 py-3">{rp.period_month}</td>
                    <td className="px-5 py-3"><StatusBadge color="blue">{rp.method?.replace(/_/g, ' ')}</StatusBadge></td>
                    <td className="px-5 py-3 text-primary">{entry ? formatCurrency(entry.commission_amount) : '-'}</td>
                    <td className="px-5 py-3">{entry ? formatCurrency(entry.landlord_share) : '-'}</td>
                  </tr>
                );
              })}
              {tPayments.length === 0 && <tr><td colSpan="6" className="px-5 py-8 text-center text-muted-foreground">No payments</td></tr>}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

