export default function TenantInvoices() {
  const { data: rentPayments, isLoading: loadingPayments } = useRentPayments();
  const { data: tenants, isLoading: loadingTenants } = useTenants();
  const { data: properties, isLoading: loadingProperties } = useProperties();
  const { data: landlords, isLoading: loadingLandlords } = useLandlords();
  const { data: carriedBalances = [] } = useTenantCarriedBalances();
  const { data: rentHistoryAll = [] } = useRentHistoryAll();

  const isLoading = loadingPayments || loadingTenants || loadingProperties || loadingLandlords;
  const safePayments = rentPayments ?? [];
  const safeTenants = tenants ?? [];
  const safeProperties = properties ?? [];
  const safeLandlords = landlords ?? [];

  const [tab, setTab] = useState('invoices');
  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterProperty, setFilterProperty] = useState('all');
  const [filterPeriod, setFilterPeriod] = useState('');
  const [selectedInvoice, setSelectedInvoice] = useState(null);
  const [emailInvoice, setEmailInvoice] = useState(null);
  const [page, setPage] = useState(1);
  const PAGE_SIZE = 20;

  const allInvoices = useMemo(() => {
    if (isLoading) return [];
    return buildTenantInvoices({ tenants: safeTenants, properties: safeProperties, landlords: safeLandlords, rentPayments: safePayments, carriedBalances, rentHistoryAll });
  }, [isLoading, safeTenants, safeProperties, safeLandlords, safePayments, carriedBalances, rentHistoryAll]);

  const filtered = useMemo(() => allInvoices
    .filter(inv => {
      if (filterStatus !== 'all' && inv.status !== filterStatus) return false;
      if (filterProperty !== 'all' && inv.property_id !== filterProperty) return false;
      if (filterPeriod && !inv.period_month.includes(filterPeriod)) return false;
      if (search) {
        const q = search.toLowerCase();
        if (!inv.tenant_name.toLowerCase().includes(q) && !inv.invoice_number.toLowerCase().includes(q) && !inv.period_month.includes(q)) return false;
      }
      return true;
    })
    .sort((a, b) => a.period_month.localeCompare(b.period_month) || a.tenant_name.localeCompare(b.tenant_name))
  , [allInvoices, filterStatus, filterProperty, filterPeriod, search]);

  const totalPages = Math.ceil(filtered.length / PAGE_SIZE);
  const paged = filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);

  const totals = {
    paid: filtered.filter(i => i.status === 'Paid').length,
    partial: filtered.filter(i => i.status === 'Partial').length,
    unpaid: filtered.filter(i => i.status === 'Unpaid').length,
    upcoming: filtered.filter(i => i.status === 'Upcoming').length,
  };

  const buildEmailBody = (inv) => `Dear ${inv.tenant_name},

Please find below your rent invoice for ${inv.cycle_label || inv.period_month}.

Property: ${inv.property_address}
Period: ${inv.cycle_label || inv.period_month}
Rent Due: ${formatCurrency(inv.rent_amount)}${inv.arrears > 0 ? '\nArrears: ' + formatCurrency(inv.arrears) : ''}
Total Due: ${formatCurrency(inv.total_due)}
Balance Due: ${formatCurrency(inv.balance_due)}

Please ensure your payment is made on time. If you have already paid, please disregard this message.

If you have any questions, please do not hesitate to contact us.

Kind regards,
ASA Estates Ltd
info@asaestates.com`;

  const exportExcel = () => {
    const rows = filtered.map(inv => ({
      'Invoice #': inv.invoice_number, 'Tenant': inv.tenant_name, 'Property': inv.property_address,
      'Period': inv.period_month, 'Rent Due': inv.rent_amount, 'Paid': inv.total_paid,
      'Balance': inv.balance_due, 'Status': inv.status,
    }));
    const ws = XLSX.utils.json_to_sheet(rows);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Invoices');
    XLSX.writeFile(wb, `Tenant_Invoices_${new Date().toISOString().slice(0,10)}.xlsx`);
  };

  return (
    <div>
      <PageHeader
        title="Tenant Invoices"
        description="Auto-generated from rent payments and tenant records"
        actions={
          <div className="flex gap-2">
            {tab === 'invoices' && <Button variant="outline" onClick={exportExcel}><Download className="w-4 h-4 mr-2" />Export Excel</Button>}
          </div>
        }
      />

      <Tabs value={tab} onValueChange={setTab} className="mb-6">
        <TabsList>
          <TabsTrigger value="invoices"><FileText className="w-4 h-4 mr-2" />Invoices</TabsTrigger>
          <TabsTrigger value="carried"><Wallet className="w-4 h-4 mr-2" />Carried Forward Balances</TabsTrigger>
        </TabsList>
        <TabsContent value="carried" className="mt-6">
          <CarriedBalancesTab tenants={safeTenants} properties={safeProperties} carriedBalances={carriedBalances} />
        </TabsContent>
        <TabsContent value="invoices" className="mt-6">
          {isLoading ? (
            <div className="flex items-center justify-center py-20 text-muted-foreground text-sm">Loading invoices…</div>
          ) : (
            <>
              <div className="grid grid-cols-4 gap-4 mb-6">
                <StatCard label="Paid" value={totals.paid} icon={FileText} color="success" />
                <StatCard label="Partial" value={totals.partial} icon={FileText} color="warning" />
                <StatCard label="Unpaid" value={totals.unpaid} icon={TrendingDown} color="destructive" />
                <StatCard label="Upcoming" value={totals.upcoming} icon={FileText} color="primary" />
              </div>

              {/* Filters */}
              <div className="flex flex-wrap items-center gap-3 mb-5">
                <div className="relative flex-1 min-w-[180px]">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                  <Input className="pl-9 h-9" placeholder="Search tenant, invoice #..." value={search} onChange={e => { setSearch(e.target.value); setPage(1); }} />
                </div>
                <Input type="month" value={filterPeriod} onChange={e => setFilterPeriod(e.target.value)} className="w-36 h-9" />
                <Select value={filterStatus} onValueChange={v => { setFilterStatus(v); setPage(1); }}>
                  <SelectTrigger className="w-36 h-9"><SelectValue placeholder="All Status" /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">All Status</SelectItem>
                    <SelectItem value="Paid">Paid</SelectItem>
                    <SelectItem value="Partial">Partial</SelectItem>
                    <SelectItem value="Unpaid">Unpaid</SelectItem>
                    <SelectItem value="Upcoming">Upcoming</SelectItem>
                  </SelectContent>
                </Select>
                <Select value={filterProperty} onValueChange={v => { setFilterProperty(v); setPage(1); }}>
                  <SelectTrigger className="w-44 h-9"><SelectValue placeholder="All Properties" /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">All Properties</SelectItem>
                    {safeProperties.map(p => <SelectItem key={p.id} value={p.id}>{p.address.split(',')[0]}</SelectItem>)}
                  </SelectContent>
                </Select>
              </div>

              <div className="bg-card rounded-xl border border-border overflow-hidden">
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="bg-muted/50">
                        <th className="text-left px-4 py-3 font-medium text-muted-foreground">Invoice #</th>
                        <th className="text-left px-4 py-3 font-medium text-muted-foreground">Tenant</th>
                        <th className="text-left px-4 py-3 font-medium text-muted-foreground">Property</th>
                        <th className="text-left px-4 py-3 font-medium text-muted-foreground">Period</th>
                        <th className="text-right px-4 py-3 font-medium text-muted-foreground">Rent Due</th>
                        <th className="text-right px-4 py-3 font-medium text-muted-foreground">Paid</th>
                        <th className="text-right px-4 py-3 font-medium text-muted-foreground">Balance</th>
                        <th className="text-left px-4 py-3 font-medium text-muted-foreground">Status</th>
                        <th className="px-4 py-3"></th>
                      </tr>
                    </thead>
                    <tbody>
                      {paged.map(inv => (
                        <tr key={inv.key} className="border-t border-border hover:bg-muted/30 transition-colors">
                          <td className="px-4 py-3 font-mono text-xs text-muted-foreground">{inv.invoice_number}</td>
                          <td className="px-4 py-3 font-medium">{inv.tenant_name}</td>
                          <td className="px-4 py-3 text-muted-foreground text-xs">{inv.property_address?.split(',')[0]}</td>
                          <td className="px-4 py-3 text-xs">{inv.cycle_label || inv.period_month}</td>
                          <td className="px-4 py-3 text-right">{formatCurrency(inv.rent_amount)}</td>
                          <td className="px-4 py-3 text-right text-emerald-600">{inv.total_paid > 0 ? formatCurrency(inv.total_paid) : '-'}</td>
                          <td className="px-4 py-3 text-right font-medium">{inv.balance_due > 0 ? <span className="text-red-600">{formatCurrency(inv.balance_due)}</span> : <span className="text-emerald-600">£0.00</span>}</td>
                          <td className="px-4 py-3"><StatusBadge color={STATUS_COLOR[inv.status]}>{inv.status}</StatusBadge></td>
                          <td className="px-4 py-3">
                            <div className="flex gap-1">
                              <Button variant="ghost" size="sm" onClick={() => setSelectedInvoice(inv)}><Eye className="w-4 h-4" /></Button>
                              <Button variant="ghost" size="sm" onClick={() => downloadTenantInvoicePDF(inv)}><Download className="w-4 h-4" /></Button>
                              <Button variant="ghost" size="sm" disabled={!inv.tenant_email} title={inv.tenant_email ? 'Send email' : 'No email on record'} onClick={() => setEmailInvoice(inv)}><Mail className="w-4 h-4" /></Button>
                            </div>
                          </td>
                        </tr>
                      ))}
                      {filtered.length === 0 && (
                        <tr><td colSpan="9" className="px-4 py-10 text-center text-muted-foreground">No invoices found</td></tr>
                      )}
                    </tbody>
                  </table>
                </div>
              </div>
              <Pagination page={page} totalPages={totalPages} total={filtered.length} pageSize={PAGE_SIZE} onPage={setPage} />
            </>
          )}
        </TabsContent>
      </Tabs>

      <Dialog open={!!selectedInvoice} onOpenChange={v => { if (!v) setSelectedInvoice(null); }}>
        <InvoiceDetailModal invoice={selectedInvoice} onClose={() => setSelectedInvoice(null)} />
      </Dialog>

      {emailInvoice && (
        <EmailComposer
          open={!!emailInvoice}
          onClose={() => setEmailInvoice(null)}
          to={emailInvoice.tenant_email}
          toName={emailInvoice.tenant_name}
          subject={`Rent Invoice – ${emailInvoice.property_address?.split(',')[0]} – ${emailInvoice.cycle_label || emailInvoice.period_month}`}
          body={buildEmailBody(emailInvoice)}
          type="tenant_invoice"
          referenceId={emailInvoice.key}
          attachmentBlobFn={() => getTenantInvoicePDFBlob(emailInvoice)}
          attachmentName={`${emailInvoice.invoice_number}-Invoice.pdf`}
        />
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { base44 } from '@/api/base44Client';
import { useTenants, useProperties, useLandlords, useRentPayments, useRentHistoryAll } from '@/hooks/useAllData';
import { useQueryClient } from '@tanstack/react-query';
import { useRole } from '@/hooks/useRole';
import { logAction } from '@/lib/audit';
import PageHeader from '@/components/ui/PageHeader';
import StatusBadge from '@/components/ui/StatusBadge';
import TenantForm from '@/components/forms/TenantForm';
import { withDerivedStatus } from '@/lib/tenantStatus';
import ConfirmDialog from '@/components/ui/ConfirmDialog';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Plus, Search, Eye, Pencil, Trash2, Upload, TrendingUp } from 'lucide-react';
