export default function Tenants() {
  const { user, isAdmin } = useRole();
  const { data: tenants } = useTenants();
  const { data: properties } = useProperties();
  const { data: landlords } = useLandlords();
  const { data: rentPayments } = useRentPayments();
  const { data: rentHistoryAll = [] } = useRentHistoryAll();
  const queryClient = useQueryClient();
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState(null);
  const [rentIncreaseFor, setRentIncreaseFor] = useState(null);
  const [search, setSearch] = useState('');
  const [confirmDelete, setConfirmDelete] = useState(null);
  const [showImport, setShowImport] = useState(false);
  const [page, setPage] = useState(1);
  const PAGE_SIZE = 20;

  const handleSubmit = async (raw) => {
    const data = withDerivedStatus(raw);
    if (editing) {
      await base44.entities.Tenant.update(editing.id, data);
      await logAction({ user, action: 'update', entityType: 'Tenant', entityId: editing.id, summary: `Updated tenant ${data.name}`, oldValue: editing, newValue: data });
    } else {
      const created = await base44.entities.Tenant.create(data);
      await logAction({ user, action: 'create', entityType: 'Tenant', entityId: created.id, summary: `Created tenant ${data.name}`, newValue: data });
    }
    queryClient.invalidateQueries({ queryKey: ['tenants'] });
    setShowForm(false);
    setEditing(null);
  };

  const handleDelete = async (tenant) => {
    await base44.entities.Tenant.delete(tenant.id);
    await logAction({ user, action: 'delete', entityType: 'Tenant', entityId: tenant.id, summary: `Deleted tenant ${tenant.name}`, oldValue: tenant });
    queryClient.invalidateQueries({ queryKey: ['tenants'] });
    setConfirmDelete(null);
  };

  const filtered = tenants
    .filter(t => t.name?.toLowerCase().includes(search.toLowerCase()))
    .sort((a, b) => (a.lease_start || '').localeCompare(b.lease_start || ''));
  const totalPages = Math.ceil(filtered.length / PAGE_SIZE);
  const paged = filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);

  const getPropertyAddress = (id) => properties.find(p => p.id === id)?.address || 'Unknown';

  const statusColors = { active: 'green', notice: 'yellow', ended: 'gray' };

  return (
    <div>
      <PageHeader
        title="Tenants"
        description={`${tenants.filter(t => t.status === 'active').length} active tenants`}
        actions={
        <div className="flex gap-2">
          <Button variant="outline" onClick={() => setShowImport(true)}>
            <Upload className="w-4 h-4 mr-2" />Bulk Import
          </Button>
          <Button onClick={() => { setEditing(null); setShowForm(true); }}>
            <Plus className="w-4 h-4 mr-2" />Add Tenant
          </Button>
        </div>
      }
      />

      <div className="mb-4 max-w-sm">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input placeholder="Search tenants..." value={search} onChange={e => { setSearch(e.target.value); setPage(1); }} className="pl-9" />
        </div>
      </div>

      <div className="bg-card rounded-xl border border-border overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-muted/50">
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Name</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Property</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Rent</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Arrears</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Status</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Actions</th>
              </tr>
            </thead>
            <tbody>
              {paged.map(t => {
                const tPayments = rentPayments.filter(p => p.tenant_id === t.id);
                const arrears = calculateArrears(t, tPayments, rentHistoryAll.filter(r => r.tenant_id === t.id));
                return (
                  <tr key={t.id} className="border-t border-border hover:bg-muted/30 transition-colors">
                    <td className="px-5 py-3 font-medium">{t.name}</td>
                    <td className="px-5 py-3 text-muted-foreground">{getPropertyAddress(t.property_id)}</td>
                    <td className="px-5 py-3">{formatCurrency(t.monthly_rent)}</td>
                    <td className="px-5 py-3">
                      {arrears > 0 ? (
                        <span className="text-red-600 font-medium">{formatCurrency(arrears)}</span>
                      ) : (
                        <StatusBadge color="green">Clear</StatusBadge>
                      )}
                    </td>
                    <td className="px-5 py-3"><StatusBadge color={statusColors[t.status]}>{t.status}</StatusBadge></td>
                    <td className="px-5 py-3">
                      <div className="flex items-center gap-2">
                        <Link to={`/TenantDetail?id=${t.id}`}><Button variant="ghost" size="sm"><Eye className="w-4 h-4" /></Button></Link>
                        <Button variant="ghost" size="sm" onClick={() => { setEditing(t); setShowForm(true); }}><Pencil className="w-4 h-4" /></Button>
                        <Button variant="ghost" size="sm" title="Rent increase" onClick={() => setRentIncreaseFor(t)}><TrendingUp className="w-4 h-4" /></Button>
                        {isAdmin && <Button variant="ghost" size="sm" className="text-destructive hover:text-destructive" onClick={() => setConfirmDelete(t)}><Trash2 className="w-4 h-4" /></Button>}
                        </div>
                        </td>
                  </tr>
                );
              })}
              {filtered.length === 0 && (
                <tr><td colSpan="6" className="px-5 py-8 text-center text-muted-foreground">No tenants found</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
      <Pagination page={page} totalPages={totalPages} total={filtered.length} pageSize={PAGE_SIZE} onPage={setPage} />

      <Dialog open={showForm} onOpenChange={setShowForm}>
        <DialogContent className="max-w-2xl">
          <DialogHeader><DialogTitle>{editing ? 'Edit Tenant' : 'Add Tenant'}</DialogTitle></DialogHeader>
          <TenantForm tenant={editing} properties={properties} allTenants={tenants} onSubmit={handleSubmit} onCancel={() => setShowForm(false)} />
        </DialogContent>
      </Dialog>

      <ConfirmDialog
        open={!!confirmDelete}
        title="Soft-Delete Tenant"
        description={`Mark "${confirmDelete?.name}" as ended? Their financial history will be preserved.`}
        onConfirm={() => handleDelete(confirmDelete)}
        onCancel={() => setConfirmDelete(null)}
      />

      <RentIncreaseDialog
        tenant={rentIncreaseFor}
        user={user}
        onClose={() => setRentIncreaseFor(null)}
        onSaved={async () => {
          setRentIncreaseFor(null);
          await queryClient.invalidateQueries({ queryKey: ['tenants'] });
          await queryClient.invalidateQueries({ queryKey: ['rent_history_all'] });
          await queryClient.invalidateQueries({ queryKey: ['rent_payments'] });
        }}
      />

      <TenantImportModal
        open={showImport}
        onClose={() => setShowImport(false)}
        onImported={() => queryClient.invalidateQueries({ queryKey: ['tenants'] })}
        properties={properties}
      />
    </div>
  );
}

import React, { useState } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { base44 } from '@/api/base44Client';
