export default function UserManagement() {
  const { isAdmin, isManager } = useRole();
  const queryClient = useQueryClient();
  const [showInvite, setShowInvite] = useState(false);
  const [inviteSuccess, setInviteSuccess] = useState('');

  const { data: users = [] } = useQuery({
    queryKey: ['users'],
    queryFn: () => base44.entities.User.list('-created_date', 200),
  });

  if (isManager === false && isAdmin === false) {
    return <Navigate to="/Dashboard" replace />;
  }

  if (!isAdmin) {
    return (
      <div className="text-center py-20">
        <Shield className="w-12 h-12 mx-auto mb-4 text-muted-foreground opacity-40" />
        <h2 className="text-lg font-semibold text-foreground">Admin Access Required</h2>
        <p className="text-sm text-muted-foreground mt-1">Only admins can manage users.</p>
      </div>
    );
  }

  const handleInvite = async ({ email, role }) => {
    await base44.users.inviteUser(email, role);
    queryClient.invalidateQueries({ queryKey: ['users'] });
    setInviteSuccess(`Invitation sent to ${email}`);
    setShowInvite(false);
    setTimeout(() => setInviteSuccess(''), 4000);
  };

  const handleRoleChange = async (userId, newRole) => {
    await base44.entities.User.update(userId, { role: newRole });
    queryClient.invalidateQueries({ queryKey: ['users'] });
  };

  return (
    <div>
      <PageHeader
        title="User Management"
        description="Manage admin and manager access"
        actions={
          <Button onClick={() => setShowInvite(true)}>
            <Plus className="w-4 h-4 mr-2" />Invite User
          </Button>
        }
      />

      {inviteSuccess && (
        <div className="mb-4 bg-emerald-50 border border-emerald-200 text-emerald-700 px-4 py-3 rounded-lg text-sm">
          {inviteSuccess}
        </div>
      )}

      <div className="bg-card rounded-xl border border-border overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-muted/50">
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Name</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Email</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Role</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Joined</th>
                <th className="text-left px-5 py-3 font-medium text-muted-foreground">Actions</th>
              </tr>
            </thead>
            <tbody>
              {users.map(u => (
                <tr key={u.id} className="border-t border-border hover:bg-muted/30 transition-colors">
                  <td className="px-5 py-3 font-medium flex items-center gap-2">
                    <UserCog className="w-4 h-4 text-muted-foreground" />
                    {u.full_name || '—'}
                  </td>
                  <td className="px-5 py-3 text-muted-foreground">{u.email}</td>
                  <td className="px-5 py-3">
                    <StatusBadge color={u.role === 'admin' ? 'blue' : 'gray'}>
                      {u.role === 'admin' ? 'Admin' : 'Manager'}
                    </StatusBadge>
                  </td>
                  <td className="px-5 py-3 text-muted-foreground">
                    {u.created_date ? format(new Date(u.created_date), 'dd MMM yyyy') : '—'}
                  </td>
                  <td className="px-5 py-3">
                    <Select value={u.role || 'user'} onValueChange={v => handleRoleChange(u.id, v)}>
                      <SelectTrigger className="h-7 text-xs w-32">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="user">Manager</SelectItem>
                        <SelectItem value="admin">Admin</SelectItem>
                      </SelectContent>
                    </Select>
                  </td>
                </tr>
              ))}
              {users.length === 0 && (
                <tr><td colSpan="5" className="px-5 py-8 text-center text-muted-foreground">No users found</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      <Dialog open={showInvite} onOpenChange={setShowInvite}>
        <DialogContent className="max-w-sm">
          <DialogHeader><DialogTitle>Invite User</DialogTitle></DialogHeader>
          <InviteForm onSubmit={handleInvite} onCancel={() => setShowInvite(false)} />
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React, { useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import { useProperties, useTenants, useLandlords } from '@/hooks/useAllData';
import { analyseVacancies } from '@/lib/vacancies';
import PageHeader from '@/components/ui/PageHeader';
import StatCard from '@/components/ui/StatCard';
import StatusBadge from '@/components/ui/StatusBadge';
import { Input } from '@/components/ui/input';
import { DoorOpen, CalendarClock, Search, Home, Phone, ArrowRight } from 'lucide-react';
import { format, parseISO } from 'date-fns';

const fmtDate = (s) => { try { return format(parseISO(s), 'd MMM yyyy'); } catch { return s || '—'; } };

export default function Vacancies() {
  const { data: properties = [] } = useProperties();
  const { data: tenants = [] } = useTenants();
  const { data: landlords = [] } = useLandlords();
  const [search, setSearch] = useState('');
  const [horizon, setHorizon] = useState(30);

  const { vacantNow, becomingEmpty } = useMemo(
    () => analyseVacancies(properties, tenants, { days: horizon }),
    [properties, tenants, horizon]
  );

  const landlordName = (id) => landlords.find(l => l.id === id)?.name || '—';
  const q = search.trim().toLowerCase();
  const match = (p) => !q || (p.address || '').toLowerCase().includes(q) || landlordName(p.landlord_id).toLowerCase().includes(q);

  const vNow = vacantNow.filter(v => match(v.property));
  const vSoon = becomingEmpty.filter(v => match(v.property));

  return (
    <div>
      <PageHeader
        title="Vacancies"
        description="Empty properties and tenancies ending soon — so you can re-let in good time"
      />

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-6">
        <StatCard label="Empty now" value={vacantNow.length} icon={DoorOpen} color={vacantNow.length > 0 ? 'warning' : 'success'} />
        <StatCard label={`Becoming empty (${horizon}d)`} value={becomingEmpty.length} icon={CalendarClock} color={becomingEmpty.length > 0 ? 'destructive' : 'success'} />
        <StatCard label="Occupied" value={properties.length - vacantNow.length} icon={Home} color="success" />
      </div>

      <div className="flex flex-wrap items-center gap-2 mb-5">
        <div className="flex items-center gap-2 bg-card border border-border rounded-lg px-3 py-2 flex-1 min-w-[220px]">
          <Search className="w-4 h-4 text-muted-foreground" />
          <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search address or landlord…" className="flex-1 bg-transparent outline-none text-sm" />
        </div>
        <div className="flex items-center gap-1">
          <span className="text-xs text-muted-foreground mr-1">Ending within:</span>
          {[30, 60, 90].map(d => (
            <button key={d} onClick={() => setHorizon(d)}
              className={`px-2.5 py-1 rounded-lg text-xs font-semibold ${horizon === d ? 'bg-primary text-white' : 'bg-muted text-muted-foreground hover:text-foreground'}`}>{d}d</button>
          ))}
        </div>
      </div>

      {/* Becoming empty */}
      <div className="mb-8">
        <h2 className="text-sm font-semibold mb-3 flex items-center gap-2"><CalendarClock className="w-4 h-4 text-red-500" />Becoming empty (next {horizon} days)</h2>
        <div className="bg-card rounded-xl border border-border overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm min-w-[720px]">
              <thead>
                <tr className="bg-muted/50 text-xs text-muted-foreground text-left">
                  <th className="px-4 py-3 font-medium">Property</th>
                  <th className="px-4 py-3 font-medium">Landlord</th>
                  <th className="px-4 py-3 font-medium">Current tenant</th>
                  <th className="px-4 py-3 font-medium">Contact</th>
                  <th className="px-4 py-3 font-medium">Ends</th>
                  <th className="px-4 py-3 font-medium">Days left</th>
                  <th className="px-4 py-3 font-medium text-right"></th>
                </tr>
              </thead>
              <tbody>
                {vSoon.map(v => (
                  <tr key={v.property.id} className="border-t border-border hover:bg-muted/30">
                    <td className="px-4 py-3 font-medium">{v.property.address}</td>
                    <td className="px-4 py-3 text-xs text-muted-foreground">{landlordName(v.property.landlord_id)}</td>
                    <td className="px-4 py-3 text-xs">{v.tenant.name}</td>
                    <td className="px-4 py-3 text-xs">{v.tenant.phone ? <a href={`tel:${v.tenant.phone}`} className="text-primary hover:underline inline-flex items-center gap-1"><Phone className="w-3 h-3" />{v.tenant.phone}</a> : '—'}</td>
                    <td className="px-4 py-3 text-xs">{fmtDate(v.endDate)}</td>
                    <td className="px-4 py-3"><StatusBadge color={v.daysLeft <= 14 ? 'red' : 'yellow'}>{v.daysLeft} day{v.daysLeft === 1 ? '' : 's'}</StatusBadge></td>
                    <td className="px-4 py-3 text-right"><Link to={`/PropertyDetail?id=${v.property.id}`} className="text-primary text-xs hover:underline inline-flex items-center gap-1">Open <ArrowRight className="w-3 h-3" /></Link></td>
                  </tr>
                ))}
                {vSoon.length === 0 && <tr><td colSpan="7" className="px-4 py-10 text-center text-muted-foreground text-sm">No tenancies ending in the next {horizon} days.</td></tr>}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* Empty now */}
      <div>
        <h2 className="text-sm font-semibold mb-3 flex items-center gap-2"><DoorOpen className="w-4 h-4 text-amber-500" />Empty now</h2>
        <div className="bg-card rounded-xl border border-border overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm min-w-[720px]">
              <thead>
                <tr className="bg-muted/50 text-xs text-muted-foreground text-left">
                  <th className="px-4 py-3 font-medium">Property</th>
                  <th className="px-4 py-3 font-medium">Type</th>
                  <th className="px-4 py-3 font-medium">Landlord</th>
                  <th className="px-4 py-3 font-medium">Rent</th>
                  <th className="px-4 py-3 font-medium">Empty since</th>
                  <th className="px-4 py-3 font-medium">Last tenant</th>
                  <th className="px-4 py-3 font-medium text-right"></th>
                </tr>
              </thead>
              <tbody>
                {vNow.map(v => (
                  <tr key={v.property.id} className="border-t border-border hover:bg-muted/30">
                    <td className="px-4 py-3 font-medium">{v.property.address}</td>
                    <td className="px-4 py-3 text-xs text-muted-foreground capitalize">{[v.property.property_type, v.property.bedrooms ? `${v.property.bedrooms} bed` : ''].filter(Boolean).join(' · ') || '—'}</td>
                    <td className="px-4 py-3 text-xs text-muted-foreground">{landlordName(v.property.landlord_id)}</td>
                    <td className="px-4 py-3 text-xs">{v.property.monthly_rent ? `£${Number(v.property.monthly_rent).toLocaleString()}/mo` : '—'}</td>
                    <td className="px-4 py-3 text-xs">{v.since ? fmtDate(v.since) : (v.everLet ? '—' : 'Never let')}</td>
                    <td className="px-4 py-3 text-xs text-muted-foreground">{v.lastTenant || '—'}</td>
                    <td className="px-4 py-3 text-right"><Link to={`/PropertyDetail?id=${v.property.id}`} className="text-primary text-xs hover:underline inline-flex items-center gap-1">Open <ArrowRight className="w-3 h-3" /></Link></td>
                  </tr>
                ))}
                {vNow.length === 0 && <tr><td colSpan="7" className="px-4 py-10 text-center text-muted-foreground text-sm">No empty properties. 🎉</td></tr>}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}

