/* ---------- Animated count-up for the figures ---------- */
function Figure({ end, label, suffix = '' }) {
  const [val, setVal] = useState(0);
  const ref = useRef(null);
  const reduce = useReducedMotion();
  useEffect(() => {
    if (reduce) { setVal(end); return; }
    const ob = new IntersectionObserver(([e]) => {
      if (!e.isIntersecting) return; ob.disconnect();
      const dur = 1400, t0 = Date.now();
      const tick = () => {
        const p = Math.min((Date.now() - t0) / dur, 1);
        setVal(Math.round((1 - Math.pow(1 - p, 3)) * end));
        if (p < 1) requestAnimationFrame(tick);
      };
      requestAnimationFrame(tick);
    }, { threshold: 0.4 });
    if (ref.current) ob.observe(ref.current);
    return () => ob.disconnect();
  }, [end, reduce]);
  return (
    <div ref={ref} className="text-center sm:text-left">
      <div style={{ ...display, color: INK }} className="text-5xl sm:text-6xl leading-none">
        {val}<span style={{ color: RED }}>{suffix}</span>
      </div>
      <div style={body} className="mt-2 text-[11px] uppercase tracking-[0.18em]" >{label}</div>
    </div>
  );
}

