import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { usePublicProperties } from '@/hooks/useAllData';
import PropertyCard from '@/components/public/PropertyCard.jsx';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Search, Filter, MapPin } from 'lucide-react';

export default function PublicListings() {
  const { data: properties = [] } = usePublicProperties();
  const [filterType, setFilterType] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState('newest');

  const filtered = properties.filter(p => {
    const matchType =
      filterType === 'all' ||
      (filterType === 'let' && p.listing_type !== 'sale') ||
      (filterType === 'sale' && p.listing_type === 'sale');
    const q = searchQuery.toLowerCase();
    const matchSearch = !q ||
      p.address?.toLowerCase().includes(q) ||
      p.public_title?.toLowerCase().includes(q);
    return matchType && matchSearch;
  });

  const priceOf = (p) => p.listing_type === 'sale' ? (p.sale_price || 0) : (p.monthly_rent || 0);
  const sorted = [...filtered].sort((a, b) => {
    // Rent always comes before sale
    const aIsRent = a.listing_type !== 'sale' ? 0 : 1;
    const bIsRent = b.listing_type !== 'sale' ? 0 : 1;
    if (aIsRent !== bIsRent) return aIsRent - bIsRent;
    // Available (not let agreed) before let agreed
    const aLetAgreed = a.let_agreed ? 1 : 0;
    const bLetAgreed = b.let_agreed ? 1 : 0;
    if (aLetAgreed !== bLetAgreed) return aLetAgreed - bLetAgreed;
    if (sortBy === 'price-high') return priceOf(b) - priceOf(a);
    if (sortBy === 'price-low') return priceOf(a) - priceOf(b);
    return new Date(b.created_date || 0) - new Date(a.created_date || 0); // newest
  });

  return (
    <div>
      <section className="bg-gradient-to-br from-[#1f2c80] to-[#0f1723] text-white py-16 sm:py-24">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="max-w-3xl">
            <h1 className="text-5xl sm:text-6xl lg:text-7xl font-black leading-[0.95] tracking-tight mb-4">Find your perfect property</h1>
            <p className="text-xl text-white/80">Browse our hand-picked selection of properties across Greater London</p>
          </motion.div>
        </div>
      </section>

      <section className="bg-white border-b border-border sticky top-16 z-40">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
              <Input
                placeholder="Search location or title..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-10"
              />
            </div>
            <Select value={filterType} onValueChange={setFilterType}>
              <SelectTrigger>
                <SelectValue placeholder="Type" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Properties</SelectItem>
                <SelectItem value="let">To Let</SelectItem>
                <SelectItem value="sale">For Sale</SelectItem>
              </SelectContent>
            </Select>
            <Select value={sortBy} onValueChange={setSortBy}>
              <SelectTrigger>
                <SelectValue placeholder="Sort by" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="newest">Newest</SelectItem>
                <SelectItem value="price-low">Price: Low to High</SelectItem>
                <SelectItem value="price-high">Price: High to Low</SelectItem>
              </SelectContent>
            </Select>
            <div className="text-sm text-muted-foreground flex items-center">
              <Filter className="w-4 h-4 mr-2" />
              {sorted.length} properties found
            </div>
          </div>
        </div>
      </section>

      <section className="py-12 lg:py-20 bg-background">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          {sorted.length > 0 ? (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
              {sorted.map((property, index) => (
                <PropertyCard key={property.id} property={property} index={index} />
              ))}
            </div>
          ) : (
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="text-center py-20">
              <MapPin className="w-16 h-16 mx-auto text-muted-foreground/50 mb-4" />
              <h3 className="text-2xl font-bold text-foreground mb-2">No properties found</h3>
              <p className="text-muted-foreground">Try adjusting your search filters</p>
            </motion.div>
          )}
        </div>
      </section>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { useQuery } from '@tanstack/react-query';
import { base44 } from '@/api/base44Client';
import { formatCurrency } from '@/lib/computations';
import InquiryForm from '@/components/public/InquiryForm.jsx';
import { Bed, Bath, Maximize, MapPin, ArrowLeft, Home, TrainFront, GraduationCap } from 'lucide-react';

const placeholder = 'https://images.unsplash.com/photo-1568605114967-8130f3a36994?w=1200&q=80';

function haversineMiles(aLat, aLng, bLat, bLng) {
  const R = 3958.8;
  const dLat = (bLat - aLat) * Math.PI / 180;
  const dLng = (bLng - aLng) * Math.PI / 180;
  const s = Math.sin(dLat / 2) ** 2 + Math.cos(aLat * Math.PI / 180) * Math.cos(bLat * Math.PI / 180) * Math.sin(dLng / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(s), Math.sqrt(1 - s));
}
function stationType(t = {}) {
  if (t.station === 'subway') return 'Underground';
  if (t.station === 'light_rail' || t.light_rail === 'yes') return 'Light rail / DLR';
  if (t.railway === 'tram_stop' || t.tram === 'yes') return 'Tram';
  if (t.railway === 'station' || t.railway === 'halt') return 'Rail';
  return 'Station';
}
function schoolAges(t = {}) {
  const min = t.min_age || t['school:age:min'];
  const max = t.max_age || t['school:age:max'];
  return min && max ? `Age ${min} - ${max}` : '';
}

function NearbyPlaces({ address }) {
  const [state, setState] = useState({ loading: true, error: null, stations: [], schools: [] });

  useEffect(() => {
    let active = true;
    if (!address) { setState({ loading: false, error: 'noaddr', stations: [], schools: [] }); return; }
    setState({ loading: true, error: null, stations: [], schools: [] });

    (async () => {
      try {
        // 1) Geocode the address (OpenStreetMap Nominatim)
        const geoRes = await fetch(
          `https://nominatim.openstreetmap.org/search?format=json&limit=1&countrycodes=gb&q=${encodeURIComponent(address)}`,
          { headers: { 'Accept-Language': 'en-GB' } }
        );
        const geo = await geoRes.json();
        if (!geo || !geo.length) throw new Error('geocode');
        const lat = parseFloat(geo[0].lat), lng = parseFloat(geo[0].lon);

        // 2) Nearby stations + schools (Overpass)
        const q = `[out:json][timeout:25];(node(around:2500,${lat},${lng})[railway=station];node(around:2500,${lat},${lng})[railway=halt];node(around:2500,${lat},${lng})[station=subway];node(around:2500,${lat},${lng})[railway=tram_stop];node(around:1800,${lat},${lng})[amenity=school];way(around:1800,${lat},${lng})[amenity=school];);out center tags;`;
        const opRes = await fetch('https://overpass-api.de/api/interpreter', {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: 'data=' + encodeURIComponent(q),
        });
        const op = await opRes.json();

        const stations = [], schools = [], seenS = new Set(), seenSch = new Set();
        for (const el of (op.elements || [])) {
          const t = el.tags || {}; const name = t.name; if (!name) continue;
          const elat = el.lat ?? el.center?.lat, elng = el.lon ?? el.center?.lon;
          if (typeof elat !== 'number' || typeof elng !== 'number') continue;
          const miles = Math.round(haversineMiles(lat, lng, elat, elng) * 10) / 10;
          if (t.amenity === 'school') { if (seenSch.has(name)) continue; seenSch.add(name); schools.push({ name, ages: schoolAges(t), miles }); }
          else { if (seenS.has(name)) continue; seenS.add(name); stations.push({ name, type: stationType(t), miles }); }
        }
        stations.sort((a, b) => a.miles - b.miles);
        schools.sort((a, b) => a.miles - b.miles);
        if (active) setState({ loading: false, error: null, stations: stations.slice(0, 6), schools: schools.slice(0, 6) });
      } catch (e) {
        if (active) setState({ loading: false, error: e.message || 'error', stations: [], schools: [] });
      }
    })();

    return () => { active = false; };
  }, [address]);

  const { loading, error, stations, schools } = state;
  if (loading) return <div className="text-sm text-muted-foreground">Finding nearby stations and schools…</div>;
  if (error || (stations.length === 0 && schools.length === 0))
    return <div className="text-sm text-muted-foreground">Nearby station and school information isn’t available for this address right now.</div>;

  const Row = ({ icon: Icon, name, meta, miles }) => (
    <div className="flex items-start gap-3 py-2">
      <Icon className="w-4 h-4 mt-0.5 shrink-0 text-primary" />
      <div className="flex-1 min-w-0">
        <div className="text-sm font-medium leading-snug">{name}</div>
        {meta && <div className="text-xs text-muted-foreground">{meta}</div>}
      </div>
      <div className="text-sm text-muted-foreground whitespace-nowrap">{miles} {miles === 1 ? 'mile' : 'miles'}</div>
    </div>
  );

  return (
    <div className="space-y-6">
      {stations.length > 0 && (
        <div>
          <h3 className="text-lg font-bold mb-1">Stations</h3>
          <div className="grid sm:grid-cols-2 gap-x-8">
            {stations.map((s, i) => <Row key={i} icon={TrainFront} name={s.name} meta={s.type} miles={s.miles} />)}
          </div>
        </div>
      )}
      {schools.length > 0 && (
        <div>
          <h3 className="text-lg font-bold mb-1">Schools</h3>
          <div className="grid sm:grid-cols-2 gap-x-8">
            {schools.map((s, i) => <Row key={i} icon={GraduationCap} name={s.name} meta={s.ages} miles={s.miles} />)}
          </div>
        </div>
      )}
      <p className="text-xs text-muted-foreground">These distances are calculated in a straight line. The actual route and distance may vary.</p>
    </div>
  );
}

