                </div>
              )}
              {property.bills_included && property.bills_included.length > 0 && (
                <div>
                  <div className="text-xs text-muted-foreground mb-1.5">Bills Included in Rent</div>
                  <div className="flex flex-wrap gap-2">
                    {property.bills_included.map(bill => (
                      <span key={bill} className="bg-white border border-blue-200 px-2 py-1 rounded text-xs capitalize">{bill.replace(/_/g, ' ')}</span>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Legal & Safety Compliance */}
          {(property.epc_rating || property.gas_safety_cert || property.eicr_status) && (
            <div className="bg-green-50 border-l-4 border-green-400 p-4 rounded">
              <h3 className="text-sm font-semibold text-green-900 mb-3">Legal & Safety Compliance</h3>
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 text-sm">
                {property.epc_rating && (
                  <div>
                    <div className="text-xs text-muted-foreground">EPC Rating</div>
                    <div className="font-semibold text-lg">{property.epc_rating}</div>
                  </div>
                )}
                {property.gas_safety_cert && (
                  <div>
                    <div className="text-xs text-muted-foreground">Gas Safety Certificate</div>
                    <span className={`inline-block px-2 py-1 rounded text-xs font-semibold ${
                      property.gas_safety_cert === 'compliant' ? 'bg-green-100 text-green-700' :
                      property.gas_safety_cert === 'pending' ? 'bg-yellow-100 text-yellow-700' :
                      'bg-red-100 text-red-700'
                    }`}>
                      {property.gas_safety_cert.charAt(0).toUpperCase() + property.gas_safety_cert.slice(1)}
                    </span>
                  </div>
                )}
                {property.eicr_status && (
                  <div>
                    <div className="text-xs text-muted-foreground">Electrical Safety (EICR)</div>
                    <span className={`inline-block px-2 py-1 rounded text-xs font-semibold ${
                      property.eicr_status === 'compliant' ? 'bg-green-100 text-green-700' :
                      property.eicr_status === 'pending' ? 'bg-yellow-100 text-yellow-700' :
                      'bg-red-100 text-red-700'
                    }`}>
                      {property.eicr_status.charAt(0).toUpperCase() + property.eicr_status.slice(1)}
                    </span>
                  </div>
                )}
              </div>
            </div>
          )}

          {/* Nearby stations & schools */}
          <div className="pt-2 border-t border-border">
            <h2 className="text-lg font-semibold mb-3 mt-4">Local area</h2>
            <NearbyPlaces address={property.address} />
          </div>

          {/* Description */}
          {property.public_description && (
            <div>
              <h2 className="text-lg font-semibold mb-2">About this property</h2>
              <p className="text-sm text-foreground/80 leading-relaxed whitespace-pre-line">
                {property.public_description}
              </p>
            </div>
          )}
        </div>

        {/* Right: inquiry */}
        <aside className="lg:col-span-1">
          <div className="lg:sticky lg:top-24 bg-card rounded-2xl border border-border p-5 sm:p-6 elev-1">
            <h2 className="text-lg font-semibold mb-1">Interested in this property?</h2>
            <p className="text-sm text-muted-foreground mb-5">
              Send us a message and we'll get back to you shortly.
            </p>
            <InquiryForm propertyId={property.id} propertyTitle={property.public_title || property.address} />
          </div>
        </aside>
      </div>
    </div>
  );
}

export function createPageUrl(pageName: string) {
    return '/' + pageName.replace(/ /g, '-');
}

